local P = LoreForeverPacks.Begin("LoreForever_Lang_svSE")
P.entries["quest:886"] = {n="The Barrens Oases",s="Högt uppe på Elder Rise i Thunder Bluff känner Arch Druid Hamuul Runetotem en oroande kraftvåg strömma in i The Barrens torra jord. För att ta reda på sanningen skickar han lovande resenärer österut, förbi Mulgore, för att möta sin frände Tonga Runetotem vid The Crossroads. Uppdraget inleder en undersökning av de onaturliga vatten som springer fram över de solstekta slätterna.",h="Högt uppe på Elder Rise i Thunder Bluff känner Arch Druid Hamuul Runetotem en oroande kraftvåg strömma in i...",kw={"bloodhoof village","cenarion circle","the crossroads","elder rise","hamuul runetotem","mulgore","oaser","the barrens","thunder bluff","tonga runetotem"},ang={["class:Druid"]="Som de första eleverna som utbildats under Hamuul Runetotem får unga druider i uppdrag av sin Arch Druid att lyssna till jordens viskningar och läka såren i naturens sköra balans.",["faction:Horde"]="The Crossroads är den livsviktiga pulsådern som förbinder Hordens västra besittningar med kusten, så varje magisk störning i närheten är en fråga av stor strategisk och andlig betydelse.",["race:Tauren"]="För tauren som för första gången färdas bortom Mulgore heliga ängar är uppgiften en övergångsrit till det större ansvaret att skydda Kalimdors balans."},sec={{t="En störning i torkan",b="Medan Mulgore slätter frodas under Earth Mothers vakande blick har de vidsträckta savannerna i The Barrens österut varit karga, svedda och torra i generationer. Nyligen har tauren-druider som mediterar högst upp på Elder Rise i Thunder Bluff upptäckt märkliga energiströmmar som vaknar djupt under de uttorkade slätterna. Liv rör på sig där det inte borde, och Cenarion Circle fruktar att kraften bakom denna våg kan dölja en fara för landet och dess varelser."},{t="Österut bortom Mulgore",b="För att undersöka dessa märkliga händelser skickade Arch Druid Hamuul Runetotem ut Tonga Runetotem i fält. Eftersom den vidsträckta vildmarken rymmer faror som är alltför stora för en ensam utredare ber Hamuul resenärer som lämnar Mulgore att skynda efter Tonga. Följ vägen österut förbi Bloodhoof Village och genom bergspassen, så kommer du rakt till The Crossroads, The Barrens dammiga och livliga hjärta i Horde-territorium, där Tonga väntar på svar."}},faq={{q="Varför oroar sig Hamuul Runetotem för The Barrens?",a="Hamuul och druiderna i Thunder Bluff har känt en onaturlig kraftvåg läcka in i The Barrens jord. Att livet plötsligt tar fart i ett så torrt och ogästvänligt klimat tyder på att märkliga krafter verkar under ytan.",al={"varför oaser i the barrens","hamuuls oro","varför skicka till the crossroads"}},{q="Var hittar jag Tonga Runetotem?",a="Tonga Runetotem är stationerad vid The Crossroads i centrala The Barrens. Följ huvudvägen österut från Mulgore, ta dig in i The Barrens och följ stigen norrut vid vägskälet tills du når bosättningen.",al={"tonga runetotems plats","var är tonga","tonga the crossroads"}},{q="Är det här uppdraget bara tillgängligt för tauren?",a="Arch Druid Hamuul Runetotem erbjuder främst det här uppdraget till resenärer som kommer från Mulgore. Äventyrare av alla Horde-folk kan dock möta Tonga direkt vid The Crossroads och hjälpa till att undersöka oaserna.",al={"kan icke-tauren få oasuppdraget i the barrens","vem ger uppdraget the barrens oaser"}},{q="Vad väntar vid vägens slut från Bloodhoof Village?",a="Om du lämnar Bloodhoof Village österut kommer du genom bergspasset mellan Mulgore och The Barrens. När du kommit förbi bergen tar du norrut vid vägskälet, så kommer du tryggt genom den ogästvänliga vildmarken till The Crossroads.",al={"vägen till the crossroads","vägen från mulgore till the barrens"}},{q="Vilka är de märkliga krafter som Hamuul känner av?",a="Druiderna känner av magiska strömmar som skapar grönskande oaser med källvatten i ett ökenlandskap som är känt för sin bittra torka. Tonga Runetotem skickades dit för att ta reda på om denna tillväxt är en välsignelse eller en farlig förvridning.",al={"vilka krafter finns i the barrens","oaserna mysterium","onaturlig energi i the barrens"}},{q="Varför anses The Barrens vara så farligt för unga äventyrare?",a="The Barrens är en vidsträckt gränsmark full av rovdjur, där raptorer, slättlöpare och fientliga kentaurstammar stryker omkring. Hamuul varnar resenärer för att hålla sig strikt till de patrullerade handelsvägarna, så att de inte övermannas av den hårda vildmarken.",al={"faror i the barrens","varför hålla sig till vägen"}}},fx={caac276a={q="Varför skickar Arch Druid Hamuul Runetotem dig i stället för att ge sig av själv?",a="Som ärkedruid och andlig ledare för taurendruiderna i Thunder Bluff måste Hamuul Runetotem stanna på platån för att vägleda sina bröder och ge råd åt högklanledaren. Han har redan skickat ut Tonga Runetotem för att undersöka oroligheterna, men Tonga kan inte lösa gåtan ensam. Hamuul förlitar sig på dugliga, lovande hjältar som du för att vara Tongas händer och ögon ute i den vida världen.",al={"varför skicka mig","varför ger han sig inte av själv","varför behöver hamuul mig"}}},fp="17,231,28.323.0,19.357.0,52.189.0,33.151.0,39.164.0,58.151.0,42.183.0,66.185.0"}
P.entries["quest:8866"] = {n="Bronzebeard the Elder",s="Bronzebeard the Elder är ett möte under Lunar Festival med Elder Bronzebeard i dvärgstaden Ironforge, byggd inne i ett berg. Genom att hedra honom under denna förfädershögtid får resenärer visdom och en uppskattningstoken. Det speglar den djupa vördnad som folket i Khaz Modan känner för sina förfäder och sitt långlivade arv.",h="Bronzebeard the Elder är ett möte under Lunar Festival med Elder Bronzebeard i dvärgstaden Ironforge, byggd...",kw={"förfäder","bronzebeard","coin of ancestry","äldste","ironforge","lunar festival"},ang={["faction:Alliance"]="Den äldste bor i stillhet i Ironforges huvudstad och välkomnar Alliance-medlemmar som vill fira forntida traditioner under berget.",["faction:Horde"]="Att nå Elder Bronzebeard innebär en farlig intrång i Ironforges befästa kärna. Du behöver smyga eller visa mod för att hälsa på honom.",["race:Dwarf"]="För dvärgar är en hyllning till Elder Bronzebeard en direkt förbindelse med de ädla förfäder som byggde deras bergsrike av sten och järn."},sec={{t="Hyllning till bergsklanen",b="Under Lunar Festival visar sig andar och vördnadsvärda äldste runt om i Azeroth för att dela sin visdom med resenärer som hedrar det förflutna. I Ironforge står Elder Bronzebeard som en sinnebild för Bronzebeard-klanens okuvliga motståndskraft. När äventyrare kommer för att visa sin vördnad uttrycker han stilla tillfredsställelse över att folket i detta land fortfarande erkänner och hedrar de forntida rasernas släktlinjer."},{t="Tecken på vördnad för förfäderna",b="Mötet kräver ingen stor prövning eller farlig expedition. Resenärer behöver bara stanna till, uppmärksamma den äldstes närvaro och hälsa på honom. I gengäld framför Elder Bronzebeard sina lyckönskningar och ger dem ett Coin of Ancestry. Dessa heliga högtidstoken påminner påtagligt om den levande förbindelsen mellan nutidens hjältar och generationerna som formade Khaz Modan av sten och eld."}},faq={{q="Vem är Elder Bronzebeard?",a="Elder Bronzebeard är en dvärg från förfädernas tid som hedras under Lunar Festival. Han finns i Ironforges underjordiska fäste, där han tar emot besökare och firar deras arv.",al={"elder bronzebeard","vem är den äldste","äldste i ironforge"}},{q="Vad innebär det att hedra Elder Bronzebeard?",a="Att hälsa på honom är ett sätt att vörda förfäderna under Lunar Festival. Han berömmer resenärer för att de minns de tidiga raserna i Azeroths rötter och forntida uppoffringar.",al={"varför hedra bronzebeard","bronzebeards uppgift"}},{q="Var i Ironforge finns Elder Bronzebeard?",a="Han står i Ironforge, dit du kan ta dig när du utforskar bergsstaden för att söka upp högtidens äldste och visa din vördnad.",al={"elder bronzebeards plats","var finns bronzebeard the elder","äldstens plats i ironforge"}},{q="Kan Horde-spelare tala med Elder Bronzebeard?",a="Elder Bronzebeard uppmärksammar alla som är villiga att hälsa på honom, men Horde-äventyrare måste våga sig ner i Ironforges befästa djup och undvika dvärgarnas vakter för att nå fram.",al={"kan horde göra uppdraget","horde elder bronzebeard"}},{q="Vilken belöning ger den äldste?",a="Han ger sin välsignelse från förfäderna tillsammans med ett högtidsmynt, som ett tecken på välvilja och ett bevis på att man hedrat forntida generationer.",al={"elder bronzebeards belöning","vilket tecken ger han"}},{q="Innebär det här uppdraget någon strid?",a="Du behöver inte strida för att tala med honom. Det räcker att närma sig den vördnadsvärde äldsten respektfullt, även om fientligt territorium kan innebära fara på vägen.",al={"måste jag slåss","strid med bronzebeard the elder"}}},fp="21,213,27.329.0,26.292.0,25.166.0,45.170.0,46.133.0,47.154.0,34.136.0,35.109.0"}
P.entries["quest:887"] = {n="Southsea Freebooters",s="Längs Merchant Coast söder om Ratchet anfaller Southsea Freebooters goblinernas handelsfartyg. Gazlowe anlitar äventyrare för att anfalla deras läger och hejda räderna.",h="Längs Merchant Coast söder om Ratchet anfaller Southsea Freebooters goblinernas handelsfartyg.",kw={"the barrens","banditer","kanonbesättningar","freebooters","gazlowe","grezzlik","pirater","ratchet","southsea","steamwheedle"},ang={["class:Rogue"]="Som skurk hittar du möjligheter att göra fickstölder i Southsea Freebooters läger, om du kan smita förbi vaksamma vakter och tungt kustartilleri.",["faction:Horde"]="Som medlem av Horden förlitar du dig på Ratchet som en viktig försörjningsled i Kalimdor. Fria sjöleder skyddar förnödenheter på väg inåt landet genom The Barrens."},sec={{t="En nagel i Gazlowes öga",b="Ratchets handel lider av pirater vid Merchant Coast. Hamnen ligger i centrala Kalimdor, där handelsfartyg färdas mellan Kalimdor och de östra kontinenterna. Söder om staden håller Southsea Freebooters till i ett befäst strandläger. Därifrån anfaller de goblinernas lastfartyg när de anländer och avgår, vilket minskar vinsterna och stör de lokala sjölederna."},{t="Försummelse från Undermine",b="Gazlowe skyller på piraterna och Steamwheedle Cartels marinledare. Handelsfurstarna har lagt enorma summor på försvarsflottor, men viceamiral Grezzlik har inte lyckats patrullera vattnen effektivt. Frustrerad över Undermines långsamma agerande anlitar Gazlowe oberoende legosoldater för att decimera piratbanditerna och kanonjärerna."}},faq={{q="Vilka är Southsea Freebooters?",a="Southsea Freebooters är pirater som härjar i de södra haven och Great Sea. I The Barrens håller de ett beväpnat strandläger söder om Ratchet och plundrar handelsfartyg på handelsvaror avsedda för Kalimdor.",al={"southsea-pirater","vilka är southsea freebooters","freebooters-bakgrund"}},{q="Varför bryr sig Gazlowe så mycket om dessa pirater?",a="Gazlowe övervakar Ratchets hamn för Steamwheedle Cartel. Varje handelsfartyg som Freebooters bordar eller plundrar minskar kartellens intäkter och skadar Ratchets rykte som en trygg handelshamn.",al={"varför vill gazlowe döda piraterna","gazlowes motiv","ratchets piratproblem"}},{q="Var ligger piratlägret?",a="Southsea-lägret ligger längs Merchant Coast, en bit ner längs kusten söder om Ratchet. Befästa tält, uppdragna jollar och artilleripositioner bemannade av Southsea Cannoneers kännetecknar lägret.",al={"var finns southsea-banditerna","kanonbesättningarnas plats","var ligger piratlägret"}},{q="Vem är viceamiral Grezzlik?",a="Viceamiral Grezzlik övervakar Steamwheedle Cartels handelsflottor och skyddar dess sjöleder. Gazlowe anser att han är ineffektiv, med tanke på piraterna som öppet härjar utanför The Barrens kust.",al={"vem är grezzlik","viceamiral grezzliks bakgrund","steamwheedle-amiral"}},{q="Vad händer efter att lägret rensats?",a="Att slå ut lägrets försvarare löser bara en del av problemet. När banditerna och kanonjärerna har drivits bort börjar Gazlowe spåra upp den värdefulla lasten de kapade, vilket leder till undersökningar av hans försvunna leveranser.",al={"what comes next","fortsättning på southsea freebooters","försvunnen leverans"}},{q="Är Southsea Freebooters knutna till Alliansen eller Horden?",a="Nej. Southsea Freebooters verkar utanför båda fraktionerna och ger sig på såväl Alliansens fartyg som Hordens förnödenhetsfartyg och neutrala gobliners fraktfartyg.",al={"är freebooters horden","är piraterna alliansen","southsea-fraktion"}}},fx={["56366fb6"]={q="Varför anlitar Gazlowe en äventyrare i stället för att använda sina egna styrkor?",a="Ratchet är en livlig neutral hamn, men stadens försvarsstyrkor är hårt ansträngda när de håller ordning på rivaliserande resenärer från Alliansen och Horden. Steamwheedle Cartels handelsflottor, som övervakas av viceamiral Grezzlik, ska sköta säkerheten till sjöss, men Grezzlik har inte lyckats hejda pirathotet. Undermine agerar långsamt och Gazlowes egna slagskämpar är upptagna med att vakta handelspirarna. Därför vänder sig Gazlowe till självständiga, dugliga legosoldater som du för att lösa problem utanför staden utan att använda kartellens militära resurser.",al={"varför anlita mig","varför använda inte ratchets vakter","varför skickar gazlowe inte sina egna vakter"}}},fp="20,168,25.359.0,22.328.0,33.225.0,50.196.0,33.189.0,29.192.0,36.224.1,67.145.0"}
P.entries["quest:88756"] = {n="Bring Back a Bang",s="Bring Back a Bang är ett uppdrag där du ska återta instabilt sprängkrut som stulits från en byggarbetsplats i närheten. Fientliga Dark Iron-dvärgar har fört de märkta tunnorna österut till sina läger på Direforge Hill, där de utgör ett allvarligt hot mot området om de lämnas i fred.",h="Bring Back a Bang är ett uppdrag där du ska återta instabilt sprängkrut som stulits från en byggarbetsplats i...",kw={"sprängkrut","bring back a bang","byggarbetsplats","dark iron-dvärg","direforge hill","stulna sprängämnen"},ang={["profession:Engineering"]="Ingenjörer vet att sprängkrut och instabila ämnen kräver respekt och säker förvaring. Osäkrade förråd är en katastrof som bara väntar på att inträffa.",["race:Dwarf"]="Dvärgiska byggare och grävare förstår sprängämnenas destruktiva kraft alltför väl, särskilt när de hamnar i händerna på deras bittra släktingar bland Dark Iron-dvärgarna."},sec={{t="Stölden på byggarbetsplatsen",b="Fientliga Dark Iron-dvärgar har slagit läger österut på Direforge Hill. De utnyttjade byggarbetet i närheten och plundrade en byggarbetsplats, där de stal viktigt sprängkrut och körde lagret raka vägen tillbaka till sina tält."},{t="Farligt i fel händer",b="Sprängkrut i händerna på illasinnade Dark Iron-dvärgar utgör en omedelbar fara för det omgivande landet. De stulna tunnorna har tydliga röda märkningar som skiljer dem från vanliga förråd, och det är mycket bråttom att återta dem innan Dark Iron-dvärgarna använder dem för att orsaka förstörelse."}},faq={{q="Vem stal sprängämnena?",a="Dark Iron-dvärgar plundrade en byggarbetsplats i närheten och körde iväg tunnor med sprängkrut till sina tält österut på Direforge Hill.",al={"vem stal sprängämnen","vem tog tunnorna","stulet krut"}},{q="Vart tog Dark Iron-dvärgarna tunnorna?",a="De stulna kruttunnorna fördes österut till Dark Iron-dvärgarnas läger på Direforge Hill.",al={"var finns sprängämnen","läger på direforge hill","var finns stulet krut"}},{q="Hur känner du igen de stulna sprängämnena?",a="Sprängämnena från byggarbetsplatsen känns igen på de tydliga röda märkningarna som målats på tunnorna.",al={"hur ser tunnorna ut","hur känner man igen krut","rödmärkta tunnor"}},{q="Varför måste sprängämnena återtas?",a="Byggarbetarna har inte material över, och kraftfullt sprängkrut hos illasinnade Dark Iron-dvärgar utgör ett allvarligt hot mot alla i närheten.",al={"varför återta krut","vilket hot utgör dark iron-dvärgarna","varför stoppa dark iron-dvärgarna"}},{q="Vad är Direforge Hill?",a="Direforge Hill ligger öster om den lokala arbetsplatsen och har blivit översållat med fientliga Dark Iron-dvärgläger.",al={"vad är direforge hill","direforge hill-bakgrund"}},{q="Vilka är Dark Iron-dvärgarna?",a="Dark Iron-dvärgarna är en förrädisk dvärgfraktion som är ökänd för sin illvilja, mörka magi och ständiga fientlighet mot sina släktingar och grannar.",al={"vilka är dark iron-dvärgarna","varför är dark iron-dvärgar fientliga"}}},fp="17,162,30.144.0,14.223.0,25.129.0,42.86.0,43.80.0,43.128.0,23.100.0,30.130.0"}
P.entries["quest:888"] = {n="Stolen Booty",s="Piraternas last utanför Ratchet har tvingat Gazlowe att välja vad som är viktigast. Stolen Booty ger honom två viktiga varor: stövlar åt de lokala arbetarna och en ömtålig Telescopic Lens som behövs för att färdigställa hans observatorium.",h="Piraternas last utanför Ratchet har tvingat Gazlowe att välja vad som är viktigast.",kw={"the barrens","booty bay","drizzlik","gazlowe","ratchet","southsea freebooters","stolen booty","telescopic lens"},ang={["profession:Engineering"]="Gazlowes observatorium för in goblinernas precisionsoptik i kustbygget. Praktisk infrastruktur kräver både tungt byggnadsarbete och känsligt glasarbete.",["profession:Tailoring"]="Stövlarna från Drizzlik i Booty Bay visar hur färdiga lädervaror och skomakeri transporteras genom Steamwheedle Cartels hamnar."},sec={{t="Piratkapningen",b="Southsea Freebooters har i åratal stört handelsleder över Great Sea. Deras befästa läger strax söder om Ratchet ledde till en direkt konflikt med Gazlowe. Piraterna stoppade handelsfartyg på väg till hamnen och lade beslag på värdefulla förnödenheter från Steamwheedle Cartel. En del varor kunde avskrivas som fraktkostnader. Speciallasten var så viktig för Gazlowe att han anlitade legosoldater för att ta sig in i piraternas fäste."},{t="De saknade delarna",b="Gazlowe har två praktiska prioriteringar. Drizzlik skickade en välbehövlig sändning stövlar från Booty Bay åt de lokala arbetarna. Den andra varan är specialtillverkad: en slipad Telescopic Lens för observatorietornet med utsikt över Ratchet. Dess tvilling anlände oskadd med karavan genom Durotar, men piraterna lade beslag på den här linsen till havs. Så länge den inte återfinns står observatoriet tomt."}},faq={{q="Varför bryr sig Gazlowe så mycket om just de här två föremålen?",a="Gazlowe kan inte återta all last, men stövlarna från Drizzlik i Booty Bay och Telescopic Lens är oersättliga. De lokala arbetarna behöver stövlarna, och precisionslinsen behövs för att färdigställa observatoriet med utsikt över Ratchet.",al={"varför stövlar och lins","gazlowes föremål","vad stals"}},{q="Varifrån kom de två linserna till observatoriet?",a="Observatoriet behöver två linser. Den större anlände oskadd med en landkaravan genom Durotar. Southsea Freebooters stoppade den mindre linsen, som skickades sjövägen, utanför kusten vid The Barrens.",al={"telescopic lens ursprung","observatoriets linser","hur fick gazlowe tag på linserna"}},{q="Vem är Drizzlik?",a="Drizzlik är en goblinskomakare i Booty Bay, i södra Eastern Kingdoms. Han tillverkade och skickade stövlar åt Gazlowes arbetslag i Ratchet innan piraterna lade beslag på skeppet som fraktade dem.",al={"drizzlik booty bay","vem skickade stövlarna","drizzlik"}},{q="Var gömmer sig de stulna föremålen?",a="Stövellådorna och Telescopic Lens är gömda i Southsea-piraternas läger på The Merchant Coast, strax söder om Ratchet.",al={"var finns stövlarna","piratlägrets plats","var finns linsen"}},{q="Vad händer efter det här uppdraget?",a="Gazlowe tackar dig och berömmer din pålitlighet när du återlämnar föremålen. Han bjuder in dig att fortsätta arbeta för hans handelsverksamhet i Ratchet.",al={"uppföljning till stolen booty","nästa uppdrag","vad händer efter stolen booty"}},{q="Varför har Ratchet ett observatorium?",a="Goblinernas ingenjörskonst bygger på observation, navigering och kartläggning av närliggande land och sjöleder. Med ett färdigställt observatorietorn kan Ratchets ledare hålla uppsikt över handelsflottor, rivalers fartyg och hot längs The Merchant Coast.",al={"ratchets teleskop","gazlowes observatorium","varför vill gazlowe ha ett teleskop"}}},fx={["7e99fee8"]={q="Vad är Shipment of Boots till för?",a="Lasten innehåller stövlar som Drizzlik tillverkat nere i Booty Bay för Gazlowes affärer i Ratchet. Det krävs gott om utrustning för att driva en livlig neutral hamn och samordna handel över Kalimdor, och Gazlowe har inte råd att låta värdefulla importerade skor stanna i piraternas händer.",al={"varför behöver gazlowe stövlar","vad ska stövlarna användas till","shipment of boots"}},f85d62c5={q="Vad ska Telescopic Lens användas till?",a="Den teleskopiska linsen är det andra viktiga optiska elementet som Gazlowe behöver för att färdigställa observatoriet i Ratchet. Den större linsen har redan kommit fram säkert landvägen med karavan från Durotar, men piraterna i Southsea Freebooters lade beslag på den mindre linsen som skulle fraktas till sjöss. Hela anläggningen förblir ofärdig tills du hämtar den.",al={"vad ska linsen användas till","telescopic lens användning","varför behöver gazlowe linsen"}},["2f3767f4"]={q="Vilka ska du bekämpa för att återta bytet?",a="Du ska ge dig på Southsea Freebooters, som slagit läger längs kusten söder om Ratchet. Dessa banditer plundrade handelsfartyget som fraktade Gazlowes importerade last och gömde bytet runt sina läger vid stranden.",al={"vem har gazlowes byte","vem stal linsen och stövlarna","vilka pirater tog lasten"}}},fp="12,170,16.433.0,18.357.0,61.232.0,47.184.0,16.178.0,34.128.0,30.147.1,37.226.0"}
P.entries["quest:88809"] = {n="Preserving Eldarath",s="Commander Truesong ber dig hämta reliker från Eldarath och driva bort Spitelash. Ruinerna rymmer Kaldorei-historia som hon anser värd att bevara.",h="Commander Truesong ber dig hämta reliker från Eldarath och driva bort Spitelash.",kw={"azshara","commander truesong","eldarath","kaldorei-reliker","lord sarthiss","naga","spitelash"},sec={{t="En ruin värd att rädda",b="Kaldorei gjorde en gång Eldarath till en plats präglad av ära och makt. Commander Truesong ber dig hjälpa till att bevara det som finns kvar av historien. Spitelash plundrar ruinerna, och hon vill att du driver bort dem innan mer går förlorat."},{t="Truesongs beslutsamhet",b="Truesong anser att Eldaraths historia är värd att kämpa för, även om vissa Kaldorei skulle överlämna ruinerna åt naga. Du återvänder med reliker och Lord Sarthiss huvud, men Truesong säger att arbetet där fortsätter. Kampen för att bevara Eldarath är inte över."}},faq={{q="Varför är Eldarath viktigt?",a="Eldarath var en gång en plats präglad av Kaldoreis ära och makt. Commander Truesong anser att de reliker som finns kvar är värda att rädda.",al={"varför rädda eldarath","eldaraths historia","vad är eldarath värt"}},{q="Vem plundrar ruinerna?",a="Spitelash plundrar Eldarath, och Commander Truesong vill att du driver bort dem.",al={"vilka finns i eldarath","spitelash i ruinerna","naga plundrar eldarath"}},{q="Vem är Commander Truesong?",a="Commander Truesong ber dig hämta reliker från Eldarath och anser att Kaldorei-historien där är värd att kämpa för.",al={"vem är truesong","vem frågar om eldarath","befälhavare i azshara"}},{q="Vad ber Truesong dig hämta?",a="Truesong ber dig hämta reliker från Eldarath och Lord Sarthiss huvud.",al={"eldarath-reliker","vad ska samlas in","sarthiss huvud"}},{q="Var ligger Eldarath-ruinerna?",a="Eldarath ligger i Azshara. Vägen nordost leder in i ruinernas hjärta.",al={"eldaraths läge","var ligger eldarath","vägen till eldarath"}},{q="Är arbetet i Eldarath avslutat?",a="Nej. Truesong säger att arbetet i Eldarath är långt ifrån över och att kampen måste fortsätta.",al={"eldarath färdigt","vad händer sedan","är truesong klar"}}},fp="19,159,19.225.0,18.263.0,25.121.0,28.84.0,26.122.0,38.72.0,29.78.0,33.90.0"}
P.entries["quest:88821"] = {n="Making Contact",s="En väktare ber dig hitta en kaldorei-kvinna som setts på The Shattered Strand. Hennes ärende är okänt, och expeditionen hoppas få veta om hennes intressen stämmer överens med deras.",h="En väktare ber dig hitta en kaldorei-kvinna som setts på The Shattered Strand.",kw={"bay of storms","expedition","kaldorei-kvinna","ta kontakt","night elf","väktare","the shattered strand"},sec={{t="Längs kusten",b="En väktare på The Shattered Strand ber dig söka efter en kaldorei-kvinna som senast sågs på norra sidan av Bay of Storms. Hon tillhör inte expeditionen, och väktaren tvivlar på att hon är stridsvan. Hitta henne och ta reda på varför hon är där och om hennes syfte stämmer överens med expeditionens."}},faq={{q="Vem ber mig hitta kvinnan?",a="En väktare från expeditionen ber dig hitta kaldorei-kvinnan och ta reda på varför hon är där.",al={"vem vill ta kontakt","väktarens uppdrag","vem skickade mig"}},{q="Var sågs kaldorei-kvinnan senast?",a="Hon sågs senast längs norra sidan av Bay of Storms på The Shattered Strand.",al={"var är hon","kvinnans plats","var hittar jag henne"}},{q="Varför vill expeditionen tala med henne?",a="Expeditionen vill ta reda på hennes syfte och om hennes intressen stämmer överens med deras.",al={"varför kontakta henne","vad vill de","varför hitta alven"}},{q="Tillhör kvinnan expeditionen?",a="Nej. Väktaren säger att hon inte är med expeditionen.",al={"är hon med oss","vem är kvinnan","expeditionens kaldorei"}}},fp="14,177,15.282.0,35.94.0,39.84.0,47.86.0,36.53.0"}
P.entries["quest:889"] = {n="Spirit of the Wind",s="I Camp Taurajo erbjuder Mangletooth resenärer en fartökning hämtad från Agamaggan-blodskärvor. Den tillfångatagna quilboarens ritual hjälper dem att snabbt ta sig genom The Barrens.",h="I Camp Taurajo erbjuder Mangletooth resenärer en fartökning hämtad från Agamaggan-blodskärvor.",kw={"agamaggan","the barrens","blodsskärvor","camp taurajo","mangletooth","quilboar","hastighet","spirit of the wind"},ang={["class:Druid"]="Som druid kan du finna den kvarvarande kraften från vildguden Agamaggan i dessa riter fascinerande, ett rått uttryck för uråldrig natur.",["class:Shaman"]="Som shaman kan du höra ett eko av dina traditioner i samspelet med vinden genom kristalliserad gudomlig essens, med dess vördnad för elementära och förfäders krafter.",["faction:Horde"]="I Camp Taurajo håller vakterna Mangletooth under noggrann uppsikt. Horde-spejare använder hans kunskap om blodskärvsmagi för att snabbare ta sig över de södra slätterna."},sec={{t="En gåva från blodsskärvor",b="Att snabbt ta sig genom The Barrens kan hjälpa dig att undvika dess bestar och centaurkrigarskaror. I Camp Taurajo hämtar den tillfångatagna quilboaren Mangletooth kraft från röda, kristallina blodskärvor som finns utspridda över regionen. Ge honom tio, så kanaliserar han deras kvarvarande kraft till en fartökning som kallas Spirit of the Wind."},{t="Agamaggans uråldriga andetag",b="Quilboar vördar Agamaggan, den store galten vars blod spilldes över centrala Kalimdor under uråldriga War of the Ancients. Mangletooth kan riterna som kanaliserar det utspillda blodet, även i fångenskap. Ritualen väcker vild kraft och ger löpare fart som kan mäta sig med zhevraflockarna. Quilboar är bittra fiender till Horde, men Mangletooth delar med sig av Agamaggans välsignelser till resenärer som ger honom färska skärvor."}},faq={{q="Vad är Spirit of the Wind?",a="Spirit of the Wind är en kortvarig välsignelse som Mangletooth ger i Camp Taurajo. För tio blodskärvor ger han resenärer fart att ta sig genom The Barrens.",al={"vad är spirit of the wind","spirit of the wind-bonus","hastighetsbonus mangletooth"}},{q="Vem erbjuder Spirit of the Wind?",a="Mangletooth ger välsignelsen. Han är en quilboar som hålls fången av Horde i Camp Taurajo och utför ritualen när du vinner hans samarbete.",al={"vem ger spirit of the wind","mangletooth","vem lämnar in blodsskärvor för hastighet"}},{q="Varför behöver Mangletooth blodsskärvor?",a="Blodskärvor är kristallina fragment av Agamaggans utspillda blod. Mangletooth hämtar uråldragalfgudens ursprungliga kraft ur dem för att väva sina välsignelser.",al={"varför blodsskärvor","blodsskärvornas syfte","vad gör mangletooth med skärvor"}},{q="Kan jag få den här välsignelsen mer än en gång?",a="Ja. Ge Mangletooth tio blodskärvor varje gång, så kan han kanalisera välsignelsen när du återvänder.",al={"kan spirit of the wind upprepas","kan jag göra det här uppdraget igen","upprepningsbar bonus"}},{q="Varför skulle en quilboar hjälpa Hordens medlemmar?",a="Mangletooth hålls fången i Taurajo. Han byter bort sina förfäders kunskap om Agamaggans magi för att säkra sin överlevnad och gör upp med resenärer som samlar de heliga skärvor han värdesätter.",al={"varför hjälper mangletooth","vänlig quilboar","varför hjälpa horden"}},{q="Hur länge varar välsignelsen?",a="Välsignelsen klingar snart av, men Mangletooths förtrollning ger tillräcklig fart för att underlätta resor genom The Barrens en stund.",al={"hur länge varar bonusen","spirit of the wind-varaktighet","varar hastighetsbonusen länge"}}},fx={c2e92fc0={q="Varför behöver Mangletooth din hjälp i stället för att samla Blood Shards själv?",a="Mangletooth är en fånge hos Horden och hålls under noggrann bevakning i en bur i Camp Taurajo. Han kan inte ströva över slätterna eller själv skörda den fallne gudens kristalliserade väsen. Därför måste han förlita sig på äventyrare som har vägarna förbi och samla skärvorna i utbyte mot Agamaggans uråldriga välsignelser.",al={"varför kan mangletooth inte få tag på skärvor","varför behöver mangletooth mig","varför just jag, mangletooth"}}},fp="18,173,24.316.0,26.407.0,31.151.0,34.138.0,42.157.0,43.103.0,47.168.0,32.135.0"}
P.entries["quest:89"] = {n="The Everstill Bridge",s="Everstill Bridge är ett återuppbyggnadsprojekt som leds av Foreman Oslow i Lakeshire för att reparera stadens skadade stenbro. Arbetet har stannat av eftersom järnet som var avsett för projektet omdirigerades till vapentillverkning under den senaste orkinvasionen, och ersättningskaravanen från Stormwind överfölls av gnoller från Redridge.",h="Everstill Bridge är ett återuppbyggnadsprojekt som leds av Foreman Oslow i Lakeshire för att reparera stadens...",kw={"everstill bridge","foreman oslow","järnspett","järnnitar","lakeshire","redridge","gnoller från redridge"},ang={["faction:Alliance"]="Lakeshires avskurna försörjningsleder är ytterligare ett tydligt tecken på Stormwinds försummelse av sina yttre områden. Lokala arbetsledare tvingas förlita sig på lejda svärd för att skydda handeln längs vägarna.",["profession:Blacksmithing"]="Bristen visar hur desperata Lakeshires försvarare var: att smida vapen av konstruktionsspett och nitar var en sista utväg som räddade liv på bekostnad av viktig infrastruktur."},sec={{t="En avskuren stad",b="Stenbron över Lake Everstill är Lakeshires livsnerv. Den förbinder de västra vägarna mot Elwynn Forest med den bortre stranden och de norra passen. Under de senaste orkinfallen drevs staden till bristningsgränsen. När överlevnaden stod på spel smälte Lakeshire ner sitt järn till byggnadskonstruktioner för att smida ammunition, klingor och plåtrustningar och slå tillbaka Blackrock-inträngarna. Bron blev därför ofärdig och sårbar."},{t="Stulna leveranser",b="Foreman Oslow vädjade till adelsrådet och Stormwind om nytt byggnadsmaterial för att slutföra reparationerna. En järnlastad försörjningskaravan skickades iväg, men den kom aldrig fram. Ett krigsband av gnoller från Redridge överföll karavanen längs vägen och förde bort viktiga järnspett och nitar till sina läger i de norra kullarna. Utan äventyrare som är villiga att återta det stulna materialet står broprojektet stilla medan gnoller och orcher stärker sitt grepp om bergen."}},faq={{q="Varför är Everstill Bridge inte färdig?",a="Lakeshire var tvunget att smälta ner sitt byggnadsjärn till vapen, kulor och rustningar för att överleva den senaste orkinvasionen. En ersättningsleverans från Stormwind överfölls och plundrades sedan av lokala gnoller, så Foreman Oslow står utan materialet som behövs för att slutföra arbetet.",al={"varför trasig bro","vem förstörde everstill bridge","lakeshire trasiga bron"}},{q="Vem är Foreman Oslow?",a="Foreman Oslow är byggmästaren som leder återuppbyggnaden av bron över Lake Everstill. Utan stöd eller material från huvudstaden förlitar han sig på förbipasserande äventyrare för att återta stulet byggnadsmaterial från kullarna.",al={"foreman oslow","vem är oslow"}},{q="Vem stal bromaterialet?",a="Gnollerna från Redridge överföll försörjningskaravanen från Stormwind och förde järnspetten och nitarna till sina läger i kullarna bakom Lakeshire.",al={"vem stal järnnitarna","vem tog brojärnet"}},{q="Varför skickade inte Stormwind vakter som skyddade karavanen?",a="Sedan kung Varian Wrynn försvann har Stormwinds adelsråd i stort sett hållit tillbaka militärt stöd till avlägsna områden. Redridge Mountains har lämnats att försvara sig mot gnoller och Blackrock-orcher med endast minimalt stöd från stadens miliser.",al={"stormwind hjälper lakeshire","varför inga vakter"}},{q="Varför smälte Lakeshire ner sitt järn?",a="Under den senaste orkinvasionen fick Lakeshires försvarare desperat slut på krigsmateriel. För att överleva anstormningen smälte staden ner sina lager av byggnadsjärn till rustningar, svärd och ammunition.",al={"varför smälta järn","orkinvasion redridge"}},{q="Vilket material behövs för att reparera bron?",a="Foreman Oslow behöver särskilt kraftiga järnspett och järnnitar för att förstärka och förankra brospannet över Lake Everstill ordentligt.",al={"bromaterial","vad behöver oslow"}}},fx={f119d943={q="Varför måste Everstill Bridge byggas upp igen?",a="Foreman Oslow ansvarar för att återställa Lakeshires livsviktiga förbindelse över Lake Everstill. Bron binder samman staden med de kringliggande vägarna och södra Redridge, men tidigare krig tvingade staden att smälta ner brons järnkonstruktion till vapen och rustningar. Utan material till bron förblir staden utsatt, splittrad och oförmögen att upprätthålla normal trafik eller försvar.",al={"foreman oslows motiv","varför bygga upp bron igen","varför bryr sig oslow"}},f9ba0cdb={q="Vad ska Iron Pikes och Iron Rivets användas till?",a="Järnspjuten och järnnitarna är byggnadsbeslag som ska förstärka och stötta Everstill Bridges träställningar och stenvalv. De fraktades ursprungligen från Stormwind, men gnollerna i Redridge kapade försörjningskaravanen. Utan metallfästen har Oslows arbetslag tvingats avbryta allt arbete.",al={"vad ska järnspjuten användas till","järnnitarnas användning","varför behöver oslow spjut och nitar"}},["9c1de71f"]={q="Varför har gnollerna i Redridge materialet till bron?",a="En rövarhop av gnoller från Redridge överföll och plundrade karavanen från Stormwind och förde järnspjuten och järnnitarna till kullarna norr om Lakeshire. Gnollerna plundrar förnödenheter längs vägarna när tillfälle ges och utnyttjar Lakeshires isolerade läge och brist på militärt skydd.",al={"vem stal nitarna","varför har gnollerna järnet","gnollerna i redridges mål"}},ecd0e353={q="Varför ber Foreman Oslow dig i stället för stadsvakten?",a="Lakeshires lokala garnison är hårt pressad när den försvarar stadens utkanter mot invaderande Blackrock-orcher och aggressiva gnollflockar. Stormwind erbjuder i stort sett inga militära förstärkningar, så stadsvakten kan inte avvara män för att genomsöka kullarna efter stulet byggmaterial. Oslow måste därför förlita sig på äventyrare som har vägarna förbi.",al={"varför inte lakeshires vakter","varför just jag till everstill bridge","varför hämtar inte vakterna förnödenheterna"}}},fp="20,229,14.375.0,16.361.0,39.244.0,21.199.0,30.135.0,56.223.0,39.175.0,46.113.0"}
P.entries["quest:890"] = {n="The Missing Shipment",s="I Ratchet väntar Gazlowe på varor som skickats från Booty Bay över Great Sea. Han skickar bud till Wharfmaster Dizzywig för att kontrollera kajens register, medan Southsea Freebooters fortfarande kan ligga bakom förseningen.",h="I Ratchet väntar Gazlowe på varor som skickats från Booty Bay över Great Sea.",kw={"booty bay","dizzywig","drizzlek","freebooters","gazlowe","liggare","ratchet","försändelse"},ang={["faction:Horde"]="Ratchet förblir neutralt och erbjuder resande från Horde en hamn mellan Kalimdor och Stranglethorn Vale. Handeln vid dess kajer är viktig för båda.",["profession:Engineering"]="Gazlowes behov av reservdelar, exotiska importer och specialutrustning från Booty Bay visar hur svårt det är att hålla Ratchets maskineri igång långt från goblinernas industricentra."},sec={{t="Ratchets livsviktiga förbindelse",b="Ratchet är Steamwheedle Cartels handelshamn på Kalimdor. Skepp korsar Great Sea från Booty Bay med tillverkade varor, exotiska förnödenheter och tung last till stadens byggprojekt och handel. När last försvinner blir affärerna lidande. Chief Engineer Gazlowe håller noga reda på varje låda som förs in i hamnen."},{t="Jämföra lastförteckningarna",b="Southsea Freebooters håller till längs kusten söder om Ratchet och bordar ofta handelsskepp. Gazlowe kontrollerar sina register innan han anklagar piraterna eller skickar någon i strid. Han skickar sin inventarieförteckning till Wharfmaster Dizzywig vid hamnen. Dizzywig övervakar lossning och förvaring av skeppens last och kan kontrollera om varor gått förlorade till havs eller hamnat fel i ett lager."}},faq={{q="Vad finns i den försvunna försändelsen?",a="Gazlowe talar om livsviktiga varor från Booty Bay, men Wharfmaster Dizzywig tror att chefingenjören oroar sig för en specialbeställning av stövlar från Drizzlek.",al={"gazlowes last","vad stals","varor i försvunnen försändelse"}},{q="Vem är Wharfmaster Dizzywig?",a="Wharfmaster Dizzywig ansvarar för fraktregistren vid Ratchets kajer. Han sköter lastöverföringar mellan skepp som korsar havet och lokala lager åt Steamwheedle Cartel.",al={"dizzywig","vem är dizzywig","ratchets hamnmästare"}},{q="Varför misstänker Gazlowe Southsea Freebooters?",a="Southsea Freebooters har läger längs Merchant Coast, strax söder om Ratchet. De angriper handelslederna mellan Kalimdor och Eastern Kingdoms, vilket gör dem misstänkta när handelslast försvinner.",al={"freebooters roll","pirattjuvar","varför pirater"}},{q="Varifrån kom försändelsen?",a="Sändningen kom från Booty Bay, goblinhamnen vid södra spetsen av Stranglethorn Vale i Eastern Kingdoms.",al={"försändelsens ursprung","var kom den ifrån","last från booty bay"}},{q="Vad händer efter att jag lämnat liggaren till Dizzywig?",a="Dizzywig jämför sina fraktregister med Gazlowe's Ledger för att se om lasten nådde Ratchets lager eller beslagtogs innan den lossades.",al={"dizzywigs nästa steg","uppföljning av liggaren"}},{q="Varför kontrollerar Gazlowe inte kajerna själv?",a="Som Ratchets Chief Engineer och ledare sköter Gazlowe stadens angelägenheter och utbyggnadsprojekt från sitt centrala kontor. Han föredrar att betala resande äventyrare för att bära papper genom staden.",al={"varför skicka mig","gazlowes lättja"}}},fx={cd1ef655={q="Varför vill Gazlowe att du undersöker lasten?",a="Gazlowe har väntat i evigheter på viktiga varor från Booty Bay på andra sidan Stora havet. Som chefsingenjör och boss i Ratchet är det centralt för hans verksamhet och inflytande att hålla den lokala handeln igång och lagret fyllt. Han misstänker starkt att de närbelägna Southsea Freebooters lade beslag på lasten, men först måste han be Wharfmaster Dizzywig att jämföra sin bokföring med hamnens loggböcker. Då kan han bekräfta om lådorna stals eller bara försvann bland Ratchets kaotiska hamnkajer.",al={"varför bryr sig gazlowe om lasten","gazlowes motiv till den försvunna lasten","varför hitta den försvunna lasten"}}},fp="20,215,24.296.0,27.381.0,32.152.0,28.176.0,50.206.0,33.116.0,49.146.0,44.173.0"}
P.entries["quest:89001"] = {n="Home on the Range",s="Vid Talrendis Point erbjuder Berdun Cliffbrew dig gratis logi om du tar med hudar för att laga hans reselägertält. Han behöver Mosshoof Hides från Azshara.",h="Vid Talrendis Point erbjuder Berdun Cliffbrew dig gratis logi om du tar med hudar för att laga hans...",kw={"azshara","berdun cliffbrew","gratis logi","mosshoof-hudar","mosshooves","talrendis point","tältlagning","reseläger"},sec={{t="En plats att bo",b="Berdun Cliffbrews reseläger vid Talrendis Point behöver repareras. Han erbjuder dig gratis logi om du tar med Mosshoof Hides till tältet. De lättaste Mosshooves att jaga finns norr om lägret, men hudar från vilken Mosshoof som helst duger."}},faq={{q="Vad behöver Berdun?",a="Berdun Cliffbrew behöver Mosshoof Hides för att laga sitt reselägertält vid Talrendis Point.",al={"vilka hudar behöver berdun","berduns tältlagning","mosshoof-hudar"}},{q="Vad erbjuder Berdun?",a="Berdun erbjuder dig gratis logi i sitt reseläger om du tar med hudarna han behöver för att laga tältet.",al={"gratis logi hos berdun","var kan jag bo","berduns logi"}},{q="Var hittar jag Mosshoof Hides?",a="Berdun säger att de lättaste Mosshooves att jaga finns strax norr om Talrendis Point, men hudar från vilken Mosshoof som helst duger.",al={"var finns mosshooves","mosshoof-plats","jaga mosshooves"}},{q="Hur många hudar behöver Berdun?",a="Berdun behöver fem Mosshoof Hides.",al={"antal hudar","hur många mosshoof-hudar"}}},fp="17,150,15.234.0,22.89.0,23.106.0,32.114.0,32.33.0"}
P.entries["quest:89013"] = {n="Gettin' Buzzed",s="Berdun behöver vildhonung till mjödet på raststugan och ber dig samla den från getingbon. Han lånar dig ett luftgevär så att du kan skjuta ner bona.",h="Berdun behöver vildhonung till mjödet på raststugan och ber dig samla den från getingbon.",kw={"berdun","gettin' buzzed","mjöd","luftgevär","valormok","getingbon","vildhonung"},sec={{t="Honung till mjöd",b="Berdun brygger mjöd åt raststugan, men han är för gammal för att samla honung själv. Du hittar getingbon i träd norr om Haldaarlägret och väster om Valormok. Hippogryfer visar att du är på rätt plats. Berdun lånar dig ett luftgevär så att du kan skjuta ner bona och samla in honungen."}},faq={{q="Vem behöver honungen?",a="Berdun behöver vildhonung till mjödet han brygger åt raststugan.",al={"vem vill ha honung","berdun honung"}},{q="Var finns getingbona?",a="Getingbona finns i träd norr om Haldaarlägret och väster om Valormok. Ser du hippogryfer är du på rätt plats.",al={"var finns bona","honungens plats"}},{q="Varför behöver Berdun hjälp med att samla honung?",a="Berdun säger att han börjar bli till åren och inte kan samla honungen själv.",al={"varför hjälpa berdun","berdun för gammal"}},{q="Vad lånar Berdun mig?",a="Berdun lånar dig ett luftgevär så att du kan skjuta ner bona.",al={"luftgevär","hur skjuta ner bon"}},{q="Vad ska honungen användas till?",a="Berdun använder honung för att brygga mjöd åt raststugan.",al={"vildhonungens syfte","honung till mjöd"}}},fp="14,151,14.276.0,20.66.0,25.127.0,42.74.0,25.54.0,22.52.0"}
P.entries["quest:891"] = {n="The Guns of Northwatch",s="Captain Thalo'thas Brightsun i Ratchet vill att kanonerna vid Northwatch Hold tystas. Alliansens kanonjärer där har beskjutit handelsfartyg, så han skickar dig längs The Merchant Coast för att slå ut artilleriofficerarna och hämta brickor från fallna fotsoldater.",h="Captain Thalo'thas Brightsun i Ratchet vill att kanonerna vid Northwatch Hold tystas.",kw={"barrens","brightsun","kanoner","fairmount","the merchant coast","northwatch","ratchet","smythe","theramore","whessan"},ang={["faction:Horde"]="Som medlem av Horden kan du angripa Northwatch Hold och hejda en aggressiv alliansfästning i The Barrens, så att Kalimdors gränser säkras för ditt folk.",["race:Human"]="Som människa kan du se hur isoleringen långt hemifrån tär på Theramores gränsgarnisoner och göder hänsynslös fientlighet."},sec={{t="Ett hot längs kusten",b="Northwatch Hold bevakar Southern Barrens kust åt människorna i Theramore. Soldaterna håller uppsikt över Hordens aktiviteter i Kalimdor, men rädslan har fått dem att se varje okänt segel som ett hot. Kanonerna på murkrönen skjuter utan förvarning mot förbipasserande skepp och utsätter Ratchets handelssjöfart och kaparfartyg för fara."},{t="Tysta murvärnen",b="Captain Brightsun vill att angreppen på hans skepp ska besvaras. Captain Fairmount för befälet över Northwatch, medan Whessan och Smythe leder dess kanoner. När du besegrar dem och tar Theramore-medaljer från garnisonen kastas artilleriet i oordning och Ratchets skepp får fritt fram längs The Merchant Coast."}},faq={{q="Varför skjuter Northwatch Hold på skepp från Ratchet?",a="Northwatchs mänskliga soldater fruktar angrepp från Horden och traktens pirater. Deras kanonjärer skjuter på nästan alla fartyg som passerar The Merchant Coast, oavsett om de för neutral eller fientlig flagg.",al={"varför skjuter de på skepp","varför anfaller northwatch ratchet","northwatchs kanoner skjuter"}},{q="Vem är Captain Thalo'thas Brightsun?",a="Captain Thalo'thas Brightsun är en högalvskapten inom kaparflottan med bas i Ratchet. Han för befälet över en handelsflotta och skyddar den lokala sjöfarten mot rivaler, däribland Alliansens styrkor vid Northwatch Hold.",al={"vem ger uppdraget","thalo'thas brightsun","uppdragsgivare i ratchet"}},{q="Vilka är Captain Fairmount, Cannoneer Whessan och Cannoneer Smythe?",a="Captain Fairmount för befälet över garnisonen vid Northwatch Hold. Whessan och Smythe leder artilleribatterierna som vetter mot havet. När du besegrar dem störs fästningens befäl och dess tunga kanoner slås ut.",al={"fairmount whessan smythe","northwatchs officerare","mål för northwatchs kanoner"}},{q="Vad är Theramore Medals?",a="Theramore-medaljer är militära insignier som bärs av människornas fotsoldater och vakter vid Northwatch Hold. Captain Brightsun ber dig hämta dem som bevis på att kaparnas död har hämnats och garnisonen slagits sönder.",al={"theramore medal","varför samla medaljer","vad ger medaljer"}},{q="Var ligger Northwatch Hold?",a="Northwatch Hold ligger på Barrens sydöstra klippor, söder om Ratchet längs The Merchant Coast.",al={"var ligger northwatch","northwatchs plats","var finns the guns of northwatch"}},{q="Tillhör Northwatch Hold officiellt Theramore?",a="Ja. Theramore grundade Northwatch Hold för att säkra ett militärt fotfäste på Kalimdors fastland. Den isolerade garnisonen agerar aggressivt och misstänksamt mot dem som färdas genom The Barrens.",al={"tillhör northwatch theramore","alliansfraktionen northwatch","jaina northwatch"}}},fx={["30184c04"]={q="Varför vill Captain Thalo'thas Brightsun att Northwatch Hold ska angripas?",a="Captain Brightsun leder en handelsflotta från Ratchet, och Northwatch Hold har ödelagt hans försörjning. Alliansens artillerister i fästningen är paralyserade av misstänksamhet och skjuter mot nästan alla fartyg som seglar förbi Merchant Coast. De behandlar neutrala kapare och handelsfartyg som fientliga plundrare. Efter att ännu ett fartyg och dess besättning gått förlorade för Northwatchs kanoner vill Brightsun hämnas direkt på de ansvariga officerarna och få ett slut på bombardemanget som hotar hela hans flotta.",al={"varför angripa northwatch","brightsuns motiv","varför vill brightsun förstöra northwatch"}},f93e1604={q="Varför behöver Captain Brightsun din hjälp i stället för att själv ta hand om Northwatch?",a="Ratchet blomstrar tack vare sin neutralitet och förlitar sig på en öppen hamn som välkomnar både Horde och oberoende resenärer utan att formellt förklara krig mot Theramore eller Alliansen. Ett direkt anfall lett av Ratchets goblinmyndigheter eller Brightsuns överlevande kapare kan utlösa en öppen konflikt med Jaina Proudmoores styrkor på andra sidan havet. Genom att anlita en oberoende äventyrare kan Brightsun tysta kanonerna och hämnas sina förlorade fartyg utan att dra in hamnen i ett formellt krig.",al={"varför anlita mig","varför angriper inte ratchet northwatch","varför angriper inte brightsun"}}},fp="22,245,24.305.0,22.304.0,54.191.0,36.198.0,67.212.0,26.220.0,33.106.0,48.202.0"}
P.entries["quest:892"] = {n="The Missing Shipment",s="Vid Ratchets kajer pekar Dizzywigs liggare bort från korruption i hamnen och mot Southsea Freebooters. Gazlowe tar emot handlingarna och förbereder sig på att återta sin förlorade last.",h="Vid Ratchets kajer pekar Dizzywigs liggare bort från korruption i hamnen och mot Southsea Freebooters.",kw={"the barrens","dizzywig","freebooters","gazlowe","bokföring","pirater","ratchet","försändelse","undermine"},ang={["class:Rogue"]="Hamndokumenten visar hur lätt varor kan försvinna mellan hav och land, ett klassiskt smugglarknep.",["faction:Alliance"]="I Barrens krävs noggranna allianser. Genom att hjälpa Ratchets ledning bidrar du till en pålitlig bas för Alliansen i centrala Kalimdor.",["faction:Horde"]="Ratchet är neutralt, och att hålla Gazlowe nöjd bidrar till stabila handelsvägar och goblinernas neutralitet, vilket gynnar Horden."},sec={{t="Räkenskaperna går ihop vid kajen",b="Ratchets handel och hamn medför ständiga logistiska problem. När en försändelse inte kommer fram misstänker Gazlowe felaktiga hamnräkenskaper eller fuffens på kajerna. Hamnmästare Dizzywig granskar fraktsedeln och hävdar att hans böcker är rena. Mottagningshandlingarna redovisar allt, så varorna kom aldrig till kajen."},{t="Blicken riktas mot Freebooters",b="När Dizzywig friar hamnens egna verksamheter från förskingring återstår Southsea Freebooters, som slagit läger längs kusten, som de troliga skyldiga. Dizzywig lämnar tillbaka liggaren och nämner separata lådor som väntar från Undermine. Han skickar dig tillbaka till Gazlowe, Ratchets chefsingenjör. Övertygad om Dizzywigs lojalitet slutar Gazlowe granska leveransböcker och börjar organisera en expedition för att återta sitt stulna byte."}},faq={{q="Vad finns i Gazlowes bokföring?",a="Gazlowes liggare innehåller fraktsedlar, lastförteckningar och hamnens mottagningsloggar för varor som anländer till Ratchet. Dizzywig granskar handlingarna för att se om lådorna som saknas registrerades när de lossades från fartygen.",al={"vad är bokföringen","gazlowes bokföring","fraktsedel vid kajen"}},{q="Vem stal egentligen Gazlowes försändelse?",a="Gazlowe misstänker Southsea Freebooters, pirater som slagit läger längs kusten söder om Ratchet. Dizzywigs handlingar visar inga avvikelser vid kajerna, så Gazlowe riktar uppmärksamheten mot plundrarna.",al={"vem stal försändelsen","vem tog lasten","vem har försändelsen"}},{q="Varför litar Gazlowe på Wharfmaster Dizzywig?",a="Gazlowe litar på Dizzywig, som står på hans lönelista och har tjänat honom troget. Gazlowe tror att hamnmästaren vet bättre än att lura honom och godtar hans försäkran om att böckerna är rena.",al={"ljuger dizzywig","litar gazlowe på dizzywig","är dizzywig ärlig"}},{q="Vad är det för föremål från Undermine som Dizzywig nämner?",a="Dizzywig nämner separata varor från Undermine, goblinernas huvudstad, som väntar på att Gazlowe ska hämta dem när han får en stund över från att sköta staden.",al={"försändelse från undermine","vad kommer från undermine","varor från undermine"}},{q="Vart leder utredningen härnäst?",a="När du lämnar tillbaka liggaren till Gazlowe leder det till Stolen Booty. Du får i uppdrag att infiltrera Southsea Freebooters läger längs Barrens södra kust och ta tillbaka den förlorade lasten.",al={"vilket uppdrag kommer härnäst","nästa steg efter den saknade försändelsen","vart ska man gå härnäst"}},{q="Var finns Wharfmaster Dizzywig?",a="Hamnmästare Dizzywig ansvarar för Ratchets kajer, nära bryggorna där handelsfartyg lastar och lossar sin last.",al={"var finns dizzywig","dizzywigs plats","hitta hamnmästaren"}}},fx={["96f6dc82"]={q="Varför skickar Wharfmaster Dizzywig dig tillbaka till Gazlowe?",a="Wharfmaster Dizzywig ansvarar för att hantera lasten som kommer till och lämnar hamnkajerna. Gazlowe skickade dig för att granska Dizzywigs bokföring kring de försvunna lådorna. När Dizzywig lämnar tillbaka liggaren rentvår han sig själv. Fraktsedlarna visar att varorna aldrig officiellt lämnade hamnen, vilket flyttar skulden från hamnkajerna och pekar rakt på de lokala Southsea Freebooters.",al={"varför vill dizzywig ha det här","dizzywigs motiv","varför skicka liggaren till gazlowe"}}},fp="20,207,27.326.0,23.386.1,28.200.0,38.193.0,44.181.0,57.145.0,40.173.1,38.118.0"}
P.entries["quest:8921"] = {n="The Ectoplasmic Distiller",s="Mux Manascrambler i Gadgetzan arbetar på sin spökavslöjare som sträcker sig över dimensionerna, men har fått slut på både pengar och arbetskraft. Det första han behöver är en ektoplasmadestillator, och han ber dig om en lista med dyrbara material och fyrtio guld för att bygga den.",h="Mux Manascrambler i Gadgetzan arbetar på sin spökavslöjare som sträcker sig över dimensionerna, men har fått...",kw={"arkanitkonverterare","burning steppes","ectoplasmic distiller","gadgetzan","mux manascrambler","stenskalolja","tanaris","vulkanisk aska"},sec={{t="Vad Mux behöver",b="Efter A Supernatural Device välkomnar Mux Manascrambler din hjälp med sin spökavslöjare, en maskin som ska nå genom dimensionerna. Den första delen är en destillator som ska samla själva dödens väv, och han varnar för att den inte blir lätt att bygga. Han vill ha en ömtålig arkanitkonverterare, fyra större evighetsessenser, tio stenskalolja och tjugofem vulkanisk aska, plus fyrtio guld. Askan ska användas till ett filter och måste komma från Burning Steppes lavapölar. Mux medger att materialen är dyra, men svär på att vartenda ett behövs."},{t="Mux tackar dig",b="Mux säger att det här är precis materialen han behövde och att du kom i rättan tid. Han lovar att ha din destillator klar om ett ögonblick och ger dig något som tack för besväret."}},faq={{q="Vem ber om de här materialen?",a="Mux Manascrambler i Gadgetzan i Tanaris, som bygger en spökavslöjare som sträcker sig över dimensionerna.",al={"uppdragsgivare","vem ger uppdraget","vem är mux"}},{q="Vilka material behöver Mux?",a="En ömtålig arkanitkonverterare, fyra större evighetsessenser, tio stenskalolja, tjugofem vulkanisk aska och fyrtio guld.",al={"föremål som krävs","vad behöver jag","material till destillatorn"}},{q="Var hittar man den vulkaniska askan?",a="Mux säger att du ska samla den vid lavapölarna i Burning Steppes.",al={"var finns vulkanisk aska","var får man tag på aska"}},{q="Varför behöver Mux just de här komponenterna?",a="De används i en ektoplasmadestillator, en apparat som samlar det som döden är gjord av. Den vulkaniska askan används till filtret.",al={"varför arkanit","vad används askan till","varför behövs föremålen"}},{q="Vad händer efter att du har lämnat över materialen?",a="Hunting for Ectoplasm är nästa steg.",al={"nästa steg","vad händer sedan","nästa uppdrag"}}},fp="25,204,14.509.0,12.161.1,29.111.0,32.135.0,32.75.0,44.124.0,42.33.0"}
P.entries["quest:8922"] = {n="A Supernatural Device",s="Deliana söker ett sätt att tala med Anthion Harmons vålnad. En ingenjör med en säregen fascination för det övernaturliga säger sig kunna bygga en maskin som talar med de döda, och du tar med blodet du samlade till honom i Gadgetzan som betalning.",h="Deliana söker ett sätt att tala med Anthion Harmons vålnad.",kw={"anthion harmon","deliana","gadgetzan","mux manascrambler","förseglad behållare med gift","övernaturlig anordning","tanaris"},ang={["faction:Alliance"]="Deliana skickar alliansäventyrare till Mux Manascrambler i Gadgetzan."},sec={{t="Betalning till en ingenjör",b="Deliana söker ett sätt att nå Anthion Harmon, eller närmare bestämt hans vålnad. Ingenjören Deliana tänker på är Mux Manascrambler, som skryter med en maskin för att tala med de döda. Blodet du har var avsett för honom från början, så ta det till Gadgetzan i Tanaris och ge det till Mux i utbyte mot hans tjänster."},{t="En välkommen leverans",b="Mux blir glad över att få blodet, eftersom hans förråd började sina. Sedan frågar han om Deliana skickade dig."}},faq={{q="Varför skickar Deliana dig till Gadgetzan?",a="Deliana vill tala med Anthion Harmons vålnad. En ingenjör i Gadgetzan hävdar att han kan bygga en maskin som talar med de döda, så du tar med betalningen till honom.",al={"varför åka till gadgetzan","deliana gadgetzan","övernaturlig anordnings syfte"}},{q="Vad finns i behållaren som levereras?",a="Det är en förseglad behållare med blodet du samlade, avsedd som betalning för ingenjörens tjänster.",al={"vad finns i behållaren","förseglad behållare med gift","vilket blod är det här"}},{q="Vem tar emot leveransen i Gadgetzan?",a="Mux Manascrambler, ingenjören i Gadgetzan med en säregen fascination för det övernaturliga.",al={"vem får behållaren","kontakt i gadgetzan","vem är mux manascrambler"}},{q="Vad följer efter den här leveransen?",a="Ectoplasmic Distiller följer.",al={"vad händer sedan","nästa uppdrag","efter a supernatural device"}}},fp="21,166,23.301.0,18.104.1,39.156.0,45.86.0,39.111.0,27.34.0"}
P.entries["quest:89228"] = {n="Winter Frontier Fishery",s="Berdun Cliffbrew vid Talrendis Point vill ha Winter Squid till resestugans måltider. De är i säsong längs Azsharas kust.",h="Berdun Cliffbrew vid Talrendis Point vill ha Winter Squid till resestugans måltider.",kw={"azshara","berdun cliffbrew","fiske","skaldjur","talrendis point","resestuga","winter squid"},sec={{t="En måltid åt resestugan",b="Vid Talrendis Point i Azshara vill Berdun Cliffbrew ha skaldjur till resestugan. Winter Squid är i säsong längs kusten, och du kan ta med tio stycken till Berdun. Han medger att fiske inte är hans starka sida, men matlagning kan han."}},faq={{q="Vem ber om Winter Squid?",a="Berdun Cliffbrew vid Talrendis Point i Azshara vill ha Winter Squid till resestugan.",al={"vem vill ha bläckfisk","berdun cliffbrew fiske","vem är berdun"}},{q="Varför vill Berdun ha Winter Squid?",a="Berdun vill ha skaldjur till resestugan, och Winter Squid är i säsong längs Azsharas kust.",al={"varför bläckfisk","vad ska bläckfisken användas till","mat till resestugan"}},{q="Var kan jag hitta Winter Squid?",a="Winter Squid kan fiskas upp utanför Azsharas kuster.",al={"var finns winter squid","var finns bläckfisk","azshara bläckfisk"}},{q="Hur många Winter Squid behöver Berdun?",a="Berdun ber om tio Winter Squid.",al={"antal bläckfiskar","hur många fiskar","tio bläckfiskar"}},{q="Kan jag få bläckfisken från någon annan?",a="Om fiske inte är något för dig föreslår Berdun att du blir vän med en fiskare eller betalar någon för fångsten.",al={"köpa bläckfisk","be någon om fisk","inte fiske"}},{q="Är Berdun fiskare?",a="Berdun säger att han inte är någon vidare fiskare, men att han är kock.",al={"berdun fiske","kan berdun fiska","berdun kock"}}},fp="23,135,20.223.0,31.87.0,34.98.0,30.54.0,39.33.0,38.99.0,22.58.0"}
P.entries["quest:8923"] = {n="A Supernatural Device",s="Mokvar har användning för giftproverna du samlade in: de är till en bekant, Mux Manascrambler, som finns i Gadgetzan. Mux arbetar på en apparat för att tala med de döda, och Mokvar hoppas att den ska hjälpa till att nå Anthion.",h="Mokvar har användning för giftproverna du samlade in: de är till en bekant, Mux Manascrambler, som finns i...",kw={"anthion","gadgetzan","mokvar","mux manascrambler","förseglad giftbehållare","övernaturlig apparat","tanaris"},ang={["faction:Horde"]="Mokvar skickar Horde-äventyrare till Mux Manascrambler i Gadgetzan."},sec={{t="Gift åt en ingenjör",b="Mokvar påpekar att du måste vara modig som stannat kvar och säger att det finns mer rustning att få för den som fortfarande är villig att hjälpa till. Giftet du samlade in hör hemma hos en bekant, Mux Manascrambler, en ingenjör med intresse för det övernaturliga. Mux nuvarande projekt är en apparat för att tala med de döda. Mokvar sätter sitt sista hopp till den: att nå Anthion för att få veta mer om Mokvars egen situation. Du tar den förseglade behållaren till Mux i Gadgetzan, i Tanaris."},{t="En välkommen leverans",b="Mux blir glad över att få giftet, eftersom förrådet höll på att ta slut. Sedan frågar Mux om Mokvar skickade dig."}},faq={{q="Vem skickar dig på den här leveransen?",a="Mokvar, som vill att den förseglade giftbehållaren ska lämnas till en bekant i Gadgetzan.",al={"vem ger uppdraget","uppdragsgivare","mokvar"}},{q="Vart ska giftet?",a="Till Mux Manascrambler i Gadgetzan, i Tanaris.",al={"var lämnar jag giftet","inlämningsplats","mux plats"}},{q="Vem är Mux Manascrambler?",a="En ingenjör som fascineras av det övernaturliga och är bekant med Mokvar.",al={"vem är mux","mux manascrambler bakgrund"}},{q="Vad bygger Mux?",a="En apparat som låter dig kommunicera med de döda. Det är Mux senaste projekt.",al={"vad är apparaten","vad bygger mux","övernaturlig apparat"}},{q="Varför vill Mokvar nå de döda?",a="Mokvar hoppas kunna nå Anthion och få veta mer om sin egen situation, och ser apparaten som en sista chans.",al={"varför kontakta anthion","vem är anthion","mokvars motiv"}}},fp="21,174,21.392.0,18.121.1,36.82.0,32.61.0,25.94.0,21.88.0,39.112.0"}
P.entries["quest:8924"] = {n="Hunting for Ectoplasm",s="Mux Manascrambler i Gadgetzan har sin Ectoplasmic Distiller redo och behöver nu ektoplasma. Du tar den till tre avlägsna länder, Silithus, Winterspring och Eastern Plaguelands, och samlar in tolv av varje sort från de kroppslösa döda. Detta följer på The Ectoplasmic Distiller.",h="Mux Manascrambler i Gadgetzan har sin Ectoplasmic Distiller redo och behöver nu ektoplasma.",kw={"eastern plaguelands","ectoplasmic distiller","frusen ektoplasma","gadgetzan","hunting for ectoplasm","mux manascrambler","bränd ektoplasma","silithus","stabil ektoplasma","winterspring"},sec={{t="Tre klimat, tre sorter",b="Mux Manascrambler är stolt över destillatorn och varnar för att du har en lång resa framför dig för att hitta kroppslösa odöda. Enligt Mux påverkar klimatet hur de dödas spektrala väv är beskaffad. I Silithus finns plågade nattalver, i Winterspring finns highborne-andar och i Eastern Plaguelands finns spöken och banshees. Varje plats ger en annan sorts ektoplasma: tolv brända, tolv frusna och tolv stabila. Mux säger att du ska ställa ned destillatorn i närheten innan du skördar ektoplasman och sedan ta med den och ektoplasman tillbaka till Gadgetzan."},{t="Mux fäller sin dom",b="Mux är förtjust i ektoplasman. Han förklarar att de övernaturliga energierna i den låter dig nå ut till själar som inte helt har lämnat den här världen."}},faq={{q="Vem skickar dig för att samla ektoplasma?",a="Mux Manascrambler i Gadgetzan, i Tanaris, när hans destillator är byggd.",al={"vem ger uppdraget hunting for ectoplasm","uppdragsgivare till hunting for ectoplasm"}},{q="Varför behöver Mux ektoplasma från tre olika platser?",a="Mux säger att olika klimat ger de dödas spektrala väv olika konsistens. Han vill ha tolv brända från Silithus, tolv frusna från Winterspring och tolv stabila från Eastern Plaguelands.",al={"varför tre sorters ektoplasma","olika sorters ektoplasma","varför silithus winterspring eastern plaguelands"}},{q="Vilka andar ger ektoplasman?",a="Plågade nattalver i Silithus, highborne-andar i Winterspring samt spöken och banshees i Eastern Plaguelands.",al={"vilka fiender ger ektoplasma","vad ska dödas för ektoplasma","vilka spöken ger ektoplasma"}},{q="Hur samlas ektoplasman in?",a="Mux säger att du ska ställa ned destillatorn nära de kroppslösa odöda innan du skördar ektoplasman från dem.",al={"hur fungerar destillatorn","hur samlar man in ektoplasma"}},{q="Var passar detta in i Mux arbete?",a="Det kommer efter The Ectoplasmic Distiller, och A Portable Power Source följer på det.",al={"förkunskapskrav för hunting for ectoplasm","vad kommer före hunting for ectoplasm"}}},fp="21,245,27.492.0,13.159.1,34.82.0,56.187.0,36.149.0,30.84.0,34.77.0"}
P.entries["quest:8925"] = {n="A Portable Power Source",s="Med ektoplasman i handen behöver Mux Manascrambler en stabil, bärbar energikälla som håller den aktiv. Han har hört rykten om Magma Lord Bokk, en elementarvarelse i Burning Steppes vars hjärta är en Magma Core, och vill att du hämtar den åt honom i Gadgetzan.",h="Med ektoplasman i handen behöver Mux Manascrambler en stabil, bärbar energikälla som håller den aktiv.",kw={"blackrock mountain","burning steppes","gadgetzan","spökavslöjare","magma core","magma lord bokk","mux manascrambler"},sec={{t="Ett hjärta av ändlös hetta",b="Efter Hunting for Ectoplasm vill Mux Manascrambler ha en stadig, flyttbar kraftkälla som håller ektoplasman aktiv. Ryktet säger att Magma Lord Bokk, en mäktig elementarvarelse, har en Magma Core som hjärta, en ändlös värmekälla. Magma Lord sägs hålla till i Burning Steppes, söder om Blackrock Mountain och väster om Pillar of Ash. Mux vill att du hämtar kärnan till Gadgetzan så att den extradimensionella spökavslöjaren kan fungera."},{t="Äntligen kraft",b="Mux blir överlycklig när du kommer med kärnan och förklarar att den helt säkert ger spökavslöjaren all energi den behöver."}},faq={{q="Varför behöver Mux Manascrambler en kraftkälla?",a="Mux vill ha en stadig, flyttbar energikälla som räcker för att hålla ektoplasman igång och driva den extradimensionella spökavslöjaren.",al={"varför behövs en kraftkälla","vad används kraftkällan till","varför magma core"}},{q="Vem är Magma Lord Bokk?",a="Enligt ryktet en mäktig elementarvarelse med en Magma Core som hjärta, en värmekälla som aldrig sinar.",al={"vem är bokk","magma lord bokks bakgrund","var finns bokk"}},{q="Var i Burning Steppes kan Magma Lord Bokk hittas?",a="Enligt ryktet finns han i Burning Steppes, söder om Blackrock Mountain och väster om Pillar of Ash.",al={"bokks plats","var finns magma lord bokk","hitta magma lord bokk"}},{q="Var passar det här steget in i Mux arbete?",a="Det kommer efter Hunting for Ectoplasm, och därefter följer A Shifty Merchant.",al={"vad kommer före","uppdragskedjans ordning","what comes next"}}},fp="23,184,23.367.0,13.134.1,47.122.0,23.105.0,58.112.0,41.69.0"}
P.entries["quest:8928"] = {n="A Shifty Merchant",s="Mux Manascrambler har kärnan som behövs för att driva hans apparat och behöver nu en stav som kan leda kraften utan att smälta. Han träffade en gång en imp i Winterspring som sålde exotiska varor, och önskar att han hade köpt elementarstaven som var till salu. Du letar efter impen i en grotta vid ingången till Darkwhisper Gorge och köper Fel Elemental Rod.",h="Mux Manascrambler har kärnan som behövs för att driva hans apparat och behöver nu en stav som kan leda...",kw={"darkwhisper gorge","fel elemental rod","gadgetzan","imp","köpman","mux manascrambler","winterspring"},sec={{t="Impen i grottan",b="Efter A Portable Power Source tar Mux Manascrambler itu med nästa problem: en stav som kan leda kärnans kraft utan att smälta. Mux träffade en imp i Winterspring som sålde alla slags exotiska varor, och impens elementarstav hade passat perfekt. Mux ångrar bittert att han inte köpte den. Impen bor i en grotta vid ingången till Darkwhisper Gorge i södra Winterspring. Du hittar impen, köper Fel Elemental Rod och tar med den tillbaka till Mux i Gadgetzan. Mux insisterar på att impen bara får ta fyrtio guld, priset som impen uppgav för Mux."},{t="Staven kommer fram",b="Mux är förtjust i staven och säger att den passar perfekt. Sedan börjar han sätta ihop allt."}},faq={{q="Vem skickar dig efter staven?",a="Mux Manascrambler i Gadgetzan, i Tanaris.",al={"vem ger en skum köpman","uppdragsgivare en skum köpman"}},{q="Vad kom före det här steget?",a="Det följer efter A Portable Power Source.",al={"föregående uppdrag","förutsättningar en skum köpman"}},{q="Var hittar man impköpmannen?",a="I en grotta vid ingången till Darkwhisper Gorge, i södra Winterspring.",al={"var är impen","impens plats i darkwhisper gorge","var är köpmannen i winterspring"}},{q="Vilket föremål ska du köpa?",a="En Fel Elemental Rod.",al={"vilket föremål ska jag köpa","vad säljer impen"}},{q="Vad kostar staven?",a="Fyrtio guld är priset som impen uppgav för Mux, och Mux vill inte att du betalar mer.",al={"stavens kostnad","hur mycket guld för staven","impens pris"}},{q="Varför behöver Mux staven?",a="Kärnan ger apparaten tillräckligt med kraft, men Mux behöver fortfarande en stav som kan leda kraften utan att smälta.",al={"varför fel elemental rod","vad används staven till"}}},fp="17,300,19.453.0,15.106.1,28.67.0,27.37.0,36.92.0,35.40.0,27.65.0,27.102.0"}
P.entries["quest:893"] = {n="Weapons of Choice",s="I Camp Taurajo undersöker Tatternack Steelforge rapporter om ovanligt hållbara Razormane-vapen. Han skickar resande förbi Field of Giants för att hämta dem, så att Horde kan bedöma hotet.",h="I Camp Taurajo undersöker Tatternack Steelforge rapporter om ovanligt hållbara Razormane-vapen.",kw={"backstabber","barrens","kvillagevin","razormane","steelforge","tatternack","taurajo","stav","krigssköld"},ang={["faction:Horde"]="Camp Taurajo är utsatt vid den södra gränsen, så kunskap om Razormanes militära framsteg hjälper till att försvara Barrens handelsvägar.",["profession:Blacksmithing"]="För en smed visar dessa återtagna vapen hur en fiendes material formar dess beredskap vid gränsen.",["race:Orc"]="Som ork vet du att hedern kräver respekt för stridsstyrka. Tatternacks plikt gentemot Thrall innebär att inse när en fiende blir farlig."},sec={{t="En märklig utveckling",b="Razormane tillverkar ovanligt hållbara vapen i södra Barrens. De flesta quilboar avfärdas som råbarkade kämpar med verktyg av trä, ben och sten, så rapporterna har fångat Hordes uppmärksamhet. Tatternack Steelforge, en orksmed i Camp Taurajo, undersöker saken på order av Warchief Thrall. Han tvivlar på att quilboar behärskar riktigt metallarbete och vill få bevis på om de har lärt sig nya tekniker eller hittat bättre material."},{t="Razormanes vapen",b="Tatternack behöver vapen från olika delar av Razormanes arsenal för att studera deras hantverk. Söder om Field of Giants möter spejare Razormanes krigsläger och tar vapen från deras krigare. Razormane Stalkers bär på backstabber-dolkar, Razormane Seers svingar förkolnade stavar och ursinniga stormtrupper bär tunga krigssköldar. Varje föremål ger en inblick i de stridskonster och mystiska konster som ligger bakom Razormanes framryckning mot Hordes territorium."},{t="Fienden underskattades",b="Tatternack finner att de återtagna vapnen är betydligt bättre tillverkade och starkare än Horde väntat sig. Deras kvalitet visar att Horde har underskattat Razormane. Tatternack lägger smidet åt sidan för att studera materialen, och misstänker att ett yttre inflytande eller en nyupptäckt resurs hjälper deras krigsinsats."}},faq={{q="Vem är Tatternack Steelforge?",a="Tatternack Steelforge är en orksmed och rustningsmakare stationerad i Camp Taurajo i södra Barrens. På order av Warchief Thrall studerar han fiendens vapen och tillverkar utrustning åt de lokala styrkorna.",al={"tatternack steelforge","vem ger weapons of choice","smeden i taurajo"}},{q="Varför vill Tatternack ha kvillagevinernas vapen?",a="Rapporter säger att Razormane i söder har ovanligt hållbara vapen trots att de inte är kända för skickligt smide. Tatternack vill studera deras dolkar, stavar och sköldar för att lära sig hur de tillverkas och om de utgör ett större hot.",al={"varför samla kvillagevinvapen","orsak till weapons of choice","tatternacks motiv"}},{q="Var finns Razormane-kvillagevinen som uppdraget gäller?",a="Razormanes läger ligger längst söderut i Barrens, förbi Field of Giants och väster om vägen mot The Great Lift och Thousand Needles.",al={"var finns kvillagevinerna","plats för weapons of choice","var hittar man razormane"}},{q="Vilka kvillageviner bär de efterfrågade vapnen?",a="Razormane Stalkers bär Razormane Backstabber-dolkar, Razormane Seers svingar Charred Razormane Wands och Razormane Warfrenzies bär tåliga Razormane War Shields.",al={"vem släpper backstabber","vem släpper stav","vem släpper krigssköld"}},{q="Vad upptäcker Tatternack när han undersöker vapnen?",a="Tatternack finner vapnen anmärkningsvärt välgjorda, långt bättre än vad Horde väntat sig av quilboar. I uppföljaren, A New Ore Sample, undersöker han råmaterialen.",al={"vad upptäcker tatternack","resultat av weapons of choice","är kvillageviner smeder"}},{q="Varför oroar sig Horden över att kvillageviner tillverkar vapen?",a="Horde är beroende av starkt metallarbete och disciplinerade krigare för att hålla det vidsträckta Barrens mot de många lokala hoten. Om de talrika Razormane kan tillverka hållbara vapen av järn eller stål i stora mängder kan de överväldiga gränsposter som Camp Taurajo.",al={"varför spelar kvillagevinvapen roll","hur stort är kvillagevinhotet"}}},fx={["17648e33"]={q="Vilka ska du ge dig på i Weapons of Choice?",a="Du ska ge dig på Razormane quilboar som håller till i södra Barrens, söder om Field of Giants. Horde har länge betraktat dem som råa, primitiva asätare, men vissa grader bland dem, deras förföljare, siare och krigsrasare, har börjat använda oväntat hållbara och välgjorda vapen som hotar närliggande bosättningar.",al={"vilka är måltavlorna","vilka quilboar ska jag slåss mot","fiender i weapons of choice"}},["3f25a614"]={q="Vad ska Razormane Backstabber användas till?",a="Razormane Backstabber bärs av Razormane Stalkers. Tatternack Steelforge behöver den som exempel på stammens arbete med eggvapen. Han vill undersöka metallen och eggen för att avgöra om quilboar-smeder verkligen kan smida härdat stål.",al={"vad ska dolken användas till","razormane backstabbers syfte","varför samla in backstabbern"}},["5a3ff8c6"]={q="Vad ska Charred Razormane Wand användas till?",a="Charred Razormane Wand bärs av Razormane Seers och visar hur quilboar blandar enkla redskap med mystisk eller elementär kraft. Tatternack tänker granska hur den är byggd för att se hur stammen kanaliserar magi genom sina egentillverkade verktyg.",al={"syftet med den brända trollstaven","varför samla in charred razormane wand","vad gör tatternack med trollstaven"}},d1102a3e={q="Vad ska Razormane War Shield användas till?",a="Den här tunga skölden används av Razormane Warfrenzies i främsta ledet och ger Tatternack direkt inblick i quilboarens skyddande rustning. Genom att granska dess plåtar och förstärkningar kan han bedöma om deras hantverksmetoder utgör ett betydande hot mot Horde-krigare.",al={"razormane war shields syfte","varför samla in razormane-skölden","vad ska skölden användas till"}}},fp="17,179,21.402.0,26.446.0,25.307.1,29.198.0,42.240.0,55.156.0,42.164.0,47.172.1,62.262.0"}
P.entries["quest:894"] = {n="Samophlange",s="Vid en Venture Company-utpost i norra The Barrens vill Sputtervalve ha en anordning som kallas samophlange. Han skickar dig sydväst om The Sludge Fen för att hitta den.",h="Vid en Venture Company-utpost i norra The Barrens vill Sputtervalve ha en anordning som kallas samophlange.",kw={"the barrens","kontrollpanel","goblinteknik","samophlange","the sludge fen","sputtervalve","venture company"},ang={["faction:Horde"]="Som medlem av Horde har du skäl att motarbeta Venture Companys verksamhet. Dess exploatering och kemiska utsläpp hotar The Barrens, och dess anläggningar utsätter landet du försvarar för fara.",["profession:Engineering"]="Som ingenjör kan du förstå Sputtervalves intresse för en rivaliserande aktörs konstruktioner. Hans jakt visar hur hårt gobliner konkurrerar om tekniska upptäckter."},sec={{t="En märklig apparat",b="I norra The Barrens kan Sputtervalve inte förklara vad Venture Company bygger. Gobliningenjören och mekanikern arbetar i Ratchet, medan rivalföretaget experimenterar sydväst om The Sludge Fen. Dess folk kallar en anordning för en samophlange. Sputtervalve känner inte till dess syfte eller värde, men vill studera konstruktionen innan konkurrenterna kan tjäna på den."},{t="Infiltrera anläggningen",b="Venture Company bevakar sin forskningsplats med beväpnade uppsyningsmän, skogsskövlare och maskiner. Sputtervalve ger dig en uppsnappad bruksanvisning som hjälp för att stänga av riggen säkert. Vid den centrala kontrollstationen hittar du en låst konsol med spakar, lampor och mätare. Tre kontrollventiler håller riggens tryck i schack."}},faq={{q="Vad är en samophlange?",a="Sputtervalve vet inte exakt vad samophlangen är eller gör. Venture Company tillverkade den som en experimentell mekanisk komponent på sin plats sydväst om The Sludge Fen.",al={"vad är en samophlange","samophlangens syfte","vad gör en samophlange"}},{q="Vem är Sputtervalve?",a="Sputtervalve är en gobliningenjör och mekaniker i Ratchet. Han är intresserad av Venture Companys affärshemligheter och anlitar äventyrare för att sabotera deras verksamhet och lägga beslag på deras uppfinningar.",al={"vem är sputtervalve","sputtervalves plats","uppdragsgivare"}},{q="Var finns kontrollpanelen?",a="Kontrollkonsolen finns inne på Venture Companys forskningsplats norr om The Crossroads och sydväst om det förorenade Sludge Fen i The Barrens.",al={"kontrollpanelens plats","var finns kontrollpanelen","var hittar man samophlangen"}},{q="Varför är Venture Company i The Barrens?",a="Venture Company är en kartell som exploaterar Kalimdors naturresurser för vinst. I The Barrens röjer dess arbetare skog, borrar efter olja och bygger experimentella riggar nära Sludge Fen.",al={"venture co i the barrens","varför är venture co här","verksamhet vid sludge fen"}},{q="Hur kopplar du säkert bort samophlangen?",a="Konsolen har tre öppna kontrollventiler och ett nyckelhål. Du använder Sputtervalves återfunna manual för att kringgå säkerhetsspärrarna och manövrera ventilerna så att modulen lossnar.",al={"hur använder man kontrollpanelen","control console operating manual","instruktioner i bruksanvisningen"}},{q="Arbetar Sputtervalve för Venture Company?",a="Nej. Sputtervalve arbetar oberoende av Venture Company och försöker stjäla företagets ingenjörsupptäckter för att kunna undersöka dem.",al={"tillhör sputtervalve venture co","sputtervalves fraktion"}}},fx={["122be8ea"]={q="Varför vill Sputtervalve ha samophlangen?",a="Sputtervalve drivs av yrkesmässig nyfikenhet och goblinernas uppfinningsrikedom. Han har upptäckt att Venture Company har inrättat en hemlighetsfull forskningsanläggning nära Sludge Fen för att experimentera med en märklig apparat som kallas samophlange. Han vet inte ens vad en sådan apparat är eller gör, men är fast besluten att lägga beslag på den och själv plocka isär den för att avslöja dess tekniska hemligheter.",al={"varför vill sputtervalve att det här görs","sputtervalves motiv","varför hämta samophlangen"}}},fp="11,156,22.366.0,20.326.0,22.176.0,20.164.0,37.144.0,42.193.0,44.171.0,47.130.0"}
P.entries["quest:895"] = {n="WANTED: Baron Longshore",s="På Ratchets kajer sätter överingenjör Gazlowe upp en belöning för baron Longshore. Piratkaptenen kommer från Gilneas och för befäl över Southsea Freebooters fartyg. Hans närvaro längs The Merchant Coast hotar de goblinska handelsfartygen i hela regionen.",h="På Ratchets kajer sätter överingenjör Gazlowe upp en belöning för baron Longshore.",kw={"baron longshore","gazlowe","gilneas","heedless","the merchant coast","belöning för pirat","ratchet","southsea freebooters"},ang={["faction:Alliance"]="Som medlem av Alliansen förlitar du dig på neutral sjöfart mellan Kalimdor och Eastern Kingdoms, som Longshores piratverksamhet stör.",["faction:Horde"]="Som medlem av horden tjänar du på att Southsea Freebooters nära Ratchet rensas ut och att hamnen hålls öppen för hordens förnödenheter på väg in i The Barrens.",["race:Human"]="Som människa ser du hur långt desertörer och utstötta från Eastern Kingdoms har spridits över haven, när en gilneansk baron för befäl över mördare på Kalimdor."},sec={{t="Piratverksamhet längs The Merchant Coast",b="Söder om Ratchet har Southsea Freebooters befästa läger längs The Merchant Coast. Deras pirater trakasserar handelsfartyg och stör sjölederna som Steamwheedle Cartel förlitar sig på mellan Ratchet, Booty Bay och platser längre bort. Under kaptener som baron Longshore tömmer räderna den lokala goblinska förvaltningens resurser och hotar handeln längs kusten."},{t="En kapten från Gilneas",b="Baron Longshore kommer från Gilneas, det isolerade människoriket på andra sidan havet. På Kalimdor för han befäl över piratskeppet Heedless och leder besättningar i land strax norr om Northwatch Hold. Överingenjör Gazlowe svarar med en belöning och efterlyser Longshores lätt igenkännliga huvud."}},faq={{q="Vem är Baron Longshore?",a="Baron Longshore är en piratkapten från Gilneas som för befäl över Heedless åt Southsea Freebooters. Han plundrar fartygslederna längs kusten söder om Ratchet.",al={"baron longshore","vem är longshore","kapten longshore"}},{q="Varför vill Gazlowe se honom död?",a="Longshores piratverksamhet hotar handelsfartygen från Ratchet. Gazlowe har utfäst en belöning för hans huvud för att skydda handeln och Steamwheedles vinster.",al={"varför döda longshore","gazlowes skäl till belöningen","varför är longshore efterlyst"}},{q="Var kan Baron Longshore hittas?",a="Baron Longshore brukar hålla till i Southsea Freebooters läger längs The Merchant Coast, söder om Ratchet och strax norr om Northwatch Hold.",al={"longshores plats","var finns longshore","baron longshores tillhåll"}},{q="Vilket skepp är Baron Longshore kapten på?",a="Baron Longshore för befäl över Heedless, ett fruktat piratskepp på öppet hav kring The Merchant Coast.",al={"longshores skepp","namnet på longshores båt","skeppet heedless"}},{q="Är Baron Longshore en adelsman i Alliansen?",a="Baron Longshore bär titeln baron och kommer från Gilneas, men han leder Southsea Freebooters som en laglös kapare utan band till Alliansens nuvarande ledning.",al={"är longshore med i alliansen","adlig pirat från gilneas","longshore gilneas"}},{q="Var finns efterlysningsaffischen?",a="Efterlysningen hänger på anslagstavlorna nära banken i hamnstaden Ratchet.",al={"var finns efterlysningsaffischen","longshores affischplats","hur startar man longshore-uppdraget"}}},fx={["65a73854"]={q="Vad ska Baron Longshore's Head användas till?",a="Gazlowes efterlysning kräver uttryckligen att den ökände piratkaptenens kvarlevor går att identifiera innan belöningen betalas ut. Om man skiljer Baron Longshores huvud från kroppen får man obestridliga fysiska bevis på att kaptenen på Heedless har gått under och inte längre kommer att ge sig på Ratchets handelsfartyg.",al={"baron longshores huvud","varför ta baron longshores huvud","bevis på att baron longshore dödats"}}},fp="23,238,28.358.0,22.274.0,23.162.0,31.145.0,35.129.0,39.103.0,37.176.0,35.75.0"}
P.entries["quest:896"] = {n="Miner's Fortune",s="Wharfmaster Dizzywig har hört talas om en smaragd stor som en knytnäve vid Venture Companys Boulder Lode Mine. Han anlitar dig för att ta Cats Eye Emerald från gruvans arbetsledare och dela på vinsten.",h="Wharfmaster Dizzywig har hört talas om en smaragd stor som en knytnäve vid Venture Companys Boulder Lode Mine.",kw={"boulder lode mine","cats eye emerald","dizzywig","enforcer","overseer","ratchet","the sludge fen","venture co"},ang={["class:Rogue"]="Som skurk vet du hur man smyger sig in i ett fientligt läger och stjäl en bevakad ädelsten från giriga arbetsledare.",["faction:Horde"]="Som medlem i Horde slår du till mot Venture Companys chefer i Boulder Lode Mine och stör en industrikartell som tränger in på Horde-kontrollerad mark i Barrens.",["profession:Mining"]="Som gruvarbetare kan du känna igen hur sällsynt en hel smaragd stor som en knytnäve är. Ädelstenar av den storleken överlever nästan aldrig utgrävningen utan att spricka eller gå sönder."},sec={{t="Ögon på kajen",b="Wharfmaster Dizzywig hör köpmännen som passerar genom Ratchets hamn längs rutterna mellan Ratchet och Booty Bay. Han får höra om en väldig ädelsten som hittats djupt inne i Boulder Lode Mine. Venture Company utarmar norra Barrens för egen vinning, så få lär ställa frågor om dess finaste fynd på senare tid försvinner."},{t="En andel av fyndet",b="Nordost om The Sludge Fen fyller arbetare Boulder Lode Mines klippiga gruvschakt. Venture Co. Overseers och Enforcers har tagit Cats Eye Emerald, och en vanlig gruvarbetare kan inte göra anspråk på ett så sällsynt fynd. Du måste möta de beväpnade cheferna, säkra stenen och ta den till Dizzywig. Han kan bedöma dess värde mot marknaden i Undermine."}},faq={{q="Vem är Wharfmaster Dizzywig?",a="Wharfmaster Dizzywig är en goblinsk hamntjänsteman i Ratchet. Han ansvarar för last och passagerare som reser till och från Booty Bay till sjöss, och handlar med skvaller, rykten och köpmannainformation.",al={"dizzywig","vem ger gruvarbetarna en förmögenhet","ratchet kajmästare"}},{q="Var ligger Boulder Lode Mine?",a="Boulder Lode Mine ligger i norra Barrens, bland kullarna strax nordost om The Sludge Fens oljeanläggning.",al={"boulder lode mine plats","var finns smaragden","venture co gruva barrens"}},{q="Vem har Cats Eye Emerald vid gruvan?",a="Venture Co. Overseers och Venture Co. Enforcers håller Cats Eye Emerald. De leder och bevakar gruvarbetet i Boulder Lode Mine.",al={"vem släpper cats eye emerald","cats eye emerald byte","var finns cats eye emerald"}},{q="Vad har Venture Company för intresse i The Barrens?",a="Venture Company är ett goblinskt handelssyndikat som snabbt utvinner resurser. I norra Barrens borrar det vid The Sludge Fen och gräver i Boulder Lode Mine efter timmer, olja och mineraler, med liten hänsyn till den lokala ekologin.",al={"varför är venture co i barrens","venture company barrens"}},{q="Varför nämner Dizzywig Undermine?",a="Undermine är kartellernas underjordiska östad och goblinernas uråldriga huvudstad. Dess marknader sätter priserna på dyrbara ädelstenar och sällsynta varor i hela Azeroth.",al={"omnämnande av undermine","ädelstenspriser i undermine"}},{q="Delar Dizzywig verkligen på vinsten?",a="Dizzywig lovar dig halva det uppskattade marknadsvärdet i Undermine när du levererar Cats Eye Emerald, och han håller sin del av avtalet.",al={"delar dizzywig vinsten lika","dizzywigs utbetalning"}}},fx={b052118f={q="Varför vill Wharfmaster Dizzywig ha Cats Eye Emerald?",a="Som hamnmästare i Ratchet håller Dizzywig koll på handeln mellan Kalimdor och Booty Bay och lyssnar efter lukrativa möjligheter. När han fick höra att en enorm ädelsten grävts fram i Venture Companys Boulder Lode Mine såg han en chans att berika sig själv. Genom att anlita en oberoende legosoldat för att smyga in och stjäla bytet kan han sälja det till välbärgade privata köpare och stoppa en förmögenhet i egen ficka utan att blanda in hamnmyndigheterna.",al={"varför vill dizzywig ha smaragden","dizzywigs motiv med smaragden","varför stjäla cats eye emerald"}},["0186bc21"]={q="Vad ska Cats Eye Emerald användas till?",a="Cats Eye Emerald är en ovanligt sällsynt ädelsten stor som en knytnäve. Dizzywigs plan nämner ingen inneboende magisk kraft. Värdet ligger helt i dess storlek, renhet och astronomiska marknadsvärde bland ädelstenshandlare och samlare på platser som Undermine.",al={"cats eye emeralds användning","vad är cats eye emerald","varför är smaragden värdefull"}},bd4101f7={q="Vem ska du ge dig på i Boulder Lode Mine?",a="Du ska ge dig in i Boulder Lode Mine och ge dig på Venture Company, ett skrupelfritt gruvkonglomerat av gobliner som aggressivt utvinner resurser i norra Barrens. Deras Enforcers och Overseers vaktar gruvplatsen, leder arbetslagen och har tagit den enastående smaragd som gruvarbetarna hittade.",al={"vem har smaragden","venture company i boulder lode mine","boulder lode mines uppsyningsmän"}}},fp="15,155,17.292.0,17.323.0,28.171.0,39.110.0,43.138.0,54.232.0,38.151.0,41.125.1"}
P.entries["quest:897"] = {n="The Harvester",s="Ett avhugget huvud som hittas i södra Barrens för med sig The Harvesters märkliga närvaro till Camp Taurajo. Jorn Skyseer undersöker kvarlevorna, och varel­sens intrång väcker oro för landets andliga och ekologiska balans.",h="Ett avhugget huvud som hittas i södra Barrens för med sig The Harvesters märkliga närvaro till Camp Taurajo.",kw={"the barrens","camp taurajo","the harvester","the harvesters huvud","insektsliknande","jorn skyseer","silithid"},ang={["class:Druid"]="Som druid kan du se dessa främmande grävvarelsers fördärvande, parasitiska natur när de invaderar savannen.",["class:Shaman"]="Som shaman förstår du Jorn Skyseers frustration: anden har flytt från huvudet, vilket hindrar honom från att tala med elementarkrafterna och upptäcka varelsens sanna ursprung.",["faction:Horde"]="Som medlem av Horde vet du att Camp Taurajo vaktar Barrens södra gränstrakter. Ett invasivt rovdjur i de omgivande höjderna hotar områdets säkerhet.",["race:Tauren"]="Som Shu'halo vet du att Jordmodern harmoniska ordning är av största vikt. En varelse som trotsar naturens ordning vittnar om djup andlig disharmoni."},sec={{t="En onaturlig inkräktare",b="I södra Barrens hittar du det avhuggna huvudet från en silithid som kallas Harvester. Lejon, rovfåglar och kodos strövar omkring på dessa gräsmarker, men denna pansrade insektsvarelse skiljer sig från det inhemska djurlivet. Dess närvaro tyder på att en främmande ekologi har nått Kalimdors öppna slätter."},{t="Jorn Skyseers föraning",b="I Camp Taurajo undersöker taurenmystikern Jorn Skyseer Harvesters huvud. Varelsens ande har redan flytt, så Jorn kan inte utröna dess ursprung. Han känner igen kvarlevorna som ett allvarligt hot och fruktar att dess intrång kan förebåda en mörk framtid för Horde. Mörkare mysterier håller på att växa fram under sanden."}},faq={{q="Vad är The Harvester?",a="Harvester är en stor silithidinsekt som stryker omkring i södra Barrens. Dess pansrade kropp skiljer sig från regionens inhemska djurliv.",al={"vem är the harvester","vad är the harvester för insekt","varelsen the harvester"}},{q="Vem är Jorn Skyseer?",a="Jorn Skyseer är en respekterad taurenäldste och andlig vägledare i Camp Taurajo. Han vakar över slätternas andliga hälsa och ger råd när landets balans hotas.",al={"jorn skyseer","vem lämnar man in uppdraget till","jorn i taurajo"}},{q="Var kommer The Harvester ifrån?",a="Jorn Skyseer kan inte utröna Harvesters exakta ursprung från dess avhuggna huvud. Varelsen kommer från silithidernas bon som sprider sig norrut från de djupa öknarna i söder.",al={"var kommer silithider ifrån","the harvesters ursprung","silithidernas ursprung"}},{q="Varför oroar varelsen Jorn Skyseer?",a="Harvesters onaturliga form och främmande ande oroar Jorn djupt. Han känner att dess närvaro i Barrens inte är någon slump, utan en varning om ett onaturligt hot som närmar sig.",al={"varför är jorn orolig","jorn skyseers reaktion","dyster framtid"}},{q="Hur startar du det här uppdraget?",a="Du börjar med att döda den sällsynta silithiden Harvester i södra Barrens och ta dess avhuggna huvud. Sedan söker du de äldstes vägledning i Camp Taurajo.",al={"hur får man uppdraget","the harvesters huvudbyte","starta the harvester"}},{q="Vad säger Jorn att du ska göra härnäst?",a="Jorn föreslår inget omedelbart motangrepp. Han tror att Horde måste förbereda sig och hålla vakt medan mysteriet kring silithidernas framryckning långsamt nystas upp.",al={"nästa uppdrag","vad händer efter the harvesters huvud","jorns nästa steg"}}},fx={["5f65deeb"]={q="Varför ska Harvester's Head tas till Jorn Skyseer?",a="Det avhuggna huvudet tillhör ett bisarrt, insektsliknande vidunder som är helt främmande för Barrens naturliga balans. Den som ser dess onaturliga skepnad kan känna att något djupt felaktigt har trängt in på slätterna. Att ta det direkt till Jorn Skyseer, en vis tauren-siare som är lyhörd för landet och andarna vid Camp Taurajo, är ett försök att förstå vad den skräckinjagande varelsen var och vilket hot den kan utgöra mot riket.",al={"varför ta huvudet till camp taurajo","varför visa harvester-huvudet för jorn","harvester-huvudets syfte"}}},fp="13,216,21.268.0,26.249.1,22.132.0,20.185.0,35.171.0,43.181.0,28.166.0,35.151.0"}
P.entries["quest:898"] = {n="Free From the Hold",s="Gilthares Firebough hålls fången i Northwatch Hold efter att alliansstyrkor sänkt hans skepp utanför The Barrens kust. Alven, som arbetar på däck, vill nå sin kapten i Ratchet.",h="Gilthares Firebough hålls fången i Northwatch Hold efter att alliansstyrkor sänkt hans skepp utanför The...",kw={"booty bay","captain brightsun","eskort","gilthares firebough","sprit","northwatch hold","kapare","ratchet","smugglare","theramore"},ang={["faction:Horde"]="Som medlem av Horden kan du slå mot Theramores fäste vid The Barrens kust genom att befria en smugglare som hålls fången i Northwatch Hold."},sec={{t="Fängslad i Northwatch",b="Gilthares Firebough hålls fången i fängelsehålorna i Northwatch Hold. Theramore använder fästningen som militärt brohuvud vid The Barrens kust, där garnisonen håller utkik efter hot. Gilthares var ombord på ett skepp som fraktade hembränt längs handelsrutten mellan Ratchet och Booty Bay när alliansstyrkor besköt det och sänkte det. Han var den enda som överlevde förlisningen. Soldaterna förde honom till Northwatch och anklagade honom för att vara en fiendeagent som konspirerade mot Alliansen."},{t="En smugglare på flykt",b="Gilthares säger att han bara är en däcksman som fraktade olaglig sprit. Med hjälp av hordstyrkor kämpar han sig ut ur Northwatch Hold och flyr norrut längs stranden mot Ratchet. Captain Thalo'thas Brightsun välkomnar honom tillbaka till besättningen på Thalo'dan Privateers."}},faq={{q="Vem är Gilthares Firebough?",a="Gilthares Firebough är en alv som arbetar på däck och seglar under Captain Thalo'thas Brightsun. Han tjänstgjorde ombord på ett transportfartyg som fraktade hembränt mellan Ratchet och Booty Bay innan Theramores trupper sänkte fartyget och fängslade honom.",al={"gilthares","vem är gilthares firebough","vem är fången i northwatch hold"}},{q="Varför greps Gilthares av Theramores styrkor?",a="Allianssoldater vid Northwatch Hold stoppade Gilthares skepp utanför The Barrens kust och sprängde det i havet. De var misstänksamma mot sjöfarten nära sitt fäste och dömde honom som en agent som var fientlig mot Alliansen.",al={"varför grep theramore honom","varför sitter gilthares i fängelse","varför sänktes skeppet"}},{q="Vart beger sig Gilthares när han blir fri?",a="Gilthares flyr norrut från Northwatch Hold längs The Barrens östra kust till Ratchet. Där återförenas han med Captain Brightsun vid hamnen.",al={"vart ska gilthares eskorteras","gilthares destination","vart går eskortuppdraget"}},{q="Vilka är Thalo'dan Privateers?",a="Thalo'dan Privateers är en besättning till sjöss, ledd av Captain Thalo'thas Brightsun och med bas i Ratchet. De fraktar varor och smugglar olagligt hembränt över havet mellan Kalimdor och Eastern Kingdoms.",al={"thalodan privateers","captain brightsuns besättning","vem leder brightsun"}},{q="Varför angriper Northwatch Hold civila fartyg eller smugglarskepp?",a="Northwatch Hold är Theramores fästning i The Barrens, mellan hordterritorium och viktiga sjöleder. Befälhavarnas paranoia och strikta militärorder får dem att betrakta nästan alla skepp som inte tillhör Alliansen som en hordoperation eller ett pirathot.",al={"varför är northwatch fientligt","theramores aggression i the barrens","northwatch holds syfte"}},{q="Vilken last bar det sjunkna skeppet?",a="Det sjunkna fartyget fraktade olagligt hembränt för distribution mellan Ratchet och Booty Bay, inte vapen eller militär utrustning.",al={"vad fanns på skeppet","gilthares last","vad transporterade de"}}},fx={["6c76d4e5"]={q="Varför vill Gilthares Firebough fly från Northwatch Hold?",a="Gilthares är den enda överlevande från ett sjunket smugglarskepp. Överdrivet nitiska Theramore-soldater i Northwatch Hold har stämplat honom som fiende och hot mot Alliansen. Han sitter fängslad i deras fängelsehålor och riskerar livet om ingen fritar honom så att han tryggt kan återvända till Ratchet och Captain Thalo'thas Brightsun.",al={"gilthares motiv","varför fly från northwatch hold","varför hjälpa gilthares firebough"}},["153b57ec"]={q="Varför behöver Gilthares Firebough din hjälp för att fly?",a="Gilthares är bara en däcksman, inlåst djupt inne i en fientlig fästning full av fientliga Theramore-trupper. Hela hans besättning gick förlorad när deras skepp förstördes. Han har inga vapen, allierade eller möjlighet att slå sig förbi vakterna utan en duglig äventyrare som röjer en väg till friheten.",al={"varför behöver gilthares hjälp","varför kan gilthares inte fly ensam","varför jag för gilthares"}}},fp="18,173,24.446.0,19.277.0,27.207.0,47.213.0,35.137.1,33.206.0,60.236.0,40.125.0"}
P.entries["quest:899"] = {n="Consumed by Hatred",s="Mankrik gör sin sorg vid The Crossroads till ett fälttåg mot quilboar från Bristleback. Orchen skildes från sin fru i ett våldsamt bakhåll, och nu uppmanar han Hordens resenärer att döda varelserna och ta med deras betar tillbaka.",h="Mankrik gör sin sorg vid The Crossroads till ett fälttåg mot quilboar från Bristleback.",kw={"the barrens","bristleback","consumed by hatred","the crossroads","mankrik","quilboar","taurajo","betar"},ang={["class:Warrior"]="Som krigare vet du att ett sår i hjärtat inte alltid går att förbinda. Mankrik söker botemedel med stål mot stål över de taggiga slätterna.",["faction:Horde"]="Som medlem av Horden möter du quilboarhot mot färdvägarna mellan Durotar, Mulgore och södra The Barrens. Mankriks strid skyddar också Hordens territorium.",["race:Orc"]="Som ork kanske du känner igen Mankriks sorg och hans drivkraft att hämnas fallna fränder i orkernas hederstraditioner och det hårda arbetet med att skapa ett hem i Kalimdor."},sec={{t="En makes hämnd",b="Mankrik bär på sorgen efter ett quilboar-bakhåll som lämnade honom slagen och hans fru försvunnen. Vid The Crossroads blickar han ut över den torra horisonten och törstar fortfarande efter Bristlebacks blod, trots att han själv dödat många. Han ber andra resenärer i Horden att hjälpa honom fortsätta striden."},{t="Bristlebacks betar",b="Mankrik kräver sextio betar från Bristleback-quilboar. Var och en är ett mått på det lidande han ger tillbaka till varelserna som slet sönder hans liv. Troféerna kan inte läka hans sorg eller stilla hans hämndbegär, men att se Bristlebacks blöda ger den sårade krigaren en kort, bitter tillfredsställelse."}},faq={{q="Varför vill Mankrik ha sextio quilboar-betar?",a="Mankrik vill ha sextio betar eftersom sorg och vrede driver honom efter att ett quilboar-bakhåll skilde honom från hans fru. Räkningen kräver stora förluster bland Bristlebacks, och deras lidande ger honom en smula tröst.",al={"varför sextio betar","mankriks betuppdrag","varför så många betar"}},{q="Var utspelar sig uppdraget?",a="Mankrik ber om betarna vid The Crossroads i centrala The Barrens. Bristleback-quilboar lever i närliggande buskmarker och taggiga fästen.",al={"var finns consumed by hatred","platsen för consumed by hatred"}},{q="Får Mankrik sin hämnd när han lämnar in betarna?",a="Nej. Mankriks hämndbegär finns kvar, även om quilboarernas förluster lockar fram ett bistert leende och får honom att känna att de äntligen har fått känna hans smärta.",al={"slutar mankrik hata quilboar","slutet på mankriks uppdrag"}},{q="Varför nämner Mankrik Camp Taurajo?",a="Mankrik undrar om stridens utgång och hans sökande kunde ha blivit annorlunda om han efter bakhållet hade flytt söderut mot Camp Taurajo i stället för norrut till The Crossroads.",al={"varför taurajo","camp taurajo mankrik"}},{q="Vilka är Bristlebacks?",a="Bristlebacks är en aggressiv quilboar-stam som hör hemma i The Barrens. De är ytterst revirhävdande och främlingsfientliga, drabbar ständigt samman med Horden och anfaller resenärer från taggiga läger över slätterna.",al={"vad är bristlebacks","bristleback-stammen"}},{q="Har uppdraget något samband med att hitta Mankriks hustru?",a="Ja. Mankriks hat började med bakhållet som övermannade honom och hans fru. Medan du söker på slätterna efter hennes öde i Lost in Battle är hans krav på betar en uppmaning till hämnd på dem som anföll henne.",al={"sambandet med lost in battle","uppdraget om mankriks hustru"}}},fx={["69927be8"]={q="Varför behöver Mankrik din hjälp med att döda Bristlebacks i stället för att göra det själv?",a="Mankrik utkämpar redan ett enmanskrig och dödar varje quilboar han stöter på från soluppgång till solnedgång. Men hans sorg och vrede är för stora för en enda klinga. Han är kvar vid Crossroads medan han spanar mot horisonten och plågas av ovissheten, så han anlitar dugliga resenärer för att utöka slakten långt bortom vad han själv kan nå.",al={"varför jag för mankrik","varför behöver mankrik hjälp","varför kan inte mankrik jaga quilboar själv"}}},fp="18,220,21.290.0,24.286.0,43.200.0,33.137.0,52.132.0,38.167.0,25.231.0,44.197.0"}
P.entries["quest:9"] = {n="The Killing Fields",s="The Killing Fields är ett Alliance-uppdrag som Farmer Saldean erbjuder i Westfall. Saldean ber äventyrare förstöra de förrymda Harvest Watchers som härjar bland hans grödor och på grannarnas åkrar. Uppdraget visar hur det lokala jordbruket kollapsar när Defias Brotherhood stör ordningen.",h="The Killing Fields är ett Alliance-uppdrag som Farmer Saldean erbjuder i Westfall.",kw={"urverk","defias","farmer saldean","harvest watchers","the killing fields","saldean's farm","fågelskrämmor","westfall"},ang={["faction:Alliance"]="För Alliance-resenärer är hjälpen till Saldean ett direkt sätt att skydda en av de få matförråd som finns kvar i ett område som Stormwinds krona har övergett.",["profession:Engineering"]="Ingenjörer känner igen Harvest Watchers som automatiserade urverksunderverk som löpt amok utan ordentligt underhåll."},sec={{t="En hårt ansatt gård",b="Medan många bönder i Westfall övergav sina marker när banditer och laglösa drog genom trakten, bestämde sig Farmer Saldean och hans familj för att stå på sig. Tyvärr är kringströvande tjuvar inte det enda hotet mot Saldeans gård. De mekaniska Harvest Watchers, som skulle sköta och skydda säden, har löpt amok. De patrullerar fårorna och angriper alla som kommer nära."},{t="Rensa åkrarna",b="För att hålla gården igång ber Saldean förbipasserande resenärer att montera ned tjugo fientliga automater på hans åkrar och närliggande marker. När dessa konstruktioner röjs undan får Saldeans skörd en tillfällig frist och en sällsynt strimma hopp lever kvar om att Westfalls kornbod en dag kan återtas."}},faq={{q="Vem erbjuder uppdraget The Killing Fields?",a="Farmer Saldean ger uppdraget från Saldean's Farm, som ligger längs vägen i centrala Westfall.",al={"uppdragsgivare the killing fields","vem ger the killing fields","saldeans uppdrag"}},{q="Vad är Harvest Watchers?",a="Harvest Watchers är urverksdrivna fågelskrämmor som byggts för att sköta grödor och skydda åkrar från skadedjur. Efter oroligheterna och övergivandet av Westfall lämnades många av dessa mekaniska konstruktioner utan tillsyn eller programmerades om. Nu vänder de sig aggressivt mot just de bönder de skulle tjäna.",al={"vad är harvest watchers","harvest watchers bakgrund","mekaniska fågelskrämmor westfall"}},{q="Varför har Farmer Saldean inte flytt från Westfall som de andra?",a="Till skillnad från grannarna som övergav sina gårdar åt tjuvar och rövare vägrar Saldean ge upp sin försörjning. Han håller envist fast vid sin mark och tar hjälp av inhyrda äventyrare för att hålla den förrymda maskinparken borta.",al={"varför är saldean kvar här","farmer saldeans bakgrund","saldean stannar kvar"}},{q="Vad ska man göra i The Killing Fields?",a="Du ska förstöra tjugo Harvest Watchers som strövar omkring på Saldeans åkrar och de övergivna gårdarna i närheten.",al={"målet med the killing fields","hur många harvest watchers","vad ska dödas i the killing fields"}},{q="Vilka är ”tjuvarna” som Saldean nämner?",a="Saldean syftar på tjuvar och rövare som löst organiserats under Defias Brotherhood. Deras räder och utpressning drev bort de flesta gårdsägarna från sina marker.",al={"vilka är tjuvarna","saldeans tjuvar","vem drev bort bönderna från westfall"}},{q="Löser det här uppdraget Westfalls jordbruksproblem?",a="När de tjugo Harvest Watchers förstörs får Saldeans gård en omedelbar lättnad, men det större bandithotet och de trasiga maskinerna i resten av trakten finns kvar.",al={"återhämtar sig westfall","slutet på the killing fields","hur det går för saldean"}}},fx={a141c1eb={q="Varför vill Farmer Saldean att Harvest Watchers dödas?",a="Farmer Saldean är en av få jordbrukare som vägrar överge sin mark trots Westfalls sammanbrott. Fälten som en gång försörjde Stormwind har förfallit, vuxit igen och invaderats av bortsprungna mekaniska Harvest Watchers. Saldean vill att dessa herrelösa automater förstörs så att han och de andra som är kvar kan få en chans att återta jorden och se Westfall blomstra igen.",al={"varför döda harvest watchers","saldeans motiv i killing fields","farmer saldeans skäl"}},["05cf05c3"]={q="Varför behöver Farmer Saldean en äventyrare i stället för att ta hand om Harvest Watchers själv?",a="Saldean är bara en vanlig bonde som försöker skydda sitt hem och sin familj, utan kungliga vakter eller soldater som kan hjälpa till. Stormwinds militära närvaro i Westfall har minskat, så de lokala bönderna står helt försvarslösa mot beväpnade tjuvar och dödliga, felande jordbruksmaskiner. Att möta tjugo Harvest Watchers ensam vore självmord, så en beväpnad äventyrare är hans enda hopp.",al={"varför kan inte saldean göra det","varför fråga mig om killing fields","varför behöver saldean hjälp"}}},fp="18,223,23.296.0,17.264.0,40.97.0,26.239.0,57.204.0,46.110.0,39.153.0,59.157.0"}
P.entries["quest:90"] = {n="Seasoned Wolf Kabobs",s="Seasoned Wolf Kabobs är ett kulinariskt uppdrag för Alliansen som Chef Grual ger på Scarlet Raven Tavern i Darkshire. Grual vill laga sin signaturrätt och ber äventyrare jaga vilda vargar i Duskwood för att få köttet, medan kryddörterna levereras från Stormwind City. Uppdraget visar vardagens utmaningar och påhittighet som krävs för att hålla en belägrad by med mat.",h="Seasoned Wolf Kabobs är ett kulinariskt uppdrag för Alliansen som Chef Grual ger på Scarlet Raven Tavern i...",kw={"chef grual","darkshire","duskwood","lean wolf flank","scarlet raven tavern","stormwind","wolf kabobs"},ang={["class:Hunter"]="Att spåra upp Duskwoods glupska vargflockar kräver klassiska spårnings- och gallringsfärdigheter. På så vis skyddar du byn och håller tavernans skafferi fyllt.",["faction:Alliance"]="Leveransen mellan Darkshire och Stormwind visar hur isolerade bosättningar i kungariket förlitar sig på huvudstadens marknader även när militära garnisoner uteblir.",["profession:Cooking"]="Chef Gruals recept lär äventyrare hur jägare i vildmarken tar vara på segt rovdjurskött och döljer dess vilda smak med förfinade kryddor från staden."},sec={{t="En rätt för Darkshire",b="Darkshire är en isolerad bosättning omgiven av Duskwoods krypande fasor, där handelskaravaner sällan färdas och det vanliga jordbruket har kollapsat helt. Trots det ständiga mörkret och de odöda som lurar behöver stadens invånare fortfarande mat. Chef Grual, som styr köket på Scarlet Raven Tavern, tar vara på skogens farliga djur och gör rejäla spett av vilt vargkött. Eftersom den lokala skogen och jorden inte kan ge näring åt känsliga grödor förlitar sig Grual på särskilda kryddor från huvudstaden för att göra det smakrika skogsköttet aptitligt."},{t="En leverans från Stormwind",b="För att fullborda Gruals recept behöver resenärer bara skaffa magra stycken från de våldsamma vargar som stryker omkring i Duskwood. Grual har just fått sin senaste leverans av Stormwind Seasoning Herbs, så köttet är det enda han saknar. Leveransen visar Darkshires bräckliga koppling till det större kungariket: det kungliga militära stödet har minskat, men småskaliga samhällsband och försörjningslinjer mellan stadens köpmän och avlägsna byar nätt och jämnt består."}},faq={{q="Vem är Chef Grual?",a="Chef Grual är byns kock på Scarlet Raven Tavern i Darkshire. Han ser till att gäster, lokalbor och Night Watch-medlemmar får mat och lagar rejäla måltider av allt vilt som går att jaga i skogarna omkring.",al={"chef grual","grual darkshire","vem ger seasoned wolf kabobs"}},{q="Var får du tag på Stormwind Seasoning Herbs?",a="Du behöver inte hämta dem. Chef Grual har just fått sin senaste leverans av Stormwind Seasoning Herbs, så det enda han behöver från dig är 10 Lean Wolf Flanks.",al={"stormwind örter plats","var finns kryddörter"}},{q="Var hittar man vargarna som ger vargköttet?",a="Vilda vargar strövar genom Duskwoods mörka skogar och jagar särskilt i dungarna och längs stigarna strax utanför Darkshire. Alla lokala vargar ger det magra kött som Chef Grual behöver.",al={"lean wolf flank plats","wolf flanks duskwood","var jagar man vargar"}},{q="Varför behöver Darkshire vargkött som mat?",a="Duskwoods jordbruksmark är förstörd och avskuren av monster, vilket gör traditionell boskapsskötsel och odling nästintill omöjlig. Lokalborna överlever genom att jaga det farliga viltet utanför sina gränser, däribland de talrika vargarna.",al={"varför äta vargar","darkshires matförsörjning","varför wolf kabobs"}},{q="Varför kan Grual inte få tag på örter lokalt i Duskwood?",a="Den genomträngande förbannelsen som plågar Duskwood har fördärvat mycket av den inhemska växtligheten, så det finns knappt några ätliga eller väldoftande matörter. Grual måste förlita sig på odlade sorter som importeras från Stormwind för att krydda sina rätter.",al={"varför köpa örter i stormwind","duskwood örter"}},{q="Har det här uppdraget koppling till en större berättelse?",a="Det är ett fristående uppdrag med lokal prägel, snarare än en del av en större berättelse. Men det skildrar tydligt Darkshires invånares lantliga, självständiga livsstil och deras fortsatta, osäkra försörjningslänk till Stormwind.",al={"wolf kabobs betydelse i berättelsen","är seasoned wolf kabobs viktigt"}}},fx={e8f8f6ed={q="Vad används Stormwind Seasoning Herbs till?",a="Vargkött från Duskwoods fördärvade skogar har ett ökänt kraftigt och strävt viltsmak. Chef Grual förlitar sig på väldoftande örter från Felicia Gumps blomsteraffär i Stormwind för att krydda köttet ordentligt och förvandla det till en aptitlig delikatess för Darkshires gäster.",al={"användning av kryddörter från stormwind","varför hämta örter från stormwind","vad används örterna till"}},["4102789d"]={q="Varför ber Chef Grual dig att hämta förnödenheterna i stället för att göra det själv?",a="Grual är kock, inte jägare eller budbärare, och han måste hålla uppsikt över eldstäderna på Scarlet Raven Tavern. Om han ger sig ut i de hemsökta vildmarkerna utanför Darkshire utsätter han sig för kringströvande bestar och värre hot, medan Night Watch har fullt upp med att försvara stadens utkanter i stället för att jaga eller springa ärenden till Stormwind.",al={"varför kan inte chef grual hämta köttet","varför behöver grual en äventyrare","varför jagar inte night watch vargarna"}},d7293b81={q="Vad ska Lean Wolf Flanks användas till?",a="Chef Grual använder flankerna som huvudingrediens i sin lokala specialitet, Seasoned Wolf Kabobs. Mat är en bristvara i Darkshires skuggiga utkanter och vargar stryker omkring utanför stadens gränser, så magert vargkött är en riklig basvara i Scarlet Raven Taverns kök.",al={"lean wolf flanks användning","varför vargflanker","vad ska lean wolf flank användas till"}}},fp="20,171,20.398.0,25.308.0,18.185.0,47.131.0,47.154.0,43.195.0,46.191.0,44.157.0"}
P.entries["quest:900"] = {n="Samophlange",s="Vid The Sludge Fen håller Samophlange-maskineriet Venture Companys borrigg igång. Tre ventiler måste tätas innan den centrala apparaten kan stängas av säkert.",h="Vid The Sludge Fen håller Samophlange-maskineriet Venture Companys borrigg igång.",kw={"the barrens","kontrollpanel","bränsleventil","regulatorventil","samophlange","the sludge fen","venture company"},ang={["faction:Horde"]="Genom att stoppa Venture Companys maskiner skyddar du norra The Barrens från okontrollerad industriell exploatering.",["profession:Engineering"]="Ingenjörer känner igen en klassisk goblindesign: överdimensionerade bränsleledningar som lätt blir instabila och få automatiska säkerhetsmekanismer. Manuella avstängningar hjälper till att förebygga ett katastrofalt tryckbakslag."},sec={{t="Täj apparaten",b="Vid The Sludge Fen är Venture Companys maskineri komplicerat och farligt. Den centrala konsolen visar tydligt att kärnan inte kan stoppas med en enda strömbrytare. Först måste du hantera matningsledningarna för hand, annars kan apparaten haverera eller explodera."},{t="De tre ventilerna",b="Tre ventiler styr flödet in i riggen: Main Control Valve, Fuel Control Valve och Regulator Valve. Var och en måste tätas för hand mot det höga trycket. När de stängs skiftar konsolens gröna indikatorer till gult, vilket gör det säkert att aktivera den centrala avstängningen."}},faq={{q="Varför ska ventilerna stängas?",a="Ventilerna tätar tryck- och bränsleledningarna innan apparaten stängs av. Om du stänger dem först minskar risken för skador på maskinen eller en katastrof.",al={"varför stänga ventilerna","samophlange-ventilernas syfte","vad gör ventilerna"}},{q="Vad händer när alla tre ventiler är stängda?",a="När alla tre ventiler är stängda sjunker trycket och bränslet slutar flöda. Konsolens blinkande lampor skiftar från grönt till gult, och huvudströmbrytaren går att röra fritt.",al={"panelens lampor","vad händer när ventilerna är stängda"}},{q="Vem byggde den här maskinen?",a="Venture Company byggde apparaten. Det här handelskartellet av gobliner utvinner olja och råmaterial i norra The Barrens.",al={"vem byggde samophlangen","venture company-maskin"}},{q="Var finns ventilerna?",a="De tre ventilerna finns nära den centrala kontrollkonsolen och huvudmaskineriet vid Venture Companys utgrävningsplats i The Barrens.",al={"ventilernas plats","var finns ventilerna"}},{q="Varför är Horden intresserad av den här apparaten?",a="Venture Companys tunga industri skadar The Barrens och tränger in på Hordens marker. Genom att förstå och sabotera deras maskineri kan du begränsa exploateringen.",al={"varför bryr sig horden","horden och samophlange"}},{q="Vad är en samophlange?",a="En samophlange är en obskyr teknisk goblinkomponent. De som inte är ingenjörer förstår sällan dess exakta funktion, men den verkar vara avgörande för högtrycksutrustning för borrning.",al={"samophlange betydelse","vad är en samophlange"}}},fp="11,165,20.235.0,16.256.0,49.139.0,46.178.0,23.125.0,29.120.0,43.158.0,22.169.0"}
P.entries["quest:901"] = {n="Samophlange",s="Vid The Sludge Fen står Venture Companys maskineri och väntar med stängda ventiler och trycket avlastat. Tinkerer Sniggles har nyckeln som öppnar kontrollenheten och frigör samophlangen därinne.",h="Vid The Sludge Fen står Venture Companys maskineri och väntar med stängda ventiler och trycket avlastat.",kw={"barrens","console key","samophlange","the sludge fen","sniggles","venture company"},ang={["faction:Horde"]="Som medlem av Horde hjälper du till att bromsa Venture Companys exploatering och giftiga utsläpp i norra Kalimdor genom att sabotera dess utrustning vid The Sludge Fen.",["profession:Engineering"]="Som ingenjör kan du se hur det följer goblinernas mekaniska säkerhetspraxis att låta mätarna gå ner på tomgång innan höljet öppnas."},sec={{t="Låsa upp mekanismen",b="Du har avlastat trycket genom att vrida på hjälpsventilerna, och rattarna och mätarna har stabiliserats. Höljet är fortfarande låst för att hindra manipulering. Nyckeln finns hos gobliningengören som övervakar borrplatsen."},{t="Mekanikern Sniggles",b="Tinkerer Sniggles övervakar Venture Companys utrustning vid The Sludge Fen. Han förvarar Console Key i en hydda strax nordost om den stora riggen. Du behöver nyckeln för att öppna höljet och komma åt samophlangen."},{t="Strömmen bryts",b="När du vrider Sniggles nyckel i konsolen låses höljet upp. Den röda fyren slocknar och det elektriska brummandet tonar bort. När konsolens säkerhetsspärrar har kopplats ur är kärnan redo att tas ut."}},faq={{q="Var finns Tinkerer Sniggles?",a="Tinkerer Sniggles finns i en goblinhydda strax nordost om huvudkonsolen vid The Sludge Fen i norra Barrens.",al={"hitta sniggles","sniggles plats","var finns tinkerer sniggles"}},{q="Vad används Console Key till?",a="Console Key låser upp huvudterminalen vid The Sludge Fen och bryter den återstående strömmen, så att du kan ta ut samophlangen därinne.",al={"använda console key","vad öppnar nyckeln","hur använder man console key"}},{q="Varför behövde konsolen stängas av innan nyckeln användes?",a="Först måste apparatens ventiler släppa ut trycket så att maskineriet går ner på tomgång. Det vore farligt att hantera den under fullt tryck.",al={"varför stänga av först","ventiler före nyckeln"}},{q="Vem arbetar Tinkerer Sniggles för?",a="Tinkerer Sniggles arbetar för Venture Company, som handlar med och utvinner resurser i norra Barrens.",al={"sniggles fraktion","tillhör sniggles venture company"}},{q="Vad är en samophlange?",a="En samophlange är en avancerad teknisk komponent som används i Venture Companys tunga borr- och pumpmaskineri.",al={"vad betyder samophlange","vad är en samophlange"}},{q="Vad händer när nyckeln används på konsolen?",a="När du använder nyckeln låses terminalen upp och strömmen bryts. Varningslamporna slocknar, och du kan ta ut samophlangen.",al={"vad händer sedan","efter console key"}}},fx={["50a822cb"]={q="Varför behöver du Console Key?",a="Även när apparaten är avstängd och tryckventilerna säkert har tömts är kontrollpanelen fortfarande ordentligt låst. Console Key krävs för att låsa upp höljet och bryta den sista strömtillförseln till terminalen, så att samophlange inuti kan tas ut säkert utan att den ömtåliga mekanismen skadas.",al={"vad används console key till","console keys syfte","varför console key"}}},fp="11,180,23.212.0,17.219.0,11.194.1,35.122.0,33.141.0,62.124.0,36.113.0,22.118.0,48.118.0"}
P.entries["quest:902"] = {n="Samophlange",s="Vid Venture Companys kontrollpanel hittar du den svårfunna samophlangen och tar den till Ratchet. Du har stängt av kontrollerna och försvaret; nu är den ömtåliga apparaten redo för Sputtervalves undersökning.",h="Vid Venture Companys kontrollpanel hittar du den svårfunna samophlangen och tar den till Ratchet.",kw={"kontrollpanel","ratchet","samophlange","sputtervalve","the barrens","tinkers' union","undermine","venture company"},ang={["faction:Horde"]="Som äventyrare för Horde hanterar du flyktigt skrot från Venture Company i Ratchets goblinhamnar, där goblinernas neutrala affärsverksamhet kan leda till explosiv inkompetens.",["profession:Engineering"]="För en ingenjör är samophlangen en maskin från Venture Company, fullpackad med täta ledningar, rör och obekanta delar som inbjuder till noggranna studier."},sec={{t="Gräv fram kärnan",b="Bakom Venture Company-kontrollpanelens frontplåt trängs ledningar och meningslösa rör runt märklig ingenjörskonst. Långt därinne finns samophlangen, en central komponent som har förbryllat ingenjörer i hela trakten. Med ett stadigt ryck lossar du apparaten ur sitt hölje och bär tillbaka den till goblinen som inledde bärgningsarbetet."},{t="Ömtåliga uppfinningar",b="Tillbaka i Ratchet tar Sputtervalve emot den märkliga apparaten och planerar att skicka den till Tinkers' Unions högkvarter i Undermine för undersökning. Goblinernas nyfikenhet tar överhanden. När han lägger ner samophlangen för att titta närmare på den går den ömtåliga mekanismen sönder mot golvet, och han skyndar sig att rädda så mycket av forskningsmaterialet han kan."}},faq={{q="Vad är egentligen en samophlange?",a="Inte ens erfarna mekaniker kan begripa samophlangens röra av ledningar, rör och märkliga småsaker. Den är den centrala komponenten i Venture Companys kontrollpanel, men varken Sputtervalve eller asätarna förstår hur den fungerar.",al={"vad är samophlange","samophlangens syfte","vad gör den"}},{q="Varför vill Sputtervalve ha samophlangen?",a="Sputtervalve planerar att skicka komponenten till Tinkers' Unions högkvarter i Undermine. Goblinuppfinnarna där studerar och bakåtutvecklar rivalers konstruktioner, om apparaten överlever granskningen.",al={"varför sputtervalve vill ha den","vem vill ha samophlange"}},{q="Vad händer när du lämnar över samophlangen?",a="Sputtervalve planerar att skicka samophlangen till Tinkers' Union i Undermine, men först vill han undersöka den själv.",al={"går samophlangen sönder","vad gör sputtervalve med den"}},{q="Vem byggde höljet till kontrollpanelen?",a="Venture Company byggde kontrollpanelen och samophlangen vid sin verksamhet i Sludge Fen, i norra The Barrens. Företagets tekniska experiment är ökända för hafsigt arbete och föroreningar.",al={"vem byggde samophlange","vem skapade kontrollpanelen"}},{q="Vart skickar Sputtervalve dig efter det här?",a="Sputtervalve skickar dig till sin medarbetare Wenikee Boltbucket, en annan ingenjör i The Barrens.",al={"nästa uppdrag efter samophlange","vad göra härnäst"}},{q="Var finns Sputtervalve?",a="Sputtervalve arbetar på Ratchets kajer och i verkstäder, i hamnstaden på The Barrens östra kust.",al={"sputtervalves plats","var finns sputtervalve","var lämnar man in samophlange"}}},fp="11,183,19.329.0,19.332.1,31.249.0,43.189.0,48.120.1,49.183.0,44.92.1,30.109.0"}
P.entries["quest:903"] = {n="Prowlers of the Barrens",s="Vid The Crossroads skickar Sergra Darkthorn dig efter savannens lurare. Deras klor visar om du kan möta The Barrens mäktigaste bestar.",h="Vid The Crossroads skickar Sergra Darkthorn dig efter savannens lurare.",kw={"the crossroads","echeyakee","jakt","prowler claws","prowlers","savannens prowler","sergra darkthorn","the barrens"},ang={["class:Hunter"]="Som jägare tränar du på att spåra savannens lurare genom höga snår, upptäcka dem innan de slår till och kuva aggressiva katter.",["faction:Horde"]="Som medlem av Horde hjälper du till att tämja vildmarken kring The Crossroads och hålla försörjningskonvojer säkra på vägarna mellan Durotar, Mulgore och de södra utposterna.",["race:Tauren"]="Som tauren hedrar du naturens balans när du gallrar bland vildsinta rovdjur och skyddar sårbara karavaner som korsar dina förfäders jaktmarker."},sec={{t="Ett äkta rovdjur",b="Sergra Darkthorn prövar jägare som redan mött plainstriders och zhevras. Sydväst om The Crossroads försvinner savannens lurare i centrala The Barrens gyllene och ockrafärgade snår. De stora kattdjuren jagar i stället för att beta med hjordarna. De väntar i det höga gräset och överfaller sedan sitt byte, och oförsiktiga resenärer kan falla offer för dem."},{t="Rovdjur eller byte",b="Sergra varnar dig för att lurarna kan jaga. Läs av gräset och slå till innan en katt hoppar, om du tänker ta dess tassar och klor. Ta med dig sju prowler claws för att visa att du har list och snabba reflexer nog att överleva Kalimdors farligaste vilda djur."},{t="Steget mot mästaren",b="Din näve full av klor bevisar att du har lärt dig överleva på den öppna savannen. Sergra är nöjd med din stridsförmåga och förbereder ett modprov: åkalla och döda Echeyakee, det vita lejon som vördas som en förkämpe bland The Barrens rovdjur."}},faq={{q="Vem erbjuder jakten?",a="Sergra Darkthorn, en erfaren ork vid The Crossroads i The Barrens, ger dig jakten som ett steg i en traditionell serie jaktriter.",al={"uppdragsgivare","vem ger uppdraget med prowlers","sergra darkthorn"}},{q="Var finns savannens prowlers?",a="Savannens lurare smyger genom det höga gräset sydväst om The Crossroads, där de smälter in i det öppna landskapet och jagar zhevras och intet ont anande resenärer.",al={"var finns prowlers","prowler-platser","var hittar man savannens prowler"}},{q="Vilka troféer kräver Sergra?",a="Sergra kräver sju Prowler Claws, tagna från katterna i direkt strid, som bevis på att du har besegrat dem.",al={"vad behöver jag","föremål till prowler-uppdraget","klor"}},{q="Vad leder jakten till?",a="När du dödar lurarna bevisar du att du är redo att utmana Echeyakee, det berömda vita lejonet i The Barrens.",al={"nästa uppdrag","vad kommer efter prowlers","echeyakee"}},{q="Varför låter Sergra resenärer jaga rovdjur?",a="Sergra låter dig gallra bland farliga bestar som hotar vägarna och prövar om jägare förstår balansen mellan rovdjur och byte. De sorterar bort de vårdslösa innan större hot väntar.",al={"varför jaga prowlers","syftet med jakten","bakgrund till jakten"}},{q="Är savannens prowlers farliga för bosättningen?",a="Lurare anfaller sällan befästa läger som The Crossroads, men de håller sig nära de södra vägarna och jagar resenärer, budbärare och lastdjur.",al={"anfaller prowlers the crossroads","hot mot the crossroads"}}},fx={["52f28747"]={q="Vad används Prowler Claws till?",a="Sergra Darkthorn kräver klorna som fysiskt bevis på att du har dödat ditt byte. Jakten på savannens strykare prövar din list och uthållighet mot The Barrens verkliga rovdjur. När du kommer tillbaka med deras dödliga klor visar du att du behärskade jakten och inte själv blev byte bland de höga gräsen.",al={"varför samla prowler claws","prowler claws syfte","vad gör sergra med prowler claws"}},["6a79a965"]={q="Vad är savannens strykare som du jagar?",a="Savannens strykare är stora rovkatter som hör hemma på The Barrens öppna slätter. De smyger genom de höga gräsen och är tåliga, påhittiga, listiga och farliga för resenärer. Sergra skickar dig efter dem för att du ska lämna det fogliga bytet bakom dig och pröva din överlevnadsförmåga mot bestar som kan vända jakten och jaga dig.",al={"vad är savannens strykare","vem jagar strykare","mål för savannens strykare"}}},fp="23,151,15.303.0,16.222.0,28.246.1,21.125.0,40.135.0,37.119.0,28.105.1,46.195.0,50.146.0"}
P.entries["quest:90487"] = {n="Ancient Allies",s="En eremit visar dig vägen till en utpost med uråldriga och dryader på Mount Hyjals nedre sluttningar. Fraxinus och hans följeslagare kan hjälpa dig med den kommande klättringen.",h="En eremit visar dig vägen till en utpost med uråldriga och dryader på Mount Hyjals nedre sluttningar.",kw={"uråldriga allierade","uråldriga","dryader","fraxinus","eremit","mount hyjal","utpost"},sec={{t="Bergens väktare",b="Eremiten har inte mycket mer att erbjuda när du förbereder dig för den långa klättringen uppför Mount Hyjal. Han visar dig västerut från sin grotta, sedan norrut mot bergets fot. Där finns ännu en utpost från de väktare som en gång strövade omkring på sluttningarna. Fraxinus, en uråldrig, och hans vänner kan hjälpa dig."}},faq={{q="Vem är Fraxinus?",a="Fraxinus är en uråldrig vid en utpost på Mount Hyjals nedre sluttningar.",al={"fraxinus","uråldriga fraxinus"}},{q="Var ligger utposten?",a="Utposten ligger väster om eremitens grotta, nära foten av Mount Hyjal.",al={"utpost med uråldriga","var finns de uråldriga"}},{q="Vilka bor vid utposten?",a="Vid utposten finns uråldriga och dryader, rester av de väktare som en gång strövade omkring på Mount Hyjals sluttningar.",al={"dryader och uråldriga","hyjals väktare"}},{q="Varför ska man tala med de uråldriga?",a="Eremiten säger att Fraxinus och hans följeslagare kanske kan hjälpa dig på den långa färden uppför Mount Hyjal.",al={"hjälp från uråldriga","hjälp med klättringen på hyjal"}}},fp="14,152,22.290.0,16.69.0,21.75.0,25.105.0,28.91.0"}
P.entries["quest:905"] = {n="The Angry Scytheclaws",s="Söder om The Crossroads skickar Sergra Darkthorn ut jägare för att möta de vilda scytheclaws som stryker omkring i The Barrens. Ta med sunscale raptor-fjädrar till deras häckningsbon och visa ditt mod i ett land där ingen visar nåd.",h="Söder om The Crossroads skickar Sergra Darkthorn ut jägare för att möta de vilda scytheclaws som stryker...",kw={"the crossroads","ägg","gold road","bon","raptor grounds","raptorer","scytheclaws","sergra darkthorn","the stagnant oasis","sunscale"},ang={["class:Hunter"]="Som jägare prövar du din vildmarkskunskap när du går in i ett territoriellt rovdjurs bo och utmanar dess dominans.",["faction:Horde"]="Som medlem av Horde vet du att raptorflockarna längs Gold Road hotar karavaner och ensamma budbärare som färdas mellan The Crossroads och utposterna i söder.",["race:Orc"]="Som orch vet du att det krävs styrka, uthållighet och orubbligt mod för att överleva Durotar och The Barrens."},sec={{t="Ett modprov",b="Sergra Darkthorn prövar jägare mot The Barrens vidunder. Efter enklare prövningar skickar hon dig söder om The Crossroads för att jaga våldsamma sunscale raptors och ta deras fjädrar. Sedan bär du fjädrarna sydväst om The Stagnant Oasis, in i raptorernas revir. Att lägga dem i bona är det verkliga provet: det visar att du kan möta scytheclaws utan rädsla."},{t="Scytheclaw-bona",b="Tre raptorbon ligger sydväst om The Stagnant Oasis, nära Gold Road. Röda, blå och gula ägg markerar de olika kullarna. Scytheclaws försvarar sina bon häftigt mot allt som kommer nära. Lägg fallna raptorers fjädrar bland äggen, så gör du din utmaning tydlig för bestarna."},{t="Härdad av savannen",b="Återvänd till The Crossroads efter att ha gått in i bona, så ser Sergra att du mött faran och överlevt. Att ta sig ut ur ett raptorbo kräver rått mod. The Barrens prövar varje jägare; varje strid kan härda dig eller lämna dina ben bland kodo-revbenen som ligger strödda över marken."}},faq={{q="Varför vill Sergra Darkthorn att jag ska lägga fjädrar i raptorernas bon?",a="Sergra Darkthorn ber dig visa mod och dominans. Döda sunscale raptors och lägg sedan deras fjädrar i de färgade kullarna för att visa deras flock och släkt att du inte fruktar dem.",al={"varför scytheclaw-bon","syftet med fjädrar i bon","varför vanhelga bon"}},{q="Var ligger scytheclaw-bona?",a="Bona ligger söder om The Crossroads och sydväst om The Stagnant Oasis, nära Gold Road. De ligger intill en liten kulle som markeras av jättelika kodoben, strax öster om vägdiket.",al={"var finns bona","scytheclaw-bonas plats","plats för blått, gult och rött bo"}},{q="Vilka slags raptorer lever i den här delen av The Barrens?",a="Sunscale scytheclaws och deras släktingar lever här. Dessa listiga, aggressiva reptilrovdjur jagar i flock och försvarar häftigt sina kullar kring Gold Road och närliggande Raptor Grounds.",al={"raptorarter i the barrens","sunscale-raptorer","vad är scytheclaws"}},{q="Var samlar jag in Sunscale Feathers?",a="Sunscale raptors och scytheclaws på slätterna söder om The Crossroads och i närliggande Raptor Grounds mot de östra kullarna bär på Sunscale Feathers.",al={"var får man fjädrar","sunscale-fjädrar som byte","hur får man raptor­fjädrar"}},{q="Vem är Sergra Darkthorn?",a="Sergra Darkthorn är en erfaren orch som är stationerad vid The Crossroads. Hon prövar Horde-äventyrare som anländer med uppdrag runt om i The Barrens och mäter deras överlevnadsinstinkt och stridsdisciplin.",al={"vem är sergra","sergra darkthorns historia"}},{q="Leder det här uppdraget till fler jakter?",a="Ja. Sergra Darkthorns jakter fortsätter genom The Barrens och avslutas med jakten på Isha Awak, det legendariska havsvidundret utanför The Barrens kust.",al={"vad kommer efter the angry scytheclaws","jaktkedjan vid the crossroads","nästa uppdrag efter bona"}}},fx={["95d43724"]={q="Varför låter Sergra Darkthorn dig jaga rovfåglarna i stället för att göra det själv?",a="Sergra Darkthorn bekämpar inte bara skadedjur, hon vägleder dig också i jaktens konst. Från sin post vid The Crossroads prövar hon blivande hjältar från Horden mot The Barrens hårda vildmark. Genom att låta dig samla fjädrar och medvetet tränga in i rovfåglarnas bon stärker hon ditt mod och din uthållighet genom verklig fara. Hon ser om det skoningslösa landet formar dig till en tåligare överlevare.",al={"varför skicka mig","varför inte sergra","varför jagar inte sergra dem"}}},fp="21,197,15.345.0,20.294.0,23.269.0,70.184.0,39.183.0,55.188.0,41.177.0,24.196.0,36.141.1"}
P.entries["quest:9051"] = {n="Toxic Test",s="Torwa Pathfinder i Un'Goro Crater ber dig testa Devilsaur Barb på en devilsaur. Återvänd till honom när du har gjort det.",h="Torwa Pathfinder i Un'Goro Crater ber dig testa Devilsaur Barb på en devilsaur.",kw={"devilsaur","devilsaur barb","torwa pathfinder","giftigt test","un'goro crater"},sec={{t="Hulling",b="Med Devilsaur Barb i handen kan du testa den. Torwa Pathfinder i Un'Goro Crater väntar på att du återvänder efter att du stuckit en devilsaur; testet hänger på det sticket."}},faq={{q="Vad vill Torwa att jag ska göra?",a="Torwa Pathfinder ber dig sticka en devilsaur med Devilsaur Barb och sedan återvända till honom i Un'Goro Crater.",al={"uppdrag med devilsaur barb","giftigt test","sticka devilsaur"}},{q="Vart ska jag återvända?",a="Återvänd till Torwa Pathfinder i Un'Goro Crater efter att du stuckit en devilsaur med Devilsaur Barb.",al={"var finns torwa","återvänd till torwa","torwas plats"}},{q="Vad ska jag använda på devilsauren?",a="Använd Devilsaur Barb för att sticka en devilsaur.",al={"vad används devilsaur barb till","testa hullingen","föremål för giftigt test"}}},fp="10,123,8.172.0,30.108.0,18.96.0,31.43.0"}
P.entries["quest:9053"] = {n="A Better Ingredient",s="Torwa Pathfinder söker en Putrid Vine från väktaren längst ner i Sunken Temple. Du ombeds ta den tillbaka till honom.",h="Torwa Pathfinder söker en Putrid Vine från väktaren längst ner i Sunken Temple.",kw={"en bättre ingrediens","väktare","putrid vine","sunken temple","torwa pathfinder"},sec={{t="Sunken Temple",b="Väktaren längst ner i Sunken Temple har en Putrid Vine som Torwa Pathfinder vill ha. Du ska hämta den och återvända till Torwa med den."}},faq={{q="Vem vill ha Putrid Vine?",a="Torwa Pathfinder ber dig hämta en Putrid Vine åt honom.",al={"vem behöver vinrankan","torwas ingrediens","vem bad om putrid vine"}},{q="Var finns Putrid Vine?",a="Putrid Vine finns hos väktaren längst ner i Sunken Temple.",al={"var finns vinrankan","vinrankans plats","hitta putrid vine"}},{q="Vad ska jag ta tillbaka till Torwa?",a="Hämta en Putrid Vine åt Torwa Pathfinder från väktaren längst ner i Sunken Temple.",al={"vilken ingrediens","vad ska jag ta med till torwa","torwas vinranka"}}},fp="19,129,17.149.0,26.53.0,25.72.0,30.90.0"}
P.entries["quest:906"] = {n="Betrayal from Within",s="I centrala The Barrens når jakten på Lok Orcbane sitt slut. Hans fall försvagar Razormane-räderna, och du för hans avhuggna huvud till Thork vid The Crossroads.",h="I centrala The Barrens når jakten på Lok Orcbane sitt slut.",kw={"agamaggan","barrens","camp taurajo","crossroads","lok orcbane","mangletooth","quilboar","razormane","thork"},ang={["faction:Horde"]="Som medlem av Horden hjälper du till att säkra färdvägarna mellan Camp Taurajo och The Crossroads. Lok Orcbanes död dämpar Razormanes hot mot nya bosättningar i Kalimdor.",["race:Orc"]="Som orch hör du en varning i Loks efternamn: Orcbane. Han har länge slaktat orchska nybyggare och försörjningskaravaner på de torra slätterna."},sec={{t="En förrädares huvud",b="Mangletooth, en tillfångatagen Razormane quilboar som hålls i en bur vid Camp Taurajo, pekar ut Lok Orcbane som hövdingen bakom attackerna mot Hordens karavaner. När du dödar Lok djupt inne i de södra törnesnåren ger Mangletooth dig hövdingens skalle. Han tycker det är roligt att orcherna får hjälp av ett förräderi inom stammen utan att veta att en tillfångatagen quilboar hjälpte dem."},{t="Trygghet vid The Crossroads",b="Du för Loks huvud norrut till Thork vid The Crossroads och lättar trycket på Hordens försörjningslinjer genom den centrala savannen. Thork är förvånad över att en ensam resenär fällde en så mäktig ledare; han hade väntat sig att någon annan låg bakom de samordnade anfallen. Loks död splittrar Razormanes offensiv och gör deras kämpar oorganiserade."}},faq={{q="Vem är Mangletooth?",a="Mangletooth är en tillfångatagen Razormane quilboar som hålls i en träbur vid Camp Taurajo. Förbittrad över att stammen övergav honom vägleder han Hordens äventyrare mot dess krigsherrar för att få sin hämnd.",al={"mangletooth","tillfångatagen quilboar","fånge i taurajo"}},{q="Vem var Lok Orcbane?",a="Lok Orcbane var en framstående Razormane-hövding som samordnade våldsamma bakhåll mot Hordens utposter och försörjningslinjer runt om i The Barrens.",al={"lok","lok orcbane","razormane-ledare"}},{q="Varför bryr sig Thork om Loks död?",a="Thork leder försvaret av The Crossroads mot ihärdiga rövare från törnesnåren. Lok Orcbane ledde angreppen längs Gold Road, och hans död undanröjer deras främsta taktiker.",al={"varför thork vill att lok ska dö","räder mot försörjningslinjer vid crossroads"}},{q="Varför hjälpte Mangletooth till att döda sin egen hövding?",a="Mangletooth är djupt förbittrad på sin stams ledarskap och värderar rå styrka högre än släktskap. Han vägleder Hordens mästare när de ska döda Lok och får utlopp för sitt hat, samtidigt som han håller sin mystiska förbindelse med Agamaggan hemlig bakom galler.",al={"varför förrådde mangletooth","mangletooths motiv"}},{q="Vart leder den här uppdragskedjan?",a="Du för Loks huvud som tecken på att den omedelbara mordkedjan är över. Mangletooth byter fortfarande Agamaggans elementvälsignelser mot Blood Shards som samlats in från quilboar runt om i The Barrens.",al={"nästa uppdrag efter betrayal from within","vad följer efter betrayal from within"}},{q="Var finns Thork?",a="Thork befinner sig på vakt inne i bosättningen The Crossroads i norra delen av centrala The Barrens, där han övervakar försvaret och logistiken.",al={"thorks plats","var finns thork"}}},fx={["1320d8a4"]={q="Varför låter Mangletooth dig lämna över Loks skalle i stället för att göra det själv?",a="Mangletooth sitter fången i en bur från Horden vid Camp Taurajo. Även om han kunde gå fri skulle vakterna vid The Crossroads slå ner en Razormane quilboar på plats i stället för att förhandla med honom. Genom att skicka dig med Lok Orcbanes skalle ser han till att Horden får veta att hövdingen har fallit, samtidigt som du får äran och den belöning Thork erbjuder.",al={"varför behöver mangletooth dig","varför skickar mangletooth dig till thork","varför kan inte mangletooth lämna över skallen"}}},fp="20,189,16.376.0,23.349.1,19.182.0,20.139.0,38.184.0,53.227.0,33.191.0,23.117.0"}
P.entries["quest:907"] = {n="Enraged Thunder Lizards",s="I södra Barrens strövar åsködlor över slätterna runt Camp Taurajo. Jorn Skyseer kallar jägare att möta de väldiga bestarna och hämta deras blod som del av en större övergångsrit.",h="I södra Barrens strövar åsködlor över slätterna runt Camp Taurajo.",kw={"barrens","camp taurajo","enraged thunder lizards","jorn skyseer","stormhide","stormsnout","thunderhead"},ang={["class:Hunter"]="Som jägare prövar du ditt fotarbete mot en åsködla och håller dig undan dess krossande stampningar medan du nöter på dess väldiga skinn.",["faction:Horde"]="Som medlem av Horde hjälper du till att rensa stigarna runt Camp Taurajo från ursinniga bestar och skyddar karavaner och resande krigare i södra Barrens.",["race:Tauren"]="Som Shu'halo hedrar du förfädernas slätter genom den traditionella jakten på väldiga åsködlor runt Camp Taurajo. Den prövar din uthållighet och balans."},sec={{t="En prövning på de södra slätterna",b="Efter att ha besegrat raptorn Ishamuhale återvänder du till Camp Taurajo. Taurenäldsten Jorn Skyseer prövar nu din styrka mot landets största betesdjur. Stormsnouts och Thunderheads strövar i södra Barrens, och deras tunga steg kan krossa en oförsiktig jägare."},{t="Rovdjurets väg",b="Tauren- och orcjägare värdesätter lugn, position och styrka när de möter en åsködla. Jorn ber dig hämta prover av deras kraftfulla blod, ett bevis på att du stod i vägen för de dånande bestarna och överlevde med benen hela. Trofén öppnar vägen till Jorns sista byte i skyn."}},faq={{q="Var hittar jag åsködlorna till den här jakten?",a="Åsködlor strövar över slätterna runt Camp Taurajo i södra Barrens. Stormsnouts, Stormhides och Thunderheads betar norr, öster och söder om lägret.",al={"åsködlornas plats","var finns stormsnouts","var hittar man åsködlor"}},{q="Vem skickar mig på den här jakten?",a="Jorn Skyseer, en taurenäldste och jägare vid Camp Taurajo, skickar dig efter åsködlorna. Jakten följer på ditt möte med den snabba raptorn Ishamuhale.",al={"uppdragsgivare","vem ger enraged thunder lizards","jorn skyseer"}},{q="Vad gör åsködlor särskilt farliga?",a="Åsködlor är farliga på grund av sin väldiga storlek och elektriska natur. En oförsiktig jägare kan krossas under deras fötter eller bedövas av deras stormladdade stampningar.",al={"varför är de farliga","strid mot åsködlor"}},{q="Vad gör Jorn med blodet som samlas in?",a="Jorn använder blodet som bevis på att du mötte och fällde varelserna i närstrid. Han granskar det för att se om du överlevde deras trampande med benen oskadda.",al={"varför åsködlornas blod","blodets syfte"}},{q="Vad händer efter det här uppdraget?",a="För med dig blodet till Jorn Skyseer, så skickar han dig efter slätternas bevingade rovdjur i Cry of the Thunderhawk, nästa steg i södra Barrens jaktprov.",al={"nästa uppdrag","vad händer efter enraged thunder lizards"}},{q="Hur passar detta in i Sergra Darkthorns prövningar?",a="Sergra Darkthorn inleder din jaktutbildning nära The Crossroads i norra Barrens. Hon skickar dig efter plainstriders, zhevras och raptorer, och sedan söderut till Taurajo för att lära av Jorn Skyseer och jaga större villebråd.",al={"jaktprövningar vid the crossroads","sergra darkthorns uppdragskedja"}}},fx={["0ee753a7"]={q="Varför vill Jorn Skyseer att jag jagar åsködlor?",a="Jorn Skyseer vägleder lovande jägare genom slätternas riter och bygger vidare på jaktprövningarna som Sergra Darkthorn inledde. När du möter de kolossala åsködlorna visar du ditt mod, din smidighet och din uthållighet mot några av södra The Barrens farligaste och mest överväldigande bestar.",al={"varför jaga åsködlor","jorn skyseers motiv","varför vill jorn ha thunder lizard blood"}},["5ef19b55"]={q="Vad är åsködlorna i södra The Barrens?",a="Åsködlor, som på de södra slätterna är kända som Stormsnouts, Stormhides och Thunderheads, är enorma reptilbestar som hör hemma i The Barrens. Deras väldiga kroppar får marken att skälva när de dundrar fram över grässlätterna. De kan lätt krossa oförsiktiga jägare under sina fötter.",al={"vad är åsködlor","stormsnouts och stormhides","the barrens thunderheads"}}},fp="23,185,29.275.0,23.293.0,51.160.0,26.159.0,50.155.0,43.168.0,28.164.0,49.231.0"}
P.entries["quest:90902"] = {n="Rediscovering the Light",s="Aramis Hammerhand i Deathknell erbjuder den här uppgiften, där nyuppståndna Forsaken-paladiner utmanas att åter omfamna Holy Light. När de åkallar heliga krafter drabbas deras odöda kroppar av intensiv smärta, så de måste kanalisera läkande kraft till skadade Deathguards trots den brännande plågan.",h="Aramis Hammerhand i Deathknell erbjuder den här uppgiften, där nyuppståndna Forsaken-paladiner utmanas att...",kw={"aramis hammerhand","deathguard","deathknell","forsaken-paladin","holy light","rediscovering the light","tirisfal glades","odöd paladin"},ang={["class:Paladin"]="För en odöd paladin är återknytningen till Light ett prov på tro och uthållighet. Den visar att heliga eder kan överleva själva döden, trots den blåsande smärta det innebär.",["race:Undead"]="Den här riten visar Forsakens häftiga motståndskraft. De förvandlar till och med Lights brännande plåga till ett disciplinerat vapen för sin överlevnad."},sec={{t="En smärtsam återförening",b="För forna Silver Hand-mästare och fallna riddare från Lordaeron innebär uppvaknandet i odödlighet en fasansfull insikt: Holy Light svarar fortfarande på deras kallelse, men bränner deras vissnade kroppar inifrån. Aramis Hammerhand förklarar för nyuppståndna Forsaken-paladiner att förmågor de en gång använde helt naturligt nu orsakar outhärdlig smärta. Eftersom helig energi står i naturlig konflikt med den mörka magi som upprätthåller odödligheten kräver det rå viljestyrka och plågsam uthållighet att kanalisera Light."},{t="Renande lidande",b="I stället för att låta plågan avskräcka dem ser Forsaken-paladiner smärtan som ett bestående bevis på sin tro. Deathguards runt om i Deathknell lider av svåra sår efter strider mot tanklösa zombier, och det faller på dessa odöda riddare att hela dem. Aramis lär dem att uthärda den brännande smärtan, ungefär som när man tränar en förtvinad muskel. Själva plågan blir en hedersbeteckning och ett levande bevis på att Light inte har övergett dem."}},faq={{q="Varför gör det ont när Forsaken-paladiner använder Light?",a="Holy Light står i grundläggande motsättning till de nekrotiska energier som upprätthåller odödligheten. En Forsakens vilja och övertygelse låter dem kanalisera Lights kraft, men när den heliga energin strömmar genom dött kött orsakar den outhärdlig, brännande smärta.",al={"varför gör light ont på odöda","holy light bränner odöda","varför gör det ont att hela"}},{q="Vem är Aramis Hammerhand?",a="Aramis Hammerhand är en odöd paladintränare i Deathknell. Han vägleder nyuppståndna Forsaken-paladiner när de åter bygger upp sin krossade förbindelse till Holy Light.",al={"vem är aramis hammerhand","aramis hammerhands bakgrund","uppdragsgivare"}},{q="Varför är Deathguards i Deathknell skadade?",a="Deathguards är soldaterna som försvarar Deathknell mot tanklösa odöda, vilda rester av Scourge och fientliga vilda djur som omger bosättningen när de nyuppståndna vaknar ur sina gravar.",al={"varför är deathguards skadade","deathguards bakgrund","deathknells försvarare"}},{q="Kan odöda naturligt använda Holy Light?",a="Ja, om de behåller sin tro, viljestyrka och minnet av sina forna eder. Light svarar på äkta övertygelse, men kräver ett brutalt fysiskt pris av döda kroppar.",al={"kan forsaken vara paladiner","odöda som använder light","forsaken-paladinernas bakgrund"}},{q="Vad menar Aramis när han kallar smärtan en hedersbeteckning?",a="Aramis ser den brännande plågan inte som en förbannelse, utan som ett obestridligt bevis på att Light fortfarande lyssnar. Forsaken-paladiner uthärdar den brännande hettan från sina besvärjelser för att visa sin orubbliga lojalitet och sitt syfte.",al={"smärtans renande egenskap","vad hedersbeteckning betyder","aramis tal"}},{q="Var utspelar sig det här uppdraget?",a="Det utspelar sig helt och hållet i Deathknell, den avskilda nybörjarfristaden i sydvästra Tirisfal Glades, där nyuppståndna Forsaken först träder in i sin odöda tillvaro.",al={"var finns uppdraget","uppdragets plats","deathknell-uppdrag"}}},fx={["8eaa6c3c"]={q="Varför vill Aramis Hammerhand att detta blir gjort?",a="Aramis vill träna nyuppståndna paladiner bland de Förfallna att åter knyta an till det heliga ljuset. Eftersom det innebär en enorm fysisk smärta att kanalisera ljuset i odöden vet han att dina förmågor har förtvinat. Det enda sättet att återfå din skicklighet och fungera fullt ut är att härda ut plågan och träna dina andliga muskler genom att hela de sårade soldaterna som försvarar Deathknell.",al={"varför vill aramis få detta gjort","aramis hammerhands motiv","varför hela sårade deathguards"}},["1e0efd99"]={q="Varför behöver Aramis att du helar Deathguards?",a="Det här uppdraget är ett prov och en disciplinövning för dig som nyväckt paladin. Etablerade helare eller Aramis själv skulle kunna ta hand om de sårade, men bara genom att själv kanalisera ljusets brännande plåga kan du bygga upp din uthållighet och återta dina forna krafter i odöden.",al={"varför jag ska återupptäcka ljuset","varför behöver aramis att jag helar deathguards","varför kan inte aramis hela dem"}}},fp="23,102,17.373.0,30.305.0,48.185.0,25.153.0,46.206.0,42.200.0,58.177.0,33.144.0"}
P.entries["quest:91"] = {n="Solomon's Law",s="Solomon's Law är ett lokalt dekret som utfärdas genom Bailiff Conacher i Lakeshire Town Hall. Det dömer Shadowhide-gnollerna i Redridge till döden för att ha samarbetat med Morganth, en fiende till Stormwind. Äventyrare får i uppdrag att skipa stadens hårda gränsrättvisa genom att återlämna hängen som tagits från gnollerna.",h="Solomon's Law är ett lokalt dekret som utfärdas genom Bailiff Conacher i Lakeshire Town Hall.",kw={"conacher","gnoller","lakeshire","morganth","hängen","redridge","shadowhide","solomon","stadshuset"},ang={["class:Mage"]="Morganth förkroppsligar förvrängningen av arkan kunskap till mörk terror, vilket gör hans hantlangare till prioriterade mål för disciplinerade magiker.",["class:Paladin"]="Att straffa avskyvärda gnoller som villigt tjänar en mörk trollkarl svarar mot kallelsen att skipa helig rättvisa och skydda belägrade gränsstäder.",["faction:Alliance"]="Att upprätthålla Solomons dekret stärker rättsstaten vid den östra gränsen, där Stormwinds reguljära styrkor märkbart saknas."},sec={{t="Gränsrättvisa i Lakeshire",b="Lakeshire ligger till stor del isolerat från Stormwinds omedelbara militära stöd, vilket tvingar Magistrate Solomon och stadens tjänstemän att styra Redridge med sträng gränsauktoritet. Bailiff Conacher arbetar från stadshuset och företräder den lokala magistratsdomstolen. När yttre hot plågar staden har domstolen få andra möjligheter än att utfästa belöningar för lagbrytares huvuden och förlita sig på legosoldater och resande försvarare för att upprätthålla kungarikets lagar."},{t="Att hjälpa kronans fiende",b="Den rättsliga grunden för att utrota Shadowhide-klanen är dess allians med Morganth, en avfällig magiker som slagit sig ned i de östra kullarna. Enligt Lakeshires och kungariket Stormwinds lagar är direkt hjälp till en utropad fiende till riket belagd med obligatoriskt dödsstraff. Eftersom gnollerna aktivt utför Morganths order betraktar domstolen dem inte bara som vilda asätare, utan som förrädiska stridande som ska avrättas."}},faq={{q="Vem är Solomon och vad innebär hans lag?",a="Solomon syftar på Magistrate Solomon, Lakeshires civila ledare. ”Solomon's Law” återspeglar hans lokala påbud och Stormwinds lagar, som slår fast att det är förräderi att hjälpa en utropad brottsling i kungariket, ett brott som straffas med döden.",al={"vem är solomon","solomons lag betydelse","vad är solomons lag"}},{q="Vem är Morganth och varför bryr sig Lakeshire om honom?",a="Morganth är en avfällig utövare av den arkana magin som bor vid Redridges östra fotkullar. Han har stämplats som fiende till Stormwind och använder mörk magi för att terrorisera lokalbefolkningen. Han har också böjt Shadowhide-gnollerna under sin mörka vilja.",al={"vem är morganth","morganths bakgrund","varför är morganth farlig"}},{q="Varför jagas just Shadowhide-gnollerna?",a="Gnoller är alltid farliga för traktens nybyggare, men Shadowhide-klanen har trätt i mörkermagikern Morganths direkta tjänst. Den aktiva alliansen gör dem till lagliga mål för avrättning enligt stadens dekret.",al={"varför döda shadowhide","shadowhide-gnoller i redridge","varför är gnollerna måltavlor"}},{q="Vad är hängena till för?",a="Hängena som Shadowhide-gnollerna bär fungerar som bevis på deras död. Bailiff Conacher kräver att äventyrare lämnar in tio hängen för att bekräfta att domstolens dom har verkställts innan någon belöning betalas ut.",al={"varför shadowhide-hängen","hängenas syfte","hängen som bevis"}},{q="Var bedriver Bailiff Conacher sin verksamhet?",a="Bailiff Conacher är stationerad i Lakeshire Town Hall, tillsammans med Magistrate Solomon och andra civila tjänstemän som sköter Redridges angelägenheter.",al={"var finns conacher","var finns bailiff conacher","lakeshires domstol"}},{q="Varför skickar inte Stormwind kungliga soldater för att ta itu med detta?",a="Kungariket Stormwind är hårt pressat och plågas för närvarande av politisk handlingsförlamning och oroligheter i sina territorier. Lakeshires begäran om formella militära förstärkningar har upprepade gånger förbisetts, vilket lämnat Magistrate Solomon att anlita äventyrare.",al={"var är stormwinds armé","varför inga vakter mot gnollerna","lakeshire övergivet av stormwind"}}},fx={["0a2e314c"]={q="Varför vill Bailiff Conacher att Shadowhide-kobolderna dödas?",a="Som magistratens tjänsteman i Lakeshire har Bailiff Conacher i uppgift att upprätthålla rikets lagar. En avfällig trollkarl vid namn Morganth har slagit sig ner i de östra förbergen och gjort Shadowhide-koboldflocken till sin personliga förtrupp. Conacher ser deras lojalitet mot en förklarad fiende till Stormwind som högförräderi. För honom handlar det inte bara om att minska ett lokalt besvär, utan om att verkställa magistratens lagliga dödsdom över dem som hjälper kronans brottslingar.",al={"conachers motiv","varför döda shadowhide-kobolderna","bailiff conachers skäl"}}},fp="13,200,29.391.0,28.312.0,35.187.0,54.211.0,56.156.0,26.163.0,49.124.0,60.223.0"}
P.entries["quest:91208"] = {n="Coming to Terms",s="Aramis Hammerhand i Deathknell erbjuder uppdraget, där nyuppståndna paladiner ska söka upp en riddare som kämpar med att acceptera sin odödhet. I skräck flyr den återuppståndna krigaren upp i kullarna och tvingas inse den plågsamma sanningen: hon har blivit det hon en gång bekämpade.",h="Aramis Hammerhand i Deathknell erbjuder uppdraget, där nyuppståndna paladiner ska söka upp en riddare som...",kw={"aramis hammerhand","coming to terms","deathknell","skräckslagen paladin","heliga ljuset","paladin","tirisfal glades","odöd paladin"},ang={["class:Paladin"]="Uppdraget går rakt in i paladinens dilemma i odöden: att möta fasan i att ha blivit det man svor att utrota.",["race:Undead"]="Uppvaknandet i Tirisfal knäcker många sinnen; att ta hand om dem som gått förlorade i paniken är en tragisk del av de Fördömdas tidiga tillvaro."},sec={{t="En bitter återuppståndelse",b="Att vakna upp bland de Fördömdas led efter döden är omtumlande för vem som helst, men för tidigare paladiner från Silver Hand är chocken påtaglig. De har ägnat sina liv som dödliga åt att förgöra de odöda i den Heliga Ljusets tjänst, men plötsligt finner de sina själar bundna till ruttnande kroppar. Vissa anpassar sig under Aramis Hammerhands ledning, medan andra övermannas av skräck och förvirring och flyr ut i Tirisfals vildmark i stället för att möta sin mörka nya tillvaro."},{t="En barmhärtig befrielse",b="Aramis Hammerhand hoppas att en riddarkollega med medkänsla och förståelse kan nå den panikslagna paladinen som gömt sig i kullarna väster om kapellet. Förvandlingens tyngd driver henne tragiskt nog till fullständig galenskap. När du närmar dig går hon blint till angrepp av rädsla och vrede, så du har inget annat val än att slå ner henne. För de Fördömda vars sinnen brister vid graven är ett snabbt slut den enda återstående nåden."}},faq={{q="Vem är den skräckslagna paladinen?",a="Hon är en nyligen uppstånden Fördömd som var paladin i livet. När hon vaknade som odöd övermannades hon av fasa, och i fullständig panik flydde hon från Deathknell till de närliggande kullarna i väster.",al={"skräckslagen paladin","vem är paladinen i kullarna","vem hittar jag i coming to terms"}},{q="Varför angriper den skräckslagna paladinen?",a="Hon har vaknat som den sorts varelse hon en gång bekämpade och är skräckslagen och oförmögen att acceptera sin nya tillvaro. Aramis varnar för att vissa nyuppståndna paladiner blir våldsamma och ber dig närma dig henne med medkänsla.",al={"varför blir hon fientlig","varför angriper hon","kan man rädda den skräckslagna paladinen"}},{q="Vem ger uppdraget Coming to Terms?",a="Aramis Hammerhand, en paladinmentor i kyrkan i Deathknell, ger uppdraget till nyuppståndna riddare som behöver förstå hur skört sinnestillståndet är hos deras återuppståndna gelikar.",al={"uppdragsgivare coming to terms","aramis hammerhand uppdrag","var börjar coming to terms"}},{q="Kan de Fördömda fortfarande använda Ljuset?",a="Ja. Återuppståndna paladiner som Aramis Hammerhand tjänar fortfarande Ljuset, och han hoppas kunna leda även nyuppståndna paladiner tillbaka till det.",al={"odöda paladiner ljuset","använder fördömda paladiner ljuset","odöda använder ljuset"}},{q="Var finns den skräckslagna paladinen?",a="Hon flydde rakt västerut från kyrkan i Deathknell och gömmer sig bland de skogsklädda kullarna med utsikt över bosättningen.",al={"den skräckslagna paladinens plats","var är hon","var i deathknell"}},{q="Vad händer när du har slutfört Coming to Terms?",a="Du återvänder till Aramis Hammerhand och berättar om ditt försök att hjälpa den skräckslagna paladinen. Därefter hänvisar han dig till fortsatt träning för att vässa din disciplin som Fördömd paladin.",al={"nästa uppdrag efter coming to terms","efter coming to terms"}}},fx={ea9eba60={q="Varför skickar Aramis Hammerhand dig på det här uppdraget?",a="Aramis Hammerhand förstår hur plågsamt det är för fallna heliga krigare att vakna som odöda. Paladiner tillbringade sina liv som dödliga med att strida mot Scourge, så det är nästan omöjligt att förlika sig med sin egen uppståndelse. Aramis hoppas kunna rädda en nyuppstånden syster med medkänsla och lyssna med förståelse för att vägleda henne tillbaka till ljuset innan förtvivlan och vansinne slukar henne helt.",al={"aramis hammerhands motiv","varför hjälpa en rädd paladin","varför vill aramis få detta gjort"}}},fp="15,145,21.309.0,18.353.1,30.142.0,39.197.1,36.165.0,35.120.0,40.102.0,46.174.1"}
P.entries["quest:91209"] = {n="Continue Your Training",s="Det här uppdraget skickar nyväckta Forsaken-paladiner från Deathknell till Brill för avancerad träning. På uppdrag av Aramis Hammerhand får den unga heliga krigaren möta Tirisfal Glades större faror. Resan är också en tydlig varning om den djupa misstänksamhet som möter heliga utövare bland de odöda.",h="Det här uppdraget skickar nyväckta Forsaken-paladiner från Deathknell till Brill för avancerad träning.",kw={"aramis hammerhand","brill","continue your training","deathknell","forsaken-paladin","heliga ljuset","shari stilwell","tirisfal glades"},ang={["class:Paladin"]="För en odöd paladin är den här övergången en nykter påminnelse om att bruket av helig kraft gör dig till en främling även bland dina egna Forsaken.",["race:Undead"]="Uppdraget belyser spänningarna inom Forsaken-samhället, där lojaliteten till Lordaerons jord står mot det kvarlevande traumat kring det Heliga Ljuset."},sec={{t="Lämna Deathknell",b="När en nyväckt själ har lärt sig grunderna i strid och kanaliserat helig kraft på Deathknells avskilda kyrkogård skickar Aramis Hammerhand dem österut, ut i Tirisfal Glades vidsträckta marker. Målet är Brill, en livlig utpost som fungerar som administrativt centrum för centrala Tirisfal. Där leder Shari Stilwell vidareutbildningen av dem som vågar gå paladinens väg i odödligt tillstånd."},{t="Ett vanskligt kall",b="Aramis ger några sista råd som understryker hur svår situationen är för en odöd paladin. Lordaeron behöver fortfarande försvarare mot yttre hot, men den som brukar det Heliga Ljuset under Sylvanas Windrunners fana möts av bitter misstänksamhet. Otaliga Forsaken har lidit plågor eller dött för heliga fanatikers hand, och blotta närvaron av Ljuset väcker misstro bland deras odöda likar."}},faq={{q="Vem ger uppdraget och var hittar jag dem?",a="Uppdraget ges av Aramis Hammerhand, paladintränaren i Deathknell i Tirisfal Glades.",al={"uppdragsgivare","var börjar uppdraget","aramis hammerhand plats"}},{q="Var lämnar jag in Continue Your Training?",a="Du lämnar in uppdraget till Shari Stilwell, paladintränaren i Brill, längs huvudvägen strax öster om Deathknell.",al={"var lämna in","shari stilwell plats","inlämningsplats"}},{q="Varför misstror Forsaken paladiner?",a="Många Forsaken hyser djupt rotat agg mot det Heliga Ljuset, både för plågorna det orsakar odöda kroppar och för den brutala förföljelsen från heliga ordnar som Scarlet Crusade. Den som går paladinens väg kommer obekvämt nära krafter som de flesta odöda fruktar eller avskyr.",al={"varför hatar odöda paladiner","fördomar mot forsaken-paladiner","närhet till ljuset"}},{q="Kan alla Forsaken-klasser ta det här uppdraget?",a="Nej. Det här uppdraget är uttryckligen övergångsuppdraget för Forsaken-paladiner som lämnar Deathknells startområde för den större världen vid Brill.",al={"är uppdraget bara för paladiner","klasskrav"}},{q="Vad är Brill?",a="Brill är en viktig ort i centrala Tirisfal Glades och det främsta navet för Forsaken-resenärer, vakter och handelsfolk, strax norr om Undercitys ruiner.",al={"vad är brill","brills historia"}},{q="Vilka hot står Lordaeron inför enligt Aramis?",a="Trots att Lordaeron ligger i ruiner hotas det ständigt av härjande rester av Scourge, fientligt vilt och hämndlystna levande grupper som Scarlet Crusade.",al={"hot mot lordaeron","varför skydda lordaeron"}}},fx={["1d15ea77"]={q="Varför vill Aramis Hammerhand att jag åker till Brill?",a="Aramis inser att Deathknell inte längre har något att lära dig. Lordaeron har fallit i ruiner, men de Förfallna måste försvara sitt återtagna hem mot otaliga faror, och det kräver fullt förberedda hjältar. För att vässa din heliga disciplin och överleva i ett rike där dina bröder och systrar betraktar ljuset du brukar med djup misstänksamhet måste du fortsätta din träning hos Shari Stilwell i Brill.",al={"varför skicka mig till brill","aramis hammerhands motiv","varför fortsätta din träning"}}},fp="22,218,18.305.0,20.331.0,46.72.0,42.105.0,38.188.0,39.83.0,14.143.0,53.137.0"}
P.entries["quest:91282"] = {n="A Second Home",s="A Second Home är en inbjudan till nyligen återuppväckta Forsaken att ansluta sig till en ny orden i Tirisfal Glades. Den leder de nya till Bandarion Keep, ett kloster på klipporna nordväst om Solliden Farmstead, nära Whispering Woods. Initiativet ska ge gemenskap, delad tro och ömsesidigt stöd åt dem som skapar sig en plats i sitt nya odöda liv.",h="A Second Home är en inbjudan till nyligen återuppväckta Forsaken att ansluta sig till en ny orden i Tirisfal...",kw={"a second home","bandarion keep","forsaken orden","kloster","solliden farmstead","tirisfal glades","whispering woods"},ang={["faction:Horde"]="Starkare band mellan Forsaken i Tirisfal Glades hjälper till att befästa Hordens närvaro i de norra delarna av Eastern Kingdoms.",["race:Undead"]="Nyligen återuppväckta Forsaken känner sig ofta vilsna efter att ha brutit sig fria från Scourge. En orden grundad på gemenskap och delad tro ger dem en sällsynt chans att bygga upp sina liv på nytt."},sec={{t="En samling återuppväckta",b="A Second Home är en första uppmaning till nyligen återuppväckta Forsaken som försöker finna fotfäste i Tirisfal Glades. I stället för att vandra ensamma genom det dystra odöda livet uppmuntras de nyvakna att söka gemenskap bland sina likar och förlita sig på gemensam tro och samhörighet för att nå sin fulla potential."},{t="En fristad på klipporna",b="Inbjudan leder resande mot Bandarion Keep, ett kloster på de karga klipporna nordväst om Solliden Farmstead. Denna fästning ligger högt intill det gåtfulla Whispering Woods och erbjuder en tillflyktsort där medlemmarna i den nybildade orden kan studera, öva och slå rot i Tirisfals marker."}},faq={{q="Vad är uppdraget A Second Home?",a="A Second Home är en inbjudan till nyligen återuppväckta Forsaken att ansluta sig till en nybildad klassorden i Tirisfal Glades. Den hänvisar sökare till ett avskilt kloster där likasinnade samlas för att skapa gemenskap och utforska sin gemensamma potential.",al={"vad är a second home","uppdraget a second home","a second home uppdrag"}},{q="Var finns Bandarion Keep?",a="Bandarion Keep ligger på klipporna strax nordväst om Solliden Farmstead i Tirisfal Glades, precis vid kanten av Whispering Woods.",al={"var ligger bandarion keep","bandarion keep plats","hur tar man sig till bandarion keep"}},{q="Vem grundade klostret i Bandarion Keep?",a="Fästningen fungerar som kloster för Tyr's Watch, en paladinorden för Forsaken i Tirisfal Glades. Orden betonar gemenskap och delad tro för nyuppväckta bröder och systrar.",al={"vem leder bandarion keep","vem grundade bandarion keep","bandarion keep orden"}},{q="Varför bjuds Forsaken in till Bandarion Keep?",a="Grundarna tror att nyuppväckta odöda bara kan nå sin fulla potential genom gemenskap och ett gemensamt syfte. Därför erbjuder de Bandarion Keep som en fristad och läroplats för sin orden.",al={"varför bege sig till bandarion keep","bandarion keep syfte"}},{q="Hur hänger platsen ihop med Solliden Farmstead?",a="Solliden Farmstead ligger i västra Tirisfal Glades och är landmärket strax sydost om klipporna, där Bandarion Keep blickar ut över kanten av Whispering Woods.",al={"var ligger solliden farmstead","solliden farmstead bandarion"}},{q="Vad är det för orden som samlas i Bandarion Keep?",a="Orden i Bandarion Keep är Tyr's Watch, en nybildad paladinorden för Forsaken som vill stödja sina fränder när de anpassar sig till sitt nya odöda liv.",al={"vilken orden finns i bandarion keep","bandarion keep klassorden"}}},fp="13,304,24.189.0,23.219.0,32.208.0,34.120.0,48.159.0,53.176.0,49.144.0,50.144.0"}
P.entries["quest:91285"] = {n="Murlocs at the Gates",s="Breton Samuels ber dig driva tillbaka murlocs som härjar vid borgen. Deras anfall försvårar återuppbyggnaden.",h="Breton Samuels ber dig driva tillbaka murlocs som härjar vid borgen.",kw={"anfallare","breton samuels","borg","murloc","murlocs at the gates","siare","lekplatser","vile fin"},sec={{t="Murlocproblemet",b="Murlocerna härjar fortfarande vid borgen efter att du och de andra drev bort dem från deras lekplatser. Deras anfall blir allt svårare att hantera, så Breton Samuels ber dig driva tillbaka några av dem. De lurar bland klipporna längs den östra vägen och i läger runt sjön i väster."},{t="Anfallen",b="Breton Samuels räknar med att anfallen fortsätter. Han hoppas att murlocerna hejdas om Vile Fin-anfallarna och siarna drivs tillbaka. Borgen är redan svår att återuppbygga medan murlocerna anfaller dess invånare."}},faq={{q="Vem ber om hjälp?",a="Breton Samuels ber dig driva tillbaka några av murlocerna som härjar vid borgen.",al={"vem ger detta","breton samuels","vem vill ha hjälp"}},{q="Varför är murlocerna ett problem?",a="Murlocerna har härjat vid borgen sedan dess invånare drev bort dem från deras lekplatser. Deras anfall blir allt svårare att hantera.",al={"varför murlocs","murlocproblem","vad gör de"}},{q="Var finns murlocerna?",a="De lurar bland klipporna längs vägen i öster och i läger runt sjön i väster.",al={"var finns murlocs","murlocernas plats","var finns de"}},{q="Vilka murlocs är inblandade?",a="Vile Fin-anfallarna och Vile Fin-siarna härjar vid borgen.",al={"murloctyper","vile fins","vem ska bekämpas"}},{q="Varför behöver borgen hjälp?",a="Borgen håller på att återuppbyggas, och murlocernas anfall försvårar arbetet.",al={"varför hjälpa","borgens återuppbyggnad","vad står på spel"}}},fp="20,103,18.283.0,11.195.0,23.77.0,30.136.0,22.92.0,27.65.0,28.68.0"}
P.entries["quest:91294"] = {n="Touring the Grounds",s="Breton ber dig att gå runt i Bandarion Keep när murlocattackerna är under kontroll. Att träffa Danitha Morr är ditt första steg mot att finna dig till rätta bland invånarna.",h="Breton ber dig att gå runt i Bandarion Keep när murlocattackerna är under kontroll.",kw={"bandarion keep","breton","danitha morr","området","light","murlocattacker","invånare"},sec={{t="I fästet",b="Breton ber dig att träffa invånarna i Bandarion Keep och se dig omkring i fästet. När du är klar kan Danitha Morr hjälpa dig att finna dig till rätta. Fästet är fortfarande litet, men invånarna kallar det sitt hem."},{t="En befälhavare",b="Danitha Morr presenterar sig som det närmaste Bandarion Keep har en befälhavare. Hon välkomnar dem som söker gemenskap med människor som fortfarande är trogna Light. Fästet behöver hjälp innan det kan vara fullt etablerat."}},faq={{q="Vem ber mig att se mig omkring?",a="Breton uppmuntrar dig att utforska Bandarion Keep när murlocattackerna är under kontroll.",al={"vem skickade runt mig","breton se sig omkring"}},{q="Vem leder Bandarion Keep?",a="Danitha Morr är det närmaste Bandarion Keep har en befälhavare.",al={"vem är danitha","fästets ledare"}},{q="Varför ska jag prata med Danitha Morr?",a="Danitha Morr kan hjälpa dig att finna dig till rätta bland fästets invånare.",al={"vart ska jag efter rundturen","prata med danitha"}},{q="Hur är Bandarion Keep?",a="Bandarion Keep är ett litet fäste som invånarna kallar sitt hem.",al={"hur är fästet","bandarion keep"}},{q="Vem är välkommen i fästet?",a="Danitha välkomnar dem som söker gemenskap med människor som förblir trogna Light.",al={"vem kan ansluta sig","trogen light"}}},fp="19,160,11.199.0,11.219.0,32.92.0,25.68.0,35.65.0,28.66.0,27.84.0"}
P.entries["quest:913"] = {n="Cry of the Thunderhawk",s="Cry of the Thunderhawk är höjdpunkten i Jorn Skyseers jaktprov i södra The Barrens. På de äldstes uppdrag från Camp Taurajo måste en jägare söka upp en bevingad orm som svävar över buskmarkerna och föra tillbaka dess vingar som bevis på sin skicklighet bland savannens vildaste bestar.",h="Cry of the Thunderhawk är höjdpunkten i Jorn Skyseers jaktprov i södra The Barrens.",kw={"jakt i the barrens","camp taurajo","cry of the thunderhawk","jorn skyseer","thunderhawk","thunderhawk wings","bevingad orm"},ang={["class:Hunter"]="Att fälla en luftburen orm som thunderhawk prövar din disciplin med avståndsvapen och ditt tålamod. Det är en formell övergångsrit på vägen mot verklig mästarkunskap om slätterna.",["faction:Horde"]="Att tämja och säkra den farliga gränsbygden kring Camp Taurajo skyddar Horde-resenärer som färdas längs huvudvägen genom The Barrens.",["race:Tauren"]="För Shu'halo är jakten på den svävande thunderhawken ett heligt prov på respekt och ära. Den visar att jägaren kan stå i förbindelse med och mäta sig mot Earthmothers snabbaste barn."},sec={{t="Jaktprovets höjdpunkt",b="Efter att ha visat sitt mod mot strövande plainstriders, prowlers och uppretade thunder lizards får jägarna i The Barrens sin största utmaning av Jorn Skyseer. Thunderhawk räknas till de våldsammaste luftrovdjuren i buskmarkerna kring Camp Taurajo. Att fälla en kräver tålamod, skarpt sikte och en blick för himlen som få landbundna rovdjur har."},{t="En jägares vandring",b="När en jägare återvänder med thunderhawkens vingar är novisens utbildning under Camp Taurajos vaksamma blick över. För tauren är jakt inte bara slakt, utan en ständig andlig vandring i harmoni med Earthmother och vildmarkens naturliga ordning. Att övervinna en så stolt varelse visar att jägaren handlar med styrka, mod och ära, dygder som krävs innan färden går vidare ut i den kargare vildmarken bortom de centrala slätterna."}},faq={{q="Vad är en thunderhawk?",a="Thunderhawks är bevingade, ormformade rovdjur som hör hemma i The Barrens. De glider över de torra slätterna och jagar mindre byten ovanifrån. Med blixtsnabba attacker och sin förmåga att röra sig i luften härskar de över himlen kring Camp Taurajo.",al={"vad är thunderhawks","thunderhawk-varelse","flygande orm i the barrens"}},{q="Vem ger det här uppdraget?",a="Jorn Skyseer, en respekterad taurenjägare stationerad i Camp Taurajo i södra The Barrens, ger dig det här provet när du har bevisat dig mot områdets ursinniga thunder lizards.",al={"vem startar cry of the thunderhawk","uppdragsgivare"}},{q="Var finns thunderhawks?",a="De rör sig över den öppna himlen och bland de klippiga höjderna i södra The Barrens. De svävar främst över slätterna vid vägarna norr och väster om Camp Taurajo.",al={"var hittar man thunderhawks","thunderhawk-plats"}},{q="Vad betyder det för tauren att ta vingarna?",a="Att visa upp de avhuggna vingarna är ett konkret bevis på en ren och hedervärd jakt. I taurenkulturen visar troféer från farligt byte att jägaren behärskar besten och samtidigt erkänner den fallna varelsens stolthet och vildhet.",al={"varför ta med vingarna","thunderhawk wings betydelse"}},{q="Vart leder jaktprovet härnäst?",a="När du slutför Jorn Skyseers prov avslutas din utbildning i Camp Taurajo. Jorn skickar dig vidare till sin syster Mahren Skyseer, som jagar längs The Barrens östkust söder om Ratchet.",al={"vad händer efter cry of the thunderhawk","nästa uppdrag efter thunderhawk"}},{q="Hur hänger det här ihop med Sergra Darkthorn i The Crossroads?",a="Det här provet är den södra delen av de övergripande jaktriter som började hos Sergra Darkthorn i The Crossroads. När lovande jägare har bemästrat de nordliga bestarna skickas de söderut till Camp Taurajo för att fortsätta sin utbildning under Jorn Skyseer.",al={"koppling till sergra darkthorn","jaktkedjan i the crossroads"}}},fx={["2e0d4fa8"]={q="Varför vill Jorn Skyseer att detta blir gjort?",a="Jorn Skyseer prövar din styrka, ditt mod och din heder som jägare. Efter att ha väglett dig genom prövningarna i södra The Barrens ställer han den vilda åskhöken framför dig som den slutliga prövningen under hans ledning. Om du fäller ett så stolt rovdjur visar du att du är redo att avsluta din tid vid Camp Taurajo och ge dig ut på den vidare vägen som sann jägare.",al={"jorn skyseers motiv","varför döda åskhöken","syftet med åskhökjakten"}}},fp="22,295,15.413.0,15.441.0,22.232.0,21.184.0,29.153.0,51.246.0,40.202.0,60.256.0"}
P.entries["quest:91316"] = {n="Making Repairs",s="Brist på byggmaterial har gjort det svårt att återställa fästningen. Du skickas till Shadowvale för att leta efter virke.",h="Brist på byggmaterial har gjort det svårt att återställa fästningen.",kw={"byggmaterial","fästning","utföra reparationer","jordkällare","shadowvale","kraftigt virke","undercity","whispering forest"},sec={{t="Förnödenheter i Shadowvale",b="Shadowvale är en by i ruiner i Whispering Forest, sydväst om fästningen. Sök igenom en gammal jordkällare i en av byggnaderna efter användbart material. Fästningen ligger långt från bebodda trakter, så det är svårt att föra dit förnödenheter. Reparationerna är beroende av vad som går att hitta där."}},faq={{q="Varför behövs byggmaterial?",a="Fästningen behöver byggmaterial för att kunna återställas. Avståndet till Undercity gör det svårt att få fram förnödenheter.",al={"varför behövs virke","reparationer av fästningen"}},{q="Var ligger Shadowvale?",a="Shadowvale ligger i ruiner i Whispering Forest, sydväst om fästningen.",al={"shadowvales läge","var ligger byn"}},{q="Var kan det finnas användbart material?",a="Användbart material kan finnas förvarat i en gammal jordkällare i en av Shadowvales byggnader.",al={"material i jordkällaren","var leta"}},{q="Vad har fästningen brist på?",a="Fästningen har brist på byggmaterial som behövs för att återställa den.",al={"vilka förnödenheter saknas","virkesbrist"}}},fp="14,130,22.282.0,34.127.0,20.77.0,38.86.0,30.71.0"}
P.entries["quest:91317"] = {n="The Tarnished",s="I Shadowvale i Tirisfal Glades hotar Tarnished en nybildad ordens plats bland Forsaken. Deras attacker fördjupar misstron och äventyrar ordens framtid.",h="I Shadowvale i Tirisfal Glades hotar Tarnished en nybildad ordens plats bland Forsaken.",kw={"commander rudolph gelhardt","nybildad orden","forsaken","misstro","shadowvale","tarnished drudges","tarnished zealots","tarnished","tirisfal glades"},ang={["faction:Horde"]="Orden hoppas få en plats inom Horde, men dess ledare räknar med att det kan ta år eller årtionden innan orden accepteras.",["race:Undead"]="Som Forsaken ställs du mot återuppväckta som attackerar sitt eget folk. Deras våld ökar misstron mot en nybildad orden."},sec={{t="En fläckad orden",b="Vissa återuppväckta bär fortfarande på fördomar från sina tidigare liv och attackerar nu andra Forsaken. Tarnished har samlats i Shadowvale, sydväst om den här platsen. Deras våld måste få ett slut, och Commander Rudolph Gelhardts huvud måste föras tillbaka."},{t="En plats bland dem",b="Attackerna från Tarnished ger dem som misstror orden fler skäl att vända sig mot den. Att stoppa dem kan hjälpa orden att vinna en plats bland Forsaken. Det kan ändå ta år eller årtionden innan orden blir accepterad."}},faq={{q="Vilka är Tarnished?",a="Tarnished är återuppväckta som behållit fördomar från sina tidigare liv och nu attackerar andra Forsaken.",al={"tarnished vilka","vilka är dessa tarnished"}},{q="Var finns Tarnished?",a="Ett antal Tarnished har slagit sig ner i Shadowvale, sydväst om den här platsen i Tirisfal Glades.",al={"tarnished plats","var finns tarnished"}},{q="Varför är Tarnished ett hot?",a="Deras attacker mot andra Forsaken fördjupar misstron mot orden bland Forsaken.",al={"varför stoppa tarnished","tarnished attacker"}},{q="Vem leder Tarnished?",a="Commander Rudolph Gelhardt leder Tarnished.",al={"tarnished ledare","rudy gelhardt"}},{q="Varför behöver orden vinna Forsakens förtroende?",a="Orden möts av misstro eftersom Forsaken minns hur de levande förföljde dem i Lights namn. Attackerna från Tarnished fördjupar den misstron.",al={"ordens förtroende","forsakens misstro"}}},fp="13,168,17.244.0,18.203.0,22.99.0,24.91.0,31.81.0,24.47.0,45.153.0"}
P.entries["quest:914"] = {n="Leaders of the Fang",s="Leaders of the Fang är ett avgörande Horde-uppdrag från Nara Wildmane på Thunder Bluff. Det leder äventyrare in i Wailing Caverns för att döda de fyra ledarna för de korrumperade Druids of the Fang och hämta deras förvridna drömädelstenar. Att stoppa dessa avfälliga druider är avgörande för att hindra deras ormaktiga mardröm från att för evigt ta över The Barrens.",h="Leaders of the Fang är ett avgörande Horde-uppdrag från Nara Wildmane på Thunder Bluff.",kw={"anacondra","barrens","cobrahn","drömädelstenar","leaders of the fang","nara wildmane","pythas","serpentis","wailing caverns"},ang={["class:Druid"]="För taurendruider är uppdraget djupt personligt. Att se naturens tjänare förvrida The Emerald Dream till en giftig farsot är en outhärdlig kränkning av Cenarions principer.",["faction:Horde"]="The Barrens är en livsviktig knutpunkt som förbinder Orgrimmar, Thunder Bluff och Darkspearöarna. Om en fanatisk sekt av ormdyrkare tillåts förvandla landet hotas hela Hordes stabilitet.",["race:Tauren"]="Jordmoderns hälsa är central i taurernas tro, så den onaturliga korrumpering som sipprar från källorna i The Barrens är en direkt skändning av landet de vandrar över."},sec={{t="En korrumperad vision",b="Nattalven och druiden Naralex begav sig in i de underjordiska källorna i Wailing Caverns med en osjälvisk ambition: att använda The Emerald Dream för att återställa grönskan i det torra The Barrens. Tragiskt nog blev hans dröm en vaken mardröm när han föll i sömn. Acolyterna som följde honom förlorade sin hängivenhet till naturens harmoni, dukade under för mardrömmens korrumpering och antog namnet Druids of the Fang."},{t="De fyra drömädelstenarna",b="För att forma om The Barrens till sitt eget huggormsparadis kanaliserar den splittrade sektens ledare de förvridna drömkrafterna genom särskilda fokusföremål som kallas drömädelstenar. Lord Cobrahn, Lady Anacondra, Lord Pythas och Lord Serpentis bär varsin sådan ädelsten. Så länge dessa föremål är i deras händer sprider sig deras korrumperande inflytande ut i Kalimdors jord och vatten."},{t="En börda lyfts i Thunder Bluff",b="Nara Wildmane vakar över naturens balans från Thunder Bluff och känner den andliga plåga som strömmar från grottorna direkt in i hennes sinne. Genom att jaga rätt på de fyra ormherrarna och ta deras ädelstenar krossar Horde-hjältar sektens befälsstruktur, befriar taurendruiden från de kvarvarande mardrömmarna och räddar de omgivande slätterna från en onaturlig farsot."}},faq={{q="Vilka är ledarna för Druids of the Fang?",a="Sekten leds av fyra fallna druider: Lady Anacondra, Lord Cobrahn, Lord Pythas och Lord Serpentis. Var och en har övergett sina ursprungliga naturläror för att anta ormgestalt och kanalisera mardrömsmagi i Wailing Caverns.",al={"namn på leaders of the fang","bossar i wailing caverns","vem leder druids of the fang"}},{q="Vad är drömädelstenarna?",a="Drömädelstenarna är kanaler som var och en av de fyra ledarna bär på sig i Wailing Caverns. De fokuserar de förvridna, mardrömsbesmittade energierna som läcker från Naralex sömn och driver sektens försök att förändra The Barrens.",al={"vad är ädelstenarna","gem of cobrahn","berättelsen om drömädelstenarna"}},{q="Varför vill Nara Wildmane ha ädelstenarna?",a="Nara Wildmane är en taurendruid i Thunder Bluff som känner mardrömmens psykiska och andliga svallvågor. De korrumperade ledarnas ansikten hemsöker hennes drömmar, och hon måste bryta deras makt för att skydda både sitt förstånd och The Barrens framtid.",al={"vem är nara wildmane","varför döda ledarna","nara wildmanes motiv"}},{q="Var Druids of the Fang alltid onda?",a="Nej. Ursprungligen var de ädla nattalvsdruider som följde Naralex in i grottorna i hopp om att läka den torra savannen. När Naralex föll i en mardröm förvrängde energierna deras sinnen och förvandlade dem till en fanatisk ormkult.",al={"druids of the fangs ursprung","varför blev druiderna onda","naralex lärjungar"}},{q="Var lämnas uppdraget in?",a="Uppdraget börjar och slutar hos Nara Wildmane på Elder Rise i Thunder Bluff. När du har samlat alla fyra ädelstenarna i Wailing Caverns måste du resa tillbaka till Mulgore och lämna över dem till henne.",al={"lämna in leaders of the fang","var finns nara wildmane","lämna in fangens ledare"}},{q="Blir Naralex frisk om ledarna dödas?",a="När de fyra ledarna dödas krossas sektens högsta ledning och deras ritual hejdas, men det väcker inte Naralex av sig självt. Andra druidiska riter längre in i grottorna krävs för att väcka den sovande mästaren.",al={"räddar detta naralex","effekten av att döda ledarna"}}},fx={["5ca16cf2"]={q="Varför vill Nara Wildmane att Druids of the Fang dödas?",a="Druids of the Fang är tidigare druider från Cenarion Circle som försökte återställa The Barrens grönska, men deras sinnen förvrängdes av Emerald Nightmare. Nu vill de omforma landet till sitt eget förvridna drömlandskap. Deras fördärv plågar Naras egna tankar och drömmar, och hon fruktar att hela The Barrens går en mörk och förbannad framtid till mötes om inte deras fyra ledare dödas och deras inflytande bryts.",al={"nara wildmanes motiv","varför döda druids of the fang","varför vill nara ha dem döda"}}},fp="19,265,18.326.0,19.322.0,32.311.1,46.234.0,24.186.0,37.203.0,40.228.0,30.165.0,38.203.0"}
P.entries["quest:91488"] = {n="Home on the Range",s="Vid Valormok i Azshara behöver Kurll Mosshoof Hides för att laga sitt tält. Sedan det skadades i en skärmytsling med blood elves har han varit utsatt för väder och vind.",h="Vid Valormok i Azshara behöver Kurll Mosshoof Hides för att laga sitt tält.",kw={"azshara","blood elves","hemma på vidderna","kurll","mosshoof","mosshoof hides","tält","valormok"},sec={{t="Ett tak igen",b="Kurlls tält vid Valormok skadades i en skärmytsling med blood elves. I tre nätter har han saknat skydd mot väder och vind. Han behöver Mosshoof Hides för att laga det, men sömnbristen hindrar honom från att jaga. Ta med fem hudar till honom, så kan han sova under tak igen."}},faq={{q="Vem är Kurll?",a="Kurll finns vid Valormok i Azshara, där hans tält behöver lagas.",al={"kurll","kurll valormok"}},{q="Varför behöver Kurll Mosshoof Hides?",a="Kurll behöver Mosshoof Hides för att laga sitt tält, som skadades i en skärmytsling med blood elves.",al={"varför hudar","mosshoof hides kurll"}},{q="Hur många hudar behöver Kurll?",a="Kurll ber dig ta med fem Mosshoof Hides till honom.",al={"hur många hudar","5 hudar"}},{q="Var hittar jag mosshooves?",a="Kurll säger att de mosshooves som är lättast att jaga finns väster och söder om Valormok. Huden från vilken mosshoof som helst duger.",al={"mosshooves","var mosshoof"}},{q="Hur länge har Kurll saknat skydd?",a="Kurll säger att han har varit utlämnad åt väder och vind i tre nätter.",al={"kurll utan tält","tre nätter"}}},fp="17,158,12.282.0,13.61.0,35.96.0,31.48.0,28.107.0,40.69.0"}
P.entries["quest:91497"] = {n="Seals of the Sin'dorei",s="Rimtoris officerare kan bära tre sigill som behövs för Sin'doreis besvärjelse. Du tar dem till Tome of Summoning, där deras märken kan jämföras med texten.",h="Rimtoris officerare kan bära tre sigill som behövs för Sin'doreis besvärjelse.",kw={"kristaller","rimtori","seal of the ranger","seal of the warden","seal of the warrior","sin'doreis sigill","tome of summoning"},sec={{t="Tre märken",b="Tome of Summoning ligger uppslagen framför dig och beskriver Rimtoris besvärjelse. Du ombeds hämta Seal of the Warden, Seal of the Warrior och Seal of the Ranger. Deras märken sägs passa olika sorters färdigheter, och Rimtoris officerare kan bära dem. Sigillen är viktiga för besvärjelsen som tar form kring kristallerna."},{t="Tomens tecken",b="Vid boken ser du att varje sigill stämmer med märkena som beskrivs på dess sidor. Kristallerna svarar med pulserande kraft, och synen väcker en vårdslös idé i dig."}},faq={{q="Vilka sigill behöver boken?",a="Seal of the Warden, Seal of the Warrior och Seal of the Ranger ska lämnas till Tome of Summoning.",al={"tre sigill","vilka sigill","sin'doreis sigill"}},{q="Hur ser sigillen ut?",a="Sigillet på den första kristallen har ett svärd, det på den mittersta en glaive och det på den sista en klo.",al={"sigillmärken","svärd glaive klo","vilka symboler"}},{q="Vem kan kanalisera det första sigillet?",a="Energin i sigillet med svärdsmärket kräver en erfaren krigare.",al={"svärdssigill","krigarsigill","första kristallen"}},{q="Vem kan kanalisera det mittersta sigillet?",a="Energin i sigillet med glaivemärket kräver någon som behärskar både kampkonst och magi.",al={"glaivesigill","mittersta kristallen","andra sigillet"}},{q="Vem kan kanalisera det sista sigillet?",a="Energin i sigillet med klomärket kräver någon som känner sig hemma i vildmarken.",al={"klosigill","sista kristallen","jägarsigill"}},{q="Varför ta sigillen från Rimtoris officerare?",a="Rimtoris officerare kan bära sigillen för att hjälpa hennes besvärjelse, så om du tar dem ställer du till problem för henne.",al={"rimtoris sigill","officerare som bär sigill","varför stjäla sigill"}}},fp="22,164,11.329.0,16.168.1,30.104.0,30.102.0,31.59.0,32.91.0,30.70.0,43.98.0"}
P.entries["quest:91500"] = {n="An Explosive Gambit",s="Du bedömer att om du bryter Sin'dorei-sigillen kan kristallerna utlösas, så att du får en chans att anfalla Magus Rimtori. Ag'tor Bloodfist i Valormok väntar på bevis för att hon är död.",h="Du bedömer att om du bryter Sin'dorei-sigillen kan kristallerna utlösas, så att du får en chans att anfalla...",kw={"ag'tor bloodfist","en explosiv chansning","kristaller","magus rimtori","sin'dorei-sigillen","andar","valormok"},sec={{t="Ett välberäknat anfall",b="Kristallernas energier svarar på sigillen, och du ser ett sätt att vända det bandet mot Magus Rimtori. Om du bryter ett sigill kan dess energi frigöras genom kristallen i en våldsam explosion. Smällen kan överraska Rimtori och ge dig en öppning att anfalla henne."},{t="I Valormok",b="Ag'tor Bloodfist ber dig bryta Sin'dorei-sigillen och ta med Magus Rimtoris huvud till honom. Han kallar blodalverna förrädare och säger att Rimtori förtjänar en plågsam död. När du återvänder säger han att Belgrom kommer att bli nöjd och att dussintals krigares andar äntligen kan få ro."}},faq={{q="Vad ska jag göra?",a="Du ombeds bryta Sin'dorei-sigillen och sedan ta Magus Rimtoris huvud till Ag'tor Bloodfist i Valormok.",al={"vad ska jag göra","sigill och rimtori","bryt sigillen"}},{q="Varför bryta sigillen?",a="Du drar slutsatsen att om du bryter ett sigill kan dess energi frigöras genom kristallen i en explosion.",al={"varför bryta sigillen","kristallexplosion","vad gör sigillen"}},{q="Vem vill se Rimtori död?",a="Ag'tor Bloodfist ber dig ta Magus Rimtoris huvud till honom och säger att hon förtjänar en plågsam död.",al={"vem skickade mig","ag'tor bloodfist","varför döda rimtori"}},{q="Var ska jag ta Rimtoris huvud?",a="Ta Magus Rimtoris huvud till Ag'tor Bloodfist i Valormok.",al={"var finns ag'tor","vart ska jag ta huvudet","lämna in i valormok"}},{q="Varför nämner Ag'tor andarna?",a="Ag'tor säger att dussintals krigares andar äntligen kan få ro.",al={"krigarnas andar","vilka får ro","varför tacka mig"}}},fp="19,172,19.259.0,11.278.1,25.108.0,20.93.0,23.98.0,32.59.0,36.70.0"}
P.entries["quest:91531"] = {n="Revenge Exacted",s="Belgrom Rockmaul i Orgrimmar ber dig hämta Magus Rimtoris huvud från Azshara. Han vill se det med egna ögon.",h="Belgrom Rockmaul i Orgrimmar ber dig hämta Magus Rimtoris huvud från Azshara.",kw={"ag'tor","azshara","belgrom rockmaul","huvud","magus rimtori","orgrimmar","hämnd utkrävd"},sec={{t="Belgroms begäran",b="I Orgrimmar fruktar Belgrom Rockmaul att Ag'tor och de andra är döda efter att ha hört dig komma med nyheter från Azshara. Han ber dig ta med Magus Rimtoris huvud till honom, så att han kan se det med egna ögon."},{t="Ett bittert agg",b="Belgrom tittar ner i säcken och skrattar hatiskt. Han anklagar Magus Rimtori för att ha förrått honom."}},faq={{q="Vem ber om Magus Rimtoris huvud?",a="Belgrom Rockmaul i Orgrimmar ber dig hämta Magus Rimtoris huvud.",al={"vem är belgrom","belgroms begäran","orc ber om ett huvud"}},{q="Vart vill Belgrom att du tar huvudet?",a="Belgrom vill att du tar Magus Rimtoris huvud till honom i Orgrimmar.",al={"vart ska huvudet","lämna in huvudet","var belgrom finns"}},{q="Vad fruktar Belgrom efter att ha hört från Azshara?",a="Belgrom fruktar att Ag'tor och de andra är döda.",al={"ag'tor död","vad hände i azshara","belgrom orolig"}}},fp="15,120,19.197.0,18.94.1,36.75.0,46.70.0,50.50.0"}
P.entries["quest:91538"] = {n="Sin'dorei Tome of Summoning",s="Jediga ber dig ta med Rimtoris Sin'dorei Tome of Summoning till Valormok. Den mäktiga artefakten finns fortfarande ute i vildmarken.",h="Jediga ber dig ta med Rimtoris Sin'dorei Tome of Summoning till Valormok.",kw={"artefakt","belgrom","jediga","piedestal","rimtori","sin'dorei tome of summoning","kallelseboken","valormok"},sec={{t="En bok i vildmarken",b="Rimtoris bok står kvar på sin piedestal, och sidorna kan rymma hemligheter. Jediga i Valormok ber dig ta med Sin'dorei Tome of Summoning tillbaka till henne, så att den mäktiga artefakten inte lämnas kvar ute i vildmarken."}},faq={{q="Vad vill Jediga att jag ska ta med?",a="Jediga ber dig ta med Sin'dorei Tome of Summoning till henne.",al={"vilken bok","vad ska lämnas till jediga","sin'dorei-bok"}},{q="Var finns boken nu?",a="Rimtoris bok står fortfarande på sin piedestal ute i vildmarken.",al={"var är boken","bokens plats","var hittar man boken"}},{q="Varför vill Jediga ha boken?",a="Jediga vill inte att en mäktig artefakt lämnas kvar ute i vildmarken.",al={"varför ta tillbaka den","varför ta boken","vad används den till"}},{q="Vem är Rimtori?",a="Boken anges tillhöra Rimtori, men inga fler detaljer om Rimtori nämns.",al={"rimtoris bok","vem skapade boken","bokens ägare"}}},fp="27,123,19.211.0,34.61.0,22.57.0,30.59.0,15.84.0"}
P.entries["quest:91547"] = {n="Sin'dorei Tome of Summoning",s="Jediga vill hålla Sin'dorei Tome of Summoning borta från blood elves. Hon skickar dig till Zevrost i Orgrimmar för att få den dechiffrerad.",h="Jediga vill hålla Sin'dorei Tome of Summoning borta från blood elves.",kw={"blood elves","cleft of shadow","jediga","orgrimmar","sin'dorei tome","sin'dorei tome of summoning","häxmästare","zevrost"},sec={{t="En kontakt i Orgrimmar",b="I Orgrimmar visar Jediga dig till Zevrost, en häxmästare i Cleft of Shadow som kan försöka dechiffrera Sin'dorei Tome of Summoning. Du tar med dig boken till honom, medan Jediga fruktar att blood elves kan använda den för att hämnas."}},faq={{q="Vem är Zevrost?",a="Zevrost är en häxmästare i Orgrimmars Cleft of Shadow som kan försöka dechiffrera Sin'dorei Tome of Summoning.",al={"zevrost","vem är zevrost","kontakt bland häxmästare"}},{q="Varför vill Jediga hålla boken borta från blood elves?",a="Jediga fruktar att blood elves kan använda boken för att hämnas.",al={"varför hålla boken","blood elves bok","varför inte ge den till blood elves"}},{q="Vart ska jag ta Sin'dorei Tome?",a="Jediga skickar dig till Zevrost i Orgrimmars Cleft of Shadow.",al={"vart ska boken","bokens plats","ta boken till zevrost"}},{q="Vad är Sin'dorei Tome of Summoning?",a="Det är en bok som Jediga vill hålla borta från blood elves och ta till Zevrost för dechiffrering.",al={"sin'dorei tome","kallelseboken","vad är boken"}},{q="Vem skickade mig till Zevrost?",a="Jediga skickade dig till Zevrost med Sin'dorei Tome of Summoning.",al={"vem skickade mig","jediga zevrost","varför nämner zevrost jediga"}}},fp="27,132,22.226.0,15.108.0,56.61.0,35.59.0,40.100.0,23.64.0"}
P.entries["quest:91548"] = {n="Vek'zol",s="Zevrost ber dig använda en Sin'dorei Tome vid Altar of Storms i Blasted Lands. Han vill ha Vek'zols hjärta som reagens för större kraft.",h="Zevrost ber dig använda en Sin'dorei Tome vid Altar of Storms i Blasted Lands.",kw={"altar of storms","blasted lands","demon","felmagi","hjärta","reagens","sin'dorei tome of summoning","vek'zol","zevrost"},sec={{t="Zevrosts begäran",b="Zevrost studerar diagrammen i Sin'dorei Tome of Summoning, men han kan inte läsa Thalassian. Han tror att blodalverna tänkte åkalla demoner och dränera deras felmagi. Han ser en större användning för den kraften. Du ska utföra ritualen vid Altar of Storms i Blasted Lands och ta med Vek'zols hjärta till honom i Orgrimmar."}},faq={{q="Vem ber mig att åkalla Vek'zol?",a="Zevrost ber dig att åkalla Vek'zol och ta med dess hjärta till honom i Orgrimmar.",al={"vem vill ha vek'zol","zevrost åkalla demon","vem gav uppdraget"}},{q="Var ska jag åkalla Vek'zol?",a="Ritualen ska utföras vid Altar of Storms i Blasted Lands.",al={"vek'zols plats","var åkalla vekzol","altarets plats"}},{q="Varför vill Zevrost ha Vek'zols hjärta?",a="Zevrost säger att Vek'zols hjärta blir ett kraftfullt reagens.",al={"varför hjärtat","hjärta som reagens","vad behöver zevrost"}},{q="Vad finns i Sin'dorei Tome of Summoning?",a="Den innehåller diagram som Zevrost känner igen, trots att han inte talar Thalassian. Han tror att de beskriver hur man åkallar demoner för att dränera deras felmagi.",al={"sin'dorei tome","blodalvernas diagram","tome of summoning"}},{q="Vart ska jag ta med hjärtat?",a="Ta med Vek'zols hjärta till Zevrost i Orgrimmar.",al={"återvänd till zevrost","hjärtats destination","vart ta hjärtat"}}},fp="7,142,17.331.0,35.75.0,26.74.0,38.56.0,43.146.0,27.46.0"}
P.entries["quest:91568"] = {n="Long Walks on the Beach",s="Izvi Glidfizz i Valormok ber dig söka efter Highborne-skattfragment på östra stranden. Hon hoppas att fynden ska ge vinst, även om de är mer värda som metall än som fornföremål.",h="Izvi Glidfizz i Valormok ber dig söka efter Highborne-skattfragment på östra stranden.",kw={"strandskatt","östra stranden","goblin","highborne-skattfragment","izvi glidfizz","naga","treasure trowel 3000","valormok"},sec={{t="En sökning längs stranden",b="Izvi Glidfizz i Valormok har en spade som hon själv har tillverkat och en plan för östra stranden. Ruinerna där har plundrats på allt, men hon tror att värdefulla fragment finns kvar under sanden. Naga gör en lång sökning opraktisk, så hon skickar dig med Treasure Trowel 3000 för att samla ihop det du kan. Hon hoppas kunna dela vinsten med dig."},{t="Fyndet",b="Izvi blir glad över det du kommer tillbaka med. Hon säger att fragmenten kanske inte hittar några köpare som fornföremål, men att metallen fortfarande kan smältas ner och säljas. Treasure Trowel 3000 klarade också sökandet, till hennes lättnad."}},faq={{q="Vem är Izvi Glidfizz?",a="Izvi Glidfizz är goblinen i Valormok som uppfann Treasure Trowel 3000 och ber dig söka längs östra stranden.",al={"izvi","vem är goblinen","izvi glidfizz"}},{q="Vad är Treasure Trowel 3000?",a="Treasure Trowel 3000 är Izvi Glidfizzs uppfinning, en allt-i-ett-skattspade som hittar skatter.",al={"skattspade","goblinspade","trowel 3000"}},{q="Vad ligger begravt på östra stranden?",a="Highborne-skattfragment ligger under sanden på östra stranden.",al={"strandskatt","vad finns under sanden","highborne-fragment"}},{q="Varför vill Izvi ha fragmenten?",a="Izvi hoppas kunna dela vinsten med dig. Även om fragmenten inte säljs som fornföremål säger hon att metallen kan smältas ner och säljas.",al={"varför gräva efter skatter","vad är det värt","vinst på fragment"}},{q="Varför säger Izvi att det är opraktiskt att söka?",a="Izvi säger att naga gör en lång sökning längs stranden opraktisk.",al={"naga på stranden","varför inte söka","naga-problem"}}},fp="23,200,18.345.0,8.213.1,21.115.0,33.95.0,36.71.0,33.139.0,43.66.0"}
P.entries["quest:91569"] = {n="Blue Gold",s="I Valormok vill Izvi Gildfizz ha en Mana-Siphoning Wand från blood elf-arcanisterna. Hon hoppas tjäna på jakten på uråldrig Highborne-magi.",h="I Valormok vill Izvi Gildfizz ha en Mana-Siphoning Wand från blood elf-arcanisterna.",kw={"belgrom","blood elf-arcanister","blue gold","highborne-magi","izvi gildfizz","mana-siphoning wand","naga","valormok"},sec={{t="En säljares marknad",b="Izvi Gildfizz i Valormok ser en chans att tjäna på jakten efter uråldrig Highborne-magi. Belgrom, alverna och naga vill alla ha sin del, men hon ber dig hämta en Mana-Siphoning Wand som bärs av blood elf-arcanister. Deras läger ligger öster om alvernas basläger, längs klipporna."}},faq={{q="Vad vill Izvi ha?",a="Izvi Gildfizz ber dig hämta en Mana-Siphoning Wand som bärs av blood elf-arcanister.",al={"izvis stav","vilken stav","blue gold-uppdrag"}},{q="Varför vill Izvi ha staven?",a="Izvi tror att hon kan tjäna på intresset för uråldrig Highborne-magi.",al={"varför staven","izvis plan","vad tjänar izvi på det"}},{q="Vilka söker efter Highborne-magi?",a="Belgrom, alverna och naga söker alla efter sin del av den uråldriga Highborne-mag in.",al={"vem vill ha magin","jakten på highborne-magi","naga och alver"}},{q="Vad används stavarna till?",a="Blood elf-arcanister använder de särskilda stavarna för att dra magisk energi från artefakter som alverna hittar.",al={"stavens användning","mana-siphoning wand","vad gör staven"}},{q="Var finns arkanisterna?",a="Deras läger ligger öster om alvernas basläger, längs klipporna.",al={"arkanisternas läger","blood elf-läger","var hittar man staven"}}},fp="9,151,17.293.0,20.89.0,28.74.0,35.84.0,28.95.0,24.61.0"}
P.entries["quest:916"] = {n="Webwood Venom",s="Webwood Venom är ett alliansuppdrag i Shadowglen på Teldrassil. Lärde Gilshalan Windwalker ber unga Night Elf samla giftblåsor från jättelika webwoodspindlar för att undersöka hur det nya världsträdets tillväxt har påverkat den inhemska faunan.",h="Webwood Venom är ett alliansuppdrag i Shadowglen på Teldrassil.",kw={"aldrassil","gilshalan","shadowglen","shadowthread","spindlar","teldrassil","gift","webwood","windwalker"},ang={["class:Druid"]="Druiderna är mycket intresserade av Gilshalans resultat, eftersom frågan om Teldrassil läker eller förvrider djurlivet i omgivningen är central för Cenarion Circles vaksamhet.",["race:NightElf"]="För unga Night Elf som blir vuxna i Shadowglen innebär uppdraget en tidig läxa om hur skör och oberäknelig naturen har blivit under Teldrassils grenar."},sec={{t="En naturalists nyfikenhet",b="Gilshalan Windwalker har rest till Shadowglen för att undersöka de onaturligt stora och aggressiva webwoodspindlarna som härjar i Shadowthread Cave. Han noterar att dessa bestar är släkt med betydligt mindre varianter på andra håll. Han misstänker att Teldrassils enorma magiska krafter orsakar snabba och oroande mutationer hos den lokala faunan och ber om giftblåsor så att han kan jämföra deras biologiska egenskaper med vanliga spindelarter."},{t="Ett växande hot i Shadowglen",b="Webwoodspindlarna som lever runt och inne i Shadowthread Cave har blivit allt farligare för unga Night Elf-noviser i gläntan. Att samla deras gift har två syften: det minskar ett farligt lokalt angrepp och ger forskare i Darnassus direkta biologiska bevis på Teldrassils oberäkneliga påverkan på det vilda."}},faq={{q="Vem är Gilshalan Windwalker?",a="Gilshalan Windwalker är en Night Elf-forskare som är stationerad vid Aldrassil i Shadowglen. Han studerar Teldrassils inhemska fauna för att ta reda på hur världsträdets snabba tillväxt påverkar den lokala ekologin.",al={"gilshalan","vem ger webwood venom","uppdragsgivare för webwood venom"}},{q="Varför är webwoodspindlarna så stora?",a="De är naturligt släkt med betydligt mindre spindelvarianter. Gilshalan Windwalker tror att Teldrassils snabba tillväxt och vilande magiska krafter har gjort dem onaturligt stora och förändrat deras beteende.",al={"jättespindlar på teldrassil","varför är spindlarna stora i shadowglen","webwoodmutationer"}},{q="Var ligger Shadowthread Cave?",a="Shadowthread Cave ligger i den norra delen av Shadowglen, inbäddad i de klippiga höjderna bortom Aldrassils träningsplatser.",al={"shadowthread caves läge","var hittar man webwoodspindlar","webwoodspindlarnas grotta"}},{q="Vad ska Gilshalan göra med giftblåsorna?",a="Han planerar att föra giftet till Darnassus för att jämföra dess kemiska och magiska egenskaper med vanliga skogsspindlars och söka efter avvikelser som världsträdet orsakat.",al={"varför samla giftblåsor","gilshalans giftstudie","giftforskning i darnassus"}},{q="Finns det andra uppdrag i Shadowthread Cave?",a="Ja. När äventyrare samlar gift hjälper de ofta Dirania Silvershine i närheten med att bistå Iverron, en alv som förgiftats av samma spindlar i Shadowthread Cave.",al={"andra spindeluppdrag i shadowglen","uppdrag i shadowthread cave","iverrons uppdrag"}},{q="Vilket uppdrag följer efter Webwood Venom?",a="Efter att ha undersökt giftet ber Gilshalan äventyrarna hämta ett Webwood Egg direkt från djupen av Shadowthread Cave för att studera spindlarnas livscykel.",al={"nästa uppdrag efter webwood venom","vad kommer efter webwood venom","gilshalans följduppdrag"}}},fx={["6f3b3a77"]={q="Varför vill Gilshalan Windwalker ha giftblåsor från Webwood?",a="Gilshalan kom till Shadowglen som lärd för att studera de onaturligt stora Webwood-spindlarna i Shadowthread Cave. Han misstänker att den nya världsträdets snabba tillväxt och latenta magi, Teldrassil, har påverkat det lokala djurlivet. Genom att undersöka giftprover från bestarna hoppas han kunna jämföra dem med deras mindre släktingar på fastlandet och bevisa Teldrassils djupgående inverkan på naturen.",al={"varför vill gilshalan ha gift","gilshalan windwalkers motiv","varför samla webwood-gift"}},["432bbacd"]={q="Vad är Webwood-spindlar och varför finns de i Shadowglen?",a="Webwood-spindlar är spindeldjur som har byggt bo i och omkring Shadowthread Cave vid Shadowglens norra kant. De är släkt med vanliga skogsspindlar, men har blivit monstruöst stora och aggressiva under den nya världsträdets märkliga energier. Deras plötsliga spridning hotar Aldrassils skyddade lundar.",al={"vad är webwood-spindlar","varför finns webwood-spindlar här","webwood-spindlarnas bakgrund"}}},fp="13,214,24.340.0,32.231.0,28.177.0,37.183.0,27.103.0,43.193.0,44.100.0,33.134.0"}
P.entries["quest:91608"] = {n="Gettin' Buzzed",s="Ett gränsläger vill ha vildhonung till en tunna med dryck. Kurll ber dig hämta den från getingbona västerut.",h="Ett gränsläger vill ha vildhonung till en tunna med dryck.",kw={"brygd","gränsläger","gettin' buzzed","kurll","luftpistol","getingbon","vildhonung"},sec={{t="Honung till lägret",b="Kurll vill höja lägrets humör med en tunna god dryck. Han har ett recept som han tog från en dödad dvärg och behöver honung för att brygga drycken. Getingbona västerut innehåller det han behöver."}},faq={{q="Vad behöver Kurll?",a="Kurll behöver vildhonung till en dryck som bryggs enligt ett recept han tog från en dvärg.",al={"vad vill kurll ha","kurll honung","vad kurll behöver"}},{q="Var finns honungen?",a="Vildhonungen finns i getingbon västerut.",al={"var honung","honungens plats","honung i getingbon"}},{q="Varför vill Kurll ha honung?",a="Kurll vill ha honung till en dryck som han hoppas ska höja lägrets humör.",al={"varför honung","vad ska honungen användas till","kurlls dryck"}},{q="Vad är Kurlls recept?",a="Kurll säger att han tog ett recept på en utsökt dryck från en dvärg som han dödade.",al={"kurlls recept","dvärg dryck","recept på dryck"}}},fp="14,115,18.194.0,21.74.0,19.44.0,26.72.0,23.72.0"}
P.entries["quest:91685"] = {n="Ley of the Land",s="Izvi Gildfizz tror att en spricka ovanför Lake Mennar kan vara en öppen leyline. Hon vill att du suger åt dig dess magi och hämtar Tear of Mennar åt henne.",h="Izvi Gildfizz tror att en spricka ovanför Lake Mennar kan vara en öppen leyline.",kw={"izvi gildfizz","lake mennar","landets leyline","leyline-spricka","mana-siphoning wand","öppen leyline","sug åt dig magi","tear of mennar"},sec={{t="En spricka ovanför vattnet",b="Izvi Gildfizz ber dig undersöka sprickan hon fick syn på ovanför Lake Mennar. När hon letade efter outnyttjade resurser såg hon den sväva över vattnet, men kunde inte komma nära. Hon misstänker att det är en öppen leyline. Med en Mana-Siphoning Wand kan du dra magi från sprickan och hämta Tear of Mennar åt Izvi."}},faq={{q="Vem är Izvi Gildfizz?",a="Izvi Gildfizz letade efter outnyttjade resurser i området och fick syn på en spricka ovanför Lake Mennar.",al={"izvi","vem är izvi","izvi gildfizzs bakgrund"}},{q="Vad hittade Izvi vid Lake Mennar?",a="Izvi såg en enorm spricka sväva ovanför vattnet och tror att det kan vara en öppen leyline.",al={"spricka vid lake mennar","vad finns ovanför sjön","spricka vid mennar"}},{q="Vad vill Izvi att jag ska göra?",a="Izvi vill att du använder en Mana-Siphoning Wand på Leyline Rift och hämtar Tear of Mennar åt henne.",al={"vad ska jag göra","leyline-uppdrag","sug åt dig magi från sprickan"}},{q="Varför vill Izvi ha leylinens magi?",a="Izvi hoppas kunna buteljera den magi hon suger åt sig och sälja den till högstbjudande.",al={"varför suga åt sig magin","vad ska magin användas till","izvi vill ha magi"}}},fp="15,139,22.309.0,21.92.0,34.83.0,29.97.0,39.74.0"}
P.entries["quest:917"] = {n="Webwood Egg",s="Gilshalan Windwalker skickar unga försvarare i Shadowglen att hämta ett okläckt spindelägg djupt inne i Shadowthread Cave. Efter att ha samlat in prover av giftet behöver han levande exemplar för att studera den onaturliga aggressivitet som drabbar Teldrassils djurliv. Med en okläckt äggsamling kan forskarna studera varelserna säkert utan att betvinga fullvuxna spindeldjur.",h="Gilshalan Windwalker skickar unga försvarare i Shadowglen att hämta ett okläckt spindelägg djupt inne i...",kw={"aldrassil","gilshalan windwalker","shadowglen","shadowthread cave","spindelägg","teldrassil","webwood","webwood egg"},ang={["class:Druid"]="Studier av ägg och gift ger Cenarion-forskarna möjlighet att avgöra om fördärvet som förändrar dessa djur kan renas bort, eller om farsoten går djupare.",["race:NightElf"]="För unga nattalver visar hämtningen av det här ägget hur lömskt fördärvet får fäste på Teldrassil och tvingar lärda att studera hemlandets djurliv som fientliga hot."},sec={{t="Ett säkert studieobjekt",b="Efter att ha säkrat rågift från de aggressiva Webwood-spindlar som strövar vid Shadowglens utkant behöver Gilshalan Windwalker levande studieobjekt för att bättre förstå deras onaturliga fördärv. Han vet att det vore livsfarligt för en nybörjare att släpa ut ett sprattlande, jättelikt spindeldjur ur de underjordiska djupen. Därför väljer Gilshalan en mer praktisk lösning: ett okläckt ägg direkt från en ruvande kull i Shadowthread Cave."},{t="Vägen till huvudstaden",b="Shadowthread Cave är en underjordisk barnkammare för skogens alltmer fientliga spindeldjur. Om man tar sig in i grottan och hämtar ett helt ägg får lärda ett kontrollerat studieobjekt som kan kläckas under uppsikt. Gilshalan tänker packa ägget tillsammans med sina giftprover och skicka dem direkt till Darnassus för vidare undersökning. Därmed avslutas hans lokala fältstudie, och rekryterna får sikta på högre uppgifter bland Aldrassils grenar."}},faq={{q="Varför vill Gilshalan ha ett ägg i stället för en vuxen spindel?",a="Gilshalan medger att det är alldeles för farligt för en oprövad rekryt att fånga en levande jättespindel, och alldeles för svårt för honom att hålla den inspärrad på egen hand. Ett helt, okläckt ägg låter forskarna transportera levande exemplar säkert och ordna en inhägnad innan kullen kläcks.",al={"varför ett ägg","varför inte fånga en levande spindel","varför webwood-ägget"}},{q="Var finns Webwood-ägget?",a="Ägget ligger i ett nätklätt bo djupt inne i Shadowthread Cave, som skär in bland grenarna och rötterna vid norra änden av Shadowglen på Teldrassil.",al={"äggplats","var hittar man webwood-ägget","boet i shadowthread cave"}},{q="Vem är Gilshalan Windwalker?",a="Gilshalan Windwalker är en nattalvsforskare som håller till vid Aldrassil i Shadowglen. Han undersöker de plötsliga, fördärvande åkommor som driver Teldrassils inhemska varelser till våldsamt beteende.",al={"vem är gilshalan","gilshalans bakgrund"}},{q="Vad händer med ägget när det lämnas in?",a="Gilshalan gör i ordning ägget och sina insamlade giftflaskor för transport till huvudstaden Darnassus. Där kan lärda och druider undersöka dem under kontrollerade former när hans arbete i Shadowglen är avslutat.",al={"vad gör gilshalan med ägget","vart skickas ägget"}},{q="Vad händer när uppgiften är slutförd?",a="När du har säkrat ägget skickar Gilshalan dig upp i Aldrassil för att svara på Tenaron's Summons. Där får du träffa de äldre druider som vägleder Shadowglens hjärta.",al={"nästa uppdrag efter webwood egg","vad gör man efter ägget"}},{q="Varför är Webwood-spindlarna så aggressiva?",a="Spindlarna på Teldrassil, liksom många andra av dess vilda djur, har fallit offer för ett onaturligt fördärv som slår rot över det unga Världsträdet. Det förvandlar tidigare fogliga eller neutrala djur till aggressiva rovdjur.",al={"varför är spindlarna aggressiva","spindelfördärv"}}},fx={["5fcc2c84"]={q="Varför vill Gilshalan Windwalker att detta blir gjort?",a="Gilshalan vill undersöka det märkliga fördärv som oroar Teldrassils djurliv grundligt. Han har redan samlat in prover av Webwood-gift och behöver nu levande exemplar för att undersöka hur smittan påverkar spindlarna från födseln. Om forskare i Darnassus studerar ett okläckt ägg kan de föda upp och observera ungarna i fångenskap på ett säkert sätt. De hoppas kunna upptäcka källan till grenverkets sjukdom som sprider sig.",al={"gilshalans motiv för ägget","varför vill gilshalan ha ett ägg","gilshalan windwalkers skäl till uppdraget"}},f82204fd={q="Varför skickar Gilshalan dig in i Shadowthread Cave i stället för att gå själv?",a="Gilshalan är forskare och lärd, inte en härdad krigare. Han medger öppet att det överstiger hans fysiska förmåga att fånga jättespindlar eller ge sig in i deras angripna underjordiska håla. Genom att anförtro en lovande ung äventyrare uppgiften att ta sig genom de farliga grottorna kan han stanna tryggt vid Aldrassil och förbereda de nödvändiga åtgärderna för att förvara det ömtåliga exemplaret.",al={"varför kan inte gilshalan hämta ägget","varför skicka mig efter webwood egg","varför just jag, gilshalan"}}},fp="11,288,15.358.0,23.355.0,58.235.0,31.137.0,28.183.0,46.184.0,38.147.0,42.210.0"}
P.entries["quest:91723"] = {n="Delicate Instruments",s="Delicate Instruments är ett uppdrag i Elwynn Forest som Hamish Bergwort ger vid Tower of Azora. Hamishs känsliga magiska utrustning störs av oberäkneliga magiska urladdningar från norr. För att återställa stabiliteten måste resenärer bege sig in i Jasperlode Mine och rensa ut de koboldiska geomantiker som orsakar störningarna.",h="Delicate Instruments är ett uppdrag i Elwynn Forest som Hamish Bergwort ger vid Tower of Azora.",kw={"magi","delicate instruments","elwynn forest","geomanti","hamish bergwort","jasperlode mine","kobold","koboldisk geomantiker","tower of azora"},ang={["class:Mage"]="Den ömtåliga magiska utrustningen i Tower of Azora kräver stor stabilitet i omgivningen och visar hur grova geomantiska störningar kan hindra disciplinerade magiska studier.",["faction:Alliance"]="Genom att hjälpa forskarna vid Tower of Azora bidrar du till att skydda Elwynn Forests lärdomscentra från underjordiska skadedjurs kaotiska framfart."},sec={{t="Störda kalibreringar",b="Inne i Tower of Azora sköter Hamish Bergwort ömtålig magisk utrustning som kräver noggrann kalibrering. Tyvärr råder det långt ifrån lugn på landsbygden omkring honom. Upprepade urladdningar av okontrollerad energi rubbar ständigt hans mätningar och gör noggranna magiska justeringar omöjliga tills störningarnas källa åtgärdas."},{t="Störningarna från Jasperlode",b="Undersökningen spårar de magiska pulserna direkt norrut till Jasperlode Mine. Kobolder har tagit över de underjordiska tunnlarna, där deras geomantiker kanaliserar primitiv jordmagi genom stenen. Deras trolldom saknar vetenskaplig förfining, men de många primitiva ritualerna skapar elementära vågor som är starka nog att färdas genom jorden och störa Azoras känsliga instrument."}},faq={{q="Vem är Hamish Bergwort?",a="Hamish Bergwort är en magisk forskare stationerad vid Tower of Azora i Elwynn Forest. Han arbetar med känsliga instrument som kräver exakt kalibrering och lätt störs av magiska svängningar i omgivningen.",al={"vem är hamish bergwort","uppdragsgivare delicate instruments","hamish bergwort tower of azora"}},{q="Varför fungerar de magiska instrumenten fel?",a="Instrumenten störs av magiska energivågor från Jasperlode Mine i norr, som alstras av primitiva kobolder som utövar grov jordmagi.",al={"varför störs instrumenten","orsak till magiska urladdningar","vad stör azora"}},{q="Vad är Jasperlode Mine?",a="Jasperlode Mine är en angripen gruva norr om Tower of Azora i Elwynn Forest. Kobolder har tagit över tunnlarna, där deras besvärjare utför kaotiska geomantiska ritualer som skapar vågor genom skogarna runt omkring.",al={"vad är jasperlode mine","var finns geomantikerna","jasperlodes kobolder"}},{q="Vad är koboldiska geomantiker?",a="Koboldiska geomantiker är underjordiska besvärjare bland koboldflockarna som använder grov, elementär jordmagi. Trots att de är primitiva skapar deras gemensamma kanalisering påtagliga magiska störningar som påverkar känslig magisk utrustning.",al={"vad är koboldiska geomantiker","koboldiska magianvändare","koboldisk geomanti"}},{q="Hur löser det problemet att döda geomantikerna?",a="När geomantikerna i Jasperlode Mine rensas ut upphör de ständiga topparna av elementär energi. Då kan forskarna vid Tower of Azora kalibrera sina känsliga magiska apparater ordentligt utan störningar.",al={"varför döda geomantikerna","syftet med delicate instruments","stoppa urladdningarna"}},{q="Vad är Tower of Azora?",a="Tower of Azora är ett framträdande torn för magiska studier i östra Elwynn Forest. Där iakttar forskare och magiker regionala fenomen och underhåller finjusterad magisk utrustning.",al={"vad är tower of azora","tower of azoras historia","magikertorn i elwynn"}}},fp="20,171,22.207.0,32.250.0,23.180.0,46.129.0,24.162.0,27.187.0,54.167.0,27.166.0"}
P.entries["quest:91724"] = {n="Delicate Instruments",s="Delicate Instruments är ett uppdrag i östra Elwynn Forest där magisk stabilitet i Tower of Azora behöver återställas. Hamish Bergworts känsliga utrustning störs av oberäknelig magi från närliggande Defias-magiker. För att lösa problemet måste amatörernas trolldom kring Stone Cairn Lake upphöra.",h="Delicate Instruments är ett uppdrag i östra Elwynn Forest där magisk stabilitet i Tower of Azora behöver...",kw={"defias brotherhood","defias-magiker","delicate instruments","elwynn forest","hamish bergwort","stone cairn lake","tower of azora"},ang={["class:Mage"]="Den som behärskar arkan magi vet att vårdslös trolldom från amatörer som Defias-magikerna kan sätta våldsamma svängningar i rullning över Elwynn och kasta känslig magisk forskning i kaos.",["faction:Alliance"]="Att upprätthålla ordningen kring Tower of Azora är avgörande för att skydda östra Elwynn Forest mot Defias intrång."},sec={{t="Störningar i tornet",b="I Tower of Azora försöker Hamish Bergwort utföra känsliga magiska experiment, men avbryts gång på gång av oförklarliga störningar i omgivningen. I en arkan fristad där exakta mätningar är allt kan minsta krusning i den lokala magiska väven förstöra timmar av noggrant arbete. Bergwort misstänker att störningarna inte är naturliga, utan beror på klumpiga besvärjelser i närheten."},{t="Banditer och magi",b="Källan till det magiska bruset finns vid Stone Cairn Lake, där Defias-magiker har utövat magi utan tillsyn. Defias Brotherhoods beroende av självständiga magiker för in instabil amatörmagi i Elwynn-landskapet. När magikerna röjs ur vägen tystnar det magiska bruset, och Bergworts känsliga instrument kan äntligen ge rena mätvärden."}},faq={{q="Vem erbjuder uppdraget Delicate Instruments?",a="Hamish Bergwort erbjuder uppdraget från Tower of Azora i östra Elwynn Forest. Han bedriver arkan forskning som kräver stabila magiska förhållanden.",al={"vem ger delicate instruments","uppdragsgivare för delicate instruments","var finns hamish bergwort"}},{q="Vad stör Hamish Bergworts instrument?",a="De känsliga instrumenten i Tower of Azora utsätts för arkan störning från lokala Defias-banditer som börjat utöva klumpig magi nära Stone Cairn Lake.",al={"vad stör instrumenten","varför störs instrumenten","störningar i delicate instruments"}},{q="Var finns Defias Rogue Wizards?",a="Defias-magikerna samlas längs stränderna och i området kring Stone Cairn Lake, strax norr om Tower of Azora i Elwynn Forest.",al={"var finns magikerna","magiker vid stone cairn lake","var hittar man defias-magiker"}},{q="Varför utövar Defias-banditer magi?",a="Defias Brotherhood består främst av missnöjda arbetare, stråtrövare och tjuvar, men har också rekryterat utbrytare som ägnar sig åt arkan magi. Dessa magiker utövar magi utan tillstånd och orsakar oberäkneliga störningar i området.",al={"varför har defias magiker","defias-magiker","magiker och deras bakgrund"}},{q="Vad är Tower of Azora?",a="Tower of Azora är ett arkaniskt torn i östra Elwynn Forest. Där finner mänskliga magiker och lärda en fristad när de studerar ley-linjer, magiska anomalier och säkerheten i området.",al={"vad är tower of azora","azoras torn i elwynn","vem sköter tower of azora"}},{q="Löser det problemet att slå ut magikerna?",a="Ja. När du röjer Defias-magikerna vid Stone Cairn Lake ur vägen lugnar sig den magiska resonansen i omgivningen, så att Hamish Bergworts utrustning åter fungerar som den ska.",al={"fungerar det att stoppa magikerna","resultatet av delicate instruments","hamish bergworts instrument reparerade"}}},fp="20,218,25.237.0,23.270.0,42.146.0,49.108.0,44.144.0,40.167.0,27.152.0,51.154.0"}
P.entries["quest:91725"] = {n="Stolen Enchanting Supplies",s="Stolen Enchanting Supplies är ett ärende nära Tower of Azora i östra Elwynn Forest. Lärlingen Blixie Fitzwink förlorade en leverans magiska reagenser under ett gnollöverfall, och äventyrare måste hämta det stulna godset från läger runt Stone Cairn Lake. När materialen återvinns slipper lärlingen stränga städuppgifter och Master Theocritus får fortsatt material till sina arkana studier.",h="Stolen Enchanting Supplies är ett ärende nära Tower of Azora i östra Elwynn Forest.",kw={"blixie fitzwink","elwynn forest","förtrollningsförnödenheter","gnoller","master theocritus","förvandling","stone cairn lake","tower of azora"},ang={["class:Mage"]="Den arkaniska forskning som bedrivs i Tower of Azora kräver ömtåliga material, så återvunna förtrollningsreagenser är viktiga för magikerna som studerar under Master Theocritus.",["faction:Alliance"]="En trygg försörjningsväg till Tower of Azora håller Stormwinds frontlinjemagiker utrustade mot hot i Elwynn Forest och bortom skogen.",["race:Gnome"]="Gnomlärlingar som Blixie Fitzwink får ofta utföra enklare sysslor åt mänskliga ärkemagiker, och misstag kan leda till förödmjukande städjobb."},sec={{t="Ett bakhåll på vägen",b="En vanlig leveransrunda blir farlig när Blixie Fitzwink, en lärling som hjälper Master Theocritus, överfalls av fientliga gnoller mellan handelsplatsen och Tower of Azora. Hon flyr för livet och tappar lasten, så värdefulla förtrollningsreagenser sprids bland gnollägren längs Stone Cairn Lakes stränder. För att slippa veckor av städning som straff efter arkana förvandlingsexperiment ber hon förbipasserande äventyrare att återfinna det försvunna godset."},{t="Arkana ärenden och lokala faror",b="Tower of Azora är ett arkaniskt fäste i östra Elwynn Forest, där Master Theocritus bedriver känslig magisk forskning. Att skaffa ömtåliga reagenser kräver regelbundna besök vid lokala handelsplatser, men gnollflockarnas växande djärvhet runt Stone Cairn Lake gör transporterna farliga. Om de förlorade förnödenheterna återvinns kan Theocritus fortsätta sina studier utan avbrott, samtidigt som hans hårt prövade assistent slipper bekymmer."}},faq={{q="Vem ger uppdraget Stolen Enchanting Supplies?",a="Blixie Fitzwink ger uppgiften nära Tower of Azora. Hon är assistent åt Master Theocritus och springer ärenden åt honom. Gnoller överföll henne när hon transporterade viktiga förnödenheter tillbaka från en lokal handelsplats.",al={"vem ger stolen enchanting supplies","vem är blixie fitzwink","uppdragsgivare blixie"}},{q="Vem är Master Theocritus?",a="Master Theocritus är en erfaren mänsklig trollkarl som bor i Tower of Azora i östra Elwynn Forest. Han leder arkaniska undersökningar i området och förlitar sig på assistenter för att hämta förtrollningsreagenser och forskningsmaterial.",al={"vem är master theocritus","theocritus roll","magiker i tower of azora"}},{q="Vilka förnödenheter tog gnollerna?",a="Paketet innehåller förtrollningsreagenser som samlats in vid en handelsplats för Master Theocritus arkaniska arbete. Efter att ett bakhåll spritt lasten fördes föremålen till gnolläger runt Stone Cairn Lake.",al={"vad är det för förnödenheter","vad stal gnollerna","förtrollningsreagenser"}},{q="Vart förde gnollerna förnödenheterna?",a="Stone Cairn Lake ligger i östra Elwynn Forest, norr om Tower of Azora. Gnollflockar har slagit läger längs stränderna och på öarna runt sjön, vilket regelbundet hotar resande på närliggande vägar.",al={"var ligger stone cairn lake","var håller gnollerna förnödenheterna","gnoller vid sjön i elwynn"}},{q="Varför oroar sig Blixie Fitzwink för att ha förlorat paketet?",a="Blixie fruktar att Master Theocritus straffar henne med flera veckors städning efter förvandlingsexperiment. Lärlingarna i tornet får vardagliga eller kladdiga sysslor när ärenden eller magiska uppgifter går snett.",al={"vad händer om blixie misslyckas","blixies straff","städning efter förvandling"}},{q="Varför angriper gnoller resande i östra Elwynn?",a="Gnollflockar stryker omkring i östra Elwynn Forest, slår upp fientliga läger runt Stone Cairn Lake och plundrar närliggande vägar. Deras närvaro stör handeln och de överfaller ensamma resande mellan bosättningar och arkaniska utposter.",al={"varför finns gnoller nära tower of azora","gnollhotet i elwynn","riverpaw stone cairn lake"}}},fp="26,279,21.384.0,32.375.0,47.167.0,25.230.0,39.194.0,39.177.0,56.195.0,53.198.0"}
P.entries["quest:91732"] = {n="Good Steel",s="Good Steel är ett uppdrag för Alliansen som börjar vid Eastvale Logging Camp i östra Elwynn Forest. Efter de senaste konflikterna har metall av hög kvalitet blivit en bristvara, och lägrets verktyg för trädfällning är slitna och svåra att ersätta. Hantverkaren Hagar Lowe ber äventyrare bege sig ner i Jasperlode Mine för att ta till vara välgjorda hackor, så att stålet kan användas på nytt.",h="Good Steel är ett uppdrag för Alliansen som börjar vid Eastvale Logging Camp i östra Elwynn Forest.",kw={"eastvale logging camp","elwynn forest","good steel","hagar lowe","jasperlode mine","gruvverktyg","brist efter kriget","återanvända stål"},ang={["faction:Alliance"]="Ansträngda leveranser till Stormwinds avlägsna områden innebär att lokala bosättningar som Eastvale Logging Camp måste ta till vara övergiven utrustning för att hålla verksamheten i gång.",["profession:Blacksmithing"]="Stål av hög kvalitet är fortfarande en bristvara i Elwynn efter kriget, vilket tvingar smeder och hantverkare att leta upp och återanvända metall från gamla, övergivna verktyg.",["profession:Mining"]="De rejäla hackorna som lämnats kvar i Jasperlode Mine visar en äldre och överlägsen standard för metallarbete som dagens arbetare i Elwynn har svårt att nå upp till."},sec={{t="Ett kungarikes bristvara",b="Efter de förödande konflikter som härjat människorikena har stål av hög kvalitet blivit en allt mer sällsynt lyx i Elwynn Forest. Vid Eastvale Logging Camp är det dagliga timmerarbetet beroende av hållbara yxor, sågar och beslag, men verktygen som finns tillgängliga har slitits hårt och är gjorda av undermålig metall. Utan pålitliga leveranser från Stormwinds smedjor tvingas lägrets hantverkare, som Hagar Lowe, hitta påhittiga lösningar för att hålla skogslägret i gång."},{t="Ta till vara det förflutna",b="För att ersätta den slitna utrustningen riktar Hagar blicken mot Jasperlode Mine, en övergiven gruva norr om lägret. Gruvarbetarna som arbetade i de rika ådrorna innan gruvan övergavs använde fint utformade hackor, smidda i en tid då stål fanns i överflöd och härdades med stor skicklighet. I stället för att låta de rejäla verktygen rosta bort i mörkret skickas äventyrare in i de angripna tunnlarna för att hämta de övergivna hackorna och föra dem tillbaka till Eastvale, så att deras överlägsna metall kan smältas ner och användas på nytt av lägrets skogshuggare."}},faq={{q="Vem ger uppdraget Good Steel?",a="Hagar Lowe är en träarbetare eller hantverkare vid Eastvale Logging Camp i östra Elwynn Forest. Eftersom det råder brist på dugliga verktyg ber han äventyrare ta till vara utrustning av hög kvalitet i stål från övergivna verksamheter i närheten.",al={"vem ger good steel","var lämnar jag in good steel","vem är hagar lowe"}},{q="Varför behöver Hagar Lowe gruvverktyg från Jasperlode Mine?",a="Efter de senaste krigen råder det brist på stål av hög kvalitet i hela kungariket, och lägrets arbetsverktyg är illa slitna. Hagar vill åt de fint utformade hackor som lämnats kvar i Jasperlode Mine, så att han kan smälta ner stålet och använda det till nya verktyg för timmerarbetet.",al={"varför hämta hackor","varför vill hagar ha gruvverktyg","syftet med gruvverktygen"}},{q="Vad är Jasperlode Mine?",a="Jasperlode Mine är en gammal gruva i nordöstra Elwynn Forest, norr om Eastvale Logging Camp. Den var tidigare en aktiv verksamhet för kungariket, men blev översvämmad och övergiven. Fint utformad gruvutrustning ligger därför utspridd i djupet.",al={"vad är jasperlode mine","var finns verktygen","jasperlodes historia"}},{q="Varför råder det brist på stål av hög kvalitet?",a="Tredje kriget och de långvariga konflikterna störde produktionen, försörjningslederna och handeln svårt i människorikena. Eftersom resurserna går åt till att försvara och återuppbygga riket måste avlägsna bosättningar som Eastvale klara sig genom att ta till vara hållbara metaller från äldre tider.",al={"varför råder det stålbrist","stålbrist i elwynn","metallbrist efter kriget"}},{q="Vad är Eastvale Logging Camp?",a="Eastvale Logging Camp är Stormwinds främsta bosättning för timmeravverkning. Den ligger vid Elwynn Forests östra gräns nära Redridge Mountains. Skogshuggarna levererar råvirke till Stormwind och samhällena runt omkring, så pålitliga verktyg är avgörande för arbetet.",al={"var ligger eastvale logging camp","eastvale-lägrets syfte","eastvales timmerläger"}},{q="Vad gör verktygen i Jasperlode Mine så speciella?",a="Verktygen som lämnats kvar i Jasperlode Mine smiddes i en tid då hantverket höll högre klass, innan metallbristen under de senaste krigen försämrade tillgången på metall. Som Hagar påpekar visar deras bestående glans och hållbarhet att de tillverkades av mycket bättre stål än det som finns i dag.",al={"vem tillverkar hackorna","varför är hackorna bra","gruvverktygens kvalitet"}}},fp="10,208,20.345.0,18.365.0,31.179.0,59.189.0,24.183.0,34.248.0,30.234.0,51.209.0"}
P.entries["quest:91733"] = {n="Downstream",s="Downstream är ett uppdrag i östra Elwynn Forest som Ormin Pelford ger vid Eastvale Logging Camp. När Ormins vagn råkar välta ner i floden ber man äventyrare trotsa murlocer och vargar nedströms och hämta de vattendränkta timmerförnödenheterna.",h="Downstream är ett uppdrag i östra Elwynn Forest som Ormin Pelford ger vid Eastvale Logging Camp.",kw={"downstream","eastvale logging camp","elwynn forest","murloc","ormin pelford","waterlogged axe","waterlogged saw","waterlogged toolbox"},ang={["faction:Alliance"]="Om Eastvale Logging Camp har tillgång till verktyg kan viktiga timmerleveranser fortsätta att nå Stormwind och bosättningarna i Elwynn."},sec={{t="Ett missöde på vägen",b="När arbetaren Ormin Pelford transporterade en last utrustning tillbaka från en lokal handelsplats råkade han ut för ett missöde. Vagnen välte vid vattenleden nära Eastvale Logging Camp. Lasten föll ner i strömmen och sveptes snabbt nedströms innan han hann säkra den. Utan dessa viktiga träbearbetningsverktyg riskerar timmerhuggarna förseningar i sitt arbete."},{t="Faror längs flodstranden",b="Det är svårt att hämta den vattendränkta lasten på grund av det farliga djurlivet i trakten. Aggressiva murlocer håller till på de leriga grundområdena nedströms, medan rovdjursvargar strövar omkring i skogarna runtomkring. Ormin kan inte försvara sig mot hoten ensam, så han förlitar sig på härdade resenärer som vågar sig längs flodstränderna, bärgar den nedsänkta sågen, yxan och verktygslådan och för tillbaka dem säkert."}},faq={{q="Vem ger uppdraget Downstream?",a="Ormin Pelford erbjuder uppdraget nära Eastvale Logging Camp. Han är en arbetare som råkade välta sin försörjningsvagn ner i floden när han transporterade varor från handelsplatsen.",al={"vem ger downstream","uppdragsgivare för downstream","vem är ormin pelford"}},{q="Vilka förnödenheter gick förlorade i vattnet?",a="De förlorade förnödenheterna består av en Waterlogged Axe, en Waterlogged Saw och en Waterlogged Toolbox som föll i vattnet när Ormin Pelfords vagn välte.",al={"vad föll i floden","förlorade förnödenheter i downstream","vilka föremål i downstream"}},{q="Var sköljdes förnödenheterna upp?",a="Lådorna och verktygen drev nedströms längs floden som rinner söder om Eastvale Logging Camp i östra Elwynn Forest.",al={"var finns verktygen","var sköljs förnödenheterna upp","platsen för downstream"}},{q="Varför kan Ormin Pelford inte hämta förnödenheterna själv?",a="Ormin vågar inte ge sig längs flodstränderna ensam, eftersom rovlystna flodmurlocer och hungriga skogsvargar stryker omkring vid vattendragen där lasten drev iväg.",al={"varför kan ormin inte hämta förnödenheterna","varför ormin pelford behöver hjälp"}},{q="Vilka faror lurar längs flodstränderna?",a="Flodstränderna nedströms kryllar av aggressiva murlocer och strövande vargar, vilket gör bärgningsarbetet farligt för en obeväpnad arbetare.",al={"faror i floden i downstream","hot nedströms"}},{q="Varför är de här verktygen viktiga för Eastvale?",a="Yxorna, sågarna och verktygslådorna är nödvändig utrustning för skogsarbetarna vid Eastvale Logging Camp, som förser Elwynn Forest och Stormwind med råvirke.",al={"varför verktygen är viktiga för eastvale","timmerverktyg vid skogshuggarlägret"}}},fp="10,176,20.299.0,26.343.0,31.162.0,37.136.0,31.112.0,54.107.0,39.104.0,42.142.0"}
P.entries["quest:91735"] = {n="Remote Contact",s="Jes'rimon har ärenden i Azshara och kan inte sköta dem personligen. Han ber dig hitta Jediga vid ett orchläger där och framföra hans namn till henne.",h="Jes'rimon har ärenden i Azshara och kan inte sköta dem personligen.",kw={"azshara","jediga","jes'rimon","orcher","avlägsen kontakt"},sec={{t="Hälsning till Jediga",b="Jes'rimon väntar på besked från Azshara, där Jediga har läger bland en grupp orcher. Han vill inte dröja kvar ute i det fria, men väntar sig en leverans från henne och behöver någon som kan föra hans namn genom vildmarken. Om du hittar henne i Azshara lovar Jes'rimon att komma ihåg tjänsten."}},faq={{q="Vem skickar dig på det här uppdraget?",a="Jes'rimon ber dig hitta en medhjälpare i Azshara åt honom och lovar att stå i skuld till dig.",al={"vem ger avlägsen kontakt","vem skickar mig till jediga","jes'rimons tjänst"}},{q="Vem är Jediga?",a="Jediga håller till i ett läger med flera orcher i Azshara, där hon har en leverans avsedd för Jes'rimon.",al={"vem är jediga","var finns jediga","jedigas läger i azshara"}},{q="Varför skickar Jes'rimon dig till Azshara?",a="Jes'rimon väntar sig en leverans från Jediga i Azshara och behöver ett bud som kan ta sig till hennes läger med hans namn.",al={"varför åka till azshara","vad vill jes'rimon","syftet med avlägsen kontakt"}}},fp="14,150,15.303.0,30.102.0,14.104.0,39.104.0"}
P.entries["quest:91736"] = {n="Applejack Still",s="Applejack Still är en destillationsapparat som används för att omvandla jästa äpplen till sprit med hög alkoholhalt. När du närmar dig apparaten känner du en stickande ånga av koncentrerad frukt, som maskinen kondenserar och tappar upp som en klar sprit.",h="Applejack Still är en destillationsapparat som används för att omvandla jästa äpplen till sprit med hög...",kw={"alkohol","apparat","applejack","bryggning","cider","destilleri","sprit","destillationsapparat"},ang={["profession:Cooking"]="Att destillera och brygga stark sprit av skördad frukt är ett vanligt hantverk bland rustika kockar och värdshusvärdar över hela Azeroth.",["profession:Engineering"]="Apparaten använder mekanisk kondensering och rörledningar för att automatiskt omvandla jäst cider till koncentrerad sprit."},sec={{t="Destillationsapparaten",b="Applejack Still är en fungerande destillationsapparat som är byggd för att förädla jäst cider till sprit med hög alkoholhalt. Den som kliver nära apparaten möts genast av en skarp doft av koncentrerade äpplen som sticker i näsan. Rör och kondensatorslingor utvinner och koncentrerar effektivt essensen av fruktträdgårdens skörd till kraftig sprit."},{t="En klar dryck",b="När maskinen sätts igång och får gå färdigt kondenserar den förångade alkoholen till en klar, ren sprit. Den färdiga äppelspriten tappas prydligt upp i en flaska vid utloppet, redo att drickas eller lagras. Trots att apparaten är enkel och grovhuggen för destillering ute på fältet producerar den pålitligt en klar och kraftig dryck."}},faq={{q="Vad är Applejack Still?",a="Applejack Still är en mekanisk destillationsapparat som är gjord för att framställa applejack, en kraftig spritdryck gjord på äpplen. När du undersöker och använder maskinen kondenserar den jäst äppelmos eller cider till en klar, destillerad sprit som rinner direkt ner i en flaska.",al={"vad är applejack still","vad är det här för apparat","vad gör apparaten"}},{q="Varför är äppeldoften så stark runt apparaten?",a="När du undersöker apparaten känner du en skarp, stickande doft av koncentrerade äpplen som bränner rejält i näsan. Doften är så stark på grund av den höga ångkoncentrationen som bildas när alkoholen avdunstar och kondenseras på nytt inuti metallrören.",al={"hur luktar det","varför svider det","doft från apparaten"}},{q="Vilken sorts vätska tappar maskinen upp?",a="När du använder maskinen tappar den upp en klar vätska direkt i en flaska. Den destillerade spriten är applejack, en klar och kraftig fruktbrännvin som framställs genom destillering i apparaten.",al={"vilken vätska kommer ut","klar vätska från apparaten","vad tappar den upp"}},{q="Hur fungerar destillationsapparaten?",a="Apparaten fungerar genom att värma jäst äppelcider eller mäsk, skilja flyktiga alkoholångor från vattnet och fruktresterna och kondensera ångan tillbaka till vätska. Den destillerade spriten samlas vid pipen och fyller en flaska som väntar där.",al={"hur fungerar applejack still","destilleringsprocess"}},{q="Vad är applejack egentligen?",a="Applejack är en traditionell stark alkoholdryck som görs genom att destillera jäst äppelcider. Spriten som blir kvar är klar, aromatisk och har märkbart högre alkoholhalt än vanlig cider eller öl.",al={"vad är applejack","applejack-dryck"}},{q="Är det farligt att använda apparaten?",a="Apparaten avger starka alkoholångor som är tillräckligt kraftiga för att sticka i näsan när du undersöker den. Den fungerar tillräckligt bra för att tappa upp klar sprit utan att explodera, men arbete med alkoholångor med hög alkoholhalt och tryck kräver försiktighet.",al={"är apparaten säker","är den farlig"}}},fp="15,113,23.193.0,12.225.0,28.147.0,50.170.0,46.122.0,41.196.0,26.151.0,33.148.0"}
P.entries["quest:91737"] = {n="Remote Contact",s="En invånare i Thunder Bluff behöver besked om en leverans från Jediga i Azshara. Du ska hitta hennes läger och fråga när den kommer.",h="En invånare i Thunder Bluff behöver besked om en leverans från Jediga i Azshara.",kw={"azshara","leverans","jediga","orch","reagenser","kontakt på avstånd","thunder bluff"},sec={{t="Nyheter från Azshara",b="En invånare i Thunder Bluff väntar på reagenser som skickats av Jediga, en orch i Azshara. Invånaren behövs i Thunder Bluff, så du ska hitta Jedigas läger och fråga när leveransen väntas."}},faq={{q="Vem väntar på leveransen?",a="En invånare i Thunder Bluff väntar på reagenser från Jediga i Azshara.",al={"vem behöver reagenserna","vem skickade mig till jediga"}},{q="Vem är Jediga?",a="Jediga är en orch i Azshara som väntas skicka reagenser till en invånare i Thunder Bluff.",al={"vem är jediga","jediga azshara"}},{q="Var hittar jag Jediga?",a="Jedigas läger ligger i Azshara.",al={"var finns jediga","jedigas läger"}},{q="Vad ska jag fråga Jediga?",a="Du ska fråga när leveransen till Thunder Bluff väntas komma.",al={"vad ska jag fråga jediga","fråga om leveransen"}}},fp="14,133,17.207.0,32.75.0,14.92.0,23.28.0,30.76.0"}
P.entries["quest:91738"] = {n="An Apple Treat",s="En sergeant välkomnar en flaska Thunder Applejack efter flera månader utan en droppe. Han säger att den borde muntra upp trupperna.",h="En sergeant välkomnar en flaska Thunder Applejack efter flera månader utan en droppe.",kw={"an apple treat","flaska","sergeant","thunder applejack","trupper"},sec={{t="En välkommen flaska",b="En sergeant känner igen din Thunder Applejack och säger att trupperna kommer att uppskatta den. Han tackar dig för att du tog med den."}},faq={{q="Vad vill sergeanten ha?",a="Sergeanten välkomnar en flaska Thunder Applejack, som han säger borde muntra upp trupperna.",al={"vad behöver han","sergeant applejack","apple treat"}},{q="Hur länge sedan var det han såg Thunder Applejack?",a="Sergeanten säger att han inte har sett Thunder Applejack på flera månader.",al={"applejack hur länge","månader utan den","när senast applejack"}},{q="Vem är flaskan till?",a="Sergeanten säger att flaskan borde få trupperna att le.",al={"vem får applejack","applejack till trupperna","vem vill ha flaskan"}}},fp="14,111,16.115.0,28.102.0,52.62.0,22.69.0"}
P.entries["quest:91740"] = {n="Croaky's Head",s="Croaky's Head är en avhuggen prisjägarbelöning från en hotfull murlocledare som terroriserade vägarna i östra Elwynn Forest. Att visa upp bevis på varelsens död för Stormwind-vakten vid Ridgepoint Tower ger en dyster lättnad åt garnisonen, som sörjer sina stupade kamrater. Det markerar en avgörande seger för de lokala försvararna, som kämpar för att säkra Elwynns omstridda vattendrag.",h="Croaky's Head är en avhuggen prisjägarbelöning från en hotfull murlocledare som terroriserade vägarna i östra...",kw={"croaky","croaky's head","eastvale","elwynn forest","merell ross","murloc","ridgepoint tower","stormwinds vakt"},ang={["class:Warrior"]="Krigare känner till frontstridens brutala verklighet och priset som de stupade vakterna fick betala. Genom att fälla en aggressiv stamhövding avlastar du en hårt pressad försvarslinje.",["faction:Alliance"]="Som beskyddare av rikets hjärtland hjälper Alliansens förkämpar Stormwinds överansträngda styrkor direkt genom att undanröja farliga ledare som ger sig på resenärer. När den östra gränsvägen säkras stärks Alliansens makt mellan Elwynn och Redridge.",["race:Human"]="För människorna i Elwynn hotar murlocernas intrång deras gårdar och kostar lokala stadsvakter livet. När Croaky dödas skipas rättvisa för de två stupade vakterna och rikets hjärtland försvaras."},sec={{t="Terror på vägarna vid Eastvale",b="Murlocs längs floderna och bäckarna i Elwynn Forest har blivit allt djärvare. De överfaller oförsiktiga resenärer och hotar viktiga handelsvägar. Bland dessa vattenlevande plundrare utmärkte sig Croaky som en särskilt aggressiv hövding. Han samlade andra murlocs och ledde attacker farligt nära de lokala vägarna. För köpmän, bönder och resenärer mellan Elwynn och Redridge förvandlade varelsens närvaro fridfulla vägar till livsfarliga områden. När den aggressiva plundraren fälls får en skoningslös serie bakhåll ett slut. Ett fräckt hot som öppet utmanade Stormwinds kontroll över skogsbrynet i öster undanröjs."},{t="Vakten vid Ridgepoint Tower",b="Ridgepoint Tower är Stormwinds östligaste utpost i Elwynn Forest och bevakar den strategiska övergången till Redridge Mountains. Vakterna här, under ledning av Officer Merell Ross, har fått kämpa mot farorna i området med alltför få mannar. Murlocernas ökande aggression kostade nyligen två patrullerande vakter livet. Det skakade utposten och visade hur sårbar gränsen blivit. När Croakys avhuggna huvud överlämnas till Officer Ross får hon ett påtagligt bevis på hämnden. Det höjer den hårt pressade garnisonens moral och ger försvararna en chans att äntligen driva bort vattenplundrarna från Elwynns gränser."}},faq={{q="Vem var Croaky?",a="Croaky var en ökänd murlocledare som terroriserade resenärer och lokala patruller längs vattendragen i östra Elwynn Forest. Varelsen samordnade aggressiva bakhåll nära vägarna och utgjorde ett allvarligt hot mot freden i området, tills en äventyrare jagade ner besten.",al={"vem är croaky","croakys bakgrund","vilken sorts murloc är croaky"}},{q="Vem är Merell Ross?",a="Merell Ross tillhör Stormwinds stadsvakt och är stationerad vid Ridgepoint Tower, vid Elwynn Forests östra gräns. Ross har i uppdrag att skydda landsvägen till Redridge Mountains, övervaka säkerheten i gränslandet och samla garnisonen efter att vakter fallit i murlocernas aggressiva räder.",al={"merell ross","vem är officer ross","befälhavare vid ridgepoint tower"}},{q="Var ligger Ridgepoint Tower?",a="Ridgepoint Tower ligger längst österut i Elwynn Forest och bevakar vägen över gränsen till Redridge Mountains. Denna stenbyggda garnison ligger öster om Eastvale Logging Camp och fungerar som en framskjuten försvarsutpost för Stormwinds vakter mot fientliga varelser och landsvägsrövare.",al={"var ligger ridgepoint tower","ridgepoint towers plats","hur hittar man ridgepoint tower"}},{q="Varför ville vakterna vid Ridgepoint Tower att Croaky skulle dö?",a="Stormwinds vakter vid Ridgepoint Tower led nyligen stora förluster. Murlocs dödade två patrullmedlemmar i skogarna och vattnen runt utposten. Vakterna ville få murlocledaren undanröjd för att stoppa de fortsatta bakhållen längs vägen och inleda en samlad insats för att driva bort varelserna från Elwynn.",al={"varför döda croaky","varför vill vakterna ha croakys huvud","murlocattack mot vakten vid ridgepoint"}},{q="Vad uppnår man för Elwynn Forest genom att lämna in Croaky's Head?",a="När Croaky's Head överlämnas till Ridgepoint Tower får garnisonen bekräftelse på att en farlig organisatör av räder längs vägarna har fallit. Med murlocledaren död hoppas vakterna återta initiativet, säkra de östra handelsvägarna och stegvis driva bort de murlocstammar som tränger in längs Elwynns flodbankar.",al={"syftet med croakys huvud","vad händer när man dödar croaky","lämna in croakys huvud"}},{q="Varför utgör murlocs ett sådant hot längs Elwynns vägar?",a="Murlocs bygger ofta bon längs floderna, sjöarna och bäckarna som rinner genom Elwynn Forest. Eftersom viktiga vägar går intill dessa vattendrag överfaller aggressiva stammar ofta ovetande resenärer, handelskaravaner och ensamma militärpatruller. De övermannar försvararna med samordnade styrkor och våldsamma, oförutsägbara räder.",al={"varför angriper murlocs vägarna","murlocproblemet i elwynn","murlocernas hot i elwynn"}}},fp="13,224,28.411.0,29.486.0,15.225.0,19.274.0,34.227.0,56.215.0,64.226.0,51.250.0"}
P.entries["quest:91741"] = {n="Nibbled-On Book",s="Nibbled-On Book är en bok från biblioteket i Northshire Abbey som återfanns bland koboldernas byten i Northshire Valley. Den bär tandmärken från en förvirrad eller utsvulten varelse och måste återlämnas till Brother Paxton för att bevara klostrets anspråkslösa samling.",h="Nibbled-On Book är en bok från biblioteket i Northshire Abbey som återfanns bland koboldernas byten i...",kw={"klostrets bibliotek","brother paxton","elwynn forest","kobold","nibbled-on book","northshire abbey","stulen bok"},ang={["faction:Alliance"]="Northshire Abbey är en plantskola för nya rekryter till Alliansen i Elwynn Forest, där även små uppdrag som att återta stulen egendom från klostret hjälper till att trygga den lokala dalen.",["race:Human"]="Biblioteket i Northshire Abbey bevarar lokal kyrklig och historisk kunskap för kungariket Stormwind, vilket gör återfinnandet av saknade böcker personligt för Northshires invånare."},sec={{t="En söndertuggad bok",b="Bland de underjordiska skadedjur som plågar Northshire Valley är kobolderna ökända för att släpa bort allt som lämnats obevakat. När en äventyrare hittar en söndertuggad bok som en dödad kobold tappat blir det tydligt att varelsen inte bara samlade på glänsande prydnadssaker, utan också försökte gnaga sig igenom omslaget och pergamentet. Texten kommer tydligt från hyllorna i det närbelägna Northshire Abbey och bär spår av skadedjurens glupska aptit."},{t="Brother Paxtons bekymmer",b="I Northshire Abbey sköter Brother Paxton omsorgsfullt ett litet bibliotek avsett för stilla eftertanke och undervisning för Northshires brödraskap. Tyvärr har de fräcka skadedjuren som smyger omkring i dalen fått för vana att ta sig in och rycka böcker direkt från hyllorna. Brother Paxton är tacksam över att få tillbaka just den här naggade boken, men oroar sig fortfarande för resten av sin utspridda samling som fortfarande saknas och är i dalens skadedjurs händer."}},faq={{q="Vad är Nibbled-On Book?",a="Nibbled-On Book är en biblioteksbok som stulits från Northshire Abbey av kobolder. När den återfinns har den tydliga tandmärken, vilket tyder på att de underjordiska skadedjuren kan ha misstagit pergamentet och läderinbindningen för föda.",al={"vad är det här för bok","berättelsen om nibbled-on book","vilken bok tappade kobolden"}},{q="Varför försökte kobolderna äta boken?",a="Kobolder är främst underjordiska asätare som är besatta av ljus och gruvdrift, men de samlar ofta på eller gnager på allt de hittar. Brother Paxton beklagar sig över att skadedjuren tycks stjäla hans böcker för att tugga på eller äta dem.",al={"varför vill kobolder ha böcker","varför äter kobolder böcker","kobolders kost böcker"}},{q="Vem är Brother Paxton?",a="Brother Paxton är en präst som bor i Northshire Abbey och sköter klostrets anspråkslösa bibliotek och textsamling. Han är förtvivlad över att kobolder smyger in i klostret och stjäl böcker från hans hyllor.",al={"vem är brother paxton","paxton northshire","klostrets bibliotekarie"}},{q="Var kom boken ursprungligen ifrån?",a="Boken hör hemma i hyllorna i det lilla bibliotek som Brother Paxton sköter i Northshire Abbey, beläget i den avskilda Northshire Valley i Elwynn Forest.",al={"var kom boken ifrån","var förvarar paxton böckerna","northshires bibliotek"}},{q="Saknas det fler böcker från klostrets bibliotek?",a="Ja. När Brother Paxton får tillbaka boken noterar han bekymrat att kobolderna gång på gång har stulit från hans hyllor och undrar vad han ska göra åt resten av samlingen som saknas.",al={"saknas fler böcker","resten av samlingen","stal kobolderna fler böcker"}},{q="Vem ska boken återlämnas till?",a="Den återfunna boken måste lämnas direkt till Brother Paxton i Northshire Abbey. Han granskar omslaget med tandmärken och tar hand om boken igen.",al={"hur får man tillbaka boken","vem vill ha nibbled-on book","lämna tillbaka boken till paxton"}}},fp="15,146,13.284.0,23.321.0,28.153.0,40.158.0,22.160.0,40.121.0,55.145.0,35.136.0"}
P.entries["quest:91743"] = {n="Rascally Rodents",s="Rascally Rodents är ett uppdrag i Northshire Valley där Brother Paxton ber äventyrare återta böcker som de lokala kobolderna stulit. Paxton oroar sig först för att ohyran slukar hans bibliotek, men när texterna återfinns uppdagas ett oroväckande mysterium bakom varelsernas motiv.",h="Rascally Rodents är ett uppdrag i Northshire Valley där Brother Paxton ber äventyrare återta böcker som de...",kw={"brother paxton","kobolder","bibliotek","northshire abbey","northshire valley","rascally rodents","stulna böcker"},ang={["class:Mage"]="De som studerar det mystiska känner till det oersättliga värdet av skriven kunskap och litteratur, även när de hotas av oväntade tjuvar som kobolder.",["class:Priest"]="Präster som hjälper till vid Abbey of Northshire bevarar den heliga vördnaden och det lärda arvet hos den Heliga Ljusets lärda, och skyddar värdefulla texter från att förstöras.",["race:Human"]="Mänskliga noviser som inleder sin utbildning i Northshire Valley kallas att försvara klostrets skatter och lärda verk mot opportunistiska skadedjur och inkräktare."},sec={{t="Ett hot mot biblioteket",b="Brother Paxton i Northshire Valley är förtvivlad över de lokala kobolderna, som spridit sig från kullarna och gruvorna i trakten till den heliga marken. Han är övertygad om att de glupska varelserna börjat sluka böckerna i hans samling och ber unga äventyrare jaga bort ohyran och rädda de volymer som återstår innan hela biblioteket går förlorat."},{t="En oförklarlig aptit",b="När Brother Paxton återfår åtta stulna volymer från dalens kobolder upptäcker han något oväntat: varelserna har faktiskt inte ätit upp papperet eller banden. Kobolderna tar i stället böckerna med flit och samlar dem av okänd anledning. Det gör brodern djupt orolig, eftersom många volymer fortfarande saknas i dalen."}},faq={{q="Vem ger uppdraget Rascally Rodents?",a="Brother Paxton, en invånare i klostret som desperat vill skydda dess bibliotek från ohyran i dalen, ger äventyrare i Northshire Valley det här uppdraget.",al={"vem ger rascally rodents","uppdragsgivare rascally rodents","paxtons bokuppdrag"}},{q="Varför stjäl kobolderna böcker?",a="Brother Paxton tror först att kobolderna bokstavligen äter upp hans böcker. När han undersöker de återfunna volymerna inser han dock att de inte alls har blivit uppätna, och deras verkliga syfte och intresse för texterna förblir ett oroväckande mysterium.",al={"varför tar kobolder böcker","äter kobolder böcker","varför vill kobolder ha böcker"}},{q="Var hittar du de stulna böckerna?",a="De stulna böckerna finns hos kobolderna som hemsöker Northshire Valley. De har plundrat den lokala samlingen på texter och burit dem till sina läger och gruvgångar.",al={"var hittar man stulna böcker","plats för stulna böcker","koboldböcker northshire"}},{q="Vem är Brother Paxton?",a="Brother Paxton tillhör brödraskapet i Northshire. Han värnar djupt om de skrifter som förvaras i dalen och är beroende av att unga noviser räddar dem från traktens asätare.",al={"vem är brother paxton","brother paxtons bakgrund"}},{q="Vad får du som belöning av Brother Paxton?",a="När du återlämnar åtta av de stulna volymerna ger Brother Paxton dig tacksamt en av sina handböcker, som han säger att han inte behöver, samtidigt som han beklagar att många volymer fortfarande saknas.",al={"vilken belöning ger paxton","handbok som belöning"}},{q="Återfinns alla stulna böcker?",a="Nej. Även efter att åtta stulna böcker har återfunnits påpekar Brother Paxton att många volymer fortfarande saknas runtom i dalen. Koboldernas märkliga intresse för dem är fortfarande oförklarat.",al={"återfinns alla böcker","räddas alla böcker"}}},fp="16,139,23.286.0,23.254.1,37.116.0,35.149.0,35.99.0,22.158.0,46.148.0,35.128.0"}
P.entries["quest:91745"] = {n="Mining Consultant",s="Mining Consultant är ett uppdrag i Northshire Valley där äventyrare får i uppgift att rådfråga Kelsey Fargo, en gruvlärling som håller till utanför Echo Ridge Mine. Hennes iakttagelser avslöjar något ovanligt: kobolderna i området har börjat stjäla böcker från biblioteket i Northshire Abbey.",h="Mining Consultant är ett uppdrag i Northshire Valley där äventyrare får i uppgift att rådfråga Kelsey Fargo...",kw={"echo ridge mine","kelsey fargo","kobold","bibliotek","gruvdrift","mining consultant","northshire abbey","northshire valley"},ang={["profession:Mining"]="Kelsey Fargo är gruvlärling och håller till precis utanför Echo Ridge Mine. Hon är en praktisk lokal kontakt för blivande gruvarbetare som vill lära sig om gruvdrift och förhållandena i närheten.",["race:Human"]="Northshire Valley är en övningsplats för nya mänskliga äventyrare. Att skydda klostrets värdefulla arkiv och de närliggande gruvorna från kobolder är avgörande för regionens stabilitet."},sec={{t="Problem vid gruvan",b="Koboldinvasionen i Echo Ridge Mine har tagit en oväntad vändning. De här varelserna nöjer sig inte längre med att försvara underjordiska fyndigheter och samla ljus. De har väckt myndigheternas uppmärksamhet genom märkliga, samordnade störningar. Äventyrare skickas för att söka upp Kelsey Fargo, en gruvlärling som håller till nära gruvans ingång, och ta reda på vad hon har sett från sin plats utanför tunnlarna."},{t="Lärda boksamlare",b="Kelsey Fargo bekräftar att gruvans ohyra beter sig underligt. Kobolder har setts springa fram och tillbaka med tunga böcker och gräla sinsemellan. Kelsey drar slutsatsen att böckerna har stulits direkt från biblioteket i Northshire Abbey. Det väcker frågan vad analfabeta varelser som lever i tunnlarna kan vilja med stulna lärda skrifter."}},faq={{q="Vem är Kelsey Fargo?",a="Kelsey Fargo är en gruvlärling som håller till strax utanför ingången till Echo Ridge Mine i Northshire Valley. Tack vare sin arbetsplats har hon ett utmärkt läge för att observera de lokala koboldernas ovanliga rörelser och vanor.",al={"vem är kelsey fargo","kelsey fargos roll","gruvlärling northshire"}},{q="Varför bär kobolder böcker?",a="Enligt Kelsey Fargo har kobolder setts springa fram och tillbaka, gräla och bära på böcker. Hon misstänker att de stjäl böcker direkt från biblioteket i Northshire Abbey, men vad de ska med dem till är fortfarande ett mysterium.",al={"varför stjäl kobolder böcker","kobolder som läser","böcker i echo ridge mine"}},{q="Var ligger Echo Ridge Mine?",a="Echo Ridge Mine ligger i nordvästra Northshire Valley, bland kullarna nordväst om Northshire Abbey. Gruvan har blivit full av kobolder som stör gruvdriften.",al={"var ligger echo ridge mine","echo ridge mines läge"}},{q="Varifrån får kobolderna böckerna?",a="Man tror att de stulna böckerna kommer från biblioteket i Northshire Abbey. Där finns arkiv, skrifter och historiska verk som de lokala prästerna och lärda människorna har samlat och bevarat.",al={"varifrån kommer böckerna","kobolder i klosterbiblioteket"}},{q="Varför ska man rådfråga gruvlärlingen?",a="Uppdraget går ut på att besöka Kelsey Fargo utanför gruvan, undersöka rapporter om märkliga koboldaktiviteter och ta reda på vad hon har sett från sin arbetsplats.",al={"syftet med uppdraget mining consultant","varför prata med kelsey"}},{q="Vilket märkligt beteende har kobolderna visat?",a="Kobolderna vid Echo Ridge Mine nöjer sig inte med att leta efter saker och gräva som vanligt. De har setts skrika åt varandra och släpa bort skrivna texter, med en ovanligt oberäknelig samordning.",al={"vad gör kobolderna","koboldernas beteende i northshire"}}},fp="17,140,19.354.0,20.249.1,20.168.0,31.186.0,25.165.0,42.165.0,56.147.0,49.202.0"}
P.entries["quest:91746"] = {n="Elmpaw's Head",s="Elmpaw's Head är ett troféuppdrag som belönar en äventyrare för att spåra upp det mäktiga odjuret Elmpaw. Odjurets huvud byts mot en hantverkare som gör uppstoppade troféer åt välbärgade samlare.",h="Elmpaw's Head är ett troféuppdrag som belönar en äventyrare för att spåra upp det mäktiga odjuret Elmpaw.",kw={"odjur","samlare","elmpaw","huvud","jägare","spiselkrans","trofé"},ang={["class:Hunter"]="Att fälla ett mäktigt odjur som Elmpaw och ta en fysisk trofé är det främsta kännetecknet på en skicklig spårare och jägare."},sec={{t="Det fallna odjuret",b="Elmpaw's Head avslutar jakten på varelsen Elmpaw. Att fälla ett sådant odjur ses som en imponerande bedrift bland vildmarksspårare och samlare, som värdesätter konkreta bevis på seger över farliga vilddjur."},{t="En samlares byte",b="När jägaren överlämnar Elmpaws avhuggna huvud får hen en belöning direkt av en driftig uppköpare. I stället för att låta kvarlevorna gå till spillo gör mottagaren i ordning trofén och monterar den för att sälja den till välbärgade kunder som vill pryda sina spiselkransar med imponerande vildmarksbyten."}},faq={{q="Vem eller vad är Elmpaw?",a="Elmpaw är en mäktig varelse vars nederlag räknas som en imponerande bedrift. Det finns få uppgifter om vilken art den tillhör, men jägare söker upp odjuret för att ta dess huvud som en åtråvärd trofé.",al={"vem är elmpaw","vad är elmpaw","elmpaw boss"}},{q="Varför vill uppdragsgivaren ha Elmpaws huvud?",a="Uppdragsgivaren gör i ordning huvudet för att monteras och visas upp, och påpekar att välbärgade samlare betalar dyrt för att pryda sina spiselkransar med sådana exotiska troféer.",al={"varför vill de ha huvudet","lämna in elmpaws huvud","vad används trofén till"}},{q="Vilka samlare är intresserade av trofén?",a="Uppdragsgivaren gör affärer med välbärgade samlare som värdesätter exotiska odjurstroféer att visa upp i sina hem. När huvudet har monterats på rätt sätt betalar entusiasterna ett högt pris för det.",al={"vem köper trofén","elmpaws köpare","vem vill ha elmpaws huvud"}},{q="Är Elmpaw ett farligt villebråd?",a="Uppdragsgivaren beskriver det som mycket imponerande att fälla Elmpaw, vilket tyder på att odjuret är en utmaning eller en sällsynt strykare, snarare än ett vanligt vilddjur.",al={"hur svår är elmpaw","är elmpaw svår"}},{q="Vad är det för slags uppdrag, Elmpaw's Head?",a="Det är ett prisjakt- och trofébyte. En äventyrare fäller Elmpaw i vildmarken, tar huvudet och lämnar det till en intresserad köpare som belönar äventyraren innan huvudet görs i ordning för återförsäljning.",al={"är elmpaw's head ett prisjaktuppdrag","vem gav elmpaw-uppdraget"}},{q="Var kan Elmpaw hittas?",a="Elmpaw strövar omkring i vildmarken där äventyrare och storviltsjägare stöter på farliga odjur. Ta huvudet tillbaka till samlaren när du har segrat.",al={"elmpaws plats","var hittar man elmpaw"}}},fp="13,169,16.153.0,19.158.0,22.120.0,44.131.0,48.137.0,29.96.0,35.130.0,26.117.0"}
P.entries["quest:91751"] = {n="Rough Wolf Pelts",s="Rough Wolf Pelts är ett introduktionsuppdrag i flåning i Elwynn Forest som Helene Peltskinner erbjuder nära Goldshire. Med sin make borta för att hjälpa till nära Northshire Abbey förlitar sig Helene på skickliga flåare som kan ta råhudar från traktens vargar och slutföra hennes väntande beställningar av läderarbete.",h="Rough Wolf Pelts är ett introduktionsuppdrag i flåning i Elwynn Forest som Helene Peltskinner erbjuder nära...",kw={"elwynn forest","goldshire","helene peltskinner","läderarbete","skinn","rough wolf pelts","flåning","timmervargar"},sec={{t="En flåares behov",b="Strax utanför Goldshire arbetar Helene Peltskinner flitigt med att förse resenärer och invånare med garvat läder och pälsar. Hennes make jagar vanligtvis de strövande timmervargarna i Elwynn Forest för att hålla hennes verkstad med material, men uppgifter nära Northshire Abbey har fört honom bort från arbetsbänken. Med en hög kundbeställningar att slutföra tar Helene hjälp av förbipasserande lärlingar som är villiga att rikta sina flåknivar mot traktens vilda djur."},{t="Skogens strykare",b="Elwynn Forests täta skogar kryllar av timmervargar som smyger längs åkrarnas och vägarnas utkanter. För nybörjare inom flåning är insamling av grova vargskinn praktisk fälterfarenhet i konsten att ta hudar. När Helene får skinnen kan hon hålla sin verksamhet igång och handeln flödande genom Goldshire, samtidigt som kringvandrande jägare får en chans att vässa sina färdigheter i skogen."}},faq={{q="Vem är Helene Peltskinner?",a="Helene Peltskinner är en lokal flåare och läderarbetare som håller till strax utanför Goldshire i Elwynn Forest. Hon bereder hudar och utför hantverksbeställningar åt både resenärer och lokalbor. Eftersom hennes make är upptagen med att hjälpa till nära Northshire Abbey förlitar hon sig på förbipasserande äventyrare som kan samla in de färska varghudar hon behöver för sitt arbete.",al={"vem är helene peltskinner","helene peltskinner","vem ger rough wolf pelts"}},{q="Varför behöver Helene vargskinn?",a="Helene arbetar sig igenom en hög beställningar av läderarbete nära Goldshire och behöver råmaterial för att hålla verksamheten igång. Vanligtvis jagar hennes make vargar för att förse arbetsbänken med material, men hans åtaganden på annat håll i Elwynn har gjort att hon har ont om grova skinn. Äventyrare hjälper till genom att flå lokala vargar åt henne.",al={"varför behövs rough wolf pelts","varför samla skinn","vad gör helene med skinnen"}},{q="Var är Helenes make?",a="Helenes make brukar hjälpa henne genom att jaga vargar och skaffa skinn, men just nu är han upptagen norrut, nära Northshire Abbey. När han är borta måste Helene anlita lokala äventyrare som kan komma med varghudar så att hon hinner med verkstadens pågående beställningar av skinn.",al={"var är helenes make","helenes make","vem är helenes make"}},{q="Var hittar man vargar i Elwynn Forest?",a="Grova vargskinn får man från timmervargarna som strövar i skogarna i Elwynn Forest runt Goldshire och Northshire. De som lär sig flåning tar skinnen direkt från djuren ute i skogen och lämnar dem sedan till Helenes läderverkstad.",al={"var hittar man rough wolf pelts","vilka vargar ger skinn","vargplatser i elwynn"}},{q="Måste man kunna flå för att ta skinnen?",a="Helene erbjuder uttryckligen uppgiften som en möjlighet för resenärer att öva på flåning. Målet kräver att man faktiskt flår döda vargar i stället för att bara jaga dem för att få troféer, så uppgiften är särskilt anpassad för lärlingar som lär sig att ta hudar från djur.",al={"måste jag kunna flå för rough wolf pelts","flåningskrav för rough wolf pelts","flåningsuppdrag i goldshire"}},{q="Var hittar man Helene Peltskinner?",a="Helene Peltskinner har sin arbetsplats nära Goldshire, den centrala bosättningen i Elwynn Forest. Hon bedriver sin läderhandel nära byn, där jägare och resenärer längs King's Road enkelt kan lämna färska hudar från skogen till henne.",al={"var finns helene peltskinner","helene peltskinners plats","var hittar man helene"}}},fp="16,175,16.310.0,22.260.0,26.264.0,32.238.0,26.172.0,44.154.0,44.154.0,38.200.0"}
P.entries["quest:91752"] = {n="The Big Picture",s="The Big Picture är ett uppdrag i Northshire Valley som handlar om en boktjuvskobold vid namn Shinyfinder Narf, som har samlat på sig stulna böcker djupt inne i den lokala gruvan. Lokala myndigheter skickar ut äventyrare för att hämta de illustrerade böckerna och återlämna dem till Marshal McBride i Northshire Abbey.",h="The Big Picture är ett uppdrag i Northshire Valley som handlar om en boktjuvskobold vid namn Shinyfinder...",kw={"brother paxton","kobold","marshal mcbride","narf","northshire abbey","bilderböcker","shinyfinder narf","the big picture"},ang={["faction:Alliance"]="Northshire Valley är en träningsplats och fristad för unga Alliance-hjältar. Att bevara freden och återta stulna varor från skadedjur som tränger sig på är viktigt arbete.",["race:Human"]="Northshire Abbey är startpunkten för nyrekryterade mänskliga äventyrare som börjar tjänstgöra för att skydda Stormwinds avlägsna områden."},sec={{t="Kobolden som stal böckerna",b="En märklig händelse har stört lugnet i Northshire Valley: kobolder som lurar i trakten har setts rusa iväg med böcker och ropa ”Picture for Narf!” Kobolder är ökända för att leta efter ljus och glänsande småsaker, men en särskild grottinvånare vid namn Shinyfinder Narf har fått smak för illustrerade böcker och samlat en hel säck i sitt gömställe under jord."},{t="Hämta tillbaka klostrets böcker",b="I gruvans djupare schakt håller sig de tåligare och elakare koboldsläktena, som vaktar Narf och hans märkliga samling. För att få tillbaka de stulna böckerna måste du ge dig in i de mörka tunnlarna och konfrontera Narf. När säcken väl har slitits ur varelsens klor förs den till Marshal McBride i Northshire Abbey, som ser till att de värdefulla böckerna återlämnas tryggt till Brother Paxton."}},faq={{q="Vem är Shinyfinder Narf?",a="Shinyfinder Narf är en koboldledare som håller till långt inne i gruvan nära Northshire Valley. Han har samlat på sig stulna böcker och ropar efter bilderböcker, vilket har fått de lokala myndigheterna att beordra att hans förråd hämtas tillbaka.",al={"vem är narf","shinyfinder narfs bakgrund","narf kobold"}},{q="Varför stjäl kobolderna böcker?",a="Kobolder som kommer ut ur gruvan har setts ropa ”Picture for Narf!” medan de rycker åt sig läsmaterial. Narf verkar inte vara intresserad av lärdom, utan besatt av att samla illustrerade böcker och stoppa dem i en säck djupt inne i tunnlarna.",al={"varför vill kobolder ha bilderböcker","vad betyder picture for narf","varför stals böckerna"}},{q="Vem tillhörde de stulna böckerna?",a="Brother Paxton bor i Northshire Abbey och det är hans böcker som stals. När säcken med återfunna böcker når Marshal McBride ordnas det så att de återlämnas direkt till Brother Paxtons samling.",al={"vem är brother paxton","paxtons böcker"}},{q="Vem är Marshal McBride?",a="Marshal McBride är den lokala ordningsmakten och håller till strax innanför Northshire Abbey. Han ansvarar för att upprätthålla ordningen, skydda klostrets område och organisera försvaret mot koboldhotet i trakten.",al={"vem är marshal mcbride","var finns mcbride"}},{q="Var hittar du Shinyfinder Narf?",a="Narf håller till i de djupare och farligare delarna av den lokala gruvan i Northshire Valley, omgiven av elakare kobolder som försvarar sitt hopsamlade byte.",al={"var finns narf","var hittar man narf","gruvans plats"}},{q="Hur farlig är gruvan där Narf bor?",a="Vanliga kobolder utanför gruvan är mest till besvär när de letar efter saker, men kobolderna som bor djupare i tunnlarna med Narf är mycket elakare och fientligare. Därför är Narf och hans håla farliga för äventyrare som ger sig dit ensamma.",al={"är narf farlig","kan man besegra narf ensam"}}},fp="15,167,21.249.0,28.281.1,24.178.0,35.167.0,24.186.0,23.178.0,36.143.0,43.163.0"}
P.entries["quest:91753"] = {n="An Enchanting Lesson",s="An Enchanting Lesson är ett uppdrag som Kitta Firewind erbjuder vid Tower of Azora i Elwynn Forest. Det uppmanar utövare att undersöka koboldgeomantikernas grova vaxfigurer och visar att praktiska experiment är lika viktiga för förtrollning som formell arkanteori.",h="An Enchanting Lesson är ett uppdrag som Kitta Firewind erbjuder vid Tower of Azora i Elwynn Forest.",kw={"an enchanting lesson","avförtrollning","elwynn forest","kitta firewind","koboldgeomantiker","luminous residue","tower of azora","vaxfigur"},ang={["class:Mage"]="Lärda magiker fnysar ofta åt underjordiskt ohyra, men Kitta Firewind påminner utövare om att även primitiva varelser kan avslöja oväntade sanningar om hur råa magiska strömmar kan styras.",["faction:Alliance"]="Studier i Tower of Azora i Elwynn Forest ger äventyrare från Alliansen insikt i både akademisk trolldom och de förvånansvärt magiska skadedjur som hemsöker deras marker."},sec={{t="Teori och praktik",b="Akademisk noggrannhet är en viktig grundpelare i studiet av arkana konster, men verklig mästerskap kräver praktisk tillämpning. I Tower of Azora utmanar Kitta Firewind lärlingar i förtrollning att se bortom välordnade bibliotek och undersöka magi där den uppstår naturligt. Även de obildade kobolderna som krafsar under Elwynn Forest lyckas kanalisera besvärjelser till vardagliga talismaner, vilket visar att magisk instinkt ofta trotsar formell skolning."},{t="Primitiva besvärjelser",b="Koboldgeomantiker formar grova vaxfigurer som är genomsyrade av enkla folktrollformler. Genom att samla in figurerna och varsamt nysta upp den bundna magin med hjälp av avförtrollning kan en uppmärksam elev utvinna Luminous Residue. Att plocka isär dessa grova amuletter visar att man måste se hur rå magi beter sig i fält för att förstå förtrollningens grundläggande trådar, inte bara läsa om den i dammiga trollformelsböcker."}},faq={{q="Vem ger uppdraget An Enchanting Lesson?",a="Kitta Firewind, en förtrollare som bor i Tower of Azora i Elwynn Forest, erbjuder den här lektionen för att hjälpa äventyrare att balansera teoretiska magikunskaper med praktisk övning.",al={"vem ger uppdraget an enchanting lesson","uppdragsgivare enchanting lesson","kitta firewind uppdrag"}},{q="Var ligger Tower of Azora?",a="Tower of Azora står i östra Elwynn Forest och fungerar som en fästning för magiska studier och trolldom bland det mänskliga kungarikets jordbruk och skogar.",al={"var ligger tower of azora","tower of azora plats"}},{q="Hur vet kobolder hur man använder magi?",a="Trots att de saknar formell skolning och akademiska traditioner har kobolder, särskilt geomantiker, en instinktiv fallenhet för att binda enkla besvärjelser och förtrollningar i sina grova vaxfigurer.",al={"kan kobolder använda magi","koboldgeomantikernas magi","har kobolder förtrollningar"}},{q="Vad används vaxfigurerna till?",a="Grova vaxfigurer är primitiva föremål som koboldgeomantiker tillverkar. De är enkla, men innehåller bunden magisk energi som kan nystas upp och studeras genom avförtrollning.",al={"vad är vaxfigurer","grova vaxfigurer","kobolders vaxmagi"}},{q="Vad är Luminous Residue?",a="Luminous Residue är den kvarvarande essens som fås när man plockar isär och avförtrollar de grova vaxfigurer som koboldgeomantiker bär på. Den är ett konkret bevis på deras medfödda besvärjelser.",al={"vad är luminous residue","hur får man luminous residue"}},{q="Vad är huvudpoängen med Kitta Firewinds lektion?",a="Kitta Firewind lär ut att teoretiska kunskaper och praktiska experiment är två oskiljaktiga sidor av samma mynt och uppmanar elever att studera praktisk magi var den än visar sig.",al={"uppdragets lärdom","vad lär kitta firewind ut"}}},fp="20,222,19.335.0,18.371.0,41.176.0,36.148.0,37.167.0,35.173.0,25.176.0,53.161.0"}
P.entries["quest:91758"] = {n="Follow That Kobold!",s="Follow That Kobold! är ett uppdrag för Alliansen i Northshire Valley som handlar om en märklig stöld från de lokala gruvorna. En kobold har flytt med en säck böcker som tillhör Brother Paxton, och därför ber klostret dvärgtränaren i jakt, Tordrin Sternblade, att hjälpa till att spåra tjuven.",h="Follow That Kobold!",kw={"brother paxton","follow that kobold","jägarinstruktör","ironforge","kelsey","kobold","northshire","tordrin sternblade"},ang={["class:Hunter"]="Uppdraget introducerar Tordrin Sternblade, en erfaren jägarklassinstruktör som nyligen anlänt från Ironforge för att hjälpa Northshire Abbey.",["faction:Alliance"]="Samarbetet mellan Stormwinds heliga kloster och en bergsvakt från Ironforge visar styrkan i Alliansens ömsesidiga stöd.",["race:Dwarf"]="Tordrin Sternblade tar med sig traditionella dvärgiska spårningskunskaper direkt från Ironforge för att hjälpa människorna i Northshire."},sec={{t="Boktjuven i Northshire",b="Arbetarna och prästerna vid Northshire Abbey trodde att skadedjursproblemet i gruvorna var under kontroll. Då kom en ovanlig rapport från Kelsey: en ensam kobold hade setts fly från tunnlarna med en tung säck böcker. De stulna böckerna tillhör Brother Paxton, som behöver få tillbaka dem till klostrets samling snarast."},{t="Tillkalla bergsvakten",b="Det krävs särskild skicklighet för att spåra en snabb underjordisk asätare genom Northshires skogsklädda marker. För att hitta tjuven skickas äventyrarna bakom klostret, till stallet, för att söka upp Tordrin Sternblade. Han är en dvärgisk jägarklassinstruktör som nyligen anlänt från Ironforge och har den vildmarkskunskap som krävs för att följa spåret."}},faq={{q="Vad handlar Follow That Kobold! om?",a="Follow That Kobold! är ett uppdrag i Northshire Valley där du ska jaga en förrymd kobold som flydde från den lokala gruvan med en tung säck stulna böcker som tillhör Brother Paxton.",al={"vad är follow that kobold","uppdraget follow that kobold"}},{q="Vem är Tordrin Sternblade?",a="Tordrin Sternblade är en dvärgisk jägarklassinstruktör som nyligen anlänt från Ironforge. Han håller till bakom Northshire Abbey nära stallet och bidrar med sina spårningskunskaper för att hjälpa till att återfå de stulna böckerna.",al={"vem är tordrin sternblade","var finns tordrin","jägarinstruktör northshire"}},{q="Vad stal kobolden?",a="Enligt rapporter från Kelsey smet en kobold ut ur gruvan i Northshire med en stor säck böcker. Klostret behöver få tillbaka dem åt Brother Paxton, men varför en kobold skulle vilja ha människornas böcker är fortfarande ett mysterium.",al={"varför stal kobolden böcker","vad tog kobolden","säck med böcker"}},{q="Vem rapporterade stölden?",a="Kelsey Fargo är den nya gruvlärlingen som arbetar precis utanför gruvan i Northshire. Hon lade först märke till den märkliga synen av en kobold som lämnade tunnlarna med en säck full av böcker.",al={"vem är kelsey","kelsey northshire"}},{q="Vem är Brother Paxton?",a="Brother Paxton är en präst som bor vid Northshire Abbey. Det stulna biblioteksmaterialet tillhör honom eller behövs i hans heliga tjänst, så klostret ber om hjälp från en erfaren spårare för att få tillbaka det.",al={"vem är brother paxton","paxtons böcker"}},{q="Hur spårar du den tjuvaktiga kobolden?",a="I stället för att rusa blint in i skogen skickas äventyrarna till Tordrin Sternblade bakom klostret. Han förbereder dem på att följa tjuvens spår med olika spårningstekniker.",al={"hur spårar jag kobolden","spåra tjuven"}}},fp="19,182,28.245.0,26.342.0,34.121.0,26.177.0,26.176.0,23.177.0,22.175.0,37.166.0"}
P.entries["quest:91772"] = {n="Shhh! We're Hunting Kobolds",s="'Shhh! We're Hunting Kobolds' är ett uppdrag där äventyrare lämnar Northshire Valley för att spåra vandrande kobolder in i Elwynn Forest. Med hjälp av ett spårningskit upptäcker spelarna att spåret leder mot det koboldangripna Fargodeep Mine och rapporterar sina fynd till Marshal Dughan i Goldshire.",h="'Shhh!",kw={"elwynn forest","fargodeep mine","goldshire","spårningskit för kobolder","kobolder","marshal dughan","marshal mcbride","northshire","shhh we're hunting kobolds"},ang={["class:Hunter"]="Jägare som är skickliga på att spåra villebråd kan uppskatta hur spårningskit hjälper till att följa ohyrans spår genom skogen.",["faction:Alliance"]="Alliansens äventyrare som lämnar Northshire bidrar till att säkra Elwynns försörjningslinjer och bosättningar genom att hålla garnisonen i Goldshire informerad om hot som samlas."},sec={{t="Spåra ohyran",b="När koboldangreppen i Northshire Valley tilltar tyder tecken på att ohyran organiserar sig bortom klostrets avskilda område. Spejare utrustas med ett spårningskit och skickas ut för att följa varelsernas spår och ta reda på var de samlar sina styrkor. Den här rekognoseringen utgör en viktig länk mellan Northshires lokala problem och det bredare försvaret av Elwynn Forest."},{t="Spåret till Fargodeep",b="Spåret leder sydväst ut ur Northshire och genom Elwynn Forest mot Fargodeep Mine. Marshal Dughan, som leder garnisonen i Goldshire, blir inte förvånad över rapporten och konstaterar att Fargodeep redan är svårt angripet av kobolder. Upptäckten banar väg för en militär insats för att återta den viktiga gruvan."}},faq={{q="Vad är målet med uppgiften?",a="Uppdraget går ut på att använda ett särskilt spårningskit för att följa kobolder som rör sig utanför Northshire Valley. Målet är att ta reda på var varelserna samlas och överlämna informationen till Stormwinds myndigheter i Goldshire.",al={"uppdragets syfte","vad är det här för uppdrag","varför jaga kobolder"}},{q="Vem oroar sig över koboldernas rörelser?",a="Marshal McBride, befälhavaren i Northshire Valley, oroar sig över koboldernas rörelser. En lokal vägvisare tillhandahåller spårningskitet så att du kan följa deras spår ut ur dalen och mot det större Elwynn Forest.",al={"vem ger spårningskitet","vem oroar sig över kobolder"}},{q="Vart leder koboldspåren?",a="Spåren leder ut ur Northshire och rakt mot Fargodeep Mine i centrala Elwynn Forest, en plats som är kraftigt översvämmad av kobolder.",al={"vart leder spåren","koboldernas mål","vart beger sig kobolderna"}},{q="Vem är Marshal Dughan?",a="Marshal Dughan är befälhavare för Stormwinds vaktgarnison i Goldshire. Han samordnar det lokala försvaret i Elwynn Forest och tar emot rapporter om hot som närmar sig.",al={"vem är marshal dughan","var finns dughan","rapportera till dughan"}},{q="Varför beger sig kobolderna till Fargodeep Mine?",a="Fargodeep Mine är en etablerad gruva i Elwynn Forest som redan är angripen av kobolder. Att mer ohyra rör sig mot gruvan innebär att problemen för de lokala arbetarna och närliggande bosättningarna förvärras.",al={"varför fargodeep mine","kobolder i fargodeep"}},{q="Vad händer när du når Goldshire?",a="När du har lämnat din rapport bekräftar Marshal Dughan att Fargodeep Mine är angripen av kobolder. Han blir inte förvånad, utan förbereder sig på att rekrytera dugliga kämpar för att ta itu med angreppet i gruvan.",al={"vad händer efter rapporten","dughans reaktion"}}},fp="27,163,19.213.0,24.257.1,30.171.0,44.202.0,32.119.0,22.168.0,46.138.0,38.166.0"}
P.entries["quest:91775"] = {n="Book Return",s="Book Return är ett uppdrag i Elwynn Forest där äventyrare ska återfinna Brother Paxtons förlorade läsböcker i de angripna djupen av Fargodeep Mine. Bland de viktigaste saknade volymerna finns ”Fun with Elementals”, en nybörjarguide som riskerar att ge gruvans kobolder farliga förmågor att frammana elementarer om den blir kvar i deras händer.",h="Book Return är ett uppdrag i Elwynn Forest där äventyrare ska återfinna Brother Paxtons förlorade läsböcker i...",kw={"book return","brother paxton","elwynn forest","fargodeep mine","fun with elementals","goldshire","kobold","marshal dughan"},ang={["class:Mage"]="Slarvig hantering av magiska handböcker som ”Fun with Elementals” innebär en allvarlig fara om de lämnas inom räckhåll för enkla underjordiska varelser som kobolder.",["faction:Alliance"]="Biblioteken i Northshire Abbey och garnisonen i Goldshire samarbetar för att skydda civil litteratur och farliga magiska texter från skadedjuren i Elwynn."},sec={{t="Förlorade sidor i mörkret",b="Medan Marshal Dughan undersöker det växande koboldhotet i Fargodeep Mine ger han äventyrarna i uppdrag att återfinna saknade volymer som tillhör Brother Paxton från Northshire Abbey. Bland texterna som försvunnit i de dunkla underjordiska gångarna finns en särskilt riskabel handbok med titeln ”Fun with Elementals”. Paxton fruktar att instruktionerna är så lättbegripliga att till och med gruvans obildade kobolder skulle kunna tyda dem och frammana en elementarvarelse i djupet."},{t="Kunskap i fara",b="Fargodeep Mine var en gång en lönsam guldgruva för Stormwind, men de senaste problemen har låtit skadedjur ta över de lägre nivåerna. Medan Elwynns försvarare får allt mindre resurser måste återfunna texter förvaras säkert i en skyddande bokväska för att klara de fuktiga, förrädiska grottorna. Genom att återhämta Paxtons förlorade bibliotek bevaras vanliga skrifter och farliga magiska läror hålls borta från obildade händer."}},faq={{q="Vad är uppdraget Book Return?",a="Book Return är ett uppdrag från Marshal Dughan i Goldshire. Det går ut på att återfinna böcker som tillhör Brother Paxton och försvann i Fargodeep Mine. Utöver en mängd allmän läsning är Paxton särskilt angelägen om att få tillbaka en magisk handbok med titeln ”Fun with Elementals”.",al={"vad är book return","uppdraget book return","vem ger book return"}},{q="Varför finns Brother Paxtons böcker i Fargodeep Mine?",a="Kobolderna som stal Brother Paxtons böcker från Northshire spårades till Fargodeep Mine, som nyligen har blivit översvämmad av kobolder. Paxton vill skyndsamt få böckerna insamlade innan de förstörs eller missbrukas.",al={"varför finns paxtons böcker i gruvan","hur hamnade böckerna i fargodeep","varför finns böcker i fargodeep mine"}},{q="Vad är boken ”Fun with Elementals”?",a="”Fun with Elementals” är en grundläggande bok om att frammana varelser som Brother Paxton desperat vill återfå. Han fruktar att instruktionerna är så elementära och enkla att till och med en trögtänkt kobold skulle kunna följa dem av misstag och frammana en elementartjänare djupt inne i gruvan.",al={"fun with elementals","vad är fun with elementals","paxtons elementarbok"}},{q="Vem är Brother Paxton?",a="Brother Paxton är en präst från Northshire Abbey som är känd för sin hängivenhet åt studier, arkiv och litteratur. Hans oro över förlorad läsning handlar om mer än borttappad egendom, eftersom vissa texter innehåller kraftfull, grundläggande magi.",al={"vem är brother paxton","paxtons bakgrund","bibliotekarien paxton"}},{q="Varför är Marshal Dughan inblandad i att återfinna böckerna?",a="Marshal Dughan leder försvaret av Elwynn Forest från Goldshire. När han skickar ut äventyrare för att undersöka koboldangreppet som hotar Fargodeep Mine passar han på att hjälpa Brother Paxton att återfå sina saknade volymer innan kobolderna utgör ett ännu större magiskt hot.",al={"varför bryr sig dughan om böcker","marshal dughan och böckerna"}},{q="Kan en kobold verkligen frammana en elementar?",a="Kobolder är vanligtvis obildade tunnelinvånare som är kända för geomanti och eld, men Brother Paxton oroar sig för att en enkel instruktionsbok kan ge dem möjlighet att frammana elementarkrafter och göra ett redan farligt angrepp mycket värre.",al={"kan kobolder använda magi","kan kobolder frammana elementarer"}}},fp="11,179,22.274.0,18.332.0,30.188.0,53.194.0,39.213.0,22.141.0,51.230.0,42.149.0"}
P.entries["quest:91777"] = {n="Rare Books",s="Rare Books är ett alliansuppdrag i Northshire Valley där du ska återta två stulna magiska grundböcker åt Brother Paxton. Kobolder har släpat texterna till Jasperlode Mine, där de verkar studera elementär magi och åkallningsritualer.",h="Rare Books är ett alliansuppdrag i Northshire Valley där du ska återta två stulna magiska grundböcker åt...",kw={"arcane explainer","brother paxton","geomanti","jasperlode mine","kobold","northshire abbey","northshire valley","rare books"},ang={["class:Mage"]="Grundböcker som Geomancy for Curious Young Wizards och Arcane Explainer är märklig läsning för kobolder under jord, men noviser inom arkan magi känner igen grundprinciperna som studeras.",["faction:Alliance"]="När du återtar Northshire Abbeys stulna intellektuella egendom från Jasperlode Mine hjälper du till att skydda dalens kulturarv och stödja den lokala milisen."},sec={{t="Saknade från klostret",b="Brother Paxton i Northshire Abbey står inför en kris i biblioteket: skadedjur som härjar i dalen har burit bort flera böcker. Bara två böcker saknas fortfarande i hans katalog: ”Geomancy for Curious Young Wizards” och ”Arcane Explainer: Magical Stuff in Simple Words”. Kobolderna som tagit över Jasperlode Mine släpade böckerna till gruvans djup."},{t="Magiska kobolder i Jasperlode",b="Det är oväntat bråttom att återfå de här enkla texterna. Kobolder är oftast kända för småstölder och gruvhackor, men kobolderna i Jasperlode Mine har börjat experimentera med lärorna i handböckerna. En koboldlärling sågs redan försöka åkalla en elementarvarelse, vilket väcker oro för vad en mer erfaren geomantiker eller mästare skulle kunna frammana om den fick behålla den magiska litteraturen."}},faq={{q="Vad är uppdraget Rare Books?",a="Rare Books är ett uppdrag i Northshire där du ska återta de två sista stulna böckerna i Brother Paxtons katalog. De har hamnat i händerna på kobolder djupt inne i Jasperlode Mine.",al={"uppdraget rare books","vad är rare books","vad är det här för uppdrag"}},{q="Vem är Brother Paxton?",a="Brother Paxton är en präst som bor i Northshire Abbey och sköter klostrets samling av böcker och dokument. Han förlitar sig på äventyrare för att återfå böcker som stulits av invaderande kobolder.",al={"vem är paxton","brother paxtons bakgrund","klostrets bibliotekarie"}},{q="Vilka böcker ska återtas?",a="De två saknade böckerna är ”Geomancy for Curious Young Wizards” och ”Arcane Explainer: Magical Stuff in Simple Words”. Båda är introduktionstexter om arkan och magisk teori.",al={"vilka böcker saknas","titlar på stulna böcker","saknade biblioteksböcker"}},{q="Var finns de saknade böckerna?",a="De stulna böckerna finns i Jasperlode Mine, en angripen guldgruva i Northshire Valley som har tagits över av koboldgrävare och geomantiker.",al={"var finns böckerna","böckernas platser","var hittar man böckerna"}},{q="Varför tog kobolderna böcker om magi?",a="Kobolderna i Jasperlode Mine verkar använda de stulna magiska texterna för att experimentera med geomanti och besvärjelser. Det rapporterades till och med att en lärling försökt åkalla en elementarvarelse med hjälp av den stulna kunskapen.",al={"varför har kobolder böcker","kan kobolder läsa","koboldmagiker"}},{q="Varför belönar Brother Paxton med vapen avsedda för milisen?",a="Brother Paxton belönar sina hjälpare med reservvapen som ursprungligen lagrats för den lokala milisen i Northshire. Han anser att vapnen gör större nytta hos äventyrare som aktivt hanterar hoten i dalen.",al={"paxtons vapenbelöning","varför milisvapen","klostrets vapen"}}},fp="10,130,22.288.0,28.195.1,29.128.0,22.158.0,33.151.0,36.114.0,40.139.0,64.161.0"}
P.entries["quest:918"] = {n="Timberling Seeds",s="Timberling Seeds är ett tidigt uppdrag från botanisten Denalan vid Lake Al'Ameth i Teldrassil. Denalan oroar sig över att traktens naturelementaler blir allt fientligare och vill samla in deras frön för att pröva om näringsrik jord kan ge lugnare och mer harmonisk växtlighet. Uppdraget ger en inblick i nattalvernas örtkännares stillsamma försök att förstå de subtila plågor som drabbar Världsträdet.",h="Timberling Seeds är ett tidigt uppdrag från botanisten Denalan vid Lake Al'Ameth i Teldrassil.",kw={"botanik","denalan","elementaler","lake al'ameth","frön","teldrassil","timberling"},ang={["class:Druid"]="Druider känner en stark samhörighet med naturandar. Genom att hjälpa Denalan med hans studier kan du bevara den elementala balansen utan att enbart ta till våldsam utrensning.",["profession:Herbalism"]="Den som känner Teldrassils växtlighet kan uppskatta Denalans botaniska experiment, som utforskar det fina samspelet mellan växtfrön och näringsrik jord.",["race:NightElf"]="För kaldorei är timberlings tydliga mått på hur Teldrassil mår. Att se dessa milda andar förvildas är ett kusligt tecken på att deras nya hem inte mår bra."},sec={{t="Orolig natur",b="Timberlings är naturelementaler som hör hemma bland Teldrassils grenar och är nära knutna till växtlighetens hälsa och livskraft. Vanligtvis speglar de skogens balans och är fridfulla, men deras senaste, oförklarliga fientlighet har oroat de lokala nattalverna. I stället för att bara röja undan dem hoppas botanisten Denalan förstå vad som gör dem så upprörda."},{t="Frön till ny växtlighet",b="Denalan misstänker att skadan finns djupt nere i själva marken och vill därför få nya timberlings att gro i näringsrik, noggrant behandlad jord. Genom att samla frön från de vandrande timberlings nära Lake Al'Ameth hoppas han kunna fostra en mildare generation elementaler och ta reda på om markens fördärv kan motverkas från rötterna och uppåt."}},faq={{q="Vad är timberlings?",a="Timberlings är små, växtlika naturelementaler som finns på Teldrassil. De återspeglar den stora trädets växt- och djurlivs naturliga ordning och livscykel.",al={"timberlingarnas historia","vad är timberlings","naturelementaler på teldrassil"}},{q="Varför har timberlings blivit aggressiva?",a="Denalan misstänker ett underliggande fel eller en förorening i Teldrassils jord. Som elementala uttryck för trädets ekologi återspeglar timberlings det växande fördärv som sprider sig över ön.",al={"varför är timberlings arga","timberlingarnas fientlighet","arga timberlings"}},{q="Vem är Denalan?",a="Denalan är en nattalvskännare av naturen och botanist som sköter en liten trädgårdsfristad vid Lake Al'Ameths östra strand. Där studerar han Teldrassils ovanliga växter och jordar.",al={"denalans historia","vem är denalan","botanist vid lake al'ameth"}},{q="Var kan man samla timberlingfrön?",a="Timberlings strövar omkring i de skuggiga snåren, längs stränderna och på skogsgläntorna runt Lake Al'Ameth i centrala Teldrassil.",al={"var hittar man timberlingfrön","timberlingarnas platser","frön vid lake al'ameth"}},{q="Vad tänker Denalan göra med fröna?",a="Denalan tänker odla fröna i särskilda, renade jordblandningar som han har utvecklat. Han hoppas få fram fogliga timberlings som inte påverkas av skogens oro.",al={"vad händer med fröna","denalans plan","så timberlingfrön"}},{q="Hur hänger detta ihop med Teldrassils större problem?",a="De här enkla naturandarnas aggression är ett av de tidigaste tecknen på att Teldrassil lider av en onaturlig besmittelse. Det leder forskare vidare till djupare undersökningar i Darnassus.",al={"teldrassils fördärv","varför mår teldrassil dåligt","trädets fördärv"}}},fx={["0bbca4e0"]={q="Varför vill Denalan att du samlar in timberlingfrön?",a="Denalan har sett att Teldrassils naturelementaler har blivit ovanligt våldsamma, ett oroande tecken på att något är fel med själva världsträdet. Han tror att fördärvet kommer från förorenad jord och hoppas kunna odla nya frön i särskild jord för att få fram lugna, fogliga timberlings och bevisa att marken kan läka.",al={"varför denalan vill ha timberlingfrön","denalans motiv för fröna","varför denalan behöver frön"}},["024ee5fc"]={q="Varför måste du jaga timberlings runt Lake Al'Ameth?",a="Timberlings är växtliknande naturelementaler som strövar längs Lake Al'Ameths stränder. Eftersom de är nära knutna till miljön bär de på frön som Denalan behöver för sin forskning. Deras plötsliga raseri gör det tyvärr omöjligt att samla in frön i fred, så du måste kämpa mot dem för att få proverna.",al={"varför döda timberlings","timberlings mål","timberlings vid lake al'ameth"}}},fp="16,302,15.337.0,21.289.0,21.154.0,43.168.0,15.162.0,39.107.0,44.159.0,53.174.0"}
P.entries["quest:91858"] = {n="Diplomatic Incident",s="Två dignitärer från Earthen Ring har försvunnit i Silverpine Forest på väg till Tarren Mill. Danitha skickar dig till Trevan Rol vid The Sepulcher för att få veta mer och hjälpa till att säkra legitimiteten för Horde.",h="Två dignitärer från Earthen Ring har försvunnit i Silverpine Forest på väg till Tarren Mill.",kw={"danitha","dignitärer","diplomatisk incident","earthen ring","horde","försvunna resenärer","the sepulcher","silverpine forest","tarren mill","trevan rol"},sec={{t="Försvunna resenärer",b="Danitha skickar dig till Trevan Rol vid The Sepulcher i Silverpine Forest. Två dignitärer från Earthen Ring försvann på väg mot Tarren Mill, och föga är känt utöver rykten om en diplomatisk incident. Att hitta dem skulle kunna ge Horde legitimitet. Trevan säger att du har hamnat i en rejäl röra."}},faq={{q="Vilka försvann i Silverpine?",a="Två dignitärer från Earthen Ring försvann i Silverpine Forest på väg till Tarren Mill.",al={"försvunna dignitärer","resenärer från earthen ring","vilka försvann"}},{q="Vart ska jag gå för att få information?",a="Danitha skickar dig för att tala med Trevan Rol vid The Sepulcher i Silverpine Forest.",al={"var är trevan rol","hitta trevan","the sepulcher"}},{q="Varför vill Danitha att resenärerna ska hittas?",a="Att hitta de försvunna dignitärerna från Earthen Ring skulle kunna ge Horde legitimitet.",al={"varför hitta dem","legitimitet för horde","diplomatisk incident"}},{q="Vad hände med dignitärerna?",a="De försvann i Silverpine Forest på väg mot Tarren Mill. Ingen vet var de befinner sig.",al={"vad hände i silverpine","varför är de försvunna","var dignitärerna befinner sig"}}},fp="19,204,17.306.0,31.103.0,30.81.0,42.85.0,33.105.0"}
P.entries["quest:91859"] = {n="A Curious Pair",s="A Curious Pair börjar när Trevan Rol får syn på ett ovanligt par som passerar genom The Sepulcher i Silverpine Forest. Under Earthen Rings fana sågs en tauren resa tillsammans med en high elf, en så ovanlig allians på Horde-territorium att den genast väcker misstankar.",h="A Curious Pair börjar när Trevan Rol får syn på ett ovanligt par som passerar genom The Sepulcher i...",kw={"curious pair","deathguard baldren","earthen ring","high elf","the sepulcher","silverpine forest","tauren","trevan rol"},ang={["class:Shaman"]="Att Earthen Ring reser tillsammans med en alv är ovanligt även för erfarna shamaner, som vet att Ringens traditioner sällan omfattar quel'dorei.",["race:Tauren"]="Tauren-äventyrare kan känna sig kluvna när de ser en av sina egna resa tillsammans med en främmande alv genom Lordaeron och dra till sig Forsaken-vakternas skarpa blickar.",["race:Undead"]="För Forsaken som vaktar The Sepulcher bör varje utomstående som tar sig genom Silverpine Forest granskas noga, särskilt med tanke på Lordaerons splittrade politiska läge."},sec={{t="Ögon i The Sepulcher",b="The Sepulcher är en dyster rastplats där främlingar granskas noggrant, särskilt de som säger sig ha diplomatiska ärenden. När två representanter som uppgav sig tillhöra Earthen Ring färdades längs vägen fick den lokala spejaren Trevan Rol syn på dem. Att en tauren färdades under den shamanistiska ordens fana förvånade ingen, men hans beslöjade följeslagare tedde sig ytterst märklig för Forsaken: en otvetydig high elf."},{t="Ett egendomligt partnerskap",b="Att en quel'dorei öppet reser tillsammans med en medlem av Hordes shamanistiska kretsar väcker naturligtvis frågor hos Forsakens vaktposter. Earthen Ring ägnar sig vanligtvis åt elementens balans och skickar sällan high elves till Lordaeron, än mindre som följeslagare till tauren-sändebud. För att ta reda på vart detta ovanliga par tog vägen och vilka ärenden de kan ha i skogen hänvisas resenärer till Deathguard Baldren vid stadens utkant."}},faq={{q="Vilka är de två resenärer som nämns i det här uppdraget?",a="Enligt Trevan Rol utgav sig resenärerna för att vara dignitärer från Earthen Ring. Den ena var en tauren, vilket är typiskt för den shamanistiska organisationen, men hans reskamrat identifierades som en beslöjad high elf.",al={"vilka är det märkliga paret","vilka passerade genom sepulcher","vilka var resenärerna"}},{q="Varför är det så ovanligt att en high elf reser med en tauren?",a="High elves har historiska band till Alliansen och arkan magi, medan tauren är hängivna medlemmar av Horden och utövar shamanism på djupet. Att se medlemmar av dessa två folk resa tillsammans genom Hordenkontrollerade Silverpine Forest under Earthen Rings fana är en ytterst ovanlig och misstänkt syn.",al={"varför är en high elf med en tauren märkligt","tauren och high elf-lore"}},{q="Vem ger uppdraget A Curious Pair?",a="Uppdraget ges av Trevan Rol i The Sepulcher, en utpost i Silverpine Forest.",al={"uppdragsgivare","var hämtar man a curious pair"}},{q="Var hittar jag Deathguard Baldren?",a="Deathguard Baldren står på vakt nära ingången till The Sepulcher i Silverpine Forest och håller uppsikt över resenärer längs vägen.",al={"baldren plats","var är baldren"}},{q="Vad är Earthen Ring?",a="Earthen Ring är en uråldrig organisation av shamaner som har vigt sig åt att bevara elementens balans och hela andlig disharmoni i hela världen. Organisationen består mest av shamaner som tauren och orcher, men dess diplomater reser ibland till avlägsna länder.",al={"earthen ring-lore","vad är earthen ring"}},{q="Är high elf en fiende till Forsaken?",a="Det är inte genast klart. Trevan Rol påpekar att alven var beslöjad och reste under förevändning av diplomatiska ärenden tillsammans med en tauren, vilket får Forsaken att ifrågasätta deras syfte i stället för att gå till angrepp direkt.",al={"är de fientliga","är alven en fiende"}}},fx={f81f4edc={q="Varför vill Trevan Rol att jag undersöker resenärerna?",a="Trevan Rol är förbryllad och misstänksam efter att ha sett en beslöjad högalf färdas öppet tillsammans med en tauren under The Earthen Rings fana. Silverpine är farligt Horde-territorium, och att en medlem av quel'dorei passerar utan förklaring är mycket ovanligt. Trevan vill ta reda på vad det märkliga paret gör i Forsakens länder, men efter att ha berättat allt han själv såg skickar han dig till stadens ingång för att undersöka vad vakterna har upptäckt.",al={"varför bryr sig trevan","trevan rols motiv","varför undersöka resenärerna"}}},fp="14,190,21.424.0,22.381.0,50.137.0,53.239.0,36.79.0,35.123.0,25.269.0,41.200.0"}
P.entries["quest:91860"] = {n="A Grim Fate",s="En patrulls iakttagelse på Fenris Isle väcker oro för en alv och ett resesällskap från Earthen Ring. Du ombeds undersöka sällskapets öde.",h="En patrulls iakttagelse på Fenris Isle väcker oro för en alv och ett resesällskap från Earthen Ring.",kw={"a grim fate","earthen ring","alv","fenris isle","gnoller","bål","tauren","resesällskap"},ang={["class:Paladin"]="Som paladin vädjar patrullvakten till din respekt för eder, även om han tvivlar på att sökandet är värt faran."},sec={{t="Ett bål på stranden",b="En patrullvakt såg gnoller lägga en stor kropp på ett bål vid stranden på Fenris Isle. Han såg varken någon alv eller några mindre kroppar och fruktar för resesällskapet. Du ombeds söka igenom ön och ta reda på vad som hände med dem."},{t="Kroppen",b="Kroppen på Fenris Isle är en tauren och är svårt söndergnagd. Alvkvinnan syns inte till någonstans. Hon kan fortfarande befinna sig längre in i den närliggande fästningen, så hennes öde är ännu ovisst."}},faq={{q="Vad såg patrullvakten?",a="En patrullvakt såg gnoller lägga en stor kropp på ett bål vid stranden på Fenris Isle.",al={"patrullens iakttagelse","gnoller och ett bål","vad fanns på stranden"}},{q="Vilka ingår i resesällskapet?",a="Sällskapet beskrivs som ett resesällskap från Earthen Ring.",al={"earthen rings sällskap","vilka var på resa","resande grupp"}},{q="Varför skickas jag till Fenris Isle?",a="Du ombeds undersöka Fenris Isle och ta reda på vilket öde som drabbade resesällskapet från Earthen Ring.",al={"varför fenris isle","vad letar jag efter","uppdraget a grim fate"}},{q="Sågs alven på stranden?",a="Patrullvakten såg ingen alv bland dem som befann sig vid bålet.",al={"var är alven","alv på fenris","såg de henne"}}},fp="11,144,19.212.0,8.181.1,27.79.0,27.58.0,35.96.0,30.49.0"}
P.entries["quest:91861"] = {n="Into Fenris Keep",s="En enda kropp ger hopp om att en saknad medlem i gruppen från Earthen Ring fortfarande kan vara vid liv. Du ombeds söka igenom Fenris Keep efter fången.",h="En enda kropp ger hopp om att en saknad medlem i gruppen från Earthen Ring fortfarande kan vara vid liv.",kw={"fånge","earthen ring","fenris keep","hadrec","high elf","into fenris keep","saknad medlem","trevan"},sec={{t="Ett sökande i Fenris Keep",b="En medlem i gruppen från Earthen Ring saknas, och du ombeds söka igenom Fenris Keep efter personen. Trevan och Hadrec beskrev en High Elf inne i den närliggande fästningen. Eftersom bara en kropp hittades finns det hopp om att den saknade gruppmedlemmen fortfarande är vid liv."},{t="En vädjan om hjälp",b="Inne i Fenris Keep hittar du den saknade High Elf som ber en Forsaken om hjälp att fly. Tiden är knapp för fången."}},faq={{q="Vem letar jag efter i Fenris Keep?",a="Du letar efter en saknad medlem i gruppen från Earthen Ring, som Trevan och Hadrec beskrev som en High Elf.",al={"saknad person fenris","vem saknas","gruppen från earthen ring"}},{q="Varför finns det hopp om att den saknade personen är vid liv?",a="Bara en kropp hittades, vilket ger hopp om att den saknade High Elf fortfarande finns inne i Fenris Keep.",al={"bara en kropp","lever alven","fenris keep kropp"}},{q="Vem ber mig söka igenom Fenris Keep?",a="Uppmaningen är att undersöka Fenris Keep och försöka hitta den saknade medlemmen i gruppen från Earthen Ring.",al={"vem skickade mig","vem vill att jag letar","fenris keep uppmaning"}},{q="Vad ber fången om?",a="Fången ber en Forsaken om hjälp att bli fri och säger att tiden är knapp.",al={"befria mig","hjälp fången","vad vill alven"}}},fp="16,144,23.249.0,15.118.1,36.111.0,46.92.0,34.105.0,30.71.1"}
P.entries["quest:91862"] = {n="Lumina Windsinger",s="På Fenris Isle sitter en okänd fånge vid namn Lumina Windsinger instängd i en bur hos Rot Hide-gnollerna. Hon reste till Silverpine som inbjuden gäst hos The Earthen Ring och behöver att du tar nyckeln från gnollflocken och befriar henne.",h="På Fenris Isle sitter en okänd fånge vid namn Lumina Windsinger instängd i en bur hos Rot Hide-gnollerna.",kw={"arathi highlands","earthen ring","fenris isle","fenris isle key","lumina windsinger","rot hide-gnoller","shen'dorei","silverpine","skyborne","windshaper"},ang={["class:Shaman"]="Lumina och hennes följeslagare reste som gäster hos The Earthen Ring för att undersöka elementära konvergenser i Arathi innan de blev tillfångatagna.",["race:Skyborne"]="Lumina Windsinger är en av dina egna, en shen'dorei från The Windshapers, fångad långt hemifrån bland Rot Hide-gnollerna."},sec={{t="En fånge på ön",b="Lumina Windsinger sitter inlåst i en bur på Fenris Isle, omgiven av Silverpines ruttnande gnoller. Hon och hennes följeslagare Banon färdades genom skogen mot Arathi Highlands för att studera elementära konvergenser åt The Earthen Ring, men flocken tillfångatog henne innan de hann ta sig igenom. Nu behöver hon att du tar Fenris Isle Key från Rot Hide-gnollerna och låser upp buren."},{t="Ut ur buren",b="När du låser upp buren blir Lumina Windsinger fri från gnollerna, men hon varnar för att faran fortfarande lurar på ön. Resan kan inte fortsätta förrän ni båda har tagit er säkert undan Rot Hide-flocken."}},faq={{q="Vem är Lumina Windsinger?",a="Lumina Windsinger är en shen'dorei, en av Windshaper Skyborne, som kom till de här trakterna som gäst hos The Earthen Ring.",al={"vem är lumina","lumina windsinger identitet","är lumina en alv"}},{q="Varför hålls Lumina fången på Fenris Isle?",a="Rot Hide-gnollerna på Fenris Isle tillfångatog henne när hon och hennes följeslagare färdades genom Silverpine Forest mot Arathi Highlands.",al={"varför sitter lumina i en bur","vem fångade lumina","hur blev lumina fångad"}},{q="Vad gjorde Lumina i Silverpine?",a="Lumina och Banon gav sig av för att studera elementära konvergenser i Arathi Highlands innan Rot Hide-gnollerna satte stopp för deras resa.",al={"lumina banon arathi","varför resa till arathi","elementära konvergenser arathi"}},{q="Vem är Banon?",a="Banon är följeslagaren som reser tillsammans med Lumina Windsinger på deras färd mot Arathi Highlands.",al={"vem är banon","luminas följeslagare"}},{q="Var finns nyckeln till Luminas bur?",a="Rot Hide-gnollerna som stryker omkring på Fenris Isle har Fenris Isle Key, som behövs för att öppna hennes bur.",al={"hur öppnar man luminas bur","fenris isle key","var finns fenris isle key"}},{q="Är Lumina Windsinger en högalv?",a="Hon avvisar namnet quel'dorei och identifierar sig i stället som shen'dorei, en av Windshaper Skyborne.",al={"vad är shendorei","är lumina quel'dorei","skillnad mellan skyborne och quel'dorei"}}},fp="17,248,21.393.0,15.213.1,25.122.0,40.145.0,36.132.0,13.102.0,34.90.0,32.110.0"}
P.entries["quest:91899"] = {n="A Sealed Crate",s="A Sealed Crate står för handelsvaror som beslagtagits och återfunnits längs regionala vägar och i banditnästen. När tjuvar i allt högre grad stör leveranserna betalar handelsmän kringresande äventyrare för att återta förlorat gods och återställa tryggheten på vägarna.",h="A Sealed Crate står för handelsvaror som beslagtagits och återfunnits längs regionala vägar och i...",kw={"banditer","karavan","last","leverans","sealed crate","förnödenheter","tjuvar","handelsvägar"},sec={{t="Hotade handelsvägar",b="På senare tid har landsvägsbrottsligheten ökat, och organiserade banditer och laglösa tjuvar ger sig aktivt på vanliga handelsvägar. Handelsvagnar, packtåg och ensamma kurirer överfalls, så att lasten sprids ut längs vildmarksvägar eller förs bort till laglösa läger. Dessa omfattande plundringar hotar viktiga försörjningsleder mellan bosättningar."},{t="Återta förlorat gods",b="För att hålla varuflödet igång och återta stulna varor förlitar sig handelsmän och godshanterare på oberoende äventyrare som kan återfinna försvunnet gods. Förseglade lådor som räddas från banditer eller hittas övergivna i snåren kan lämnas in till handelsmän för att säkra varor, hejda olaglig handel på svarta marknaden och återställa tryggheten i den regionala handeln."}},faq={{q="Vad är A Sealed Crate?",a="A Sealed Crate står för handelsvaror och förlorade leveranser som har återfunnits längs vildmarksvägar. När du lämnar in dem säkrar du gods som annars skulle hamna i tjuvarnas händer och hjälper till att återupprätta en trygg handel.",al={"uppdrag med sealed crate","vad är en sealed crate","lämna in låda"}},{q="Varför plundrar banditer handelsvägar?",a="En plötslig ökning av banditer och laglösa som passar på tillfället har gjort resor längs vanliga vägar och handelsleder farliga. Karavaner och kurirer utsätts för angrepp och plundring, och lasten sprids ut över vildmarken.",al={"varför stjäl banditer lådor","banditer på handelsvägar","vem angriper karavaner"}},{q="Vem tar emot de återfunna lådorna?",a="Handelsmän och kvartermästare tar emot återfunna lådor för att registrera förlorad handelsvara och bygga upp förråd som är skyddade från kringströvande tjuvar. De ger ersättning till asätare och äventyrare som hämtar tillbaka dem.",al={"vem tar emot sealed crates","vart skickas sealed crates","låda leverans"}},{q="Kan du lämna in flera förseglade lådor?",a="Ja, handelsförmedlare uppmuntrar resande att fortsätta lämna in fler lådor som hittas längs vägarna och ute i vildmarken, eftersom banditer fortfarande stör de vanliga leveranserna.",al={"kan du upprepa sealed crate","fler lådor","finns det fler lådor"}},{q="Vad finns i en förseglad låda?",a="Lådorna innehåller återfunna handelsvaror och kommersiellt gods som stoppats under transporten. Även om kuriren som levererar dem inte har öppnat dem återförs de till handelsförråden för att minska förlusterna från landsvägsrövare.",al={"vad finns i sealed crate","innehållet i en förseglad låda","vad finns i lådorna"}},{q="Varifrån kommer de återfunna lådorna?",a="Lådorna hittas oftast övergivna längs farliga handelsleder, nära banditläger eller hos laglösa som har plundrat försändelser.",al={"var hittar man sealed crates","hur får man tag på sealed crates","banditernas lådor"}}},fp="14,157,23.280.0,21.309.0,23.163.0,45.155.0,36.196.0,40.150.0,30.193.0,42.127.0"}
P.entries["quest:919"] = {n="Timberling Sprouts",s="Timberling Sprouts är ett uppdrag från naturvårdaren Denalan vid Lake Al'Ameth i centrala Teldrassil. Denalan oroas över hur skogsplantor plötsligt och onaturligt sprider sig runt sjön och ber resande rycka upp dem innan de växer till fientliga timberlings. Uppdraget visar tidiga tecken på att en krypande fördärvelse rubbar balansen i det nyväxta världsträdet.",h="Timberling Sprouts är ett uppdrag från naturvårdaren Denalan vid Lake Al'Ameth i centrala Teldrassil.",kw={"fördärv","denalan","lake al'ameth","smitta","teldrassil","timberling-plantor","timberlings","ogräsrensning"},ang={["class:Druid"]="Druider ansvarar för att skydda naturens sköra balans. Att gallra bort fördärvade plantor är en sorglig men nödvändig plikt för att värna det större ekosystemet.",["profession:Herbalism"]="Örtkunniga har ett skarpt öga för hur frisk växtlighet ska växa och ser genast att plantorna är sjuka och onaturligt förvridna.",["race:NightElf"]="För kaldorei är Teldrassil tänkt att vara en ny fristad. Därför är fördärvad växtlighet kring heliga vatten som Lake Al'Ameth ett djupt oroande omen."},sec={{t="Ogräsrensning vid Lake Al'Ameth",b="Längs Lake Al'Ameths fridfulla stränder har märkliga, växtlika varelser som kallas timberlings börjat föröka sig i alarmerande takt. De spirande timberling-plantorna frodas inte i harmoni med skogen, utan visar tecken på fördärvelse redan från det att de slår rot. Denalan, en hängiven naturforskare som bor intill sjön, inser att plantorna inte går att rädda. Om de lämnas åt sitt öde växer de snabbt till aggressiva, barkklädda varelser som hotar det lokala djurlivet och ovaksamma resande. Att samla in och förstöra plantorna är ett omedelbart försvar som håller lunden ren."},{t="Tecken på ett djupare fördärv",b="Att rycka upp plantorna hjälper till att hantera den lokala faran, men Denalan bävar över hur snabbt de dyker upp. Deras ohämmade spridning är ett onaturligt fenomen på Teldrassil. De fördärvade plantorna är inte ett isolerat angrepp, utan ett symtom på en djupare sjukdom som hotar själva världsträdets rötter och jordmån. Denalan och druiderna i Darnassus försöker skyndsamt lösa gåtan."}},faq={{q="Vad är timberling-plantor?",a="Timberling-plantor är timberlingarnas späda ungstadium, små elementära växtvarelser som hör hemma i Teldrassils grenverk. Tyvärr är de som gror vid Lake Al'Ameth fördärvade och växer snabbt till fientliga, aggressiva varelser.",al={"vad är timberlings","timberling-plantornas historia","vad är en planta"}},{q="Vem är Denalan?",a="Denalan är en örtkunnig naturvårdare som bor i ett stillsamt läger nära Lake Al'Ameths stränder. Han vakar över grenverkets växtlighet och studerar de ekologiska förändringarna och märkliga fördärv som får fäste på Teldrassil.",al={"vem ger uppdraget timberling sprouts","denalans historia","uppdragsgivare vid lake al'ameth"}},{q="Varför kan plantorna inte bara läkas eller renas?",a="Denalan ser att plantorna redan är bortom all räddning när de tittar upp ur jorden. Det är meningslöst att försöka återställa dem, så gallring är det enda praktiska sättet att hindra dem från att växa till farliga hot.",al={"går plantorna att rädda","varför förstöra timberlings","är plantorna bortom all räddning"}},{q="Var finns plantorna?",a="Plantorna slår rot längs de leriga stränderna, i det grunda vattnet och vid de lummiga bankarna runt Lake Al'Ameth i centrala Teldrassil.",al={"timberling-plantornas plats","var hittar man plantor","plantor vid lake al'ameth"}},{q="Varför skjuter timberlings upp så aggressivt?",a="Den onaturliga ökningen av fientliga timberlings drivs av en fördärvande kraft som sprider sig i Teldrassils jord och vatten. Även unga skott fördärvas innan de blommar ut, vilket tyder på en bakomliggande farsot som angriper det unga världsträdet.",al={"varför är timberlings ilskna","vad fördärvar plantorna","timberlingarnas fördärv"}},{q="Vad händer när plantorna har rensats bort?",a="Denalan fortsätter undersöka vad som orsakar sjöns sjukdom och granskar prover av jord, frön och vatten för att spåra farsotens källa.",al={"nästa uppdrag efter plantorna","vad följer efter timberling sprouts"}}},fx={["24c78c98"]={q="Varför vill Denalan att timberlingskotten rensas bort?",a="Denalan vakar över Lake Al'Ameth och fruktar att skotten redan är för fördärvade för att kunna räddas. Om de lämnas ifred växer de upp till våldsamma, fullvuxna timberlings som hotar alla som går längs stränderna. Genom att rycka upp dem medan de är små hoppas han hålla den omgivande marken ren och vinna tid att hitta grundorsaken till smittan som sprider sig genom Teldrassils vatten.",al={"denalans motiv för skotten","varför rensa bort skott","varför vill denalan ha skott"}}},fp="18,148,21.277.0,23.192.0,28.160.0,15.152.0,53.166.0,28.104.0,54.188.0,42.104.0"}
P.entries["quest:91900"] = {n="A Sealed Crate",s="A Sealed Crate står för handelsvaror som bärgats från störda handelsleder. När banditer och tjuvar allt oftare plundrar vägarna förlitar sig lokala köpmän på kringresande äventyrare som återlämnar övergivna försändelser mot betalning.",h="A Sealed Crate står för handelsvaror som bärgats från störda handelsleder.",kw={"banditer","last","ersättning","leverans","sealed crate","försändelse","tjuvar","handelsleder"},sec={{t="Störda handelsleder",b="Handeln genom landet har blivit allt farligare på grund av en våg av banditdåd och stölder längs vägarna. Karavaner och kurirer utsätts regelbundet för bakhåll längs etablerade handelsvägar, så övergivna vagnar och förlorade försändelser ligger utspridda i vildmarken. För att hindra dessa värdefulla varor från att försvinna helt förlitar sig köpmän och förrådsansvariga på kringresande äventyrare som bär tillbaka vilsekomna lådor i oskadat skick."},{t="Bärgning av last",b="Om du bär en förseglad låda till en anvisad mottagningsdepå får du en omedelbar belöning. Mottagarna samlar ihop det återfunna godset och sköter sortering och vidare distribution, så att handeln kan fortsätta trots det ständiga hotet från lokala rövare och tjuvar. Så länge vägarna förblir omstridda är det ett viktigt arbete för varje resenär att återlämna förlorad last."}},faq={{q="Vad finns i en förseglad låda?",a="Lådan innehåller återfunna handelsvaror som stoppats eller gått förlorade längs handelslederna. Köpmän och mottagare betalar kurirer och äventyrare för att hämta tillbaka dem oöppnade, i stället för att låta innehållet hamna i kriminella händer.",al={"vad finns i lådan","lådans innehåll","vad finns i en förseglad låda"}},{q="Varför ber folk om att få förseglade lådor levererade?",a="En nylig våg av banditer och tjuvar har stört aktiva handelsleder och lämnat last utspridd eller stulen. Handelsmän och lokala organisatörer erbjuder belöningar och ersättning till den som är villig att återfinna och återlämna dessa förlorade försändelser.",al={"varför återlämna lådor","vem vill ha förseglade lådor","varför lådan ska levereras"}},{q="Kan du lämna in flera förseglade lådor?",a="Ja. Banditernas fortsatta räder mot handelslederna gör att övergivna och stulna lådor fortfarande dyker upp längs oroliga vägar. Kurirer uppmuntras att ta med sig alla ytterligare lådor de hittar för att få mer ersättning.",al={"kan jag hitta fler lådor","var hittar jag lådor","fler förseglade lådor"}},{q="Vem stoppar handelslederna?",a="Lokala tjuvar och banditer har allt oftare gett sig på transportleder, överfallit karavaner och stoppat handeln. Många olika rövarband håller till i regionen, men följden blir densamma: försändelser överges eller beslagtas längs vägarna.",al={"vem stal lådorna","bandituppror och handelsleder","vem angriper försändelser"}},{q="Kan du öppna en förseglad låda själv?",a="Det är oklart om du kan öppna lådan själv. Lämna tillbaka återfunna lådor till mottagaren för att få betalt för leveransen.",al={"kan jag öppna lådan","öppna förseglad låda","varför hålla lådan förseglad"}},{q="Vem betalar för att försändelserna bärgas?",a="Lokala handelsansvariga och förrådsansvariga tar emot den återfunna lasten och betalar ersättning på plats. De hanterar lagret och styr fortsatt arbete med att återfinna gods.",al={"vem betalar för lådorna","vem ger lådbelöningen","ersättning för lådor"}}},fp="14,238,22.435.0,14.391.0,30.240.0,56.234.0,39.225.0,37.252.0,37.129.0,40.168.0"}
P.entries["quest:91901"] = {n="A Sealed Crate",s="En handelsman ber dig hämta förseglade lådor medan banditer och tjuvar slår till mot handelsvägarna. Andra övergivna lådor kan behöva samma hjälp.",h="En handelsman ber dig hämta förseglade lådor medan banditer och tjuvar slår till mot handelsvägarna.",kw={"banditer","låda","leverans","betalning","sealed crate","tjuvar","handelsvägar","handelsman"},sec={{t="Vid högen",b="Handelsmannen tackar dig för ditt hårda arbete och ber dig ställa leveransen bredvid en hög. En betalning väntar. Banditer och tjuvar har på sistone gett sig på handelsvägarna, så andra lådor som lämnats kvar kan också behöva hämtas hit."}},faq={{q="Varför lämnas lådor kvar?",a="Banditer och tjuvar har gett sig på handelsvägarna och lämnat lådor liggande.",al={"varför lådor överges","banditer stjäl lådor","problem med handelsvägar"}},{q="Vad ska jag göra med andra lådor?",a="Ta med andra lådor du hittar till handelsmannen, som säger att de tar hand om resten.",al={"var lämna lådor","hjälp med andra lådor","var lämna låda"}},{q="Vem ber om lådan?",a="En handelsman ber dig ställa leveransen bredvid en hög och erbjuder betalning för ditt arbete.",al={"vem vill ha lådan","den som ger lådan","vem tar emot leveransen"}}},fp="14,138,11.243.0,33.85.0,35.78.0,28.87.0"}
P.entries["quest:91904"] = {n="A Sealed Crate",s="A Sealed Crate är en inlämningsuppgift som går ut på att återlämna handelsvaror som rövare har lagt beslag på eller som gått förlorade längs handelsvägar. Äventyrare lämnar tillbaka uppsnappad last till handelsmän för att trygga regionens försörjningsleder och få betalt.",h="A Sealed Crate är en inlämningsuppgift som går ut på att återlämna handelsvaror som rövare har lagt beslag på...",kw={"a sealed crate","banditer","karavan","last","låda","leverans","köpmän","sealed crate","tjuvar","handelsleder"},sec={{t="Stulen last och farliga vägar",b="Vagnsleder och farleder har blivit farliga på grund av en kraftig ökning av bakhåll från banditer och tjuvar som ger sig på handelskaravaner. Ovetande åkare och kurirer förlorar ofta sina leveranser när de överrumplas, och tunga förseglade lådor blir liggande längs vilda vägar och stigar tills någon hittar dem."},{t="Trygga försörjningskedjan",b="Köpmän och försörjningssamordnare utlyser stående belöningar för återlämnade varor. Äventyrare som hittar borttappade lådor och fraktar dem till regionala uppsamlingsplatser hjälper till att återställa störda distributionsleder och får direkt betalt för att skydda handeln."}},faq={{q="Vad är en förseglad låda?",a="Förseglade lådor innehåller handelslast som har snappats upp eller kommit på avvägar längs handelsleder. Äventyrare som hittar de övergivna varorna kan lämna in dem till köpmän och lokala mottagare för att säkra lasten och få ersättning för bärgningsarbetet.",al={"syftet med förseglad låda","vad är en förseglad låda","vad används förseglade lådor till"}},{q="Varför ligger lådorna här?",a="En nylig våg av banditdåd och organiserade stölder har plågat regionens handelsleder. Vägstråtrövare och skurkar ger sig regelbundet på försörjningskaravaner och åkare, vilket leder till att leveranser stjäls, överges eller tappas längs vägen.",al={"vem tappade lådorna","varför är lådor borttappade","varför ligger lådor på vägen"}},{q="Vem vill ha tillbaka lådorna?",a="Karavansamordnare, kvartermästare och handelsmän tar emot upphittade lådor för att samla lasten på hög och sortera tillbaka varorna i de vanliga försörjningslederna. De ersätter alla som räddar deras saknade varor.",al={"vem köper förseglade lådor","vem vill ha förseglade lådor","lämna in låda"}},{q="Kan man titta inuti en förseglad låda?",a="Lådorna hålls låsta och förseglade under transporten för att skydda handelsvarorna. När du lämnar in dem oskadda kan logistikansvariga hantera varorna och betala den som återfunnit dem utan att de har manipulerats.",al={"kan jag öppna en förseglad låda","vad finns i lådan","öppna förseglad låda"}},{q="Kan du lämna in fler förseglade lådor senare?",a="Ja. Vägöverfall är fortfarande vanliga längs de stora lederna, så köpmän söker aktivt efter mer återfunnen last och uppmuntrar vandrare att lämna in fler lådor de hittar ute i vildmarken.",al={"fler lådor","kan jag lämna in fler lådor","kan lådorna lämnas in flera gånger"}},{q="Vilka ger sig på handelslederna?",a="Tjuvar och ficktjuvar har blivit allt fräckare i handelsområdena. De ger sig på handelsmännens leveranser för att stjäla värdefulla varor och störa distributionen mellan bosättningarna.",al={"banditattacker mot handelsleder","tjuvar stjäl varor","vem plundrar vägarna"}}},fp="14,154,32.206.0,25.220.0,23.163.0,34.163.0,32.187.0,35.158.0,48.154.0,37.141.0"}
P.entries["quest:91905"] = {n="A Sealed Crate",s="A Sealed Crate står för handelsvaror som bärgats från handelsvägar som störts av banditer och laglösa. Handelsmottagare betalar äventyrare för att hämta tillbaka de utspridda varorna och skydda dem mot den ökande vägkriminaliteten.",h="A Sealed Crate står för handelsvaror som bärgats från handelsvägar som störts av banditer och laglösa.",kw={"banditer","last","låda","leverans","köpmän","bärgning","sealed crate","tjuvar","handelsvägar"},sec={{t="Störda handelsvägar",b="Ökad laglöshet längs etablerade handelsvägar har gjort handelskaravaner sårbara och spritt lasten omkring sig. Vägbanditer och tjuvar överföll regelbundet försörjningslinjer, så att återfunna sändningar blev en vanlig syn i omstridda områden. Äventyrare som säkrar övergivna eller stulna lådor hjälper till att upprätthålla den lokala handeln trots laglösheten."},{t="Återfunnen last",b="Lokala handelsmottagare och lageransvariga är beroende av frilansande kurirer för att återfinna förlorade varor och föra dem tillbaka till lagerdepåer. Varje återlämnad låda stärker de lokala förråden och nekar laglösa bytet från vägrån. De som bärgar varorna får skälig ersättning för att våga sig ut på farliga vägar."}},faq={{q="Vad finns i den förseglade lådan?",a="Det exakta innehållet anges inte, men lådan står för återfunnen handelslast som stoppats längs handelsvägarna. Köpmän och lageransvariga vill gärna lägga undan varorna i säkra förråd, utom räckhåll för tjuvar.",al={"vad finns i den förseglade lådan","lådans innehåll","vad finns i lådan"}},{q="Varför ligger lådorna här?",a="Ett uppror bland banditer och tjuvar har lett till att handelsvägar stoppats, sändningar spritts och handelslådor övergivits eller stulits i hela regionen.",al={"varför har lådor kommit bort","vem stjäl lådor","banditer som stjäl handelsvaror"}},{q="Vem vill ha lådorna tillbaka?",a="Lokala köpmän och handelsansvariga tar emot återfunna lådor, lägger dem i säkra förråd och ersätter äventyrare som bärgar dem från farliga platser.",al={"vem tar emot lådorna","vart förs lådorna","lämna in lådor"}},{q="Går det att hitta fler förseglade lådor?",a="Ja. Eftersom banditer ständigt stör transporterna över land betalar lokala lageransvariga löpande äventyrare för att hämta fler lådor som hittas utspridda längs handelslederna.",al={"kan jag hitta fler lådor","upprepningsbara lådor","fler förseglade lådor"}},{q="Vad hotar handelsvägarna?",a="Handelsvägarna utsätts ständigt för påtryckningar från banditer och laglösa som ger sig på oskyddade karavaner. Därför betalar köpmän belöningar för återfunnen last.",al={"banditer vid handelsvägar","störningar i handeln","varför är vägarna osäkra"}},{q="Varför är lådan förseglad?",a="Uppdragstexten säger inte varför den är förseglad. Det är helt enkelt en förlorad lastlåda som du lämnar tillbaka till lageransvariga. De ställer den i sin hög och betalar dig för den.",al={"den förseglade lådans syfte","varför försegla lådan"}}},fp="14,143,22.268.0,15.245.0,32.139.0,34.124.0,32.154.0,36.137.0,37.123.0,24.118.0"}
P.entries["quest:91906"] = {n="A Sealed Crate",s="En handelsman ber dig lämna in en förseglad låda när banditverksamheten ökar längs handelsvägarna. Andra lådor som hittas längs vägen kan lämnas här för samma hantering.",h="En handelsman ber dig lämna in en förseglad låda när banditverksamheten ökar längs handelsvägarna.",kw={"banditer","låda","leverans","betalning","sealed crate","tjuvar","handelsvägar"},sec={{t="Handelsvaror",b="Banditer och tjuvar har börjat överfalla handelsvägarna, och en handelsman ber dig lämna en förseglad låda vid högen. Handelsmannen tackar dig för leveransen och säger att du kan lämna andra lådor här så tar de hand om dem. Handelsvaror är fortfarande i fara längs vägarna."}},faq={{q="Vad ska jag göra med den förseglade lådan?",a="Lämna lådan till handelsmannen, som placerar den vid högen.",al={"sealed crate","lådan levererad","vart ska lådan"}},{q="Varför blir lådor överfallna?",a="Banditer och tjuvar har på sistone överfallit handelsvägarna.",al={"banditer och lådor","tjuvar på handelsvägarna","varför saknas lådan"}},{q="Kan jag lämna andra lådor här?",a="Ja. Handelsmannen säger att du kan lämna andra lådor här, så tar de hand om dem.",al={"andra lådor","hittade en låda","fler lådleveranser"}},{q="Vad ger handelsmannen mig?",a="Handelsmannen erbjuder dig betalning för ditt arbete.",al={"betalning för lådan","ersättning","vilken betalning"}}},fp="14,168,11.262.0,35.61.0,33.63.0,30.75.0,29.44.0"}
P.entries["quest:91920"] = {n="Wild Eyes",s="Wild Eyes är ett uppdrag i Silverpine Forest där en sjuk Forsaken-spejare söker ett botemedel för att undvika en permanent andra död. Trött på Apothecary Renferrels verkningslösa hopkok baserade på hjärtan ber spejaren äventyrare samla murlocögon från Lake Lordamere för att få apotekaren att göra ett genombrott i sin forskning.",h="Wild Eyes är ett uppdrag i Silverpine Forest där en sjuk Forsaken-spejare söker ett botemedel för att undvika...",kw={"apothecary renferrel","deathstalker","forsakens alkemi","lake lordamere","murlocögon","the sepulcher","silverpine forest","wild eyes"},ang={["class:Rogue"]="Deathstalkers är Forsakens elitstyrka av spejare och lönnmördare, så att återställa deras fysiska förmåga är en högsta operativ prioritet i regionen.",["faction:Horde"]="Forsakens krigsinsats i Silverpine Forest är starkt beroende av Apothecary Renferrels forskning vid The Sepulcher för att hålla spejare och Deathstalkers vid fronten stridsdugliga.",["race:Undead"]="Forsakens soldater kämpar ständigt mot de odödas kroppsliga förfall och förlitar sig på Royal Apothecary Societys mörka hopkok för att behålla sin sviktande styrka."},sec={{t="Desperata åtgärder",b="I Silverpine Forest står en sjuk Forsaken Deathstalker inför den bistra verkligheten av kroppsligt förfall och en möjlig andra död. Missnöjd med de verkningslösa brygderna som Apothecary Renferrel kokar ihop riskerar spejaren Renferrels ökända vrede genom att söka ett alternativt botemedel längs Lake Lordameres kreaturshärjade stränder."},{t="Nya ingredienser vid The Sepulcher",b="Deathstalker misstänker att Renferrels senaste besatthet av att skörda hjärtan har gjort honom blind för andra användbara alkemiska ingredienser och ber äventyrare samla murlocögon. När de ovanliga organen lämnas till Renferrel vid The Sepulcher får det till slut den excentriske apotekaren att bredda sina experiment och ge den tynande spejaren nytt liv."}},faq={{q="Vem ber dig samla murlocögon?",a="En sjuk Forsaken Deathstalker i Silverpine Forest ber dig hjälpa till att återställa den sviktande styrkan. Om Renferrels misslyckade hopkok inte förbättras väntar en andra död, så spejaren tar en desperat chansning med alternativa ingredienser.",al={"vem ger wild eyes","uppdragsgivare för wild eyes","vem ber om murlocögon"}},{q="Varför kräver uppdraget murlocögon?",a="Deathstalker lägger märke till en svärm murlocer som angriper Lake Lordameres stränder och föreslår att deras ögon ska skördas. Spejaren hoppas att den nya ingrediensen ska få Apothecary Renferrel att experimentera med mer än bara hjärtan, som han är besatt av.",al={"varför murlocögon","vad används murlocögon till","murlocögon till brygd"}},{q="Hur reagerar Apothecary Renferrel på leveransen?",a="Apothecary Renferrel fnyser först och skyller brygdens misslyckande på att han fått för få hjärtan, snarare än på sin formel. Han medger dock att han inte hade tänkt på att använda murlocanatomi och går med på att blanda i den för att återställa Deathstalker.",al={"renferrels reaktion","vad säger renferrel","gillar renferrel ögonen"}},{q="Var finns Apothecary Renferrel?",a="Apothecary Renferrel bedriver sin mörka forskning vid The Sepulcher, Forsakens främsta utpost i Silverpine Forest.",al={"var finns apothecary renferrel","renferrels plats","var lämnar man in wild eyes"}},{q="Varför fungerade inte Renferrels ursprungliga brygd?",a="Enligt Renferrel misslyckades brygden eftersom han bara fick tre hjärtan, trots att receptet krävde sex. Den sjuka Deathstalker tyckte ändå inte att formeln gav några märkbara resultat.",al={"varför misslyckades brygden","varför fungerade renferrels brygd inte","deathstalkers brygd misslyckas"}},{q="Vad är Apothecary Renferrel besatt av?",a="Apothecary Renferrel har blivit närmast tunnelseende i sin fascination för att använda djurhjärtan i stärkande blandningar. Det gör honom blind för andra biologiska prover tills han får se murlocögon.",al={"renferrels besatthet av hjärtan","varför vill renferrel ha hjärtan"}}},fp="9,204,18.264.0,29.275.1,35.199.0,39.181.0,52.174.0,38.108.0,49.169.0,43.163.0"}
P.entries["quest:91921"] = {n="Return to Quinn (Again)",s="Return to Quinn (Again) är ett leveransuppdrag i Silverpine Forest där en kurir för en stärkande alkemisk blandning till Quinn Yorick vid Ivar Patch. Den specialblandade brygden hindrar Quinn från att förfalla till en själlös gast och återställer hans krafter så att han kan fortsätta resa.",h="Return to Quinn (Again) är ett leveransuppdrag i Silverpine Forest där en kurir för en stärkande alkemisk...",kw={"gast","the ivar patch","quinn yorick","quinn's potion","återvänd till quinn","silverpine forest","sepulcher"},ang={["faction:Horde"]="Genom att hjälpa nödställda resenärer och utstötta i Silverpine Forest stärker man Horde:s inflytande i de pestdrabbade områdena norr om Sepulcher.",["race:Undead"]="Quinn Yoricks rädsla för att förfalla till en själlös gast visar hur skör balansen är när Forsaken försöker bevara sin fria vilja och sina fysiska förmågor."},sec={{t="Ett desperat botemedel",b="Norr om Sepulcher i Silverpine Forest vilar Quinn Yorick vid Ivar Patch, drabbad av en åkomma som hotar både hans kropp och hans förstånd. För att hejda tillståndet skickas en särskild alkemisk blandning, bryggd av sex hjärtan, till hans läger. För Forsaken och deras allierade är sådana botemedel ett viktigt steg för att hjälpa kringvandrande fränder innan förruttnelse och vansinne tar över."},{t="Att hejda förfallet",b="Quinn var nära att acceptera ett dystert öde: att förvandlas till en själlös gast. När han får och dricker den nybryggda drycken börjar botemedlet verka omedelbart. Hans livskraft återvänder, och han kan förbereda sig för kommande resor genom det pestdrabbade landskapet."}},faq={{q="Vem är Quinn Yorick?",a="Quinn Yorick är en drabbad resenär vid Ivar Patch, strax norr om Sepulcher i Silverpine Forest. Han behöver särskilda alkemiska blandningar för att hejda ett allvarligt kroppsligt förfall och återfå tillräckligt med kraft för att resa.",al={"vem är quinn","quinn yoricks bakgrund","vem är quinn yorick"}},{q="Vad är Quinn's Potion, och varför behöver han den?",a="Drycken har bryggts särskilt för att hjälpa Quinn Yorick att återhämta sig och hindra hans tillstånd från att förvärras. Utan den fruktade Quinn att han skulle duka under för förfallet och förvandlas till en själlös gast.",al={"vad gör drycken","syftet med quinns dryck","varför behöver quinn en dryck"}},{q="Var ligger Ivar Patch?",a="Ivar Patch är en utmärkt odlingslott strax norr om Sepulcher i Silverpine Forest. Den tjänar som Quinn Yoricks tillfälliga skydd medan han återhämtar sig.",al={"var ligger ivar patch","ivar patchs läge"}},{q="Vilka ingredienser finns i Quinn's Potion?",a="Botemedlet som levereras till Quinn är en alkemisk blandning bryggd av extrakt från sex hela hjärtan, avsedd att hejda kroppens förruttnelse.",al={"dryckens ingredienser","vad är quinns dryck gjord av","hjärtan i drycken"}},{q="Botar drycken Quinn Yorick?",a="När Quinn dricker den nyss levererade drycken känner han genast hur dess stärkande verkan sätter in. Han säger att han snart kommer att vara stark nog att fortsätta sina resor i stället för att förvandlas till en gast.",al={"vad händer med quinn","förvandlas quinn till en gast","quinns återhämtning"}},{q="Vem brygger drycken åt Quinn?",a="Apothecary Renferrel vid Sepulcher brygger drycken med extrakt från sex hela hjärtan. Med sin vanliga byråkratiska otålighet lämnar han över den och skyndar sig att avfärda kuriren innan mer pappersarbete uppstår.",al={"vem brygger quinns dryck","apotekare quinn"}}},fp="23,195,18.304.0,21.216.1,20.206.0,47.165.0,32.131.0,43.119.0,47.134.0,31.176.0"}
P.entries["quest:92"] = {n="Redridge Goulash",s="Redridge Goulash är en lokal mattradition som Chef Breanna håller vid liv i Lakeshire, en bosättning vid sjön. Efter att ha tömt sitt skafferi för att mätta Stormwinds garnison under de senaste Blackrock-orchernas anfall vänder sig Breanna till resande äventyrare för att fylla på förrådet av rejäla ingredienser från bergen.",h="Redridge Goulash är en lokal mattradition som Chef Breanna håller vid liv i Lakeshire, en bosättning vid sjön.",kw={"blackrock-orcher","chef breanna","kondorkött","goretusktryne","lakeshire","redridge goulash","redridge mountains","spindelkött"},ang={["faction:Alliance"]="Att Lakeshires förråd är så knappa är en tydlig påminnelse om hur Blackrock-orchernas invasion har drabbat Alliansens lokala garnisoner och civil infrastruktur.",["profession:Cooking"]="För kockar som utforskar Eastern Kingdoms visar Chef Breannas gryta hur påhittiga gränskockar förvandlar vildsinta bergsdjur till mättande och smakrik mat."},sec={{t="Ett tomt bergsskafferi",b="Lakeshire är ständigt belägrat av Blackrock-orcher, gnoller och vildsinta vilddjur. När det senaste orchupproret bröt ut längs bergsryggarna tog Chef Breanna på sig att föda hela Stormwind-brigaden som var stationerad i staden. Att hålla en aktiv garnison mätt tömde snabbt hennes skåp, så stadens kock hade många hungriga munnar att mätta men tomma förråd."},{t="Bergens rikedomar",b="Med tomma skåp vänder sig Chef Breanna till den farliga vildmarken utanför Lakeshires portar. Den karakteristiska grytan kräver en robust blandning av lokalt kött: sega bitar från bergskondorer, kryddade trynen från de väldiga Great Goretusks och spindelbenens spröda kött från jättetarantlar som strövar omkring i kullarna."}},faq={{q="Varför har Chef Breanna slut på matförråd?",a="Under det senaste Blackrock-orchernas uppror behövde Breanna föda hela Stormwind-brigaden som skickats för att försvara Lakeshire, och tömde därmed sina skåp helt.",al={"varför tomt skafferi","breannas skafferi","varför ingen mat"}},{q="Vilka ingredienser används till Redridge Goulash?",a="Äkta Redridge Goulash kräver fem bitar Tough Condor Meat, fem Great Goretusk Snouts och fem portioner Crisp Spider Meat, allt från varelser som hör hemma i de omgivande bergen.",al={"ingredienser i grytan","vad innehåller redridge goulash","kött i grytan"}},{q="Var finns Chef Breanna?",a="Chef Breanna finns i staden Lakeshire, där hon sköter sin eldstad och sina grytor. Staden ligger vid Lake Everstills norra strand i Redridge Mountains.",al={"breannas plats","var finns chef breanna","kock i lakeshire"}},{q="Varför importerar Lakeshire inte bara mat från Stormwind City?",a="Orcher, Blackrock-rövare och gnoller blockerar bergspassen, samtidigt som Stormwinds resurser är hårt ansträngda. Därför måste Lakeshire ofta förlita sig på det lokala djurlivet och besökande äventyrare för att få mat på bordet.",al={"stormwinds förnödenheter","varför inte handla med stormwind","matbrist i lakeshire"}},{q="Räknas Redridge Goulash som en delikatess?",a="För utomstående kan blandningen av spindelkött, vildsvinstryne och segt kondorkött låta motbjudande. Men Chef Breanna och Lakeshires gränsbor ser den färdiga rätten som en rejäl bergsdelikatess.",al={"är grytan god","god gryta","delikatess från redridge"}},{q="Vilken brigad behövde Breanna föda?",a="Breanna lagade mat åt Stormwinds soldater som var stationerade i Lakeshire för att slå tillbaka Blackrock-orcherna som trängde ned från de norra bergsryggarna.",al={"stormwind-brigaden","vem försvarade lakeshire","trupper i lakeshire"}}},fx={["4a7f1419"]={q="Vad ska Great Goretusk Snout användas till?",a="Chef Breanna använder Great Goretusk Snouts som en av de rejäla, smakrika köttbaserna i Redridge Goulash. De lokala goretusks som strövar omkring i Redridge Mountains ger tjocka, feta köttbitar som gör grytan mustig, särskilt nu när hennes vanliga förråd har tömts.",al={"vad great goretusk snout används till","varför samla goretusk-trynen","breanna och goretusk-tryne"}},["147c758b"]={q="Vad ska Tough Condor Meat användas till?",a="Tough Condor Meat är en av de viktiga viltköttsingredienser som Chef Breanna behöver till Redridge Goulash. Condorköttet är magert och segt, men långsam tillagning över eld gör det mört och ger den djupa, mustiga smak som är typisk för den här regionala rätten.",al={"vad tough condor meat används till","varför samla kondorkött","breanna och kondorkött"}},bcb0ca74={q="Vad ska Crisp Spider Meat användas till?",a="Crisp Spider Meat är en viktig proteinkälla i Chef Breannas Redridge Goulash. Köttet kommer från de jättelika spindeldjuren i Redridge-kullarna och ger grytan en särskild konsistens och jordig smak som kompletterar kondorernas fågelkött och goretuskfläsket.",al={"vad crisp spider meat används till","varför samla spindelkött","breanna och spindelkött"}},bc77dafb={q="Varför behöver Chef Breanna en äventyrare som samlar ingredienser?",a="Lakeshires försvarare är fullt upptagna med att skydda staden mot Blackrock-orcher och gnoller, så varken vakterna eller Breanna kan ge sig ut och samla mat i den farliga vildmarken. Hennes kök är dessutom tömt efter att ha försett Stormwinds trupper med mat. Därför måste Breanna lita på dugliga resande äventyrare som vågar möta rovdjuren i de omgivande kullarna och fylla på hennes förråd.",al={"varför kan breanna inte jaga","varför hämtar inte vakterna kött","varför jag ska hämta ingredienser till redridge goulash"}}},fp="16,217,22.284.0,15.256.0,41.171.0,51.182.0,30.134.0,59.187.0,42.183.0,38.147.0"}
P.entries["quest:920"] = {n="Tenaron's Summons",s="Tenaron's Summons markerar en viktig övergång för unga nattalver i Shadowglen. Efter att ha hjälpt Gilshalan Windwalker med faror i skogen kallas du till Aldrassils väldiga grenar för att möta Tenaron Stormgrip. Kallelsen markerar ögonblicket då en novis lämnar små lokala sysslor bakom sig för att möta djupare andliga plågor som drabbar Teldrassil.",h="Tenaron's Summons markerar en viktig övergång för unga nattalver i Shadowglen.",kw={"aldrassil","gilshalan","shadowglen","stormgrip","kallelse","teldrassil","tenaron","windwalker"},ang={["class:Druid"]="Att rapportera till Tenaron Stormgrip är ett viktigt steg mot att lära sig hur Teldrassils druidska balans övervakas och upprätthålls.",["race:NightElf"]="Den här kallelsen markerar din myndighetsålder bland kaldorei, när du går från enkelt skogsförsvar till direkt tjänst åt de äldste som vårdar världsträdet."},sec={{t="En kallelse till grenarna",b="Efter att du visat att du kan hantera de giftiga spindlarna och det fördärvade djurlivet i gläntan går dina insatser inte obemärkta förbi. Gilshalan Windwalker berättar att Tenaron Stormgrip själv har begärt att få träffa dig. Även bland nattalver, som lever mycket länge, anses det vara dålig stil att låta en äldre vänta uppe i det stora trädet Aldrassil."},{t="Uppför Aldrassil",b="Tenaron väntar i Aldrassils högsta kammare och blickar ut över Shadowglens grönskande grenar. När du svarar på kallelsen dras du genast in i större frågor om förvaltarskap: att rena Teldrassils månbrunnar och undersöka den onaturliga fördärv som sprider sig i världsträdets unga ekosystem."}},faq={{q="Vem är Tenaron Stormgrip?",a="Tenaron Stormgrip är en inflytelserik nattalv som bor i Aldrassils översta kammare i Shadowglen. Han ansvarar för gläntans andliga omsorg och samordnar arbetet med att övervaka och rena Teldrassils heliga vatten.",al={"vem är tenaron","tenaron stormgrips bakgrund"}},{q="Var hittar jag Tenaron Stormgrip?",a="Han finns i Aldrassils översta rum, den stora ihåliga trädstaden i Shadowglen. Du måste klättra uppför de vindlande ramperna inne i trädet för att nå hans utsiktsplats nära kronan.",al={"hitta tenaron","tenarons plats","var är tenaron"}},{q="Varför kallar Tenaron på mig?",a="När du har visat vad du går för genom att hantera de pestsmittade djuren där nere ger Tenaron dig större ansvar, särskilt att undersöka de heliga månbrunnarna och testa deras vatten för tecken på fördärv.",al={"varför kallar han","vad vill tenaron"}},{q="Vad händer efter det här uppdraget?",a="När du svarar på kallelsen går du genast vidare till uppdragskedjan Crown of the Earth. Där ber Tenaron dig samla vattenprover från månbrunnarna runt Teldrassil för att kontrollera trädets hälsa.",al={"nästa uppdrag","vad händer efter tenaron's summons"}},{q="Vem skickar dig till Tenaron?",a="Gilshalan Windwalker ger dig kallelsen när du har hjälpt honom med de giftgalna Webwood-spindlarna som hotar Shadowglens nedre håligheter.",al={"vem ger uppdraget","gilshalan windwalker"}},{q="Vad är Aldrassil?",a="Aldrassil är det väldiga gren-trädet i den avskilda dalen Shadowglen. Det fungerar som central bosättning och träningsfristad för unga nattalvsäventyrare på Teldrassil.",al={"aldrassils bakgrund","vad är aldrassil"}}},fx={["494cb76b"]={q="Varför skickar Gilshalan Windwalker dig till Tenaron?",a="Gilshalan vidarebefordrar bara ett meddelande från högre ort. Han har följt dina framsteg och sett hur du löst problem i Shadowglen, så han vet att Tenaron Stormgrip har lagt märke till din förmåga och behöver din hjälp uppe på Aldrassil omgående.",al={"gilshalans motiv","varför skicka mig till tenaron","gilshalan windwalkers kallelse"}}},fp="17,159,20.223.0,19.215.0,25.193.0,34.157.0,27.191.0,30.159.0,25.138.0,18.146.0"}
P.entries["quest:92017"] = {n="Cleansing Winds",s="Marn ber dig samla fjädrar och chimärhår från Summit. Han behöver dessa rester för att stärka rökelsen till en reningsritual.",h="Marn ber dig samla fjädrar och chimärhår från Summit.",kw={"renande rök","renande vindar","grand hippogryph feathers","marn","oily chimaera hair","renande rökelse","ritual","summit"},sec={{t="Rester i vinden",b="På Summit söker Marn fjädrar från Grand Hippogryphs och hår från chimärer. De högsta luftströmmarna bär fortfarande varelser vars andedräkt har undgått fördärvet. Deras drivande rester bär spår av ett oförstört land, och Marn behöver dem för att stärka sin renande rökelse före ritualen."}},faq={{q="Vad behöver Marn?",a="Marn behöver Grand Hippogryph Feathers och Oily Chimaera Hair för att stärka sin renande rökelse.",al={"vilka föremål behöver marn","marns material"}},{q="Varför vill Marn ha fjädrar och chimärhår?",a="Fjädrarna och håret tar upp det luften minns om ett oförstört land, och Marn använder dem för att förankra och stärka sin rökelse.",al={"varför fjädrar","varför chimärhår"}},{q="Var hämtar varelserna andan?",a="De flygande varelserna på Summit hämtar andan från de högsta luftströmmarna, där fördärvet ännu inte fått fullt fäste.",al={"var finns de högsta luftströmmarna","varelser på summit"}},{q="Vad ska rökelsen användas till?",a="Marn tänker koncentrera vindens kunskap till renande rök före ritualen.",al={"marns rökelse","vad ska den renande röken användas till"}}},fp="15,137,20.299.0,20.96.0,46.130.0,35.116.0,24.86.0"}
P.entries["quest:921"] = {n="Crown of the Earth",s="Crown of the Earth är en invigningsrit som Tenaron Stormgrip håller högt uppe i Aldrassil. Unga nattalver ska snart lämna Shadowglen och får i uppdrag att hämta heligt vatten från en närbelägen månskensbrunn och möta den smärtsamma historien om Mount Hyjal och sitt folks förlorade odödlighet.",h="Crown of the Earth är en invigningsrit som Tenaron Stormgrip håller högt uppe i Aldrassil.",kw={"aldrassil","crown of the earth","crystal phial","hyjal","månskensbrunn","nordrassil","shadowglen","teldrassil","tenaron stormgrip"},ang={["class:Druid"]="Månskensbrunnar är viktiga redskap för Cenarion Circle och erbjuder renade kanaler för naturens energi, som behövs för att bevara skogens balans.",["class:Priest"]="Månskensbrunnar är helgade åt Elune och fungerar som speglande helgedomar där vattnet invigs under Modermånens blick.",["race:NightElf"]="Den här riten markerar din färd ut ur Shadowglen och knyter ditt personliga öde till uppoffringen på toppen av Mount Hyjal och ansvaret att skydda Teldrassil."},sec={{t="En lektion i närtidens historia",b="Innan någon ung äventyrare lämnar Shadowglens skyddade grenar ser de äldre till att hen förstår det höga pris kaldorei nyligen betalade. Under slaget vid Mount Hyjal offrades världsträdet Nordrassil för att besegra Archimonde och fördriva Burning Legion. I den förödande explosionen förlorade nattalverna sin ålderslösa odödlighet och sitt heliga skydd. Tenaron Stormgrip är både mentor och historieberättare och ger nybörjarna denna rit för att inge ödmjukhet och målmedvetenhet innan de möter en värld i förändring."},{t="Brunnens vatten",b="Uppgiften kräver att du hämtar vatten från en månskensbrunn norr om Aldrassil med hjälp av en kristallampull. Dessa månskensbrunnar är inga vanliga källor; deras vatten är genomsyrat av rester från den uråldriga Evighetens brunn. Druiderna kanaliserar deras återställande krafter ut i vildmarken, och vaktposterna vördar dem som fridfulla helgedomar åt gudinnan Elune. Kaldorei är dock fortsatt ytterst försiktiga. Hemlig arkans magi är fortfarande strängt förbjuden i nattalvernas samhälle, eftersom källan som håller deras land vid liv också påminner om den vårdslösa magi som en gång nästan krossade världen."}},faq={{q="Vem är Tenaron Stormgrip?",a="Tenaron Stormgrip är en nattalv som håller till högt uppe bland Aldrassils övre grenar i Shadowglen. Han vägleder unga nattalver som närmar sig slutet på sin grundutbildning och ger dem riter som lär dem rasens högtidliga historia innan han skickar dem vidare ut i Teldrassil.",al={"tenaron stormgrip","vem ger crown of the earth","druid-npc i aldrassil"}},{q="Varför samlar man månskensbrunnsvatten?",a="Att samla vatten i kristallampullen är första steget på en ceremoniell och praktisk resa över ön. Månskensbrunnens vatten bär på uråldrig magi som druider använder för att nära landet, medan själva riten lär unga kaldorei om samhällets heliga skyldigheter.",al={"varför hämta vatten från månskensbrunnen","vad används filled crystal phial till","månskensbrunnens syfte"}},{q="Varför förlorade nattalverna sin odödlighet?",a="Under Tredje kriget sprängde nattalverna den nedärvda kraft som vävts in i världsträdet Nordrassil för att förgöra demonfursten Archimonde på toppen av Mount Hyjal. Uppoffringen utplånade Legionens förtrupp, men berövade nattalverna deras eviga ungdom och immunitet mot sjukdomar.",al={"varför är nattalver dödliga","vad hände med odödligheten","nordrassils förstörelse"}},{q="Är månskensbrunnar farliga?",a="Månskensbrunnar innehåller utspädda essenser med spårbar koppling till Evighetens brunn. Druider och prästinnor kanaliserar tryggt deras energier för helande, välsignelser och samhörighet med naturen, men kaldorei förbjuder strängt att använda dem till hemlig arkans magi på grund av katastroferna som vårdslös magi orsakade i forntiden.",al={"är månskensbrunnar arkana","är vatten från månskensbrunnar säkert","fara med evighetens brunn"}},{q="Vart leder den här uppdragskedjan härnäst?",a="När du lämnar tillbaka den fyllda ampullen är den inledande lektionen i Crown of the Earth-serien avklarad. Tenaron skickar dig sedan till Corithras Moonrage i Dolanaar, som låter dig fylla ampuller vid andra månskensbrunnar runt Teldrassil åt druiderna i Darnassus och till sist Arch Druid Fandral Staghelm.",al={"vad händer efter crown of the earth","uppdragskedjan crown of the earth","nästa uppdrag efter tenaron"}},{q="Var ligger månskensbrunnen för det här uppdraget?",a="Månskensbrunnen ligger en kort promenad norr om Aldrassils väldiga grenar, fridfullt inbäddad bland skogarna i Shadowglen.",al={"var ligger månskensbrunnen","månskensbrunnens plats i shadowglen","hitta kristallampullen vid brunnen"}}},fx={b29aebae={q="Varför ger Tenaron Stormgrip dig det här uppdraget?",a="Tenaron anser att du inte kan ta steget ut i den större världen utan att förstå kaldoreiernas närmaste, smärtsamma historia. Offret i slaget vid Mount Hyjal krossade Nordrassil och berövade nattalverna deras odödlighet, vilket förändrade hela deras tillvaro. Genom att skicka dig till de heliga månkällorna för att hämta deras vatten använder Tenaron varje steg på resan för att lära dig hur ditt folk hamnade i sin nuvarande situation på Teldrassil.",al={"tenaron stormgrips motiv","varför vill tenaron ha månkällsvatten","tenarons motiv i crown of the earth"}},e84820be={q="Vad används Filled Crystal Phial till?",a="Filled Crystal Phial innehåller vatten som hämtats direkt från månkällan norr om Aldrassil. Vattnet bär spår av den uråldriga Evighetens brunn, som är helig för Sentinels och används varsamt av druider. Tenaron vill att du tar med den fyllda ampullen tillbaka till honom uppe på Aldrassil. Det är ett symboliskt första steg i en större rituell plikt som ska leda dig genom Teldrassil.",al={"vad filled crystal phial används till","vad filled crystal phial är till för","syftet med filled crystal phial"}}},fp="18,205,26.391.0,18.412.0,25.222.0,49.212.0,47.261.0,35.257.0,38.221.0,45.96.0"}
P.entries["quest:92100"] = {n="Anywhere But Here",s="En veteranande ber dig hitta hans slida nära Elderwild. Kratrarna omkring honom för tankarna till Third War.",h="En veteranande ber dig hitta hans slida nära Elderwild.",kw={"var som helst utom här","archimonde","kratrar","elderwild","utsiktsplats","slida","ande","veteran of the third war"},sec={{t="En veterans begäran",b="Vid Elderwild ber Veteran of the Third War dig hitta slidan han lämnade vid en utsiktsplats väster om sig. Han minns utsikten där tydligt, trots att han glömt mycket av den han en gång var. Kratrarna runt honom har haft få besökare på flera år."}},faq={{q="Vem ber mig hitta slidan?",a="Veteran of the Third War, en ande som visar sig nära Elderwild, ber dig hitta hans slida.",al={"vem är den här anden","veteranande","veteran från third war"}},{q="Var är slidan?",a="Veteran of the Third War säger att han lämnade sin slida vid en utsiktsplats väster om där han står, nära Elderwild.",al={"slidans plats","var är hans svärdsslida","hitta slida"}},{q="Varför nämner veteranen Archimonde?",a="Veteran of the Third War undrar om Archimonde drevs tillbaka och säger sedan att det var länge sedan.",al={"fråga om archimonde","drev vi tillbaka archimonde","vad hände med archimonde"}},{q="Vad minns veteranen?",a="Veteran of the Third War minns utsikten från utsiktsplatsen där han lämnade sin slida.",al={"vad minns han","minne från utsiktsplatsen","veteranens minne"}}},fp="17,107,19.262.0,38.97.0,22.93.0,40.95.0,31.93.0"}
P.entries["quest:92109"] = {n="My First Alchemy Set",s="En ung alkemist i Moonbrook ber dig om enkla förnödenheter. Hon vill börja lära sig trots sin fars varning om örter.",h="En ung alkemist i Moonbrook ber dig om enkla förnödenheter.",kw={"alkemi","empty vials","moonbrook","my first alchemy set","peacebloom","silverleaf","westfall","ung alkemist"},sec={{t="En ung alkemist",b="Barnet i ladan i Moonbrook har blivit tillsagt att inte röra sin fars örter. Hon hoppas kunna lära sig alkemi medan hon fortfarande är ung och ber dig hämta tomma flaskor, Silverleaf och Peacebloom. Hon väntar på att få se vad hon kan göra med dem."}},faq={{q="Vem ber om förnödenheter till alkemi?",a="En ung, blivande alkemist inne i ladan i Moonbrook ber dig om förnödenheter.",al={"vem vill ha förnödenheter","alkemistflicka i moonbrook"}},{q="Varför vill hon ha de här sakerna?",a="Hon vill börja lära sig alkemi, men hennes far låter henne inte hantera hans örter eftersom han anser att de är farliga.",al={"varför alkemisaker","varför behöver hon förnödenheter"}},{q="Vilka förnödenheter ber hon om?",a="Hon ber om fem Empty Vials, fem Silverleaf och fem Peacebloom.",al={"vilka föremål","förnödenheter till alkemi"}},{q="Var hittar jag den unga alkemisten?",a="Hon är inne i ladan i Moonbrook i Westfall.",al={"var är flickan","ladan i moonbrook"}},{q="Vad tänker hon göra med förnödenheterna?",a="Hon säger att hon ska se vad hon kan göra med förnödenheterna.",al={"vad ska hon tillverka","gör hon trolldrycker"}}},fp="20,129,17.248.0,34.79.0,31.122.0,32.68.0,37.46.0,43.58.0"}
P.entries["quest:92110"] = {n="My First Real Potion",s="Ett barn ber dig hämta murlocögon till My First Real Potion. Hon är ivrig att blanda den själv.",h="Ett barn ber dig hämta murlocögon till My First Real Potion.",kw={"barn","örter","murlocögon","my first real potion","orange trolldryck","trolldryck","flaskor"},sec={{t="Ett första försök",b="Barnet blir glatt när det får se murlocögonen. Medan du var borta samlade hon fler örter och hittade tomma flaskor på nedervåningen. Nu ber hon dig blanda ingredienserna medan hon tittar på. Trolldrycken blir sjukligt orange när ögonen läggs i."}},faq={{q="Vad vill barnet ha?",a="Barnet vill ha murlocögon till sin första riktiga trolldryck, tillsammans med örter och tomma flaskor.",al={"vad hon vill ha","barn trolldryck","ingredienser till trolldrycken"}},{q="Vem blandar trolldrycken?",a="Du blandar trolldrycken medan barnet tittar på.",al={"vem blandar","blanda trolldryck","trolldryckens tillverkare"}},{q="Vilken färg får trolldrycken?",a="Blandningen blir sjukligt orange inom några sekunder efter att murlocögonen tillsätts.",al={"trolldryckens färg","orange trolldryck","hur ser den ut"}},{q="Dricker barnet den?",a="Nej. Barnet säger att hon inte skulle dricka trolldrycken, men ger dig sitt recept.",al={"dricka trolldryck","skulle hon dricka den","är den säker"}}},fp="20,95,15.228.0,25.88.0,21.43.0,32.73.0,24.76.0"}
P.entries["quest:92124"] = {n="Book Inventory",s="I Northshire Abbey är Brother Paxton frustrerad över felplacerade och försvunna böcker. Han ber unga äventyrare att hitta Daniel, hans dagdrömmande assistent, och inventera bibliotekets arkiv, men Daniels tankar vandrar hela tiden till lokala yrken, så det är svårt att få ett rakt svar.",h="I Northshire Abbey är Brother Paxton frustrerad över felplacerade och försvunna böcker.",kw={"book inventory","brother paxton","daniel","elwynn forest","bibliotek","northshire abbey","yrken","hantverk"},ang={["class:Priest"]="Som präst som studerar Northshires heliga arkiv är du beroende av ordning i biblioteket för att bevara heliga skrifter och kyrkans traditioner.",["race:Human"]="Som ung människa som börjar tjänstgöra vid Northshire Abbey känner du kanske igen kampen med att balansera klosterstudier och det praktiska livet i byn."},sec={{t="En bibliotekaries frustration",b="Northshire Abbey bevarar gamla lärda verk, andliga skrifter och historiska dokument som överlevde det första kriget i kungariket Stormwind. Brother Paxton, en noggrann munk, är mycket stolt över samlingen. På senare tid har böcker försvunnit från hyllorna, och Paxton behöver en tydlig inventering för att ta reda på hur omfattande förlusten är. Han har föga tålamod med att jaga efter sin dagdrömmande hjälpreda."},{t="Daniels skiftande intressen",b="Daniel arbetar som Brother Paxtons assistent i klosterbiblioteket, men hans tankar stannar sällan vid pergament och katalognummer. Han fascineras av de praktiska yrkena i Elwynn Forest: smide, läderarbete, skrädderi och örtkunskap. Paxton blir alltmer förbittrad när inventeringsarbetet får Daniel att svamla om lokala hantverkare i stället för att leta reda på försvunna skrifter."}},faq={{q="Vem är Brother Paxton?",a="Brother Paxton är en munk i Northshire Abbey som sköter dess omfattande samling av böcker, skrifter och historiska skriftrullar. Han är stolt över samlingen och tappar lätt humöret när böcker försvinner eller medhjälpare smiter från sina plikter.",al={"brother paxton","vem ger book inventory","paxton elwynn"}},{q="Vem är Daniel?",a="Daniel är Brother Paxtons unge assistent i biblioteket i Northshire Abbey. Han har i uppgift att ordna böcker och inventera samlingen, men tankarna går ofta till yrken och hantverk i Elwynn Forest.",al={"vem är daniel","paxtons assistent","daniel northshire"}},{q="Varför saknas det böcker i Northshire Abbey?",a="Brother Paxton säger att böcker har försvunnit, men förklarar inte varför. Han ber Daniel inventera samlingen och ta reda på hur mycket som har gått förlorat.",al={"varför saknas böcker","saknade böcker northshire","försvunna böcker klostret"}},{q="Var hittar man Daniel?",a="Daniel är inne i Northshire Abbey, bland hyllorna och skrivborden i klosterbiblioteket.",al={"var är daniel","daniels plats","hitta daniel"}},{q="Varför kallar Paxton Daniel oduglig?",a="Paxton anser att Daniel är oduglig eftersom han försummar sina arkivuppgifter. I stället för att katalogisera och ställa tillbaka böcker tillbringar Daniel timmarna med att dagdrömma och prata om praktiska yrken.",al={"varför hatar paxton daniel","daniel oduglig"}},{q="Vilka yrken intresserar Daniel?",a="Daniel fascineras av hantverk som utövas runtom i Elwynn Forest, som smide, läderarbete och skrädderi. Han föredrar praktiskt arbete framför dammiga böcker.",al={"daniels yrken","vilka yrken gillar daniel"}}},fx={deb80ab5={q="Varför vill Brother Paxton att böckerna inventeras?",a="Northshire Abbey har märkt att böcker försvinner från hyllorna, och Brother Paxton behöver fastställa omfattningen av förlusten innan klostrets samling drabbas av ytterligare bortfall. Hans assistent Daniel ska hålla ordning i biblioteket, men hans ständiga dagdrömmande om lokala hantverk har gjort Paxton frustrerad och helt ovetande om hur många böcker som faktiskt saknas.",al={"varför inventera böckerna","varför vill paxton ha en inventering","paxtons motiv"}}},fp="14,251,25.340.0,27.370.0,22.246.0,14.215.0,44.135.0,26.94.0,36.190.0,41.177.0"}
P.entries["quest:922"] = {n="Rellian Greenspyre",s="Det här ärendet tar dig från Denalans tillflyktsort vid sjön i Teldrassil till huvudstaden Darnassus. När du lämnar över ett timberlingfrö till druiden Rellian Greenspyre får du oroande nyheter om hur korruptionen sprider sig i världsträdets grenar.",h="Det här ärendet tar dig från Denalans tillflyktsort vid sjön i Teldrassil till huvudstaden Darnassus.",kw={"cenarion enclave","korruption","darnassus","denalan","rellian greenspyre","teldrassil","timberling seed"},ang={["class:Druid"]="För Cenarion-adepter visar det här ärendet hur djupt en oförutsedd farsot har trängt in i Teldrassils nyspirande ekosystem och understryker det akuta behovet av att bevara det inhemska elementära livet.",["race:NightElf"]="Timberlingarna var tänkta att frodas i takt med att Teldrassil växte. Därför är Rellians upptäckt av ärftlig korruption ett oroande tecken för kaldoreiernas nya hemland."},sec={{t="En kurir till huvudstaden",b="Denalan har lagt mycket arbete på att odla och förstå floran och det elementära livet kring Lake Al'Ameth. Efter att ha samlat frön från traktens timberlings skickar han dig till Darnassus för att överlämna ett prov till sin kollega Rellian Greenspyre. Rellian är en annan druid som vandrar på de fridfulla terrasserna i Cenarion Enclave. Han har tidigare uttryckt nyfikenhet på Denalans forskning och hoppas kunna föda upp en egen timberling."},{t="Förgiftad tillväxt",b="När Rellian tar emot fröet kommer han med dystra nyheter i stället för vetenskaplig optimism. Hans senaste undersökningar har bekräftat att timberlings över hela Teldrassil faller offer för en aggressiv och utbredd korruption. Än värre är att frön från förgiftade exemplar redan bär på föräldrarnas vanställdhet. Rellian medger att det ligger bortom hans egen förmåga att rena dem och menar att endast Denalans djupa samhörighet med levande ting ger något hopp om att återställa balansen."}},faq={{q="Vem är Rellian Greenspyre?",a="Rellian Greenspyre är en Night Elf-druid som kan hittas på stigarna i Cenarion Enclave i Darnassus. Han har nära vetenskapliga band till Denalan och delar dennes intresse för Teldrassils ekologi och elementandar.",al={"rellian greenspyres bakgrund","vem är rellian","rellian greenspyres plats"}},{q="Varför skickar Denalan ett timberlingfrö till Rellian?",a="Denalan samlade timberlingfrön vid Lake Al'Ameth med din hjälp. Han minns att Rellian hade visat intresse för timberlingarnas biologi och hade egna teorier, så Denalan ger honom ett frö så att Rellian kan försöka odla en i huvudstaden.",al={"varför skicka timberlingfrö","denalans ärende"}},{q="Vilket problem upptäcker Rellian?",a="Rellian upptäcker att en onaturlig korruption har smittat timberlingarna. Därför är fröna från dem redan förvridna av föräldrarnas vanställdhet, så det går inte att odla friska skott innan ett botemedel har hittats.",al={"vad är fel på timberlingfröet","korruption bland timberlings"}},{q="Vart leder uppgiften härnäst?",a="Rellian kan inte bota de förgiftade fröna själv, så han skickar dig till Wellspring Lake i norra Teldrassil för att fälla de mest förgiftade timberlingarna och ta med deras mossiga tumörer tillbaka så att de kan brännas.",al={"vad händer efter rellian greenspyre","nästa uppdrag efter rellian"}},{q="Var kan Rellian Greenspyre hittas?",a="Rellian vandrar längs de öppna stigarna genom Cenarion Enclave, som ligger i Darnassus nordvästra hörn.",al={"var finns rellian","rellians plats på kartan"}},{q="Varför kan Rellian inte rena fröna själv?",a="Korruptionen sitter så djupt att den överstiger Rellians särskilda förmågor. Han överlåter uppgiften åt Denalans enastående kunskaper om botanik och odling av levande ting och anser att hans vän är det bästa hoppet om att bota framtida generationer av timberlings.",al={"varför kan rellian inte bota dem","rellians druidförmågor"}}},fx={["0120e426"]={q="Varför ber Denalan en äventyrare att leverera fröet i stället för att själv åka?",a="Denalan är fullt upptagen med sin forskning vid Lake Al'Ameth, där han odlar skott och själv övervakar de drabbade timberlings. Resan till Cenarion Enclave i Darnassus skulle ta honom bort från hans levande försöksobjekt, så han förlitar sig på resande som redan visat sig pålitliga för att leverera frön till hans druidsyskon.",al={"varför skicka mig till rellian","varför levererar inte denalan fröet","varför jag ska hjälpa rellian greenspyre"}}},fp="18,182,24.351.0,14.312.1,26.175.0,51.198.0,35.161.0,31.177.1,38.96.0,44.206.0"}
P.entries["quest:923"] = {n="Tumors",s="På uppdrag av Cenarion Circle i Darnassus ska äventyrare rensa bort de sjuka timberlings kring Wellspring Lake i norra Teldrassil. Genom att samla mossiga tumörer från dessa förvridna naturandar hoppas druiderna kunna studera det spridande giftet och bränna de förorenande utväxterna på ett säkert sätt.",h="På uppdrag av Cenarion Circle i Darnassus ska äventyrare rensa bort de sjuka timberlings kring Wellspring...",kw={"cenarion circle","fördärv","darnassus","denalan","mossy tumor","rellian greenspyre","teldrassil","timberling","tumörer","wellspring lake"},ang={["class:Druid"]="För druiderna i Cenarion Circle är det en tragisk men nödvändig plikt att förgöra fördärvade naturandar för att skydda Teldrassils bräckliga balans från att kollapsa helt.",["profession:Herbalism"]="Örtkännare och botaniker blir illa till mods när de ser levande trä och mossa förvandlas till giftiga, elakartade tumörer i stället för frodig växtlighet.",["race:NightElf"]="Att sjukdomen snabbt visar sig på det nyvuxna världsträdet oroar kaldorei och utmanar Fandral Staghelms löfte om en orörd fristad."},sec={{t="Plågan bland timberlings",b="Teldrassil skapades som en fristad i harmoni, men en märklig sjukdom har börjat förvrida dess inhemska växter och djur. Timberlings, vanligtvis fridsamma naturandar med barkliknande hud, har blivit fientliga och oberäkneliga. På deras levande trä har groteska, mossiga tumörer slagit ut och pulserar av ett motbjudande, onaturligt gift. Medan forskare från Cenarion Circle, som Denalan och Rellian Greenspyre, söker efter sjukdomens grundorsak måste de varelser som redan fallit offer för illviljan rensas bort för att skydda resten av trädkronorna."},{t="Inneslutning vid Wellspring Lake",b="Wellspring Lake i norra Teldrassil har blivit ett centrum för utbrottet. Timberlings som strövar längs dess stränder är bland de mest förgiftade på hela världsträdet. Rellian Greenspyre ger resande i uppdrag att fälla dessa fördärvade väktare och skära bort deras utväxter. Genom att lämna tumörerna direkt till druiderna i Darnassus så att de kan brännas säkert hoppas nattalverna hejda smittans spridning medan de fortsätter söka efter sjukdomens källa."}},faq={{q="Varför får timberlings tumörer?",a="En mystisk sjukdom har fått fäste i Teldrassils vilda andar. De mossiga tumörerna är synliga tecken på en giftig smitta som genomsyrar deras kroppar och förvandlar deras naturliga skyddsinstinkter till blind aggression.",al={"vad är fel med timberlings","timberlings sjukdom","varför är timberlings sjuka"}},{q="Vem är Rellian Greenspyre?",a="Rellian Greenspyre är en nattalvaforskare knuten till Cenarion Circle och stationerad i Darnassus. Han arbetar nära andra botaniker, som Denalan, för att studera de märkliga förvridningar som plågar Teldrassils ekosystem.",al={"rellian greenspyres bakgrund","vem är greenspyre","rellian greenspyre"}},{q="Varför måste tumörerna brännas?",a="Rellian Greenspyre säger att tumörerna är fulla av gift som måste renas bort från Teldrassil. Han ber att få utväxterna levererade så att de kan brännas.",al={"bränna tumörer","varför bränna tumörerna","förstöra mossiga tumörer"}},{q="Var ligger Wellspring Lake?",a="Wellspring Lake ligger i Teldrassils norra delar och får sitt vatten från trädets rena vattendrag. Timberlings längs stränderna är tydligt sjukare än de som finns på andra platser.",al={"wellspring lakes läge","var hittar man timberlings","var finns mossiga tumörer"}},{q="Kan timberlings botas i stället för att dödas?",a="Cenarion Circle söker aktivt efter ett botemedel eller efter plågans ursprung, men timberlings som strövar vid Wellspring Lake anses redan vara bortom räddning. Tills källan har identifierats är det enda sättet att skydda skogen att fälla de mest aggressiva andarna.",al={"kan timberlings räddas","bota timberlings"}},{q="Vad händer när tumörerna har förts till Darnassus?",a="När Rellian har säkrat och förstört tumörerna skickar han äventyrarna tillbaka till fältbotanikern Denalan nära Lake Al'Ameth för att fortsätta undersöka fördärvet som sprider sig genom Teldrassils växtlighet.",al={"efter tumöruppdraget","vad händer efter tumörerna"}}},fx={ab07798c={q="Varför vill Rellian Greenspyre att det här görs?",a="En mörk illvilja har börjat förvrida Teldrassils djurliv, och Rellian Greenspyre fruktar för hela grenverkets säkerhet. Medan Cenarion Circle söker efter fördärvets grundorsak måste varelser som inte längre går att rädda renas bort innan deras förruttnelse sprider sig över det nya världsträdet.",al={"rellian greenspyres motiv","varför gallra bland timberlings","varför döda timberlings"}},["6d82dc19"]={q="Vad ska Mossy Tumor användas till?",a="De mossiga tumörerna är fysiska uttryck för illviljan som gör timberlings sjuka. De är fyllda med giftigt ämne och samlas in som bevis på hur omfattande smittan är. De levereras till Rellian Greenspyre i Darnassus, så att han kan bränna och göra sig av med dem på ett säkert sätt innan förruttnelsen sprider sig.",al={"vad mossy tumor används till","vad mossiga tumörer är","syftet med mossy tumor"}},["3565cc38"]={q="Vad är timberlings vid Wellspring Lake?",a="Timberlings är växtliknande skogsvarelser som hör hemma på Teldrassil. De som lever kring Wellspring Lake i norr har drabbats hårt av en okänd illvilja, blivit aggressivt fientliga och fått sjuka, mossiga utväxter som visar att de inte längre går att rädda.",al={"timberlings vid wellspring lake","vad timberlings är","timberlings mål"}}},fp="6,236,27.423.0,30.406.0,39.202.0,26.205.0,30.148.0,25.164.0,47.240.0,52.203.0"}
P.entries["quest:92343"] = {n="Get to the Roots of It",s="Nara Wildmane söker Nordrassil root caps från Blackmaw Hold för att studera deras magiska egenskaper. Druiderna i Thunder Bluff skulle stå i skuld till dig för proverna.",h="Nara Wildmane söker Nordrassil root caps från Blackmaw Hold för att studera deras magiska egenskaper.",kw={"blackmaw hold","furbolg","gå till botten med det","nara wildmane","nordrassil root caps","nordrassil rötter","satyr","thunder bluff"},sec={{t="Roots Below",b="Nara Wildmane, en druid i Thunder Bluff, ber dig hämta Nordrassil root caps från Blackmaw Hold. Gången leder in i fästet, som furbolg har försvarat ursinnigt mot främlingar. Med satyrernas situation kan du nu ta dig in. Nara vill ha prover från de växande rötterna nära Nordrassil för att studera dem."}},faq={{q="Vad behöver Nara?",a="Nara Wildmane ber dig hämta Nordrassil root caps från Blackmaw Hold så att hon kan studera dem.",al={"vad vill nara","nara rötter","root caps"}},{q="Var finns root caps?",a="Nordrassil root caps som Nara söker finns inne i Blackmaw Hold.",al={"var hittar man rötter","blackmaw rötter","nordrassil caps"}},{q="Varför kan jag ta mig in i Blackmaw Hold?",a="Furbolg har försvarat gången ursinnigt, men situationen med satyrerna gör det möjligt för dig att ta dig in.",al={"tillträde till blackmaw","varför kan man gå in","furbolg gång"}},{q="Vad vill Nara studera?",a="Nara vill studera de magiska egenskaperna hos rötter som växer nära Nordrassil. Det är inte mycket man vet om dem.",al={"rotmagi","nordrassil rötter","varför prover"}}},fp="22,161,11.306.0,20.98.0,24.61.0,30.110.0,29.113.0"}
P.entries["quest:92346"] = {n="Beneath Nordrassil",s="Jediga skickar dig för att berätta för Nara Wildmane om en håla nordost om henne. Hon misstänker att den leder under världsträdet och vill att Nara ska få veta det.",h="Jediga skickar dig för att berätta för Nara Wildmane om en håla nordost om henne.",kw={"under nordrassil","håla","furbolg","jediga","nara wildmane","satyr","thunder bluff","världsträd"},ang={["class:Druid"]="Som druid kommer du med en rapport till Nara Wildmane om en håla som kan leda under världsträdet.",["race:Tauren"]="Som tauren för du Jedigas tips vidare till Nara Wildmane, en tauren-druid i Thunder Bluff."},sec={{t="Bud till Nara",b="Nara Wildmane väntar vid Elder Rise i Thunder Bluff. Jediga skickar dig med nyheter om en håla nordost om henne, där furbolg och satyr slåss. Hon misstänker att hålan går under världsträdet och ber dig berätta för Nara vad du såg."}},faq={{q="Vem skickade mig till Nara Wildmane?",a="Jediga skickade dig för att tala med Nara Wildmane.",al={"vem skickade mig","jediga nara","vem är jediga"}},{q="Var hittar jag Nara Wildmane?",a="Nara Wildmane är vid Elder Rise i Thunder Bluff.",al={"var är nara","naras plats","elder rise nara"}},{q="Varför vill Jediga att Nara ska få veta om hålan?",a="Jediga tror att hålan kan leda under världsträdet och tror att Nara kan uppskatta informationen.",al={"varför berätta för nara","tips om håla","vad vill jediga"}},{q="Vilka slåss om hålan?",a="Furbolg och satyr slåss om hålan nordost om Jediga.",al={"furbolg satyr slåss","vilka slåss","slagsmål vid håla"}},{q="Vad finns i hålan?",a="Jediga vet inte vad som finns där inne. Hon misstänker att hålan leder under världsträdet.",al={"vad finns i hålan","under trädet","hålans innehåll"}}},fp="18,146,13.244.0,29.44.0,30.48.0,51.106.0,32.67.0,26.90.0"}
P.entries["quest:924"] = {n="The Demon Seed",s="Neeru Fireblades order når Ak'Zeloth, som skickar hordens resenärer för att förstöra Demon Seed på toppen av Dreadmist Peak. En instabil Flawed Power Stone kan bryta Burning Legions kanal innan dess inflytande sprider sig längre genom The Barrens.",h="Neeru Fireblades order når Ak'Zeloth, som skickar hordens resenärer för att förstöra Demon Seed på toppen av...",kw={"ak'zeloth","eldaltare","the barrens","burning legion","demon seed","dreadmist peak","flawed power stone","neeru fireblade"},ang={["class:Warlock"]="Som häxmästare känner du igen det precisa hantverket bakom kraftstenar som stör Legionens förbindelser utan att orsaka en katastrofal demonisk implosion.",["faction:Horde"]="Som medlem av Horden hjälper du till att skydda The Barrens viktiga karavanvägar och handelslederna som försörjer den unga Horden genom att utplåna Legionens fästen.",["race:Orc"]="Som ork har du genomlevt Draenors undergång under demonisk korruption och har föga tålamod med Legionaltaren nära Durotars gränser."},sec={{t="En fyr bland klipporna",b="Högt uppe i en grotta på Dreadmist Peak hänger Demon Seed ovanför ett eldaltare. Artefakten förankrar demonisk kraft i hjärtat av The Barrens åt Burning Legion. Orken Ak'Zeloth förbereder särskilda kraftstenar för att bryta dess länk till Nether. Någon måste nå toppen innan stenens instabila energi tar slut."},{t="Bandet brister",b="Flawed Power Stone förlorar kraft medan den förs över Dreadmist Peaks klippiga sluttningar. När den placeras mot eldaltaret överbelastar den Demon Seed och krossar dess förbindelse. Förstörelsen sänder kraftiga chockvågor genom etern och varnar osedda herrar om att deras anordning har saboterats."}},faq={{q="Vad är Demon Seed?",a="Demon Seed är en Burning Legion-artefakt i en grotta på toppen av Dreadmist Peak. Den hänger ovanför ett eldaltare och drar demonisk kraft och inflytande in i The Barrens.",al={"demon seeds syfte","vad är demon seed","demon seeds historia"}},{q="Vem beordrar att Demon Seed förstörs?",a="Orken Ak'Zeloth beordrar att Demon Seed ska förstöras, följer instruktioner och delar ut belöningar genom Neeru Fireblade, en häxmästare i Orgrimmars Cleft of Shadow.",al={"vem vill förstöra demon seed","neeru och demon seed","ak'zeloth uppdragsgivare"}},{q="Varför har Flawed Power Stone en tidsgräns?",a="Ak'Zeloths Flawed Power Stone är instabil. Dess bristfälliga magiska inneslutning gör att dess störande energi snabbt brinner ut, så den måste nå det demoniska altaret fort.",al={"flawed power stones tidsgräns","varför stenen förbrukas","stenen försvinner"}},{q="Var finns eldaltaret?",a="Eldaltaret ligger i en grotta nära toppen av Dreadmist Peak, nordväst om The Crossroads i norra The Barrens.",al={"eldaltarets plats","demon seeds grotta","grottan på dreadmist peak"}},{q="Vad händer när Demon Seed förstörs?",a="När Demon Seed förstörs kapas dess länk till Burning Legion, och frigörelsen sänder enorma vågor genom etern. Ak'Zeloth varnar för att mäktiga demoniska väsen kommer att känna störningen och undersöka förlusten av sitt verktyg.",al={"demon seeds chockvåg","följder av demon seed","kraftvågor"}},{q="Hur hänger detta ihop med Neeru Fireblade?",a="Neeru Fireblade samarbetar med Ak'Zeloth mot rivaliserande eller störande demoniska artefakter i The Barrens. Neeru står för mynten och utrustningen som ges när Demon Seed har förstörts.",al={"kopplingen till neeru","är neeru god","neerus inblandning"}}},fx={f2c946bb={q="Varför vill Ak'Zeloth att Demon Seed förstörs?",a="Ak'Zeloth följer direkta instruktioner från Neeru Fireblade i Orgrimmar. Demon Seed fungerar som en aktiv förbindelse för Burning Legion på Dreadmist Peak. Genom att neutralisera den med en defekt kraftsten bryter de just den demoniska förbindelsen till Azeroth och slår mot Legionens redskap i The Barrens.",al={"ak'zeloths motiv","varför förstöra demon seed","varför vill ak'zeloth ha det här"}}},fp="14,237,21.308.0,21.297.1,23.164.0,45.162.0,50.158.0,35.122.0,46.234.1,41.186.0"}
P.entries["quest:92401"] = {n="A Frightened Request",s="A Frightened Request är ett uppdrag om Edward Heartweavers försvinnande i de farofyllda Ruins of Lordaeron. Efter att hans son gått förlorad när huvudstaden föll, slukades Edward av sorg. Han reste gång på gång till den förstörda stadens gravplats för att leta efter sin sons kvarlevor, men försvann sedan. En äventyrare ombeds trotsa de farliga ruinerna för att ta reda på vad som till sist hände honom.",h="A Frightened Request är ett uppdrag om Edward Heartweavers försvinnande i de farofyllda Ruins of Lordaeron.",kw={"a frightened request","arthas","edward heartweaver","heartweaver","lordaerons gravplats","försvunnen make","ruins of lordaeron","scourge"},ang={["class:Priest"]="Präster som ägnar sig åt andlig läkning och tröst kan lätt förstå den outhärdliga sorg och andliga oro som driver en far att söka efter sin förlorade son på en övertagen gravplats.",["race:Human"]="Lordaerons fall är fortfarande en av de djupaste tragedierna i människornas minne. För människor är Edwards desperata sökande en gripande påminnelse om alla familjer som slets isär när prins Arthas förrådde och slaktade sitt eget folk.",["race:Undead"]="Ruinerna ovanför Undercity tillhör Forsaken, som reste sig ur kungarikets aska. Levande människor som vandrar genom den sönderslagna huvudstadens gravplats speglar det förflutnas kvardröjande spöken i marker som Forsaken nu råder över."},sec={{t="En fars sorg",b="När prins Arthas och Scourge jämnade Lordaerons huvudstad med marken under det tredje kriget slets oräkneliga familjer isär i blodbadet. Bland dem som krossades av tragedin fanns familjen Heartweaver, som förlorade sin unge son när kungariket föll. Eftersom pojkens kropp aldrig återfanns bland ruinerna greps hans far, Edward Heartweaver, av överväldigande sorg och olöst skuld. Edward kunde inte släppa det förflutna eller acceptera att förlusten var oåterkallelig, och började därför varje vecka göra farliga resor till den övertagna gravplatsen i den förstörda huvudstaden. Han var desperat efter att hitta minsta spår av sin sons kvarlevor."},{t="Farorna i ruinerna",b="Ruinerna ovan jord i Lordaeron är inte längre någon stillsam minnesplats. Efter stadens förstörelse har fientliga varelser och lurande fasor tagit över området, som fortfarande är ytterst farligt för vanliga invånare. Trots upprepade varningar och vädjanden från sin rädda hustru vägrade Edward att överge sin veckovisa vaka. När hans vanliga resa följdes av flera dagars oförklarlig frånvaro vände sig hans förtvivlade hustru till dugliga äventyrare. Hon bad dem trotsa farorna i ruinerna och ta reda på vad som till sist hänt hennes make."}},faq={{q="Vem är Edward Heartweaver?",a="Edward Heartweaver är en sörjande mänsklig far vars son försvann när Scourge förstörde Lordaeron. Plågad av skulden över att aldrig ha återfunnit sin sons kropp reste Edward varje vecka till den igenvuxna gravplatsen bland huvudstadens ruiner för att leta efter honom, tills han själv försvann under mystiska omständigheter.",al={"vem är edward","edward heartweavers bakgrund","make i ruinerna"}},{q="Varför begav sig Edward till Ruins of Lordaeron?",a="Edward gav sig in i Ruins of Lordaeron för att leta efter kvarlevorna av sin son, som gick förlorad när prins Arthas jämnade huvudstaden med marken. Tyngd av sorg och bristen på svar vägrade Edward att sluta söka igenom ruinernas farliga gravplats, trots sin hustrus varningar.",al={"varför for edward till lordaeron","edward heartweavers gravplats","varför söka i lordaerons ruiner"}},{q="Varför är Ruins of Lordaeron så farliga?",a="Sedan Scourge plundrade huvudstaden under det tredje kriget har de synliga ruinerna av Lordaeron övertagits av farliga varelser och fientliga styrkor. Vanliga civila kan inte färdas där säkert, vilket gör varje längre sökande på de gamla markerna ytterst farligt.",al={"varför är lordaerons ruiner farliga","vad finns i lordaerons ruiner","hot i ruinerna av lordaeron"}},{q="Vem erbjuder uppdraget A Frightened Request?",a="Uppdraget erbjuds av Edward Heartweavers oroliga hustru. Hon kan inte själv möta de dödliga fasor som lurar i det förstörda kungariket och vänder sig därför till äventyrare på genomresa för att hitta sin make, som inte återvänt från sin veckovisa söktur.",al={"vem ger a frightened request","uppdragsgivare för a frightened request","edwards hustru uppdrag"}},{q="Vad hände med Edwards son?",a="Familjen Heartweavers son gick förlorad när Lordaeron föll och prins Arthas och hans odöda styrkor ödelade staden. Barnets kropp hittades aldrig i kaoset, och fadern lämnades med en bottenlös sorg och obesvarade frågor.",al={"vad hände med sonen","edward heartweavers son","förlorad son i lordaeron"}},{q="Vad är målet med A Frightened Request?",a="Uppdraget går ut på att äventyrare ska ta sig till de farliga Ruins of Lordaeron och undersöka vad som hände med Edward Heartweaver. Spelarna måste trotsa de övertagna stadsområdena för att ta reda på vad som till sist hänt honom och ge svar till hans väntande hustru.",al={"vad ska jag göra i a frightened request","målet med a frightened request","hur slutför man a frightened request"}}},fp="20,248,16.370.0,23.382.0,26.193.0,44.204.0,44.163.0,42.168.0,30.169.0,46.117.0"}
P.entries["quest:92415"] = {n="Remember That I Love You",s="\"Remember That I Love You\" börjar med ett trasigt, fläckat pergament som hittas bland gravarna i Ruins of Lordaeron, där de odöda strövar. Brevet berättar den tragiska historien om ett försvunnet barn i familjen Heartweaver. För att få svar måste du ta denna ömtåliga relik söderut till barnhemmet i Stormwind City.",h="\"Remember That I Love You\" börjar med ett trasigt, fläckat pergament som hittas bland gravarna i Ruins of...",kw={"blood-stained letter","capital city","heartweaver","orphan matron nightingale","remember that i love you","ruins of lordaeron","stormwinds barnhem"},ang={["faction:Alliance"]="Att föra brevet säkert till Stormwind hedrar minnet av de nordliga familjer som splittrades när Lordaeron föll.",["race:Human"]="För människor med rötter i Lordaeron är denna pergamentbunt en smärtsam påminnelse om familjerna som splittrades när prins Arthas och Scourge intog Capital City."},sec={{t="En vädjan från ruinerna",b="Bland den fördärvade marken och de hasande odöda som hemsöker ruinerna av Capital City hittar överlevande och skattsökare ibland påminnelser om Tredje krigets förödelse. Denna trasiga bunt blodfläckat pergament har knappt överlevt gravplatsens odöda horder. Brevet nämner ett försvunnet barn av släkten Heartweaver och vittnar om liv som slogs i spillror när prins Arthas och Scourge härjade genom kungariket."},{t="Färden till barnhemmet",b="När Lordaeron hade fallit och Undercity tagit över katakomberna därunder skingrades de få flyktingar som flytt söderut över Alliansens kungadömen. I Stormwind City tar Orphan Matron Nightingale hand om barn som förlorat sina föräldrar i krigen. Att överlämna det blodfläckade brevet till henne ger ett av få hopp om att ett överlevande barn i familjen Heartweaver kan identifieras och få ett avslut."}},faq={{q="Var hittas det blodfläckade brevet?",a="Den trasiga, fläckade pergamentbunten hittas på gravplatsen i Ruins of Lordaeron, ett område där The Restless Dead och Forsaken-styrkor nu strövar.",al={"var hittar man brevet","pergamentets plats","var börjar uppdraget"}},{q="Vilka är familjen Heartweaver?",a="Det är ännu inte mycket känt om familjen Heartweaver. Brevet, som hittas på en gravplats i Ruins of Lordaeron, nämner ett försvunnet barn i familjen och väcker hopp om att barnet flytt söderut till ett skyddat boende för Alliansen.",al={"heartweaver","vilka är heartweaver-familjen","heartweaver-historia"}},{q="Vem är Orphan Matron Nightingale?",a="Orphan Matron Nightingale förestår Stormwind Orphanage i Cathedral Square i Stormwind City, där hon ger mat, tak över huvudet och vägledning åt barn som förlorat sina föräldrar i de senaste krigen.",al={"nightingale","matron nightingale","föreståndarinnan för barnhemmet"}},{q="Varför ta ett minne från Lordaeron hela vägen till Stormwind?",a="När Scourge intog Lordaeron evakuerades många föräldralösa barn söderut till kungariket Stormwind. Pergamentet antyder att föreståndarinnan för barnhemmet i Stormwind City vet mer.",al={"varför stormwind","varför skicka det till nightingale"}},{q="Kan Hordespelare slutföra det här uppdraget?",a="Uppdraget leder den som bär brevet till Orphan Matron Nightingale, djupt inne i Cathedral Square i Stormwind City, och lägger därmed resan helt i Alliansens händer.",al={"hordeversion","kan horden göra det här"}},{q="Hur ser Ruins of Lordaeron ut just nu?",a="Ruinerna av Capital City ovan jord är till största delen öde och sönderfallande, och hemsöks av kvarvarande odöda. Lady Sylvanas Windrunner och Forsaken har befäst sin underjordiska huvudstad, Undercity, i kryptorna nedanför.",al={"ruins of lordaeron nuvarande tillstånd","vem kontrollerar ruins of lordaeron"}}},fp="24,250,21.276.0,24.357.0,40.125.0,30.153.0,33.158.0,55.192.0,38.114.0,51.211.0"}
P.entries["quest:92421"] = {n="Light's Justice",s="Light's Justice är ett uppdrag för de Fördömda som Morbin Lightbane ger i Undercity. Äventyrare får i uppdrag att rensa Ruins of Lordaeron ovanför från kvarvarande Gissel och samlar in oskadade lemmar som behövs för att laga och hålla sina ruttnande Fördömda fränder vid liv.",h="Light's Justice är ett uppdrag för de Fördömda som Morbin Lightbane ger i Undercity.",kw={"fördömd paladin","garek bandarion","oskadade lemmar","light's justice","morbin lightbane","ruins of lordaeron","gisslet","undercity"},ang={["class:Paladin"]="Morbin Lightbane säger öppet att han är en paladin bland de Fördömda. Det visar att hängivenheten till heligt krig och stridsplikt kan bestå i odöden under den mörka damens tjänst.",["faction:Horde"]="Att säkra Ruins of Lordaeron ovanför Undercity skyddar Hordens livsviktiga nordliga huvudstad och stärker deras bräckliga fäste i Eastern Kingdoms.",["race:Undead"]="De Fördömdas kroppar kan inte återskapa ruttnande kött på egen hand. Därför är det ett grymt måste att ta lemmar från rester av Gisslet för att hålla deras sårade och soldater hela."},sec={{t="Gisslet ovanför",b="Direkt ovanför Undercity fortsätter tanklösa rester av Gisslet att ströva omkring på de förstörda gatorna i Lordaerons forna huvudstad. Trots den mörka damens seger över dreadlords och grundandet av de Fördömdas kungarike är det fortfarande en utdragen och kostsam kamp att rensa ytan. De invaderande odöda hotar ingången till Undercity och tär ständigt på försvarsstyrkorna som skickas ut för att återta det fallna kungariket."},{t="Kött och ben",b="Odöda kroppar läker inte av sig själva; ruttnande vävnad och avslitna senor kan inte växa ihop på egen hand. För att hålla sina stridsstyrkor vid liv skickar Morbin Lightbane ut krigare för att ta oskadade lemmar från det förstörda Gisslet i ruinerna ovanför. De bärgade delarna ger livsviktiga transplantat och ersättningar, så att sårade Fördömda kan härda ut och strida ännu en dag."},{t="En kaptens arv",b="Morbin Lightbane utför denna dystra plikt för att hedra sin bortgångne befälhavare, kapten Garek Bandarion. Morbin minns Bandarions löfte att läka sitt folk och befria Lordaeron från Gisslets ockupation. Han ser förstörelsen av deras tanklösa fiender och återställandet av deras fränder som den sanna förkroppsligandet av rättvisa under Banshe drottningen."}},faq={{q="Vem är Morbin Lightbane?",a="Morbin Lightbane är en Fördömd paladin som bor i Undercity. Han är hängiven åt att utföra Lady Sylvanas vilja och sörjer för sina odöda fränders fysiska överlevnad samtidigt som han hedrar minnet och uppdraget från sin fallne kapten, Garek Bandarion.",al={"vem ger light's justice","vem är morbin lightbane","uppdragsgivare"}},{q="Varför behövs oskadade lemmar?",a="De Fördömdas kött ruttnar naturligt och kan inte läka eller växa ihop av sig självt. För att laga skadade kroppar och hålla sina krympande stridsstyrkor i tjänst måste de Fördömda ta oskadade lemmar från fallna odöda i ruinerna ovanför.",al={"varför oskadade lemmar","varför behöver de fördömda lemmar","varför samla kroppsdelar"}},{q="Vem var kapten Garek Bandarion?",a="Kapten Garek Bandarion var en vördad befälhavare som arbetade för att rena Lordaeron från rester av Gisslet och läka sina Fördömda fränder. Trots att han har fallit fortsätter hans anhängare hans arbete till hans minne.",al={"vem var kapten bandarion","garek bandarions bakgrund","garek bandarion"}},{q="Var finns Gisslets styrkor?",a="Lemmarna samlas in i Ruins of Lordaeron, staden på ytan direkt ovanför Undercity, där obundna inkräktare från Gisslet fortfarande strövar i farligt stora antal trots de Fördömdas pågående försök att rensa bort dem.",al={"var strövar gisslet","var finns oskadade lemmar","gisslet i ruins of lordaeron"}},{q="Finns det paladiner bland de Fördömda?",a="Morbin Lightbane kallar sig uttryckligen en paladin bland de Fördömda. Traditionella mänskliga paladiner tjänar det Heliga Ljuset, men Morbin riktar sin stridsmässiga hängivenhet mot att tjäna Sylvanas Windrunner och skydda sitt folk.",al={"kan fördömda vara paladiner","odöda paladiner bakgrund","fördömd paladin"}},{q="Vad betyder ”Light's Justice” för de Fördömda?",a="Titeln anspelar på gudomlig vedergällning, omtolkad av Morbin Lightbane. För honom innebär rättvisa att utrota det tanklösa Gisslet från Lordaerons huvudstad och förvandla deras kvarlevor till de Fördömdas räddning.",al={"vad betyder light's justice","varför heter det light's justice","uppdragsnamnets betydelse"}}},fp="15,199,17.319.0,14.274.0,18.294.0,24.194.0,28.192.0,32.168.0,37.178.0,38.151.0,53.135.0"}
P.entries["quest:92422"] = {n="The Wrath of Rath'mael",s="The Wrath of Rath'mael är ett uppdrag för de Förfallna som ges av Deathguard Kristof i Brill. Äventyrare får i uppgift att ta sig in i de dimhöljda Ruins of Lordaeron och döda Rath'mael, en nekromantiker från Scourge som döljer de odödas rörelser ovanför Undercity.",h="The Wrath of Rath'mael är ett uppdrag för de Förfallna som ges av Deathguard Kristof i Brill.",kw={"brill","deathguard kristof","lordamere overlook","rath'mael","rathmael","ruins of lordaeron","nekromantiker från scourge","the wrath of rath'mael","tirisfal glades","ohelig dimma"},ang={["faction:Horde"]="Att säkra Lordaerons omgivande områden bevarar Hordens fäste i Eastern Kingdoms mot outtröttliga odöda vidunder.",["race:Undead"]="De Förfallna håller Undercity direkt under den förstörda huvudstaden, så varje växande närvaro från Scourge på gårdarna och kyrkogårdarna ovanför hotar deras egen tröskel."},sec={{t="En slöja över ruinerna",b="Spaningsrapporter från Lordamere Overlook tyder på att en hotfull närvaro har fått ett allt hårdare grepp om Ruins of Lordaeron. En tät, ohelig dimma har lagt sig över de förstörda gatorna och den närliggande kyrkogården och döljer de kvarvarande styrkorna från Scourge. Den övernaturliga slöjan är Rath'maels verk, en nekromantiker på uppgång vars besvärjelser låter hans odöda tjänare röra sig obemärkt och hålla sig dolda precis ovanför de Förfallnas hjärta."},{t="Tirisfals försvar",b="Deathguard Kristof i Brill inser att de Förfallna inte kan låta ett sådant hot slå rot utan motstånd och uppmanar därför äventyrare att samla sina allierade och slå ner Rath'mael. Kristof vet att Scourges hierarki förr eller senare ersätter en sådan trollkarl, men genom att döda Rath'mael störs deras samordning, den magiska slöjan skingras och Tirisfal Glades får ett välbehövligt andrum."}},faq={{q="Vem är Rath'mael?",a="Rath'mael är en nekromantiker från Scourge som nyligen har fått en framträdande ställning bland de odöda styrkor som håller till i Ruins of Lordaeron. Med mörk magi frammanar han en ohelig dimma som döljer Scourges rörelser på gatorna och kyrkogården nära Lordamere Overlook.",al={"vem är rathmael","vem är rath'mael","rathmael bakgrund"}},{q="Vad är den oheliga dimman i Ruins of Lordaeron?",a="Den övernaturliga dimma som hänger över den förstörda huvudstadens gator och kyrkogård är en ohelig dimma frammanad av nekromantikern Rath'mael. Den sveper in området i mörker och låter de kvarvarande styrkorna från Scourge röra sig obemärkt och hålla sig dolda för de Förfallnas patruller.",al={"vad är dimman i lordaeron","varför är det dimma i ruins of lordaeron","ohelig dimma i ruinerna"}},{q="Vem ger uppdraget?",a="Deathguard Kristof är en soldat bland de Förfallna, stationerad i staden Brill i Tirisfal Glades. Han håller uppsikt över vägarna till ruinerna av huvudstaden och uppmanar nu mästare att döda Rath'mael innan hotet från Scourge blir omöjligt att hantera.",al={"vem ger wrath of rathmael","var finns deathguard kristof","kristof brill"}},{q="Var finns Rath'mael?",a="Rath'mael verkar djupt inne i Ruins of Lordaeron, särskilt kring gatorna, kyrkogården och trakten vid Lordamere Overlook, som vetter mot sjön.",al={"var finns rathmael","var hittar man rath'mael","rathmaels plats"}},{q="Varför vill de Förfallna att Rath'mael dödas?",a="De Förfallna kan inte låta Scourge samla styrkor eller dölja sina positioner precis ovanför Undercity. Rath'maels nekromantiska slöja utgör ett omedelbart taktiskt hot mot de Förfallnas försvarslinjer och resenärernas säkerhet i hela Tirisfal.",al={"varför döda rathmael","varför slåss mot rathmael"}},{q="Tryggas ruinerna för gott när Rath'mael dör?",a="Nej. Som Deathguard Kristof konstaterar kommer Scourge förr eller senare att ersätta fallna befälhavare med en annan mörk magiker. Att döda Rath'mael hejdar bara deras framfart för stunden, minskar deras antal och skingrar dimman ett tag.",al={"tar scourge slut om rathmael dödas","försvinner scourge efter rathmael"}}},fp="22,220,23.287.0,23.277.0,17.218.0,49.148.0,24.213.0,27.122.0,45.173.0,52.178.0"}
P.entries["quest:92432"] = {n="An Alarming Request",s="Emissary Jacques i Southshore kommer med dåliga nyheter från Dalaran: stadens ley lines har rubbats, och dess konstrukter har blivit oberäkneliga och destruktiva. Archmage Modera skickade Jacques för att söka hjälp utifrån, och du får i uppdrag att söka upp hennes avbild nära Dalaran, vid Lordamere Lake.",h="Emissary Jacques i Southshore kommer med dåliga nyheter från Dalaran: stadens ley lines har rubbats, och dess...",kw={"alterac","konstrukter","dalaran","jacques","ley lines","lordamere","modera","southshore"},sec={{t="Problem i Dalaran",b="Emissary Jacques säger att Dalarans ley lines har rubbats, och att stadens konstrukter nu beter sig oberäkneligt och destruktivt. Orsaken är ännu okänd. Det höga rådet har beordrat att saken hålls hemlig för att inte dra skam över orden, men Jacques säger att charaden inte kan fortsätta för evigt, eftersom staden håller på att översvämmas. Archmage Modera skickade Jacques för att söka hjälp utifrån, och du ska hitta hennes avbild nära Dalaran, vid Lordamere Lake."},{t="Moderas välkomsthälsning",b="Vid sin avbild konstaterar Modera att Jacques lyckades hitta hjälp. Även om det inte är helt tillåtet säger hon att stolthet inte bör få staden att avvisa allierade i sin desperata stund. Hon varnar för att inget alls är under kontroll, vad vakterna än vill få dig att tro."}},faq={{q="Vem är Emissary Jacques?",a="Jacques är Dalarans emissarie i Southshore, utsänd av Archmage Modera för att söka hjälp utifrån.",al={"emissary jacques","vem är jacques","vem kommer med en alarmerande begäran"}},{q="Vad händer i Dalaran?",a="Stadens ley lines har rubbats, och dess konstrukter beter sig nu oberäkneligt och destruktivt. Orsaken är ännu okänd, och staden håller på att översvämmas.",al={"vad är fel i dalaran","dalarans problem","varför anfaller konstrukterna dalaran"}},{q="Varför hålls saken hemlig?",a="Det höga rådet beordrade att problemen skulle hållas hemliga för att inte dra skam över orden.",al={"varför hemlighetsmakeri i dalaran","varför dölja konstrukterna","dalarans höga råd håller hemligt"}},{q="Var finns Image of Archmage Modera?",a="Nära Dalaran, vid Lordamere Lake.",al={"var hittar man modera","moderás plats","image of archmage modera"}}},fp="19,262,18.421.0,16.232.1,24.96.0,29.143.0,37.75.0,46.78.0"}
P.entries["quest:92434"] = {n="Blood in the Streets",s="Dalarans barriär har fallit, och oro råder i staden. När patrullerna är undanröjda säger Magus Wordeen Voidglare att det inte finns något bättre tillfälle att smyga in och lära sig magikernas hemligheter. Du ska föra nyckeln från interneringslägret till stadens kloaker vid den norra kanten.",h="Dalarans barriär har fallit, och oro råder i staden.",kw={"alterac","blood in the streets","dalaran","smutsig nyckel","lordamere lake","modera","kloaker","wordeen voidglare"},sec={{t="En otrevlig väg in",b="Efter Dalaran Patrols säger Magus Wordeen Voidglare att vad som än sänkte Dalarans barriär har kastat staden i oro, så nu är det dags för Horde att ta sig in och lära sig magikernas hemligheter. Du ska ta nyckeln från interneringslägret och leta efter kloakerna vid stadens norra kant, intill Lordamere Lake. Med lite tur såg magikerna inget behov av att skydda en så otrevlig ingång med besvärjelser."},{t="Vad nyckeln leder till",b="The Image of Archmage Modera ber dig att sänka vapnet. Hon säger att nyckeln inte räcker för att ta sig förbi hennes skyddsbesvärjelser, eftersom magikerna inte skulle lämna en sådan svaghet oskyddad i ett läge som detta. Hon säger att Hordes intresse för hennes stad inte är någon slump, att hon räknade med det och att hon har ett förslag till dig."}},faq={{q="Vem skickar dig till Dalarans kloaker?",a="Magus Wordeen Voidglare, när patrullerna har undanröjts.",al={"uppdragsgivare för blood in the streets","vem ger blood in the streets","wordeen voidglare-uppdrag"}},{q="Var ligger ingången till Dalaran?",a="Wordeen visar dig till kloakerna vid stadens norra kant, intill Lordamere Lake.",al={"var finns dalarans kloaker","kloakingång vid lordamere lake","hur tar man sig in i dalaran"}},{q="Vilken nyckel används i försöket att ta sig in?",a="Den smutsiga nyckeln från interneringslägret.",al={"smutsig nyckel till dalaran","varifrån kom nyckeln","nyckel från interneringslägret"}},{q="Varför är Dalaran sårbart just nu?",a="Dess barriär har fallit, och oro råder i staden.",al={"varför har dalarans barriär fallit","vad hände med dalarans sköld"}}},fp="20,259,21.345.0,21.270.1,36.89.0,43.61.0,34.49.0,36.60.0"}
P.entries["quest:92456"] = {n="A Green Sample",s="A Green Sample är ett ärende från Shylamiir i Stormwind City, där äventyrare får i uppdrag att ta sig in i den avskilda magiska staden Dalaran. Expeditionen väntar sig ett felfritt exemplar av den manafyllda växtligheten i den centrala trädgården, men upptäcker oväntad demonisk besmittelse bland Kirin Tors växter.",h="A Green Sample är ett ärende från Shylamiir i Stormwind City, där äventyrare får i uppdrag att ta sig in i...",kw={"a green sample","botanik","centrala trädgården","dalaran","fel infused blossom","kirin tor","shylamiir","stormwind city"},ang={["class:Mage"]="Kirin Tors avskilda magiska experiment och Dalarans botanik har länge fascinerat lärda, men oväntad fördärvning tyder på dolda problem i magienklaven.",["class:Rogue"]="Shylamiir anlitar särskilt någon som är bekväm med att göra intrång där hen inte är välkommen och smita förbi Kirin Tors försvar.",["profession:Herbalism"]="När du samlar exotisk växtlighet från Dalarans centrala trädgård upptäcker du att onaturliga energier fördärvar vanliga växter och förvandlar dem till demoniskt besmittade blommor."},sec={{t="Ett ärende till Dalaran",b="I Stormwind City söker den gåtfulla Shylamiir en äventyrlig resenär som är villig att utföra ett diskret ärende i förbjudna områden. Shylamiir fascineras av Kirin Tors ovanliga intresse för botanik och vill ha ett levande exemplar av den manafyllda växtlighet som odlas i Dalarans centrala trädgård. Eftersom de hemlighetsfulla trollkarlarna håller sina gränser stängda för främlingar krävs någon som kan ta sig in obemärkt."},{t="Besmittade rötter",b="När du tar dig in i magokratins centrala trädgård gör du en chockerande upptäckt: växtligheten har inte bara absorberat ren arkansk energi, utan förvandlats till en Fel Infused Blossom. När Shylamiir får se det besmittade växtskottet blir hen överrumplad och inser att de hemlighetsfulla Kirin Tor kämpar med mörkare oroligheter än vad ytan antyder. Ändå visar sig den oväntade demoniska besmittelsen ännu mer fängslande att studera än vanliga arkaniska örter."}},faq={{q="Vem ger uppdraget A Green Sample?",a="Uppdraget erbjuds av Shylamiir i Stormwind City, som söker en utomstående modig nog att ta sig in i Dalaran och samla in växtprover.",al={"vem ger a green sample","uppdragsgivare a green sample","shylamiirs plats"}},{q="Vad ber Shylamiir dig att hämta?",a="Shylamiir ber spelaren hitta ett sätt att ta sig in i Dalaran och hämta växtlighet från stadens centrala trädgård. Förväntningen är ett prov av manafyllt växtliv.",al={"vad vill shylamiir ha","målet med a green sample","föremålet green sample"}},{q="Var finns det efterfrågade provet?",a="Provet kommer från den centrala trädgården i Dalaran, en avskild magokrati som strikt skyddar sina gränser mot intrång utifrån.",al={"var ligger centrala trädgården","hur får man fel infused blossom","dalarans trädgård läge"}},{q="Varför är blomman demoniskt besmittad i stället för manafylld?",a="I stället för frisk, manafylld växtlighet hittar du en Fel Infused Blossom. När Shylamiir får den inser hen att Kirin Tor hanterar mycket mörkare och mer turbulenta krafter än väntat.",al={"varför demoniskt besmittad","är dalaran demoniskt fördärvat","dalarans demoniska växter"}},{q="Varför är Shylamiir intresserad av Dalarans växtlighet?",a="Shylamiir noterar att Dalaran, trots att staden är en magokrati, har ett överraskande intresse för botanik och vill studera hur Kirin Tor odlar sin manafyllda växtlighet.",al={"varför vill shylamiir ha växter från dalaran","orsak till dalarans botanik"}},{q="Hur reagerar Shylamiir på blomman du lämnar in?",a="Shylamiir blir överraskad av att provet är fördärvat av demonisk energi i stället för arkanisk mana, men fascineras av upptäckten och berömmer äventyraren för att ha slutfört det farliga ärendet.",al={"hur reagerar shylamiir","lämna in a green sample"}}},fp="14,172,20.359.0,13.353.1,35.89.0,40.106.0,36.127.0,55.186.0,47.129.0,54.129.0"}
P.entries["quest:92457"] = {n="Starving Arcane",s="Archmage Modera ber dig att rensa bort oregerliga elementarer från City of Dalaran. En reva har rubbat stadens förtrollningar och försvar, och Kirin Tor behöver arbetsro för att se till sina skyddsförtrollningar.",h="Archmage Modera ber dig att rensa bort oregerliga elementarer från City of Dalaran.",kw={"arkan energi","archmage modera","reva","dalaran","elementarer","kirin tor","mana echoes","saturated remnants","seeking remnants","starving arcane"},sec={{t="Arkana fragment",b="Revan har stört faktotumer och förtrollningar över hela Dalaran. Några av dessa förtrollningar skyddar stadens försvar. Splittrad arkan energi har lockat till sig Seeking Remnants, Saturated Remnants och Mana Echoes. De samlas för att fylla sig med dess fritt flödande magi. Archmage Modera ber dig att minska deras antal medan Kirin Tor ser till skyddsförtrollningarna och tar hand om andra incidenter."}},faq={{q="Varför samlas elementarer i Dalaran?",a="Splittrad arkan energi från revan har lockat till sig oregerliga elementarer som vill fylla sig med dess fritt flödande magi.",al={"varför finns elementarer här","elementarer i dalaran","arkana elementarer"}},{q="Vem ber mig att rensa bort elementarerna?",a="Archmage Modera ber dig att minska antalet elementarer inne i staden. Hon befinner sig utanför Dalaran.",al={"vem gav detta","moderas uppdrag","archmage modera"}},{q="Vad påverkade revan?",a="Revan störde faktotumer och förtrollningar i hela Dalaran, däribland några som är knutna till stadens försvar.",al={"skador från revan","vad gick sönder","dalarans skyddsförtrollningar"}},{q="Vilka elementarer rör det sig om?",a="Seeking Remnants, Saturated Remnants och Mana Echoes utgör skaran av elementarer.",al={"vilka remnants","typer av elementarer","vad ska rensas bort"}}},fp="15,185,16.389.0,40.123.0,36.88.0,27.111.0,30.83.0"}
P.entries["quest:92458"] = {n="Heart of Disruption",s="Image of Archmage Modera behöver hjälp med att begränsa en magisk störning i Dalaran. Skyddsbarriärerna kring Violet Citadel är hårt ansträngda, och Kirin Tor behöver tid för att få krisen under kontroll.",h="Image of Archmage Modera behöver hjälp med att begränsa en magisk störning i Dalaran.",kw={"arcane mote","archmage modera","dalaran","heart of disruption","kirin tor","leylinjer","violet citadel","skyddsbarriärer"},sec={{t="En väg in",b="Högst upp i Violet Citadel hördes en dånande smäll från salongerna. Störningen började där, och okontrollerad magisk kraft hotar nu skyddsbarriärerna. Kirin Tor är upptagna där inne, så du får en nyckel och ombeds hitta en mer undanskymd väg in i staden innan störningen förvärras."},{t="Partikeln",b="Modera ber dig att hämta en Arcane Mote. Hon frågar inte vad du såg i citadellet. Hon vill hålla partikeln under kontroll och få slut på störningen. Kirin Tor måste nu ta sig an det arbetet medan skyddsbarriärerna håller."}},faq={{q="Vem ber om hjälp?",a="Image of Archmage Modera ber dig att hjälpa till med att begränsa den magiska störningen i Dalaran.",al={"vem behöver hjälp","modera hjälp","vem gav detta"}},{q="Vad orsakade störningen?",a="Störningen började högst upp i Violet Citadel efter att en dånande smäll hörts från salongerna ovanför.",al={"vad hände i citadellet","varför är skyddsbarriärerna ansträngda","magisk störning"}},{q="Varför är skyddsbarriärerna i fara?",a="Okontrollerad magisk kraft har tagit över citadellet, och Kirin Tor kämpar för att upprätthålla skyddsbarriärerna.",al={"vad är fel med skyddsbarriärerna","varför är dalaran övermannat","okontrollerad magisk kraft"}},{q="Vad ber Modera mig att hämta?",a="Modera vill att du hämtar en Arcane Mote.",al={"vad ska hämtas","arcane mote","partikeluppdrag"}},{q="Varför behöver jag en nyckel?",a="Modera ger dig en nyckel så att du kan ta en mer undanskymd väg in i staden.",al={"vad är nyckeln till","hur kommer man in","citadellets nyckel"}},{q="Vad händer när jag kommer tillbaka med partikeln?",a="Modera säger att Kirin Tor måste hålla partikeln under kontroll och få slut på störningen.",al={"vad gör modera med den","partikelns slut","vad händer sedan"}}},fp="19,193,12.298.0,8.213.0,23.87.0,27.111.0,28.106.0,35.42.0,20.83.0,41.71.0"}
P.entries["quest:92459"] = {n="Friend of the Kirin Tor",s="Archmage Modera's image medger att rådet inte kommer att uppskatta att höra om sveket, men resultaten går inte att förneka: Dalaran lugnar sig, och skydden kan tas ner. Hon ger dig en arcane mote att ta till Archmage Celindra i Violet Citadel.",h="Archmage Modera's image medger att rådet inte kommer att uppskatta att höra om sveket, men resultaten går...",kw={"alterac","arcane mote","celindra","dalaran","kirin tor","modera","violet citadel","skydd"},sec={{t="De goda nyheterna",b="The Image of Archmage Modera medger att rådet inte kommer att uppskatta att höra om sveket, men resultaten går inte att förneka. Staden lugnar sig, och skydden kan nu sänkas. Hon tycker att du bör vara den som framför de goda nyheterna och ger dig en arcane mote att ta till Archmage Celindra i Dalarans Violet Citadel."}},faq={{q="Vem skickar dig till Archmage Celindra?",a="The Image of Archmage Modera, som låter dig framföra de goda nyheterna om Dalaran.",al={"vem ger friend of the kirin tor","uppdragsgivare för friend of the kirin tor","modera-uppdrag"}},{q="Var finns Archmage Celindra?",a="I Violet Citadel, i City of Dalaran.",al={"var lämnar man in friend of the kirin tor","vem är celindra","archmage celindras plats"}},{q="Vilket föremål tar du med till Violet Citadel?",a="En arcane mote, som Modera ger dig att ta till Archmage Celindra.",al={"föremål i friend of the kirin tor","vad är arcane mote"}},{q="Vad är de goda nyheterna?",a="Att Dalaran lugnar ner sig och att dess skydd kan sänkas.",al={"vilka nyheter skickar modera","varför sänka skydden"}}},fp="23,96,13.279.0,35.79.0,27.67.0,45.64.0,22.49.0"}
P.entries["quest:92460"] = {n="Coming of Age",s="Coming of Age markerar den första övergångsriten för unga Skyborne som tar sina första steg bortom Thendal Village på Zephras Isle. Under Ailee Farhearts vägledning anmäler sig noviserna hos byledaren Rorian the Dayseeker för att få en förfädersrelik och formellt lova att hjälpa shen'dorei.",h="Coming of Age markerar den första övergångsriten för unga Skyborne som tar sina första steg bortom Thendal...",kw={"ailee farheart","coming of age","rorian the dayseeker","shen'dorei","skyborne","thendal grove","thendal village","zephras isle"},ang={["race:Skyborne"]="Den här övergångsriten markerar ditt inträde i vuxenlivet och ger dig ett heligt arvegods att bära vart än vindarna för dig."},sec={{t="En övergångsrit",b="För varje ung Skyborne som blir vuxen börjar resan i Thendal Village. Under Ailee Farhearts vägledning tar sig de unga västerut till det stora fadersträdet, där byns äldste väntar. Att träda in i vuxenlivet bland shen'dorei är inte bara en social milstolpe, utan också ett ceremoniellt åtagande att tjäna samhället när problemen i trakten växer."},{t="Förfädernas relik",b="Vid ingången till det stora fadersträdet leder Rorian the Dayseeker ceremonin. Han överlämnar formellt en förfädersrelik till den invigde, ett arvegods som gått i arv genom generationer av shen'dorei. Reliken, som burits av många före dig, är en bestående symbol för hemmets vindar och ska återlämnas till folket först när bärarens aska sprids för vinden."}},faq={{q="Vad är syftet med ceremonin Coming of Age?",a="Den markerar den formella övergången till vuxenlivet för unga Skyborne, välkomnar dem officiellt till aktiv tjänst för shen'dorei och ger dem ett arvegods från förfäderna.",al={"varför coming of age","syftet med coming of age","skybornes övergångsrit"}},{q="Vem inleder uppdraget?",a="Ailee Farheart, som vakar över byns noviser i Thendal Village på Zephras Isle, välkomnar dig och skickar dig för att träffa byns ledare.",al={"vem ger coming of age","var börjar coming of age","ailee farhearts plats"}},{q="Vem ska du rapportera till inför ritualen?",a="Rorian the Dayseeker, ledaren för Thendal Village, står vid ingången till det stora fadersträdet strax väster om bosättningen.",al={"vem är rorian","var finns rorian","rorian the dayseykers plats"}},{q="Vilken relik överlämnas under ceremonin?",a="Rorian överlämnar en ärvd övergångsrelik som burits av generationer av shen'dorei före dig. Enligt traditionen behåller du den till din död, då den går vidare till nästa generation.",al={"vad är reliken","skybornes relik","vad får man"}},{q="Vad betyder ”shen'dorei” i det här sammanhanget?",a="Rorian använder ”shen'dorei” som benämning på Skyborne och anspelar på deras komplexa historia, gemensamma prövningar och bestående identitet på Zephras Isle.",al={"vilka är shendorei","betydelsen av shendorei","skyborne shendorei"}},{q="Vart leder resan direkt efter detta?",a="När du har genomfört din övergångsrit riktar Rorian din uppmärksamhet mot lokala hot mot ön. Det börjar med uppdrag som Harmony in Balance och Infestation Investigation.",al={"vilket uppdrag kommer härnäst","nästa steg efter coming of age","efter rorian"}}},fx={["39b489c8"]={q="Varför skickar Ailee Farheart dig till Rorian?",a="Ailee Farheart anser att du är redo att ta din plats bland ditt folk. Som ung shen'dorei som nått vuxen ålder får du bara uppleva den här milstolpen en gång i livet. Thendal Village har länge väntat på dig och behöver din hjälp, men innan du kan ta ansvar för ditt samhälle kräver traditionen att du först inställer dig hos byns ledare Rorian the Dayseeker för övergångsriten.",al={"varför vill ailee att det här görs","ailee farhearts motiv","varför skicka mig till rorian"}}},fp="13,238,17.279.0,19.293.0,50.145.0,24.109.0,36.123.0,43.160.0,44.137.0,52.152.0"}
P.entries["quest:92461"] = {n="Harmony in Balance",s="Harmony in Balance är en tidig pliktceremoni som Rorian the Dayseeker ger blivande äventyrare på Zephras Isle. Uppdraget går ut på att minska antalet unga vuldren i Thendal Grove för att bevara öns naturliga jämvikt. Genom denna vardagliga nödvändighet lär sig nybörjare hur känsliga de lokala djuren är för de magiska strömmar som skiftar omkring dem.",h="Harmony in Balance är en tidig pliktceremoni som Rorian the Dayseeker ger blivande äventyrare på Zephras Isle.",kw={"harmony in balance","unga vuldren","rorian the dayseeker","thendal grove","vuldren","zephras","zephras isle"},ang={["class:Druid"]="Uppdraget att minska det överbefolkade vuldrenbeståndet stämmer väl överens med den druidiska filosofin, där det ibland krävs att man minskar beståndet för att bevara ekosystemets hälsa som helhet.",["class:Hunter"]="Att hantera hjordarnas storlek och observera hur inhemska djur reagerar på störningar i miljön är grundläggande träning för varje spårare i Thendal Grove."},sec={{t="Vårda lunden",b="Även under en tid präglad av osäkra framtidsutsikter och växande faror kräver den dagliga överlevnaden på Zephras Isle ödmjuk flit. I Thendal Grove har den lokala vuldrenpopulationen vuxit i en ohållbar takt och hotar den känsliga ekologiska harmoni som upprätthåller öns djurliv. Rorian the Dayseeker ger de unga beskyddarna den allvarliga uppgiften att minska deras antal för att förebygga omfattande ekologisk påfrestning."},{t="Oroliga vindar",b="Att minska antalet vilda djur kan verka som vanligt viltvårdsarbete, men vuldrens ökning speglar djupare bekymmer. Djurlivet på Zephras består vanligtvis av fogliga varelser, men det är lyhört för öns atmosfär och reagerar starkt när magin som förs med vindarna hamnar i obalans. Genom att rätta till obalanser i tid hindrar man fogliga varelser från att bli oberäkneliga och farliga skadedjur."}},faq={{q="Varför måste vuldrenbeståndet minskas?",a="Vuldrenbeståndet i Thendal Grove har vuxit bortom hållbara nivåer. Om det inte begränsas riskerar vuldren att tömma de lokala resurserna och rubba den känsliga ekologiska balansen som upprätthåller lundens övriga invånare.",al={"varför döda vuldren","överbefolkning av vuldren","vuldren i thendal grove"}},{q="Vem är Rorian the Dayseeker?",a="Rorian the Dayseeker är en äldre vägvisare och mentor på Zephras Isle. Han leder utbildningen av unga äventyrare och påminner dem om att skyddet av hemtrakten kräver uppmärksamhet på både stora kriser och vardaglig ekologisk förvaltning.",al={"rorian bakgrund","vem är rorian"}},{q="Vad får vuldren att bete sig illa?",a="Vuldren är vanligtvis fogliga varelser, men Zephras inhemska djur kan känna när den omgivande magin i öns vindar hamnar i obalans, vilket utlöser plötsliga beteendeförändringar.",al={"varför är vuldren aggressiva","vuldren beteende"}},{q="Var utförs uppgiften?",a="Uppgiften utförs i Thendal Grove, ett område strax öster och sydöst om bosättningen på Zephras Isle.",al={"thendal grove plats","var ligger thendal grove"}},{q="Vilken läxa försöker Rorian lära ut?",a="Rorian lär ut att skyddet av hemlandet ofta kräver svåra och obehagliga åtgärder. Att ta ett stadigt ledarskap för att återställa den naturliga ordningen är ett viktigt ansvar för varje blivande väktare.",al={"rorian läxa","betydelsen av harmony in balance"}},{q="Vad bör man göra medan man jagar vuldren?",a="Elatrell Featherlight ber äventyrare i närheten att undersöka en svärm besvärliga cirrusflugor. Därför är det praktiskt att samtidigt ta reda på mer om insektsangreppet i lunden.",al={"andra uppdrag i närheten","infestation investigation"}}},fx={["240c10a3"]={q="Vad är de unga vuldren du jagar?",a="Unga vuldren är inhemska varelser som lever i Thendal Grove. De är i allmänhet fogliga och en viktig del av det lokala ekosystemet, men deras antal har ökat till ohållbara nivåer. Dessutom har det lokala djurlivet börjat känna av störningar i magin som Zephras vindar bär med sig, vilket gör att djuren kan uppföra sig oförutsägbart om de inte hålls efter.",al={"vad vuldren är","unga vuldren","vilka vi jagar"}},b29e78f0={q="Varför skickar Rorian dig i stället för att själv sköta gallringen?",a="Nu när du just har markerat din övergång till vuxenlivet prövas du genom de praktiska uppgifterna som krävs för att bevara Zephras. Rorian ser arbetet med Thendal Groves vardagliga behov som en nödvändig plikt och en viktig läxa: även när framtiden är mycket oviss krävs en stadig hand för att skydda hemlandet och bevara harmonin.",al={"varför skicka mig","varför behöver rorian mig","varför jag"}}},fp="18,218,17.292.0,15.277.0,37.198.0,28.195.0,30.163.0,32.99.0,38.150.0,46.153.0"}
P.entries["quest:92462"] = {n="Infestation Investigation",s="Infestation Investigation är ett tidigt uppdrag för unga äventyrare som ger sig ut i Thendal Grove på Zephras Isle. Skogvaktaren Elatrell Featherlight beordrar dem att göra sig av med besvärliga cirrusflugor som börjat svärma i de östra skogarna. Om de lämnas åt sig själva hotar de snabbförökande insekterna att rubba lugnet i skogen och utsätta närliggande bosättningar för fara.",h="Infestation Investigation är ett tidigt uppdrag för unga äventyrare som ger sig ut i Thendal Grove på Zephras...",kw={"cirrusfluga","elatrell featherlight","angrepp","utredning","besvärlig cirrusfluga","thendal grove","zephras"},ang={["class:Druid"]="Att bevara Thendal Grove innebär att hantera rubbningar i naturen innan aggressiva svärmar kaläter skogen.",["class:Hunter"]="För blivande skyttar och spårare ger jakten på små, snabba cirrusflugor mellan träden värdefull övning i att sikta framför rörliga mål i tät terräng."},sec={{t="En svärm i trädkronorna",b="Thendal Grove har länge haft en skör balans, men lokala skogvaktare rapporterar en plötslig ökning av besvärliga cirrusflugor i skogens östra utkant. Enstaka cirrusflugor är små skadedjur, men svärmarna blir snabbt aggressiva och förstörande när de blir för många. Skogvaktaren Elatrell Featherlight skickar genast ut dugliga ungdomar för att minska antalet flygande insekter innan de helt tar över skogen."},{t="De första stegen i tjänst",b="Efter sin första Coming of Age-prövning kastas unga försvarare direkt in i det praktiska arbetet med att sköta Zephras Isle. Att röja undan skadedjur kan verka som enkelt slit, men det är avgörande att skydda skogarna från växande utbrott av vilda djur för att värna närliggande bosättningar. De stora mängderna inälvor och insekter som klänger sig fast vid återvändande jägare visar att svärmen är mycket större än man först befarade."}},faq={{q="Vad är en cirrusfluga?",a="Cirrusflugor är bevingade skadeinsekter som hör hemma i Zephras Isles frodiga miljöer. Var för sig är de små, men de förökar sig snabbt och kan bilda farliga svärmar om antalet inte hålls nere på platser som Thendal Grove.",al={"cirrusfluga","cirrusflugor","vad är cirrusflugor"}},{q="Vem ger uppdraget Infestation Investigation?",a="Uppdraget tilldelas av Elatrell Featherlight, en skogvaktare i Thendal Grove med ansvar för att hålla den lokala faunan och skogarna omkring under kontroll.",al={"uppdragsgivare","vem startar uppdraget","elatrell featherlight"}},{q="Var finns cirrusflugorna?",a="De besvärliga cirrusflugorna samlas i de östra och sydöstra delarna av Thendal Grove på Zephras Isle, där de surrar genom lövverket tillsammans med unga vuldren.",al={"var hittar man flugor","cirrusflugornas plats","flugor i thendal grove"}},{q="Varför är det viktigt att minska antalet cirrusflugor?",a="En enstaka insekt utgör liten fara, men cirrusfluge svärmar kan snabbt bli så täta att de hotar resande, utarmar växtlivet och stör den fredliga balansen i Thendal Grove.",al={"varför döda flugor","varför minska cirrusflugorna","cirrusflugornas hot"}},{q="Vad kommer efter Infestation Investigation?",a="När svärmen har tunnats ut och äventyrarna har rapporterat tillbaka till Elatrell Featherlight skickas de mot infestationens hjärta för att möta The Cirrusfly Queen.",al={"nästa uppdrag","vad händer sedan","uppföljning på utredningen"}},{q="Var passar det här uppdraget in i den tidiga resan på Zephras?",a="Uppdraget erbjuds direkt efter att Coming of Age-prövningen har slutförts och är ett av de första stridsuppdragen för nyutnämnda försvarare av Zephras Isle.",al={"uppdragskedja","när får jag uppdraget","nivåkrav"}}},fp="25,174,21.260.0,22.240.0,20.168.0,46.138.0,34.144.0,41.155.0,43.139.1,60.147.0"}
P.entries["quest:92463"] = {n="The Cirrusfly Queen",s="The Cirrusfly Queen är en jakt på matriarken i den aggressiva insektskolonin i Thendal Grove på Zephras Isle. Efter en första rekognosering av angreppet skickar Elatrell Featherlight rekryter in i lundens hjärta för att döda drottningen och minska svärmen vid källan. När hennes välde får ett slut får de lokala rangervakterna omedelbar lättnad i sitt arbete med att hålla vildmarken under kontroll.",h="The Cirrusfly Queen är en jakt på matriarken i den aggressiva insektskolonin i Thendal Grove på Zephras Isle.",kw={"cirrusfluga","elatrell featherlight","kupa","drottning","soldat","thendal grove","zephras"},ang={["class:Hunter"]="Att fälla en aggressiv drottning och överlista hennes försvarande soldater blir ett tidigt prov i spårning och jakt på vilddjur, och ger direkt beröm från de lokala rangervakterna.",["race:Skyborne"]="Genom att röja undan invasiva svärmar i Thendal Grove hjälper du till att bevara den naturliga balansen och säkra färdvägar genom ditt hemland Zephras Isle."},sec={{t="Anfall mot kupan",b="De första försöken att bekämpa cirrusflugorna visade att det aldrig skulle räcka att bara slå bort enstaka arbetsdrönare för att hejda angreppet som sprider sig över Thendal Grove. Elatrell Featherlight ger dugliga vandrare i uppdrag att ta sig djupare in i lundens sydöstra delar, där huvudkupan ligger. Där styr drottningen kolonin, skyddad av vaksamma och kraftigare soldatdrönare."},{t="En rangervakts börda",b="Vanliga cirrusflugor kan verka som obetydliga skadedjur på avstånd, men deras större varianter utgör en allvarlig fysisk fara för alla som färdas under Zephras trädkronor. Genom att jaga matriarken och stå emot hennes vakter visar nybörjare sin stridsduglighet och får högt beröm och ett respektfullt erkännande från Featherlights rangervakter."}},faq={{q="Var finns The Cirrusfly Queen?",a="The Cirrusfly Queen har sitt bo i det sydöstra hörnet av Thendal Grove på Zephras Isle, nära insektskolonins hjärta.",al={"drottningens plats","var finns cirrusflugdrottningen","hitta drottningen"}},{q="Varför räcker det inte att döda arbetsflugorna?",a="Elatrell Featherlight inser att jakt på kringströvande arbetare bara tunnar ut svärmens ytterkanter. Så länge drottningen lever fortsätter hon att föda aggressiva soldater och fylla på kupan, vilket håller hotet mot Thendal Grove vid liv.",al={"varför döda drottningen","minska kupan"}},{q="Vem ger uppdraget att jaga The Cirrusfly Queen?",a="Elatrell Featherlight erbjuder uppdraget när de första rapporterna från skogen bekräftar hur allvarligt angreppet från cirrusflugorna är.",al={"vem ger uppdraget","uppdragsgivare för drottningen"}},{q="Vad gör drottningen farligare än vanliga cirrusflugor?",a="Till skillnad från de vanliga arbetarna som strövar omkring i lunden omges drottningen av större och betydligt aggressivare soldatdrönare som har i uppgift att försvara hennes kupa.",al={"drottningens fara","cirrusflugsoldater"}},{q="Vilket uppdrag kommer före det här?",a="Det här uppdraget följer direkt på Infestation Investigation, som först slog fast hur utbredd förekomsten av insekter hade blivit i lunden.",al={"förutsättningsuppdrag","vad kommer före"}},{q="Vilken roll har Elatrell Featherlight i området?",a="Elatrell Featherlight ansvarar för säkerheten i vildmarken på Zephras Isle. Hon håller uppsikt över hot i området och vägleder nya äventyrare i skogsspårning och rangervakternas uppgifter.",al={"featherlights roll","vem är featherlight"}}},fx={["4d5b02bf"]={q="Vad är The Cirrusfly Queen?",a="The Cirrusfly Queen är matriarken i hjärtat av angreppet som sprider sig genom Thendal Grove. Hon lurar djupt inne i lunden nära huvudkupan, styr svärmen och förlitar sig på aggressiva soldatflugor som vaktar henne. Att döda vanliga arbetare kommer aldrig att stoppa insekternas förökning. Bara om du fäller drottningen kan kupans grepp om skogen brytas.",al={"vem är the cirrusfly queen","vad är the cirrusfly queen","mål för the cirrusfly queen"}}},fp="19,184,17.272.0,17.271.0,37.121.0,43.176.0,44.139.0,61.75.0,36.117.0,55.166.0"}
P.entries["quest:92464"] = {n="Elemental Unrest",s="Elemental Unrest är ett introduktionsuppdrag som Rorian the Dayseeker ger på Zephras Isle. Sedan öns kännande elementära välgörare gav sig av har de mindre vindandarna nära Thendal Standing Stones blivit upprörda och oberäkneliga. Du skickas till Thendal Grove för att hitta Rorian lärling, Yala Windwatcher, och ta reda på vad som oroar den lokala vinden.",h="Elemental Unrest är ett introduktionsuppdrag som Rorian the Dayseeker ger på Zephras Isle.",kw={"elemental unrest","rorian the dayseeker","thendal grove","thendal standing stones","vindsprites","yala windwatcher","zephras isle"},ang={["class:Shaman"]="Zephras vindandar speglar öns känsloläge som en spegel och gör denna störning till en tydlig varningssignal om en djupare miljömässig obalans.",["race:Skyborne"]="De elementära välgörarnas avfärd har gjort vindarna oberäkneliga. De som förlitar sig på Zephras Isles himmel måste därför vara vaksamma."},sec={{t="En förändring i vinden",b="I generationer levde folket på Zephras sida vid sida med mäktiga, kännande vindandar som vägledde och skyddade dem. Sedan dessa elementära välgörare försvann har ön hamnat i en ständig obalans. Luften sköts inte längre av välvilliga sinnen. Kvar finns bara enkla sprites som återspeglar de ombytliga känslor och krafter som dröjer sig kvar över landskapet."},{t="Thendal Standing Stones",b="Nordost om Rorians utpost, nära de uråldriga Thendal Standing Stones, har luften blivit påtagligt fientlig. Eftersom dessa mindre manifestationer saknar verklig självmedvetenhet beror deras oro inte på illvilja, utan på reaktioner. Rorian skickade sin lärling, Yala Windwatcher, för att bevaka deras oberäkneliga beteende från skogsbrynet och lista ut vilken osynlig spänning som stör dem."}},faq={{q="Varför är vindsprites upprörda?",a="Till skillnad från öns tidigare elementära välgörare saknar dessa vindsprites verklig självmedvetenhet. De speglar instinktivt känslor, avsikter och magiska krafter i omgivningen, och blir oroliga när den lokala miljön hamnar i obalans.",al={"varför är elementarerna arga","orsaken till vindarnas oro","arga sprites"}},{q="Vilka är de elementära välgörare som Rorian nämner?",a="De var kännande, välvilliga vindandar som en gång levde sida vid sida med Zephras invånare. Sedan de gav sig av har ön plågats av ständig oro utan deras stabiliserande inflytande.",al={"elementära välgörare","vem lämnade zephras","vindandar på zephras"}},{q="Var hittar jag Yala Windwatcher?",a="Yala Windwatcher håller till i Thendal Grove i nordost, med utsikt över Thendal Standing Stones där de upprörda vindspritesen samlas.",al={"yala windwatchers plats","var är yala","lärling i thendal grove"}},{q="Vem är Rorian the Dayseeker?",a="Rorian the Dayseeker är en äldre vägvisare på Zephras Isle som vakar över öns andliga balans och studerar de pågående störningarna bland de lokala elementarerna.",al={"vem är rorian","rorian dayseeker"}},{q="Vad händer när jag har hittat Yala?",a="När du talar med Yala går du direkt vidare till att undersöka den verkliga orsaken till oron vid stencirkeln, med uppdraget \"Agitators\" som första steg.",al={"nästa uppdrag","vad händer efter elemental unrest","uppföljning med yala"}},{q="Är vindsprites farliga?",a="De är enkla till sin natur, men deras upprörda tillstånd gör dem oberäkneliga och defensiva. De reagerar aggressivt på intrång så länge den bakomliggande störningen kvarstår.",al={"är sprites fientliga","elementär fara"}}},fx={["8058eaf6"]={q="Varför vill Rorian the Dayseeker att det här ska göras?",a="Ända sedan de elementära välgörarna gav sig av har regionen kastats från en kris till nästa. Nu verkar vindmanifestationerna runt Thendal Standing Stones vara upprörda. Eftersom dessa mindre andar bara speglar de oroliga känslorna och avsikterna hos närbelägna varelser, oroar sig Rorian för vad som kan störa dem. Han skickade sin lärling Yala för att undersöka läget och behöver att du rådfrågar henne, så att de kan fastställa orsaken till oron.",al={"rorians motiv","varför skicka till yala","varför rorian vill detta"}}},fp="16,271,20.339.0,27.338.0,34.226.0,50.210.0,34.134.0,28.155.0,32.126.0,31.148.0"}
P.entries["quest:92465"] = {n="Agitators",s="Agitators är ett tidigt uppdrag på Zephras Isle, som Yala Windwatcher ger. Den aggressiva Al'Aketh-kulten har trängt in i Thendal Grove och hetsat upp de fridfulla, inhemska vindandarna till fientliga elementaler. Äventyrare skickas dit för att skingra de virvlande vindarna och röja undan kultens omvända som hotar området.",h="Agitators är ett tidigt uppdrag på Zephras Isle, som Yala Windwatcher ger.",kw={"agitators","al'aketh","al'aketh-anhängare","roiling winds","shen'dorei","thendal grove","yala windwatcher","zephras isle"},ang={["class:Druid"]="Kultisternas skändning av Thendal Groves naturliga harmoni gör det ytterst angeläget att försvara dess inhemska andar.",["class:Shaman"]="Att se hur kultisterna driver naturliga vindandar till våldsamt raseri är ett angrepp på elementens balans som kräver ingripande."},sec={{t="Oro i lunden",b="Thendal Grove har hamnat i skuggan av Al'Aketh-kulten. Kultisterna är kända för sina oroväckande planer på Zephras Isle. De har trängt in i lunden och hetsar aktivt upp de sköra vindandarna som bor där. De tidigare fridfulla andarna har blivit våldsamma och bildat oberäkneliga virvlande vindar som hotar alla som färdas genom området."},{t="En smärtsam nödvändighet",b="Yala Windwatcher ber förbipasserande hjältar att kuva både de ursinniga elementalerna och Al'Aketh-anhängarna som eldar på oron. När vindvarelserna besegras återfår lunden ett skört lugn, men att ta itu med kultisterna är en sorglig plikt. Yala sörjer att behöva spilla shen'dorei-blod bland sitt eget folk, men inser att kulten inte lämnar dem något val."}},faq={{q="Vem ger uppdraget Agitators?",a="Yala Windwatcher erbjuder uppdraget i närheten av Thendal Grove på Zephras Isle.",al={"uppdragsgivare","vem startar agitators","yala windwatcher"}},{q="Vad gör Al'Aketh-kulten i Thendal Grove?",a="Al'Aketh-kulten har trängt in i lunden och hetsat upp de inhemska vindandarna, så att de fridfulla varelserna blivit fientliga och rasande våldsamma.",al={"vad gör kultisterna","varför är alaketh här","alaketh-anhängarnas syfte"}},{q="Vad är Roiling Winds?",a="De är enkla, inhemska vindandar från Zephras Isle som Al'Aketh-kultisterna har hetsat upp och förvridit till aggressiva virvlande elementaler.",al={"roiling winds","vindandar","vindelementaler i thendal grove"}},{q="Varför sörjer Yala Windwatcher att behöva döda anhängarna?",a="Yala sörjer att behöva spilla shen'dorei-blod i lunden. Det visar att Al'Aketh-anhängarna tillhör hennes eget folk, men har fallit för kultens farliga läror.",al={"varför ångrar yala att hon dödar","spilla shen'dorei-blod","yalas replik när uppdraget slutförs"}},{q="Vilket uppdrag följer efter Agitators?",a="När du har slutfört Agitators åt Yala Windwatcher får du fortsätta dina plikter i uppdraget Return to Rorian.",al={"vilket uppdrag kommer härnäst","fortsättning på agitators","vart går jag efter agitators"}},{q="Var utspelar sig konflikten?",a="Konflikten utspelar sig främst i Thendal Grove på ön Zephras Isle.",al={"agitators plats","thendal grove-zon","var ligger thendal grove"}}},fx={ae9ef6e2={q="Varför vill Yala Windwatcher att du tar itu med Al'Aketh-kulten?",a="Yala Windwatcher ser Al'Aketh-kulten som en plåga som hotar öns balans. Deras ritualer har hetsat de fridfulla inhemska vindandarna till våldsamma Roiling Winds och utsätter alla som går nära Thendal Grove för fara. För att skydda landet och förhindra att oskyldiga liv går förlorade måste hon agera snabbt, skingra de ursinniga elementarerna och driva bort kulten.",al={"yala windwatchers motiv","varför bekämpa kultister åt yala","varför döda roiling winds"}},["5a804844"]={q="Vem skickas du för att döda i Thendal Grove?",a="Du har fått i uppdrag att döda Al'Aketh Converts och förgöra Roiling Winds. Konvertiterna är shen'dorei som anslutit sig till Al'Aketh-kulten och etablerat ett fäste i Thendal Grove, där de lägger sig i de lokala elementen. Deras störande närvaro har hetsat de tidigare fridfulla vindandarna i området och förvandlat dem till våldsamma vindstötar av levande luft som angriper alla som passerar.",al={"mål för agitatorer","vem ska jag döda i thendal grove","vilka är målen för agitatorer"}}},fp="9,192,20.190.0,19.300.0,30.70.0,49.105.0,27.121.0,57.122.0,29.105.0,36.55.0"}
P.entries["quest:92466"] = {n="Call of Earth",s="Call of Earth är en elementär prövning som andliga noviser genomgår för att bevisa sin ståndaktighet. Genom att hämta de begärda föremålen visar den sökande sin uthållighet och beslutsamhet för sin lärare. Den som klarar uppgiften visar sig redo att gå vidare till nästa steg i sin utbildning.",h="Call of Earth är en elementär prövning som andliga noviser genomgår för att bevisa sin ståndaktighet.",kw={"call of earth","beslutsamhet","jord","element","shaman","andar","prövning"},ang={["class:Shaman"]="Call of Earth inleder en novis resa mot samhörighet med stenens och jordens andar. Först måste novisen bevisa sin beslutsamhet för att få djupare insikt.",["faction:Horde"]="Shamanistiska prövningar som Call of Earth är en grundläggande rit för andliga utövare bland hordens folk."},sec={{t="Ett prov på beslutsamhet",b="Call of Earth är en grundläggande prövning för blivande utövare av elementens krafter. Noviser får i uppgift att uppfylla särskilda krav som prövar deras tålamod, motståndskraft och samhörighet med jordens envisa och uthålliga natur. När en äventyrare uppfyller kraven visar det att hen har den inre styrka som krävs för att kommunicera med uråldriga krafter."},{t="Nästa steg",b="När den sökande återvänder med de begärda gåvorna erkänner mentorn dennes obestridliga uthållighet och beslutsamhet. Novisen har visat sig ståndaktig inför elementens krav och får erkännande som redo att ta nästa steg på sin andliga resa."}},faq={{q="Vad är Call of Earth?",a="Call of Earth är en övergångsrit för andliga noviser. Den sökande måste samla in begärda föremål för att bevisa sin uthållighet och ståndaktighet innan hen går vidare till nästa steg i utbildningen.",al={"vad är call of earth","call of earth uppdrag"}},{q="Vad visar det att klara prövningen?",a="När du klarar uppgiften visar du din uthållighet och orubbliga beslutsamhet. Du visar din mentor att du har tillräckligt stadig fokus för att ta på dig större andliga ansvar.",al={"vad bevisade jag","uthållighet och beslutsamhet"}},{q="Vad händer när man har klarat Call of Earth?",a="När du har bevisat din beslutsamhet anser din lärare att du är redo för nästa steg på din väg mot samhörighet med elementen.",al={"vad händer härnäst","nästa uppdrag"}},{q="Varför måste en novis kommunicera med jorden?",a="Jorden står för stabilitet, ståndaktighet och okuvlig styrka. En novis måste bevisa sin egen uthållighet innan hen verkligen kan kommunicera med jordandar.",al={"varför jorden","jordandarnas betydelse"}},{q="Vem leder Call of Earth?",a="En andlig lärare eller en shamanmentor vägleder noviser genom prövningen för att testa deras disciplin och beredskap att knyta band till andarna.",al={"vem ger uppdraget","call of earth tränare"}},{q="Vem får genomgå prövningen?",a="Call of Earth är direkt knuten till elementär samklang och fungerar som ett formande prov för dem som följer elementens väg.",al={"kan vem som helst göra call of earth","är call of earth för shamaner"}}},fp="13,139,17.238.0,13.185.0,26.123.0,43.147.0,48.110.0,40.111.0,31.139.0,40.72.0"}
P.entries["quest:92467"] = {n="Call of Earth",s="Call of Earth är en helig prövning där en elementlärling dricker en Earth Sapta vid Rise of Spirits för att genomtränga slöjan mellan världarna.",h="Call of Earth är en helig prövning där en elementlärling dricker en Earth Sapta vid Rise of Spirits för att...",kw={"call of earth","earth sapta","element","fyra vindar","rise of spirits","schaman","andar"},ang={["class:Shaman"]="Mötet med elementen börjar med kraftfulla elixir som saptor, vilka förankrar schamanens själ så att den kan möta elementandar direkt.",["race:Skyborne"]="Även när du driver högt ovanför det ändlösa molnhavet och är skild från de fyra vindarnas andar erbjuder jorden en stadig grund för förståelse."},sec={{t="Sapta-dryckens natur",b="För att uppfatta den osedda elementvärlden använder schamaner saptor, kraftfulla magiska brygder som särskilt blandats för att stämma en dödlig själ med ett visst elementrike. När någon med tillräcklig beslutsamhet dricker en sapta öppnas den andliga synen för elementvarelser som annars är dolda för dödliga ögon. På grund av sin djupgående natur är dessa drycker välbevakade hemligheter som bara ett fåtal utvalda utövare känner till."},{t="Rise of Spirits",b="Ritualtraditionen kräver strikt att saptor bara dricks på heliga platser. För att möta jorden leds lärlingar nordost genom ett pass till Rise of Spirits. När drycken intas på denna vigda mark kan sökaren genomtränga slöjan och skåda vad andarna vill visa."},{t="Jordens styrka",b="När lärlingen dricker Earth Sapta möter hen en elementvägvisare som känner igen hen som ett barn av de fyra vindarna, på jakt efter förståelse för varför vindarna har gett sig av. Jordanden kan inte förklara vindandarnas gåtfulla avsikter, men lär ut jordens orubbliga beslutsamhet och styrka. Även högt ovanför ett ändlöst molnhav är det nödvändigt att förankra sig i jorden som första steg för att åter tala med vindarna."}},faq={{q="Vad är en Earth Sapta?",a="En sapta är en särskild magisk dryck som bryggs för att binda en schamans själ till ett visst element. När någon med tillräcklig viljestyrka dricker den visar den dolda elementandar som vanliga sinnen inte kan uppfatta.",al={"vad är earth sapta","förklaring av sapta","vad gör en sapta"}},{q="Var måste Earth Sapta drickas?",a="Earth Sapta måste drickas vid Rise of Spirits, en helig plats uppför passet nordost om uppdragsgivaren. Saptor måste alltid drickas på helig mark, inte på vanliga platser.",al={"var dricker man earth sapta","rise of spirits plats","var ligger rise of spirits"}},{q="Varför måste saptor bara drickas på heliga platser?",a="Saptor är kraftfulla rituella brygder som skapats för att knyta dödliga själar direkt till elementen. Enligt schamanernas lära måste de ovillkorligen drickas på särskilt utsedda heliga platser för att man ska kunna möta andarna på rätt sätt.",al={"varför dricka sapta på helig plats","kan jag dricka sapta var som helst"}},{q="Varför tilltalar anden sökaren som ett ”barn av de fyra vindarna”?",a="Elementanden vid Rise of Spirits hälsar lärlingen som ett barn av de fyra vindarna, på jakt efter svar om varför vindarna har gett sig av och hur deras välvilja kan återvinnas.",al={"vem är barn av de fyra vindarna","varför barn av de fyra vindarna"}},{q="Varför har vindandarna gett sig av?",a="Vindandarna har dragit sig undan, men deras exakta avsikter och färder är okända även för jordanden vid Rise of Spirits.",al={"varför gav sig vindarna av","vart tog vindarna vägen"}},{q="Hur hjälper mötet med jorden någon att återknyta kontakten med vindarna?",a="Jorden står för obeveklig styrka och beslutsamhet. Även mitt i ett ändlöst molnhav är alla varelser förankrade i jorden, och att bemästra dess stabilitet är första steget mot att åter få kontakt med de fyra vindarna.",al={"varför börja med jorden","hur hjälper jorden med vindarna"}}},fp="13,133,23.267.0,19.241.0,21.381.1,23.161.0,39.114.0,47.154.0,70.111.0,39.123.0,72.194.0"}
P.entries["quest:92468"] = {n="Call of Earth",s="Call of Earth är en helig prövning i samhörighet där en novis får en bit Rough Quartz från en jordande. Denna mineralskärva blir kärnan i utövarens första Earth Totem när den förs till Windshaper Boros i Thendal Grove, och förankrar bandet till elementens krafter.",h="Call of Earth är en helig prövning i samhörighet där en novis får en bit Rough Quartz från en jordande.",kw={"call of earth","earth totem","element","rough quartz","shaman","thendal grove","windshaper boro","windshaper boros"},ang={["class:Shaman"]="Att få sitt första totem markerar början på samhörigheten med elementens krafter. Det är ett oumbärligt fysiskt fokus för att kanalisera jordbundna besvärjelser och riter.",["race:Skyborne"]="För Skyborne som söker sig tillbaka till vindarna är det viktigt att först bemästra jorden. Vägen till att höra vinden börjar med att förankra sig i jordens fasta grund."},sec={{t="Jordens gåva",b="Uppdraget börjar när en jordande ger en novis en skärva Rough Quartz som levande bevis på deras samhörighet. Anden säger åt bäraren att ta gåvan till Windshaper Boros i Thendal Grove och förklarar att även den minsta bit bär på bestående styrka. Andarna kräver tålamod, uthållighet och visdom innan de skänker sin ynnest och respekt."},{t="De fyra elementen och totemet",b="Windshaper Boros använder Rough Quartz som kärna när han tillverkar ett Earth Totem. Han påminner novisen om att elementens väg har många sidor: även om deras yttersta önskan kan vara att höra och sjunga vindens sånger, kräver sann mästarkunskap förståelse för alla fyra elementens krafter, med den obevekliga marken under fötterna som början."}},faq={{q="Vem är Windshaper Boros?",a="Windshaper Boros, som kallas Boro, bor i Thendal Grove. Som en erfaren utövare och hantverkare vägleder han noviser i att förstå elementandar och formar deras fokustotem av elementens gåvor.",al={"vem är boro","windshaper boros plats","var ligger thendal grove"}},{q="Vad används Rough Quartz till?",a="Rough Quartz är en elementskärva som en jordande ger direkt som bevis på ert möte och er samhörighet. Windshaper Boros använder den som grund och hjärta i ditt tillverkade Earth Totem.",al={"vad är rough quartz","jordskärva","användning av kvarts"}},{q="Varför behövs ett Earth Totem?",a="Ett Earth Totem är ett personligt fokusredskap som behövs för att kommunicera med jordens andar och kanalisera jordbaserade besvärjelser. Det visar att utövaren är en novis och förankrar hen vid världens elementära grundvalar.",al={"vad gör earth totem","totemets syfte","varför behövs ett totem"}},{q="Varför måste man kommunicera med jorden innan man talar med vindarna?",a="Utövare kan sträva efter att höra och sjunga vindarnas sånger, men vindarna utgör bara en del av världens elementära balans. Man måste först studera och bemästra alla fyra elementen, med jordens stabilitet, tålamod och styrka som början.",al={"varför börja med jorden","söker vindarna","alla fyra elementen"}},{q="Var ligger Thendal Grove?",a="Thendal Grove är fristaden där Windshaper Boros sköter elementära angelägenheter och undervisar noviser som inleder sin shamanistiska färd.",al={"var ligger thendal grove","thendal grove zon"}},{q="Vilken visdom förmedlar jordanden?",a="Jordanden lär ut att storleken saknar betydelse, för även den minsta sten kan bestå långt efter att större ting har vittrat sönder. Den kräver tålamod, inre styrka och strävan efter visdom i utbyte mot ömsesidig respekt och harmoni.",al={"vad elementen kräver","jordens filosofi"}}},fp="13,200,16.270.0,31.290.0,24.205.0,40.156.0,32.191.0,63.180.0,31.136.0,41.202.0"}
P.entries["quest:92469"] = {n="Return to Rorian",s="Return to Rorian är ett uppdrag som för med sig brådskande rapporter från fältet till Thendal Grove på Zephras Isle. Efter att ha hjälpt Yala Windwatcher mot de framryckande styrkorna skickas en äventyrare för att informera Rorian the Dayseeker om att Al'Aketh-kulten aktivt har trappat upp sin närvaro genom att störa de lokala vindandarna.",h="Return to Rorian är ett uppdrag som för med sig brådskande rapporter från fältet till Thendal Grove på...",kw={"al'aketh","kult","rorian","stencirkeln","thendal grove","vindandar","yala windwatcher","zephras isle"},ang={["class:Druid"]="Att försvara Thendal Grove och bevara den fredliga harmonin på Zephras Isles heliga marker går naturligt hand i hand med druidiska eder.",["class:Shaman"]="Upptäckten att Al'Aketh medvetet hetsar upp vindandar träffar själva kärnan i en shamanens plikt att bevara den elementära balansen."},sec={{t="En allvarlig rapport",b="Efter att ha slagit tillbaka orosstiftarna som trakasserade Zephras Isle stannar Yala Windwatcher kvar för att ta hand om de återstående fienderna, medan du får ett viktigt uppdrag: att överlämna underrättelser. Thendal Grove måste få veta att de mystiska Al'Aketh inte längre verkar enbart i skuggorna."},{t="Upptrappning vid stencirkeln",b="När Rorian the Dayseeker får rapporten medger han att ledarna i Thendal Grove har följt kultens förehavanden på avstånd en tid. Men kultisternas försök att hetsa upp de inhemska vindandarna nära stencirkeln är en djärv och oroande upptrappning som ledarna i lunden inte längre kan nöja sig med att se på."}},faq={{q="Vem skickar dig för att tala med Rorian?",a="Yala Windwatcher skickar dig för att rapportera till Rorian efter att du hjälpt till att slå tillbaka de fientliga orosstiftarna som hotar området.",al={"uppdragsgivare","vem startar return to rorian","yala windwatcher"}},{q="Var finns Rorian the Dayseeker?",a="Rorian the Dayseeker finns i Thendal Grove, bosättningen där lundens ledare sköter angelägenheterna på Zephras Isle.",al={"var finns rorian","rorian plats","rorian i thendal grove"}},{q="Vilka är Al'Aketh?",a="Al'Aketh är en kult som verkar på Zephras Isle. De övervakades tidigare i tysthet på avstånd, men deras senaste försök att hetsa upp elementära vindandar nära stencirkeln har gjort dem till ett aktivt hot.",al={"vad är kulten","vilka är al'aketh","al'aketh-kulten"}},{q="Varför blev Rorian inte överraskad av nyheten?",a="Rorian och lundens ledare kände redan till kultens förehavanden på ön, men hade tidigare valt att i tysthet hålla uppsikt över dem i stället för att konfrontera dem direkt.",al={"visste rorian","rorians reaktion","varför var det väntat"}},{q="Vad händer efter rapporten till Rorian?",a="När Rorian har tagit emot din rapport och tackat dig för hjälpen till Thendal Grove skickar han dig till Aetheen of the Gales, en medlem av de äldstes råd som har hållit ögonen på dig.",al={"nästa uppdrag","vad följer efter return to rorian","efter return to rorian"}},{q="Varför stannade Yala kvar?",a="Yala Windwatcher valde att stanna kvar på konfliktplatsen för att ta hand om eventuella eftersläntrare, medan du skickades i förväg med de brådskande underrättelserna.",al={"varför stannar yala","vart tog yala vägen","yala windwatchers roll"}}},fx={aa0b8ee2={q="Varför skickar Yala Windwatcher dig till Rorian?",a="Yala behöver omedelbart underrätta ledningen i Thendal Grove om att Al'Aketh-kulten har bekräftats vara där. Medan hon stannar kvar för att ta hand om eftersläntrare i fält måste Rorian the Dayseeker varnas om kultens eskalering och hur den hetsar de lokala andarna, så att lunden kan samordna ett svar.",al={"varför rapportera till rorian","yala windwatchers motiv","varför yala vill att rorian informeras"}}},fp="16,202,13.176.0,33.264.1,35.115.0,38.100.0,21.192.0,41.160.0,44.171.1,25.117.0"}
P.entries["quest:92470"] = {n="Foul Matriarch",s="Foul Matriarch är ett överlevnadsprov som Aetheen of the Gales ger blivande initiater i Thendal Village. Uppgiften kräver att du tar dig ner i grottorna i söder, gallrar bland de asätande ursera och dödar deras våldsamma lya-ledare, Urs'anah. När jakten är slutförd har äventyraren visat den beslutsamhet som krävs för att möta större faror över hela Zephras Isle.",h="Foul Matriarch är ett överlevnadsprov som Aetheen of the Gales ger blivande initiater i Thendal Village.",kw={"aetheen of the gales","foul matriarch","thendal cave","thendal grove","thendal village","urs'anah","ursera","zephras isle"},ang={["class:Hunter"]="Att spåra en våldsam matriark som Urs'anah, som bor i en grotta, är ett grundläggande prov på bestkunskap och beslutsamhet i strid för blivande jägare.",["race:Skyborne"]="För Skyborne-initiater visar det att de behärskar markbundna rovdjur som Urs'anah att de klarar sig själva på marken och är redo att bege sig bortom sin avskilda uppväxtmiljö."},sec={{t="Ett prov på beslutsamhet",b="Aetheen of the Gales håller ett vakande öga på nykomlingar som försöker finna sig till rätta kring Thendal Village. När en initiat visar tidig förmåga ger Aetheen hen ett farligt övergångsprov: en direkt attack mot de rovdjur som hotar byns utkanter. I stället för att bara slåss längs de öppna stigarna skickas initiaten rakt in i de mörka grottorna i söder för att minska de lokala urseraflockarna och möta deras kullmoder."},{t="Hotet från Urs'anah",b="De lokala skogvaktarna har länge lagt märke till urserornas vildsinthet, men ingen utgör ett större hot mot tillflyktsorten än Urs'anah, deras mäktiga matriark. Hon håller till djupt inne i Thendal Cave, där hon styr sina asätare och försvarar sin lya aggressivt. Att återvända med hennes avhuggna huvud är ett definitivt bevis på att äventyraren kan hantera våldsamma bestar och är redo att ta sig bortom startlundens gränser."}},faq={{q="Vem ger uppdraget att döda Urs'anah?",a="Aetheen of the Gales erbjuder provet från Thendal Village. Hon håller uppsikt över lovande nykomlingar som har uppmärksammats av lokala personer som Rorian innan hon prövar deras mod med denna farliga jakt.",al={"vem ger foul matriarch","uppdragsgivare för foul matriarch","vem är aetheen of the gales"}},{q="Var finns Urs'anah och de asätande ursera?",a="Urs'anah och de asätande urserorna håller till i grottorna söder och sydväst om Thendal Village, uppe i kullarna i Thendal Grove. Matriarken har själv sitt bo i grottans djupaste skrymslen.",al={"urs'anahs plats","var finns ursanah","urseragrotta zephras","thendal caves plats"}},{q="Vad är en ursera?",a="Ursera är aggressiva, björnliknande rovdjur som hör hemma bland Zephras Isles vildare klippor. Om de lämnas åt sig själva bygger deras asätande flockar bon farligt nära bebodda bosättningar som Thendal Village.",al={"vad är en ursera","urserornas bakgrund","är ursera björnar"}},{q="Vad innebär det för en äventyrare att slutföra jakten?",a="Att döda Urs'anah är ett avgörande övergångsprov. Genom att besegra både kultistiska inkräktare och lundens farligaste vilda djur bevisar jägaren att hen är redo att lämna Thendal Villages skyddade tillflykt och ta på sig större ansvar över Zephras Isle.",al={"varför döda ursanah","betydelsen av foul matriarch"}}},fx={["03aee340"]={q="Varför skickar Aetheen of the Gales dig mot matriarken?",a="Aetheen of the Gales har följt dina framsteg och kräver att få pröva din beslutsamhet. Hon behöver veta om du har styrkan och uthålligheten att överleva de mycket större faror som väntar på Zephras Isle. När du fäller den farliga matriarken bevisar du att du kan lämna tryggheten i Thendal Village och tjäna ön i svårare och farligare prövningar.",al={"varför aetheen vill ha urs'anah död","aetheens motiv","varför döda urs'anah"}},["30b9798a"]={q="Vad används Urs'anahs huvud till?",a="Huvudet är ett obestridligt fysiskt bevis på matriarkens död. Urs'anah är en ökänd hona som vaktar sitt bo och är välkänd bland de lokala skogsväktarna. Aetheen godtar inget mindre än hennes avhuggna huvud som bekräftelse på att det farliga odjuret verkligen har fällts.",al={"vad urs'anahs huvud används till","varför behålla urs'anahs huvud","syftet med urs'anahs huvud"}},a1adff34={q="Vem är Urs'anah?",a="Urs'anah är den vilda matriarken och bohonan bland områdets ursera. Hon håller till i grottorna söder om Thendal Village. Öns skogsväktare känner till och fruktar henne. Hon leder asätarflocken och är därmed det främsta hotet bland rovdjuren i lunden.",al={"vem är urs'anah","vad är urs'anah","urs'anahs bakgrund"}}},fp="14,220,17.293.0,22.297.0,38.181.0,54.169.0,18.178.0,57.242.0"}
P.entries["quest:92471"] = {n="Aetheen of the Gales",s="Det här uppdraget markerar en övergångsrit för unga äventyrare på Zephras Isle och leder dem till en av öns främsta auktoriteter.",h="Det här uppdraget markerar en övergångsrit för unga äventyrare på Zephras Isle och leder dem till en av öns...",kw={"aetheen of the gales","council of elders","rorian the dayseeker","shen'dorei","thendal grove","zephras isle"},sec={{t="Ett mått på potential",b="De första uppgifterna för noviser på Zephras Isle är mer än vardagssysslor; de prövar om de unga har den beslutsamhet och anda som krävs för att försvara sitt hemland. Eftersom livet på ön ställs inför allt större prövningar håller mentorer som Rorian the Dayseeker ett vakande öga på kandidater som klarar större ansvar."},{t="Vindläsaren i Thendal Grove",b="Djupt inne i Thendal Grove finns Aetheen of the Gales, en respekterad medlem av Council of Elders som styr Zephras Isle. Aetheen läser luftens strömmar och bedömer unga shen'dorei när de blir vuxna. Att träda fram inför henne visar att en novis har vuxit ifrån enklare patrulluppgifter och är redo att möta direkta hot mot samhället."}},faq={{q="Vem är Aetheen of the Gales?",a="Aetheen of the Gales är en ledare på Zephras Isle och medlem av Council of Elders. Hon håller uppsikt över vindarna i Thendal Grove och bedömer personligen unga shen'dorei som blir vuxna för att försäkra sig om att de är redo att försvara sitt hem.",al={"vem är aetheen","aetheen of the gales roll","aetheen zephras"}},{q="Varför skickar Rorian spelare för att träffa Aetheen?",a="Rorian the Dayseeker bedömer nybörjaräventyrare genom deras första uppgifter. När en äventyrare har visat sin förmåga och uthållighet skickar Rorian dem till Aetheen, så att hon kan bedöma deras färdigheter och rikta dem mot större utmaningar för ön.",al={"varför träffa aetheen","rorian skickar till aetheen","syftet med uppdraget"}},{q="Var kan Aetheen of the Gales hittas?",a="Hon finns i Thendal Grove på Zephras Isle, där hon studerar vindarnas rörelser och övervakar de lokala ungdomarnas övergångsriter.",al={"aetheens plats","var är aetheen","thendal grove aetheen"}},{q="Vad är Council of Elders?",a="Council of Elders är det styrande organ som vägleder shen'dorei på Zephras Isle. Ledare som Aetheen sitter i rådet och vakar över samhällets överlevnad, ledarskap och beredskap.",al={"council of elders zephras","vem styr zephras"}},{q="Vad händer efter att man rapporterat till Aetheen?",a="När Aetheen har försäkrat sig om att en ung äventyrare vill tjäna Zephras Isle tilldelar hon allvarliga uppgifter för att hantera faror i den lokala vildmarken. Det börjar med hot som aggressiva vilda djur och fördärvade matriarker.",al={"nästa uppdrag efter aetheen","vad vill aetheen"}},{q="Vad innebär det att bli vuxen för shen'dorei på Zephras Isle?",a="För ungdomar på Zephras Isle innebär det att bli vuxen att bevisa sig genom fysiska och magiska prövningar. Det är mer än en ceremoni: de unga shen'dorei måste visa en äldre på ön, som Aetheen, att de verkligen klarar uppgiften innan de börjar tjäna samhället.",al={"shen'dorei blir vuxna","zephras övergångsrit"}}},fx={d6e78b3c={q="Varför behöver Rorian att just du går och talar med Aetheen?",a="Dina tidiga uppgifter runt ön betraktades i tysthet som prövningar av din duglighet. Zephras står inför allvarliga utmaningar, och dess ledare behöver dugliga, företagsamma unga shen'dorei som är på väg att bli vuxna och kan träda fram för att hjälpa sitt folk. Du har visat vad du går för, så Rorian har valt ut dig som redo för en direkt prövning av äldste Aetheen.",al={"varför jag ska till aetheen of the gales","varför rorian väljer mig","varför skicka mig till aetheen"}}},fp="20,159,22.226.0,32.303.0,28.215.0,45.180.0,40.145.0,30.160.0,40.184.0,62.200.0"}
P.entries["quest:92472"] = {n="The Next Step",s="När de omedelbara hoten från bestarna nära Thendal Village har undanröjts, visar Elder Aetheen of the Gales resenärer söderut mot Shen'dar Village. Resan markerar en övergång från att röja undan vilda djur till att möta Al'Aketh Cults organiserade fanatism. De dyrkar Windlord Al'Akir.",h="När de omedelbara hoten från bestarna nära Thendal Village har undanröjts, visar Elder Aetheen of the Gales...",kw={"aetheen of the gales","al'aketh cult","al'akir","constable aonda","shen'dar village","skywall","thendal village","zephras isle"},ang={["class:Shaman"]="Schamaner känner igen faran i att dödliga blint dyrkar elementarherrar som Al'Akir, vars oberäkneliga natur ofta kräver underkastelse snarare än balans.",["race:Skyborne"]="För Skyborne innebär kampen mot Al'Aketh en direkt strid mot elementarisk fanatism som hotar tryggheten i deras hem och bosättningar runt Zephras Isle."},sec={{t="Lämna Thendal Village",b="Efter att ha visat sig klara av de lokala rovdjuren och matriarkerna som plågar Zephras Isles norra vildmark, kallas äventyrarna till större uppgifter. Elder Aetheen of the Gales inser att enkel skadedjursbekämpning är sekundär jämfört med den verkliga faran som växer på ön. För att skydda öns invånare måste dugliga försvarare skickas till stöd för de avlägsna bosättningarna."},{t="Cultens hotande skugga",b="Det största hotet mot södra Zephras är Al'Aketh Cult. De beskrivs som hänsynslösa fanatiker och ägnar sig åt Al'Akir the Windlord, härskare över elementarplanet Skywall. Deras växande makt utgör ett omedelbart hot mot Shen'dar Village. Som svar skickar Aetheen resenärer söderut längs vägen, förbi lurande bakhållsmän i höglandet, för att förstärka Constable Aondas lokala vaktstyrka."}},faq={{q="Vart leder resan?",a="Vägen går söderut från Thendal Village genom Shen'dar Highlands och slutar vid Shen'dar Village, där Constable Aonda ansvarar för det lokala försvaret.",al={"vart ska jag gå","nästa samlingsplats","destination"}},{q="Vem är Constable Aonda?",a="Constable Aonda är den civila och militära myndighet som upprätthåller ordningen i Shen'dar Village. Just nu har hon i uppgift att skydda byn mot det tilltagande hotet från kultisterna.",al={"constable aonda","vem är aonda"}},{q="Vad är Al'Aketh Cult?",a="Al'Aketh är brutala fanatiker på Zephras Isle som dyrkar Al'Akir the Windlord, Skywalls elementarherre. Deras aggressiva tillväxt utgör ett direkt hot mot öns bosättningar.",al={"vilka är al'aketh","al'aketh cults bakgrund","kultister"}},{q="Vem är Al'Akir?",a="Al'Akir the Windlord härskar över himlen och styr Skywall. Luftvarelser vördar honom, och Al'Aketh Cult dyrkar honom fanatiskt.",al={"vem är al'akir","vindherren","skywalls härskare"}},{q="Varför skickar Elder Aetheen resenärer bort från Thendal?",a="Nu när de omedelbara hoten kring Thendal har hanterats skickar Aetheen beprövade försvarare till Shen'dar Village, där Al'Aketh Cults aggressiva framryckning utgör en mycket större fara för hela ön.",al={"varför lämna thendal","aetheens mål"}},{q="Vilka faror finns längs vägen till Shen'dar Village?",a="Stigen söderut går genom Shen'dar Highlands, där Al'Aketh Ambushers och avhoppade kultligister trakasserar resenärer mellan öns bosättningar.",al={"faror längs vägen","resa söderut","faror i höglandet"}}},fp="13,134,23.226.0,30.315.0,29.140.0,23.152.0,26.157.0,15.133.0,56.194.0,52.145.0"}
P.entries["quest:92473"] = {n="Aggressive Encroachment",s="Aggressive Encroachment är ett uppdrag från Valreaa Valewind för att skydda den lokala bosättningen mot desperata vilddjur. Ursera från ett närliggande ide har blivit allt djärvare, strövar in i byn och hotar dess invånare.",h="Aggressive Encroachment är ett uppdrag från Valreaa Valewind för att skydda den lokala bosättningen mot...",kw={"klor","åldringsträd","intrång","magra urseror","thendal grove","urseror","valreaa valewind"},ang={["class:Druid"]="Druider kommer att känna igen hur lundens känsliga balans har rubbats och se att de lokala urserornas plötsliga aggressivitet och undernäring tyder på en osynlig störning i det lokala ekosystemet.",["class:Hunter"]="Jägare kommer genast att förstå faran med svältande rovdjur, eftersom desperata djur överger sin naturliga försiktighet inför humanoida bosättningar när hungern driver dem."},sec={{t="Desperata rovdjur",b="Urserapopulationen som har sitt bo sydväst om byn utgör nu en akut säkerhetsrisk. Nyligen strövade ett hungrigt ungt djur ända fram till foten av byns centrala åldringsträd och var nära att slita ett barn som lekte i närheten i stycken. Bosättningens skogsvaktare tvingades fälla varelsen innan tragedin hann inträffa."},{t="Gallring i lunden",b="Eftersom hunger och svält driver rovdjuren till att anfalla bebyggda områden har skogsvaktarna beordrat att de magraste urserorna i Thendal Grove ska gallras bort. Genom att avlägsna de desperata och undernärda djuren som stryker omkring utanför idena hoppas Grove Rangers kunna hejda ytterligare intrång tills de har tagit reda på vad som stör det lokala djurlivet."}},faq={{q="Vem erbjuder Aggressive Encroachment?",a="Uppdraget ges av Valreaa Valewind, en ledare bland skogsvaktarna som håller uppsikt över lunden och skyddar den närliggande bosättningen mot rovdjur.",al={"vem ger aggressive encroachment","uppdragsgivare","valreaa valewind uppdrag"}},{q="Varför strövar urserorna så nära byn?",a="Urserorna lider av svält och desperation, vilket driver dem långt bortom sina vanliga jaktmarker och in i bosättningens hjärta.",al={"varför anfaller urseror","urserornas aggressivitet","varför är urseror arga"}},{q="Var hittar man de magra urserorna?",a="De magra urserorna stryker omkring i Thendal Grove sydväst om byn, där de håller till utanför ingångarna till sitt ide i stället för långt inne i grottan.",al={"var finns magra urseror","urserornas plats","björnar i thendal grove"}},{q="Vilken händelse som nästan slutade i tragedi ledde till denna gallring?",a="En ung ursera strövade ända fram till åldringsträdet mitt i byn och försökte anfalla en ung pojke som lekte i närheten. Skogsvaktarna dödade djuret precis i tid för att rädda hans liv.",al={"ursera anfaller pojke","vad hände i byn","pojke vid åldringsträdet"}},{q="Varför beter sig urserorna så oberäkneligt?",a="Skogsvaktarna har lagt märke till att urserorna har blivit ovanligt aggressiva den senaste tiden, men den bakomliggande orsaken till deras plötsliga matbrist och förändrade beteende är fortfarande okänd.",al={"vad förändrades hos urserorna","varför svälter urseror"}},{q="Vilket bevis kräver Valreaa Valewind?",a="Valreaa ber dig ta med sex Scrawny Ursera Claws från de undernärda djuren som stryker omkring i lunden, så att hon kan vara säker på att de farliga rovdjuren har tagits om hand.",al={"vad ska jag samla in","målet med aggressive encroachment"}}},fp="23,153,19.242.0,17.281.0,35.147.0,53.121.0,38.116.0,37.164.0,43.126.0,41.156.0"}
P.entries["quest:92474"] = {n="Falling With Style",s="”Falling With Style” är en introduktionsrit för unga Skyborne i Thendal Village. Den erbjuds högst upp i det lokala vakttornet av den retsamma Myriaal Mistwake och utmanar nybörjare att pröva sin medfödda förmåga att falla långsamt genom att hoppa från plattformen mot Rorian the Dayseeker nedanför.",h="”Falling With Style” är en introduktionsrit för unga Skyborne i Thendal Village.",kw={"falling with style","myriaal mistwake","rorian the dayseeker","långsamt fall","thendal village","walk on air","vakttorn","zephras isle"},ang={["race:Skyborne"]="Det här tidiga provet introducerar nybörjare bland Skyborne till hur deras medfödda vindvandringsmagi fungerar i praktiken och till de kulturella debatterna kring den."},sec={{t="Ett hopp från tornet",b="Högt ovanför Thendal Village på Zephras Isle bjuder Myriaal Mistwake in unga Skyborne att pröva sitt arv i en våghalsig lek. I stället för att behandla sina medfödda magiska gåvor som heliga reliker som måste hållas under sträng kontroll, uppmuntrar Myriaal nykomlingar att hoppa ut i det fria från vakttornets kant. Syftet är både praktiskt och lekfullt: att bemästra den instinktiva konsten att gå på luft innan livet bortom lunden kräver det i farliga situationer."},{t="Skillnad i temperament",b="Övningen visar tydligt två olika inställningar bland Skyborne. Myriaal njuter av plötsliga nedstigningar och skrämmer åskådare för nöjes skull, medan Rorian the Dayseeker står för traditionell försiktighet. När nybörjare glider ner och landar rakt framför honom tillrättavisar Rorian dem för deras vårdslösa uppvisning och varnar för att tanklöst slösa med sina magiska gåvor kan göra en resenär hjälplös när faran slår till. Ändå medger han att kontrollerad övning i byns trygghet har sin plats."}},faq={{q="Vad är syftet med det här uppdraget?",a="Uppdraget lär nybörjare bland Skyborne att hantera sin medfödda förmåga Walk on Air och hjälper dem att kontrollera långsamma nedstigningar från höga platser.",al={"vad gör det här uppdraget","syftet med falling with style","varför göra det här uppdraget"}},{q="Vem ger uppdraget och var?",a="Det ges av Myriaal Mistwake, som väntar högst upp i trävakttornet med utsikt över Thendal Village på Zephras Isle.",al={"uppdragsgivare","var börjar falling with style","vem ger falling with style"}},{q="Framför vem landar du?",a="Du landar nära Rorian the Dayseeker, som Myriaal hoppas kunna skrämma med hoppet.",al={"vem ska man landa nära","vem är rorian","lämna in falling with style"}},{q="Varför blir Rorian upprörd över hoppet?",a="Rorian anser att medfödda magiska gåvor ska bevaras och användas disciplinerat, inte slösas bort på practical jokes som skrämmer folk.",al={"varför är rorian arg","rorian reagerar","varför tillrättavisar rorian dig"}},{q="Vilken förmåga övar man på?",a="Uppdraget lär ut hur man använder Walk on Air, en medfödd förmåga hos Skyborne som saktar ner en karaktärs fall och förhindrar fallskador.",al={"vilken förmåga används","walk on air-uppdraget","skybornes rasegenskap"}},{q="Var utspelar det sig?",a="Övningen äger rum i Thendal Village på Zephras Isle, Skybornes förfäders marker där de börjar sin färd.",al={"uppdragets plats","var ligger thendal village","vilken zon är det här"}}},fx={fb92945d={q="Varför låter Myriaal Mistwake dig hoppa från vakttornet?",a="Myria al Mistwake ser hoppet som en lekfull utmaning som ska hjälpa dig att öva din medfödda förmåga att gå på luft, men hon har också ett retsamt motiv: hon vill skrämma Rorian the Dayseeker och få sig ett gott skratt när hon ser honom bli upprörd.",al={"varför myriaal vill detta","myria al mistwakes motiv","varför hoppa från tornet"}}},fp="18,151,21.318.0,27.303.0,34.105.0,30.91.0,28.80.0,32.125.0,32.95.0,27.103.0"}
P.entries["quest:92479"] = {n="A Scribbled Letter",s="A Scribbled Letter är en kallelse som överlämnas till äventyrare i Northshire Abbey efter deras första sammandrabbningar med närliggande kobolder. Den är skickad under Tordrin Stemblades sigill och uppmanar lovande rekryter att söka hans undervisning och vägledning. Brevet markerar ett avgörande steg i förberedelserna av försvarare som ska möta de växande faror som hotar kungariket Stormwind.",h="A Scribbled Letter är en kallelse som överlämnas till äventyrare i Northshire Abbey efter deras första...",kw={"a scribbled letter","jägartränare","koboldläger","northshire abbey","northshire valley","scribbled letter","tordrin stemblade"},ang={["class:Hunter"]="Tordrin Stemblade handleder jägare i Northshire Abbey och påpekar hur tiderna har förändrats när nya raser tar till bågen för att försvara Stormwind mot bestar och skadedjur.",["faction:Alliance"]="Träning av skickliga försvarare i Northshire Abbey hjälper till att skydda Elwynn Forest mot kobolder som tränger in och andra växande hot mot kungariket Stormwind."},sec={{t="En kallelse i Northshire",b="När äventyrare återvänder från skärmytslingar med koboldlägren som hemsöker dalen får de ett hastigt meddelande i Northshire Abbey. Den lilla skrivelsen är märkt med Tordrin Stemblades sigill och ber dem komma så snart som möjligt innan de tar itu med andra ärenden. Brevet är en brådskande kallelse som ska knyta blivande hjältar till formell handledning inom klostrets skyddande murar."},{t="Vägledning i farliga tider",b="När Tordrin Stemblade får se brevet anmärker han på hur tiderna har förändrats och konstaterar att främlingar har tagit till vapen för att försvara riket. Han erkänner att vildmarken runt omkring blir farligare för varje dag och bjuder in resande att söka hans råd dag som natt medan de övar upp sina färdigheter och hjälper Stormwinds hårt prövade folk."}},faq={{q="Vad är A Scribbled Letter?",a="A Scribbled Letter är ett meddelande som ges till äventyrare i Northshire Abbey när de återvänder från koboldlägren. Det bär Tordrin Stemblades sigill och uppmanar mottagaren att söka upp honom för handledning och träning i dalen.",al={"vad är scribbled letter","uppdraget scribbled letter","brev från tordrin"}},{q="Vem skickade brevet?",a="Brevet skrevs och förseglades av Tordrin Stemblade, en lokal tränare i Northshire Abbey som undervisar nybörjaräventyrare medan de lär sig sitt yrke.",al={"vem skickade brevet","vem skrev brevet","författare till scribbled letter"}},{q="Var finns Tordrin Stemblade?",a="Tordrin Stemblade finns i Northshire Abbey i Northshire Valley. Han är där dag och natt, redo att ge resande undervisning och råd.",al={"var finns tordrin stemblade","tordrins plats","hitta tordrin stemblade"}},{q="Varför skickade Tordrin Stemblade brevet?",a="När en äventyrare har visat vad hen går för mot de lokala kobolderna skickar Tordrin ett meddelande för att se till att de får rätt träning. Han vill förbereda dem på de växande faror som hotar invånarna i Northshire och det större riket Stormwind.",al={"varför skickade tordrin ett brev","tordrin stemblades syfte","varför en kallelse"}},{q="Vilka hot drabbar Northshire just nu?",a="Northshire Valley utsätts för angrepp från aggressiva koboldläger och farliga människoätande bestar som strövar i de omgivande skogarna. Därför samlar lokala mentorer skickliga kämpar och tränar dem.",al={"vilka hot finns i northshire","faror i northshire abbey","kobolder i northshire"}},{q="Vad erbjuder Tordrin Stemblade efter att man fått brevet?",a="När äventyrarna träffar honom erbjuder Tordrin fortlöpande träning och vägledning. Han uppmanar dem att lära känna trakten och hjälpa lokalbefolkningen med de många problem som drabbar kungariket.",al={"vad erbjuder tordrin","tordrins träning","vad händer efter mötet med tordrin"}}},fp="18,193,23.303.0,26.296.0,27.177.0,20.140.0,37.153.0,42.232.0,48.187.0,61.156.0"}
P.entries["quest:92481"] = {n="A Student of the Arcane",s="A Student of the Arcane är ett inledande prov och en kallelse för novisa magiker på Zephras Isle. Efter att nykomlingar visat vad de går för skickar Rorian the Dayseeker dem för att granska en Glowing Recall Crystal och rapportera till den lokala mentorn Dorii Brightwhisper.",h="A Student of the Arcane är ett inledande prov och en kallelse för novisa magiker på Zephras Isle.",kw={"dorii brightwhisper","glowing recall crystal","magikeruppdrag","rorian the dayseeker","student of the arcane","thendal grove","vuldren","zephras isle"},ang={["class:Mage"]="Den här uppgiften markerar starten på en magikers formella utbildning hos Dorii Brightwhisper och gör din magiska resa till ett försök att återställa sedan länge förlorade magiska hemligheter från molnen.",["race:Skyborne"]="Dorii berättar att årtusenden av isolering bland molnen fick de magiska traditionerna att försvagas, så unga lärlingar spelar en central roll i att återuppliva kulturarvet."},sec={{t="Ett meddelande i kristall",b="Efter att ha hjälpt till att hantera de besvärliga vuldren som håller till nära Thendal Grove får blivande magiker ett märkligt föremål: en Glowing Recall Crystal. Kristallen lämnades kvar av Dorii Brightwhisper, öns lokala lärare i magi, och innehåller ett magiskt inspelat meddelande som ska pröva en novis förmåga och välkomna hen till djupare studier i mystik."},{t="Återupptäck magin",b="Enligt Dorii Brightwhisper har kunskaperna i magi långsamt gått förlorade bland deras folk under de långa årtusenden då de levt isolerade högt uppe bland molnen. Dorii ser varje ny utövare inte bara som en elev, utan som en viktig pionjär som ska återfinna förlorad kunskap och återupprätta folkets forna mäktiga magiska arv."}},faq={{q="Vad är Glowing Recall Crystal?",a="Glowing Recall Crystal är ett litet magiskt fokus som Dorii Brightwhisper anförtrott åt Rorian the Dayseeker. Det innehåller ett inskrivet meddelande som ska introducera unga lärlingar till grunderna i magisk kommunikation.",al={"återkallandekristall","kristallmeddelande","vad gör kristallen"}},{q="Vem är Dorii Brightwhisper?",a="Dorii Brightwhisper är den lokala magitränaren i byggnaden bakom Rorian the Dayseeker i Thendal Grove på Zephras Isle. Dorii vägleder unga magiker som vill återta sitt folks uråldriga magiska traditioner.",al={"vem är dorii","magitränare zephras","doriis plats"}},{q="Varför har magin bland folket på Zephras försvagats?",a="Som Dorii förklarar föll magiska konster gradvis i glömska under de tusentals år som deras folk levde isolerat uppe bland molnen. Därför vill lärare som Dorii gärna träna nya noviser att söka efter och återvinna det som gått förlorat.",al={"varför försvann magin","magisk lära från skyn","förlorad magi"}},{q="Vem ger det här uppdraget?",a="Rorian the Dayseeker erbjuder det här uppdraget i Thendal Grove på Zephras Isle när en blivande magiker har slutfört den inledande uppgiften ”Harmony in Balance”.",al={"uppdragsgivare","vem startar a student of the arcane","rorian uppdrag"}},{q="Var hittar jag Dorii Brightwhisper?",a="Dorii Brightwhisper finns i byggnaden direkt bakom Rorian the Dayseeker i Thendal Grove.",al={"dorii brightwhispers plats","var finns magitränaren","hitta dorii"}},{q="Vilket krav måste uppfyllas innan det här uppdraget kan påbörjas?",a="Du måste först slutföra ”Harmony in Balance”, som går ut på att hantera problemet med de lokala vuldren åt Rorian the Dayseeker.",al={"förkrav","vilket uppdrag kommer före"}}},fx={["1ed09f17"]={q="Varför skickar Rorian the Dayseeker dig till Dorii?",a="Rorian förmedlar helt enkelt ett brådskande meddelande som är avsett för dig. Medan du tog hand om hotet från vuldren i närheten lämnade Dorii Brightwhisper en återkallelsekristall med en inskription särskilt riktad till dig. Rorian ser till att du får kristallen och visar dig direkt till magitränaren i lunden, så att din magiska potential inte går till spillo.",al={"varför rorian skickar dig","rorian the dayseekers motiv","varför tala med dorii brightwhisper"}},ab250928={q="Varför vill Dorii Brightwhisper träna just dig?",a="Den magiska konsten har försvagats bland ditt folk under årtusenden av avskildhet bland molnen. Efter att du visat vad du går för mot lokala hot ser Dorii Brightwhisper den råa förmåga som krävs för att hjälpa till att återta detta förlorade arv. Hon söker blivande magiker som aktivt kan utforska och bemästra magin, i stället för att låta uråldrig kunskap blekna bort i minnet.",al={"varför du ska bli a student of the arcane","varför träna mig","varför dorii vill ha mig"}}},fp="23,217,20.301.0,24.270.0,35.210.0,27.215.0,55.213.0,21.118.0,37.101.0,63.111.0"}
P.entries["quest:92482"] = {n="The Way of the Hunter",s="The Way of the Hunter är ett introduktionsuppdrag i jägarnas utbildning för nybörjare i Thendal Grove på Zephras Isle. Efter att ha visat vad de går för mot hotet från de lokala vuldren hänvisas unga spårare av Rorian the Dayseeker till Tai'ree Farsight för att inleda sin formella utbildning.",h="The Way of the Hunter är ett introduktionsuppdrag i jägarnas utbildning för nybörjare i Thendal Grove på...",kw={"jägarlärare","rorian the dayseeker","scribbled note","tai'ree farsight","the way of the hunter","thendal grove","vuldren","zephras"},ang={["class:Hunter"]="Uppdraget är en viktig övergångsrit för nybörjare bland jägarna på Zephras Isle och inleder deras formella utbildning under Tai'ree Farsight."},sec={{t="En kallelse till jakten",b="När unga jägare återvänder efter att ha minskat antalet störande vuldren som stryker omkring i utkanten av Thendal Grove, märker de att deras praktiska färdigheter har väckt lokal uppmärksamhet. Rorian the Dayseeker lämnar över en klottrad kallelse från Tai'ree Farsight, lundens jägarlärare. För nybörjare som ger sig ut i Zephras Isles vidsträckta vildmarker innebar detta ett skifte från enkelt försvar av ön till riktig strids- och överlevnadsutbildning."},{t="Tai'ree Farsights undervisning",b="Tai'ree Farsight håller till nära byns mitt och välkomnar lovande elever med kärv realism. Hon betonar att det krävs skarpa sinnen och blixtsnabba reflexer för att klara sig i otämjd natur och erbjuder vägledning grundad på hennes egna många års erfarenhet. Hennes handledning markerar de första stegen för varje öspårare som vill vässa sitt bågskytte och sina överlevnadsfärdigheter."}},faq={{q="Vem erbjuder uppdraget?",a="Rorian the Dayseeker erbjuder uppdraget i Thendal Grove på Zephras Isle efter att du hjälpt honom med det lokala vuldrenproblemet i uppdraget 'Harmony in Balance'.",al={"vem ger the way of the hunter","vem startar uppdraget","rorian uppdrag"}},{q="Vem är Tai'ree Farsight?",a="Tai'ree Farsight är jägarläraren i Thendal Grove och håller till nära byns mitt. Hon ansvarar för träningen och disciplinen hos blivande skyttar och öspårare.",al={"var finns tai'ree","jägarlärare thendal grove","tai'ree farsights plats"}},{q="Vad är syftet med Scribbled Note?",a="Scribbled Note är ett meddelande från Tai'ree Farsight som lämnades medan du var borta och tog hand om vuldren. Det hänvisar dig till henne på bytorget för att inleda avancerad träning.",al={"scribbled note","vad står det i meddelandet","jägarmeddelande"}},{q="Var utspelar sig uppdraget?",a="Uppdraget utspelar sig helt i Thendal Grove, en utpostbosättning på Zephras Isle.",al={"uppdragsområde","jägaruppdragets plats","var ligger thendal grove"}},{q="Vilket förhandskrav måste uppfyllas före uppdraget?",a="Du måste först slutföra 'Harmony in Balance' åt Rorian the Dayseeker och visa din grundläggande förmåga genom att ta hand om de aggressiva vuldren nära lunden.",al={"förhandskrav för the way of the hunter","hur låser man upp","föregående uppdrag"}},{q="Vad lär Tai'ree Farsight ut till nya jägare?",a="Tai'ree Farsight är din klasslärare. När du talar med henne får du en introduktion till grundprinciperna för spårning på ön och tillgång till grundläggande jägarförmågor och stridstekniker.",al={"vad gör tai'ree","varför prata med tai'ree"}}},fx={bb563a7d={q="Varför skickar Rorian the Dayseeker dig till Tai'ree Farsight?",a="Medan du var ute och hanterade hotet från vuldren lämnade byns jägartränare, Tai'ree Farsight, ett meddelande där hon särskilt bad att få tala med dig. Rorian förmedlar bara meddelandet och visar dig till platsen där hon väntar i Thendal Grove, så att du kan börja vässa dina stridsfärdigheter.",al={"varför rorian skickar dig","rorians motiv för jägarens väg","varför besöka tai'ree farsight"}}},fp="21,173,21.403.0,23.307.0,21.153.0,24.164.0,42.181.0,33.86.0,54.184.0,45.185.0"}
P.entries["quest:92483"] = {n="At Home in the Shadows",s="\"At Home in the Shadows\" är ett introduktionsuppdrag för skurkar på Zephras Isle. Efter att ha hjälpt Rorian the Dayseeker i Thendal Grove får blivande skurkar läsa en kallelse och träffa sin lokala klassmentor, Akeri Duskblade. Uppdraget markerar ögonblicket då unga skurkar går från allmänna bysysslor till seriös träning i smygande och strid.",h="\"At Home in the Shadows\" är ett introduktionsuppdrag för skurkar på Zephras Isle.",kw={"akeri duskblade","at home in the shadows","skurk uppdrag","skurk tränare","rorian the dayseeker","simple note","thendal grove","zephras isle"},ang={["class:Rogue"]="Uppdraget inleder din formella skurk träning på Zephras Isle och låter dig träffa Akeri Duskblade i vakttornet i Thendal Grove."},sec={{t="En skum inbjudan",b="När unga skurkar tar hand om grundläggande hot runt Thendal Grove väcker de Akeri Duskblades uppmärksamhet. Akeri är lundens skurk tränare. I stället för att öppet umgås i bosättningen låter Akeri Rorian the Dayseeker förmedla en enkel lapp. Rorian inser att mentorn, trots sitt misstänksamma sätt, förstår vilka praktiska färdigheter som krävs för att överleva utanför lundens skyddade gränser."},{t="Lektioner i vakttornet",b="Inne i byns vakttorn går Akeri Duskblade rakt på sak. Hen bedömer genast varje nykomlings fotarbete och uppmärksamhet och varnar för att slarviga steg utanför Thendal Grove leder raka vägen till en för tidig grav. När en skurk klarar Akeris granskning tar hen sitt första formella steg mot att bemästra smygande, precision och överlevnad på Zephras Isle."}},faq={{q="Vem ger uppdraget At Home in the Shadows?",a="Rorian the Dayseeker erbjuder uppdraget i Thendal Grove på Zephras Isle efter att du har slutfört \"Harmony in Balance\".",al={"vem startar at home in the shadows","uppdragsgivare at home in the shadows","rorian uppdrag"}},{q="Var hittar jag Akeri Duskblade?",a="Akeri Duskblade finns inne i byns vakttorn i Thendal Grove på Zephras Isle.",al={"akeri duskblade plats","var finns akeri duskblade","hitta akeri"}},{q="Vad är Simple Note som ges under uppdraget?",a="Simple Note är ett meddelande från Akeri Duskblade med en begäran om att få träffa lovande skurkar. Du måste läsa det innan du talar med Akeri för att slutföra målet.",al={"simple note zephras","vad är lappen","läs simple note"}},{q="Är uppdraget tillgängligt för alla klasser?",a="Nej, uppdraget är särskilt avsett för skurkar som lär sig sitt yrke i Thendal Grove.",al={"kan andra än skurkar göra uppdraget","är at home in the shadows endast för skurkar","klasskrav"}},{q="Vad lär Akeri Duskblade ut?",a="Akeri Duskblade är den lokala skurk tränaren i Thendal Grove och lär nybörjare smygande, list och svärdskonst när de inleder sin resa över Zephras Isle.",al={"akeri duskblades roll","vem är akeri","skurk tränare thendal grove"}},{q="Vilket förutsättningsuppdrag måste slutföras först?",a="Du måste först slutföra \"Harmony in Balance\" åt Rorian the Dayseeker innan hen ger dig Akeris lapp.",al={"förutsättningsuppdrag at home in the shadows","föregående uppdrag","lås upp at home in the shadows"}}},fx={["776f9cb3"]={q="Varför skickar Rorian the Dayseeker dig till Akeri Duskblade?",a="Efter att du visat din förmåga genom att hantera det lokala hotet från vuldren förmedlar Rorian helt enkelt en kallelse. Akeri Duskblade, lundens egen tränare för skurkar, bad särskilt att få träffa dig och lämnade ett meddelande till dig. Rorian förstår att en nybliven skurk behöver rätt handledning av någon som behärskar yrket och påpekar skämtsamt att du och den skumraskaktige Duskblade nog kommer att trivas ihop.",al={"rorians motiv","varför skicka till akeri","varför tala med akeri duskblade"}},["4629917d"]={q="Varför måste du gå i stället för att Rorian själv tar hand om Akeri?",a="Akeri Duskblade bad uttryckligen att få träffa dig, inte Rorian eller lundens väktare. Du har valt skurkens väg, och Akeri är den lokala mentor som ansvarar för att träna dem som verkar i skuggorna. Kallelsen ska pröva din uppmärksamhet, vässa dina instinkter och förbereda dig på att överleva utanför tryggheten i Thendal Grove.",al={"varför jag ska till akeri duskblade","varför akeri vill träffa mig","varför skurk tränaren vill ha mig"}}},fp="22,157,18.326.0,25.286.0,43.118.0,33.85.0,47.101.0,39.69.0,32.135.0,48.91.0"}
P.entries["quest:92484"] = {n="Embracing the Elements",s="Embracing the Elements är ett introduktionsuppdrag för schamaner i Thendal Grove på Zephras Isle. Rorian the Dayseeker ger uppdraget, som leder unga utövare till Windshaper Boro, byns schamantränare. Det introducerar den tysta sprickan mellan lokalbefolkningen och vindarnas elementandar.",h="Embracing the Elements är ett introduktionsuppdrag för schamaner i Thendal Grove på Zephras Isle.",kw={"embracing the elements","humming recall crystal","rorian the dayseeker","schaman","de fyra vindarnas andar","thendal grove","windshaper boro","zephras isle"},ang={["class:Shaman"]="Uppdraget är en lärlings första formella möte med Windshaper Boro. Det skildrar de elementära vindarnas tragiska tystnad och den livslånga strävan att återställa gemenskapen.",["faction:Horde"]="För hordresenärer som besöker Zephras Isle introducerar uppdraget öbornas särskilda utmaningar som elementbesvärjare, jämfört med fastlandets traditioner kring jord och andar."},sec={{t="En kallelse till elementen",b="Efter att ha hjälpt till att hantera vuldrenproblemet runt byn får blivande schamaner besök av Rorian the Dayseeker. Under tiden du var borta lämnade Windshaper Boro kvar en surrande återkallelsekristall som signalerar att den formella elementträningen ska börja i lundens mitt."},{t="De tysta vindarna",b="När du träffar Windshaper Boro berättar han om det svåra läget för den lokala schamanismen. De fyra vindarnas andar avbröt plötsligt kontakten för flera år sedan och övergav sin tidigare gemenskap. Zephras schamaner ägnar sig nu åt ingående studier av naturen och försöker genom hård träning överbrygga tystnaden och åter få andarna att tala."}},faq={{q="Vem ger uppdraget Embracing the Elements?",a="Uppdraget ges av Rorian the Dayseeker i Thendal Grove på Zephras Isle, direkt efter att du har hjälpt till att hantera det lokala vuldrenproblemet.",al={"uppdragsgivare för embracing the elements","vem startar embracing the elements"}},{q="Var finns Windshaper Boro?",a="Windshaper Boro finns nära mitten av Thendal Grove på Zephras Isle, där han är bosättningens schamantränare.",al={"windshaper boro plats","var finns boro","hitta windshaper boro"}},{q="Varför slutade elementandarna tala med folket här?",a="Enligt Windshaper Boro upphörde elementandarna plötsligt att tala och lämnade folket för flera år sedan. De lokala schamanerna förstår inte helt varför kontakten bröts, men de fortsätter sina studier i hopp om att återupprätta den förlorade förbindelsen.",al={"varför är vindarna tysta","de fyra vindarnas tysta andar","vad hände med vindandarna"}},{q="Vad är Humming Recall Crystal?",a="Humming Recall Crystal är ett föremål som Windshaper Boro lämnade kvar medan du var borta och hjälpte bosättningen. När du undersöker den visar det att du är redo att börja elementträningen under Boros vägledning.",al={"humming recall crystal","recall crystal zephras"}},{q="Vilket förhandsuppdrag leder till Embracing the Elements?",a="Uppdraget följer på Harmony in Balance, där du tar itu med vuldren som stör området runt omkring.",al={"förhandsuppdrag till embracing the elements","vad kommer före embracing the elements"}},{q="Vilken roll har Windshaper Boro i Thendal Grove?",a="Windshaper Boro är byns schamantränare och vägleder nya lärlingar i gemenskapen med elementen och studierna av naturen.",al={"vad gör boro","windshaper boros roll"}}},fx={["52185878"]={q="Varför skickar Rorian the Dayseeker dig till Windshaper Boro?",a="Medan du var ute och hanterade lundens problem med vuldren lämnade Windshaper Boro en återkallelsekristall i Rorians förvar, särskilt till dig. Rorian förmedlar bara kristallen och visar dig till Boro nära byns centrum, så att du kan börja lära dig att följa elementens väg.",al={"varför rorian vill att detta görs","varför boro-uppdraget från rorian","varför undersöka humming recall crystal"}}},fp="22,190,25.245.0,16.285.0,43.113.0,33.100.0,63.180.0,35.179.0,56.90.0,53.126.0"}
P.entries["quest:92485"] = {n="A Student of Nature",s="A Student of Nature markerar en blivande druids första formella utbildning på Zephras Isle. Efter att ha hjälpt till att återställa den lokala harmonin kallas de unga druiderna till Xyton Silverwind under Thendal Groves grenar. Det är porten till en djupare förståelse för balansen mellan öns växt- och djurliv.",h="A Student of Nature markerar en blivande druids första formella utbildning på Zephras Isle.",kw={"druid","folded parchment","rorian the dayseeker","thendal grove","vuldren","xyton silverwind","zephras isle"},ang={["class:Druid"]="Den här övergångsriten för dig direkt till Xyton Silverwind och inleder din livslånga utbildning i vildmarkens konster, huggtandens och grenens väg."},sec={{t="En kallelse från lunden",b="När störningarna som den överentusiastiska faunan orsakat har åtgärdats överlämnar Rorian the Dayseeker en personlig kallelse till de unga lärlingarna. Det vikta pergamentet, som den lokala mentorn Xyton Silverwind lämnat efter sig, bjuder in blivande druider att träda fram och ägna sig åt vildmarkens djupare mysterier. Det visar att lärlingarnas naturliga talanger har fångat lundens äldstes uppmärksamhet."},{t="Vävens väktare",b="Mötet med Xyton Silverwind på det stora trädets nedre våning i Thendal Grove förankrar den unga lärlingen i sitt kall. Silverwind ser Zephras Isles livfulla växt- och djurliv som en intrikat, levande väv som kräver ständig omvårdnad och vaksam balans. Att vandra huggtandens, klons, fjäderns och grenens väg kräver en långvarig mentors vägledning, och mötet markerar början på ett livslångt ansvar för naturen."}},faq={{q="Vem skickar spelaren till Xyton Silverwind?",a="Rorian the Dayseeker överlämnar det vikta pergamentet som leder dig till Xyton Silverwind efter att du hjälpt till att hantera problemen med vuldren i lundens närhet.",al={"vem ger a student of nature","uppdragsgivare","rorian"}},{q="Var finns Xyton Silverwind?",a="Xyton Silverwind finns på bottenvåningen i det stora trädet i Thendal Grove, precis bakom Rorian the Dayseeker på Zephras Isle.",al={"xyton silverwinds plats","var finns xyton","druidtränarens plats"}},{q="Vad är syftet med det här uppdraget?",a="Uppdraget presenterar de unga druiderna för sin klasslärare, Xyton Silverwind, som är deras främsta lärare och vägledare i att bevara Zephras Isles naturliga balans.",al={"varför göra uppdraget","uppdragets mål","start på druidutbildningen"}},{q="Vad lär Xyton Silverwind de unga druiderna om Zephras Isle?",a="Silverwind lär ut att öns växt- och djurliv bildar en skör, sammanlänkad väv som kräver aktiv omvårdnad och balans genom huggtandens, klons, fjäderns och grenens disciplin.",al={"vad säger xyton","naturens balans på zephras","druidens roll på zephras"}},{q="Vilket förkunskapskrav måste uppfyllas innan du får kallelsen?",a="Lärlingarna måste först slutföra Harmony in Balance åt Rorian the Dayseeker och ta hand om den oregerliga vuldrenpopulationen innan de får Silverwinds meddelande.",al={"förkunskapsuppdrag","föregående uppdrag","före a student of nature"}},{q="Vad står det i Folded Parchment?",a="Det vikta pergamentet är ett direkt meddelande från Xyton Silverwind, där han ber den lovande unga druider att söka upp honom för vidare utbildning under det stora trädets krona.",al={"meddelande på vikt pergament","silverwinds meddelande","vad står på pergamentet"}}},fx={caa97f7a={q="Varför skickar Rorian the Dayseeker dig till Xyton Silverwind?",a="Medan du var ute och hanterade det lokala hotet från vuldren lämnade lundens druidtränare, Xyton Silverwind, ett särskilt meddelande till dig. Rorian agerar mellanhand för att se till att lovande noviser får rätt undervisning. Han uppmanar dig att följa Silverwinds råd, så att du kan bemästra druidkonsten och bevara naturens balans.",al={"rorians motiv","varför skicka mig till silverwind","varför rorian ger dig folded parchment"}}},fp="19,323,24.408.0,22.428.0,41.149.0,34.139.0,34.175.0,66.196.0,66.153.0,46.175.0"}
P.entries["quest:92489"] = {n="Power Overwhelming",s="Power Overwhelming är ett uppdrag från High Sorcerer Andromath i Stormwind City där du ska hjälpa de tillbakadragna Kirin Tor. Du skickas till den förstörda staden Dalaran för att hejda ett farligt utbrott av okontrollerad arkansk energi, som har tagit formen av en Mana Elemental.",h="Power Overwhelming är ett uppdrag från High Sorcerer Andromath i Stormwind City där du ska hjälpa de...",kw={"arkansk energi","archimonde","dalaran","high sorcerer andromath","kirin tor","mana elemental","power overwhelming","stormwind"},ang={["class:Mage"]="Magiker känner samhörighet med Kirin Tor och förstår det allvarliga hotet från instabila arkaniska manifestationer som härjar i Dalaran.",["faction:Alliance"]="Kirin Tor är sedan länge allierade till Alliansen, och Stormwind vill stärka banden genom att hjälpa Dalaran under stadens utsatta återuppbyggnad."},sec={{t="En stad i avskildhet",b="Efter att ärkedemonen Archimonde ödelade Dalaran under det tredje kriget drog sig Kirin Tor undan. De överlevande magikerna hade en gång välkomnat lärda och trollkarlar från hela världen, men har blivit hemlighetsfulla, tillbakadragna och djupt misstänksamma mot främlingar. De arbetar outtröttligt bakom stängda gränser för att återuppbygga sin förstörda stad."},{t="Okontrollerade arkaniska krafter",b="De senaste försöken att återställa Dalaran till dess forna glans har stött på allvarliga problem. Farliga läckor av instabil arkan energi har vuxit bortom kontroll och samlats till varelser av ren mana. High Sorcerer Andromath fruktar att Dalaran kan falla offer för inre oro eller överge sina historiska band till Alliansen. Därför skickade han hjältar från Stormwind för att hejda Mana Elemental och påminna Kirin Tor om sina trogna allierade."}},faq={{q="Vad är uppdraget Power Overwhelming?",a="Power Overwhelming är ett uppdrag från High Sorcerer Andromath i Stormwind City. Du ska hjälpa Kirin Tor att återuppbygga Dalaran genom att dräpa en oregerlig Mana Elemental.",al={"vad är power overwhelming","uppdraget power overwhelming","dalaran mana elemental uppdrag"}},{q="Vem ger uppdraget?",a="High Sorcerer Andromath, en framstående trollkarl i Stormwind City, erbjuder uppdraget till hjältar som är villiga att resa till Dalaran och hjälpa Kirin Tor.",al={"vem ger power overwhelming","andromaths uppdrag","var startar man power overwhelming"}},{q="Varför är Dalaran så tillbakadraget och misstänksamt?",a="Ärke­demonen Archimonde ödelade Dalaran under det tredje kriget. Kirin Tor försöker återuppbygga sitt hem, men katastrofen har gjort de överlevande magikerna tillbakadragna och vaksamma mot främlingar.",al={"varför är dalaran avskilt","vad hände med dalaran","varför är magikerna i dalaran misstänksamma"}},{q="Vad orsakar oron i Dalaran?",a="Under återuppbyggnaden av staden fick Kirin Tor svårt att hålla ett utbrott av okontrollerad arkan energi i schack. Energin samlades till fientliga manaelementaler.",al={"arkanskt utbrott i dalaran","varför finns manaelementaler i dalaran","vad händer i dalaran"}},{q="Vad är Mana Elemental?",a="Mana Elemental är en manifestation av ren, obunden arkan kraft. Dess uppdykande visar att den arkaniska störningen som hotar Dalaran är mycket starkare än de första rapporterna antydde.",al={"vad är mana elemental","dalarans elementallore","varelse av ren mana"}},{q="Varför skickar Stormwind hjälp till Dalaran?",a="Kirin Tor har länge varit viktiga allierade till Alliansen. High Sorcerer Andromath vill se till att Dalaran inte faller i kaos eller lämnar Alliansen under sin utsatta tid.",al={"varför hjälper stormwind dalaran","varför bryr sig alliansen om dalaran"}}},fp="18,189,19.248.0,21.415.0,37.155.0,21.101.0,41.133.0,43.118.0,27.156.0,41.171.0"}
P.entries["quest:92514"] = {n="Welcome to Shen'dar Village",s="Welcome to Shen'dar Village presenterar resenärer för Shen'dar Villages viktigaste personer och lokala förhållanden. När nykomlingar anländer hänvisas de till byns Windshaper-äldste och värdshusvärd innan de hjälper till med akuta hot, som traktens banditer.",h="Welcome to Shen'dar Village presenterar resenärer för Shen'dar Villages viktigaste personer och lokala...",kw={"banditer","coriella calmbreeze","high order","illaya amberwind","shen'dar village","andeberörd","welcome to shen'dar village","windshapers"},ang={["class:Shaman"]="Som någon som är i samklang med andar och element märker du snart den svaga statiska laddningen i luften som kännetecknar andeberörda Windshapers som Illaya Amberwind i Shen'dar Village."},sec={{t="Första stegen i Shen'dar",b="När resenärer anländer till Shen'dar Village uppmuntras de att lära känna bosättningens viktigaste invånare innan de tar sig an lokala uppgifter. Nykomlingar med andeberörda egenskaper hänvisas till Elder Illaya Amberwind nära bytorget och till Coriella Calmbreeze på byns värdshus för logi och förnödenheter. Välkomnandet hjälper besökarna att förstå bosättningens känsliga sociala dynamik innan de griper till vapen."},{t="Fraktioner och oroligheter vid gränsen",b="Bakom Shen'dar Villages lugna yta finns politiska motsättningar mellan de andebundna Windshapers och High Order. Även om de ideologiska tvisterna mellan fraktionerna blossar upp i hela regionen håller invånarna i Shen'dar sina meningsskiljaktigheter hövliga. Båda grupperna inser att smågräl får stå tillbaka för akuta överlevnadsfrågor, inte minst hotet från banditer som tränger sig in i området."}},faq={{q="Vad är syftet med uppdraget Welcome to Shen'dar Village?",a="Welcome to Shen'dar Village är ett introduktionsuppdrag där nyanlända får lära känna Shen'dar Villages viktigaste personer. Innan resenärerna får i uppgift att hantera lokala problem som banditplågan ser det lokala ledarskapet till att de träffar byns Windshaper-äldste och värdshusvärd.",al={"vad är uppdraget shen'dar village","översikt över welcome to shen'dar","vad gör man i shen'dar village"}},{q="Vem är Illaya Amberwind?",a="Illaya Amberwind är Shen'dar Villages Windshaper-äldste. Hon finns nära byns mitt och vägleder dem som är känsliga för andarnas närvaro, mitt i de större politiska motsättningarna.",al={"vem är illaya amberwind","var finns illaya amberwind","windshaper-äldste i shen'dar"}},{q="Vem är Coriella Calmbreeze?",a="Coriella Calmbreeze driver det lokala värdshuset i Shen'dar Village. Hon erbjuder resenärer, äventyrare och lokalbor välbehövligt logi, vila och förnödenheter.",al={"vem är coriella calmbreeze","värdshusvärd i shen'dar village","var ligger värdshuset i shen'dar village"}},{q="Vilka är Windshapers?",a="Windshapers är andeberörda utövare som känns igen på den påtagliga statiska laddningen i luften omkring dem. Trots de pyrande spänningarna mellan Windshapers och High Order lever fraktionerna sida vid sida i Shen'dar Village, med större hot i åtanke.",al={"vad är windshapers","lore om andeberörda windshapers","high order mot windshapers"}},{q="Vad ligger bakom spänningarna mellan High Order och Windshapers?",a="High Order är en lokal makt eller fraktion som för närvarande befinner sig i politisk konflikt med Windshapers. Trots sina ideologiska meningsskiljaktigheter håller företrädare och invånare i Shen'dar Village fredliga relationer för att kunna hantera mer akuta gemensamma bekymmer.",al={"vad är high order","konflikt i shen'dar village","spänningar mellan high order och windshapers"}},{q="Vilka problem står Shen'dar Village inför just nu?",a="Utöver den olustiga filosofiska konflikten mellan Windshapers och High Order hotas bosättningen omedelbart av lokala banditer som härjar i trakten.",al={"problem i shen'dar village","vilket hot står shen'dar village inför","banditer i shen'dar village"}}},fp="27,136,23.361.0,29.291.0,61.234.0,24.155.0,27.112.0,24.221.0,63.168.0,51.146.0"}
P.entries["quest:92515"] = {n="The Problem With Prideclaws",s="The Problem With Prideclaws handlar om det växande hotet från vilda prideclaw-rovdjur i Shen'dar Highlands. Medan bosättningarna redan kämpar mot banditer och kultister skyddar jakten på de allt fler bestarna utsatta bybor och ger användbara skinn åt samhället.",h="The Problem With Prideclaws handlar om det växande hotet från vilda prideclaw-rovdjur i Shen'dar Highlands.",kw={"jakt för att minska antalet","prideclaw-skinn","prideclaws","shen'dar","shen'dar highlands","the problem with prideclaws","bygränser"},ang={["class:Hunter"]="Att spåra och jaga rovdjur som tränger sig på bosättningar hör till vardagen för erfarna jägare, men så här många prideclaws kräver respekt."},sec={{t="Ett växande vildmarkshot",b="Kullarna kring Shen'dar Highlands är farliga. Där finns kringströvande banditer och vettlösa kultister, och dessutom blir prideclaws allt fler. De här våldsamma bestarna har börjat närma sig byns utkanter. De blir djärvare när deras revir växer och utgör snart en omedelbar fara för lokalbefolkningen."},{t="Säkra gränserna",b="För att undvika en katastrof innan rovdjuren tar husdjur eller barn har byborna ordnat en jakt för att minska antalet prideclaws. Jakten fyller två syften: rovdjuren hålls borta från byns gränser, och deras tåliga skinn kan användas av hantverkarna till viktiga varor för byn."}},faq={{q="Vad är prideclaws?",a="Prideclaws är rovdjur som lever i kullarna och högländerna i Shen'dar. De är kända för sitt våldsamma temperament och sina värdefulla skinn. När de blir för många utgör de ett allt större hot mot bosättningarna i närheten.",al={"vad är prideclaws","prideclaws historia","prideclaws"}},{q="Var finns prideclaws?",a="Prideclaws strövar omkring i kullarna i Shen'dar Highlands. De blir allt fler och har börjat närma sig den lokala byns gränser, så att de nu kommer farligt nära bebodda områden.",al={"var finns uppdraget","var lever prideclaws","prideclaws plats"}},{q="Varför behöver byn minska antalet prideclaws?",a="Banditer och galna kultister hotar redan trakten, och ett överskott av prideclaws hotar byns gränser. Jakten ska förebygga att barn eller husdjur faller offer för de framryckande rovdjuren.",al={"varför döda prideclaws","varför minska antalet prideclaws","fara för byn"}},{q="Vad ska hända med skinnen från prideclaws?",a="Byhantverkarna använder skinnen till praktiska varor och förnödenheter. På så vis blir den nödvändiga jakten en källa till nyttiga resurser för bosättningen.",al={"vad händer med skinnen","användning av prideclaw-skinn","skinnens syfte"}},{q="Vilka andra hot finns i kullarna runtomkring?",a="Förutom de vilda prideclaws som stryker omkring i kullarna måste den lokala bosättningen hantera kringströvande banditer och oberäkneliga kultister. Det sätter byns säkerhet och försvar under hård press.",al={"andra hot i shendar","vad mer hotar byn","lokala hot"}},{q="Hur ser lokalbefolkningen på prideclaws?",a="Bybon som ansvarar för uppgiften tycker att prideclaws är ganska söta när de betraktas på tryggt avstånd bakom beväpnade vakter, men inser att byns säkerhet måste värnas innan en tragedi inträffar.",al={"vem ger uppdraget the problem with prideclaws","uppdragsgivarens tankar"}}},fp="27,188,21.276.0,20.237.0,20.157.0,33.131.0,48.159.0,43.74.0,48.109.0,38.162.0"}
P.entries["quest:92516"] = {n="Hippogryph Harassment",s="Hippogryph Harassment är ett lokalt uppdrag som gäller en aggressiv flock vilda hippogryfer med bo sydost om Shen'dar Village. Resenärer på vägen i närheten har ofta attackerats av de revirhävdande bestarna i Shen'dar Highlands. För att säkra passagen kallas äventyrare in för att decimera flockens ungar, beskyddare och ledande matriark.",h="Hippogryph Harassment är ett lokalt uppdrag som gäller en aggressiv flock vilda hippogryfer med bo sydost om...",kw={"hippogryf","hippogryph harassment","hippogryfmatriark","hippogryfbeskyddare","hippogryfunge","kalimdor","matriark","shen'dar highlands","shen'dar village"},ang={["class:Druid"]="Druider strävar efter att bevara harmonin med det vilda och ser denna decimering som en sorglig nödvändighet för att återställa balansen efter att bestarna börjat jaga resenärer.",["class:Hunter"]="Jägare förstår rovinstinkterna hos flygande bestar och hierarkin i ett vilt bo. De vet att det effektivaste sättet att krossa flockens aggression är att döda matriarken.",["race:NightElf"]="Night Elf hyser en djup andlig vördnad för hippogryfer som Elunes heliga följeslagare. Därför är det en sorgsen uppgift att decimera även en aggressiv vild flock när vildmarken kolliderar med resenärernas säkerhet."},sec={{t="Fara på vägen",b="Resenärer på vägarna nära Shen'dar Village möter ett växande hot från skyn. En vild flock hippogryfer har nyligen tagit det karga området sydost om bosättningen i besittning och gjort Shen'dar Highlands till sitt aktiva häckningsområde. Hippogryfer är kända över hela Kalimdor som ädla bestar som ibland knyter band med alviska ryttare, men otämjda flockar försvarar sitt revir med våldsam kraft. Varje vagn och ensam resenär på stigarna nedanför har blivit mål för luftangrepp. Det stör viktiga resor och riskerar att isolera byn om varelserna lämnas åt sig själva."},{t="Decimera flocken",b="För att undanröja det omedelbara hotet måste häckningsområdet i Shen'dar Highlands angripas direkt. För att återställa lugnet på huvudvägarna måste flockens snabba tillväxt hejdas genom att dess yngre medlemmar fälls innan de blir vuxna, och genom att ta sig förbi de vaksamma hippogryfbeskyddarna som bevakar området. Den verkliga störningen kommer dock från flockens matriark, vars ledarskap styr attackerna mot förbipasserande. Först när boet angrips och matriarken fälls kan vägarna åter bli säkra för resenärer."}},faq={{q="Varför attackerar hippogryferna resenärer nära Shen'dar Village?",a="Hippogryferna har nyligen etablerat ett aktivt häckningsområde sydost om Shen'dar Village i Shen'dar Highlands. Eftersom flocken slog sig ner alldeles intill den huvudsakliga färdvägen trakasserar de revirhävdande varelserna aggressivt alla som kommer i närheten, för att försvara sin nytagna kull och sina jaktmarker.",al={"varför attackerar hippogryfer","varför är hippogryfer fientliga","orsaken till hippogryftrakasserier"}},{q="Var håller hippogryfflocken till?",a="Flocken häckar sydost om Shen'dar Village i Shen'dar Highlands. Deras boplatser och jaktmarker överblickar vägen genom området, där ungar, beskyddare och flockens matriark samlas bland klippor och bergsryggar.",al={"var finns hippogryferna","hippogryfernas plats","var ligger shen'dar highlands"}},{q="Vilka hippogryfer måste dödas för att slutföra uppdraget?",a="För att hejda flockens aggressiva beteende och åter göra vägen säker måste äventyrare decimera åtta hippogryfunger, sex robusta hippogryfbeskyddare och den mäktiga hippogryfmatriark som styr boet i Shen'dar Highlands.",al={"vilka hippogryfer ska jag döda","mål för hippogryftrakasserier","hippogryfuppdragets mål"}},{q="Vem leder hippogryfflocken?",a="Flocken leds av en mäktig hippogryfmatriark som håller till i Shen'dar Highlands. Hon styr boet och övervakar försvaret av häckningsområdet sydost om Shen'dar Village. Hennes död är nödvändig för att bryta flockens grepp om vägen.",al={"vem leder hippogryferna","hippogryfmatriark","hippogryf-boss"}},{q="Varför måste hippogryfungarna decimeras?",a="Hippogryfungarna står för flockens framtida tillväxt och fortsatta expansion. Genom att decimera deras antal tillsammans med de vuxna beskyddarna ser äventyrare till att boet inte snabbt kan återhämta sin styrka eller upprätta ett permanent skräckvälde på de lokala vägarna.",al={"varför döda hippogryfungar","varför rikta in sig på unga hippogryfer","decimera hippogryfungar"}},{q="Är hippogryferna tama eller allierade med någon?",a="Nej, det här är helt vilda, otämjda varelser som på egen hand har etablerat ett bo i Shen'dar Highlands. Till skillnad från de disciplinerade riddjur som Night Elf föder upp med omsorg betraktar den här förvildade flocken alla humanoider som passerar som inkräktare eller byte på deras revir.",al={"är hippogryferna tama","är det här night elf-hippogryfer","vänliga hippogryfer"}},{q="Vilket hot utgör hippogryferna mot den lokala bosättningen?",a="Flocken har etablerat bon med utsikt över vägen som leder sydost från Shen'dar Village. Genom att störtdyka ner och terrorisera förnödenhetsvagnar, budbärare och kringvandrande resenärer hotar de aggressiva bestarna att stänga av säkra landvägar och isolera byn från de omgivande länderna.",al={"vilket hot utgör hippogryfer","fara för shen'dar village","varför är hippogryfer ett problem"}}},fp="21,267,17.465.0,17.357.0,66.235.0,38.181.0,53.165.0,42.231.0,41.232.0,49.257.0,62.250.0"}
P.entries["quest:92517"] = {n="The Criminal Element",s="The Criminal Element handlar om att slå till mot Highlands Bandits och deras ledare, ”Badwind” Bennic, som håller till i en dold grotta bakom ett vattenfall i Shen'dar Highlands. Eftersom de lokala styrkorna är överväldigade av en hotfull kults nyliga ankomst krävs hjälp utifrån för att oskadliggöra Bennic och störa det laglösa bandet.",h="The Criminal Element handlar om att slå till mot Highlands Bandits och deras ledare, ”Badwind” Bennic, som...",kw={"badwind bennic","bennic","kult","highlands bandits","shen'dar highlands","the criminal element","vattenfallsgrotta"},ang={["class:Rogue"]="Att hålla till i en dold grotta bakom ett vattenfall är klassiskt rövartrick, men ”Badwind” Bennic och hans följe saknar finessen och diskretionen som krävs för att undgå lokalbefolkningens vedergällning."},sec={{t="Laglösa bakom vattenfallet",b="I Shen'dar Highlands har ett rövarnäste som kallas Highlands Bandits befäst sig i en dold grotta bakom ett vattenfall i norr. De hänsynslösa rövarna leds av den ökände ”Badwind” Bennic och var redan en ständig plåga för lokalbefolkningen innan en gåtfull kult anlände till höglandet. Därefter övergick deras laglöshet i ren terror. De lokala försvararna är hårt ansatta och kan inte avvara några styrkor, så äventyrare får i uppdrag att ta sig in i vattenfallsfästet, bryta upp bandet och oskadliggöra Bennic."},{t="En förändring i skuggorna",b="Att oskadliggöra ”Badwind” Bennic slår visserligen sönder rövarnas fäste och ger tillfällig lättnad, men det skapar en ny strategisk komplikation. De lokala myndigheterna oroar sig för att de överlevande laglösa ska söka skydd hos den närliggande kulten när deras ledare är borta. Om desperata, erfarna stråtrövare ansluter sig till kulten riskerar den redan alarmerande regionala hotbilden att växa ytterligare."}},faq={{q="Vem är ”Badwind” Bennic?",a="”Badwind” Bennic är ledaren för Highlands Bandits, som håller till i en dold grotta bakom ett vattenfall i Shen'dar Highlands. Hans gäng har länge plågat området och blivit ett ännu större hot under den senaste tidens oroligheter i regionen.",al={"vem är badwind bennic","bennic","badwind"}},{q="Var gömmer sig Highlands Bandits?",a="Rövarna har sitt näste i en avskild grotta bakom ett vattenfall i norr i Shen'dar Highlands.",al={"var finns rövarna","rövargrottans plats","vattenfallsgrotta"}},{q="Vad är kulten som nämns i området?",a="Kulten är en nyare, oroväckande fraktion vars anhängare samlas i Falaath Village i söder och blir allt fler. Rövarna var verksamma långt innan kulten anlände, men dess närvaro har förvärrat faran för lokalbefolkningen. Det finns en kvarstående oro för att överlevande rövare ska söka skydd och stärka kulten när deras ledarskap har brutits.",al={"vilken kult","koppling till kulten","vem är kulten"}},{q="Varför kan inte de lokala styrkorna själva ta hand om rövarna?",a="De lokala styrkorna har inte manskap nog att rensa ut rövarna samtidigt som de hanterar den framväxande kulten. Att oskadliggöra Bennic och skingra hans gäng undanröjer ett aktivt hot mot regionen.",al={"varför döda rövarna","rövarproblemet"}},{q="Vad händer med rövarna när Bennic har besegrats?",a="Bennic faller och hans gömställe skingras, men oron kvarstår för att överlevande laglösa ska vända sig till den närliggande kulten för skydd och öka kultisternas redan alarmerande antal.",al={"vad händer med överlevande rövare","dog alla rövare"}},{q="Var utspelar sig den här konflikten?",a="Shen'dar Highlands är den oländiga region där Highlands Bandits strövar omkring och håller till i sitt dolda vattenfallsfäste.",al={"var ligger shendar highlands","shen'dar highlands"}}},fp="20,221,24.398.0,22.278.1,24.206.0,39.95.0,39.323.0,53.187.0,53.159.0,36.100.0"}
P.entries["quest:92519"] = {n="Ward Restocking",s="Ward Restocking är en uppgift i Arathi Highlands där resenärer hjälper Doctor Gregory Victor i Hammerfall. När utpostens sjukstuga börjar få slut på viktiga elixir skickas kurirer för att hämta försummade förråd från Apothecary Jorells laboratorium vid Go'Shek Farm.",h="Ward Restocking är en uppgift i Arathi Highlands där resenärer hjälper Doctor Gregory Victor i Hammerfall.",kw={"apothecary jorell","arathi highlands","doctor gregory victor","go'shek farm","hammerfall","packaged tonics","ward restocking"},ang={["faction:Horde"]="Utposten Hammerfall är beroende av regelbundna leveranser av toniker och medicin för att hålla sina soldater, försvarare och resenärer på benen mot hoten i Arathi Highlands.",["race:Undead"]="Apothecary Jorell står för Royal Apothecary Societys avlägsna närvaro i Arathi, men hans oberäkneliga beteende och giftiga experiment vid Go'Shek Farm gör även hans allierade frustrerade."},sec={{t="Brist på förråd i sjukstugan",b="I Horde-bosättningen Hammerfall i Arathi Highlands vårdar Doctor Gregory Victor de sårade och sjuka i utpostens sjukstuga. För att hålla sjukstugan igång krävs en stadig tillgång på läkemedel, motgifter och elixir, som vanligtvis tillhandahålls av Forsaken-apotekaren i närheten. När leveranserna uteblir måste Victor be dugliga resenärer att rycka in och fylla på klinikens förråd."},{t="Enstöringen vid Go'Shek Farm",b="Apothecary Jorell utför sina alkemiska experiment i en trång, dåligt ventilerad koja vid Go'Shek Farm, söder och väster om Hammerfall. Enligt Doctor Victor är Jorells frånvaro inget ovanligt; den excentriske Forsaken-kemisten är ökänd för att antingen strunta i sina officiella plikter eller av misstag duka under för sina egna giftiga brygder. Kurirer som skickas för att hämta de förpackade tonikerna förväntas hitta medicinen där, oavsett om Jorell är på plats."}},faq={{q="Vem erbjuder uppdraget Ward Restocking?",a="Doctor Gregory Victor, traumakirurgen som ansvarar för traumaavdelningen och sjukstugan i Hammerfall, ger uppgiften till pålitliga resenärer. Han behöver pålitliga kurirer som kan hämta medicinska förråd när de vanliga leveransvägarna sviker.",al={"vem ger ward restocking","uppdragsgivare för ward restocking","doctor gregory victor uppdrag"}},{q="Var håller Apothecary Jorell till?",a="Apothecary Jorell arbetar i en liten koja vid Go'Shek Farm, söder och en bit väster om Hammerfall längs vägen i Arathi Highlands.",al={"var finns apothecary jorell","jorells laboratorium plats","var hittar man toniker"}},{q="Varför skickar Doctor Gregory Victor dig till Go'Shek Farm?",a="Doctor Gregory Victor skickar resenärer till Go'Shek Farm eftersom Apothecary Jorell inte har levererat en brådskande efterfrågad låda med motgifter och elixir till sjukstugan i Hammerfall.",al={"varför åka till goshek farm","vad finns vid goshek farm"}},{q="Vilka förråd behövs till sjukstugan?",a="Du måste hämta en låda med Packaged Tonics, som innehåller motgifter och elixir tillverkade av Apothecary Jorell, för att fylla på de sinande förråden i Hammerfalls sjukstuga.",al={"vad är packaged tonics","vilka föremål ska hämtas"}},{q="Varför har Apothecary Jorell inte levererat förråden själv?",a="Doctor Gregory Victor misstänker att Jorell antingen har förgiftat sig själv igen när han blandat brygder i sin dåligt ventilerade verkstadsk koja eller helt enkelt försummat sina skyldigheter gentemot sjukstugan.",al={"vad hände med jorell","är jorell död","varför levererade jorell inte"}},{q="Vart ska förråden levereras?",a="När lådan med toniker har hämtats vid Go'Shek Farm ska den föras tillbaka till Doctor Gregory Victor på sjukstugan i Hammerfall.",al={"vart ska tonikerna","vem lämnar man ward restocking till"}}},fp="15,140,22.273.0,27.333.0,37.154.0,35.137.0,56.170.0,38.166.0,60.161.0,37.102.0"}
P.entries["quest:92528"] = {n="Among the Faithful",s="Among the Faithful följer en undercoverutredning av Al'Akirs trogna, som är stationerade i Falaath Village i Shen'dar Highlands. Genom att smälta in som en möjlig rekryt får en äventyrare veta att kultens högsta ledning samlas i hemlighet för att snart inleda en offensiv mot lokala bosättningar och utposter.",h="Among the Faithful följer en undercoverutredning av Al'Akirs trogna, som är stationerade i Falaath Village i...",kw={"al'akir","among the faithful","falaath village","lorthuna","shen'dar highlands","skypriest aanders","västra vakttornet","vindherren"},ang={["class:Priest"]="Heliga präster och skuggpräster följer välkända trosläror, men kultisterna i Falaath Village leds av Skypriests som är hängivna Al'Akir Vindherren och kanaliserar stormens ursprungliga kraft.",["class:Shaman"]="Tillbedjan av Al'Akir och kultens herravälde över stormkrafter har en direkt koppling till de elementära krafter som schamaner vördar och förhandlar med."},sec={{t="Infiltrationen av Falaath Village",b="En infiltratör utger sig för att vara en ivrig rekryt bland Al'Akirs trogna och tar sig in i Falaath Village i Shen'dar Highlands. Kultisterna firar öppet att de blir fler och hävdar att deras gemensamma hängivenhet ger själva stormen form och ursinne. Nykomlingar skickas vanligtvis direkt till Skypriest Aanders för granskning, men ett oväntat möte på det lokala värdshuset stör de vanliga rutinerna."},{t="Den hemliga gästen",b="Aanders är upptagen på stadens norra sida med att ta emot en förnäm gäst, så den nya rekryten kan vandra runt obevakad. Genom att hålla låg profil och tjuvlyssna på bosättningens ledning avslöjar spanaren kultens verkliga, omedelbara ambition: en samordnad militär offensiv genom Shen'dar Highlands."},{t="Lorthunas plan",b="Den mystiska gästen på värdshuset visar sig vara Lorthuna själv, hela kultens högsta befälhavare. Hennes personliga närvaro förebådar ett aggressivt anfall riktat inte bara mot Shen'dar Village, utan även mot det västra vakttornet. Byn är ett tydligt befolkningscentrum, men att rikta in sig på det avlägsna utkikstornet förbryllar de lokala spejarna och antyder att kulten döljer motiv bakom sin stormdrivna offensiv."}},faq={{q="Vilka är Al'Akirs trogna?",a="Al'Akirs trogna är en kult som tillber Vindherren Al'Akir. Deras medlemmar håller till kring Falaath Village i Shen'dar Highlands, brukar stormmagi och lyder ytterst under en person vid namn Lorthuna.",al={"vilka är alakirs trogna","vad är det här för kult","alakirkulten"}},{q="Vem är Skypriest Aanders?",a="Skypriest Aanders är en högt uppsatt officer inom kulten i Falaath Village och ansvarar för att bedöma och ta in nya rekryter. Under infiltrationen var han upptagen med att ta emot en viktig gäst på byns värdshus.",al={"vem är skypriest aanders","aanders","kultens rekryteringsansvarige"}},{q="Vem är Lorthuna?",a="Lorthuna är den högsta ledaren för hela Al'Akir-kulten. Hennes direkta, hemliga närvaro på värdshuset i Falaath Village visar att kulten planerar en förestående offensiv på högsta nivå i höglandet.",al={"vem är lorthuna","kultledaren lorthuna","gästen på värdshuset"}},{q="Varför riktar kulten in sig på det västra vakttornet?",a="Kulten planerar ett samtidigt anfall mot både Shen'dar Village och det västra vakttornet. Att anfalla byn är strategiskt begripligt, men varför de riktar in sig på den obetydliga utkiksposten vid vakttornet är fortfarande en gåta för höglandets försvarare.",al={"varför anfalla vakttornet","kulten och västra vakttornet","kultens mål"}},{q="Var utspelar det sig?",a="Falaath Village är en bosättning i Shen'dar Highlands som nu fungerar som en viktig bas och uppmarschplats för Al'Akirs trogna och deras nya rekryter.",al={"var ligger falaath village","falaath villages läge"}},{q="Vad har kulten för avsikter i Shen'dar Highlands?",a="Kulten vill utöka sitt inflytande och släppa lös stormmagi i Shen'dar Highlands. Under Lorthunas ledning är det omedelbara målet ett anfall mot både Shen'dar Village och det västra vakttornet.",al={"vad har kulten för mål i shendar highlands","kultens planer i shendar"}}},fp="18,227,28.348.0,16.267.1,17.364.2,32.176.0,25.204.0,16.188.0,49.208.0,27.137.0,57.197.0"}
P.entries["quest:92529"] = {n="Falaath Village",s="Falaath Village är en samlingsplats för ångerfulla shen'dorei som vill återvinna vindfursten Al'Akirs gunst. Märkta rekryter reser från Shen'dar Village för att anmäla sig hos Missionary Jasaan och ansluta sig till sina trosfränder.",h="Falaath Village är en samlingsplats för ångerfulla shen'dorei som vill återvinna vindfursten Al'Akirs gunst.",kw={"al'akir","falaath village","akirs märke","missionary jasaan","sania silverstream","shen'dar village","shen'dorei","vindfursten"},ang={["class:Shaman"]="Medan shamaner söker harmoni med elementandar, närmar sig kultister som är hängivna vindfursten Al'Akir genom botgöring och religiös hängivenhet för att återta de övergivna vindarna.",["race:Skyborne"]="För shen'dorei som vill återställa sitt band till vindarna innebär anslutningen till de trogna i Falaath Village en gemensam botgöring för att återvinna Al'Akirs förlorade gunst."},sec={{t="Ånger inför vindfursten",b="I Shen'dar Village beklagar Sania Silverstream att hennes folk blev högmodigt och tog luftens överflöd för givet, tills vindandarna övergav dem åt stagnation. För att gottgöra detta fall från nåden märks ångerfulla rekryter och skickas till Falaath Village, där de söker gemenskap med andra shen'dorei som tror att endast ångerfulla handlingar kan återställa vindens gunst."},{t="Uppdraget i Falaath",b="När de når utkanten av Falaath Village med Akirs märke blir de invigda mottagna av Missionary Jasaan. Jasaan ser ankomsten av nya akolyter som ett tecken på välsignelse från de fyra vindarna och välkomnar alla som kommer för att bada i Al'Akirs elementära nåd."}},faq={{q="Vad är uppdraget Falaath Village?",a="Falaath Village är ett introduktionsuppdrag där rekryter märkta av Sania Silverstream reser från Shen'dar Village för att anmäla sig hos Missionary Jasaan och söka gemenskap med vindfurstens trogna dyrkare.",al={"vad är uppdraget falaath village","översikt över falaath village","uppdraget falaath village"}},{q="Vem är Missionary Jasaan?",a="Missionary Jasaan är en akolyt stationerad nära ingången till Falaath Village som välkomnar nya rekryter, skickade dit av syster Sania Silverstream för att bada i Al'Akirs välsignelser.",al={"vem är missionary jasaan","jasaan-lore","missionären i falaath"}},{q="Vem är Sania Silverstream?",a="Sania Silverstream är en av de trogna i Shen'dar Village som hänvisar blivande anhängare till Falaath Village och ger Akirs märke till nya rekryter.",al={"vem är sania silverstream","sania-lore","syster sania"}},{q="Varför dyrkar shen'dorei Al'Akir?",a="Anhängarna tror att deras folk blev självbelåtet och högmodigt och tog vindarnas överflöd för givet, tills andarna övergav dem. Genom ångerfulla handlingar dyrkar de vindfursten Al'Akir för att återvinna vindens välsignelse.",al={"varför dyrka al'ak ir","dyrkan av vindfursten al'akir","vem är vindfursten"}},{q="Vad är Akirs märke?",a="Akirs märke är ett tecken som Sania Silverstream ger i Shen'dar Village för att visa att en invigd är rekryt bland de trogna innan hen går in i Falaath Village.",al={"vad är akirs märke","förlorade akirs märke","rekryternas märke"}},{q="Vilka är shen'dorei som nämns i uppdraget?",a="De shen'dorei som Sania nämner är alver som kämpar mot andlig stagnation efter att vindandarna dragit tillbaka sin gunst. Det får några av dem att söka försoning genom elementär hängivenhet.",al={"vilka är shen'dorei","shen'dorei-lore"}}},fp="15,158,27.338.0,22.204.0,34.143.0,25.150.0,26.139.0,43.190.0,25.162.0,46.157.0"}
P.entries["quest:92532"] = {n="The Warrior's Path",s="The Warrior's Path är ett introduktionsuppdrag i stridskonst för blivande kämpar på Zephras Isle. Följ instruktionerna från Rorian the Dayseeker, så leds unga krigare till Blademaster Ren i vakttornet i Thendal Village. Ren är redo att lära ut strid och disciplin till dem som vill skydda sitt folk.",h="The Warrior's Path är ett introduktionsuppdrag i stridskonst för blivande kämpar på Zephras Isle.",kw={"blademaster ren","crumpled note","rorian the dayseeker","thendal village","the warrior's path","vakttorn","zephras isle"},ang={["class:Warrior"]="Det här uppdraget är början på din formella stridsutbildning i Thendal Village och introducerar dig för Blademaster Ren, din mentor."},sec={{t="En kallelse till vakttornet",b="När blivande kämpar återvänder till Rorian the Dayseeker i Thendal Village efter att ha återställt balansen i närheten får de veta att byns svärdmästare har lagt märke till dem. Rorian lämnar över en skrynklig lapp som Ren själv har skrivit, där hon ber novisen att söka upp henne direkt. Högt ovanför bebyggelsen i byns vakttorn håller Ren ett vakande öga på både öns gränser och de rekryter som en dag kan komma att försvara dem."},{t="Skyddets mantel",b="I vakttornet får krigaren lära sig Blademaster Rens syn på strid. För Ren handlar mästerskap i stridskonst inte bara om råstyrka, utan om en viktig plikt att leda, härda ut och skydda i en allt osäkrare värld. Hon lovar att vägleda rekryten när hen finslipar sina färdigheter och erbjuder hård träning tills hen blivit stark nog att möta de större faror som hotar hemmet."}},faq={{q="Vem skickar mig för att hitta Blademaster Ren?",a="Rorian the Dayseeker visar dig till Blademaster Ren när du har slutfört uppgifter i Thendal Village. Medan du var borta bad Ren uttryckligen Rorian att skicka dig till hennes vakttorn när du kom tillbaka.",al={"vem startar det här","uppdragsgivare","rorian roll"}},{q="Var hittar jag Blademaster Ren?",a="Blademaster Ren finns inne i vakttornet i Thendal Village på Zephras Isle, där hon håller uppsikt över byn och tränar nya stridskämpar.",al={"var finns blademaster ren","rens plats","vakttornet i thendal"}},{q="Vad är Crumpled Note?",a="Crumpled Note är en personlig kallelse som Rorian överlämnar till dig på uppdrag av Blademaster Ren. I den ber hon dig läsa lappen och infinna dig i vakttornet i Thendal Village för formell stridsträning.",al={"crumpled note","vad står det i lappen","rens lapp"}},{q="Vad lär Blademaster Ren unga krigare?",a="Blademaster Ren betonar vaksamhet, ledarskap och beskydd. Hon påminner sina elever om att krigare måste ha viljan att stå mellan faran och sitt folk när världen förändras och hoten växer.",al={"rens undervisning","vad tränar ren","krigarens syfte"}},{q="Måste jag göra det här uppdraget för att träna som krigare på Zephras Isle?",a="Uppdraget är den formella introduktionen till din klasstränare i Thendal Village. Det visar dig direkt till Blademaster Ren, så att du vet vart du ska återvända för att lära dig fler stridstekniker.",al={"måste jag göra det här","introduktion till krigartränaren","är det obligatoriskt"}},{q="Vad menar Ren med ”må vindarna vägleda dig”?",a="Den här traditionella välsignelsen speglar kulturen på Zephras Isle och önskar resenärer trygg färd, fokus och lycka när de ger sig ut i okända och farliga områden.",al={"vad betyder må vindarna vägleda dig","vindcitat","rens avsked"}}},fx={["2d8c1194"]={q="Varför skickar Rorian the Dayseeker mig till Blademaster Ren?",a="Blademaster Ren bad personligen Rorian att visa dig till vakttornet så snart du återvände till Thendal Village. Världen förändras och farliga prövningar väntar. Ren förstår att blivande krigare behöver gedigen stridsträning och vägledning från en ledare om ditt folk ska överleva de faror som väntar. Rorian uppfyller helt enkelt Rens begäran och ser till att du får den träning du behöver.",al={"varför rorian skickar mig","rorians motiv","varför söka upp blademaster ren"}}},fp="18,146,27.382.0,24.302.0,37.160.0,33.138.0,26.167.0,47.165.0,60.128.0,48.140.0"}
P.entries["quest:92533"] = {n="Twisted Tools",s="En smed ber dig undersöka vapnen som Blackthorne-kultister bär. Deras märken kan avslöja hur kultens fördärv sprids.",h="En smed ber dig undersöka vapnen som Blackthorne-kultister bär.",kw={"blackthorne","fördärv","kultister","recoiling gnarlybark staff","ritualdolk","smed","förvridna verktyg","wicked ritualist's kris"},sec={{t="Smedens oro",b="En smed som arbetat med järn hela sitt liv ser hur Blackthorne-kultister vänder sina vapen mot land och liv. Han ber dig hämta en ritualdolk och en stav så att deras fördärvande märken kan undersökas."},{t="En mörk börda",b="Vapnen bär på ett mörker som klänger sig fast vid dig medan du bär dem. Smeden tar dem ifrån dig och hoppas, med Earthmothers välsignelse, finna ett sätt att vända deras fördärv."}},faq={{q="Vad vill smeden ha?",a="Smeden ber dig hämta en ritualdolk och en stav som Blackthorne-kultister bär.",al={"vad behöver han","fråga om förvridna verktyg","vilka vapen"}},{q="Varför undersöka vapnen?",a="Smeden hoppas att märkena på vapnen ska visa hur kultens fördärv sprids och hur det kan hejdas eller vändas.",al={"varför ta verktygen","vad kan märkena visa","blackthorne-vapen"}},{q="Vilka vapen behövs?",a="Vapnen som nämns är en Wicked Ritualist’s Kris och en Recoiling Gnarlybark Staff.",al={"dolk och stav","vilka verktyg","ritualdolk"}},{q="Vad händer när man bär dem?",a="Smeden känner ett mörker omkring dig medan du bär vapnen och varnar för att man ännu inte känner till följderna av att hantera dem.",al={"förbannade vapnens effekt","mörker över mig","vapenplåga"}}},fp="13,126,21.213.0,13.187.1,25.93.0,22.127.0,24.83.0,33.127.0"}
P.entries["quest:92544"] = {n="Al'Aketh Thugs",s="De fridfulla vägarna kring Thendal Grove hotas av ett våldsamt Al'Aketh-kultistgäng som ockuperar tempelruinerna i närheten. De skickades från Shrine of Akir för att trakassera vägfarare och tvinga in nya rekryter i leden, och utgör ett omedelbart hot mot traktens resenärer. Hanaa Nightwind ger äventyrare i uppdrag att bryta deras grepp och döda deras brutala befälhavare.",h="De fridfulla vägarna kring Thendal Grove hotas av ett våldsamt Al'Aketh-kultistgäng som ockuperar...",kw={"al'aketh-råskinn","al'aketh-novis","al'aketh thugs","hanaa nightwind","översteprästinnan lorthuna","malduko cloudcrush","shrine of akir","thendal grove"},sec={{t="Kultistbusar i ruinerna",b="Strax sydväst om Thendal Grove ligger uråldriga tempelruiner som borde erbjuda vandrare en lugn tillflykt. I stället har Al'Aketh tagit över området, en aggressiv kult driven av fanatisk ärelystnad. Kultisterna är inga fridsamma gudsdyrkare, utan beter sig som stråtrövare och våldsverkare och ger sig på dem som färdas i utkanten av lunden. De närbelägna skogvaktarna misstänker att dessa busar skickades direkt av översteprästinnan Lorthuna från Shrine of Akir för att trakassera och tvinga befolkningen att underkasta sig kultens inflytande."},{t="Kultledaren Malduko Cloudcrush",b="I spetsen för pöbeln vid tempelruinerna står Malduko Cloudcrush, en brutal ledare som använder våld och rädsla för att hålla både sina invigda och intet ont anande vägfarare i schack. Med råskinn och nyligen indoktrinerade noviser under sitt befäl har Malduko upprättat en aggressiv utpost alldeles intill Thendal Grove. Genom att fälla Cloudcrush och skingra hans underhuggare hoppas Hanaa Nightwind krossa kultens självförtroende och tydligt visa att fanatism och tvång inte tolereras i dessa trakter."}},faq={{q="Vilka är Al'Aketh?",a="Al'Aketh är en fanatisk kult verksam på Zephras. Under ledning av personer som översteprästinnan Lorthuna vid Shrine of Akir använder de våld, hot och skrämseltaktik för att tvinga traktens resenärer och invånare att ansluta sig till deras led.",al={"vad är al'aketh","al'aketh-kulten","vilka är al'aketh"}},{q="Varför angriper kultisterna Thendal Grove?",a="De har slagit läger i tempelruinerna sydväst om Thendal Grove för att överfalla resenärer som lämnar området. Genom att terrorisera vägfarare hoppas de pressa och tvinga lokalbefolkningen att underkasta sig kulten.",al={"varför är kultister här","varför thendal grove","kultisternas motiv"}},{q="Vem är Malduko Cloudcrush?",a="Malduko Cloudcrush är ett våldsamt råskinn som leder Al'Akeths läger vid tempelruinerna. Hanaa Nightwind beskriver honom som ett monster. Han befaller råskinnen och noviserna som ger sig på vägarna i närheten.",al={"malduko","cloudcrush","vem är malduko cloudcrush"}},{q="Vem är Hanaa Nightwind?",a="Hanaa Nightwind är en av skogvaktarna som skyddar Thendal Grove. Hon håller vakt vid sin post längs vägen och varnar resenärer för kultisternas överfall i närheten. För att röja hotet förlitar hon sig på skickliga äventyrare.",al={"hanaa","hanaa nightwind","uppdragsgivare"}},{q="Vem skickade kultisterna till ruinerna?",a="Hanaa misstänker att de skickades dit av översteprästinnan Lorthuna, som övervakar kultens verksamhet från Shrine of Akir.",al={"vem befaller dem","kultledare","vem skickade malduko"}},{q="Vad mer finns nära tempelruinerna?",a="Förutom Al'Akeths läger finns en aktiv ley-linje i de uråldriga ruinerna vid områdets sydvästra ände.",al={"ley-linje i ruinerna","tempelruinernas hemlighet","ruinerna i sydväst"}}},fx={b63e8692={q="Varför vill Hanaa Nightwind rensa bort Al'Aketh-busarna?",a="Al'Aketh-kultisterna har slagit läger farligt nära Thendal Grove, trakasserar resande längs vägarna och försöker tvinga in lokalbefolkningen i sin fanatiska rörelse. Skogsväktaren Hanaa Nightwind vill bryta deras grepp om ruinerna i sydväst och skicka ett blodigt, tydligt budskap som tvingar de överlevande kultisterna att lämna området.",al={"varför döda al'aketh-busarna","hanaa nightwinds motiv","varför rensa tempelruinerna"}},b6ccde37={q="Varför kan inte Hanaa Nightwind ta hand om kultisterna själv?",a="Hanaa måste stanna på sin post för att hålla vakt och varna ovetande resande som lämnar Thendal Grove innan de vandrar rakt in i kultens bakhåll. Det krävs all hennes självbehärskning för att inte själv marschera in i ruinerna, men hon kan inte överge sin plikt vid lundens utkant.",al={"varför hanaa behöver mig","varför hanaa inte slåss mot dem","varför jag ska till al'aketh thugs"}}},fp="14,276,29.322.0,18.370.0,21.201.0,45.206.0,26.168.0,23.188.0,37.122.0,45.117.0"}
P.entries["quest:92550"] = {n="Havoc in the Highlands",s="Havoc in the Highlands är ett förebyggande anfall för Shen'dar Village, avsett att störa en förestående attack från Al'Aketh-fanatiker. Genom att slå till mot deras förtrupp vid ruinerna av Falaath Village och döda Commander Cyclas vänder försvararna striden mot kultisterna innan de kan översvämma höglandet.",h="Havoc in the Highlands är ett förebyggande anfall för Shen'dar Village, avsett att störa en förestående...",kw={"al'aketh","commander cyclas","falaath village","havoc in the highlands","living lightning","sania silverstream","shen'dar village","stormcallers"},ang={["class:Shaman"]="Al'Aketh-kultisterna styr elementen med sina Stormcallers och frammanad Living Lightning och förvrider vind och storm till vapen för fanatisk aggression."},sec={{t="Ett förebyggande anfall",b="Inför en nära förestående invasion från fanatiska kultister beslutar ledningen i Shen'dar Village att ett snabbt förebyggande anfall ger den bästa chansen att överleva. I stället för att invänta en attack bakom bräckliga försvar skickas en äventyrare till ruinerna av Falaath Village för att överraska de fientliga Al'Aketh-styrkorna innan anfallet kan inledas."},{t="Anfall mot Falaath Village",b="Uppsamlingsplatsen vid Falaath Village kryllar av farliga fanatiker som brukar kaotiska elementarkrafter. För att slå till mot de samlade styrkorna måste du döda Al'Aketh Stormcallers, krossa frammanad Living Lightning och spåra upp Commander Cyclas själv för att göra slut på expeditionens ledarskap."},{t="Säkra höglandet",b="När Commander Cyclas har dödats och hans förtrupp krossats får Shen'dar Village ett välbehövligt andrum. Men mitt i tumultet när invånarna beväpnas smiter en person vid namn Sania Silverstream obemärkt ut ur byn och flyr precis när det lokala försvaret samlar sig."}},faq={{q="Vad är Havoc in the Highlands?",a="Havoc in the Highlands är ett förebyggande anfall från Shen'dar Villages försvarare mot Al'Aketh-kultister som samlas i ruinerna av Falaath Village innan de kan inleda en attack.",al={"uppdraget havoc in the highlands","vad är havoc in the highlands","uppdrag i höglandet"}},{q="Vem hotar Shen'dar Village?",a="Bosättningen hotas av Al'Aketh, en fanatisk kult av elementära stormdyrkare med Stormcallers, bundna Living Lightning och deras ledare, Commander Cyclas.",al={"vilka är fienderna","vilken kult är det här","vem anfaller shen'dar"}},{q="Var samlas kultisterna?",a="Anfallet äger rum i ruinerna av Falaath Village, där Commander Cyclas och hans Al'Aketh-anhängare har upprättat sin uppsamlingsplats.",al={"var finns commander cyclas","ruinerna av falaath village","vart ska man gå"}},{q="Vem är Commander Cyclas?",a="Commander Cyclas är den militäre befälhavaren som leder Al'Aketh-styrkorna i ruinerna av Falaath Village, där de samlats för att marschera mot Shen'dar.",al={"vem är commander cyclas","cyclas bakgrund","cyclas kult"}},{q="Varför flydde Sania Silverstream från Shen'dar Village?",a="Sania Silverstream smet ut ur Shen'dar Village precis innan byns försvarare samlades, troligen för att fly när hon insåg att lokalbefolkningen beväpnade sig och organiserade ett försvar.",al={"sania silverstream flyr","varför lämnade sania byn","vem är sania silverstream"}},{q="Lyckas anfallet säkra Shen'dar Village?",a="Genom att bryta igenom kultisternas främsta led och ta Commander Cyclas huvud slår Shen'dar Village tillbaka det omedelbara hotet och visar eventuella återvändande fanatiker att höglandet inte faller lätt.",al={"överlevde shen'dar","efter anfallet","är shen'dar säkert"}}},fp="22,163,19.185.0,26.214.0,22.231.1,31.145.0,36.153.0,31.128.0,24.119.0,49.163.0,53.179.0"}
P.entries["quest:92551"] = {n="Stolen Supplies",s="Stolen Supplies ger äventyrare i uppdrag att återta plundrade varor från höglandet från Al'Aketh i Falaath Village. Karavanöverfall har stoppat viktiga leveranser av mat och vindstenar mellan låglandet och Shen'dar Highlands, och de lokala luftburna samhällena svälter snart.",h="Stolen Supplies ger äventyrare i uppdrag att återta plundrade varor från höglandet från Al'Aketh i Falaath...",kw={"al'aketh","karavaner","konstapel","falaath village","shen'dar highlands","luftburna","stolen supplies","vindstenar"},ang={["race:Skyborne"]="Räderna slår direkt mot livlinan mellan höglandet och låglandet och lämnar luftburna invånare hungriga och desperata utan sina regelbundna leveranser av mat och vindstenar."},sec={{t="Räder mot höglandets livlina",b="I flera månader har karavaner mellan låglandet och Shen'dar Highlands utsatts för återkommande angrepp längs handelsvägarna. Leveranserna för med sig viktiga förnödenheter, däribland mat och vindstenar, som håller bosättningarna i höglandet vid liv. Utan regelbundna leveranser är lokalbefolkningen på väg att svälta och kämpar för att klara sig medan förråden sinar i hela regionen."},{t="Förrådet i Falaath",b="Al'Aketh skyller offentligt karavanöverfallen på vanliga banditer, men den försvunna lasten berättar en annan historia. Stulna förpackningar med förnödenheter från Shen'dar hamnar gång på gång i Falaath Village, där Al'Aketh samlar sina förråd. När varorna återtas kan de lokala myndigheterna och konstapeln dela ut välbehövlig proviant direkt till de mest utsatta luftburna invånarna."}},faq={{q="Vilka förnödenheter stals från karavanerna?",a="Karavanerna mellan höglandet och låglandet transporterade livsviktiga varor, framför allt mat och vindstenar. De regelbundna leveranserna håller lokalbefolkningen mätt och försörjd.",al={"vad stals","stulna förnödenheter","vilka varor stals"}},{q="Vem ligger bakom karavanräderna?",a="Al'Aketh har plundrat förnödenhetskaravanerna i flera månader. De försöker skylla de försvunna leveranserna på vanliga banditer, men de stulna förråden hamnar bevisligen i deras område vid Falaath Village.",al={"vem stal förnödenheterna","vem överföll karavanerna","karavanernas angripare"}},{q="Var förvaras de stulna förnödenheterna?",a="De stulna förpackningarna med förnödenheter förvaras i Falaath Village, en bosättning tillhörande Al'Aketh i Shen'dar Highlands.",al={"var finns förnödenheterna","var hittar man förnödenheter","plats för stulna förråd"}},{q="Varför är förnödenhetskaravanerna måltavlor?",a="Förnödenheterna omfattar livsviktig proviant som mat och vindstenar som fraktas till och från låglandet. Räderna berövar lokalbefolkningen bland de luftburna dess försörjning, samtidigt som Falaath Village fylls med viktiga resurser från höglandet.",al={"varför stjäla vindstenar och mat","varför karavanräder"}},{q="Vad händer med förnödenheterna när de återtas?",a="När förnödenheterna har återtagits från Falaath Village samordnas utdelningen med den lokala konstapeln, så att de når invånarna som allra mest behöver mat och hjälp.",al={"vem får tillbaka förnödenheterna","omfördelning av förnödenheter","vad händer efter återtagandet"}},{q="Varför skyller Al'Aketh räderna på banditer?",a="Al'Aketh skyller på kringströvande banditer för att slippa ta ansvar för de försvunna handelsvarorna, trots att den stulna lasten gång på gång hamnar på hög i deras egen bosättning i Falaath Village.",al={"varför skylla på banditer","al akeths ursäkt om banditer"}}},fp="15,213,30.272.0,17.274.0,44.135.0,44.138.0,46.93.0,45.171.0,53.144.0,48.134.0"}
P.entries["quest:92553"] = {n="Restocking the Larders",s="Restocking the Larders är ett försörjningsuppdrag i Shen'dar Highlands på Zephras. När ökande faror i vildmarken hindrar byborna från att samla mat får en äventyrare i uppdrag att hämta ägg och striderkött för att försörja bosättningen.",h="Restocking the Larders är ett försörjningsuppdrag i Shen'dar Highlands på Zephras.",kw={"matlagning","restocking the larders","shen'dar highlands","små ägg","strider meat","urseraspäck","zephras"},ang={["profession:Cooking"]="Att samla lokala ingredienser som striderkött och små ägg ger praktisk erfarenhet och matlagningsrecept anpassade till Zephras vilda djur."},sec={{t="Faror i höglandet",b="När oroligheter och ökande faror sprider sig över Shen'dar Highlands blir vardagslivet på Zephras allt mer bekymmersamt. Vanliga bybor kan inte längre tryggt ge sig ut i vildmarken för att samla mat eller jaga, och de gemensamma matförråden har därför sinat rejält. För att hålla bosättningen mätt måste de lokala kockarna vända sig till resande äventyrare med styrkan och skickligheten att trotsa de vilda stigarna."},{t="Mat och tröst",b="Uppgiften går ut på att spåra upp inhemska vilda djur i höglandet för att få tag på striderkött och färska små ägg. Till dem som bidrar med förnödenheter delar kocken gärna med sig av sina matlagningskunskaper och lär ut recept och tekniker som förfinats med lokalt villebråd, bland annat ägg stekta i mustigt urseraspäck, avnjutna med en stillsam pipa torkad peacebloom."}},faq={{q="Vilka förnödenheter behövs till Restocking the Larders?",a="En lokal kock behöver 3 Small Eggs och 8 stycken Strider Meat för att hjälpa till att mätta byn medan farorna håller vanliga matsamlare inomhus.",al={"syftet med restocking the larders","vad ska samlas till restocking the larders"}},{q="Var hittar man ingredienserna?",a="Strider Meat och Small Eggs kommer från vilda djur som strövar omkring i Shen'dar Highlands på ön Zephras.",al={"var hittar man strider meat på zephras","var finns ägg i shen'dar"}},{q="Varför börjar byn få slut på mat?",a="De ökande farorna i området gör det alltför riskabelt för vanliga bybor att ge sig ut för att jaga eller samla mat, så matförråden har sinat.",al={"varför behövs mat på zephras","varför är byn hungrig i shen'dar"}},{q="Vilken belöning erbjuder kocken för maten?",a="Som tack för färska förnödenheter erbjuder uppdragsgivaren matlagningstips, knep och träning i lokala recept.",al={"vad erbjuder uppdragsgivaren","uppdrag med matlagningsträning"}},{q="Vad är Shen'dar Highlands och Zephras?",a="Shen'dar Highlands ligger på Zephras, där lokalbefolkningen kämpar med tilltagande hot samtidigt som de försöker få vardagen att gå ihop.",al={"vad är zephras","var ligger shen'dar highlands"}},{q="Hur tillagar kocken äggen?",a="Kocken svär vid att steka nyplockade små ägg i urseraspäck och kallar kombinationen en oöverträffad tröst på Zephras.",al={"späckets matlagningshemlighet","hur tillagas ägg på zephras"}}},fp="22,187,24.271.0,22.247.0,52.134.0,35.100.0,39.111.0,45.106.0,44.116.0,35.82.0"}
P.entries["quest:92579"] = {n="To Valanaar",s="\"To Valanaar\" är ett öuppdrag där äventyrare för ett brådskande militärt meddelande från Aonda i Shen'dar till fredsvakarnas ledare Valennia Stormfist. Meddelandet varnar bosättningen vid öns sydöstra kant för att en aggressiv kult snabbt växer sig större och att en direkt konflikt inte längre går att undvika.",h="\"To Valanaar\" är ett öuppdrag där äventyrare för ett brådskande militärt meddelande från Aonda i Shen'dar...",kw={"aonda","kult","fredsvakare","shen'dar","to valanaar","valanaar","valennia stormfist"},sec={{t="Ett brådskande meddelande",b="Efter försvaret av Shen'dar och dess pylon skickar höglandsbon Aonda en betrodd resenär över ön med brådskande nyheter till Valanaar. Valanaar ligger vid landets sydöstra kant och hyser öns fredsvakare, under ledning av Valennia Stormfist. Uppdraget bär på en viktig varning: öns fredliga dagar går mot sitt slut, och Valennia måste förbereda sitt folk på en oundviklig sammandrabbning med en aggressiv kult som växer sig allt större."},{t="Stormen närmar sig",b="Fram till den här varningen har de lokala fredsvakarna lyckats undvika direkt konflikt med den mystiska kulten. Men kultens aggressiva intrång har drivit spänningarna till bristningsgränsen. När Valennia läser Aondas skriftliga rapport inser hon att fredsvakarna genast måste samla sina återstående styrkor och utforma en försvarsstrategi innan kulten riktar sin uppmärksamhet mot själva Valanaar."}},faq={{q="Vem skickar dig till Valanaar?",a="Uppdraget ges av Aonda, en höglandsbo i Shen'dar, efter att du hjälpt till att skydda den lokala byn och pylonen från ett överhängande hot från kultister. Hon är imponerad av din hjälp och anförtror dig ett brådskande skriftligt meddelande som ska föras tvärs över ön.",al={"vem ger uppdraget till valanaar","uppdragsgivare till valanaar","vem skickar mig till valanaar"}},{q="Vem är Valennia Stormfist?",a="Valennia Stormfist leder fredsvakarna på ön, med högkvarter i bosättningen Valanaar. Hon ansvarar för det lokala försvaret och ordningen och ska samordna insatser mot regionala hot, som kultens aggressiva expansion.",al={"vem är valennia stormfist","valennia ledare","valennia"}},{q="Vad är Valanaar?",a="Valanaar är en bosättning vid öns sydöstra kant. Den fungerar som bas för öns fredsvakare, ledda av Valennia Stormfist, och som tillflykt och samlingsplats för ortsborna.",al={"vad är valanaar","var ligger valanaar","valanaars plats"}},{q="Vad är syftet med Aondas rapport?",a="Aondas rapport beskriver det växande hotet från kulten och händelserna kring säkerheten i Shen'dar och vid dess pylon. Fredsvakare har länge undvikit direkt konflikt, men rapporten varnar för att kultens snabba expansion gör en framtida sammandrabbning oundviklig och att Valanaar därför måste förbereda sitt försvar.",al={"varför leverera rapporten","vad är aondas rapport","vad står i brevet"}},{q="Vilket hot utgör kulten mot ön?",a="Rapporten varnar för en namnlös kult som snabbt växer sig större över ön. Fredsvakarna har tidigare hållit avstånd för att undvika öppet krig, men kultens senaste aggressiva handlingar mot platser som Shen'dar visar att konflikten inte längre går att undvika.",al={"vilken kult hotar valanaar","vem är kulten","kultens hot mot ön"}},{q="Vad händer när du kommer fram till Valanaar?",a="När Valennia får de dystra nyheterna måste hon rådgöra med sina återstående fredsvakare för att utforma en försvarsstrategi mot framtida kultattacker. Medan hon samordnar deras planer bjuder hon in resenärer att hjälpa ortsborna kring Valanaar, som behöver en hand.",al={"vad göra efter att ha lämnat rapporten","vad händer sedan i valanaar"}}},fp="11,206,18.368.0,19.279.1,26.207.0,26.191.0,17.167.0,38.241.0,45.248.0,37.226.0"}
P.entries["quest:92595"] = {n="The Windshapers",s="\"The Windshapers\" är ett uppdrag där Illaya Amberwind introducerar spelaren till Windshapers och deras andliga uppdrag. Orden har fått i uppgift att återknyta kontakten med vindandarna och strävar efter att skydda Zephras och säkra Shen'doreis överlevnad bland hoten i Skywall.",h="\"The Windshapers\" är ett uppdrag där Illaya Amberwind introducerar spelaren till Windshapers och deras...",kw={"al'aketh","illaya amberwind","shen'dorei","skysight","skywall","windshapers","zephras"},ang={["class:Shaman"]="Illaya påpekar att utbildade schamaner naturligt kommunicerar med elementen, men att gåvan skysight även kan visa sig hos andra. Det visar på Windshapers gemensamma andliga plikt med dem som åkallar elementen.",["race:Skyborne"]="Windshapers kämpar för Shen'doreis överlevnad och hemland bland de osäkra höjderna i Skywall och Zephras."},sec={{t="Windshapers uppdrag",b="Windshapers är en orden som ägnar sig åt att kommunicera med vindandarna och skydda Shen'dorei. De välkomnar dem med en medfödd andlig känslighet och försöker överbrygga den växande klyftan mellan sitt folk och de elementarkrafter som upprätthåller deras luftburna rike. Illaya Amberwind hjälper nya rekryter att förstå de tunga bördor som orden bär."},{t="Prövningar på Zephras",b="Överlevnad i Skywall är långt ifrån säker. Windshapers måste ta sig igenom den förrädiska inre oron som Al'Aketh orsakar, samtidigt som de uthärdar elementarplanets större faror. Att återupprätta dialogen med vindandarna anses avgörande för att Zephras ska bestå och Shen'dorei klara stormen."}},faq={{q="Vilka är Windshapers?",a="Windshapers är en grupp som ägnar sig åt att kommunicera med vindandarna och skydda sitt folk, Shen'dorei. Under ledare som Illaya Amberwind söker de upp individer med skysight för att återupprätta dialogen med vindandarna och bevara sitt hotade hemland.",al={"vilka är windshapers","windshapers fraktion","vad gör windshapers"}},{q="Vad är skysight?",a="Skysight är en medfödd andlig känslighet eller gåva som gör det möjligt att få kontakt med luftens element. Som Illaya förklarar behöver man inte ha formell träning som schaman för att ha skysight, men det är avgörande att kunna bemästra gåvan för att nå vindandarna.",al={"vad är skysight","skysight historia"}},{q="Vem är Illaya Amberwind?",a="Illaya Amberwind är en mentor bland Windshapers som känner igen andliga gåvor hos resenärer. Hon välkomnar dem som har skysight och förklarar Windshapers uppdrag, farorna som hotar Zephras och prövningarna som Shen'dorei står inför.",al={"vem är illaya","illaya amberwind"}},{q="Vad är Zephras?",a="Zephras är ett luftburet område eller samhälle som genomlider svåra prövningar och inre oro. Windshapers kämpar aktivt för att skydda Zephras och bevara en framtid för sitt folk där.",al={"vad är zephras","zephras historia"}},{q="Vilka är Al'Aketh?",a="Al'Aketh är en fientlig intern fraktion eller ett hot som plågar Windshapers och Shen'dorei och förvärrar farorna med att överleva i Skywall.",al={"vilka är al'aketh","al'aketh hot"}},{q="Vilka är Shen'dorei?",a="Shen'dorei är folket som Windshapers företräder. De står inför inre hot som Al'Aketh och osäkra förhållanden i Skywall, och deras överlevnad hänger på att Windshapers återställer balansen med vindarna.",al={"vilka är shen'dorei","shen'dorei historia"}}},fp="15,176,26.326.0,17.239.0,24.217.0,17.209.0,24.217.0,16.171.0,21.150.0,23.209.0"}
P.entries["quest:92596"] = {n="The High Order",s="The High Order är ett introduktionsuppdrag på Zephras där Rathiril Sunlance förklarar shen'doreis svåra situation. Sedan de förlorade sina elementära välgörares hjälp måste dessa ättlingar till Highborne från Eldre'Thalas bemästra sin uråldriga arkana magi för att säkra sin överlevnad.",h="The High Order är ett introduktionsuppdrag på Zephras där Rathiril Sunlance förklarar shen'doreis svåra...",kw={"al'aketh","arkana","eldre'thalas","highborne","rathiril sunlance","shen'dorei","the high order","zephras"},ang={["class:Mage"]="Rathiril påpekar att även äventyrare som inte formellt utbildats till magiker bär starka arkaniska auror. Det visar att deras gemensamma magi är ett medfött arv, inte bara en studerad disciplin.",["race:Skyborne"]="Som ättlingar till forntidens Highborne i Eldre'Thalas måste shen'dorei bemästra sina uråldriga arkaniska gåvor för att stå på egna ben efter att deras elementära beskyddare lämnat dem."},sec={{t="Ett folk på egen hand",b="The High Order är shen'doreis på Zephras målmedvetna försök att återta sin styrka och forma sin egen framtid. Länge förlitade sig deras folk på sina elementära välgörares beskydd och ynnest. Nu när dessa elementära beskyddare är borta står folket ensamt, sårbart för inre stridigheter och faror från omgivningen. Ledare som Rathiril Sunlance söker upp personer med fallenhet för arkana förmågor, så att de kan ansluta sig till uppdraget att bevara folket och göra det självförsörjande."},{t="Arvet från Eldre'Thalas",b="Shen'dorei bär med sig arvet från sitt förfädershem Eldre'Thalas och delar en medfödd källa till arkan energi, som omger även dem som inte formellt har invigts i magins konst. The High Order ser det som deras gemensamma öde, som ättlingar till Highborne, att utöva dessa uråldriga magiska gåvor. På så vis hoppas de kunna motverka inre hot som Al'Aketh och stå emot de många säkerhetshot som hemsöker deras hem på Zephras."}},faq={{q="Vad är High Order?",a="The High Order är en organisation bland shen'dorei som arbetar för folkets överlevnad. Orden grundades av ättlingar till Highborne från Eldre'Thalas och strävar efter att ta till vara på sina uråldriga arkaniska gåvor, så att deras samhälle kan försvara sig och klara sig på egen hand på Zephras.",al={"vilka är high order","vad är high order","high orders syfte"}},{q="Vem är Rathiril Sunlance?",a="Rathiril Sunlance är en alv med anknytning till The High Order på Zephras. Han lär nykomlingar om de lokala arkanenergiernas natur, shen'doreis svåra situation och The High Orders beslutsamhet att överleva utan sina forna elementära beskyddare.",al={"vem är rathiril","rathiril sunlance berättelse","sunlance"}},{q="Vad är Zephras?",a="Zephras är den flytande ön i Skywall där Rathiril Sunlance och hans folk nu bor. Platsen genomsyras av arkan energi, och där möter shen'dorei både inre faror och yttre osäkerhet kring sin trygghet.",al={"var finns high order","vad är zephras","zephras berättelse"}},{q="Vilka är shen'dorei?",a="Shen'dorei är alver som härstammar från Highborne i sitt förfädershem Eldre'Thalas. De bor nu på Zephras, har en medfödd koppling till arkan magi och strävar efter att klara sig på egen hand.",al={"vilka är shen'dorei","shen'dorei","shen'dorei berättelse"}},{q="Vilka var de elementära välgörarna?",a="De elementära välgörarna var mäktiga elementvarelser som tidigare hjälpte och beskyddade shen'dorei. Men nu är de borta, och folket på Zephras måste helt förlita sig på sin egen magiska förmåga och uppfinningsrikedom.",al={"vilka är elementvarelserna","elementära beskyddare","elementära välgörare"}},{q="Vad är Al'Aketh?",a="Al'Aketh är en intern fraktion eller ett hot som utmanar shen'doreis trygghet på Zephras. Att hantera sådana inre fiender är en av de centrala frågor som får The High Order att organisera sitt försvar.",al={"vad är al'aketh","al'aketh-hot","inre hot på zephras"}},{q="Hur hänger The High Order och Eldre'Thalas ihop?",a="Shen'doreis förfäder kom från Eldre'Thalas, den uråldriga Highborne-staden i Kalimdor, som många år 25 ADP känner till som Dire Maul. The High Order hedrar detta förfädersarv genom att bevara och använda sina uråldriga arkaniska gåvor.",al={"kopplingen till eldre'thalas","kommer de från dire maul","highbornes ursprung"}}},fp="14,225,21.364.0,22.360.0,23.242.0,25.214.0,16.225.0,23.168.0,35.191.0,22.164.0,63.241.0"}
P.entries["quest:92597"] = {n="Reading the Ley Lines",s="Reading the Ley Lines är en övergångsrit för unga Skyborne som upptäcker sitt magiska Highborne-arv. På uppdrag av Falorne Fallwind på Zephras Isle reser noviser till stenarna i Thendal Grove för att känna av och dra kraft ur de råa arkanströmmar som rusar genom elementterrängen.",h="Reading the Ley Lines är en övergångsrit för unga Skyborne som upptäcker sitt magiska Highborne-arv.",kw={"al'aketh","falorne fallwind","highborne","ley-linjer","reading the ley lines","skyborne","thendal grove","thendal standing stones","windshapers","zephras isle"},ang={["class:Mage"]="För utövare av arkanmagi är blottlagda ley-linjer en ovärderlig reservoar av otämjd kraft i en miljö som domineras av elementstormar.",["race:Skyborne"]="Denna rit väcker ditt medfödda Highborne-arv och lär dig att kanalisera underjordisk ley-energi direkt in i dina besvärjelser."},sec={{t="Arkanströmmar från elementplanet",b="Även i elementplanets vindpinade trakter löper slumrande arkanledningar under jorden. Medan märkliga elementaler och fientliga Al'Aketh driver över Zephras Isle har underjordiska ley-linjer börjat tränga upp mot ytan. För magiutövare ger dessa sprickor direkt tillgång till otämjda arkanreservoarer och skänker kraft åt alla som har den blodslinje och kunskap som krävs för att kanalisera dem."},{t="Highborne-arvet",b="Falorne Fallwind uppmanar nykomlingar att omfamna sitt Highborne-ursprung i stället för att ödmjuka sig inför vindandar som de lokala Windshapers eller Al'Aketh-fanatikerna. Enligt Fallwind beror överlevnaden mot elementplanets hårda krafter inte på att be främmande varelser om nåd, utan på att bemästra den inneboende arkanmakt som löper under deras fötter."},{t="Thendal Standing Stones",b="Nordost om bosättningen ligger Thendal Grove, där uråldriga resta stenar markerar en kraftfull ley-linjekonvergens. Denna utsatta plats för magisk energi, omgiven av virvlande vindar och Al'Aketh-anhängare, låter noviser stämma sina sinnen, harmoniera med ley-linjens puls och frigöra sin naturliga rasförmågas fulla potential."}},faq={{q="Vem ger uppdraget Reading the Ley Lines?",a="Uppdraget erbjuds av Falorne Fallwind på Zephras Isle till unga Skyborne som lär sig att tygla sina förfäders arkanförmågor.",al={"uppdragsgivare","falorne fallwind","vem startar reading the ley lines"}},{q="Var finns ley-linjen?",a="Ley-linjen finns nordost vid Thendal Standing Stones, som ligger i Thendal Grove bland fientliga elementaler och Al'Aketh-anhängare.",al={"ley-linjens plats","var ligger thendal grove","thendal standing stones plats"}},{q="Varför finns ley-linjer i elementplanet?",a="Slumrande arkanledningar löper genom marken även här i elementplanet. Nyligen har dessa ley-linjer börjat bryta igenom ytan och ge Skyborne direkt tillgång till kraftfulla energiströmmar.",al={"arkanmagi i elementplanet","ley-linjer i elementplanet historia"}},{q="Hur ser Falorne Fallwind på Windshapers?",a="Falorne föraktar Windshapers och ser deras vördnad för luftandar som en svag underkastelse inför likgiltiga elementvarelser, inte bättre än Al'Akeths dyrkan.",al={"falorne om windshapers","windshapers historia","windshapers jämfört med highborne"}},{q="Vilken förmåga krävs för att kanalisera ley-linjen?",a="Uppdraget kräver att du använder Skybornes rasförmåga ”Read Ley Line” medan du står i energikonvergensen vid stenarna.",al={"read ley line-förmågan","hur man läser en ley-linje","använd rasförmåga"}},{q="Vilken nytta ger det att utnyttja ley-linjer?",a="Genom att kommunicera med blottlagda ley-linjer kanaliseras rå arkanenergi in i användaren, vilket höjer dennes magiska förmåga och ger varierande effekter beroende på ledningens natur.",al={"vad gör ley-linjer","ley-linjernas fördelar"}}},fx={e5a629f0={q="Varför vill Falorne Fallwind att du läser ley-linjerna?",a="Falorne tror att det enda sättet att rädda ditt folk i elementarplanet är att återta ditt Highborne-arv och hämta kraft direkt från arkana ley-linjer. Han ser ner på grupper som The Windshapers och Al'Aketh, eftersom de underkastar sig likgiltiga elementvarelser. I hans ögon kräver överlevnad att du bemästrar latent magi i stället för att förlita dig på nyckfulla andar.",al={"falorne fallwinds motiv","varför läsa ley-linjer","varför falorne fallwind vill läsa ley-linjerna"}}},fp="21,171,38.291.0,16.349.0,23.302.0,42.118.0,30.142.0,49.174.0,47.161.0,49.114.0,49.147.0"}
P.entries["quest:92598"] = {n="The Gift of Skysight",s="The Gift of Skysight är en tidig övergångsrit för unga Windshapers som lär sig att bemästra sin medfödda kontakt med andevärlden. Under Ventaari Brightwishs ledning reser de invigda till en Elemental Convergence för att väcka sin perception och lyssna direkt till andarnas viskningar.",h="The Gift of Skysight är en tidig övergångsrit för unga Windshapers som lär sig att bemästra sin medfödda...",kw={"elemental convergence","elementandar","skysight","resta stenar","thendal grove","ventaari brightwish","windshaper","zephras"},ang={["class:Shaman"]="Schamaner känner igen Elemental Convergence som helig mark, där gränsen mellan dödlig vilja och elementplanen är som tunnast.",["faction:Horde"]="Som allierade på Zephras Isle förlitar sig Horde på Windshapers övernaturliga förutseende för att navigera bland öns okartlagda faror.",["race:Skyborne"]="För Skyborne är Skysight inte bara ett besynnerligt trick, utan en födslorätt skänkt av elementära beskyddare, som ligger till grund för deras kulturella och andliga identitet."},sec={{t="En helig perception",b="Windshapers har ett medfött band till de elementarkrafter som formar deras värld, förkroppsligat i den heliga förmåga som kallas Skysight. Gåvan låter dödliga sinnen stämma in på andliga våglängder och överbrygga den fysiska klyftan mellan de levande och det osedda. En Windshaper kan kalla fram denna inre syn ute i vildmarken, men kontakten fördjupas nära kraftsamlingar och låser upp resonanta välsignelser och dold visdom som vinden viskar fram."},{t="Thendal Groves sammanflöde",b="Nordost om bosättningen, bland forntida resta stenar, ligger en Elemental Convergence i Thendal Grove. Sådana platser fungerar som fokuspunkter där råa energier samlas och andeväsen dröjer sig kvar. Ventaari Brightwish skickar noviser till denna heliga plats, inte bara för att slutföra en uppgift, utan för att pröva deras andliga styrka. Precis som kroppens och sinnets förmågor behöver Skysight övas medvetet för att mogna, så att en växande Windshaper kan tyda elementens skiftande omen, som deras folks överlevnad är beroende av."}},faq={{q="Vad är syftet med det här uppdraget?",a="Uppdraget lär novisa Windshapers att använda sin Skysight-förmåga i praktiken. Ventaari Brightwish leder de invigda till en Elemental Convergence, där de får uppleva hur omgivningens kraft förstärker deras andliga sinnen.",al={"syftet med the gift of skysight","varför göra det här uppdraget","träning i skysight"}},{q="Vem är Ventaari Brightwish?",a="Ventaari Brightwish är en andlig vägledare och mentor som ansvarar för Windshapers tidiga träning på Zephras Isle. Hon lär dem att respektera och utveckla sitt elementära arv.",al={"ventaari","vem är ventaari brightwish","brightwish"}},{q="Vad är en Elemental Convergence?",a="En Elemental Convergence är en fokuserad plats med förhöjd andlig energi, ofta utmärkt av forntida resta stenar. Sådana platser drar naturligt till sig elementandar och förstärker förmågor som Skysight.",al={"vad är en elemental convergence","lore om elemental convergence","sammanflödet i thendal grove"}},{q="Var ligger Elemental Convergence?",a="Sammanflödet finns bland de resta stenarna i Thendal Grove, strax nordost om bosättningen på Zephras Isle.",al={"var ligger sammanflödet","thendal groves läge","de resta stenarnas läge"}},{q="Kan Skysight användas var som helst?",a="Ja. En Windshaper kan åkalla Skysight var som helst, men inne i en Elemental Convergence får du en mycket kraftfullare välsignelse och kan få ytterligare insikter från närliggande andar.",al={"kan jag använda skysight var som helst","skysight utanför sammanflödet","var kan jag använda skysight"}},{q="Varför anses Skysight vara avgörande för överlevnaden?",a="Skysight överbryggar klyftan mellan dödliga och elementandar. Enligt Ventaari är förmågan att uppfatta och lyssna till elementens varningar avgörande för att kunna navigera bland hotande faror och skydda deras folk.",al={"varför är skysight viktigt","skysight och överlevnad","elementen och överlevnad"}}},fx={d2ee972c={q="Varför vill Ventaari Brightwish att du använder Skysight vid konvergensen?",a="Ventaari Brightwish vill träna dig i ditt medfödda Windshaper-arv. Precis som en muskel måste Skysight tränas på kraftplatser som Elemental Convergence, så att du kan lära dig att överbrygga avståndet mellan den dödliga och den andliga världen. Hon tror att det är avgörande för din överlevnad att tala med andarna och lyssna till vad elementen säger ditt folk.",al={"varför ventaari vill det här","ventaari brightwishs motiv","varför använda skysight här"}}},fp="20,163,19.399.0,32.398.0,34.114.0,27.131.0,33.163.0,43.119.0,30.136.0,50.163.0"}
P.entries["quest:926"] = {n="Flawed Power Stone",s="Över The Barrens vilar Flawed Power Stone på arkana bord, laddad med arkan energi. Dess skapare lämnade den fatalt bristfällig, så den förbrukar sin egen kraft kort efter att den flyttas.",h="Över The Barrens vilar Flawed Power Stone på arkana bord, laddad med arkan energi.",kw={"arkanisk","the barrens","bristfällig kraftsten","kraftstenar","ritualbord","instabil magi"},ang={["faction:Horde"]="Som medlem av Horde håller du uppsikt över arkaniska märkvärdigheter utspridda över The Barrens, på din vakt mot obehörig trolldom som kan hota dina försörjningsleder."},sec={{t="Instabilt hantverk",b="I The Barrens håller bristfälliga kraftstenar arkan essens i bräckliga strukturer. Deras skapare gjorde dem avsiktligt instabila, så de förfaller till inert materia ögonblick efter att någon hanterar dem."},{t="Självförbrukande energi",b="En sten börjar förbruka sin kraft så snart den lämnar ritualbordet där den vilar. Energin brinner bort för snabbt för att någon ska kunna bära den långt."}},faq={{q="Vad är en bristfällig kraftsten?",a="Flawed Power Stone rymmer rå magisk kraft, men dess avsiktliga brister gör att den snabbt förbrukar sig själv när den väl har flyttats.",al={"bristfällig kraftsten","vad är den här stenen","kraftstenens bakgrund"}},{q="Kan stenarna bevaras för alltid?",a="Nej. När stenarna skiljs från borden som stabiliserar dem kollapsar deras magiska matriser och energin tar snabbt slut.",al={"bevara bristfällig sten","kan jag förvara den","bevara stenen"}},{q="Vem använder stenarna?",a="Orchen Ak'Zeloth förbereder stenarna, och Horde-äventyrare bär dem till eldaltaret på Dreadmist Peak. Där stör de Demon Seeds förbindelse med Burning Legion.",al={"vem gjorde kraftstenarna","vem tillverkade dem","stenarnas skapare"}},{q="Varför bryr sig Horde om dem?",a="Horde använder stenarna mot Burning Legion. Ak'Zeloth förberedde dem åt Neeru Fireblade, så att bära en till eldaltaret på Dreadmist Peak kan bryta Demon Seeds förbindelse med Legion.",al={"hordes intresse","varför vill horde ha den"}}},fp="18,171,22.187.0,21.150.0,29.102.0,40.128.0,22.182.0,35.206.0"}
P.entries["quest:9260"] = {n="Investigate the Scourge of Stormwind",s="Gisselstyrkor pressar mot Stormwind, medan nekropoler tornar upp sig bortom murarna. Lieutenant Orrin kallar försvararna till anfall mot lägren, insamling av nekrotiska stenar och studier av runorna där.",h="Gisselstyrkor pressar mot Stormwind, medan nekropoler tornar upp sig bortom murarna.",kw={"argent dawn","invasion","lich king","lieutenant orrin","nekropol","nekrotiska stenar","runcirklar","gisslet","stormwind"},ang={["class:Paladin"]="Som paladin möter du Gisslet utanför Stormwind och kan rikta helig vrede mot dess runor medan du skyddar kungarikets invånare.",["class:Priest"]="Som präst kan du studera de förvridna viskningarna i runorna och lära dig om skuggmagin som binder samman Gisselns främsta styrkor.",["faction:Alliance"]="För Alliansen är försvaret av Stormwinds portar en fråga om överlevnad. Gisslet har nått ända till detta sydliga fäste."},sec={{t="De odöda vid huvudstadens tröskel",b="Gisselstyrkor har nått utkanten av Stormwind City. Nekropoler svävar ovanför medan odöda och kultister får fäste nära kungarikets främsta bastion. Lieutenant Orrin samlar försvarare utanför staden för att driva tillbaka dem innan de hotar huvudstaden."},{t="De viskande runorna",b="Glödande runor märker ut marken kring Gisselläger, men deras syfte är fortfarande oklart. Cirklarna sprakar av magi som liknar nekropolernas och bär på kusliga viskningar. Lieutenant Orrin kan bara gissa vem som hör de onaturliga rösterna, om någon gör det."}},faq={{q="Vem är Lieutenant Orrin?",a="Lieutenant Orrin är en officer som samordnar Stormwinds försvar. Han samarbetar med Argent Dawn och organiserar lokala krigare för att samla information och bryta upp Gisselns fästen nära staden.",al={"orrin","lieutenant orrin","vem ger uppdraget"}},{q="Varför anfaller Gisslet Stormwind?",a="Lich King har skickat nekropoler och invasionsstyrkor över Azeroth för att sprida skräck och öka de odödas antal. Stormwind är ett viktigt fäste för de levande och därför ett mål för Gisslet.",al={"varför gisslet här","gisslets invasion av stormwind","varför anfalla stormwind"}},{q="Vad är de glödande runcirklarna?",a="Gisslet har placerat glödande runcirklar nära sina läger. De pulserar av mörk magi och bär på onaturliga viskningar, men deras syfte är okänt.",al={"runcirklar","glödande runor","vad gör cirklarna"}},{q="Vad är dunkla nekrotiska stenar?",a="Dunkla nekrotiska stenar är magiska föremål som bärs av Gisselns mindre styrkor. De innehåller kvarvarande nekrotisk energi och intresserar Argent Dawn.",al={"dunkla nekrotiska stenar","nekrotiska stenar","vad är nekrotiska stenar"}},{q="Vilken roll spelar Argent Dawn i det här uppdraget?",a="Argent Dawn är en självständig orden som bekämpar Gisslet var det än visar sig. Lieutenant Orrin samarbetar med orden för att säkra information och stenar åt dess krig mot Lich Kings arméer.",al={"argent dawn","argent dawns koppling"}},{q="Är det farligt att närma sig runcirklarna?",a="Cirklarna utstrålar en oroande energi och disharmoniska viskningar. Försiktiga spejare kan närma sig dem och lära sig om Gisselns kommunikation utan att förlora förståndet.",al={"är runorna säkra","viskningar i runorna"}}},fx={c2a78be7={q="Varför vill Lieutenant Orrin att det här undersöks?",a="The Lich King har släppt lös sina odöda styrkor precis utanför Stormwinds portar, under en hotfull, svävande nekropol. Lieutenant Orrin vet att staden inte har råd att sitta sysslolös medan inkräktare samlas vid tröskeln. Han måste snabbt förstå den märkliga magin bakom deras lysande runringar och decimera deras led innan de odöda får ett permanent fäste utanför kungarikets murar.",al={"varför orrin vill få det här gjort","lieutenant orrins motiv","varför undersöka scourge"}},["9cb0511c"]={q="Vilka skickas du att bekämpa utanför Stormwind?",a="Du strider mot Scourges invaderande styrkor, som har samlats under nekropolen strax utanför staden. Dessa odöda stormtrupper och vidunder har slagit läger vid Stormwinds portar för att skapa kaos och hota kungariket på uppdrag av The Lich King.",al={"vem strider jag mot","vilka är fienderna utanför stormwind","vilka scourge-styrkor finns utanför"}}},fp="36,219,33.265.0,20.249.0,24.195.0,39.206.0,35.155.0,29.139.0,52.202.0,44.164.0"}
P.entries["quest:9261"] = {n="Investigate the Scourge of Ironforge",s="Lieutenant Nevell från Argent Dawn kallar på modiga försvarare när Scourge dyker upp precis utanför Ironforges portar. Odöda trupper och hotfulla runcirklar hotar Dun Moroghs snöiga bergspass under en svävande nekropol. Försvararna ska förgöra de vandrande liken och ta reda på vad de märkligt lysande sigillen är till för.",h="Lieutenant Nevell från Argent Dawn kallar på modiga försvarare när Scourge dyker upp precis utanför...",kw={"argent dawn","dimmig nekrotisk sten","dun morogh","undersök scourges angrepp mot ironforge","ironforge","lich king","lieutenant nevell","nekropol","runcirkel","scourge"},ang={["class:Paladin"]="Scourge är den heliga Ljusets raka motsats. Att undersöka Lich Kings runiska ondska och rena bort hans viljelösa slavar hör helt och hållet till en paladins heliga uppdrag.",["class:Priest"]="De psykiska ekon som mumlar genom runcirklarna utgör en tydlig fara för vanliga soldaters förstånd. Det krävs andlig styrka för att stå emot dem.",["faction:Alliance"]="Ironforge är en viktig ekonomisk och militär grundpelare för Alliansen. Ett fäste för odöda vid dess portar hotar försörjningslinjerna genom Eastern Kingdoms.",["race:Dwarf"]="Att vanhelga Dun Moroghs rena snö med ruttnande vidunder är en skymf mot varje dvärg. Att försvara bergsingången handlar om hem och härd."},sec={{t="Döden vid bergsportarna",b="Scourges invasion stannar inte vid Lordaeron eller de pestdrabbade nordliga länderna. Svävande nekropoler kastar dystra skuggor över Azeroth, även över Dun Moroghs iskalla höjder precis utanför Ironforges bergsingång. Argent Dawn har placerat ut observatörer som Lieutenant Nevell för att övervaka och hejda denna krypande farsot innan den kan bryta igenom Bronzebeards fäste."},{t="Oheliga inskrifter",b="Under nekropolens skugga har de odöda slagit läger kring lysande runcirklar och pulserande nekrotiska stenar. När spejare ställer sig nära de hotfulla cirklarna upptäcker de mörka, viskande röster som ekar genom den omgivande magin. Lieutenant Nevell drar slutsatsen att cirklarna fungerar som mörka kanaler för kommunikation, men han vet inte vem Scourge kontaktar."}},faq={{q="Vem är Lieutenant Nevell?",a="Lieutenant Nevell är en officer i Argent Dawn som är stationerad vid Ironforge för att samordna försvaret mot Scourges invasion. Han ger äventyrare i uppdrag att samla in nekrotiska stenar och ta reda på vad de oheliga sigillen kring inkräktarnas läger är till för.",al={"nevell","lieutenant nevell","uppdragsgivare"}},{q="Varför anfaller Scourge Ironforge?",a="Uppdraget gäller Scourge-styrkor som slagit läger utanför Ironforge under en nekropol. Lieutenant Nevell ber försvararna att decimera deras styrkor och undersöka de märkliga runcirklarna i närheten.",al={"scourge utanför ironforge","varför odöda i dun morogh","invasion av ironforge"}},{q="Vad är dimmiga nekrotiska stenar?",a="Dimmiga nekrotiska stenar tas från Scourges inkräktare och lämnas till Argent Dawn som bevis på att odöda har dödats.",al={"nekrotiska stenar","dimmig nekrotisk sten","scourge-stenar"}},{q="Vad är de lysande runcirklarna till för?",a="De lysande runcirklarna finns nära Scourges invasionsstyrkor. Lieutenant Nevell ber dig undersöka vad de är till för.",al={"runcirklar","lysande cirklar","vad är runorna"}}},fx={["4916b51d"]={q="Varför vill Lieutenant Nevell att det här undersöks?",a="Scourge marscherar mot Ironforges tröskel och en nekropol tornar upp sig ovanför. Lieutenant Nevell och Argent Dawn vägrar att stå sysslolösa. Märkliga runringar som glöder av ohelig magi har dykt upp nära de odödas läger utanför portarna. Nevell vet att dessa ritualer bådar illa, och han behöver att du avslöjar vilka onda krafter inkräktarna kanaliserar innan staden drabbas av en ännu större katastrof.",al={"nevells motiv","varför undersöka scourge vid ironforge","varför nevell vill få det här gjort"}},f222933f={q="Vilka skickas du att bekämpa utanför Ironforge?",a="Du skickas mot Scourges förtrupp, som slagit läger precis utanför Ironforges portar. Dessa odöda fasor, utsända på The Lich Kings order och stärkta av en svävande nekropol, vill terrorisera Dun Morogh och belägra dvärgarnas kungarike.",al={"vem ska jag bekämpa","scourges mål vid ironforge","vem strider jag mot"}}},fp="36,188,27.275.0,19.288.1,25.231.0,39.162.0,29.120.0,49.110.0"}
P.entries["quest:9262"] = {n="Investigate the Scourge of Darnassus",s="Investigate the Scourge of Darnassus är ett nöduppdrag från Lieutenant Beitha på uppdrag av Argent Dawn. Med en nekropol som tornar upp sig över Scourge-lägret får Alliansens försvarare i uppgift att förgöra de framryckande odöda och tyda de mörka runringar som dyker upp utanför stadsportarna.",h="Investigate the Scourge of Darnassus är ett nöduppdrag från Lieutenant Beitha på uppdrag av Argent Dawn.",kw={"argent dawn","beitha","darnassus","lich king","nekropol","nekrotisk sten","runring","scourge","teldrassil","odöda"},ang={["class:Druid"]="Nekromantins spridning och förruttnat kött på Teldrassils jord utgör en onaturlig farsot som varje vildmarkens väktare svurit att utrota.",["class:Priest"]="Präster ställs inför det isande provet att undersöka korrumperade nekromantiska runor och använda sin mentala disciplin och tro för att stå emot vansinnet som viskar genom Scourges mörka nätverk.",["faction:Alliance"]="Försvaret av Darnassus visar Alliansens beslutsamhet att stå enad mot det globala hot som Lich Kings invasionsstyrka utgör.",["race:NightElf"]="För kaldorei är ruttnande nekropoler och vanhelgande odöda så nära Teldrassils heliga mark en grotesk kränkning som måste renas bort omedelbart."},sec={{t="En farsot på världsträdet",b="Scourge-invasionen har nått Teldrassils skyddade grenar. Svävande nekropoler visar sig på himlen och kräks ut gastar, skelett och nekromantiska fasor alldeles utanför Darnassus. Lieutenant Beitha från Argent Dawn har trätt fram för att samordna försvaret av huvudstaden och värvar frivilliga som vill hejda förtruppen och samla underrättelser innan de odöda övermannar nattalvernas hemland."},{t="Viskningar i runorna",b="Utöver att dräpa de odöda och samla in deras dunkla nekrotiska stenar får spejare i uppdrag att undersöka märkliga, glödande runformationer som pulserar på marken nära invasionslägren. När försvarare går nära ringarna utsätts de för oroande övernaturliga viskningar, som avslöjar att runorna fungerar som onaturliga kommunikationsreläer, även om Lieutenant Beitha inte vet vem Scourge kontaktar."}},faq={{q="Vem är Lieutenant Beitha?",a="Lieutenant Beitha är en officer från Argent Dawn som är stationerad i Darnassus. Hon organiserar det lokala motståndet mot Scourge-invasionen och delar ut uppgifter för att minska antalet odöda och studera deras nekromantiska utrustning.",al={"vem ger uppdraget investigate the scourge of darnassus","uppdragsgivare beitha","lieutenant beithas bakgrund"}},{q="Varför anfaller Scourge Darnassus?",a="Uppdraget gäller Scourge-styrkor som slagit läger utanför Darnassus under en nekropol. Lieutenant Beitha ber försvararna minska deras antal och undersöka de märkliga runringarna i närheten.",al={"varför finns odöda i darnassus","invasionen av teldrassil","lich king anfaller nattalver"}},{q="Vad är de glödande runringarna utanför staden?",a="De glödande runringarna syns nära Scourges invasionsstyrkor. Lieutenant Beitha ber dig undersöka deras syfte.",al={"scourge-runor darnassus","runringar utanför darnassus","vad är invasionsrunorna"}},{q="Vad är dunkla nekrotiska stenar?",a="Dunkla nekrotiska stenar tas från Scourge-inträngare och förs till Argent Dawn som bevis på att odöda har dräpts.",al={"nekrotiska stenar","vad gör nekrotiska stenar","bakgrund om dim necrotic stone"}},{q="Vem finansierar eller leder försvaret i Darnassus?",a="Argent Dawn samordnar undersökningen genom Lieutenant Beitha. Orden är hängiven åt kampen mot Scourge.",al={"vem leder försvaret av darnassus","argent dawn darnassus"}},{q="Kan det skada dig att lyssna på runringarna?",a="Deras exakta effekter är inte fastställda. Beitha ber försvararna undersöka den märkliga energin kring ringarna.",al={"viskningar från runringar","är röster från runringar farliga"}}},fx={["39b377fd"]={q="Varför vill Lieutenant Beitha att det här görs?",a="The Lich King har sänt en odöd invasion ända fram till Teldrassils tröskel, med en hotfull nekropol ovanför Darnassus som bas. Lieutenant Beitha och Argent Dawn vägrar stå sysslolösa medan vidunder samlas utanför stadsportarna. Hon behöver att du decimerar deras led för att lätta trycket på huvudstaden, tar med bevis på att de har förstörts och avslöjar det mörka syftet bakom de lysande runringar som stärker deras läger.",al={"beithas motiv","varför undersöka scourge","varför beitha vill få det här gjort"}},a5f671f0={q="Vilka skickas du att bekämpa utanför Darnassus?",a="Du skickas mot Scourges invaderande styrkor, som har slagit läger precis utanför Darnassus. Dessa odöda trälar och vidunder har sänts direkt av The Lich King under skuggan av en svävande nekropol. De försöker få ett fotfäste och hota nattalvernas huvudstad.",al={"vem strider jag mot","vilka scourge-styrkor finns utanför darnassus","vilka är inkräktarna"}}},fp="36,187,26.352.0,21.290.1,25.185.0,39.160.0,52.111.0,29.113.0,52.118.0,44.109.0"}
P.entries["quest:9263"] = {n="Investigate the Scourge of Orgrimmar",s="Utanför Orgrimmar har Scourge slagit läger under en svävande nekropol. Lieutenant Dagel kallar på försvarare att slå tillbaka de odöda, återta nekrotiska stenar och undersöka runringar laddade med nekromantisk energi. Angreppet för Lich Kings räckvidd till Durotar.",h="Utanför Orgrimmar har Scourge slagit läger under en svävande nekropol.",kw={"argent dawn","dagel","durotar","invasion","lich king","nekrotisk sten","orgrimmar","runring","the scourge"},ang={["faction:Horde"]="En Scourge-styrka som slagit läger inom synhåll från Orgrimmars torn är en förolämpning Horden inte kan tåla. Varje svuren mästare har en plikt att försvara Durotar från Lich Kings undersåtar.",["race:Orc"]="Orcherna vann Durotars torra, röda jord genom umbäranden och blod. De tänker inte låta tanklösa vidunder vanställa hemmet de huggit ut med sina bara händer.",["race:Undead"]="För Forsaken väcker Scourge minnen av deras forna slaveri. Att krossa inkräktarna är en personlig vendetta mot Lich Kings fortsatta räckvidd."},sec={{t="Odöda vid portarna",b="Scourge hotar nu länder långt från Lordaeron och den nordliga isen. Svävande nekropoler kastar sina skuggor över Azeroth, till och med över Durotar. Odöda styrkor har samlats vid Orgrimmars portar och slagit läger som hotar Hordens huvudstad. Lieutenant Dagel och Argent Dawn samordnar försvaret och kallar på lokala mästare att driva tillbaka inkräktarna innan de kan inleda en belägring."},{t="Nekrotiska reliker och mörka viskningar",b="Scourges läger rymmer dunkla nekrotiska stenar och glödande runringar. Ringarna omger lägret och bär samma mörka kraft som nekropolen ovanför. De som kliver in i runorna hör onaturliga röster eka genom etern. Rösterna antyder någon form av kommunikation, men Dagel vet inte vem de når."}},faq={{q="Varför anfaller The Scourge Orgrimmar?",a="Scourge-styrkor har slagit läger utanför Orgrimmar under en nekropol. Lieutenant Dagel ber försvarare decimera deras led och undersöka de närliggande runringarna.",al={"varför the scourge orgrimmar","odöda utanför org","lich king anfaller orgrimmar"}},{q="Vem är Lieutenant Dagel?",a="Lieutenant Dagel är en officer som samordnar med Argent Dawn för att samla försvarare mot invasionen. Från en plats nära hotet leder Dagel krigare i att döda de odöda och undersöka deras magiska redskap.",al={"lieutenant dagel","dagel uppdragsgivare","vem är dagel"}},{q="Vad är de dunkla nekrotiska stenarna?",a="Dunkla nekrotiska stenar tas från Scourge-inkräktare och förs till Argent Dawn som bevis på att odöda har dödats.",al={"nekrotiska stenar","vad är dunkla nekrotiska stenar","dunkla stenar"}},{q="Vad är de glödande runringarna utanför staden?",a="De glödande ringarna bär samma märkliga energi som de närliggande odöda och nekropolen. Dagel ber försvarare undersöka deras syfte.",al={"runringar","glödande runor org","scourge-ringar"}},{q="Varför är Argent Dawn i Durotar?",a="Argent Dawn är en självständig orden som ägnar sig åt att förgöra Scourge var den än visar sig. Orden samarbetar med Hordens försvarare för att skydda Orgrimmars gränser från invasionen.",al={"argent dawn i orgrimmar","varför argent dawn här","argent dawn horden"}},{q="Är nekropolen ovanför staden farlig?",a="Nekropolen tornar upp sig över Scourges läger och delar dess märkliga energi. Dess närvaro gör hotet från de odöda nära staden oroande.",al={"svävande fästning org","nekropol ovanför durotar"}}},fx={["4fe35d0b"]={q="Varför vill Lieutenant Dagel att Scourge undersöks?",a="The Lich Kings undersåtar samlas precis utanför Orgrimmars portar under en hotfull nekropol, och Lieutenant Dagel vet att staden inte kan stå sysslolös. Han fruktar den vidriga magi inkräktarna smider i sina läger. Genom att avslöja syftet med deras märkliga, lysande runringar och decimera den annalkande horden hoppas Dagel få viktig information om Scourges mörka planer och avvärja en katastrofal belägring av Durotar.",al={"varför dagel vill det här","dagels motiv","varför undersöka scourge"}},["76cd191d"]={q="Vilka skickas du att bekämpa utanför Orgrimmar?",a="Du skickas mot de annalkande odöda styrkorna som sänts av The Lich King och slagit läger precis utanför Orgrimmar, under en svävande nekropol. Dessa viljelösa vidunder och vidriga vandrande döda ingår i en samordnad invasion som hotar Kalimdor. De etablerar vidriga arkana fästen i öknen för att försvaga Hordens försvar och terrorisera Durotar.",al={"vilka strider vi mot","scourge-fiender utanför orgrimmar","vem ska jag döda åt dagel"}}},fp="36,274,19.396.0,33.327.1,39.164.0,24.201.0,33.120.0,52.136.0,43.181.0,49.135.0"}
P.entries["quest:92640"] = {n="Desperate Times",s="Desperate Times ber spelarna rapportera till Valennia Stormfist i Valanaar för att planera ett direkt angrepp mot en farlig kults helgedom. Eftersom det inte går att konfrontera kulten öppet är det avgörande att slå ut dess ledare Lorthuna vid helgedomen, men det kräver att de djupa motsättningarna mellan Windshapers och High Order överbryggas.",h="Desperate Times ber spelarna rapportera till Valennia Stormfist i Valanaar för att planera ett direkt angrepp...",kw={"kult","desperate times","high order","lorthuna","helgedom","valanaar","valennia stormfist","windshapers"},sec={{t="Ett direkt angrepp",b="När kulten inte kan konfronteras säkert öppet måste försvararna byta till en djärvare strategi. I stället för en utdragen strid på ofördelaktig mark går planen ut på att utnyttja en öppning och slå direkt mot kultens helgedom. Om Lorthuna elimineras innan hon fullgör sin roll i deras storslagna plan kan hotet slås ut vid källan."},{t="Enade splittrade fraktioner",b="I Valanaar har Valennia Stormfist länge utarbetat en strategi för att anfalla helgedomen. Men räden kan inte lyckas utan betydande förstärkningar och samlad styrka. Ett angrepp kräver att allvarliga politiska motsättningar överbryggas, eftersom de kvarstående spänningarna mellan Windshapers och High Order hotar den allians som behövs för att genomföra anfallet."}},faq={{q="Vem är Valennia Stormfist?",a="Valennia Stormfist är en ledare eller strateg i Valanaar. Hon har ägnat tid åt att utveckla en taktisk plan för att anfalla helgedomen där kulten håller till, men för att genomföra den måste klyftan mellan rivaliserande fraktioner överbryggas.",al={"vem är valennia","valennia stormfist","var finns valennia"}},{q="Vem är Lorthuna?",a="Lorthuna är en central person i den fientliga kulten. Hon håller just nu på att genomföra en viktig plan vid helgedomen, vilket gör henne till huvudmålet för det föreslagna förebyggande anfallet.",al={"vem är lorthuna","lorthunas bakgrund","kultledaren lorthuna"}},{q="Varför måste helgedomen angripas direkt?",a="Att angripa kulten direkt i det öppna anses omöjligt eller självmordsbenäget. Ett direkt angrepp mot deras helgedom ger det bästa strategiska tillfället att oskadliggöra Lorthuna innan hennes plan kan förverkligas.",al={"varför anfalla helgedomen","orsaken till kultanfallet"}},{q="Vad är problemet mellan Windshapers och High Order?",a="Spänningarna är just nu stora mellan Windshapers och High Order. Trots motsättningarna påpekar Valennia att ingen av fraktionerna ensam kan hoppas lyckas med ett angrepp mot helgedomen; båda måste samarbeta.",al={"spänningar mellan high order och windshapers","varför strider fraktionerna","windshapers tvist"}},{q="Var ligger Valanaar?",a="Valanaar fungerar som utgångspunkt där Valennia Stormfist samordnar strategin och samlar nödvändiga allierade inför det kommande anfallet mot kultens helgedom.",al={"var ligger valanaar","valanaars plats"}},{q="Vad är det övergripande målet med uppdraget?",a="Målet är att söka upp Valennia Stormfist i Valanaar, ta reda på detaljerna kring hennes planerade angrepp mot helgedomen och bidra till att säkra det nödvändiga samarbetet mellan de splittrade fraktionerna.",al={"desperate times mål","vad är planen i desperate times"}}},fp="15,195,15.304.0,24.282.0,26.153.0,16.140.0,41.140.0,61.148.0,18.121.0,41.150.0"}
P.entries["quest:92642"] = {n="Disrupting Logistics",s="Disrupting Logistics ger äventyrare i uppdrag att hejda ett fullskaligt anfall från Al'Aketh-kultister i Gustberry Lowlands. Genom att slå ut fiendens helare, som håller frontens slagskämpar vid liv, hjälper spelarna de hårt trängda lokala försvararna att vända striden innan deras linjer kollapsar.",h="Disrupting Logistics ger äventyrare i uppdrag att hejda ett fullskaligt anfall från Al'Aketh-kultister i...",kw={"al'aketh","slagskämpar","kultister","disrupting logistics","gustberry lowlands","helare","valennia"},ang={["class:Priest"]="Präster vet hur viktigt helande stöd är för att hålla en anfallslinje uppe, vilket gör Al'Akeths helare till kultisternas offensivs nyckel.",["class:Rogue"]="Att smyga bakom fiendens linjer för att slå ut viktiga helare och störa förstärkningar till förtruppen är vanlig taktisk sabotageverksamhet för skurkar."},sec={{t="Ett desperat försvar",b="Ett våldsamt anfall hotar att övermanna försvararna som är stationerade ovanför Gustberry Lowlands. Fiendestyrkor samlas och de lokala linjerna pressas till bristningsgränsen, så frontens befälhavare börjar misströsta. Försvararna väntar sig betydande förstärkningar från Valennia, men tvingas förlita sig på vilka kapabla händer som än dyker upp. De hoppas att precisa angrepp mot fiendens stödnätverk kan förhindra en nära förestående kollaps."},{t="Bryt kultisternas linje",b="Al'Akeths anfall bygger på samordnade led av våldsamma slagskämpar, med hängivna helare som läker sår och håller trycket vid fronten uppe. I Gustberry Lowlands bryter det kultisternas offensiv när helarna slås ut. Då skärs deras uthållighet av, och försvararna får en chans att samla sig och slå tillbaka invasionen."}},faq={{q="Vad är uppdraget Disrupting Logistics?",a="Disrupting Logistics är ett brådskande försvarsuppdrag som ska hejda ett fullskaligt anfall från Al'Aketh-kultister i Gustberry Lowlands. En ensam försvarare håller stånd och behöver omedelbar hjälp med att slå ut fiendens stöd vid fronten innan försvaret kollapsar helt.",al={"vad är disrupting logistics","uppdraget disrupting logistics","uppdrag i gustberry lowlands"}},{q="Vilka är Al'Aketh-kultisterna som anfaller låglandet?",a="Anfallarna är Al'Aketh-kultister, med aggressiva slagskämpar och stödjande helare som driver ett pågående anfall in i Gustberry Lowlands. Deras samordnade front är starkt beroende av hängivna helare för att hålla ett oavbrutet tryck mot de lokala försvararna.",al={"vilka är alaketh","vem anfaller gustberry lowlands","vilka är kultisterna"}},{q="Varför är Al'Akeths helare särskilt utvalda mål?",a="Al'Akeths helare ger ett kontinuerligt helande stöd som låter förtruppens krigare storma fram utan uppehåll. Genom att slå ut helarna hoppas försvaret bryta anfallets momentum och skapa en öppning för att samla sig och driva kultisterna tillbaka.",al={"varför döda helare","varför rikta in sig på alakeths helare"}},{q="Var äger anfallet rum?",a="Gustberry Lowlands ligger precis nedanför den försvarspost som kultisterna belägrar. Området är nu översvämmat av Al'Akeths slagskämpar och helare, som driver sitt anfall framåt.",al={"var ligger gustberry lowlands","gustberry lowlands plats"}},{q="Vem är Valennia?",a="Valennia verkar vara en ledare eller samordnare med ansvar för att organisera hjälp och förstärkningar. Försvararen är dock frustrerad över att Valennia bara lyckades skicka en enda äventyrare för att möta ett massivt anfall.",al={"vem är valennia","valennia förstärkningar"}},{q="Vem leder försvaret mot Al'Aketh?",a="Uppdraget erbjuds av en hårt trängd försvarare vars folk är på väg att övermannas av Al'Aketh-kultisterna. Försvararen visar vördnad för ”vindarna” och är desperat efter alla stridskrafter som kan vända striden.",al={"vem ger disrupting logistics","vilka är mina folk som håller stånd"}}},fp="20,178,19.351.0,25.239.0,39.198.0,53.171.0,51.183.0,35.192.0,16.146.0,46.183.0"}
P.entries["quest:92643"] = {n="The Turncoat",s="The Turncoat handlar om en Al'Aketh-kultist som försöker hoppa av och byta kultens verkliga avsikter med ön mot en fristad. Resenärer skickas för att hämta honom från ett avskilt gömställe i högländerna nordväst om Valanaar. De måste ta reda på om detta hemliga möte är ett verkligt genombrott eller en dödlig fälla.",h="The Turncoat handlar om en Al'Aketh-kultist som försöker hoppa av och byta kultens verkliga avsikter med ön...",kw={"al'aketh","kultist","avhoppare","högländerna","the turncoat","valanaar"},ang={["class:Rogue"]="Infiltration, avhopp och bakhåll hör till välbekant mark. Kultister som bryter leden väntar sig tystnad eller ett hugg, och lönnmördarna utanför visar att hemlighetsmakeriet gick åt båda hållen i högländerna."},sec={{t="Eden som bröts",b="En hemlig kontakt inom Al'Aketh erbjuder en sällsynt möjlighet att genomskåda kultens hemlighetsmakeri. En kultist hävdar att han känner till organisationens verkliga avsikter med ön, har brutit sin trohet och erbjudit sig att hoppa av. I utbyte kräver han säkra löften om beskydd. Med tanke på hur väl kulten skyddar sina planer är varje spår in i dess inre värt risken att ta kontakt."},{t="Gömstället i högländerna",b="Avhopparen flydde till en avskild bostad i högländerna nordväst om Valanaar och väntar ensam på en diskret eskort. För att nå honom måste du ta dig försiktigt in bland kullarna. Mötet innebär en tydlig risk för ett Al'Aketh-bakhåll, utformat för att locka fram nyfikna motståndare."},{t="Tystnad i högländerna",b="Hoppet om ett fredligt undsättande krossas när du kommer fram till det avskilda huset i högländerna. Lönnmördare har redan spårat upp avhopparen och dödat honom innan någon eskort hunnit fram. Bland spåren efteråt och de fallna lönnmördarna utanför fångar en glimtande reflex på den döde avhopparens kropp blicken. Kanske har han ändå lämnat ett svar efter sig."}},faq={{q="Vem är avhopparen?",a="Avhopparen är en före detta medlem av Al'Aketh-kulten som påstod sig ha avgörande kunskap om kultens verkliga avsikter med ön. I utbyte mot beskydd erbjöd han sig att hoppa av och avslöja vad han visste.",al={"vem är avhopparen","vem var avhopparen","avhopparens identitet"}},{q="Vad är Al'Aketh?",a="Al'Aketh är en gåtfull kult som verkar i trakten. Deras hemliga planer och slutliga mål med ön förblir dolda bakom sträng sekretess och fanatism. Därför tar de lokala myndigheterna stora risker för att hämta avhoppare som är villiga att tala.",al={"vilka är alaketh","alaketh-kulten","vad är alaketh"}},{q="Var gömmer sig avhopparen?",a="Avhopparen tog sin tillflykt till en avskild bostad strax nordväst om Valanaar, inbäddad i högländerna. Det avlägsna huset valdes som gömställe medan han väntade på att bli hämtad, efter löften om beskydd.",al={"var gömmer sig avhopparen","avhopparens plats","var hittar man avhopparen"}},{q="Vad hände med avhopparen?",a="När någon nådde den avskilda bostaden i högländerna hade lönnmördare redan spårat upp och dödat avhopparen. Allt hopp om att förhöra honom medan han levde försvann när hans kropp hittades inne i huset.",al={"vad hände med avhopparen","dog avhopparen","vem dödade avhopparen"}},{q="Vad lämnade avhopparen efter sig?",a="När du undersöker den döde avhopparens kropp efter att ha gjort dig av med lönnmördarna utanför fångar något glittrande blicken. Föremålet han bar på blev kvar och antyder att hans hemligheter kanske inte dog helt med honom.",al={"vilket glänsande föremål","avhopparens glänsande föremål","glittrande reflex på kroppen"}},{q="Varför bestämde sig kultisten för att hoppa av?",a="Kultisten säger sig känna till Al'Akeths verkliga avsikter med ön och går bara med på att överlämna sig om han får löften om beskydd. Uppdraget säger inte vad som fick honom att hoppa av.",al={"varför hoppade kultisten av","avhopparens motiv","varför förråda alaketh"}}},fp="12,206,13.233.0,20.213.0,24.246.1,20.188.0,21.197.0,29.147.0,30.166.0,35.168.0,37.171.0"}
P.entries["quest:92644"] = {n="Unfortunate News",s="Unfortunate News är ett uppdrag i WoW Forever som följer på ett försök att kontakta en avhoppande kultist. När äventyraren anländer är informatören redan död. Äventyraren hittar en skadad, lysande blå kristall på kroppen och lämnar den till High Elder Talanaanis Shadowsong i Valanaar.",h="Unfortunate News är ett uppdrag i WoW Forever som följer på ett försök att kontakta en avhoppande kultist.",kw={"kultist","lysande kristall","shadowsong","talanaanis shadowsong","avhoppare","unfortunate news","valanaar"},ang={["class:Mage"]="Den återfunna artefakten är en skadad, lysande blå kristall som hittats hos en kultist. Den antyder att kultisterna ägnar sig åt magiska eller mystiska bruk som High Elder Shadowsong undersöker."},sec={{t="Ett misslyckat möte",b="I WoW Forever skildrar ”Unfortunate News” de dystra följderna av ett försök att möta en avhoppande kultist. En äventyrare som skickats för att träffa avhopparen upptäcker att informatören redan har dödats. Kroppen är fortfarande varm när äventyraren kommer fram. Under liket ligger en liten, lysande blå kristall. Den är skadad, men utstrålar fortfarande tillräckligt mycket närvaro för att motivera en omedelbar rapport till High Elder Talanaanis Shadowsong i Valanaar."},{t="Shadowsongs undersökning",b="När äventyraren återvänder ensam till Valanaar berättar hen att avhopparen dog innan något vittnesmål kunde samlas in. Förlusten av en levande kontakt är ett allvarligt bakslag, men den återfunna blå kristallen fångar High Elders uppmärksamhet. Han finner den skadade kristallen intressant och tar den från dig."}},faq={{q="Vad är uppdraget Unfortunate News?",a="”Unfortunate News” är ett uppdrag i WoW Forever som handlar om en avhoppande kultists död. När du upptäcker att avhopparen har dödats hittar du en mystisk, lysande kristall på liket och rapporterar tillbaka till High Elder Shadowsong.",al={"vad är unfortunate news","uppdraget unfortunate news","unfortunate news wow forever"}},{q="Vem var den avhoppande kultisten?",a="Avhopparen var en kultist som en äventyrare skickades för att träffa eller föra i säkerhet. Men kultisten dödades innan hen hann tala eller fly, och lämnade bara efter sig sitt fortfarande varma lik och en skadad kristall.",al={"vem är den döda avhopparen","vem dog i unfortunate news","avhoppande kultist"}},{q="Vem är High Elder Shadowsong?",a="Talanaanis Shadowsong är en alv och High Elder i Valanaar. Han leder undersökningar av kultisterna och tar emot den skadade kristall som hittas på avhopparens kropp.",al={"vem är shadowsong i valanaar","var finns talanaanis shadowsong","talanaanis shadowsong"}},{q="Vad är den skadade blå kristallen?",a="Det är en liten, lysande blå kristall som hittas under den fallna kultisten som hoppat av. Trots att den är synligt skadad finner High Elder Shadowsong den intressant och ser den som en ledtråd värd att undersöka vidare.",al={"vad är den lysande kristallen","blå kristall från kultist","skadad kristall unfortunate news"}},{q="Var utspelar sig uppdraget?",a="Valanaar är bosättningen eller utposten där High Elder Talanaanis Shadowsong bor och dit du återvänder för att lämna din rapport och den tillvaratagna kristallen.",al={"var ligger valanaar","valanaars plats","lämna in unfortunate news"}},{q="Hur hänger det här uppdraget ihop med The Turncoat?",a="Det här uppdraget följer direkt efter ”The Turncoat”, där en äventyrare ger sig av för att hitta den avhoppande kultisten, men kommer för sent för att rädda hen.",al={"vilket uppdrag kommer före unfortunate news","föregångare till unfortunate news","uppdraget the turncoat"}}},fp="16,164,19.232.0,26.275.1,35.166.0,29.160.0,29.166.0,33.153.0,33.120.0,44.112.0"}
P.entries["quest:92645"] = {n="Breaking the Breaker",s="Breaking the Breaker är ett desperat militärt anfall mot Commander Belguilos, en skräckinjagande före detta fredsväktare som nu leder ett farligt kultangrepp i Gustberry Lowlands. Att döda henne vid hennes villa på sluttningen ger de hårt ansatta försvararna deras enda verkliga chans att överleva anfallet.",h="Breaking the Breaker är ett desperat militärt anfall mot Commander Belguilos, en skräckinjagande före detta...",kw={"belguilos","breaking the breaker","commander belguilos","kultbefälhavare","gustberry lowlands","fredsväktare","the breaker","villa"},ang={["class:Warrior"]="Att möta Commander Belguilos innebär att ta sig an en aggressiv före detta fredsväktare som gjort sig förtjänt av den fruktade titeln ”the Breaker”.",["race:Skyborne"]="Åkallan av de fyra vindarna för att välsigna hjälten speglar Skyborne-kulturens traditioner och trosföreställningar när den står emot farliga kultister i låglandet."},sec={{t="Ett desperat försvar",b="Gustberry Lowlands utsätts för ett intensivt angrepp av aggressiva kultister, och de lokala försvararna pressas till gränsen för sin överlevnad. Att slå tillbaka anfallet verkar nästan omöjligt utan att slå till direkt mot operationens ledare: Commander Belguilos, som alla fruktar som ”the Breaker”. Att döda henne vid hennes basvilla anses vara en farlig, nästan självmordsbenägen uppgift, men passivitet garanterar försvararnas undergång."},{t="Den fallna fredsväktaren",b="Långt innan hon tog befälet över kultisthären upprätthöll Belguilos ordningen som fredsväktare. Ändå märkte de omkring henne redan då något djupt oroande i hennes uppförande. När kultens inflytande spred sig okontrollerat anammade hon dess extremism fullt ut. Nu är hon kultens befälhavare och en veritabel skräck."}},faq={{q="Vem är Belguilos the Breaker?",a="Belguilos, känd som ”the Breaker”, är en mäktig befälhavare som leder ett kultistangrepp. Innan hon anslöt sig till kulten tjänstgjorde hon som fredsväktare, men de som levde samtidigt med henne minns att hon redan då var djupt oroande och våldsbenägen.",al={"vem är belguilos","vem är the breaker","kultbefälhavare"}},{q="Var finns Commander Belguilos?",a="Commander Belguilos är stationerad i villan vid foten av kullen i Gustberry Lowlands. Därifrån kan hon samordna kultisternas offensiv mot de lokala försvararna.",al={"var finns belguilos","belguilos plats","var hittar man the breaker"}},{q="Varför måste Belguilos dödas?",a="De lokala försvararna utsätts för ett anfall från kultister som nästan inte går att slå tillbaka medan Belguilos leder angreppet. Om hon dödas bryts kultens ledarskap, vilket ger försvararna en verklig chans att överleva.",al={"varför döda belguilos","orsak till kultangreppet","varför är the breaker farlig"}},{q="Vad var Belguilos innan hon anslöt sig till kulten?",a="Belguilos tjänstgjorde ursprungligen som fredsväktare innan kulten spårade ur. De som kände henne tyckte dock att hon var märkbart ”underlig” redan när hon upprätthöll ordningen. Därför är hennes senare uppgång till brutal kultledare föga förvånande.",al={"vad var belguilos tidigare","var belguilos god","fredsväktare kultist"}},{q="Vad betyder välsignelsen från de fyra vindarna?",a="Välsignelsen åkallar de fyra vindarna, ett traditionellt uttryck för djup lättnad och tacksamhet. Försvararna använder det när de får veta att den skräckinjagande kultbefälhavaren har stoppats för gott.",al={"de fyra vindarnas betydelse","vem säger de fyra vindarna välsigne dig"}},{q="Vad är Gustberry Lowlands?",a="Gustberry Lowlands är det omstridda område där kultangreppet pågår. Vid foten av kullen ligger en villa där Commander Belguilos kan hittas.",al={"vad är gustberry lowlands","var finns uppdraget the breaker"}}},fp="20,195,19.329.0,22.276.0,29.175.0,39.158.0,33.180.0,50.158.0,59.166.0,32.144.0"}
P.entries["quest:92646"] = {n="Confront Lorthuna",s="Confront Lorthuna skildrar jakten på översteprästinnan Lorthuna, som flyr genom en portal till Rohashi Spires ovanför Zephras. Äventyrarna ska förstärka Elaadrin Evengale och Ayessa Dawnsinger i en desperat strid högt ovanför ön. Efter striden är viktiga försvarare skadade, och Zephras framtida säkerhet är oviss.",h="Confront Lorthuna skildrar jakten på översteprästinnan Lorthuna, som flyr genom en portal till Rohashi Spires...",kw={"ayessa dawnsinger","confront lorthuna","elaadrin evengale","översteprästinnan lorthuna","lorthuna","muln","rohashi spires","valennia","windshapers","zephras"},ang={["class:Priest"]="Översteprästinnan Lorthuna står för ett korrumperat andligt ledarskap bland spirorna, vilket gör striden mot henne särskilt betydelsefull för präster som försvarar sig mot mörka läror.",["class:Shaman"]="Muln och Windshapers vägleder den elementära balansen på Zephras, så schamaner har ett starkt andligt intresse av att öns elementära harmoni överlever Lorthunas hot."},sec={{t="Jakten till spirorna",b="Översteprästinnan Lorthuna flyr genom en mystisk portal upp till Rohashi Spires ovanför. En skadad allierad lämnas kvar vid portalens tröskel, medan Elaadrin Evengale och Ayessa Dawnsinger genast följer efter upp i höjden. De ropar på alla stridsdugliga hjältar att komma igenom och hjälpa dem innan Lorthuna undkommer rättvisan eller stärker sin makt."},{t="Stridens pris",b="Efter den farliga sammandrabbningen i spirorna är försvararna hårt åtgångna. Valennia och hennes överlevande styrkor behöver omedelbar vård av helare och förs tillbaka till High Elder's residence för att återhämta sig. Lorthuna möts i strid, men insatsen lämnar koalitionen sargad och dess resurser hårt ansträngda."},{t="En utsatt ö",b="När den omedelbara striden är över återvänder Muln till Azeroths fastland efter att ha diskuterat Windshapers framtid och deras fortsatta uppdrag. Men segern innebär ingen fred: efter striden är Zephras kritiskt utsatt, och de kvarvarande ledarna måste skyndsamt planera försvar mot de faror som väntar."}},faq={{q="Vem är översteprästinnan Lorthuna?",a="Översteprästinnan Lorthuna är en mäktig motståndare som flydde genom en portal till Rohashi Spires ovanför Zephras. Hennes handlingar utgjorde ett så allvarligt hot att viktiga försvarare, däribland Ayessa Dawnsinger och Elaadrin Evengale, följde efter henne för att besegra henne.",al={"vem är lorthuna","vad är lorthuna","översteprästinnan lorthunas bakgrund"}},{q="Vad är Rohashi Spires?",a="Rohashi Spires är högt belägna klippor som tornar upp sig ovanför ön Zephras. De nås via en portal och blev slagfältet dit översteprästinnan Lorthuna flydde för att ta strid.",al={"vad är rohashi spires","vart leder portalen","rohashi spires plats"}},{q="Vem följde efter Lorthuna genom portalen?",a="Elaadrin Evengale och Ayessa Dawnsinger var först genom portalen i jakten på översteprästinnan Lorthuna när hon flydde upp mot spirorna. De bad om förstärkning, och äventyraren följde efter.",al={"vem följde efter lorthuna","ayessa och elaadrin","vem går in i portalen"}},{q="Vad hände med Valennia och hennes styrkor?",a="Valennia ledde styrkor under konfrontationen och skadades svårt i striderna. Efteråt skickades helare dit för att säkerställa att hon kom tillbaka i trygghet, och hon fördes till High Elder's residence för att vila.",al={"vem är valennia","vad hände med valennia","valennas styrkor"}},{q="Vilken roll har Muln i händelserna?",a="Muln är en allierad med koppling till Windshapers, som hjälpte till på Zephras innan han återvände till Azeroths fastland. Innan han gav sig av diskuterade han Windshapers framtidsplaner och deras större uppdrag.",al={"vem är muln","muln lämnar zephras","vart tog muln vägen"}},{q="Är Zephras tryggt efter konfrontationen med Lorthuna?",a="Även efter konfrontationen med översteprästinnan Lorthuna är Zephras i ett utsatt läge. Ön är mer sårbar än någonsin, och försvararna måste utarbeta nya planer för att skydda den mot hot som närmar sig.",al={"vad händer med zephras","är zephras tryggt nu","zephrasöarnas tillstånd"}}},fp="17,204,23.295.0,22.248.1,25.257.1,31.169.0,28.138.0,37.141.0,41.156.0,36.134.0,59.146.0"}
P.entries["quest:92679"] = {n="Blood Tithe",s="Blood Tithe är ett uppdrag som Alvarion Windfield, en sjuklig Skyborne-bonde, inleder när han söker hjälp i bosättningen Valanaar. I sin desperation att skydda sin försörjning rekryterar han äventyrare som ska resa västerut till hans fruktträdgård i låglandet och hjälpa hans fru, Aamelia.",h="Blood Tithe är ett uppdrag som Alvarion Windfield, en sjuklig Skyborne-bonde, inleder när han söker hjälp i...",kw={"aamelia windfield","alvarion windfield","blood tithe","skyborne","valanaar","windfield orchard"},ang={["race:Skyborne"]="Alvarion Windfield är en Skyborne-bonde vars fysiska lidande och desperata vädjan om hjälp belyser de svårigheter som vanliga Skyborne möter utanför bosättningen Valanaar."},sec={{t="En vädjan i Valanaar",b="I bosättningen Valanaar söker en skadad Skyborne vid namn Alvarion Windfield desperat efter dugliga äventyrare. Alvarion plågas av synlig smärta och har rest från sitt hem till staden för att leja stridsvana personer som kan rädda hans försörjning. I stället för att ge resande uppgifter på plats vädjar han till dem som vill hjälpa att bege sig västerut till låglandet, där hans fru Aamelia sköter familjens fruktträdgård."},{t="Problem i låglandet",b="Windfield Orchard ligger i låglandet väster om Valanaar. Eftersom Alvarion är oförmögen att arbeta på grund av sitt svåra lidande faller ansvaret för gården på Aamelia Windfield. Äventyrare som antar Alvarions erbjudande måste ta sig till den västra dalen för att ta reda på vad som hotar fruktträdgården och hjälpa den hårt ansatta familjen."}},faq={{q="Vem är Alvarion Windfield?",a="Alvarion Windfield är en Skyborne-bonde som har kommit till Valanaar för att hitta dugliga stridskämpar som kan skydda hans hem. Trots att han lider av svår fysisk smärta lyckas han hänvisa äventyrarna till sin fru, Aamelia, vid deras fruktträdgård.",al={"vem är alvarion","alvarion windfields bakgrund","vem ger blood tithe"}},{q="Var ligger Windfield Orchard?",a="Windfield Orchard ligger väster om Valanaar, nere i låglandet. Alvarion skickar dit äventyrare för att träffa sin fru, Aamelia Windfield, som leder gårdens omedelbara försvar.",al={"var ligger windfield orchard","var finns aamelia windfield","hur hittar man fruktträdgården"}},{q="Varför har Alvarion ont?",a="När man träffar honom säger han inte vad han lider av, men Alvarion plågas tydligt av intensiv, förlamande smärta när han talar. Det gör hans vädjan om hjälp än mer brådskande.",al={"varför har alvarion ont","vad är det för fel på alvarion","alvarions smärta"}},{q="Vem är Aamelia Windfield?",a="Aamelia Windfield är Alvarions fru och befinner sig vid familjens fruktträdgård väster om Valanaar. Alvarion hänvisar villiga äventyrare till henne så att hon kan organisera försvaret av deras mark.",al={"vem är aamelia","aamelia windfields bakgrund","alvarions fru"}},{q="Vad går uppdraget Blood Tithe ut på?",a="Blood Tithe börjar med att Alvarion Windfield rekryterar resande i Valanaar för att hjälpa hans utsatta gård. Äventyrarna måste lyssna på hans önskemål och söka upp hans fru Aamelia vid deras fruktträdgård i låglandet.",al={"sammanfattning av uppdraget blood tithe","vad handlar blood tithe om","gård under attack i valanaar"}},{q="Vilken betydelse har Valanaar här?",a="Valanaar är en bosättning där resande och Skyborne samlas. Alvarion besöker denna samlingsplats särskilt för att hitta lejda hjälpare och äventyrare som kan rädda hans fruktträdgård från faran.",al={"valanaars bakgrund","var utspelar sig blood tithe","vad är valanaar"}}},fp="11,208,18.270.0,23.239.0,26.183.0,39.163.0,24.149.0,25.143.0,32.131.0,37.139.0"}
P.entries["quest:92682"] = {n="Make Yourself Useful",s="Make Yourself Useful är ett uppdrag på Windfield Orchard där äventyrare hjälper till att skydda stormäppleskörden mot odisciplinerade banditer. En utpressare vid namn Ferauu ska hämta sin vanliga andel av skörden, men hungriga fredlösa har lämnat leden för att plundra träden i förväg. När du tar hand om dessa tjuvar vinner du den vaksamme fruktodlarens respekt.",h="Make Yourself Useful är ett uppdrag på Windfield Orchard där äventyrare hjälper till att skydda...",kw={"banditer","ferauu","hungriga banditer","make yourself useful","fruktodling","mogna stormäpplen","stormäpplen","windfield orchard"},ang={["class:Rogue"]="Medan fredlösa banditer sviker sitt eget gäng för att få smaka stormäpplen i förtid känner rutinerade skurkar igen den klassiska bristen på disciplin hos amatörtjuvar."},sec={{t="Problem på Windfield Orchard",b="På Windfield Orchard försvåras jordbruket av utpressning. En banditledare vid namn Ferauu och hans gäng har gjort upp om att ta sin vanliga andel av fruktskörden. Men disciplinen brister bland banditerna, så småtjuvar kan inte alltid vänta tills chefen kommer som planerat. De smyger in i förväg för att plocka från träden."},{t="Tjuvar bland tjuvar",b="I stället för att tåla odisciplinerade tjuvar bland stormäppelträden sätter fruktodlaren ambitiösa nykomlingar i arbete innan Ferauu väntas komma. Äventyrare får i uppgift att säkra den mogna stormäppleskörden och göra sig av med de hungriga banditer som olovligen rör sig bland träden. Odlaren påpekar att Ferauu troligen skulle avrätta skurkarna själv för att de gått bakom ryggen på honom och lagt beslag på hans andel."}},faq={{q="Vem är Ferauu?",a="Ferauu är en banditledare som pressar Windfield Orchard på regelbundna tributer, eller en ”andel”, av skörden. Han upprätthåller en hänsynslös disciplin bland sina män, men uppenbarligen inte tillräckligt för att hindra några hungriga underhuggare från att smyga dit i förväg bakom hans rygg.",al={"vem är ferauu","ferauus historia","ferauu banditledare"}},{q="Vad är Windfield Orchard?",a="Windfield Orchard är en lokal odling som är känd för sina stormäpplen. Odlingen drivs under tvång och måste betala Ferauus banditgäng med delar av fruktskörden för att hålla fred.",al={"vad är windfield orchard","windfield orchards historia","stormäppelodling"}},{q="Varför stryker hungriga banditer omkring bland stormäppelträden?",a="Hungriga banditer som tillhör Ferauu har tjuvstartat och smugit in i odlingen före den planerade hämtningen av skörden för att stjäla stormäpplen åt sig själva. Eftersom de har lämnat leden och stjäl från skörden sätter fruktodlaren äventyrare i arbete med att rensa bort dem.",al={"varför döda hungriga banditer","varför är banditer på odlingen","hungriga banditers historia"}},{q="Vad är stormäpplen?",a="Stormäpplen är en fruktsort som odlas på Windfield Orchard. De är tillräckligt eftertraktade för att både vara vardagsmat och utgöra den tribut som lokala brottsgäng som Ferauus kräver.",al={"vad är stormäpplen","mogna stormäpplen"}},{q="Vet Ferauu att hans banditer smyger in i odlingen?",a="Nej, Ferauu vet inte att just de här banditerna kom tidigt. Som fruktodlaren påpekar har dessa fredlösa gått sin egen väg, och Ferauu skulle troligen avrätta dem själv om han kom på dem med att lägga beslag på skörden innan han anlände.",al={"vet ferauu om banditerna","ferauus svek"}},{q="Vem ger dig uppdraget Make Yourself Useful?",a="Uppdraget erbjuds av fruktodlaren på Windfield Orchard, som håller uppsikt över odlingarna från ett fönster i närheten. När djärva nykomlingar kommer för att söka arbete eller mat sätter odlaren deras mod på prov genom att skicka dem mot inkräktande banditer.",al={"vem ger make yourself useful","uppdragsgivare för make yourself useful"}}},fp="20,208,28.224.0,21.298.0,14.193.0,26.153.0,53.219.0,21.125.0,59.175.0,40.230.0"}
P.entries["quest:92683"] = {n="Flutterfly Dust",s="Flutterfly Dust är en lokal syssla i Gustberry Lowlands där pulver samlas från jättelika, bevingade flutterflies. Insekterna är vanligtvis fogliga, men ensliga nybyggare behöver resenärers hjälp med att samla in det kladdiga ämnet på grund av det ständiga hotet från kringströvande banditer.",h="Flutterfly Dust är en lokal syssla i Gustberry Lowlands där pulver samlas från jättelika, bevingade...",kw={"banditer","flutterfly","flutterfly dust","flutterfly swatter","gustberry lowlands","fruktodling","vingdamm"},sec={{t="Giganterna i Gustberry",b="De yttre fälten och fruktodlingarna i Gustberry Lowlands är hem åt jättelika flutterflies, natursköna bevingade insekter som makligt svävar genom landsbygden. Deras milda utseende ger trakten en lantlig charm, men de fladdrande vingarna sprider ett fint, genomträngande damm som kan samlas in i stora mängder. Även om insekterna främst lever vilt, lockar deras närvaro närboende nybyggare som vill samla in denna luftburna biprodukt för praktiska hushållsbehov."},{t="Flugsmällor och skakningar",b="För att samla in flutterfly-damm krävs ett förvånansvärt trubbigt tillvägagångssätt: slå de stora insekterna med en Flutterfly Swatter. De flesta flutterflies får panik och flyger upp när de blir slagna, skakar på bakdelen och lämnar högar av löst pulver efter sig. Ibland vänder sig dock en upprörd flutterfly om och slår tillbaka när den blir provocerad, vilket visar att även fogliga trädgårdskryp har sina gränser när de får en smäll."},{t="Outtalade användningsområden",b="Att samla in dammet är kladdigt och det fastnar lätt, så kläder och utrustning brukar vara täckta i veckor. Den lokala beställaren väntar ivrigt på leveransen eftersom banditer på lur gör ensamma utflykter till fälten alltför farliga, men dammets slutdestination hålls hemlig. När nybyggaren får frågor om vad det ska användas till, avfärdar hen dem undvikande med att det är till allmänna ”grejer och sånt”."}},faq={{q="Vad används flutterfly-damm till?",a="Enligt den lokala invånaren som samlar in det har vingdammet från jättelika flutterflies praktiska användningsområden i hemmet när det samlas i tillräckliga mängder. Det exakta syftet förblir dock medvetet oklart, eftersom uppdragsgivaren avleder frågor med påståendet att det är till allmänna ”grejer och sånt”.",al={"vad är flutterfly dust","användning av flutterfly dust","vad ska dammet användas till"}},{q="Var finns flutterflies?",a="Jättelika flutterflies kan hittas fladdrande över de yttre fälten nära den lokala fruktodlingen, särskilt i Gustberry Lowlands. De delar fälten med närliggande banditer, vilket gör insamlingen farlig för ensliga invånare.",al={"var finns flutterflies","flutterfly-plats","kryp i gustberry lowlands"}},{q="Är flutterflies aggressiva?",a="Flutterflies är i allmänhet fogliga och lugna varelser som oftast flyr när de blir störda. Men om de får en smäll eller provoceras kan några ta illa upp och överraska äventyrare genom att försvara sig innan de släpper ifrån sig vingdammet.",al={"är flutterflies farliga","attackerar flutterflies","flutterfly-beteende"}},{q="Hur samlas flutterfly-damm in?",a="Äventyrare använder en specialutformad Flutterfly Swatter för att ge de överdimensionerade insekterna en rejäl smäll. De skrämda eller upprörda varelserna skakar på bakdelen när de reagerar och sprider en hög med vingdamm som går att samla in på marken.",al={"hur får man tag på damm","flutterfly swatter","samla flutterfly-damm"}},{q="Varför behöver invånaren hjälp med att samla in dammet?",a="Nybyggaren som behöver dammet bor ensam och kan inte enkelt lämna huset för att samla in det, eftersom banditer som lurar i låglandet runtomkring utgör ett alltför stort hot för att det ska vara värt risken att ge sig långt ut på fälten.",al={"varför behövs hjälp","bandithot i gustberry","varför ber uppdragsgivaren om hjälp"}},{q="Varför är invånaren undvikande om dammets egentliga syfte?",a="Uppdragsgivaren vägrar avslöja exakt vad det kladdiga dammet ska användas till i hushållet och viftar nervöst bort frågorna med ”grejer och sånt”. Om det handlar om en pinsam personlig syssla, ett oortodoxt hantverk eller helt enkelt privata angelägenheter förblir oförklarat.",al={"varför så hemlighetsfull","hemligt dammrecept"}}},fp="15,184,23.244.0,19.200.0,21.277.0,33.122.0,29.170.0,28.135.0,33.151.0,59.169.0,58.144.0"}
P.entries["quest:92684"] = {n="Ornery Ornery Galestriders",s="Ornery Ornery Galestriders handlar om en fruktodlare i Gustberry Lowlands som kämpar med en mager säsongsskörd. De lokala galestriders i låglandet, större och vildsintare än sina släktingar i höglandet, har plundrat odlingen på stormapples och hotar gårdens försörjning. Om du gallrar ut de aggressiva fåglarna säkrar du den återstående frukten och får välbehövliga färska filéer till middagen.",h="Ornery Ornery Galestriders handlar om en fruktodlare i Gustberry Lowlands som kämpar med en mager...",kw={"galestrider","gustberry lowlands","galestrider i låglandet","fruktodling","argsinta galestriders","stormapples","filé"},ang={["class:Hunter"]="Jägare som spårar vilda djur i Gustberry Lowlands bör tänka på att de lokala galestriders i låglandet har kraftiga sparkar och ett aggressivt temperament jämfört med sina släktingar i höglandet.",["profession:Cooking"]="Galestriders i låglandet ger rejäla bitar filé som blir en mättande varm måltid, ett välkommet avbrott från magra skördar och frukt."},sec={{t="Försvara odlingen",b="I Gustberry Lowlands har lokala bönder det svårt efter en redan mager säsongsskörd. Som om det inte vore nog har vilda galestriders invaderat odlingarna, länsat grenarna på mogna stormapples och hotat den lilla frukt som finns kvar. För att gården ska kunna överleva måste de djärvaste fåglarna skrämmas bort eller gallras ut innan hela skörden går förlorad."},{t="Låglandets fasor",b="Till skillnad från sina mindre och jämförelsevis lugnare kusiner i höglandet är låglandets galestriders väldiga, argsinta bestar. Resenärer i låglandet måste närma sig dem med yttersta försiktighet, eftersom en enda välriktad spark från deras kraftiga ben kan sätta en oförsiktig kämpe ur stridbart skick eller döda hen. När de fälls ger de stora filéer som förser hungriga lokalbor med sällsynta, rejäla måltider."}},faq={{q="Varför ställer galestriders till problem för bonden?",a="De lokala galestriders har plundrat odlingen för att äta bondens stormapples. Eftersom säsongens skörd redan är ovanligt liten hotar fruktstölden direkt den lokala matförsörjningen.",al={"vad stjäl galestriders","varför döda galestriders","stormappleodling"}},{q="Hur farliga är galestriders i låglandet?",a="Galestriders i låglandet är betydligt större och aggressivare än de som finns i höglandet. Deras kraftiga, välriktade sparkar kan lätt slå omkull en resenär för gott om hen blir överraskad.",al={"hur farliga är galestriders","galestriderattacker","är galestriders starka"}},{q="Vad vill bonden ha från galestriders?",a="Bonden ber resenärer att gallra ut de aggressiva galestriders i låglandet och samla in filéer från de fallna bestarna. Köttet ger en välbehövlig varm måltid efter lång tid utan färskt kött.",al={"galestriderkött","vad lämnar galestriders efter sig","filéuppdrag"}},{q="Var finns de här galestriders?",a="Argsinta galestriders från låglandet strövar omkring i Gustberry Lowlands, särskilt nära gårdarna och fruktodlingarna där de letar efter stormapples.",al={"var finns galestriders","galestriders plats","gustberry lowlands"}},{q="Hur skiljer sig galestriders i låglandet från dem i höglandet?",a="Galestriders i låglandet skiljer sig från sina motsvarigheter i höglandet främst genom storlek och temperament: låglandets variant blir märkbart större, är betydligt argsintare och utdelar förödande sparkar.",al={"galestriders i höglandet jämfört med låglandet","galestridervarianter"}},{q="Vad är stormapples?",a="Stormapples är en frukt som odlas i regionen. Eftersom skörden den här säsongen redan är knapp är det avgörande att skydda de återstående träden från galestriders som letar efter mat.",al={"vad är stormapples","fruktskörd"}}},fp="26,213,21.253.0,15.241.0,57.126.0,40.136.0,48.109.0,35.132.0,63.120.0,21.141.0"}
P.entries["quest:92685"] = {n="The Hills Have Eyes",s="\"The Hills Have Eyes\" är ett uppdrag i Gustberry Lowlands där den hårt ansatta bonden Aamelia tar strid mot landsvägsrövare. Äventyrare slår till mot ett läger i de norra kullarna för att försvaga rövarbandet innan dess ledare Ferauu går till anfall.",h="\"The Hills Have Eyes\" är ett uppdrag i Gustberry Lowlands där den hårt ansatta bonden Aamelia tar strid mot...",kw={"aamelia","rövarmasker","blodfläckade rövarmasker","ferauu","gustberry lowlands","landsvägsrövare","the hills have eyes"},ang={["profession:Tailoring"]="Aamelia skämtar mörkt om att sy en filt av blodfläckade rövarmasker åt Ferauu, vilket visar hennes rätt makabra förtjusning i nål och tråd."},sec={{t="Ett förebyggande anfall",b="I Gustberry Lowlands står bonden Aamelia inför ett överhängande anfall från ett rövarband lett av Ferauu. I stället för att passivt vänta på att undergången ska stå vid hennes dörr uppmanar hon resande att slå till mot ett rövarläger i kullarna norrut. Genom att slå ut landsvägsrövarna innan de samlar sig för attacken hoppas hon tunna ut deras led och vinna dyrbar tid."},{t="Förnyat hopp och hämnd",b="Som bevis på bakhållet ber Aamelia om blodfläckade masker som tagits från de stupade landsvägsrövarna. Hon skämtar bistert om att sy ihop dem till en filt att ge Ferauu och gläds åt vetskapen om att hennes plågoandar mötte hårt motstånd. När lägret i norr försvagas bryts veckor av hopplös väntan, och hon får mod att stå upp när Ferauu och hans huvudstyrka till slut anländer."}},faq={{q="Vad är The Hills Have Eyes?",a="\"The Hills Have Eyes\" är ett försvarsuppdrag som Aamelia ger på sin gård. Inför ett nära förestående anfall från Ferauus rövarband skickar hon äventyrare till kullarna i norr för att överfalla rövarna och hämta deras blodfläckade masker innan de slår till.",al={"uppdraget hills have eyes","vad är det här för uppdrag","vad är hills have eyes"}},{q="Vem ger uppdraget The Hills Have Eyes?",a="Aamelia försvarar sin gård och har i veckor väntat skräckslagen på att rövare ska övermanna hennes hem. När hon slår tillbaka mot landsvägsrövarna får hon nytt hopp inför Ferauus förestående anfall.",al={"vem ger hills have eyes","vem är aamelia","uppdragsgivaren aamelia"}},{q="Vem är Ferauu?",a="Ferauu leder landsvägsrövarna som härjar kring Gustberry Lowlands. Han och hans banditer har hotat Aamelias gård och är redo att gå till anfall.",al={"vem är ferauu","ferauu boss","rövarledaren ferauu"}},{q="Var finns landsvägsrövarna?",a="Highwayman Bandits håller till i läger runt om i Gustberry Lowlands, däribland ett litet läger uppe i kullarna strax norr om Aamelias gård.",al={"rövare i gustberry lowlands","var finns rövarna","rövarläger i kullarna"}},{q="Varför vill Aamelia ha blodfläckade rövarmasker?",a="Aamelia kräver blodfläckade masker som bevis på att rövarna fick lida och överrumplades. Att slå ner dem i förväg jämnar ut oddsen inför Ferauus nära förestående anfall.",al={"varför samla masker","varför blodfläckade masker","vad ska maskerna användas till"}},{q="Vad händer efter att uppdraget är slutfört?",a="När lägret i kullarna har slagits ut börjar Aamelia åter känna hopp för sin gård. Men Ferauu och hans kvarvarande banditer väntas anlända när som helst, och en sista strid närmar sig.",al={"vad händer efter hills have eyes","nästa uppdrag aamelia","ferauus anfall"}}},fp="19,175,19.295.0,28.357.1,28.177.0,40.136.0,14.130.0,41.136.0,49.140.0,40.161.0"}
P.entries["quest:92693"] = {n="Standing Our Ground",s="Standing Our Ground är ett avgörande uppdrag där en äventyrare står sida vid sida med Aamelia Windfield i en desperat konfrontation med en hotfull banditledare. Efter att ha förberett försvararna för strid möter du det som tycktes vara en förlorad kamp för att skydda dem från banditerna.",h="Standing Our Ground är ett avgörande uppdrag där en äventyrare står sida vid sida med Aamelia Windfield i en...",kw={"aamelia windfield","banditledare","banditer","förlorad kamp","standing our ground","valanaar"},sec={{t="En desperat sista strid",b="Standing Our Ground är höjdpunkten i en desperat kamp mot ett banditgäng. Efter att ha hjälpt till att förbereda de lokala försvararna för en oundviklig strid får du en sista möjlighet att gå därifrån och återvända tryggt till Valanaar i stället för att kasta dig in i vad som verkar vara en dödsdömd sista strid."},{t="Mötet med banditledaren",b="När du signalerar att du är redo går du fram tillsammans med Aamelia Windfield för att möta banditledaren direkt. När du besegrar banditen är det överhängande hotet undanröjt, och Aamelia kippar efter andan av chock och lättnad över att deras desperata chansning faktiskt lyckades."}},faq={{q="Vem ger uppdraget Standing Our Ground?",a="Uppdraget ges av Aamelia Windfield, som förbereder sig på att möta ett förestående banditanfall och ger dig en sista chans att dra dig ur innan ni konfronterar deras ledare.",al={"vem ger standing our ground","uppdragsgivare standing our ground","npc standing our ground"}},{q="Vem slåss du mot i Standing Our Ground?",a="Du möter en framryckande banditledare som hotar de lokala försvararna. Aamelia Windfield samlar sina sista krafter för att marschera ut och möta ledaren direkt.",al={"vem är banditledaren i standing our ground","boss i standing our ground","banditledare i standing our ground"}},{q="Vilken roll spelar Valanaar i det här uppdraget?",a="Valanaar är den närliggande bosättning som Aamelia Windfield nämner som en tillflyktsort. Hon ger dig uttryckligen möjligheten att dra dig tillbaka till Valanaar om du inte vill riskera livet i striden.",al={"var ligger valanaar i standing our ground","reträttstad i standing our ground","valanaar-uppdrag"}},{q="Varför beskriver Aamelia striden som en förlorad kamp?",a="Aamelia och hennes följeslagare tror att oddsen är starkt emot dem. De ser konfrontationen som en desperat sista strid där det verkar nästan omöjligt att överleva en dag till utan hjälp utifrån.",al={"varför är standing our ground en förlorad kamp","standing our ground-berättelse","aamelia windfields kamp"}},{q="Vad händer när konfrontationen är över?",a="Mot alla odds besegras banditledaren. När uppdraget är slutfört är Aamelia Windfield chockad och lättad över att prövningen äntligen är över, och kämpar för att lugna sitt bultande hjärta.",al={"vad händer efter att banditledaren besegrats i standing our ground","lämna in standing our ground","överlever aamelia"}},{q="Vad leder fram till den sista striden?",a="Före det här uppdraget hjälpte du försvararna med förberedelser som gav dem en chans att slåss mot bandithotet och banade väg för den avgörande konfrontationen.",al={"förkunskapskrav för standing our ground","uppdrag före standing our ground"}}},fp="19,181,22.219.0,29.228.1,40.89.0,40.122.0,43.129.0,53.169.0,44.139.0,34.117.0"}
P.entries["quest:92698"] = {n="What Is My Purpose?",s="\"What Is My Purpose?\" är ett uppdrag som kretsar kring en jättelik Malfunctioning Cyclone Construct, som planlöst vandrar genom åkrarna. Den uråldriga maskinen upprepar trasiga talfragment under sin pansarplåt och har glömt sina ursprungliga uppgifter efter årtionden av vanvård sedan vindelementarerna gav sig av. För att undersöka konstrukten får äventyrarna söka upp den lokala fruktodlaren Aamelia Windfield och fråga om dess mystiska förflutna och tidigare skötare.",h="\"What Is My Purpose?\" är ett uppdrag som kretsar kring en jättelik Malfunctioning Cyclone Construct, som...",kw={"aamelia windfield","alvarion","konstrukt","cyklonkonstrukt","felande cyklonkonstrukt","fruktodling","vad är mitt syfte","vindelementarer","windshapers"},ang={["class:Shaman"]="Schamaner kan vara särskilt intresserade av konstruktens funktionsförfall, eftersom lokala berättelser kopplar dess övergivande och haveri direkt till vindelementarernas avfärd från området.",["profession:Engineering"]="Ingenjörer kan finna Malfunctioning Cyclone Construct intressant som exempel på uråldrig automatisering. Dess interna logikloopar består trots århundraden av slitage och total avsaknad av tekniskt underhåll."},sec={{t="Den vandrande konstrukten",b="Djupt inne bland åkrarna står en väldig Cyclone Construct och vandrar planlöst över marken, fast i en trasig funktionsloop. Den som närmar sig den bepansrade jätten kan höra dämpat, fragmenterat tal vibrera under de tunga plåtarna. Den upprepar felmeddelanden i det oändliga och ifrågasätter sin grundläggande funktion. Årtionden av isolering har berövat maskinen dess syfte, och dess interna direktiv är förvanskade eller bortglömda. Automatonen ser väldig och skräckinjagande ut, men utgör inget aktivt hot mot förbipasserande. I stället är den en melankolisk relik från en äldre tid, vars röst reducerats till statiska frågor som ekar över jorden."},{t="Glömt arbete och The Windshapers",b="När Aamelia Windfield får frågor om maskinen berättar hon att automatonen har vandrat omkring på fälten i årtionden, till synes ända sedan vindelementarerna gav sig av. En lokalbo vid namn Alvarion spekulerade i att maskinen en gång fraktade rikliga skördar till avlägsna marknader eller skötte boskap, för flera sekler sedan och långt innan marken blev en fruktodling. I forna tider byggde och underhöll en grupp som kallades The Windshapers dessa cyklonkonstrukter. Fruktodlarna har ibland pratat om att be The Windshapers reparera maskinen, men frågan har aldrig varit brådskande. Därför får konstrukten ströva omkring ostörd och till stor del ignorerad."}},faq={{q="Vad är Malfunctioning Cyclone Construct?",a="Malfunctioning Cyclone Construct är en uråldrig bepansrad automaton som planlöst vandrar genom de lokala åkrarna. Den underhölls en gång av The Windshapers, men har förfallit efter årtionden av vanvård. Under sin pansarplåt upprepar den oavbrutet trasiga talfragment som ifrågasätter dess syfte och rapporterar funktionsfel.",al={"vad är konstrukten","cyklonkonstrukt","jättekonstrukt på åkrarna"}},{q="Vem är Aamelia Windfield?",a="Aamelia Windfield är en lokalbo som bor nära fruktodlingen där den felande konstrukten vandrar. Hon känner till maskinens historia och berättar att den har vandrat över fälten i årtionden sedan vindelementarerna gav sig av, och att dess skapare, The Windshapers, brukade ta hand om sådana apparater.",al={"aamelia windfield","vem är aamelia","fruktodlings-npc"}},{q="Vad var konstruktens ursprungliga syfte?",a="Konstruktens exakta ursprungliga syfte har fallit i glömska. Enligt Aamelia Windfield trodde en lokalbo vid namn Alvarion att den kan ha fraktat skördar till marknaden eller skött boskap för flera sekler sedan, innan den nuvarande fruktodlingen fanns. Det kan ha varit så långt tillbaka som tusen år.",al={"konstruktens syfte","vad gjorde konstrukten","konstruktens uppgift"}},{q="Vilka är The Windshapers?",a="The Windshapers är en uråldrig grupp som är känd för att skapa och underhålla cyklonkonstrukter. Förr ansvarade de för att serva dessa automatiserade maskiner. Numera har de lokala lantarbetarna inte bett dem om hjälp, eftersom det saknas både överhängande fara och behov.",al={"windshapers","vem skapade konstrukten","vem underhåller cyklonkonstrukter"}},{q="Varför upprepar konstrukten fragmenterade ord?",a="Konstrukten lider av ett allvarligt mekaniskt eller funktionellt fel, troligen orsakat av årtionden utan underhåll efter att vindelementarerna gav sig av. När någon närmar sig yttrar den osammanhängande fraser som ”funktionsfel” och ”vad är funktion”, vilket tyder på att dess direktivhantering har fastnat i en olöst frågeloop.",al={"varför talar konstrukten","funktionsfel hos konstrukten","vad säger den"}},{q="Varför har lokalborna inte reparerat eller monterat ned konstrukten?",a="Konstrukten utgör inget hot mot invånarna eller deras fruktodlingar, utan vandrar bara fredligt bland träden och grödorna. Lokalbor som Aamelia Windfield har pratat om att be The Windshapers om underhåll, men frågan har aldrig varit tillräckligt brådskande för att motivera handling. Därför ignorerar lokalborna den helt enkelt.",al={"varför ignoreras konstrukten","varför lagar man inte konstrukten","är konstrukten farlig"}},{q="Vem är Alvarion?",a="Alvarion är en lokalbo som Aamelia Windfield nämner och som undersökte den vandrande konstruktens historia. Han trodde att maskinen ursprungligen utförde jordbruksarbete, antingen genom att frakta inbärgade skördar till marknaden eller genom att valla boskap långt innan området gjordes om till en fruktodling.",al={"alvarion","vem är alvarion","alvarions teori"}}},fp="19,220,23.373.0,35.470.0,45.276.0,25.191.0,42.187.0,24.182.0,48.216.0,60.264.0,16.201.0"}
P.entries["quest:92699"] = {n="The Supreme Magister",s="The Supreme Magister hänvisar nyanlända äventyrare i Valanaar till Elaadrin Evengale, ledaren för High Order. Orden håller till i en lodge i bosättningens sydöstra del och söker dugliga allierade samtidigt som den hanterar bittra motsättningar med Windshapers och hotet från en lokal sekt.",h="The Supreme Magister hänvisar nyanlända äventyrare i Valanaar till Elaadrin Evengale, ledaren för High Order.",kw={"magi","sekt","elaadrin evengale","high order","rathiril","the supreme magister","valanaar","windshapers"},ang={["class:Mage"]="Elaadrin lägger märke till en livfull magisk aura hos magiutövare och värdesätter den sällsynta begåvning och vilja som krävs för att bemästra magin och bevara deras hemland."},sec={{t="High Order i Valanaar",b="När de anländer till Valanaar hänvisas nykomlingar med särskilt stor potential till High Order. Organisationen leds av Supreme Magister Elaadrin Evengale och håller till i en lodge längst i bosättningens sydöstra del. Elaadrin håller noga uppsikt över nyanlända och söker dem som har den styrka, beslutsamhet och mystiska aura som krävs för att möta farorna kring deras hotade hem."},{t="Rivaliserande fraktioner och hotande sekter",b="Den sköra inre freden i Valanaar är hotad. High Order och Windshapers hyser en djup fientlighet mot varandra, och nykomlingar varnas för att hålla sig på långt avstånd från Windshapers så att våld inte bryter ut på gatorna. Med en farlig sekt i närheten har de lokala ledarna inte råd med inre blodsutgjutelse medan yttre hot tornar upp sig över staden."}},faq={{q="Vem är Elaadrin Evengale?",a="Elaadrin Evengale är High Orders nuvarande Supreme Magister. Han leder deras verksamhet från en lodge i Valanaars sydöstra hörn och söker personer med magisk begåvning och beslutsamhet nog att skydda deras hem.",al={"vem är elaadrin evengale","elaadrin evengale","vem är supreme magister"}},{q="Var finns Elaadrin Evengale?",a="Elaadrin Evengale och hans följare håller till i en lodge längst i Valanaars sydöstra del.",al={"var finns supreme magister","var hittar man elaadrin evengale","var ligger lodgen i valanaar"}},{q="Vad är High Order?",a="High Order är en magisk organisation i Valanaar, ledd av Supreme Magister Elaadrin Evengale. De fokuserar på att använda magisk kraft för att försvara sitt hem, trots att de blir allt färre och spänningarna i trakten ökar.",al={"vad är high order","high orders historia"}},{q="Varför råder det konflikt mellan High Order och Windshapers?",a="High Order och Windshapers är bittra rivaler i Valanaar. De lokala ledarna insisterar på att hålla dem på långt avstånd från varandra för att förhindra öppet fraktionsvåld på gatorna, särskilt när sektens verksamhet hotar bosättningen.",al={"varför strider high order och windshapers","konflikten med windshapers","spänningar i valanaar"}},{q="Vem är Rathiril?",a="Rathiril är en medarbetare eller medlem som genom magiska meddelanden hänvisar lovande äventyrare i Valanaar till High Order och uppmärksammar Elaadrin Evengale på personer med stor potential.",al={"vem är rathiril","rathirils meddelande"}},{q="Vilken sekt hotar Valanaar?",a="En mystisk sekt är verksam kring Valanaar och utgör ett så stort hot att de lokala myndigheterna aktivt motverkar stridigheter mellan grupper som High Order och Windshapers för att hålla bosättningen trygg.",al={"vilken sekt finns i valanaar","sektens hot mot valanaar"}}},fp="20,192,26.282.0,32.298.0,25.178.0,37.84.0,23.227.0,65.198.0,16.163.0,29.190.0"}
P.entries["quest:927"] = {n="The Moss-twined Heart",s="Moss-twined Heart är en märklig, förvriden kärna från den monstruösa trädlingen Blackmoss the Fetid. Den är täckt av oljig, mörk mossa, men hjärtat fortsätter oroväckande nog att slå på egen hand. Det får botanisten Denalan vid Lake Al'Almeth att undersöka saken.",h="Moss-twined Heart är en märklig, förvriden kärna från den monstruösa trädlingen Blackmoss the Fetid.",kw={"blackmoss the fetid","farsot","förvridning","denalan","lake al'ameth","moss-twined heart","teldrassil","trädling"},ang={["class:Druid"]="Druider i Cenarion Circle intresserar sig starkt för avvikelser som det här pulserande, fördärvade hjärtat. De försöker avgöra om förvridningen kan renas bort eller om den visar på en djupare förruttnelse.",["profession:Herbalism"]="Varje växtkunnig kan se att den oljiga påväxten på den här kärnan är helt onaturlig. Den trotsar vanliga botaniska egenskaper genom att hålla ett avskuret hjärta vid liv.",["race:NightElf"]="För kaldorei är det ett allvarsamt tecken på att deras nya hem plågas av en krypande sjukdom att se hur det unga Världsträdet Teldrassil fostrar besmittade, aggressiva trädlingar som Blackmoss."},sec={{t="En pulserande kärna",b="Det här trädlinghjärtat har skurits ut ur resterna av Blackmoss the Fetid och är nästan oigenkännligt under ett lager mörk, oljig mossa. Det enda som avslöjar dess sanna natur är en långsam, rytmisk puls som fortsätter även efter att det skilts från varelsen. En sådan onaturlig uthållighet antyder att förvridningen som sprider sig bland Teldrassils vilda växtliv är långt mer omfattande än vanlig förruttnelse."},{t="Denalans undersökning",b="Denalan, en skarpsinnig forskare av traktens växter som håller till nära Lake Al'Almeth, inser genast hur allvarligt det är med föremålet. Trädlingar ska vara milda varelser, sammanflätade med Världsträdets grenar, men det här hjärtat visar tecken på en virulent förödande kraft. Denalan är både nyfiken och bekymrad och bestämmer sig för att plantera och studera det förvridna organet för att förstå den hemska mossan som slår rot i öns jord."}},faq={{q="Var kommer Moss-twined Heart ifrån?",a="Hjärtat tas från Blackmoss the Fetid, en stor och svårt förvriden trädling som strövar omkring i Teldrassils vildmark.",al={"var får jag tag på hjärtat","moss-twined heart byte","blackmoss the fetids hjärta"}},{q="Varför slår hjärtat fortfarande?",a="Den mörka, oljiga mossan som angripit trädlingen verkar hålla hjärtat vid liv med onaturlig kraft. Även när det skurits loss från varelsen behåller hjärtat sin långsamma, ihållande rytm.",al={"varför pulserar hjärtat","hjärta som fortfarande slår","trädlinghjärtats puls"}},{q="Vem är Denalan?",a="Denalan är en nattalv och naturkännare som sköter en plantskola nära Lake Al'Almeths stränder. Han ägnar sig åt att studera Teldrassils växter, groddar och den krypande förvridning som drabbar öns trädlingar.",al={"vem är denalan","var finns denalan","denalans plats"}},{q="Vad ska Denalan göra med hjärtat?",a="Denalan bestämmer sig för att plantera hjärtat i en förtrollad kruka så att det kan gro och han kan isolera den hemska mossan. Han hoppas kunna hitta grundorsaken till den fördärvade växtligheten.",al={"vad händer med hjärtat","uppdraget att plantera hjärtat","denalans hjärtforskning"}},{q="Vad ska trädlingar vara?",a="Trädlingar är naturligt fridsamma plantelementarer som föds ur skogen. Men i hela Teldrassil har mörka krafter och onaturlig besmittelse drivit många av dem till vansinne och gjort dem aggressiva.",al={"vad är trädlingar","trädlingars bakgrund","är trädlingar onda"}},{q="Är förvridningen i hjärtat magisk eller naturlig?",a="Mossan verkar hemsk och oljig snarare än frisk. Det tyder på en onaturlig farsot i Teldrassils inhemska ekosystem, inte vanlig nedbrytning i vildmarken.",al={"är mossan magisk","varifrån kommer den hemska mossan","teldrassils mossfarsot"}}},fp="21,166,14.241.0,21.405.0,43.120.0,31.138.0,15.184.0,36.156.0,36.158.0,50.119.0"}
P.entries["quest:92700"] = {n="The Grand Skyseer",s="The Grand Skyseer är en introducerande resa in i hjärtat av Valanaar, där resenärer uppmanas att söka audiens hos Ayessa Dawnsinger i Windshaper-lodgen. Medan spänningarna pyr mellan lokala fraktioner och en skum kult hotar regionen, söker Windshapers desperat personer med andlig synförmåga.",h="The Grand Skyseer är en introducerande resa in i hjärtat av Valanaar, där resenärer uppmanas att söka audiens...",kw={"ayessa dawnsinger","elder amberwind","high order","shen'dar village","skysight","the grand skyseer","valanaar","windshapers","zephras"},ang={["class:Druid"]="De som känner av andliga auror och naturens osedda flöde finner besläktade tankar hos Windshapers, som håller uppsikt över himlens subtila skiftningar.",["class:Shaman"]="Ayessa Dawnsinger känner genast igen resenärer som står i samklang med andarna och har andliga gåvor, vilket gör Windshapers till en viktig kontakt för schamaner i samklang med elementarkrafter."},sec={{t="Ankomsten till Valanaar",b="När resenärer anländer till staden Valanaar hänvisas de till den centrala lodgen, där Windshapers samlas under ledning av Grand Skyseer Ayessa Dawnsinger. Efter att ha väckt Elder Amberwinds uppmärksamhet genom anmärkningsvärda dåd i Shen'dar Village välkomnas nyanlända in bland dem som står i samklang med andarna. Men Valanaar är fortfarande fullt av yttre och inre faror, och nykomlingar måste navigera den bräckliga lokala politiken varsamt."},{t="Rivaliteter och hotande kulter",b="Freden i Valanaar är skör. Windshapers är öppet fientliga mot High Order, och gatustrider mellan fraktionerna hotar att destabilisera bosättningen. Eftersom en skum kult aktivt hotar regionen har lokala ledare beordrat båda fraktionerna att hålla avstånd och prioritera överlevnad mot gemensamma fiender framför bittra territoriella fejder."},{t="Den avtagande skysynen",b="Grand Skyseer Ayessa Dawnsinger ser att den andliga förmåga som kallas skysight blir allt ovanligare bland Zephras folk. De som anländer med en stark aura och andlig harmoni betraktas som oumbärliga allierade, i stort behov av att hjälpa Windshapers navigera de svåra tider som landet står inför."}},faq={{q="Vem är Grand Skyseer?",a="Grand Skyseer är Ayessa Dawnsinger, en framstående andlig ledare bland Windshapers i Valanaar. Hon håller till i lodgen nära bosättningens centrum och tar emot resenärer som står i samklang med andarna och har den sällsynta gåvan skysight.",al={"vem är grand skyseer","ayessa dawnsinger vem är hon","vem är ayessa"}},{q="Var finns Ayessa Dawnsinger?",a="Ayessa Dawnsinger finns i Windshaper-lodgen nära centrum av bosättningen Valanaar. Hon väntar på resenärer från Shen'dar Village som för med sig nyheter om nyliga dåd från Elder Amberwind.",al={"var finns ayessa dawnsinger","var ligger grand skyseers lodge","ayessas plats i valanaar"}},{q="Vilka är Windshapers?",a="Windshapers är en andlig sammanslutning i Valanaar, lokalt ledd av Grand Skyseer Ayessa Dawnsinger. Medlemmarna studerar himlen och samtalar med andarna, men befinner sig för närvarande i skarp konflikt med en annan lokal grupp som kallas High Order.",al={"vad är windshapers","windshaper-fraktionen i valanaar"}},{q="Varför är Windshapers i konflikt med High Order?",a="De två ordnarna är oense om vindandarna. High Order har blivit misstänksamma mot andarnas avsikter och vill själva förstå Skywalls krafter, medan Windshapers litar på elementarerna och ser sådana frågor som en förolämpning. Motsättningarna är så djupa att våld mellan fraktionerna på Valanaars gator inte kommer att tolereras, särskilt medan kulten hotar regionen.",al={"konflikten mellan windshapers och high order","varför är high order arg på windshapers","high order i valanaar"}},{q="Vad är gåvan skysight?",a="Skysight är en sällsynt andlig förmåga som bara ett fåtal individer i Zephras besitter. Den låter dem känna av andliga auror och kommunicera med osedda krafter. Ayessa Dawnsinger säger att allt färre har gåvan, vilket gör dem med skysight oumbärliga för att uthärda de nuvarande svårigheterna.",al={"vad är skysight","skysight-gåvan i zephras"}},{q="Vem är Elder Amberwind?",a="Elder Amberwind är en respekterad äldste i Shen'dar Village som bedömer resenärer och skickar besked till Valanaar om deras dåd och andliga samklang. Hen hänvisar värdiga personer till Grand Skyseer Ayessa Dawnsinger.",al={"vem är elder amberwind","amberwind i shendar village"}}},fp="17,185,19.340.0,27.313.0,19.244.0,25.226.0,37.185.0,24.199.0,49.292.0,29.232.0,23.222.0"}
P.entries["quest:92701"] = {n="To Valanaar",s="”To Valanaar” är ett leveransuppdrag med brådskande nyheter från byn Shen'dar till fredsbevararnas garnison i Valanaar. Det markerar en kritisk upptrappning på ön och varnar Commander Valennia Stormfist för att fredsbevararna inte längre kan undvika öppen konflikt med den snabbt växande kulten.",h="”To Valanaar” är ett leveransuppdrag med brådskande nyheter från byn Shen'dar till fredsbevararnas garnison i...",kw={"aonda","kult","fredsbevarare","pylon","shen'dar","to valanaar","valanaar","valennia stormfist"},sec={{t="Meddelande från Shen'dar",b="Efter försvaret av byn Shen'dar och dess viktiga pylon skickar höglandsbon Aonda en betrodd budbärare över ön. Målet är Valanaar, en bosättning på öns sydöstra spets, där de lokala fredsbevararnas befälhavare måste varnas för kultens snabba upptrappning."},{t="Stormen närmar sig",b="Under en tid har fredsbevararna under Valennia Stormfist försökt förhindra en öppen strid med den gåtfulla kult som tränger in på ön. Men händelserna i Shen'dar markerar en vändpunkt. Kultens inflytande växer snabbt, och Valennia tvingas inse att tiden då de kunde undvika strid är över. Hennes krympande skara fredsbevarare måste nu förbereda Valanaar på ett nära förestående anfall."}},faq={{q="Vem är Valennia Stormfist?",a="Valennia Stormfist är befälhavare för fredsbevararna på ön och verkar från bosättningen Valanaar. Hon ansvarar för att skydda lokalbefolkningen och märker hur den lilla garnisonen får allt svårare att räcka till när kultens aktivitet ökar i regionen.",al={"vem är valennia stormfist","valennia","fredsbevararnas ledare"}},{q="Vem är Aonda?",a="Aonda är en listig höglandsbo som håller till i byn Shen'dar. Efter att ha säkrat en lokal pylon och försvarat bosättningen mot kultens angrepp anförtror hon resenärer uppgiften att föra hennes skriftliga rapport över ön till Valennia.",al={"vem skickade rapporten","listig höglandsbo","aonda"}},{q="Vad är Valanaar?",a="Valanaar är en bosättning vid öns sydöstra spets. Den är huvudbas för Valennia Stormfist och de lokala fredsbevararna och fungerar som en försvarsbastion för öns invånare.",al={"vad är valanaar","var ligger valanaar","valanaars läge"}},{q="Vad hotar kulten ön med?",a="Ön hotas av en snabbt växande kult som har börjat tränga in i lokala bosättningar och heliga pyloner. Fredsbevararna har tidigare undvikit direkta strider, men kultens expansion tvingar nu Valanaar och dess försvarare att förbereda sig på en oundviklig kamp.",al={"vilken kult","vem anfaller","kultens expansion"}},{q="Vad är Shen'dar?",a="Shen'dar är en by nära en viktig pylon på ön. Efter att nyligen ha slagit tillbaka kultens angrepp och säkrat byn och pylonen har dess ledare nära kontakt med fredsbevararna i Valanaar.",al={"vad är shen'dar","shen'dar","by vid en pylon"}},{q="Vad står det i Aondas rapport?",a="Den skriftliga rapporten beskriver de senaste händelserna kring försvaret av Shen'dar och dess pylon. Den varnar Valennia för att kultens snabba territoriella expansion gör att en direkt konflikt inte längre kan undvikas.",al={"vad står i aondas rapport","den skriftliga rapportens innehåll","vad står det i brevet"}}},fp="11,154,22.249.0,19.303.0,26.173.0,13.170.0,17.143.0,40.200.0,17.194.0,36.162.0"}
P.entries["quest:92703"] = {n="Deliver the News",s="Deliver the News avslutar Windfield-familjens prövningar vid fruktodlingen i Skywall. Efter att ha hjälpt Aamelia att säkra gården beger sig The Adventurer till Valanaar för att berätta för den orolige Alvarion Windfield att familjen är i säkerhet.",h="Deliver the News avslutar Windfield-familjens prövningar vid fruktodlingen i Skywall.",kw={"aamelia","alvarion windfield","konstruktion","deliver the news","fruktodling","skywall","valanaar","windfield","vindformare"},ang={["race:Skyborne"]="Alvarion talar om verkliga hjältar ur berättelser från tiden innan folket kom till Skywall. Det påminner Skyborne-äventyrare om deras rötter och kulturarv före flytten."},sec={{t="Lättnad vid fruktodlingen",b="Deliver the News löser krisen vid Windfield-familjens fruktodling. Efter att ha räddat gården från en annalkande katastrof tackar Aamelia varmt och är redo att lämna faran bakom sig. Nu när fruktodlingen är säkrad blir det viktigast att lugna Alvarion Windfield, som flydde till bosättningen Valanaar för att be om hjälp."},{t="En hemlighet för framtiden",b="Innan Aamelia skickar resenären till Valanaar ber hon Alvarion att rekrytera en skicklig vindformare när han har återhämtat sig. En konstruktion finns kvar vid fruktodlingen, och hon vill att en expert undersöker den noggrant för att försäkra sig om att den inte utgör något hot. Hon delar också en öm hemlighet: hon väntar barn och vill hålla det hemligt för Alvarion tills han har återvänt hem i säkerhet."},{t="En hjälte i Valanaar",b="I Valanaar blir Alvarion Windfield överväldigad av känslor när han får veta att hans familj och hem är i säkerhet. Han hade begett sig till staden för att söka hjälp och trodde att det var ett desperat, nästan hopplöst försök. The Adventurers framgång påminner honom om de legendariska hjältar som omtalades innan hans folk kom till Skywall. Nu när hemmet är räddat hälsar familjen Windfield sin räddare välkommen för alltid."}},faq={{q="Vad är uppdraget Deliver the News?",a="Deliver the News är ett uppdrag som Aamelia ger efter att krisen vid Windfield-fruktodlingen är löst. Hon ber The Adventurer att resa till staden Valanaar och berätta för hennes partner Alvarion Windfield att faran är över och att hon är i säkerhet.",al={"uppdraget deliver the news","vad är deliver the news","vem ger deliver the news"}},{q="Vem är Alvarion Windfield?",a="Alvarion Windfield är en invånare i Skywall som återhämtar sig i Valanaar. Han reste till staden för att söka hjälp med problemen vid familjens fruktodling och trodde att allt hopp var ute innan han mötte spelaren.",al={"vem är alvarion windfield","var är alvarion","alvarions plats"}},{q="Vem är Aamelia?",a="Aamelia bor på Windfield-gården och sköter fruktodlingen tillsammans med Alvarion. Tacksam för spelarens ingripande ger hon dem i uppdrag att berätta för Alvarion i Valanaar att de har lyckats.",al={"vem är aamelia","uppdragsgivaren aamelia"}},{q="Vad håller Aamelia hemligt för Alvarion?",a="Aamelia berättar lågmält för The Adventurer att hon väntar barn. Hon rör varsamt vid magen och ber att få hålla nyheten hemlig för Alvarion tills han har återhämtat sig och kommit hem.",al={"vad är aamelias hemlighet","aamelia rör vid magen","är aamelia gravid"}},{q="Varför vill Aamelia att en vindformare kommer till fruktodlingen?",a="Aamelia vill att Alvarion tar med sig en vindformare tillbaka till fruktodlingen när han har återhämtat sig. Hon vill att specialisten undersöker en konstruktion på ägorna för att se till att den inte utgör någon fara för familjen som snart växer.",al={"varför konstruktionen och vindformaren","vilken konstruktion nämner aamelia","windfield-konstruktionen"}},{q="Var utspelar sig uppdraget?",a="Uppdraget knyter samman Windfield-fruktodlingen med bosättningen Valanaar, som ligger i det elementära riket Skywall där nybyggarna har slagit sig ner.",al={"var utspelar sig deliver the news","valanaar-uppdrag i skywall"}}},fp="16,125,21.196.0,23.287.1,18.337.0,35.135.0,26.168.0,15.161.0,44.134.0,58.181.0,33.126.0"}
P.entries["quest:92706"] = {n="WANTED: Bruuz",s="Bruuz hotar hamntrafiken som håller Ratchet i gång. Gazlowe har utlyst en belöning för den enorma hajen som stryker kring kajerna och stör kusthandeln.",h="Bruuz hotar hamntrafiken som håller Ratchet i gång.",kw={"the barrens","belöning","bruuz","ryggfena","gazlowe","ratchet","haj","steamwheedle"},ang={["class:Hunter"]="Som jägare kan du pröva ditt tålamod och din träffsäkerhet mot Bruuz, en enorm vattenpredator.",["profession:Cooking"]="Som kock skulle du kunna använda det färska kustköttet från en haj så stor som Bruuz. Gazlowe vill bara ha ryggfenan som bevis på att den dödats."},sec={{t="Skräck i bukten",b="Ratchet är den främsta neutrala förbindelsen mellan Kalimdor och Eastern Kingdoms, och handeln är beroende av handelsfartyg. På senare tid har en enorm haj vid namn Bruuz strukit omkring i bukten. Hamnarbetarna gav hajen dess namn efter att den började angripa småbåtar, sjömän och last som lossades nära kajerna. Dess närvaro stör hamnen och utsätter fartygen som försörjer Ratchet för fara."},{t="Gazlowes belöning",b="Gazlowe har utlyst en offentlig belöning för att hindra fartyg från att undvika hans hamn av rädsla för hajen. Efterlysningen vänder sig till fiskare och utlovar en rejäl belöning. För att göra anspråk på den måste du döda Bruuz och ta med hajens ryggfena som bevis."}},faq={{q="Vem är Bruuz?",a="Bruuz är en enorm, aggressiv haj som jagar nära Ratchets lastkajer. Hamnarbetarna gav den det namnet efter att den angripit sjömän och småfartyg.",al={"vad är bruuz","bruuz haj","vem är hajen bruuz"}},{q="Varför utlyste Gazlowe en belöning för Bruuz?",a="Bruuz stör sjöfarten och handeln som driver Ratchets ekonomi. Gazlowe erbjuder en kontant belöning för hajens kropp för att skydda verksamheten vid kajerna.",al={"varför döda bruuz","gazlowes hajuppdrag","varför vill gazlowe ha bruuz fena"}},{q="Var brukar Bruuz hålla till?",a="Bruuz stryker omkring i vattnen utanför Ratchet i The Barrens, ofta nära de största lastkajerna och hamninloppet.",al={"bruuz plats","var finns bruuz","hitta bruuz"}},{q="Vilket bevis kräver Gazlowe för dödandet?",a="Gazlowe kräver Bruuzs ryggfena som bevis på att hajen har dödats innan han betalar ut belöningen.",al={"lämna in bruuz","vad tar man med till gazlowe","bruuz ryggfena"}},{q="Kan både alliansens och hordens äventyrare ta sig an efterlysningen?",a="Ja. Ratchet styrs av det neutrala Steamwheedle Cartel, och Gazlowe välkomnar dugliga äventyrare från båda fraktionerna att ta hand om hajen.",al={"är wanted: bruuz neutral","kan horden göra wanted: bruuz","kan alliansen göra bruuz"}},{q="Varför riktar efterlysningen sig särskilt till fiskare?",a="Efterlysningen förklarar inte varför den vänder sig till fiskare. Den inleds med ”Alla fiskare sökes!” och utlovar en rejäl belöning för Bruuzs fena.",al={"alla fiskare sökes bruuz","är det här ett fiskeuppdrag"}}},fp="13,145,19.347.0,16.231.0,13.141.0,39.144.0,29.107.0,45.101.0,57.140.0,50.139.0"}
P.entries["quest:92707"] = {n="The Giant in the Den",s="Du bär på de kolossala handledsskydden som slitits loss från en fallen jättes kropp. Drum Fel vid Hammerfall måste se hur stora bestarna som stryker omkring i vildmarken är, så att han kan förbereda sina soldater på faran som väntar.",h="Du bär på de kolossala handledsskydden som slitits loss från en fallen jättes kropp.",kw={"armskydd","drum fel","jätte","hammerfall","witherbark","handledsskydd"},ang={["faction:Horde"]="Som krigare i Horde visar du att du delar hans vaksamma blick över höglandet när du bär bevis på dödade monster till Drum Fel i Hammerfall."},sec={{t="Vildmarkens trofé",b="Du bär på de enorma handledsskydden från en fallen jätte, slitna direkt från bestens kvarlevor. De är så breda att du får in hela armen utan att röra metallen. Drum Fel vakar över Hammerfall och har inte råd med några blinda fläckar, så bevis på sådana väldiga fiender hör hemma hos honom."},{t="Ord från Hammerfall",b="Drum Fel blir varken chockad eller skakad av de väldiga handledsskydden. Utposten har drabbat samman med Witherbark-jättar förut och räknar med att strida mot dem igen. Ändå berömmer han ditt omdöme att genast varna Hammerfalls försvarare för hotet."}},faq={{q="Vem är Drum Fel?",a="Drum Fel är en orkisk officer stationerad vid Hordens utpost Hammerfall. Han håller uppsikt över alla hot som lurar i de omgivande trakterna.",al={"vem är drum fel","drum fel hammerfall"}},{q="Vad är en Witherbark-jätte?",a="De är väldiga bestar som strider för trollstammen Witherbark, så massiva att en vuxen resenär kan trä igenom hela armen genom ett av deras handledsskydd.",al={"vad är jättar","witherbark-troll jättar"}},{q="Varför måste handledsskydden till Hammerfall?",a="Drum Fel måste känna till varje fara som stryker omkring i höglandet, och handledsskydden visar utposten hur enorma bestarna ute i vildmarken är.",al={"varför hammerfall","ta handledsskydd till hammerfall"}}},fp="20,200,19.295.0,21.265.1,16.134.0,29.154.0,42.154.0"}
P.entries["quest:92708"] = {n="A Grand Adventure",s="A Grand Adventure markerar en vändpunkt för krisen på Zephras Isle i Skywall. Under ledning av Ayessa Dawnsinger och Windshapers skisseras en djärv plan för att rädda deras hem genom att resa ner till Azeroths dödliga värld.",h="A Grand Adventure markerar en vändpunkt för krisen på Zephras Isle i Skywall.",kw={"a grand adventure","ayessa dawnsinger","azeroth","skywall","vindandar","windshapers","zephras isle"},ang={["race:Skyborne"]="För Skywalls himmelsburna folk innebär detta en monumental perspektivförändring: de lämnar sitt hems elementära rike och beger sig ner till Azeroth för att söka räddning åt Zephras Isle."},sec={{t="Krisen på Zephras Isle",b="Zephras Isle står inför en växande kris då vindandar har försvunnit utan förklaring. Som svar har Windshapers undersökt dessa störningar och upptäckt oväntade sanningar om sina försvunna fränder och sitt elementära hems öde. Ayessa Dawnsinger söker dugliga äventyrare som kan ta till sig deras upptäckter och förbereda sig för ett aldrig tidigare skådat uppdrag."},{t="En färd bortom Skywall",b="När Ayessa Dawnsinger berättar om sina upptäckter avslöjar hon en djärv och okonventionell slutsats: Skywall ensamt har varken kraften eller kunskapen som krävs för att rädda Zephras Isle. Räddningen finns i stället nedanför, i Azeroths dödliga värld. Att färdas bortom deras hemland innebär ett djärvt brott mot traditionen och ber äventyrare att ge sig ut i det okända för att säkra öns framtid."}},faq={{q="Vad är uppdraget A Grand Adventure?",a="A Grand Adventure är ett avgörande uppdrag som Ayessa Dawnsinger ger på Zephras Isle. Där berättar hon om Windshapers slutsats: för att rädda deras hem måste de lämna Skywall och bege sig till Azeroth.",al={"vad är det här för uppdrag","uppdraget grand adventure","vad är a grand adventure"}},{q="Vem är Ayessa Dawnsinger?",a="Ayessa Dawnsinger är en viktig medlem av Windshapers på Zephras Isle. Hon undersöker krisen som hotar ön och föreslår en plan för att söka hjälp och kraft från Azeroth.",al={"vem är ayessa","dawnsinger","vem är ayessa dawnsinger"}},{q="Vilken kris pågår på Zephras Isle?",a="Zephras Isle drabbas av en allvarlig kris där vindandar har försvunnit. Windshapers har undersökt försvinnandena för att hitta ett sätt att rädda sitt hem.",al={"vad är krisen på zephras isle","vad hände på zephras isle","zephras problem"}},{q="Vilka är Windshapers?",a="Windshapers är en grupp på Zephras Isle som arbetar för att undersöka och lösa de elementära störningar och försvinnanden av vindandar som hotar ön.",al={"vilka är windshapers","windshapers zephras"}},{q="Varför måste Windshapers resa till Azeroth?",a="Ayessa Dawnsinger tror att kunskapen, den outnyttjade potentialen och kraften som krävs för att lösa krisen på Zephras Isle inte finns enbart i Skywall, utan måste sökas i världen nedanför, på Azeroth.",al={"varför resa till azeroth","varför lämna skywall","vägen till räddning"}},{q="Vad är Skywall?",a="Skywall är Windshapers och Zephras Isles elementära hemrike, beläget ovanför Azeroths dödliga värld.",al={"vad är skywall","var ligger skywall"}}},fp="17,165,26.318.0,24.283.1,36.158.0,25.150.0,44.145.0,24.95.0,49.142.0,16.107.0"}
P.entries["quest:92709"] = {n="A Grand Adventure",s="I Valanaar ber Elaadrin Evengale dig att lyssna på High Orders planer. Deras sökande efter uråldrig magi kan forma Zephras Isles framtid.",h="I Valanaar ber Elaadrin Evengale dig att lyssna på High Orders planer.",kw={"a grand adventure","uråldrig magi","elaadrin evengale","high order","highborne","kirin tor","valanaar","zephras isle"},sec={{t="Ett förlorat arv",b="Elaadrin talar om din härkomst som Highborne och de unga som kan hjälpa till att rädda sitt hem. High Order söker sina förfäders uråldriga magi och det som har gått förlorat under många årtusenden."},{t="Vägen framåt",b="Elaadrin säger att Azeroth är nyckeln till sökandet. Kirin Tor ska visa High Order vägen. Medan dess medlemmar förbereder sig för att ge sig av kan du tala med andra i Valanaar. Många behöver hjälp med sitt arbete."}},faq={{q="Vem ber mig att lyssna?",a="Elaadrin Evengale i Valanaar ber dig att lyssna på High Orders planer.",al={"vem är elaadrin","elaadrin evengale","vem vill prata"}},{q="Vad försöker High Order återupptäcka?",a="High Order söker sina förfäders uråldriga magi och det som gick förlorat under många årtusenden.",al={"vad letar de efter","uråldrig magi","high orders planer"}},{q="Varför söker High Order efter uråldrig magi?",a="Elaadrin säger att återupptäckten av uråldrig magi är nyckeln till att avslöja Zephras Isles hemligheter och trygga dess framtid.",al={"varför uråldrig magi","rädda zephras","öns framtid"}},{q="Vem ska visa dem vägen?",a="Elaadrin säger att Kirin Tor ska visa High Order vägen.",al={"kirin tor","vem vägleder dem","azeroth-planen"}},{q="Vad kan jag göra medan de förbereder sig för att ge sig av?",a="Medan de förbereder sig för att ge sig av kan du tala med andra medlemmar av High Order i Valanaar. De flesta behöver hjälp med sitt arbete.",al={"hjälp i valanaar","andra medlemmar i high order","vad händer sedan"}}},fp="17,139,15.193.0,13.195.1,27.72.0,44.90.0,43.111.0,27.61.0,42.124.0"}
P.entries["quest:92727"] = {n="The Missing Scholar",s="The Missing Scholar handlar om Fillion Flamebreezes försvinnande. Han var forskare vid High Order och skickades till Zephras för att undersöka atmosfärisk magi. Hans spår längs vägen mellan Valanaar och Shen'dar Highlands visar hur farliga forskningsresor över ön kan vara.",h="The Missing Scholar handlar om Fillion Flamebreezes försvinnande.",kw={"blodfläckad väska","fillion flamebreeze","high order","shen'dar highlands","the missing scholar","valanaar","vindburen magi","zephras"},ang={["class:Mage"]="Magiker som undersöker Zephras naturliga avvikelser delar Flamebreezes nyfikenhet på de vindburna, magiska strömmar som samlas i högländerna.",["race:Skyborne"]="Zephras vindar och atmosfäriska magi är av största intresse för Skyborne, men terrängens dolda faror utgör ett hot även mot forskare."},sec={{t="The High Order:s uppdrag",b="Att söka kunskap är den lärda orden High Orders främsta uppgift, men akademiskt fältarbete på Zephras har blivit allt farligare. När forskaren Fillion Flamebreeze gav sig av mot Shen'dar Highlands för att studera atmosfäriska, magiska fenomen rapporterade han aldrig tillbaka. Hans kollegor började befara att faror i området hade tagit honom längs gränsvägarna."},{t="Spår längs vägen i väster",b="Flamebreeze lämnade bosättningen Valanaar och begav sig västerut mot Shen'dar Highlands karga bergstrakter för att samla in empiriska uppgifter om vindburen magi som samlas bland topparna. Han försvann innan han nådde fram. En genomsökning av färdvägen hittar bara hans personliga väska kvar i smutsen, med stänk av intorkat blod. Det råder därför allvarliga tvivel om att han överlevde."}},faq={{q="Vem är Fillion Flamebreeze?",a="Fillion Flamebreeze är en forskare knuten till High Order på Zephras. Han skickades ut för att undersöka den mystiska vindburna magi som samlas i Shen'dar Highlands, men försvann sedan spårlöst längs vägen.",al={"vem är fillion flamebreeze","fillion flamebreeze bakgrund","vem är den försvunna forskaren"}},{q="Vad hände med Fillion Flamebreeze?",a="Fillion nådde aldrig fram. Längs vägen västerut mot Shen'dar Highlands finns bara hans övergivna väska kvar. Den har ett broderat namn och olycksbådande stänk av intorkat blod som tyder på att han överfölls eller attackerades.",al={"vad hände med fillion","dog fillion","fillion flamebreezes öde"}},{q="Vad är High Order?",a="High Order ägnar sig åt att samla in och bevara kunskap om Zephras. Trots sitt akademiska uppdrag har arbetet på ön blivit allt farligare på grund av vilda magiska fenomen och hot längs vägarna.",al={"high orders uppdrag","vad gör high order","high order zephras"}},{q="Varför reste Fillion till Shen'dar Highlands?",a="Flamebreeze reste till Shen'dar Highlands för att dokumentera och samla in uppgifter om ovanlig vindburen magi som samlas och strömmar genom vissa delar av det höglänta området.",al={"vart var fillion på väg","vindmagi shendar","varför reste han till högländerna"}},{q="Var sågs Fillion Flamebreeze senast?",a="Forskarens blodfläckade väska ligger längs vägen västerut från Valanaar, där den börjar stiga mot Shen'dar Highlands.",al={"var finns väskan","fillions väskas plats","vägen från valanaar"}},{q="Vad är den vindburna magin i Shen'dar Highlands?",a="Vindburen magi är atmosfäriska, magiska strömmar som naturligt samlas på vissa högt belägna platser på Zephras, särskilt i Shen'dar Highlands. Därför är de ett viktigt studieområde för magiker.",al={"vad är vindburen magi på zephras","vindmagi i högländerna"}}},fp="19,224,24.308.0,26.321.1,27.158.0,37.214.0,23.152.0,53.139.0,40.129.0,54.177.0"}
P.entries["quest:92741"] = {n="Unwelcome Visitors",s="Unwelcome Visitors är ett uppdrag i Valanaar som ges av Iaadaria Bitterwind på uppdrag av High Order. En plötslig ökning av shrieklingbeståndet i den farliga Shadowgale Forest hotar att sprida sig till omgivande områden. Äventyrare får i uppdrag att gå in i den avspärrade skogen, gallra bland bestarna och samla in deras klor för lärda studier och alkemisk forskning.",h="Unwelcome Visitors är ett uppdrag i Valanaar som ges av Iaadaria Bitterwind på uppdrag av High Order.",kw={"alkemiska egenskaper","iaadaria bitterwind","shadowgale forest","shriekling","shriekling talons","the high order","unwelcome visitors","valanaar"},ang={["class:Druid"]="Shrieklingarnas plötsliga explosionsartade ökning och utbredning visar på en ekologisk störning i Shadowgale Forest som kräver ett snabbt ingripande för att återställa den naturliga balansen.",["class:Hunter"]="Jägare är väl lämpade att spåra och minska det överbefolkade shrieklingbeståndet i Shadowgale Forest och ta på sig rollen som skogvaktare och fångstmän, något som High Order öppet föraktar."},sec={{t="Shrieklinginvasionen",b="Shadowgale Forest har länge ansetts vara ett farligt område där vanliga äventyrare inte får vistas. Men gränsen har börjat suddas ut. Skogens inhemska shrieklingar har blivit fler än någonsin och trängs nu mot skogsbrynet, redo att utvidga sina jaktmarker bortom trädkronorna. Om ingen hejdar dem riskerar rovbestarna att tränga in på bebodda marker och färdvägar. Då blir ett avskilt hot ett aktivt hot mot hela trakten."},{t="Vetenskaplig jakt",b="I Valanaar ser Iaadaria Bitterwind från High Order både faran och de vetenskapliga möjligheterna med angreppet. High Order brukar avstå från vardaglig skadedjursbekämpning och från att agera enkla fångstmän, men shrieklingklornas unika alkemiska egenskaper gör ett undantag värt besväret. Genom att anlita erfarna äventyrare för att bege sig in i Shadowgale Forest och säkra åtta klor skyddar Orden samhället och får samtidigt tag på sällsynta biologiska reagenser till sina studier."}},faq={{q="Vem ger uppdraget Unwelcome Visitors?",a="Unwelcome Visitors ges av Iaadaria Bitterwind, en forskare med anknytning till High Order som är stationerad i Valanaar. Hon ber dugliga resenärer att jaga shrieklingar i den närliggande vildmarken och samla material till hennes alkemiska studier.",al={"vem ger unwelcome visitors","uppdragsgivare för unwelcome visitors","var hämtar man unwelcome visitors"}},{q="Varför är High Order intresserade av shrieklingarna?",a="High Order anser i regel att fångst och skadedjursbekämpning ligger under deras värdighet, men Iaadaria Bitterwind ser en chans till vetenskaplig vinning. Shrieklingklor har särskilda alkemiska egenskaper, så Orden kan studera värdefulla reagenser och samtidigt låtsas hjälpa trakten.",al={"varför vill high order ha klor","high order och shrieklingar","iaadaria bitterwinds motiv"}},{q="Varför måste shrieklingbeståndet gallras?",a="Under de senaste månaderna har shrieklingarna i Shadowgale Forest ökat kraftigt i antal. När de blev fler började bestarna tränga utanför sitt vanliga skogsområde. Om spridningen inte hejdas utgör de ett växande hot mot närliggande områden.",al={"varför döda shrieklingar","hotet från shrieklingarna","varför är shrieklingar ett problem"}},{q="Var ligger Shadowgale Forest?",a="Shadowgale Forest är en förrädisk skog nära Valanaar. Den är känd för att vara ytterst farlig och brukar vara avspärrad för vanliga resenärer och oerfarna äventyrare på grund av det våldsamma djurlivet där.",al={"var ligger shadowgale forest","shadowgale forests läge","hur tar man sig till shadowgale forest"}},{q="Vad är shrieklingar?",a="Shrieklingar är våldsamma rovdjur som hör hemma i Shadowgale Forest. De har vassa klor med alkemisk kraft, och under de senaste månaderna har de förökat sig snabbt. De är tillräckligt aggressiva för att ta sig ut ur skogen och hota marker bortom sitt vanliga habitat.",al={"vad är en shriekling","shrieklingarnas historia","vad är shrieklingar för slags bestar"}},{q="Vilka föremål behövs för att slutföra Unwelcome Visitors?",a="Äventyrare som tar sig an Unwelcome Visitors måste bege sig in i Shadowgale Forests farliga djup, döda de talrika bestarna och hämta åtta Shriekling Talons. Troféerna lämnas direkt till Iaadaria Bitterwind i Valanaar för att hjälpa henne med hennes lärda studier och alkemiska forskning.",al={"målen med unwelcome visitors","vad behövs för unwelcome visitors","antal shrieklingklor som behövs"}},{q="Varför får vanliga äventyrare inte gå in i Shadowgale Forest?",a="Shadowgale Forest anses vara ytterst farlig och är officiellt avspärrad för vanliga äventyrare på grund av det dödliga djurlivet och den förrädiska miljön. Bara de som är beredda på stor fara vågar sig in i skogen, till exempel de som anlitats för att gallra bland de aggressiva shrieklingarna.",al={"varför är shadowgale avspärrad","faror i shadowgale forest","får vem som helst gå in i shadowgale forest"}}},fp="18,160,20.339.0,17.417.0,39.185.0,53.263.0,45.190.0,35.171.0,21.215.0,55.162.0,58.217.0"}
P.entries["quest:92742"] = {n="Testing the Wells",s="Alba Fairmoon skickar dig genom Westfall för att testa gårdarnas brunnar. Proverna kan avslöja vad som förgiftar jorden och grundvattnet.",h="Alba Fairmoon skickar dig genom Westfall för att testa gårdarnas brunnar.",kw={"alba fairmoon","grundvatten","the jansen stead","the molsen farm","gift","testing the wells","vattenprov","westfall"},ang={["class:Druid"]="Som druid inser du att onaturliga gifter i jord och färskt grundvatten skadar landets balans och kräver helande.",["faction:Alliance"]="Som medlem av Alliansen vet du att Westfalls gårdar måste producera mat för att Stormwinds kungarike ska överleva. Brunnarnas hälsa angår hela kungariket."},sec={{t="Förgiftning i grundvattnet",b="Alba Fairmoon ber dig testa grundvattnet i Westfall. Försummelse och banditdåd har redan skadat de öppna slätterna, och gift under jorden hotar den jordbruksmark som finns kvar. Du samlar prover från gårdsbrunnar så att Alba kan ta reda på vad som förorenar jorden och vattnet."},{t="Gårdar i gränslandet",b="Du tar prover från brunnarna vid The Jansen Stead och The Molsen Farm. Dessa gårdar ligger bland utspridda gårdar som hotas av Defiaslaglösa och vilda djur. Vattnet från deras brunnar kan visa om förgiftningen stiger upp ur marken, orsakas av magi eller medvetet har hällts i vattnet som försörjer regionen."}},faq={{q="Vad är syftet med Testing the Wells?",a="Alba Fairmoon vill ta reda på varifrån giftet som drabbar Westfall kommer och vad det är. Färska grundvattenprover från gårdsbrunnar låter henne undersöka föroreningen.",al={"varför testa brunnarna","målet med att testa brunnarna","vad går uppdraget ut på"}},{q="Vem ger dig uppdraget?",a="Alba Fairmoon ger dig uppdraget medan hon undersöker den utbredda korruptionen och de onaturliga gifterna i Westfall.",al={"vem ger uppdraget testing the wells","alba fairmoon uppdrag","uppdragsgivare"}},{q="Vilka platser ska provtas?",a="Du tar prover från brunnarna vid The Jansen Stead och The Molsen Farm i Westfall.",al={"vart ska jag gå","vilka brunnar","brunnarnas platser"}},{q="Vad hotar Westfalls vatten och jord?",a="En okänd förgiftning eller ett gift fördärvar Westfalls mark. Att testa brunnsvattnet är första steget mot att ta reda på om grundvattnet under gårdarna är förorenat.",al={"varför är westfall förgiftat","vad förgiftar marken","giftets källa"}},{q="Är föroreningen naturlig eller konstgjord?",a="Orsaken är ännu okänd. Prover från The Jansen Stead och The Molsen Farm kan visa om förruttnelsen kommer av naturlig förorening av grundvattnet eller av avsiktligt sabotage.",al={"är vattnet förgiftat med flit","vem förgiftade brunnarna"}},{q="Varför fokusera på The Jansen Stead och The Molsen Farm?",a="The Jansen Stead och The Molsen Farm är etablerade gårdar med brunnar som hämtar vatten från grundvattennivån under slätterna. Genom att testa dem kan man se hur långt föroreningen har spridit sig.",al={"varför jansen och molsen","varför dessa gårdar"}}},fx={["40e3ab69"]={q="Varför vill Alba Fairmoon att det här görs?",a="Alba Fairmoon försöker hitta källan till och den exakta karaktären hos giftet som förorenar Westfalls jord och grundvatten. Genom att analysera vatten direkt från brunnarna på gårdar i drift hoppas hon kunna fastställa vad som förstör landet innan föroreningen sprider sig bortom all räddning.",al={"varför alba vill ha vattenprover","alba fairmoons motiv","varför testa brunnarna"}},d6dffc38={q="Vad ska vattenprovet från The Jansen Stead användas till?",a="Det här provet ger Alba Fairmoon grundvatten direkt från The Jansen Stead. Genom att undersöka det tillsammans med prover från andra gårdar kan hon spåra om fördärvet sprider sig djupt ner i grundvattenmagasinen i Westfall eller läcker ut från en specifik lokal föroreningskälla.",al={"vad vattenprovet från the jansen stead används till","varför hämta vatten från the jansen stead","syftet med provet från the jansen stead"}},fcb7e3cb={q="Vad ska vattenprovet från The Molsen Farm användas till?",a="Det här vattnet, hämtat från brunnen vid The Molsen Farm, låter Alba Fairmoon undersöka hur omfattande föroreningen är på olika delar av Westfalls jordbruksmark. Genom att jämföra dess renhet med andra lokala brunnar kan hon bedöma hur giftet sprider sig och hur kraftigt det är.",al={"vad vattenprovet från the molsen farm används till","varför samla in prov från the molsen farm","syftet med vattnet från the molsen farm"}}},fp="17,131,21.270.0,21.268.0,41.155.0,22.110.0,35.65.0,46.164.0,43.167.0,42.182.0"}
P.entries["quest:92743"] = {n="A Conqueror's Crown",s="Warug vill ha en Conqueror’s Crown från en krypta i Badlands åt Magram. I utbyte lovar han att avslöja klanens största styrka.",h="Warug vill ha en Conqueror’s Crown från en krypta i Badlands åt Magram.",kw={"badlands","centaur","conqueror’s crown","krypta","magram","magram village","anseende","warug"},sec={{t="Warugs krav",b="Warug söker en krona åt Magram i Magram Village. Han säger att den starkaste centaurklanen förtjänar vapen som motsvarar dess styrka och pekar ut Badlands som platsen att leta på. Du ska ta tillbaka kronan och samtidigt behålla ditt anseende hos Magram. I utbyte har Warug lovat en uppenbarelse."}},faq={{q="Vem vill ha Conqueror’s Crown?",a="Warug i Magram Village vill ha Conqueror’s Crown åt Magram.",al={"vem vill ha kronan","warug och kronan","krona åt magram"}},{q="Var sägs kronan finnas?",a="Warug säger att du ska leta i en krypta i Badlands.",al={"kronans plats","var finns kronan","krypta i badlands"}},{q="Varför vill Warug ha en krona?",a="Warug säger att den starkaste centaurklanen förtjänar vapen som motsvarar dess styrka, och att han själv behöver kronan mer än någon annan.",al={"varför kronan","magrams vapen","vad warug vill ha"}},{q="Vad lovar Warug i utbyte?",a="Warug lovar att avslöja Magrams största styrka.",al={"warugs löfte","magrams styrka","vad han ska avslöja"}},{q="Vad måste jag bevara medan jag söker efter kronan?",a="Du måste upprätthålla ditt anseende hos Magram medan du söker efter kronan.",al={"behålla anseendet","anseende hos magram","anseende och kronan"}}},fp="19,143,16.294.0,34.69.0,30.45.0,28.124.0,34.58.0,45.77.0"}
P.entries["quest:92744"] = {n="Murloc Gills",s="Alba Fairmoon skickar hjälp från Alliansen till Longshore i Westfall för att samla murlocgälar. Hon oroar sig för att missväxten ska nå Stora havet, och gälarna kan visa om kustvattnen är förgiftade.",h="Alba Fairmoon skickar hjälp från Alliansen till Longshore i Westfall för att samla murlocgälar.",kw={"alba fairmoon","missväxt","svält","longshore","murloc gills","havsvatten","stormwind","gifter","westfall"},ang={["class:Druid"]="Missväxt som sprider sig från inlandet till kustens ekosystem hotar den inhemska faunan. Att övervaka inhemska indikatorarter som murlocs hjälper till att skydda mot den faran.",["faction:Alliance"]="Med kung Varian försvunnen och matbrist som underblåser oroligheter är det avgörande för Stormwinds stabilitet att skydda Westfalls återstående livsmedelsförsörjning.",["race:Human"]="För Stormwinds folk är Westfalls förfall ett omedelbart hot mot deras hem, jordbruk och matbord."},sec={{t="Ett hot mot kusten",b="Westfall är redan nära ruin, med sviktande skördar, bönder som drivits bort och banditer som strövar längs vägarna. Alba Fairmoon oroar sig för att missväxten ska sprida sig från åkrarna inåt landet till Stora havet. Om kusten är förgiftad kan fisken som mättar Westfalls fattiga och pryder borden i Stormwind City försvinna. Den förlusten kan driva ett redan hårt pressat kungarike rakt in i svält."},{t="Vattnets väktare",b="Murlocs är envisa och våldsamma, men deras amfibiska kroppar gör dem till naturliga tecken på vattnets kvalitet. Deras andning filtrerar ständigt havsvatten, vilket gör gälarna särskilt mottagliga för gifter, missväxt och onaturliga föroreningar. Alba Fairmoon hoppas kunna bedöma föroreningen genom att undersöka färska gälar från murlocs som stryker omkring vid Longshore."}},faq={{q="Varför vill Alba Fairmoon ha murlocgälar?",a="Alba Fairmoon vill ha murlocgälar för att ta reda på om Westfalls missväxt har nått havet. Murlocgälar fungerar som biologiska filter och visar snabbt spår av gifter eller föroreningar i havsvatten.",al={"varför murlocgälar","alba fairmoon murlocs","uppdragets syfte"}},{q="Var finns murlocs som hör till uppdraget?",a="Murlocs stryker omkring vid Longshore, stranden längs Westfalls västkust. De håller till i det grunda vattnet och på tidvattenslätterna bortom klipporna.",al={"var finns murlocs","murlocs vid longshore","plats för murlocgälar"}},{q="Vilken större fara hotar om havet förgiftas?",a="Westfall är Stormwinds främsta spannmålsbod, och skördarna inåt landet sviktar redan. Fisket längs kusten ger livsviktig mat. Om gifter förorenar havslivet längs kusten kan kungariket drabbas av oundviklig svält.",al={"varför spelar detta roll","risk för svält i westfall","hot mot stormwind"}},{q="Är murlocs särskilt mottagliga för sjukdomar?",a="Murlocs överlever hårda förhållanden, men deras amfibiska andningssystem reagerar omedelbart på kemiska eller magiska orenheter i vattnet. Därför är de användbara när man undersöker vattenburna föroreningar.",al={"murlocernas fysiologi","blir murlocs sjuka"}},{q="Har det här uppdraget någon koppling till Defias Brotherhood?",a="Defias Brotherhood har skapat kaos och lämnat jordbruksmark obrukad i stora delar av Westfall. Alba Fairmoons undersökning handlar i stället om ekologisk missväxt och om att skydda kungarikets livsmedelskällor.",al={"koppling till defias","är det här defias"}},{q="Vem är Alba Fairmoon?",a="Alba Fairmoon är en forskare från Alliansen i Westfall som håller uppsikt över missväxten och miljöförsämringen som hotar regionens jordbruk.",al={"vem är fairmoon","alba fairmoons historia"}}},fx={["853673a8"]={q="Vad ska Longshore Murloc Gill användas till?",a="Murlocs andas genom sina gälar när de stryker omkring i kustvattnen, vilket gör deras andningsvävnad känslig för allt som förorenar havet. Alba Fairmoon använder gälarna som biologiska testobjekt. Genom att undersöka vävnaden efter gifter kan hon avgöra om den märkliga förorening som förtorkar Westfalls jord och grödor också har börjat förgifta havet.",al={"vad murloc-gälar används till","varför samla in murloc-gälar","murloc-gälar från longshore"}},["4abd0ea3"]={q="Varför jagar du murlocs vid Longshore?",a="Murlocs lever längs Westfalls västkust och utsätts ständigt för tidvattnet och havsstänket. Eftersom deras vattenlevande kroppar filtrerar kustvattnet direkt genom gälarna ger prover från dem omedelbara biologiska bevis på om föroreningar har läckt från den drabbade jordbruksmarken ut i havet.",al={"varför murlocs","vilka är murlocs vid longshore","varför angripa murlocs"}}},fp="12,190,25.325.0,26.319.0,41.169.0,44.133.0,53.215.0,42.192.0,50.195.0,21.137.0"}
P.entries["quest:92745"] = {n="The State of the Mines",s="Alba Fairmoon hittar giftiga metaller i Westfalls brunnar och oroar sig för åkermarken. Hon misstänker gruvorna som Defias Brotherhood tagit över och varnar för att jorden kan bli obrukbar i årtionden. Du beger dig till Jangolode Mine och Gold Coast Quarry för att störa gruvdriften.",h="Alba Fairmoon hittar giftiga metaller i Westfalls brunnar och oroar sig för åkermarken.",kw={"alba fairmoon","defias","gold coast quarry","jangolode mine","koboldgrävare","gruvdrift","riverpaw","giftiga utsläpp","westfall"},ang={["class:Druid"]="Som druid möter du ett akut hot från metallgifter som sipprar ut i Westfalls slätter och kustekosystem.",["faction:Alliance"]="Som medlem i Alliansen vet du att Westfall hjälper till att försörja Stormwind med mat. Om Defias förstör dess åkermark kan kungariket drabbas av svält i åratal.",["profession:Mining"]="I Jangolode Mine och Gold Coast Quarry utvinner Defias mineraler utan större hänsyn till säkerheten eller gruvornas bärighet."},sec={{t="Förgiftad jord",b="Alba Fairmoon hittar farligt höga halter giftiga metaller i Westfalls brunnar. Regionen var en gång Stormwinds viktigaste spannmålsbod, men nu hotas dess grödor. Alba misstänker att gruvorna som Defias Brotherhood tagit över förgiftar vattnet. Om föroreningen fortsätter kan den omgivande jorden ligga ofruktbar i årtionden."},{t="Tvångsarbete och rekryterad arbetskraft",b="Defias låter lokala varelser arbeta tillsammans med sina stråtrövare och tömmer Westfall på dess resurser. Riverpaw-kobolder gräver efter sten och mineraler i Gold Coast Quarry, medan koboldgrävare tunnlar genom Jangolode Mine. Om du stör deras arbete försvagas Defias förmåga att bearbeta och distribuera förorenade mineraler."}},faq={{q="Varför läcker giftiga metaller ut från Westfalls gruvor?",a="Alba Fairmoon misstänker att gruvorna som Defias Brotherhood tagit över förorenar Westfalls grundvatten med giftiga metaller. Hon vill störa gruvarbetarna för att stoppa utsläppen.",al={"varför giftigt vatten westfall","gruvföroreningar westfall","giftiga utsläpp westfall"}},{q="Vem ligger bakom gruvdriften i Westfall?",a="Defias Brotherhood kontrollerar gruvdriften i Westfall. De har tagit över det forna kungarikets infrastruktur och låter Riverpaw-kobolder och kobolder utvinna mineraler.",al={"vem driver gruvorna","vem kontrollerar westfalls gruvor","defias gruvdrift"}},{q="Var arbetar Riverpaw-kobolderna och kobolderna?",a="Riverpaw-kobolder arbetar i Gold Coast Quarry vid Westfalls västra kust, medan koboldgrävare arbetar inne i Jangolode Mine i norr.",al={"var finns gruvarbetarna","gold coast quarry plats","jangolode mine plats"}},{q="Vem är Alba Fairmoon?",a="Alba Fairmoon undersöker Westfalls vatten och försöker skydda regionens åkermark från bestående skador.",al={"vem ger uppdraget gruvornas tillstånd","alba fairmoon bakgrund","uppdragsgivare"}},{q="Varför arbetar kobolder och kobolder för Defias?",a="Defias använder kobolder och kobolder som arbetskraft i de övertagna gruvorna. Alba säger inte hur arbetarna rekryterades.",al={"varför anlitar defias kobolder","kobolder som arbetar för defias"}},{q="Kan jorden i Westfall återhämta sig från föroreningen?",a="Alba Fairmoon säger att jorden kan återhämta sig om föroreningskällan stoppas snabbt. Om gruvdriften fortsätter kan marken förbli ofruktbar och förhärjad i årtionden.",al={"kan westfalls jord läka","kan grödor växa igen"}}},fx={f9d72c87={q="Varför vill Alba Fairmoon att gruvarbetarna dödas?",a="Vattenprover från de lokala brunnarna visade att farliga giftiga metaller sipprar ner i Westfalls jord. Alba Fairmoon vet att miljögiftet blir kvar och gör regionen ofruktbar och oförmögen att odla grödor i årtionden om den aggressiva dagbrottsbrytningen inte stoppas omedelbart.",al={"varför döda gruvarbetarna","alba fairmoons motiv","varför stoppa gruvbrytningen"}},["23ba5f2a"]={q="Vilka är gruvarbetarna i Jangolode Mine och Gold Coast Quarry?",a="Du skickas mot Kobold Diggers i Jangolode Mine och Riverpaw Miners i Gold Coast Quarry. De här varelserna arbetar inte för egen räkning, utan används som arbetskraft av Defias Brotherhood, som tog gruvorna för att skoningslöst utvinna Westfalls mineraltillgångar.",al={"vilka är gruvarbetarna","vem skickas jag att döda","kobold diggers och riverpaw miners"}}},fp="22,240,18.325.0,25.320.0,51.182.0,48.160.0,50.136.0,21.107.0,50.113.0,57.169.0"}
P.entries["quest:92747"] = {n="Moonbrook Espionage",s="Alba Fairmoon skickar dig för att spana på Moonbrook, där tecken på industri oroar Alliansen. Giftet som hittats i hela Westfall verkar inte komma från de mindre gruvorna, så blickarna vänds mot The Deadmines under staden.",h="Alba Fairmoon skickar dig för att spana på Moonbrook, där tecken på industri oroar Alliansen.",kw={"alba fairmoon","the deadmines","spioneri","industriförnödenheter","gruvor","moonbrook","gift","westfall"},ang={["class:Rogue"]="Som skurk kan du smyga genom Moonbrook och samla underrättelser om Defias verksamhet utan att väcka misstankar.",["faction:Alliance"]="Som medlem av Alliansen vet du att aktiv industri i Moonbrook hotar Westfalls kornbod och Stormwinds säkerhet.",["profession:Mining"]="Som gruvarbetare känner du till rikedomarna och den logistiska omfattningen hos de djupa schakten under Moonbrook."},sec={{t="Ett giftigt spår",b="Gruvorna som redan undersökts i hela Westfall ger inga svar om giftet som sprider sig genom regionen. Ingen känd gruvdrift ovan jord verkar vara källan. En stor plats återstår att utforska: The Deadmines vidsträckta schakt, direkt under Moonbrooks förstörda gator."},{t="The Deadmines hemligheter",b="Enligt uppgifter övergavs The Deadmines efter att Horden intog regionen under det första kriget. Ändå ligger modern industriutrustning och förnödenheter utspridda i Moonbrook. De tyder på en omfattande gruv- och tillverkningsverksamhet som döljs bakom den ruinerade stadens tomma yta."}},faq={{q="Vem ger uppdraget Moonbrook Espionage?",a="Alba Fairmoon ger dig i uppdrag att undersöka Moonbrook. Hon har granskat misstänkta gifter och industriell verksamhet i det omstridda Westfall.",al={"uppdragsgivare","vem ger moonbrook espionage","alba fairmoon"}},{q="Varför undersöker Alba Moonbrook?",a="De andra gruvorna i området visar inga tecken på att framställa giftet som Alba undersöker. Moonbrook ligger direkt ovanför The Deadmines, så hon misstänker en olaglig verksamhet under staden.",al={"varför moonbrook","vad finns i moonbrook","undersöka moonbrook"}},{q="Vad är The Deadmines?",a="The Deadmines är regionens djupaste och mest vidsträckta guldgruvor. De har betraktats som tomma ruiner sedan Stormwind föll under det första kriget, men det sägs att ohyra och banditer hemsöker dem.",al={"the deadmines historia","vad är the deadmines","deadmines historia"}},{q="Vilka föremål samlas in under spaningsuppdraget?",a="Spejare skickas för att hämta Suspicious Industrial Supplies som ligger utspridda i Moonbrook. Förnödenheterna tyder på aktiv industri och raffinering nära gruvschakten.",al={"suspicious industrial supplies","föremål i moonbrook espionage"}},{q="Vilka hot finns i Moonbrook just nu?",a="Defias Brotherhood har tagit över Moonbrook och använder dess förfallna byggnader som en främre samlingsplats. De vaktar ytans ingång till det underjordiska nätverket.",al={"fiender i moonbrook","vem kontrollerar moonbrook"}},{q="Vad bevisar fyndet av förnödenheterna?",a="Modern, tung industriutrustning i en stad som anses övergiven tyder på en samordnad fraktion som bedriver storskalig tillverkning utom räckhåll för Stormwinds myndigheter.",al={"vad betyder förnödenheterna","defias industri"}}},fp="19,209,13.271.0,24.282.1,32.144.0,36.181.0,23.198.0,53.167.0,40.161.0,39.175.0"}
P.entries["quest:92748"] = {n="Explosive Consultation",s="I Westfall förgiftar giftig industri under The Deadmines jordbruksmarken. Du beger dig till Dwarven District i Stormwind för att söka upp en ingenjör som kan skaffa kraftiga sprängämnen.",h="I Westfall förgiftar giftig industri under The Deadmines jordbruksmarken.",kw={"alba fairmoon","the deadmines","dwarven district","ingenjörskonst","explosive consultation","sprite jumpsprocket","stormwind","gifter","westfall"},ang={["faction:Alliance"]="Som medlem av Alliansen ser du hur Westfalls kämpande gränssamhällen är beroende av verkstäderna i Stormwinds Dwarven District.",["profession:Engineering"]="Som ingenjör vet du att rå styrka inte kan lösa Westfalls problem med förgiftad mark. Att slå ut stora underjordiska maskiner kräver specialiserad ammunition och noggrann teknisk skicklighet.",["race:Gnome"]="Som gnom bidrar du med teknisk uppfinningsrikedom som kan hjälpa till att neutralisera industriella hot under jord, bortom räckhåll för Alliansens reguljära styrkor."},sec={{t="En giftig källa",b="Westfall plågas av hemlösa på flykt och banditdåd under Defias Brotherhoods styre. Bevis från hela regionen tyder på ett samordnat, mekaniserat hot under jord. Industriavfall och frätande gifter förorenar marken, och spåren leder in i The Deadmines, där en organiserad verksamhet pågår under jord."},{t="Söker Stormwinds expertis",b="De befästa tunnlarna och maskineriet i The Deadmines kräver mer än vanliga vapen. För att hindra giftet från att nå Westfalls åkrar söker du hjälp i Stormwind Citys Dwarven District. Dånande smedjor, uppfinnare och handlare som säljer sprängpulver fyller stadsdelen. Där letar du efter Sprite Jumpsprocket, en ingenjör som kan ta fram sprängämnen för uppdraget."}},faq={{q="Varför behöver vi sprängämnen i The Deadmines?",a="Bevis från Westfall tyder på att en omfattande industriell verksamhet i The Deadmines producerar gifter som förorenar närliggande jordbruksmark. Kraftiga sprängämnen kan slå ut dess förstärkta maskineri.",al={"varför sprängämnen i the deadmines","varför behöver vi bomber","orsak till gifterna i the deadmines"}},{q="Vem ger uppdraget?",a="Alba Fairmoon skickar hjältar för att undersöka de onaturliga föroreningarna och oroligheterna som hotar Westfall.",al={"vem ger explosive consultation","starta explosive consultation"}},{q="Vem är Sprite Jumpsprocket?",a="Sprite Jumpsprocket är en gnomingenjör i Stormwinds Dwarven District. Hon arbetar med komplicerade mekaniska apparater och flyktiga ämnen och kan tillverka kraftfulla sprängladdningar.",al={"sprite jumpsprocket plats","vem är jumpsprocket"}},{q="Varför söka hjälp i Dwarven District?",a="Stormwinds Dwarven District är stadens industriella hjärta, med skickliga smeder, uppfinnare, sprängpulver och tekniska komponenter.",al={"varför dwarven district","stormwind och dwarven district"}},{q="Hjälper Stormwinds regering till med detta?",a="Eftersom kung Varian Wrynn är försvunnen och Adelsrådet tvekar att skicka reguljära militära garnisoner till Westfall, förlitar sig de lokala försvararna på frivilliga och privata hantverkare i huvudstaden i stället för reguljära arméregementen.",al={"hjälper armén till","varför ingenjör i stormwind"}}},fx={fe11cddb={q="Varför vill Alba Fairmoon att du letar efter sprängämnen?",a="Alba Fairmoon har hittat bevis på en omfattande industriell verksamhet djupt inne i The Deadmines. Hon har kopplat maskineriet under jord direkt till de vidriga gifter som förgiftar jorden och förstör odlingsmarken ovanför. Hon vet att en verksamhet av den här storleken inte kan monteras ner för hand, och vill därför ha kraftiga sprängämnen som kan förinta maskineriet som förorenar landsbygden innan skadorna blir oåterkalleliga.",al={"varför alba fairmoon behöver sprängämnen","alba fairmoons motiv","varför alba behöver sprängämnen"}}},fp="22,216,14.261.0,29.256.0,43.169.0,22.101.0,27.174.0,44.171.0,52.231.0"}
P.entries["quest:92749"] = {n="A Dynamite Plan",s="Sprite Jumpsprocket vill gärna använda dynamit i Stormwind. Den uppfinningsrika fixaren i Dwarven District har hört talas om industriellt sabotage och vill ha grov dynamit för att sätta sin plan i verket.",h="Sprite Jumpsprocket vill gärna använda dynamit i Stormwind.",kw={"grov dynamit","dwarven district","ingenjörskonst","sprängämnen","sabotage","sprite jumpsprocket","stormwind"},ang={["faction:Alliance"]="Som medlem i Alliansen upptäcker du Sprites explosiva plan innanför murarna i din huvudstad, Stormwind.",["profession:Engineering"]="Som ingenjör kan du tillverka grov dynamit av grovt sprängkrut och linnetyg. Det är ett enkelt prov på tidig pysslingsteknik.",["race:Gnome"]="Som gnom ser du hur Sprite Jumpsprocket möter komplicerade industriella problem med kluriga, explosiva uppfinningar."},sec={{t="Gnistor i Dwarven District",b="Sprite Jumpsprocket, en gnomisk ingenjör i Stormwinds Dwarven District, välkomnar prat om industriellt sabotage. I stället för att mana till försiktighet ber hon förbipasserande legosoldater att ta med ett knippe grov dynamit."},{t="Gnomiska ambitioner",b="Du kan tillverka grov dynamit vid en ingenjörsarbetsbänk eller byta till dig den av stadens hantverkare. Sprite ber om tio stavar, tillräckligt för att störa de industriella planer som tar form i de kringliggande områdena. Hennes plan visar de praktiska och farliga metoder som gnomer föredrar när de möter mekaniska och politiska störningar."}},faq={{q="Vem är Sprite Jumpsprocket?",a="Sprite Jumpsprocket är ingenjör i Dwarven District i Stormwind City, bland stadens smedjor och verkstäder. Hon ägnar sig åt djärva och oberäkneliga ingenjörsprojekt.",al={"sprite jumpsprocket","vem är sprite","uppdragsgivare"}},{q="Vad behöver Sprite till uppdraget?",a="Sprite behöver tio stavar grov dynamit. Du kan tillverka dem med ingenjörskonst eller skaffa dem genom handel eller auktionshuset.",al={"föremål till dynamitplanen","vad behöver jag","föremål som behövs"}},{q="Varför vill Sprite ha grov dynamit?",a="Pratet om industriellt sabotage har fångat Sprites intresse. Hon vill ha ett lager enkla sprängladdningar för att sätta igång.",al={"varför dynamit","dynamitens syfte","sabotagemotiv"}},{q="Var lämnar jag in uppdraget?",a="Sprite Jumpsprocket finns i Stormwind Citys Dwarven District.",al={"var lämnar jag in","inlämningsplats","sprites plats"}},{q="Måste jag kunna ingenjörskonst för att slutföra uppdraget?",a="Nej, du behöver inte kunna ingenjörskonst. Ingenjörer kan tillverka grov dynamit, och du kan också byta till dig den eller köpa den på auktionshuset.",al={"behöver jag ingenjörskonst","krav på ingenjörskonst","kan icke-ingenjörer göra det här"}},{q="Hur hänger det här ihop med oron kring Stormwind?",a="Sprite säger inte vad hon tänker sabotera. Hon visar bara sin iver att sätta igång med dynamit när industriellt sabotage kommer på tal.",al={"problem i stormwind","sabotage i westfall","lore om industriellt sabotage"}}},fx={dd094caa={q="Vad ska Coarse Dynamite användas till?",a="Sprite Jumpsprocket vill gärna ägna sig åt lite industrisabotage, och sprängkraft är central för planen. Coarse Dynamite ger den råa sprängkraft hon behöver för att störa maskindriften eller röja undan strukturella hinder inför sitt kommande företag.",al={"vad coarse dynamite används till","vad sprite behöver dynamit till","varför coarse dynamite"}}},fp="15,158,30.184.0,17.309.0,27.155.0,36.130.0,37.112.0,29.60.0,47.130.0,58.129.0"}
P.entries["quest:92750"] = {n="Detonation at a Distance",s="Sprite Jumpsprocket behöver ett säkrare sätt att utlösa sprängämnen, och svaret finns i Stormwind. Hon skickar dig till Stormwind Intelligence för att hämta en fjärrutlösare.",h="Sprite Jumpsprocket behöver ett säkrare sätt att utlösa sprängämnen, och svaret finns i Stormwind.",kw={"detonation at a distance","jasper fel","fjärrutlösare","si:7","sprite jumpsprocket","stormwind intelligence","westfall"},ang={["class:Rogue"]="Som rogue tar du dig in i hjärtat av SI:7:s verksamhet i Old Town, där människor utövar konsten att arbeta i hemlighet.",["profession:Engineering"]="Som ingenjör kan du tillverka stubiner och dynamit, men fjärrutlösare av militär kvalitet kommer ofta via kontakter som specialiserar sig på diskret sabotage.",["race:Gnome"]="Som gnom delar du Sprite Jumpsprockets intresse för ingenjörsproblem, men hon vänder sig till människornas underrättelsetjänst för spionammunition."},sec={{t="En kontrollerad explosion",b="Sprite Jumpsprocket vill utlösa sprängämnen på säkert avstånd. Gobliner och gnomer är kända för att hantera flyktiga kemikalier vårdslöst, men vissa sprängningar kräver försiktighet. En vanlig stubin kan utsätta den som tänder den för fara. Sprite vet att en kontrollerad explosion kräver en särskild utlösare, en sådan som vanliga uppfinnare inte har till hands."},{t="Kontakta SI:7",b="Sprite skickar dig till Stormwind Intelligence i Old Town i stället för till lokala dvärgsprängare eller vanliga ingenjörsleverantörer. Nätverket kallas SI:7, och dess hemliga agenter hanterar sabotage, smygoperationer och riktade sprängningar. Jasper Fel arbetar bland dem i huvudstaden och kan ordna diskret, farlig utrustning."}},faq={{q="Vem skickar dig på uppdraget?",a="Sprite Jumpsprocket, en gnomisk uppfinnare i Stormwinds Dwarven District, skickar dig för att hitta en fjärrutlösare.",al={"uppdragsgivare","vem startar detonation at a distance","sprite jumpsprocket uppdrag"}},{q="Vem behöver du prata med i Stormwind?",a="Sprite hänvisar dig till Jasper Fel, en medarbetare inom Stormwind Intelligence i Stormwind.",al={"var lämnar man in uppdraget","kontakt inom stormwind intelligence","jasper fels plats"}},{q="Varför behöver Sprite Jumpsprocket en fjärrutlösare?",a="Sprite vill utlösa sprängämnen på avstånd. En fjärrutlösare är mer praktisk än en okontrollerad explosion om du vill behålla armar och ben i behåll.",al={"varför fjärrutlösare","syftet med detonation"}},{q="Varför kontakta Stormwind Intelligence i stället för en ingenjör?",a="Stormwind Intelligence har specialiserad sabotageutrustning som vanliga handlare och fältuppfinnare varken lagerför eller säljer öppet.",al={"varför si:7","varför stormwind intelligence"}},{q="Var i Stormwind finns Jasper Fel?",a="Jasper Fel finns i Old Town, vid SI:7:s högkvarter där Stormwinds spioner och hemliga agenter arbetar.",al={"jasper fel stormwind","jasper fels rum"}},{q="Vilken fraktion kan utföra uppdraget?",a="Endast medlemmar i Alliance kan utföra det här arbetet, eftersom det kräver samarbete med Stormwinds kungliga underrättelseavdelning.",al={"är uppdraget bara för alliance","kan horde göra detta"}}},fx={be1ed035={q="Varför skickar Sprite Jumpsprocket dig till SI:7 i stället för att gå själv?",a="Sprite Jumpsprocket har ingen fjärrutlösare själv. Eftersom du vill ha en kontrollerad explosion som låter dig behålla armar och ben hänvisar hon dig till de listiga typerna på Stormwind Intelligence, som hon litar på kan hitta en. Uppdraget säger inte varför hon inte går själv.",al={"varför jag, sprite jumpsprocket","varför skicka spelaren till si:7","varför kan inte sprite åka till stormwind"}}},fp="24,124,18.229.0,21.299.0,30.108.0,40.84.0,53.136.0,59.133.0,41.95.0,37.125.0"}
P.entries["quest:92751"] = {n="Detonation at a Distance",s="I Moonbrook väcker explosioner under Westfall SI:7:s uppmärksamhet. Jasper Fel, en agent från Stormwind, skickar ett Remote Detonator Kit så att arbetet kan skötas på säkert avstånd.",h="I Moonbrook väcker explosioner under Westfall SI:7:s uppmärksamhet.",kw={"the deadmines","dwarven district","jasper fel","moonbrook","fjärrdetonator","si:7","sprite jumpsprocket","westfall"},ang={["class:Rogue"]="Som skurk ger mötet med Jasper Fel dig en inblick i SI:7:s hemliga nätverk, som håller uppsikt över agenter i fält och i tysthet förser dem med verktyg.",["faction:Alliance"]="Som medlem av Alliansen ser du hur Stormwind försöker återta Westfall med hemlig ingenjörskonst och underrättelsearbete i stället för öppen militär styrka.",["profession:Engineering"]="Som ingenjör kan du uppskatta en detonatorprototyp som utlöser laddningar på avstånd och undviker riskfyllda manuella stubiner vid sprängningar i grottor.",["race:Gnome"]="Som gnom visar Sprite Jumpsprockets arbete hur gnomisk ingenjörskonst förser Stormwinds spioner med prototyper."},sec={{t="Ögon i skuggorna",b="Jasper Fel och SI:7 håller uppsikt över händelser i Stormwinds områden, däribland den oroliga gränsen mot Westfall. När han får höra om sprängningsarbetet i Moonbrook vet Fel redan vad som pågår i de övergivna gruvgångarna under landsbygden."},{t="En prototyp till lösning",b="Explosioner i trånga grottor utsätter alla i närheten för fara. Jasper Fel tillhandahåller ett Remote Detonator Kit av prototypmodell, tillverkat av ingenjörer med band till Alliansen, så att sprängladdningar under Westfall kan utlösas utifrån. Han skickar dig med kitet till Sprite Jumpsprocket i Stormwinds Dwarven District och varnar dig för att nämna SI:7 för dina alvbundsförvanter."}},faq={{q="Vem är Jasper Fel?",a="Jasper Fel är agent vid Stormwinds underrättelsetjänst SI:7. Han håller utkik efter dolda hot i riket och tillhandahåller verktyg för att hantera dem.",al={"jasper fel","vem ger uppdraget detonation at a distance","uppdragsgivare"}},{q="Varför bryr sig SI:7 om Moonbrook?",a="Banditer och laglösa håller Moonbrook, vars yta leder ner till The Deadmines. Sprängningsarbetet djupt under Westfall har fångat Stormwinds underrättelsenäts uppmärksamhet.",al={"varför moonbrook","koppling till defias","grottor i westfall"}},{q="Vem är Sprite Jumpsprocket?",a="Sprite Jumpsprocket är en gnomingenjör i Stormwinds Dwarven District. Hon förbereder sprängämnen för rivningen.",al={"sprite jumpsprocket","vem tar emot detonatorn","npc att lämna in till"}},{q="Vem menar Jasper Fel med ”alvvännen”?",a="Jasper Fel syftar på Alba Fairmoon, alven som undersöker giftet i Westfall och skickade dig för att leta efter sprängämnen. SI:7 håller sitt direkta stöd hemligt för utomstående bundsförvanter.",al={"alvvän","berätta inte för alven","jasper fel alv"}},{q="Vad används Remote Detonator Kit till?",a="Remote Detonator Kit utlöser sprängladdningar på säkert avstånd, så att agenter kan röja eller rasa underjordiska passager utan att bli instängda där inne.",al={"fjärrdetonator","detonatorkit","vad gör kitet"}},{q="Vart tar det här uppdraget dig?",a="Du tar detonatorkitet till Sprite Jumpsprocket i Stormwind Citys Dwarven District.",al={"vart ska jag gå","uppdragsväg","inlämningsplats"}}},fx={dd5ef9f7={q="Varför hjälper Jasper Fel till med fjärrutlösaren?",a="Jasper Fel erbjuder ett avancerat prototypkit för utlösare till Sprite. Han ber dig hålla hans inblandning hemlig för din alvvän medan du hjälper till med den planerade sprängningen.",al={"jasper fels motiv","varför hjälpa till med utlösaren","varför ger jasper fel mig kitet"}},["2c859344"]={q="Varför ber Jasper Fel dig i stället för att sköta det själv?",a="Jasper Fel anförtror dig prototypkitet för utlösare till Sprite och ber dig hålla hans inblandning hemlig för din alvvän. Han förklarar inte varför han inte kan överlämna det själv.",al={"varför skicka mig","varför levererar inte jasper fel själv","varför inte si:7-agenter"}}},fp="24,179,19.243.0,20.334.1,18.154.0,35.165.0,27.120.0,44.162.0,42.162.0,31.88.0"}
P.entries["quest:92752"] = {n="Explosive Consultation",s="I Westfall skickar Sprite Jumpsprocket en instabil sprängladdning till Alba Fairmoon. Den armerade sprängladdningen måste nå henne säkert, med detonatorn orörd.",h="I Westfall skickar Sprite Jumpsprocket en instabil sprängladdning till Alba Fairmoon.",kw={"alba fairmoon","detonator","explosive consultation","sprängämnen","gnomisk ingenjörskonst","sprite jumpsprocket","westfall"},ang={["faction:Alliance"]="Som äventyrare för Alliansen ser du operatörer runt om i Westfall använda okonventionella vapen mot befästa banditläger och skenande maskiner.",["profession:Engineering"]="Som ingenjör känner du till riskerna med gnomisk ammunition: stor sprängkraft och en hårutlösande detonator.",["race:Gnome"]="Som gnom ser du Sprite Jumpsprocket ta med sig Gnomeregans explosiva lösningar till Westfalls hårt prövade front."},sec={{t="En explosiv leverans",b="Sprite Jumpsprocket har färdigställt ett knippe Extra-Destructive Explosives åt Alba Fairmoon. Att bära en skarp laddning genom ett krigshärjat Westfall gör en väg ännu farligare, redan hotad av Defias-banditer och vildsinta bestar."},{t="Varsam hantering",b="Sprite Jumpsprocket varnar dig för att vara försiktig med detonatorn. Lasten ska förstöra den dolda industriella verksamheten i The Deadmines, som förgiftar Westfalls odlingsmarker. Alba Fairmoon behöver sprängämnena oskadade innan hon kan använda dem."}},faq={{q="Vem ger uppdraget Explosive Consultation?",a="Sprite Jumpsprocket, en gnomisk uppfinnare i Stormwinds Dwarven District, ger dig sprängämnena att bära.",al={"vem ger explosive consultation","uppdragsgivare explosive consultation","sprite jumpsprockets uppdrag"}},{q="Vem tar emot sprängämnena när uppdraget är slutfört?",a="Alba Fairmoon i Westfall tar emot Extra-Destructive Explosives.",al={"vart ska jag ta sprängämnena","vem lämnar in explosive consultation","alba fairmoon sprängämnen"}},{q="Vilket föremål ska du transportera?",a="Du bär ett paket Extra-Destructive Explosives med en armerad, ömtålig detonator.",al={"vad lämnar sprite över","föremål i explosive consultation","vilken bomb är det här"}},{q="Varför behövs sprängämnen i Westfall?",a="Alba Fairmoon spårade gifterna som förorenar Westfalls odlingsmarker till en enorm industriell verksamhet gömd i The Deadmines. Hon sökte upp en ingenjör som kunde förse henne med sprängämnen kraftiga nog att förstöra den.",al={"varför behöver de bomber","syftet med sprängämnen i westfall","varför spränga saker i westfall"}},{q="Är uppdraget tillgängligt för Hordens äventyrare?",a="Nej. Sprite Jumpsprocket och Alba Fairmoon stöder Alliansens operationer, så bara Alliansens äventyrare kan ta sig an uppdraget.",al={"kan horden göra explosive consultation","horden explosive consultation"}},{q="Varnar Sprite Jumpsprocket dig för någon särskild fara?",a="Sprite Jumpsprocket varnar för att bomben är armerad och säger åt dig att hantera detonatorn ytterst varsamt under färden.",al={"sprites varning","bombvarning i westfall"}}},fx={bb434565={q="Varför vill Sprite Jumpsprocket att sprängämnena levereras till Alba?",a="Sprite Jumpsprocket har färdigställt de extra kraftiga sprängämnen som beställts för Alba Fairmoons arbete i Westfall. Efter att ha tillverkat den farliga lasten behöver Sprite en äventyrare som kan sköta den känsliga och riskfyllda transporten tillbaka till Alba, så att bomben kan användas som avsett.",al={"varför leverera sprängämnen till alba","sprite jumpsprockets motiv","varför tillverkade sprite bomben"}}},fp="22,151,19.237.0,18.246.0,44.105.0,52.68.0,43.86.0,38.190.0,45.117.0,60.121.0"}
P.entries["quest:92753"] = {n="Destruction in Deadmines",s="Djupt under Moonbrook förgiftar Defias industri marken. Alba Fairmoon misstänker att deras metallurgiska smedja är källan till förgiftningen och skickar dig att förstöra den med sprängämnen.",h="Djupt under Moonbrook förgiftar Defias industri marken.",kw={"alba fairmoon","the deadmines","defias brotherhood","extra-destructive explosives","metallurgisk smedja","moonbrook","sabotage","westfall"},ang={["faction:Alliance"]="När Defias smedja förstörs slår det mot maskineriet och vapnen som hotar Stormwinds suveränitet inifrån Westfall.",["profession:Engineering"]="Alba Fairmoon föreslår att använda särskilda Extra-Destructive Explosives mot tunga industrianläggningar för att undanröja den misstänkta föroreningskällan.",["profession:Mining"]="The Deadmines var en gång Stormwinds rikaste guld- och järngruvor. Defias har förvandlat dem till ett befäst smältverk som förgiftar jorden."},sec={{t="Sabotera gjuteriet",b="Under Moonbrook rymmer The Deadmines ett befäst komplex som driver Defias Brotherhood. Den tunga smedjan smälter metall och tillverkar maskiner. Alba Fairmoon tror att smedjan troligen är källan till föroreningen som plågar området. Hon vill förstöra den."},{t="En avgörande explosion",b="Smedjan ligger bakom barrikader, stråtrövare och gobliningenjörer. Du bär på Extra-Destructive Explosives och placerar dem intill smedjan. Sedan flyr du till kullarna ovanför Moonbrook, där Alba Fairmoon väntar på att detonera laddningen och hoppas att marken kan börja läka."}},faq={{q="Vad är målet med uppdraget?",a="Du ska ta dig in i The Deadmines under Moonbrook, hitta Defias Brotherhoods metallurgiska smedja och placera Extra-Destructive Explosives i närheten. Alba Fairmoon väntar vid utgången.",al={"uppdragsmål","vad ska jag göra","vad är destruction in deadmines"}},{q="Vem är Alba Fairmoon?",a="Alba Fairmoon är en agent för Alliansen i Westfall. Hon tror att förgiftningen och giftet i regionen kommer från tung smältning och industriellt arbete inne i The Deadmines.",al={"vem är alba","alba fairmoon bakgrund","uppdragsgivare"}},{q="Varför anses Defias smedja vara så farlig?",a="Alba misstänker att den stora metallurgiska smedjan i The Deadmines är källan till giftet. Hon hoppas att marken kan börja läka om den förstörs.",al={"varför förstöra smedjan","vad gör smedjan","gift från smedjan"}},{q="Var möter spelaren Alba efter att ha placerat sprängämnena?",a="Alba Fairmoon väntar i kullarna bakom Moonbrook, utanför The Deadmines nära gruvans övre utgång. Hon är redo att utlösa sprängämnena när du kommer ut i säkerhet.",al={"var väntar alba","var ligger utgången från the deadmines","var lämnar jag in uppdraget"}},{q="Var ligger smedjan i The Deadmines?",a="Smedjan ligger djupt inne i The Deadmines, bortom gruvgångarna i det industriella gjuteriet, där Defias-arbetare och goblinförmän arbetar.",al={"var ligger smedjan","smedjans läge i the deadmines","hitta smedjan"}},{q="Läker marken direkt när smedjan förstörs?",a="Alba hoppas att marken runt Moonbrook kan återhämta sig när den tunga smältningen upphör. Det kommer att ta tid att få bort spåren efter år av Defias-industri och försummelse.",al={"kommer marken att läka","upphör giftet","efterverkningar av smedjan"}}},fx={cfdfebff={q="Varför vill Alba Fairmoon att smedjan förstörs?",a="Alba tror att Defias-smedjan djupt inne i The Deadmines är den verkliga källan till den giftiga förorening som sipprar ut i den omgivande jorden. Genom att placera ut sprängämnen och krossa den enorma smältanläggningen hoppas hon kunna hejda fördärvet vid dess källa, så att Westfalls skadade jord äntligen kan börja återhämta sig.",al={"alba fairmoons motiv","varför förstöra smedjan i deadmines","varför vill alba att det här ska göras"}}},fp="24,177,22.263.0,16.278.1,33.180.0,21.167.0,48.146.0,62.163.0,48.141.0,52.146.0"}
P.entries["quest:92754"] = {n="A New Need for Shadow Protection",s="Mirda behöver Greater Shadow Protection Potions åt Magram-klanmedlemmar som beger sig söderut mot Valley of Bones. Ta dem till henne i Magram Village och bevara klanens förtroende.",h="Mirda behöver Greater Shadow Protection Potions åt Magram-klanmedlemmar som beger sig söderut mot Valley of...",kw={"klanmedlemmar","desolace","greater shadow protection potion","magram","magram village","mirda","skydd mot skugga","valley of bones"},sec={{t="Mirdas begäran",b="Mirda i Magram Village behöver att du tar med Greater Shadow Protection Potions till henne. Magram-klanmedlemmar reser längre söderut, mot och bortom Valley of Bones. Mirda säger att dryckerna behövs för att hjälpa dem att överleva och ber dig ta med tre, samtidigt som du behåller din ställning hos klanen."}},faq={{q="Vem ber om dryckerna?",a="Mirda i Magram Village ber dig ta med Greater Shadow Protection Potions till henne.",al={"vem vill ha drycker","mirdas begäran"}},{q="Varför behöver Mirda dryckerna?",a="Magram-klanmedlemmar beger sig söderut mot och bortom Valley of Bones, och Mirda säger att dryckerna behövs för att de ska överleva.",al={"varför drycker","skydd mot skugga"}},{q="Var ska jag lämna dryckerna?",a="Lämna dryckerna till Mirda i Magram Village i Desolace.",al={"var finns mirda","dryckernas plats"}},{q="Hur många drycker behöver Mirda?",a="Mirda ber om tre Greater Shadow Protection Potions.",al={"antal drycker","hur många"}},{q="Vad säger Mirda om klanmedlemmarnas färder?",a="Mirda litar inte tillräckligt på dig för att berätta om klanmedlemmarnas färder.",al={"klanmedlemmarnas färder","vad gör de"}},{q="Vad måste jag bevara hos Magram?",a="Du behöver bevara ditt rykte hos Magram medan du lämnar dryckerna till Mirda.",al={"ställning hos magram","klantrykte"}}},fp="32,180,15.300.0,30.80.0,32.143.0,29.57.0,33.55.0,50.79.0,37.89.0"}
P.entries["quest:92755"] = {n="Mysterious Mysticism",s="Halea i Gelkis Village behöver Greater Mystic Essences för att förtrolla vapen åt Gelkis windchasers. Du ombeds ge henne tre och samtidigt behålla Gelkis förtroende.",h="Halea i Gelkis Village behöver Greater Mystic Essences för att förtrolla vapen åt Gelkis windchasers.",kw={"desolace","förtrollade vapen","gelkis","gelkis village","greater mystic essence","halea","mystisk mysticism","windchasers"},sec={{t="Haleas behov",b="Halea i Gelkis Village tar till vara på magiska vapen som samlats in från fallna äventyrare. Hon använder deras mystiska rester för att förtrolla vapen, särskilt de som bärs av Gelkis windchasers. Nu behöver hon Greater Mystic Essences för att utrusta nästa rövarband."}},faq={{q="Vem ber om essenserna?",a="Halea, som arbetar med tillvaratagna magiska vapen i Gelkis Village, behöver Greater Mystic Essences.",al={"vem vill ha essenser","haleas begäran","vem är halea"}},{q="Varför behöver Halea Greater Mystic Essences?",a="Halea behöver dem för att förtrolla vapen åt Gelkis nästa rövarband, särskilt windchasers vapen.",al={"varför essenser","vad används essenser till","gelkis mysticism"}},{q="Vad gör Halea med tillvaratagna vapen?",a="Halea kan inte använda de tillvaratagna vapnen direkt, så hon tar deras magiska rester och använder dem för att förtrolla vapen.",al={"tillvaratagna vapen","vad tar halea till vara på","gelkis rester"}},{q="Var hittar jag Halea?",a="Halea finns i Gelkis Village i Desolace.",al={"haleas plats","var är halea","gelkis village"}},{q="Hur många Greater Mystic Essences behöver Halea?",a="Halea ber om tre Greater Mystic Essences.",al={"antal essenser","hur många essenser","tre mystic essences"}}},fp="20,168,14.266.0,31.98.0,44.109.0,41.119.0,23.39.0,49.45.0"}
P.entries["quest:928"] = {n="Crown of the Earth",s="Crown of the Earth är en övergångsresa som tar unga night elves från Shadowglen ut i Teldrassils större värld. Med heligt månbrunnsvatten, välsignat på toppen av Aldrassil, beger sig resenärerna söderut längs skogsvägen för att möta Corithras Moonrage i Dolanaar. Resan markerar steget från avskild träning till det brådskande försvaret av det stora världsträdet.",h="Crown of the Earth är en övergångsresa som tar unga night elves från Shadowglen ut i Teldrassils större värld.",kw={"aldrassil","corithras moonrage","crown of the earth","dolanaar","månbrunn","partially filled vessel","shadowglen","teldrassil","tenaron stormgrip"},ang={["class:Druid"]="När unga druider transporterar det helgade vattnet blir de en del av de pågående, sköra ansträngningarna att vårda och balansera Teldrassils växande ekosystem.",["class:Priest"]="Att bära månbrunnsvatten som helgats genom Elunes nåd står för hennes prästerskaps heliga plikt att värna samhällets andliga hälsa.",["race:NightElf"]="Steget utanför Shadowglens gräns är en viktig övergångsrit för varje ung Kaldorei som ger sig av för att tjäna sitt folk."},sec={{t="Lämna gläntan",b="Efter att ha visat sin hängivenhet genom att smaka på Shadowglens förtrollade månbrunnsvatten kallas de nya lärlingarna inför Tenaron Stormgrip vid Aldrassils krona. Tenaron ser att de är redo, förseglar det insamlade vattnet i ett större kärl och beordrar dem att bege sig bortom den skyddade gläntan. Vägen söderut mot Dolanaar är huvudleden ut ur Shadowglen och slingrar sig genom skogar som blivit alltmer oberäkneliga och fientliga."},{t="Vägen till Dolanaar",b="Dolanaar är den första större byn som resenärer möter när de lämnar startgläntan. Byn ligger längs kullerstensvägarna som slingrar sig genom centrala Teldrassil och sjuder av liv kring sin egen orörda månbrunn. Här väntar Corithras Moonrage, en äldste som har fått i uppgift att leda större bevarandeinsatser bland trädets grenar. Kärlet som överlämnas till honom knyter den unga äventyraren direkt till världsträdets större och oroliga öde."}},faq={{q="Vad bär jag till Dolanaar?",a="Du bär på Partially Filled Vessel, som innehåller helgat vatten från månbrunnen i Shadowglen. Tenaron Stormgrip hällde ditt första offer i kärlet så att Corithras Moonrage kan fortsätta ritualarbetet runtom i Teldrassil.",al={"vad är kärlet","lore om partially filled vessel","vad är det här för vatten"}},{q="Vem är Corithras Moonrage?",a="Corithras Moonrage är en äldste bland night elves som håller till vid månbrunnen i Dolanaar. Han vägleder äventyrare som anländer och hjälper dem att fortsätta de viktiga riter och undersökningar som krävs för att vårda det nyväxta världsträdet.",al={"vem är corithras","corithras moonrages roll","var finns corithras"}},{q="Varför skickar Tenaron bort mig från Shadowglen?",a="Shadowglen erbjuder grundläggande träning, men utmaningarna som Teldrassil står inför kräver hjälp från hela trädet. När du har visat att du kan hantera lokala hot och vörda månbrunnarna skickar Tenaron dig till Dolanaar, där större uppgifter väntar.",al={"varför lämna shadowglen","varför bege sig till dolanaar","tenaron skickar bort mig"}},{q="Var ligger vägen till Dolanaar?",a="Följ kullerstensvägen söderut från Aldrassil och förbi Shadowglens portar. Fortsätt längs kullerstenen när stigen svänger söderut och västerut, tills du kommer fram till byn Dolanaar.",al={"hur tar man sig till dolanaar","vägen till dolanaar","vägen ut ur shadowglen"}},{q="Varför varnar Tenaron för farliga bestar?",a="Tenaron säger bara att farliga bestar har strövat omkring i skogarna på sistone. Även bland Teldrassils heliga grenar har djurlivet blivit aggressivt, så det innebär en verklig risk att lämna den stenlagda stigen.",al={"varför är bestar farliga","fördärvade bestar i teldrassil","varning om att hålla sig på vägen"}},{q="Vad händer när jag kommer till Dolanaar?",a="Corithras Moonrage tar emot kärlet och skickar dig för att fylla flaskor vid andra månbrunnar runtom i Teldrassil. På så sätt fortsätter du berättelsen om trädet.",al={"vad händer efter crown of the earth","nästa uppdrag i dolanaar","vad gör corithras"}}},fx={a4343de4={q="Varför skickar Tenaron Stormgrip en äventyrare i stället för att själv leverera kärlet?",a="Tenaron Stormgrip vakar över Aldrassils grenar och sköter de heliga angelägenheterna i Shadowglen, där unga nattalver först finslipar sina färdigheter. Han kan inte överge sina plikter uppe i det stora trädet bara för att bära budburet vatten tvärs över Teldrassil. Genom att skicka lovande noviser kan han pröva din disciplin och beredskap för den större världen, samtidigt som det heliga kärlet når Corithras Moonrage utan att Shadowglen lämnas obevakat.",al={"varför skicka mig","varför behöver tenaron mig","varför tar han inte kärlet själv"}}},fp="18,172,17.281.0,20.317.0,31.196.0,26.161.0,46.219.0,30.160.0,45.177.0,37.142.0"}
P.entries["quest:92811"] = {n="Economic Warfare",s="En centaur från Magram ber dig ta med guld och silver till Desolace. Klanerna värdesätter snidat trä, medan Magram ser en användning för din sorts valuta.",h="En centaur från Magram ber dig ta med guld och silver till Desolace.",kw={"byteshandel","snidat trä","centaur","desolace","ekonomisk krigföring","guld","magram clan","silver","totem"},sec={{t="En annan uppgörelse",b="Magram Clans talesperson berättar att centaurklanerna byter snidat trä med berättelser om sin ära och sina erövringar. Bara de mest sansade bland dem får förhandla med andra klaner, och sådan handel ger en paus från striderna. Magram ber dig ta med guld och silver, trots att metallerna saknar värde för dem."}},faq={{q="Vad vill Magram Clan ha?",a="Magram Clan ber dig ta med guld och silver.",al={"vad vill magram ha","handel med guld och silver"}},{q="Vad handlar centaurklanerna med?",a="Centaurklanerna byter intrikat snidat trä som berättar om en centaurs ära och erövringar.",al={"centaurernas byteshandel","vad handlar centaurerna med"}},{q="Varför handlar centaurerna med snidat trä?",a="Snidat trä är centaurklanernas bytesvara, och sniderierna berättar om en centaurs ära och erövringar.",al={"varför handla med trä","snidat trä hos centaurerna"}},{q="Vilka får handla med andra centaurklaner?",a="Bara de mest sansade centaurerna får förhandla med andra klaner.",al={"vem förhandlar mellan klaner","centaurer som får handla"}},{q="Vad innebär handel för centaurerna?",a="Handel är den enda pausen från striderna för centaurklanerna.",al={"handel och strid","paus från strider för centaurer"}},{q="Är guld och silver värdefullt för Magram?",a="Nej. Magram anser att guld och silver saknar värde, precis som din sort anser att deras totem saknar värde.",al={"magrams syn på guld","centaurernas värdering av silver"}}},fp="16,144,19.325.0,31.50.0,32.102.0,37.110.0,39.76.0,36.61.0,43.91.0"}
P.entries["quest:92812"] = {n="Economic Warfare",s="En Gelkis-kentaur ber dig samla in snidade totem från andra klaner. Sådana totem bär på berättelser och ger Gelkis mer makt att förhandla med Magram.",h="En Gelkis-kentaur ber dig samla in snidade totem från andra klaner.",kw={"byte","kentaur","desolace","ekonomisk krigföring","gelkis","magram","totem","handel"},sec={{t="Berättelser i byte",b="Gelkis håller fast vid en gammal kentaurtradition: klaner byter snidade totem som berättar om en persons eller klans stora bedrifter. Klanerna är fortfarande i konflikt, men hedrar ändå denna bytestradition. Du kan ge Gelkis totem från stupade kentaurer i andra klaner, så att de får mer att erbjuda i byte."},{t="Gelkis förråd",b="Gelkis lägger dina bidrag till sin samling, och deras makt växer. De har fortfarande långt kvar innan de kan besegra Magram Clan."}},faq={{q="Vad byter kentaurerna?",a="Kentaurklaner byter snidade totem som står för en individs eller klans stora bedrifter.",al={"kentaurernas bytesvaror","vad byts"}},{q="Varför är totemen viktiga för Gelkis?",a="Gelkis använder totemen som bytesmedel, och en större samling gör dem starkare.",al={"gelkis totem","totemens värde"}},{q="Byter kentaurerna fortfarande medan de strider?",a="Ja. Klanerna hedrar traditionen trots sin ständiga konflikt, även om tillfällena att byta har blivit få.",al={"kentaurklaner byter","byte under konflikt"}},{q="Vilken klan hoppas Gelkis besegra?",a="Gelkis hoppas besegra Magram Clan.",al={"gelkis fiende","magram clan"}}},fp="16,152,16.298.0,13.152.1,26.99.0,43.99.0,42.113.0,42.44.0"}
P.entries["quest:92814"] = {n="I Need a Tailor",s="Molkar ber dig ta med en White Bandit Mask till honom i Gelkis Village. Han hoppas kunna ge Halea, sin partner, enkla kläder att öva sin förtrollningskonst på.",h="Molkar ber dig ta med en White Bandit Mask till honom i Gelkis Village.",kw={"centaur","desolace","förtrollning","gelkis","gelkis village","halea","molkar","white bandit mask"},sec={{t="En gåva till Halea",b="Molkar ser till att Gelkis får förnödenheter och utrustning, och Halea tar hand om den magiska energin i deras vapen. Även om han inte förstår sig på förtrollning vet han att hon ofta hamnar efter utan att själv kunna rå för det. Han ber dig om en White Bandit Mask så att hon kan öva sin konst på enkla kläder. Din hjälp bidrar också till Gelkis krigsinsats."}},faq={{q="Vem är Molkar?",a="Molkar är en Gelkis-centaur som ansvarar för att byn får förnödenheter och utrustning.",al={"vem är molkar","vem ber om masken"}},{q="Vem är Halea?",a="Halea är Molkars partner och arbetar med att ge Gelkis vapen magisk energi.",al={"vem är halea","molkars partner"}},{q="Varför vill Molkar ha en White Bandit Mask?",a="Molkar vill ge Halea enkla kläder att öva sin förtrollningskonst på.",al={"varför vit mask","mask till halea"}},{q="Var ska jag lämna masken?",a="Lämna White Bandit Mask till Molkar i Gelkis Village i Desolace.",al={"maskens plats","var finns molkar"}},{q="Hur hjälper det Gelkis?",a="Molkar säger att din hjälp bidrar till Gelkis krigsinsats och hjälper Halea att förbättra sina färdigheter.",al={"hjälp till gelkis","varför hjälpa molkar"}}},fp="15,153,16.348.0,14.85.0,13.90.0,41.78.0,26.68.0,30.93.0"}
P.entries["quest:92817"] = {n="Leather Technique",s="Talra i Gelkis Village vill studera läderarbetet på en Barbaric Harness. Gelkis-folket har motsatt sig att bära rustning, och läder är för sällsynt för att slösas bort.",h="Talra i Gelkis Village vill studera läderarbetet på en Barbaric Harness.",kw={"rustning","barbaric harness","centaur","desolace","gelkis","gelkis village","läder","talra","väst"},sec={{t="Talras begäran",b="Talra från Gelkis ber dig att ta med en Barbaric Harness till henne i Gelkis Village i Desolace. Hennes klanfränder motsätter sig att bära rustning trots sina förluster till klingor och armborstpilar. Talra hoppas kunna utforma en skyddsväst utan det obehag de klagar på, och vill studera rustningen innan hon använder det sällsynta lädret."}},faq={{q="Vem ber om rustningen?",a="Talra, en medlem av Gelkis-klanen, ber dig att ta med en Barbaric Harness till henne i Gelkis Village.",al={"vem vill ha rustningen","talras begäran","vem är talra"}},{q="Varför vill Talra ha en Barbaric Harness?",a="Talra vill studera dess teknik medan hon utformar en skyddsväst åt sina klanfränder.",al={"varför rustning","vad behöver talra den till","talras läderidé"}},{q="Varför utformar Talra en väst?",a="Hennes Gelkis-klanfränder motsätter sig att bära rustning trots att de lider förluster till klingor och armborstpilar.",al={"varför rustning","gelkis-väst","centaur-rustning"}},{q="Vad besvärar Gelkis med rustning?",a="De klagar på att rustningen kliar.",al={"rustning som kliar","varför ingen rustning","gelkis klagomål på rustning"}},{q="Var är Talra?",a="Talra är i Gelkis Village i Desolace.",al={"talras plats","talra i gelkis village","var ska rustningen lämnas"}},{q="Varför måste lädret användas varsamt?",a="Förråden är knappa, så Talra vill inte slösa läder på en dålig utformning.",al={"sällsynt läder","varför inte slösa läder","läderförråd"}}},fp="17,156,17.310.0,30.95.0,39.87.0,30.87.0,36.34.0,15.39.0,39.78.0"}
P.entries["quest:92819"] = {n="Destruction in Deadmines",s="I Westfall skickar Alba Fairmoon en agent för att förstöra Defias smedja i The Deadmines. Sprängämnena är redan utplacerade, och Alba väntar i kullarna bakom Moonbrook på fjärrutlösaren.",h="I Westfall skickar Alba Fairmoon en agent för att förstöra Defias smedja i The Deadmines.",kw={"alba fairmoon","the deadmines","defias","destruction in deadmines","detonator","sprängämnen","sabotage","westfall"},ang={["class:Rogue"]="Du infiltrerar fiendens område, placerar sprängladdningar och smiter undan före explosionen i denna hemliga sabotageaktion.",["faction:Alliance"]="Som medlem i Alliance bidrar varje slag mot Defias fäste till att skydda Westfalls kämpande gårdar och Stormwinds södra gräns.",["profession:Engineering"]="Uppdraget kretsar kring sprängningar och fjärrutlösta detonatorer, ett hantverk som kan tilltala ingenjörer."},sec={{t="Sabotage under Westfall",b="The Deadmines rymmer Defias Brotherhoods styrka under Westfall. Alba Fairmoon ger dig i uppdrag att sabotera smedjan som göms i gruvorna. Sprängämnena är redan utplacerade intill den, och du återvänder till Alba i kullarna bakom Moonbrook för att detonera dem på säkert avstånd. Hon hoppas att Westfalls förgiftade jord ska kunna börja läka när smedjan förstörts."},{t="Fjärrutlösaren",b="Laddningen ligger intill smedjan djupt inne i The Deadmines. Med en fjärrutlösare kan du detonera den utanför grottorna, efter att du återvänt till Alba Fairmoon i kullarna bakom Moonbrook. Hon hoppas att Westfalls förgiftade jord ska kunna börja läka när smedjan förstörts."}},faq={{q="Vem ger uppdraget Destruction in Deadmines?",a="Alba Fairmoon, en agent i Westfall, ger dig uppdraget och skickar dig mot Defias Brotherhoods fäste.",al={"vem ger destruction in deadmines","uppdragsgivare för detonering i deadmines","alba fairmoon-uppdrag"}},{q="Vad är uppdragets främsta mål?",a="Du detonerar sprängämnena som placerats intill Defias smedja i The Deadmines med fjärrutlösaren från utsidan av gruvorna, efter att du återvänt till Alba Fairmoon.",al={"vad gör man i destruction in deadmines","målet med destruction in deadmines","hur slutför man destruction in deadmines"}},{q="Varför angriper man The Deadmines med sprängämnen?",a="Alba Fairmoon spårade giftet i Westfalls åkermark till en stor metallurgisk smedja gömd i The Deadmines. Hon hoppas att marken ska kunna börja läka när den förstörs.",al={"varför spränga deadmines","deadmines-sabotagets bakgrund","varför använda detonator i deadmines"}},{q="Var utspelar sig uppdraget?",a="När sprängämnena har placerats återvänder du till Alba Fairmoon i kullarna bakom Moonbrook, utanför The Deadmines.",al={"destruction in deadmines-plats","var ligger destruction in deadmines","var ligger detonatorn i deadmines"}},{q="Är det här uppdraget tillgängligt för Horde-spelare?",a="Nej. Alba Fairmoon arbetar med Alliance-agenter som försvarar Westfall mot Defias Brotherhood.",al={"är destruction in deadmines bara för alliance","kan horde göra destruction in deadmines"}},{q="Vilket hot utgör Defias Brotherhood i Westfall?",a="Defias Brotherhood drev bort bönder, plundrade bosättningar och tog över Westfalls övergivna gruvor. Djupt inne i The Deadmines bygger de upp ett väpnat uppror som hotar Stormwinds kungarike.",al={"defias bakgrund i westfall","varför bekämpa defias","vad gör defias i deadmines"}}},fp="24,158,25.344.0,13.261.0,46.95.0,46.145.0,41.169.0,33.115.0,43.99.0,57.209.0"}
P.entries["quest:92834"] = {n="Avenged Tenfold",s="Avenged Tenfold handlar om Elaadrin, en lärd i High Order som försökte få slut på ett utbrott av kultvåld genom fredliga förhandlingar. När kulten Al'Aketh brutalt styckade hans sändebud och kära vän Belathaan Brightwish övergav Elaadrin diplomatin och valde snabb, magisk vedergällning mot kultisterna norr om Valanaar.",h="Avenged Tenfold handlar om Elaadrin, en lärd i High Order som försökte få slut på ett utbrott av kultvåld...",kw={"al'aketh","avenged tenfold","belathaan brightwish","elaadrin","gustberry fields","high order","shrine of akir","windshapers","windstone charms"},ang={["class:Mage"]="När Elaadrin provoceras kanaliserar han sprakande arkan kraft, vilket visar att High Orders hängivenhet till logik backas upp av en formidabel magisk styrka."},sec={{t="Det diplomatiska försöket",b="När kulten Al'Aketh inledde sin våldsamma kampanj svarade grupper som Peacekeepers och Windshapers med väpnad kraftmätning. Elaadrin, som företrädde High Order, såg sådana aggressiva uppvisningar som en dåraktig upptrappning. Han höll fast vid High Orders pragmatiska principer och vilja att undvika konflikter, trodde att ett förnuftigt samtal fortfarande var möjligt och skickade sin nära vän Belathaan Brightwish till Shrine of Akir för att förhandla om fred."},{t="Ett makabert avslag",b="Kulten svarade på Elaadrins diplomatiska försök med fruktansvärd brutalitet. Ett paket anlände med Belathaans avskurna tunga, täckt av silverpigment. Förfärad och tyngd av skuld insåg Elaadrin att det hade kostat hans kära vän livet att välja den fredliga vägen. Han medgav att Windshapers hade rätt när de avvisade förhandlingar, övergav all diplomati och beordrade resenärer att jaga kultisterna genom Gustberry Fields och vid Shrine of Akir och samla in deras Al'Aketh Windstone Charms."},{t="Försiktighet och arkan vrede",b="High Order sätter logik framför känslor och resonerar att det nästan alltid är klokast att undvika blodsutgjutelse. Men Elaadrin visar att kall logik kan slå åt båda hållen när motståndare misstar återhållsamhet för hjälplöshet. Med sprakande arkan energi omkring sig gör han klart att High Order föredrar fred, men att de som styckar deras sändebud kommer att mötas av överväldigande vedergällning."}},faq={{q="Vem är Elaadrin?",a="Elaadrin företräder High Order och försökte först nå en fredlig diplomatisk lösning med kulten Al'Aketh. När hans sändebud och nära vän Belathaan Brightwish mördades övergav Elaadrin diplomatin och beordrade att kultisterna skulle förgöras.",al={"vem är elaadrin","uppdragsgivare avenged tenfold","vem ger det här uppdraget"}},{q="Vad hände med Belathaan Brightwish?",a="Belathaan Brightwish var en nära vän till Elaadrin, som skickades som sändebud till Shrine of Akir för att inleda en fredlig dialog med kulten Al'Aketh. Kulten mördade honom brutalt och skickade tillbaka en låda med hans avskurna tunga, målad med silverpigment, till Elaadrin.",al={"vad hände med belathaan","vem är belathaan brightwish","varför dog belathaan"}},{q="Vilka är kultisterna i Al'Aketh?",a="Al'Aketh är en våldsam kult som verkar norr om Valanaar, kring Gustberry Fields och Shrine of Akir. De bär böneamuletter som kallas Al'Aketh Windstone Charms och avvisar utomståendes fredliga försök med våld.",al={"vilka är alaketh","vilka är kultisterna","al'aketh-kulten"}},{q="Vad är High Order?",a="High Order är en organisation som är stolt över sin pragmatism, sitt intellekt och sin logik. De anser i allmänhet att det klokaste är att undvika konflikter och värna om liv, men de kan ta till kraftfull magisk vedergällning när någon går dem emot.",al={"vad är high order","high orders övertygelser"}},{q="Vilka är Windshapers?",a="Windshapers och Peacekeepers är grupper som först svarade på kulten Al'Akeths våld med styrkedemonstrationer och maktspel. Elaadrin kritiserade till en början deras agerande som en vårdslös upptrappning, men medgav till sist att de hade rätt i att avvisa diplomatiska vädjanden.",al={"vilka är windshapers","windshapers och peacekeepers"}},{q="Var finns kultisterna i Al'Aketh?",a="Kultisterna i Al'Aketh samlas norr om Valanaar, särskilt i Gustberry Fields och kring Shrine of Akir, dit Belathaan Brightwish skickades före sin död.",al={"var ligger shrine of akir","var ligger gustberry fields","var finns kultisterna"}}},fp="15,227,23.376.0,20.443.1,25.341.0,16.209.0,38.249.0,30.223.0,23.186.0,24.239.0,38.164.0"}
P.entries["quest:92840"] = {n="Catching Wind",s="Catching Wind är en expedition från High Order till Overlook Standing Stones i Shen'dar Highlands. Med ett Index Esoteria skickas en agent för att mäta elementarkraften i forntida vindstensformationer, trots Windshapers häftiga och våldsamma protester.",h="Catching Wind är en expedition från High Order till Overlook Standing Stones i Shen'dar Highlands.",kw={"al'aketh","catching wind","fillion","high order","index esoteria","overlook standing stones","shen'dar highlands","valanaar","windshapers","vindstensformationer","zephras"},ang={["class:Mage"]="Magiker och lärda inom arkana uppskattar Index Esoterias analytiska funktion och ser elementarfenomen som mätbara fält för arkan forskning.",["class:Shaman"]="Schamaner kan slitas mellan Windshapers vördnad för elementarströmmarna och High Orders kliniska utvinning av rå elementarkraft."},sec={{t="Att mäta stormvindarna",b="High Order vill mäta och förstå de kaotiska elementarflöden som strömmar genom Shen'dar Highlands. För att låsa upp hemligheterna i Overlook Standing Stones skapade forskare Index Esoteria, ett precisionsinstrument avsett att samla in data från enorma vindstensformationer. High Order beskriver arbetet som livsviktig forskning som krävs för att rädda Zephras, medan lokala traditionalister ser dessa akademiska undersökningar som vanhelgande intrång i vindens domäner."},{t="Dogm mot undersökning",b="Spänningarna mellan expeditionen från High Order och Windshapers blossar snabbt upp vid stenarna. Windshapers ser studiet och utvinningen av elementarkrafter som en ren skändning av sina heliga traditioner. High Order anser att Windshapers är lika dogmatiskt trångsynta som de våldsamma Al'Aketh och vägrar låta det lokala motståndet stoppa uppdraget att rädda riket."},{t="Massakern vid de resta stenarna",b="När arbetet från High Order vid Overlook Standing Stones möter fientligt motstånd blir våld oundvikligt. Sammandrabbningen spiller blod bland vindstenarna. High Order lyckas säkra sina mätvärden med Index Esoteria, men Windshapers fördömer händelsen som en massaker, vilket förvärrar en bitter fejd som kastar sin skugga över staden Valanaar."}},faq={{q="Vad handlar uppdraget Catching Wind om?",a="Catching Wind är ett uppdrag på High Orders vägnar för att studera elementarkraften kring Overlook Standing Stones i Shen'dar Highlands. En äventyrare får i uppgift att bära ett Index Esoteria och samla in viktiga data från enorma vindstensformationer trots Windshapers fientliga motstånd.",al={"vad är catching wind","uppdraget catching wind"}},{q="Vad är ett Index Esoteria?",a="Index Esoteria är ett specialiserat mätinstrument som används av High Order. Det är utformat för att samla in, mäta och registrera data om elementarkraft direkt från de enorma vindstensformationerna vid Overlook Standing Stones.",al={"vad är index esoteria","index esoteria instrument"}},{q="Vilka är Windshapers?",a="Windshapers är en fraktion som värnar om sina heliga platser och traditionella trosföreställningar om elementarmagi. De ser High Orders akademiska forskning och tekniska apparater som en skändning och försvarar aggressivt vindstensformationerna mot utomstående intrång.",al={"vilka är windshapers","windshapers historia"}},{q="Vilka är Al'Aketh?",a="Al'Aketh är en öppet våldsam grupp som High Order nämner tillsammans med Windshapers. High Order säger att Al'Aketh är den mer öppet våldsamma av de två grupperna, men ser båda fraktionerna som farliga fanatiker bundna till felaktiga och orubbliga dogmer.",al={"vilka är al'aketh","al'aketh"}},{q="Var ligger Overlook Standing Stones?",a="Overlook Standing Stones ligger i Shen'dar Highlands. Platsen är känd för sina enorma vindstensformationer som leder starka elementarströmmar, vilket gör den till en viktig forskningsplats för High Order.",al={"var ligger overlook standing stones","overlook standing stones plats"}},{q="Vem är Fillion?",a="Fillion är en agent eller forskare från High Order som ursprungligen skickades till Overlook Standing Stones för att mäta och studera elementarkraften. Konfrontationen med Windshapers gjorde det nödvändigt att skicka en äventyrare med Index Esoteria för att säkra uppgifterna.",al={"vad hände med fillion","vem är fillion"}},{q="Varför behöver High Order data om vindstenarna?",a="High Order anser att kunskap om rikets elementarkrafter är avgörande för deras övergripande uppdrag att rädda Zephras. De ser vetenskapliga undersökningar som nödvändiga för att övervinna elementarhot som traditionella trosföreställningar inte kan lösa.",al={"varför vill high order ha data","rädda zephras"}}},fp="13,177,19.306.0,26.322.0,27.272.1,38.234.0,26.168.0,24.199.0,21.205.0,47.183.0,15.231.0,48.184.0"}
P.entries["quest:92841"] = {n="Valley of Bones",s="Warug skickar dig till Orgrul, en kentaur nära Valley of Bones söder om Magram Village. Magramfolkets upptäckt står på spel, och Warug säger att Orgrul avgör om du får veta vad den är.",h="Warug skickar dig till Orgrul, en kentaur nära Valley of Bones söder om Magram Village.",kw={"kentaur","upptäckt","magram","magram village","orgrul","valley of bones","warug"},sec={{t="Warugs vägledning",b="Warug skickar dig till den bortre änden av Magram Village, där du ska leta efter Orgrul. Han beskriver Orgrul som en stor, illaluktande kentaur nära Valley of Bones, söder om byn. Magram måste lita på dig innan du kan få veta vad de har upptäckt."}},faq={{q="Vem ber mig hitta Orgrul?",a="Warug ber dig leta efter Orgrul, en kentaur nära Valley of Bones söder om Magram Village.",al={"vem skickade mig","warugs begäran"}},{q="Var finns Orgrul?",a="Orgrul finns nära Valley of Bones söder om Magram Village.",al={"orgruls plats","var hittar jag orgrul"}},{q="Vad vill Warug att jag ska få veta?",a="Warug säger att Magram har gjort en stor upptäckt, men att Orgrul avgör om du får veta vad det är.",al={"magrams upptäckt","vad hittade de"}},{q="Varför måste Magram lita på mig?",a="Warug säger att du måste vinna Magrams aktning innan du kan få veta mer om deras upptäckt.",al={"förbättra anseendet hos magram","magrams förtroende"}},{q="Vad händer om Orgrul vägrar berätta?",a="Warug säger att du kan finna tröst i att veta att han har fått en ny krona.",al={"warugs krona","om orgrul säger nej"}}},fp="15,187,19.255.0,32.90.0,16.59.0,33.103.0,37.93.0,42.62.0"}
P.entries["quest:92842"] = {n="A Cousin Abroad",s="En resenär ber dig leta efter en kusin som reste till Mount Hyjal. Posten kan ta flera månader att nå honom.",h="En resenär ber dig leta efter en kusin som reste till Mount Hyjal.",kw={"en kusin långt borta","post","försvunnen kusin","mount hyjal","sökning"},sec={{t="Ett avlägset sökande",b="En person med en kusin på Mount Hyjal ber dig leta efter honom. Kusinen tänkte resa dit och se vad som hände, men posten kan ta flera månader att nå honom. Hans släkting hoppas att du kan hitta honom någonstans på berget."}},faq={{q="Vem letar jag efter?",a="Du letar efter uppdragsgivarens kusin, som reste till Mount Hyjal.",al={"försvunnen kusin","kusin utomlands","vem är kusinen"}},{q="Vart reste kusinen?",a="Kusinen reste till Mount Hyjal.",al={"var är kusinen","kusinens plats","hitta kusinen"}},{q="Varför ber någon mig leta efter honom?",a="Uppdragsgivarens kusin tänkte resa till Mount Hyjal, och posten kan ta flera månader att nå honom där.",al={"varför hitta honom","varför leta efter kusinen","vad är tjänsten"}}},fp="15,106,16.215.0,21.64.0,24.31.0,37.93.0"}
P.entries["quest:92844"] = {n="Mountain of Bones",s="Orgrul i Desolace skickar dig till Valley of Bones efter lätt förbannade ben. Magram använder nu den nekromantiska magi som finns där, men orsaken är fortfarande okänd.",h="Orgrul i Desolace skickar dig till Valley of Bones efter lätt förbannade ben.",kw={"desolace","lätt förbannade ben","magram","magram village","nekromantisk energi","orgrul","valley of bones"},sec={{t="Ben åt Orgrul",b="Orgrul väntar söder om Magram Village i Desolace, där Magram har börjat använda en ny sorts magi. Någon nekromantisk kraft har spridit sig genom Valley of Bones, men orsaken är fortfarande okänd. Orgrul ber dig hämta lätt förbannade ben åt honom utan att försämra ditt anseende hos Magram."},{t="En ungefärlig räkning",b="Orgrul börjar räkna benen du kommer med, men tappar räkningen när antalet växer. Han tycker att högen ser tillräckligt stor ut och säger att han behåller den, men varnar dig för att lura honom."}},faq={{q="Vem ber om benen?",a="Orgrul, söder om Magram Village i Desolace, ber dig hämta lätt förbannade ben.",al={"vem är orgrul","benhämtare"}},{q="Var finns benen?",a="Benen finns i Valley of Bones i Desolace.",al={"benens plats","var ligger valley of bones"}},{q="Varför vill Orgrul ha benen?",a="Orgrul ber dig hämta lätt förbannade ben åt honom, men säger inte varför han vill ha dem.",al={"varför ben","orgruls ben"}},{q="Vilken magi finns i Valley of Bones?",a="Någon sorts nekromantisk energi har spridit sig genom Valley of Bones, men orsaken är okänd.",al={"nekromantisk magi","förbannad dal"}},{q="Vad gör Magram med magin?",a="Magram lär dem som inte slåss med klinga eller klubba den nya magin.",al={"magrams magi","ny magi"}},{q="Vad säger Orgrul om jag har för få ben?",a="Orgrul hotar att ta ett av dina ben för varje ben du saknar.",al={"saknade ben","för få ben"}}},fp="17,166,16.289.0,13.183.1,23.83.0,20.49.0,31.87.0,37.97.0,37.78.0,44.67.0"}
P.entries["quest:92846"] = {n="Outcast Necromancers",s="En Magram i Valley of Bones vill att du dödar Gelkis-utstötta som befattar sig med förbjudna krafter. Deras exil har lett till konflikt med Magram.",h="En Magram i Valley of Bones vill att du dödar Gelkis-utstötta som befattar sig med förbjudna krafter.",kw={"kentaur","landsförvisade","gelkis","magram","nekromanter","outcast necromancers","valley of bones"},sec={{t="Utstötta i kanjonen",b="En Magram ber dig ta hand om Gelkis-utstötta i Valley of Bones. Magram har fått ett fotfäste längre in i kanjonen, och några Gelkis följde efter dem dit. Deras klan har dömt dem till exil, medan Magram inte vet om de tänker ansluta sig eller störta dem. Magram kallar dem ensamvargar som befattar sig med krafter de inte har rätt till."},{t="Magrams klagomål",b="Magram vill att de utstötta ska dö och säger att Gelkis borde ha tagit hand om sina egna. De ser de landsförvisade som en börda som en underlägsen klan lämnat efter sig och varnar för att alla fler ska dödas. Deras krav grundar sig på fejden mellan klanerna och de utstöttas förbjudna förehavanden."}},faq={{q="Vilka är Outcast Necromancers?",a="De är Gelkis som förvisats och befattar sig med krafter som Magram säger att de inte har rätt till.",al={"outcast necromancers","gelkis-nekromanter","vilka är de utstötta"}},{q="Varför har Gelkis förvisats?",a="Deras Gelkis-klan dömde dem alla till exil efter att några följt Magram in i kanjonen.",al={"varför förvisades de","orsak till gelkis exil","varför förvisade klanen dem"}},{q="Vad vill Magram att jag ska göra?",a="Magram vill att du dödar Outcast Necromancers i Valley of Bones.",al={"vad vill magram","döda de utstötta","magrams begäran"}},{q="Varför vill Magram att de ska dö?",a="Magram kallar dem ensamvargar som befattar sig med krafter de inte har rätt till.",al={"varför döda dem","magram avskyr de utstötta","varför är de fiender"}},{q="Vill de utstötta ansluta sig till Magram?",a="Magram vet inte om de landsförvisade vill ansluta sig eller störta dem.",al={"ansluta sig till magram","de utstötta ansluter sig","vad vill gelkis"}}},fp="20,159,22.359.0,22.276.0,33.81.0,26.93.0,34.77.0,35.82.0,40.75.0"}
P.entries["quest:92847"] = {n="Corrupting Tears",s="Orgrul vill ha trä från de fördömda träden och kristaller från Warug för att tillverka stavar. Han tror att Gelkis sätt att kanalisera magi kan hjälpa Magram att säkra Valley of Bones.",h="Orgrul vill ha trä från de fördömda träden och kristaller från Warug för att tillverka stavar.",kw={"corrupting tears","gelkis","laddade tårar","magram","necrokhan","orgrul","utstötta nekromantiker","förstenad bark","stavar","valley of bones","warug"},sec={{t="Orgruls plan",b="De utstötta nekromantikernas vapen har väckt Orgruls intresse, och han ser en användning för deras sätt att kanalisera magi. Du återvänder till dalen för att hämta förstenad bark och ber Warug om laddade tårar. Orgrul tänker forma dem till stavar som kan hjälpa Magram att ta Valley of Bones."},{t="Stavarna",b="Orgrul tillverkar tre stavar av materialet du kommer med. Han behåller en och ger en annan till Necrokhan som patrullerar vid den smala passagen mot alveruinerna. Den tredje får du, och Orgrul säger att du nu har en större roll i kriget."}},faq={{q="Vad vill Orgrul att jag hämtar?",a="Orgrul ber dig hämta tre bitar förstenad bark och tre laddade tårar åt honom, samtidigt som du behåller ditt anseende hos Magram.",al={"föremål i corrupting tears","vad orgrul behöver"}},{q="Varför vill Orgrul ha barken och tårarna?",a="Orgrul tänker använda barken och Warugs kristaller för att tillverka stavar, med inspiration från de utstötta nekromantikernas sätt att kanalisera magi.",al={"varför bark och tårar","vad materialen ska användas till"}},{q="Vem är Warug?",a="Warug är den som Orgrul ber dig uppsöka för att få laddade tårar.",al={"warugs kristaller","vem som har kristallerna"}},{q="Vem får stavarna?",a="Orgrul behåller en stav, ger en till Necrokhan som patrullerar nära den smala passagen mot alveruinerna och ger den tredje till dig.",al={"orgruls stavplan","vem som får stavarna"}},{q="Vad ska stavarna användas till?",a="Orgrul tror att stavarna kan hjälpa Magram att säkra resten av Valley of Bones.",al={"stavarnas syfte","varför stavar tillverkas"}}},fp="16,171,15.278.0,10.222.1,34.133.0,40.121.0,13.62.0,20.133.0,24.84.0"}
P.entries["quest:92849"] = {n="The Missing Scholar",s="The Missing Scholar följer sökandet efter Fillion Flamebreeze, en forskare som försvann på vägen tillbaka från ett uppdrag vid Overlook Standing Stones. Spåren leder till en närliggande grotta i norr, dit Fillion släpades av ett rovlystet bevingat odjur.",h="The Missing Scholar följer sökandet efter Fillion Flamebreeze, en forskare som försvann på vägen tillbaka...",kw={"fillion","fillion flamebreeze","overlook standing stones","the missing scholar","windshapers","bevingat odjur"},sec={{t="Den försvunna forskaren",b="Tecken på olycka längs vägen tyder på att forskaren Fillion Flamebreeze utsattes för ett överfall under sin resa. Spåren efter hans försvinnande leder norrut mot mynningen av en mörk grotta, där den försvunna forskaren kanske fortfarande klamrar sig fast vid livet och väntar på hjälp."},{t="Överfall av Windshapers",b="Fillion Flamebreeze var på väg tillbaka från ett forskningsuppdrag vid Overlook Standing Stones när fientliga Windshapers överföll honom. Angriparna misshandlade honom skoningslöst, släpade honom sedan till grottmynningen och lämnade honom att förblöda, helt hjälplös inför vad som än lurade därinne."},{t="Det bevingade odjurets håla",b="Medan Fillion låg döende vid grottans tröskel kom ett enormt bevingat odjur fram ur mörkret och släpade in honom. Odjuret förde honom djupt in i sitt näste som byte åt sina ungar, ett grymt öde som bara avvärjdes tack vare en räddning i sista stund."}},faq={{q="Vem är Fillion Flamebreeze?",a="Fillion Flamebreeze är en forskare som var på väg tillbaka från ett uppdrag vid Overlook Standing Stones när fientliga Windshapers överföll honom. Blödande och medvetslös utanför en närliggande grotta släpades han in av ett enormt bevingat rovdjur.",al={"vem är fillion","fillion flamebreeze","försvunnen forskare npc"}},{q="Vad gjorde Fillion vid Overlook Standing Stones?",a="Overlook Standing Stones var platsen för Fillion Flamebreezes forskningsuppdrag före överfallet. Det är oklart exakt vad han forskade om där, men hans väg tillbaka från stenarna ledde rakt in i Windshapers överfall.",al={"vad är overlook standing stones","uppdrag vid overlook standing stones","fillions uppdrag"}},{q="Vem attackerade Fillion Flamebreeze?",a="Fillion överfölls och misshandlades av angripare som kallas Windshapers. I stället för att döda honom direkt tvingade de honom till mynningen av en närliggande grotta och lämnade honom där, blödande och knappt vid medvetande.",al={"vem attackerade fillion","vad är windshapers","windshapers överfall"}},{q="Vilket odjur tog in Fillion i grottan?",a="Ett enormt bevingat odjur som hade sitt bo i grottan norr om överfallsplatsen plockade upp en medvetslös Fillion vid grottmynningen. Det släpade honom djupt in i sitt näste för att föda sig självt och sina hungriga ungar.",al={"vilket grottodjur","bevingat monster fillion","vad tog fillion"}},{q="Var kan Fillion Flamebreeze hittas?",a="Ledtrådar vid platsen för hans olycka pekar mot en grotta strax norrut. Om du söker igenom grottan hittar du Fillion fångad i odjurets häckningsplats, där han väntar på att bli räddad innan han blir uppäten.",al={"hur hittar man fillion","var är den försvunne forskaren","fillions grottplats"}},{q="Vad blev den försvunne forskarens öde?",a="Fillion överlever prövningen tack vare ett ingripande i sista stund i grottan. Om en äventyrare inte hade spårat upp honom och ingripit skulle han ha blivit middag åt det bevingade odjuret och dess avkomma.",al={"överlevde fillion","vad händer med fillion flamebreeze","rädda den försvunne forskaren"}}},fp="19,179,23.215.0,25.234.1,24.217.1,27.237.0,55.204.0,33.144.0,41.165.0,39.186.0,41.190.0"}
P.entries["quest:92850"] = {n="The Missing Scholar",s="The Missing Scholar är ett uppdrag där äventyrare hjälper forskaren Fillion Flamebreeze efter att ha hittat honom nära ett farligt näste. När Fillion återvänder oskadd till Valanaar ger han resenärer i uppdrag att döda den närbelägna Shriekling Matriarch, som hotar bosättningen.",h="The Missing Scholar är ett uppdrag där äventyrare hjälper forskaren Fillion Flamebreeze efter att ha hittat...",kw={"fillion flamebreeze","shriekling","shriekling den","shriekling matriarch","supreme magister","the missing scholar","valanaar"},ang={["class:Mage"]="Fillion Flamebreeze förlitar sig på sin egen träning i de arkana konsterna för att återhämta sig och resa tryggt, vilket visar på en samhörighet med andra som utövar magi."},sec={{t="En farlig häckningsplats",b="Efter att ha återhämtat sig från sin prövning nära ett näste med rovdjur kan forskaren Fillion Flamebreeze resa tillbaka mot tryggheten i Valanaar. Men det omedelbara hotet kan inte ignoreras: en kull shrieklings har byggt ett näste oroväckande nära bosättningen. I stället för att låta bestarna dröja kvar vid stadens tröskel ber Flamebreeze dugliga resenärer att ta sig in i Shriekling Den och döda Shriekling Matriarch."},{t="Rapport till magistern",b="När Matriarch är dödad och hennes huvud har lämnats till Fillion i Valanaar tackar forskaren, men påpekar bekymrat att shrieklings bara är det minsta av deras bekymmer. Innan Flamebreeze tar itu med större frågor förbereder han en fullständig rapport om sitt uppdrag och trakten omkring, som han ska lämna direkt till Supreme Magister."}},faq={{q="Vem är Fillion Flamebreeze?",a="Fillion Flamebreeze är en forskare med kunskaper i de arkana konsterna. Han var på ett uppdrag nära Valanaar innan han blev strandsatt nära ett näste med farliga bestar.",al={"vem är fillion flamebreeze","vem är forskaren","vem ger uppdraget the missing scholar"}},{q="Vad är shrieklings?",a="Shrieklings är fientliga bestar som har byggt bo i ett närbeläget näste, farligt nära bosättningen Valanaar. Fillion Flamebreeze varnar för att deras närhet utgör ett direkt hot mot alla som reser i trakten.",al={"vad är shrieklings","var bygger shrieklings bo","hot från shrieklings"}},{q="Vem är Supreme Magister?",a="Supreme Magister är den regionala myndigheten i Valanaar som Fillion Flamebreeze måste rapportera till om händelserna vid nästet och läget för hans uppdrag.",al={"vem är supreme magister","fillions rapport","vem rapporterar fillion till"}},{q="Vad är Valanaar?",a="Valanaar är den närbelägna bosättningen eller utposten där Fillion Flamebreeze är stationerad och dit han återvänder när han har återhämtat sig tillräckligt för att resa på egen hand.",al={"vad är valanaar","var ligger valanaar"}},{q="Vad är Shriekling Matriarch?",a="Shriekling Matriarch är ledaren för shrieklings som håller till i Shriekling Den. Fillion ger äventyrare i uppdrag att döda henne och ta med hennes huvud tillbaka för att undanröja det omedelbara hotet mot Valanaar.",al={"målet shriekling matriarch","vem ska dödas i shriekling den"}},{q="Varför anser Fillion att shrieklings är det minsta av deras bekymmer?",a="Fillion Flamebreeze ser shrieklings som ett omedelbart hot mot Valanaar på grund av deras närhet, men när du återvänder påpekar han illavarslande att de i slutänden är det minsta av deras bekymmer.",al={"varför minsta av våra bekymmer","större fara för valanaar"}}},fp="19,163,25.263.0,25.226.1,27.156.0,21.128.0,28.157.0,17.118.0,33.171.0,70.152.0"}
P.entries["quest:92858"] = {n="WANTED: Ohk'zi",s="Latronicus Moonspear utlyser en belöning för ogret Ohk'zi vid Gordunni Outpost. Hans släktingar bland Gordunni hotar Feralas, men naga utgör en större fara.",h="Latronicus Moonspear utlyser en belöning för ogret Ohk'zi vid Gordunni Outpost.",kw={"belöning","feathermoon stronghold","feralas","gordunni","latronicus moonspear","naga","ohk'zi","ohkzi","staff of ohk'zi"},sec={{t="Belöningen",b="General Feathermoon erbjuder betalning för Ohk'zis död, och Latronicus Moonspear sätter upp efterlysningen vid Feathermoon Stronghold. Gordunni-ogrerna plågar Feralas, men utgör ett mindre hot än naga. Ohk'zi sågs senast vid utposten öster om fästet. Du ombeds ta med hans stav till Latronicus som bevis på hans död."}},faq={{q="Vem är Ohk'zi?",a="Ohk'zi är ett ogre från Gordunni, som senast sågs vid deras utpost öster om Feathermoon Stronghold.",al={"ohkzi","ohk'zi ogre","vem är ohkzi"}},{q="Varför har Ohk'zi en belöning på sitt huvud?",a="General Feathermoon utlyser en belöning för Ohk'zis död eftersom Gordunni-ogrerna hotar Feralas.",al={"ohkzi belöning","varför döda ohkzi","efterlyst ohkzi"}},{q="Var sågs Ohk'zi senast?",a="Ohk'zi sågs senast vid Gordunni-utposten öster om Feathermoon Stronghold.",al={"ohkzi plats","var är ohkzi","gordunni outpost"}},{q="Vilket bevis vill Latronicus ha?",a="Latronicus Moonspear ber dig ta med Staff of Ohk'zi till Feathermoon Stronghold som bevis på hans död.",al={"ohkzi bevis","vad ska lämnas till latronicus","staff of ohk'zi"}},{q="Är Gordunni det största hotet i Feralas?",a="Gordunni är ett hot mot Feralas, men naga utgör en större fara.",al={"gordunni hot","naga eller ogrer","fara i feralas"}}},fp="14,152,10.333.0,14.93.0,32.99.0,27.76.0,32.107.0,48.73.0"}
P.entries["quest:92860"] = {n="In Service of Zephras",s="In Service of Zephras är ett uppdrag där en äventyrare överlämnar ett bud från High Order, som lovar Valanaar sitt fulla militära och diplomatiska stöd mot Al'Aketh-sekten. Tilltagande fientliga rörelser på ön har tvingat High Order att överge sin policy att undvika direkt konfrontation med sektmedlemmarna. När sändebudet överlämnar budskapet till Valennia Stormfist kommer hen också med dystra nyheter om att hennes kusin Belathaan har dött, vilket befäster deras gemensamma beslutsamhet att skydda Zephras folk.",h="In Service of Zephras är ett uppdrag där en äventyrare överlämnar ett bud från High Order, som lovar Valanaar...",kw={"al'aketh","belathaan","al'aketh-sekten","high order","in service of zephras","stormfist","valanaar","valennia stormfist","zephras"},sec={{t="Det växande hotet",b="Under en tid försökte High Order begränsa den öppna fientligheten mot den hemlighetsfulla Al'Aketh-sekten och förhindra ett fullskaligt krig över hela ön. Den bräckliga hållningen föll samman när sekten visade omisskännlig fientlighet, styrkt av oroväckande rapporter om omfattande truppförflyttningar. High Order insåg att sektmedlemmarna samlar styrkor inför en operation som hotar freden och tryggheten i varje bosättning och har därför valt att agera beslutsamt. I stället för att förbli passiva åskådare har de beslutat att bidra med sina styrkor till en aktiv allians och skickar ett sändebud för att samordna med de lokala försvararna innan Al'Aketh går till angrepp."},{t="Allians med Valanaar",b="För att möta det växande hotet från sekten skickas sändebudet till Valennia Stormfist för att officiellt erbjuda High Orders ovillkorliga hjälp i Valanaars motstånd mot Al'Aketh. Budskapet upprättar en gemensam försvarsfront mellan de två fraktionerna och banar väg för gemensamma militära insatser i regionen. Uppdraget har dock ett högt personligt pris: vid ankomsten måste resenären meddela att Belathaan, Valennias kusin och en hängiven tjänare åt Zephras, har dött. Medan Valennia sörjer hans bortgång svär hon hämnd, och den gemensamma sorgen blir till omedelbara förberedelser inför det kommande fälttåget."}},faq={{q="Vad handlar uppdraget In Service of Zephras om?",a="I In Service of Zephras får spelaren i uppdrag att uppsöka Valennia Stormfist på uppdrag av High Order. High Order försökte tidigare undvika direkt våld mot Al'Aketh-sekten, men ökande fientlighet och rapporter om omfattande truppförflyttningar från sekten runt ön tvingade dem att agera. Uppdraget innebär att High Order formellt stöder Valanaars försvar och samtidigt framför sorgliga nyheter om Belathaans öde.",al={"översikt över in service of zephras","vad händer i in service of zephras","uppdraget in service of zephras"}},{q="Vem är Valennia Stormfist?",a="Valennia Stormfist är en ledare som samordnar försvaret mot Al'Aketh i Valanaar. När High Order skickar ett sändebud för att lova sitt stöd tar Valennia emot erbjudandet om ömsesidig hjälp. Hon är också kusin till Belathaan, en fallen tjänare åt Zephras vars död rapporteras under mötet. Det får henne att svära hämnd mot sektmedlemmarna som hotar deras folk.",al={"valennia stormfists bakgrund","vem är valennia","valennia stormfist"}},{q="Vem var Belathaan?",a="Belathaan var kusin till Valennia Stormfist och en hängiven tjänare åt Zephras som dog före händelserna i det här uppdraget. Valennia minns honom som en hedervärd tjänare och försvarare av deras sak. Äventyraren bekräftar formellt hans död när hen rapporterar till Valennia, vilket gör konflikten mer personlig och stärker löftet att hämnas honom.",al={"vem är belathaan","belathaans bakgrund","vad hände med belathaan"}},{q="Vad är Al'Aketh?",a="Al'Aketh är en fientlig sekt som är verksam på ön och vars aggressiva rörelser hotar Zephras folk. High Order försökte först undvika att provocera fram direkta konfrontationer med dem, men de senaste fientliga utspelen och illavarslande rapporterna om omfattande rörelser från sekten har gjort kriget oundvikligt. Sekten har tvingat de lokala styrkorna och High Order att bilda en väpnad allians för att slå tillbaka den.",al={"vilka är al'aketh","al'aketh-sekten","vad är al'aketh"}},{q="Vilken roll har High Order i konflikten?",a="High Order försökte först undvika ett direkt krig med Al'Aketh-sekten och föredrog en återhållsam hållning. Men aggressiva handlingar och rykten om omfattande mobilisering från sekten övertygade ledningen om att neutralitet inte längre var hållbar. Genom att skicka en kurir till Valennia Stormfist lovar High Order officiellt att ställa hela sin styrka bakom Valanaars militära motstånd mot sekten.",al={"high orders inblandning","varför strider high order","high order och zephras"}},{q="Vad är Zephras?",a="Zephras är ön Zephras Isle, som High Order, Valanaar och dess försvarare alla kämpar för att skydda. High Order varnar uttryckligen för att sektens växande aktivitet bådar illa för Zephras folk, och fallna hjältar som Belathaan blir ihågkomna som trogna tjänare åt Zephras. Att skydda befolkningen är det främsta skälet till alliansen mot Al'Aketh.",al={"var ligger zephras","vem är zephras","zephras bakgrund"}}},fp="21,194,20.378.0,22.413.1,46.324.0,26.251.0,18.227.0,21.223.0,47.266.0,16.284.0"}
P.entries["quest:92867"] = {n="Ground to Keep",s="Groundskeeper Lomar ber dig driva bort inkräktare från Stromgarde Keep. Rikets kvarvarande skulpturer och heliga gravplatser behöver skyddas.",h="Groundskeeper Lomar ber dig driva bort inkräktare från Stromgarde Keep.",kw={"boulderfist","gravplatser","mark att bevara","groundskeeper lomar","skulpturer","stromgarde","stromgarde keep","syndicate","witherbark"},sec={{t="Resterna av ett kungarike",b="I Stromgarde Keep ber Groundskeeper Lomar dig driva tillbaka inkräktarna från Boulderfist, Syndicate och Witherbark. Han säger att Stromgarde har mer i reserv och att det måste förbli dolt för att skyddas. Allt fler vill bevara rikets kvarvarande skulpturer och heliga gravplatser."}},faq={{q="Vem ber om hjälp?",a="Groundskeeper Lomar ber dig driva bort inkräktarna från Boulderfist, Syndicate och Witherbark från Stromgarde Keep.",al={"vem behöver hjälp","groundskeeper lomar","vem gav uppdraget"}},{q="Varför bör Stromgardes kvarlevor skyddas?",a="Allt fler vill bevara Stromgardes kvarvarande skulpturer och heliga gravplatser.",al={"varför skydda stromgarde","vad behöver skyddas","skydda skulpturerna"}},{q="Vilka inkräktare finns i Stromgarde Keep?",a="Boulderfist, Syndicate och Witherbark har slagit sig ner i Stromgarde Keep.",al={"vilka finns i borgen","fiender i stromgarde","boulderfist syndicate witherbark"}},{q="Vad måste förbli dolt?",a="Lomar säger att Stromgarde har mer i reserv och att det måste förbli dolt för att skyddas.",al={"vad är dolt","stromgardes reserver","vad måste hållas hemligt"}}},fp="14,149,19.307.0,23.112.0,47.96.0,39.86.0,24.92.0"}
P.entries["quest:92871"] = {n="In Service of Zephras",s="Ryktet sprids över Zephras om att Al'Aketh-sekten mobiliserar inför en större konflikt. För att stärka öns försvar skickas ett sändebud för att försäkra Valennia Stormfist om att Windshapers står redo att stödja hennes fredsvakter.",h="Ryktet sprids över Zephras om att Al'Aketh-sekten mobiliserar inför en större konflikt.",kw={"al'aketh","in service of zephras","valanaar","valennia stormfist","windshapers","zephras"},sec={{t="Rykten på ön",b="Spänningarna ökar över ön Zephras, då rapporter tyder på omfattande sekteristisk aktivitet. Fredsvakterna under Valennia Stormfist har länge hållit vakt över dessa marker, men Al'Aketh verkar organisera sig inför en större konflikt. För att skydda ön har Windshapers lovat att stå stadigt vid Valanaars styrkors sida om öppna strider bryter ut."},{t="Lova stöd",b="Du skickas för att träffa Valennia Stormfist och bekräfta att Windshapers är fullt redo att hjälpa hennes fredsvakter. När Valennia får höra att de allierade är redo välkomnar hon det snabba åtagandet och förbereder sig på att diskutera den förvärrade situationen kring sekten."}},faq={{q="Vem är Valennia Stormfist?",a="Valennia Stormfist leder fredsvakterna som ansvarar för att skydda Zephras. Hon samordnar öns försvar, däribland Valanaars kampanj mot den fientliga sekten Al'Aketh.",al={"vem är valennia stormfist","valennia stormfist"}},{q="Vilka är Windshapers?",a="Windshapers är en allierad grupp på Zephras som hjälper Valennia Stormfist och hennes fredsvakter. De ger Valanaars styrkor sitt fulla stöd i kampen mot det växande hotet från Al'Aketh.",al={"vilka är windshapers","windshapers bakgrund"}},{q="Vad är Al'Aketh?",a="Al'Aketh är en sekt som verkar över hela ön Zephras. Rapporter tyder på att de genomför större förflyttningar och förbereder sig för en nära förestående konflikt.",al={"vilka är alaketh","vad är alaketh","al aketh-sekten"}},{q="Vad är Zephras?",a="Zephras är en ö som försvaras av Valennia Stormfist och hennes fredsvakter, där Windshapers hjälper till mot hotfull sektaktivitet från Al'Aketh.",al={"vad är zephras","ön zephras"}},{q="Vad är Valanaar?",a="Valanaar är en bosättning på Zephras och hem åt Valennia Stormfists fredsvakter. Windshapers ger sitt fulla stöd till dess kamp mot Al'Aketh.",al={"vad är valanaar","vem är valanaar"}}},fp="21,167,20.279.0,16.208.0,26.148.0,24.175.0,22.115.0,16.125.0,17.144.0"}
P.entries["quest:92872"] = {n="Dutiful Steps",s="Caretaker Alaric ber dig bära gravstoft från kryptan i Stromgarde Keep till havet. Riten förnyar minnescykeln för de fallna.",h="Caretaker Alaric ber dig bära gravstoft från kryptan i Stromgarde Keep till havet.",kw={"caretaker alaric","ceremonier","krypta","plikttrogna steg","fallna","great sea","påse med gravstoft","stromgarde keep","gravstoft"},sec={{t="Mot havet",b="Din väg tillbaka till den solbelysta världen börjar med en liten väska. Caretaker Alaric ber dig ta den till klipporna bakom Stromgarde Keep och kasta innehållet i Great Sea. Stoftet kommer från graven under borgen, där dess väktare bevarar ceremonier för att hedra de fallna. Varje årstid sprids en del över Azeroths hav som en symbolisk förnyelse."}},faq={{q="Vem ber mig bära stoftet?",a="Caretaker Alaric ber dig bära gravstoftet från kryptan i Stromgarde Keep till havet.",al={"vem gav mig detta","alarics begäran"}},{q="Vad finns i väskan?",a="Väskan innehåller stoft från graven under Stromgarde Keep.",al={"vad finns i påsen","gravstoft"}},{q="Varför sprids gravstoftet över havet?",a="Varje årstid sprids en del gravstoft över Azeroths hav som en symbolisk handling för att förnya kretslopp.",al={"varför kasta stoft i havet","vad är stoftet till för"}},{q="Var ska jag kasta väskan?",a="Caretaker Alaric ber dig kasta gravstoftet i Great Sea från klipporna bakom Stromgarde Keep.",al={"var ska jag kasta det","klipporna bakom stromgarde"}},{q="Vad bevarar gravens väktare?",a="Gravens väktare bevarar kunskap om ceremonier som används för att hedra de fallna.",al={"vad finns i graven","ceremonier"}}},fp="13,142,14.371.0,35.91.0,23.61.0,43.101.0,37.106.0,40.87.0"}
P.entries["quest:92880"] = {n="Return to Valanaar",s="Return to Valanaar är ett uppdrag där en äventyrare överlämnar Yorna's report om försvaret av det östra vakttornet till Valennia Stormfist i Valanaar. Rapporten bekräftar att försvarslinjen har stabiliserats och att de återstående angriparna håller på att rensas bort, till stor lättnad för bosättningens ledning.",h="Return to Valanaar är ett uppdrag där en äventyrare överlämnar Yorna's report om försvaret av det östra...",kw={"östra vakttornet","fyra vindar","return to valanaar","valanaar","valennia stormfist","yorna","yorna's report"},ang={["race:Skyborne"]="Välsignelsen som åkallar de fyra vindarna speglar de kulturella och andliga band som är gemensamma bland Valanaars försvarare och ledare."},sec={{t="Besked från utposten",b="Efter ett våldsamt angrepp på utposten skickar försvararen Yorna ett besked tillbaka till bosättningen Valanaar. Angriparna har slagits tillbaka och de återstående fienderna håller på att rensas bort. En äventyrare skickas med Yorna's Report för att lugna den oroliga ledningen som väntar på nyheter i staden."},{t="Lättnad i Valanaar",b="Budet förmedlar direkt till Valennia Stormfist i Valanaar hur det står till vid det östra vakttornet. När hon får bekräftat att tornet har hållit stånd och att försvarslinjen är stabiliserad uttrycker Valennia tydlig lättnad och tackar vindarna för att deras viktiga gränspost fortfarande är säker."}},faq={{q="Vem skickar dig till Valanaar?",a="Yorna ger dig uppdraget efter ett hårt utkämpat försvar mot fientliga angripare vid en utpost och ber dig överlämna en lägesrapport till ledningen.",al={"vem ger return to valanaar","vem skickar dig tillbaka till valanaar","yorna uppdragsgivare"}},{q="Vem rapporterar du till i Valanaar?",a="Valennia Stormfist är stationerad i Valanaar och väntar på besked om de avlägsna försvararnas säkerhet och beredskap.",al={"vem är valennia stormfist","var finns valennia stormfist","lämna in return to valanaar"}},{q="Vad är Yorna's Report?",a="Yorna's Report innehåller en uppdatering som bekräftar att försvararna har stabiliserat sin ställning efter angreppet och håller på att rensa bort de återstående angriparna.",al={"vad är yorna's report","vad står i yorna's report"}},{q="Vilket vakttorn angreps?",a="Utposten som försvaras av Yorna och hennes styrkor är det östra vakttornet, en viktig försvarsposition som bevakar vägarna mot Valanaar.",al={"vilket torn angreps","vilket vakttorn är yorna vid"}},{q="Hur är läget vid det östra vakttornet?",a="Även om några angripare fortfarande måste rensas bort har försvararna säkrat positionen, och läget vid vakttornet anses vara stabilt.",al={"är vakttornet säkert","vann försvararna"}},{q="Varför talar försvararna om de fyra vindarna?",a="Uttrycket ”Må de fyra vindarna välsigna dig” och Valennias utrop ”Tacka vindarna” visar att försvararna i Valanaar vördar vindarna och elementen.",al={"de fyra vindarnas betydelse","må de fyra vindarna välsigna dig"}}},fp="18,153,21.219.0,18.204.0,26.128.0,33.105.0,23.112.0,34.105.0,45.130.0,45.135.0"}
P.entries["quest:92881"] = {n="The High Elder's Request",s="The High Elder's Request skickar äventyrare till Valanaar för att rådgöra med High Elder Talaanis Shadowsong efter samordnade angrepp mot regionens vakttorn. Rapporter från det västra vakttornet tyder på att en fientlig kult siktar in sig på de lokala förankringspelarna.",h="The High Elder's Request skickar äventyrare till Valanaar för att rådgöra med High Elder Talaanis Shadowsong...",kw={"förankringspelare","östra vakttornet","shadowsong","skypräst","talaanis shadowsong","the high elder's request","valanaar","västra vakttornet"},ang={["class:Priest"]="Kultens intresse för förankringspelarna och den gåtfulla skyprästens inblandning vid det västra vakttornet är en oroande utveckling för präster som studerar gudomlig eller rituell manipulation."},sec={{t="Problem vid vakttornen",b="Nyliga samordnade angrepp mot både det västra och det östra vakttornet har avslöjat ett oroande mönster. Det som först verkade vara utspridda skärmytslingar pekar nu mot en välplanerad offensiv riktad mot de lokala förankringspelarna. Rapporter från konfrontationen med en skypräst vid det västra vakttornet avslöjade först kultens intresse för dessa strukturer, vilket fick myndigheterna att se försvaret av tornen som en akut angelägenhet."},{t="Möte i Valanaar",b="Medvetna om det växande hotet mot förankringspelarna uppmanar ledarna äventyrarna att tala direkt med High Elder Talaanis Shadowsong i Valanaar. High Elder har ett lovande spår om kultens rörelser och söker erfarna allierade som är beredda att spåra fienden och hindra den ritual eller det sabotage de planerar att genomföra."}},faq={{q="Vem är High Elder Shadowsong?",a="High Elder Talaanis Shadowsong är en ledare i Valanaar. När en kult genomför samordnade angrepp mot regionens vakttorn söker han kapabla äventyrare som kan följa upp lovande spår om kultens verkliga avsikter.",al={"vem är talaanis shadowsong","high elder shadowsong","var är shadowsong"}},{q="Var ligger Valanaar?",a="Valanaar är en bosättning eller fristad där High Elder Talaanis Shadowsong håller till, samordnar försvaret och undersöker kultens intrång mot de lokala förankringspelarna och tornen.",al={"vad är valanaar","valanaars plats"}},{q="Varför angreps vakttornen?",a="Samordnade angrepp träffade både det västra och det östra vakttornet. Försvararna misstänker att angreppen inte var slumpmässiga räder, utan avsiktliga manövrer för att angripa eller manipulera de närliggande förankringspelarna.",al={"varför angreps vakttornen","västra och östra vakttornen","angrepp mot vakttornen"}},{q="Vad är förankringspelarna?",a="Förankringspelarna är viktiga försvarsstrukturer eller regionala strukturer. Underrättelser från angreppet mot det västra vakttornet tyder på att en fientlig kult specifikt försöker störa dem eller lägga dem under sig.",al={"vad är förankringspelarna","kulten och förankringspelarna","varför förankringspelarna"}},{q="Vem var skyprästen vid det västra vakttornet?",a="En skypräst var inblandad i händelsen vid det västra vakttornet. Uppgifterna från mötet ledde till att ledarna drog slutsatsen att kulten hade en större plan för förankringspelarna.",al={"vem var skyprästen","skyprästen vid det västra vakttornet","skyprästens roll"}},{q="Vilken kult siktar in sig på vakttornen?",a="En aggressiv kult har samordnat samtidiga angrepp mot regionens vakttorn. Dess exakta natur och djupare motiv utreds fortfarande medan High Elder Shadowsong försöker avslöja dess planer.",al={"vilken kult är det","vem angrep tornen"}}},fp="24,213,26.339.0,20.266.0,29.188.0,18.159.0,34.160.0,27.166.0,48.177.0,39.179.0"}
P.entries["quest:92893"] = {n="No Mercy for the Weak",s="I Valley of Bones håller Orgrul och Magram-klanen Gelkis-vandrare fångna efter att de vågat sig in på deras territorium. Benmaskarna vägrar äta levande byte, så Orgrul ber dig ta fångarnas liv i stället för att ge dem hopp om att fly.",h="I Valley of Bones håller Orgrul och Magram-klanen Gelkis-vandrare fångna efter att de vågat sig in på deras...",kw={"benmaskar","kentaur","desolace","gelkis","magram","orgrul","valley of bones"},sec={{t="Fångar i stoftet",b="I Valley of Bones dammiga vidder håller Magram flera Gelkis-vandrare fångna. Orgrul skonade först inkräktarna för att mata de lokala benmaskarna, men de grävande bestarna vägrar äta levande byte. I stället för att ge fångarna hopp om att bli fria vill Orgrul att du avslutar deras liv där de sitter."},{t="Kött åt maskarna",b="Orgrul lämnar de dödade Gelkis i dalen i stället för att ta deras skallar som troféer. Benmaskarna äter upp kropparna under natten och lämnar rena skelett efter sig, som Magram kan resa upp till sin växande armé."}},faq={{q="Vilka är Gelkis-fångarna?",a="De är kringvandrande Gelkis-kentaurer som kommit in på Magrams territorium och tillfångatagits levande.",al={"vilka är fångarna","gelkis-fångar","vilka är fångarna i valley of bones"}},{q="Varför höll Magram Gelkis-fångarna vid liv till en början?",a="Magram skonade dem först för att använda dem som levande föda åt de grävande benmaskarna, men varelserna visade inget intresse för levande byte.",al={"varför mata benmaskar","varför hölls fångarna vid liv"}},{q="Var hålls Gelkis-fångarna?",a="Fångarna hålls utspridda över Valley of Bones, djupt inne i Magrams land.",al={"var finns fångarna","var fångarna finns i valley of bones"}},{q="Vem beordrar att fångarna ska avrättas?",a="Orgrul från Magram-kentaurerna befaller dig att döda Gelkis-fångarna.",al={"vem skickar dig att döda fångarna","vem ger uppdraget"}}},fp="21,252,21.328.0,19.217.1,28.89.0,59.140.0,35.75.0,42.75.0"}
P.entries["quest:92894"] = {n="Bone Raising",s="Orgrul från Magramklanen skickar dig till Valley of Bones för att pröva en förstärkt stav mot Gelkis primitiva nekromanti. Genom att väcka halvt begravda döda till en lydig stridsstyrka hjälper du klanen att stå starkare mot sina bittra rivaler.",h="Orgrul från Magramklanen skickar dig till Valley of Bones för att pröva en förstärkt stav mot Gelkis...",kw={"benresning","kentaur","desolace","gelkis","magram","nekromantisk stav","orgrul","valley of bones"},ang={["class:Warlock"]="Krigslåsets klass känner igen sig i Orgruls kyliga nyfikenhet på mörka riter och på att binda odöda trälar till tjänst för en större makt."},sec={{t="En armé ur jorden",b="Orgrul från Magramklanen vill pröva hur väl du behärskar mörka konster i Valley of Bones. Rivalerna Gelkis försökte utöva sin egen primitiva nekromanti där och lämnade efter sig ofullständiga lik som kämpar för att ta sig upp ur stoftet. Med en genomdränkt stav i handen måste du fullborda väckandet av de begravda döda, stärka Magramklanens stridsstyrka och kuva alla som gör motstånd."},{t="Lärdomar i stoftet",b="Många av de spröda skeletten faller sönder eller blir fientliga i stället för att böja sig för din vilja. Ändå räknar Orgrul försöket som en triumf och tar tillbaka staven, nöjd med att Gelkis nekromanti förblir spröd och svag jämfört med hans egen."}},faq={{q="Vem ger dig det här uppdraget?",a="Orgrul från Magramklanen ber dig pröva dina nekromantiska förmågor och stärka klanens led med väckta odöda.",al={"vem ger benresningsuppdraget","uppdragsgivare för benresning","vem är orgrul"}},{q="Vart måste du ta dig?",a="Valley of Bones ligger i Desolace, där misslyckade odöda klöser sig upp ur jorden bland forntida skelettrester.",al={"var ligger valley of bones","vart ska jag för benresning","valley of bones plats"}},{q="Varför ligger halvt begravda skelett i dalen?",a="De rivaliserande Gelkiskentaurerna försökte väcka de döda där, men deras primitiva magi lämnade liken fångna och kämpande i jorden.",al={"gelkis nekromanti","vem väckte skeletten","varför ligger skelett i jorden"}},{q="Vad är syftet med Enhanced Necromancy Staff?",a="Orgrul har genomsyrat din stav med större nekromantisk kraft, så att du kan väcka de fångna liken helt och skapa en odöd stridsstyrka.",al={"vad gör staven","enhanced necromancy staff","hur väcker man odöda"}},{q="Varför bygger Orgrul en odöd armé?",a="Orgrul vill utöka Magramklanens styrkor med en odöd här och samtidigt bevisa att deras nekromantiska skicklighet vida överträffar Gelkis.",al={"varför väcka odöda i desolace","magrams nekromantiska plan","varför bygga en odöd armé"}}},fp="12,236,21.362.0,19.242.1,30.116.0,18.108.0,50.134.0,53.129.0,38.139.0"}
P.entries["quest:929"] = {n="Crown of the Earth",s="Crown of the Earth är ett heligt uppdrag från Corithras Moonrage i Dolanaar, där du hämtar välsignat vatten från månkällan nära Starbreeze Village. Som tack för att de fyller på vattnet i Darnassus får unga Night Elf lära sig den tragiska historia som fick deras folk att odla Teldrassils väldiga grenar.",h="Crown of the Earth är ett heligt uppdrag från Corithras Moonrage i Dolanaar, där du hämtar välsignat vatten...",kw={"corithras moonrage","crown of the earth","dolanaar","jade phial","månkälla","nordrassil","starbreeze village","teldrassil"},ang={["class:Druid"]="Månkällorna är viktiga kanaler för naturens och stjärnornas magi. De är levande reservoarer som knyter din ordens plikter i Darnassus till Teldrassils rötter.",["race:NightElf"]="Varje Night Elf måste möta förlusten av odödligheten och Malfurion Stormrages försvinnande. Därför är denna heliga insamling en viktig lektion i ditt folks sorg efter de senaste händelserna."},sec={{t="Att hålla månkällorna vid liv",b="Den stora månkällan mitt i Darnassus kräver ständig kontakt med de mindre källor som finns utspridda i världsträdets krona. Druider tillverkar särskilda jadeflaskor för att samla och bära det lysande vattnet utan att förorena det. Genom att skicka noviser till fots till Starbreeze Village ser de äldre till att stadens fontäner hålls fyllda av Elunes nåd och att de unga förstår arbetet som krävs för att ge näring åt Teldrassil."},{t="Ekon från Tredje kriget",b="När novisen har slutfört arbetet får hen höra berättelser från förr. Corithras Moonrage berättar om förtvivlan som grep kaldorei strax efter slaget vid Mount Hyjal. Offret av världsträdet Nordrassil berövade Night Elf deras dyrbara odödlighet, och mitt i förödelsen släpptes Illidan Stormrage fri medan Shan'do Malfurion Stormrage försvann. Denna tid av sorg och isolering lade grunden till den omstridda planteringen av Teldrassil."}},faq={{q="Varför hämtar man vatten från månkällan?",a="Druiderna i Darnassus fyller regelbundet på stadens främsta månkällas vatten med vatten från skogsskrinen i närheten. På så sätt bevarar de det heliga nätverket över hela Teldrassil.",al={"varför hämta vatten från månkällan","vad används månkällans vatten till","vad används jadeflaskan till"}},{q="Var ligger månkällan för uppdraget?",a="Månkällan ligger strax utanför Starbreeze Village, öster om Dolanaar längs skogsstigen.",al={"var ligger månkällan","var ligger månkällan vid starbreeze","brunnen i starbreeze village"}},{q="Vem är Corithras Moonrage?",a="Corithras Moonrage är en Night Elf i Dolanaar som vägleder unga äventyrare genom ritualerna och berättelserna kring Teldrassils välmående.",al={"vem ger uppdraget","corithras moonrages historia"}},{q="Vilken historia berättar Corithras när man återvänder?",a="Han berättar om de katastrofala följderna av slaget vid Mount Hyjal: Nordrassil brändes, kaldoreis odödlighet försvann, Illidan befriades och Shan'do Malfurion Stormrage försvann.",al={"vad berättar corithras","historien om crown of the earth"}},{q="Varför känner sig Night Elf vilsna efter Mount Hyjal?",a="Nordrassil hade skänkt Night Elf evigt liv och beskydd. När trädets kraft offrades för att förgöra Archimonde krossades deras tidlösa tillvaro. De blev dödliga, vilse och djupt sårbara.",al={"varför förlorade alverna sin odödlighet","vad hände efter hyjal"}},{q="Vad betyder Shan'do?",a="Shan'do är en hederstitel på darnassiska som betyder ”ärad lärare”. Här används den om Malfurion Stormrage, druidernas högste ledare.",al={"vad betyder shan'do","betydelsen av shan'do"}}},fx={["5a4296ad"]={q="Varför vill Corithras Moonrage att det här ska göras?",a="Corithras utför viktiga uppdrag för Cenarion Circle och undervisar unga nattalver om deras folks utsatta tillstånd. Teldrassils heliga vatten kräver ständig omsorg och balans, och druiderna i Darnassus behöver färskt vatten från månbrunnar ute bland grenarna. Genom att byta denna tjänst mot historia och vägledning ser Corithras till att månbrunnen i Darnassus fylls på och att du förstår de tunga bördor ditt folk bär efter det tredje kriget.",al={"corithras moonrages motiv","varför behöver corithras vatten","corithras uppdrag vid månbrunnarna"}},["0abe9d82"]={q="Vad används Filled Jade Phial till?",a="Filled Jade Phial innehåller heligt vatten från månbrunnen nära Starbreeze Village. Kärlet är särskilt utformat för att bevara månbrunnsvattnets latenta magiska kraft, och förser druiderna i Darnassus med nytt vatten. De hämtar kraft ur Teldrassils samlade källor för sina ritualer och sin läkekonst.",al={"filled jade phials syfte","vad används jade phial till","filled jade phial"}}},fp="18,215,24.445.0,23.359.0,46.138.0,44.90.0,26.151.0,46.194.0,47.202.0,18.122.0"}
P.entries["quest:92909"] = {n="Harvesting the Harvesters",s="Harvesting the Harvesters är ett lokalt uppdrag i Westfall där du hjälper Ozwin Ironsprocket, en besökande gnomisk uppfinnare som sitter fast i ett stall på Saldean's Farm. Efter att ha underskattat hur våldsamma områdets vildsinta skördegolemer är behöver Ozwin bärgade mekaniska delar för att bygga en flyktanordning.",h="Harvesting the Harvesters är ett lokalt uppdrag i Westfall där du hjälper Ozwin Ironsprocket, en besökande...",kw={"isofjädrar från golemer","skördegolemer","gyrostabilisatorer från skördare","harvesting the harvesters","ironforge","ozwin ironsprocket","saldean's farm","westfall"},ang={["faction:Alliance"]="Alliansresenärer som besöker Saldean's Farm kan hjälpa en besökande gnomisk lärd som blev strandsatt efter ett felberäknat försök att laga Westfalls mekaniska plåga.",["profession:Engineering"]="Genom att bärga komplicerade delar som isofjädrar och gyrostabilisatorer från oregerliga skördegolemer får man de viktiga rådelar som behövs för att uppfinna en fungerande flyktanordning.",["race:Gnome"]="Ozwin Ironsprocket förkroppsligar gnomernas typiska ambition att meka med komplicerade maskiner, även om hans underskattning av maskinernas aggressivitet ledde till att han blev instängd i ett stall."},sec={{t="Ett felberäknat försök",b="Westfalls bördiga slätter har kastats in i kaos och översvämmats av både laglösa och mekaniska skördare på bärsärkagång. Ryktet om dessa vildsinta automater nådde Ironforges tekniska verkstäder och inspirerade den gnomiske ingenjören Ozwin Ironsprocket att resa söderut. Ozwin litade på sin tekniska skicklighet och trodde att han kunde felsöka och kalibrera om de oregerliga jordbruksmaskinerna för att återställa lugnet på regionens hårt prövade åkrar."},{t="Fast i stallet",b="När Ozwin kom fram till fälten kring Saldean's Farm upptäckte han snabbt att skördegolemerna var mycket mer oberäkneliga och våldsamma än ritningarna antydde. Maskinernas rakbladsvassa skär och vilda svingar fick gnomen att fly för sitt liv in i ett närbeläget stall. Ozwin sitter fast och kan inte ta sig ut på fälten, så han förlitar sig på djärva äventyrare som kan bärga användbara isofjädrar och gyrostabilisatorer från de mekaniska bestarna. Då kan han sätta ihop en anordning för att fly säkert."}},faq={{q="Vem är Ozwin Ironsprocket?",a="Ozwin Ironsprocket är en gnomisk uppfinnare som reste från Ironforge till Westfall med det djärva målet att kalibrera om de våldsamma skördegolemerna. Deras extrema fientlighet tvingade honom dock att söka skydd i ett stall på Saldean's Farm.",al={"vem är ozwin ironsprocket","ozwin","uppdragsgivare"}},{q="Varför är skördegolemerna så aggressiva?",a="De mekaniska skördegolemerna som strövar omkring på Westfalls övergivna fält har blivit vilt aggressiva och angriper förbipasserande. Ozwin hoppades kunna åtgärda deras funktionsfel med en rutinmässig omkalibrering, men deras våldsamhet visade sig vara långt värre än hans beräkningar förutspådde.",al={"varför anfaller skördarna","varför är golemer aggressiva","vad är fel på skördarna"}},{q="Var kan Ozwin Ironsprocket hittas?",a="Ozwin Ironsprocket gömmer sig i ett stall på Saldean's Farm i Westfall och tar skydd från de farliga skördegolemerna som stryker omkring på fälten i närheten.",al={"var finns ozwin ironsprocket","var lämnar man in harvesting the harvesters","ozwins plats"}},{q="Vad tänker Ozwin bygga med de insamlade delarna?",a="Ozwin behöver isofjädrar från golemer och gyrostabilisatorer från skördare för att bygga en mekanisk nödanordning som ger honom tillräckligt skydd för att fly från stallet utan att skadas.",al={"vad behöver ozwin delarna till","varför samla isofjädrar","delar till flyktanordning"}},{q="Varför reste Ozwin från Ironforge till Westfall?",a="Ozwin fick höra att oregerliga maskiner terroriserade landsbygden i Westfall och reste hela vägen från dvärgarnas huvudstad Ironforge. Han trodde att hans uppfinningsrikedom kunde hjälpa honom att kalibrera om de oregerliga automaterna.",al={"varför kom ozwin till westfall","varför lämna ironforge"}},{q="Var kommer de nödvändiga golem-delarna ifrån?",a="Isofjädrarna och gyrostabilisatorerna bärgas direkt från de fientliga skördegolemerna och skördarna som stryker omkring på jordbruksfälten i Westfall kring Saldean's Farm.",al={"varifrån får man delarna","hur får man isofjädrar och gyrostabilisatorer"}}},fp="25,156,24.307.0,20.345.0,26.178.0,41.190.0,38.124.0,57.134.0,48.158.0,44.135.0"}
P.entries["quest:92910"] = {n="Harvesting the Harvesters",s="En bärgad del från en skördemaskin kan intressera någon som studerar skördegolemar. Du ombeds ta den till Ozwin Ironsprocket på Saldean's Farm.",h="En bärgad del från en skördemaskin kan intressera någon som studerar skördegolemar.",kw={"skördegolem","skördemaskin","harvesting the harvesters","ozwin ironsprocket","precessive autocognition assembly","saldean's farm","bärgad del"},sec={{t="En bärgad del",b="Någon på Saldean's Farm kanske vill undersöka delen du bärgade från en skördemaskin. Den verkar till största delen vara intakt, och Ozwin Ironsprocket väntar på att få se den."}},faq={{q="Vad ska jag ta med till Ozwin?",a="Du tar med Precessive Autocognition Assembly till Ozwin Ironsprocket, en del som bärgats från en skördemaskin.",al={"skördemaskinsdel","vilket föremål","autocognition assembly"}},{q="Vart ska jag ta den bärgade delen?",a="Ta Precessive Autocognition Assembly till Ozwin Ironsprocket på Saldean's Farm.",al={"var finns ozwin","saldean's farm","vart ska den lämnas"}},{q="Varför skulle någon vilja ha delen?",a="Den bärgade delen verkar till största delen vara intakt, och någon som är intresserad av skördegolemar kanske vill se den.",al={"varför skördemaskiner","vem vill ha detta","intresse för skördemaskiner"}}},fp="25,141,15.156.0,24.101.0,35.84.0,32.101.0"}
P.entries["quest:92911"] = {n="Harvesting the Harvesters",s="På Saldean's Farm behöver Ozwin Ironsprocket delar till en apparat som ska ta kontroll över skördemaskinernas system en kort stund. Han fortsätter att sätta ihop apparaten medan du samlar ihop det han behöver.",h="På Saldean's Farm behöver Ozwin Ironsprocket delar till en apparat som ska ta kontroll över skördemaskinernas...",kw={"copper modulators","crude scope","apparat","golem isosprings","skördemaskiner","harvesting the harvesters","ozwin ironsprocket"},sec={{t="Delar till Ozwin",b="Ozwin Ironsprocket på Saldean's Farm undersöker vad som får skördemaskinerna att fungera. Han tror att han kan ta kontroll över deras system en kort stund. Du samlar ihop delar till hans apparat medan han fortsätter att arbeta med bygget."},{t="Den färdiga apparaten",b="Ozwin gör färdigt apparaten och ber dig att prova den. Han stannar på gården, som börjar kännas som hemma för honom."}},faq={{q="Vem ber om delar?",a="Ozwin Ironsprocket på Saldean's Farm behöver delar till en apparat.",al={"vem behöver delar","ozwin delar"}},{q="Vad bygger Ozwin?",a="Ozwin bygger en apparat som ska ta kontroll över skördemaskinernas system en kort stund.",al={"vilken apparat","skördemaskinsapparat"}},{q="Vilka delar behöver Ozwin?",a="Ozwin behöver Golem Isosprings, Copper Modulators och en Crude Scope.",al={"dellista","vad behöver ozwin"}},{q="Var arbetar Ozwin?",a="Ozwin Ironsprocket arbetar på Saldean's Farm.",al={"var är ozwin","ozwins plats"}}},fp="25,182,15.218.0,19.117.1,24.62.0,23.80.0,27.67.0,23.48.0"}
P.entries["quest:92914"] = {n="Strange Pylons",s="I Shen'dralas är en urladdad kristallpylons syfte okänt. Du ombeds leta efter fler i närheten.",h="I Shen'dralas är en urladdad kristallpylons syfte okänt.",kw={"kristall","alvruiner","ädelsten","manaelementärer","pylon","shen'dralas","märkliga pyloner"},sec={{t="Bland ruinerna",b="En märklig kristall vilar på en uråldrig piedestal bland Shen'dralas alvruiner. För bara några ögonblick sedan vaktades den av utmärglade manaelementärer. Ädelstenen är sprucken och dess magi nästan uttömd, så dess syfte förblir ett mysterium. Du söker i området efter fler liknande pyloner."}},faq={{q="Vad är den märkliga pylonen?",a="Det är en sprucken ädelsten på en uråldrig piedestal i Shen'dralas. Den uttömda magin gör dess syfte okänt.",al={"märklig pylon","kristallpylon","vad är den här kristallen"}},{q="Varför surrar kristallen?",a="Ett svagt kraftsurr kommer från den spruckna ädelstenen, trots att dess magi nästan är uttömd.",al={"kristallsurr","varför surrar den","svagt surr"}},{q="Vad vaktade kristallen?",a="Utmärglade manaelementärer vaktade kristallen för bara några ögonblick sedan.",al={"manaelementärer","vad vaktade den","elementärer vid pylonen"}},{q="Var finns de andra pylonerna?",a="Du ombeds söka i Shen'dralas efter fler pyloner som den du hittade.",al={"andra pyloner","hitta fler pyloner","pylonernas platser"}}},fp="14,109,15.269.0,26.116.0,27.92.0,30.63.0,27.76.0"}
P.entries["quest:92947"] = {n="Making Our Move",s="Making Our Move är ett samordnat taktiskt anfall mot de fientliga Al'Aketh som befäst sig i Shrine of Akir. Med en avledningsmanöver framifrån och en flankmanöver försöker anfallsstyrkan bryta igenom försvaret och nå översteprästinnan.",h="Making Our Move är ett samordnat taktiskt anfall mot de fientliga Al'Aketh som befäst sig i Shrine of Akir.",kw={"al'aketh","al'aketh blademaster","al'aketh guardian","al'aketh spiritcaller","översteprästinna","hyusaa quickbreeze","making our move","shrine of akir"},ang={["class:Priest"]="Anfallet riktas mot Al'Akeths ledning, särskilt den fientliga översteprästinnan och hennes Spiritcallers som styr från Shrine of Akir."},sec={{t="En samordnad kniptång",b="Anfallet mot Shrine of Akir bygger på exakt timing och en uppdelning av styrkorna. En liten grupp elitkämpar stormar huvudingången för att slå larm och locka fram försvararna, medan befälhavaren leder huvudstyrkan från flanken. Den samordnade framryckningen ska splittra försvararnas uppmärksamhet och öppna en väg rakt mot helgedomens ledning."},{t="Genom Al'Akeths försvarslinjer",b="Shrine of Akir försvaras av de mäktiga Al'Aketh, vars led består av tungt rustade Guardians, mystiska Spiritcallers och stridsvana Blademasters. För att bryta igenom försvarslinjen måste ni ta er genom dessa främsta led och bana väg mot den inre helgedomen, där översteprästinnan leder sina anhängare. När det yttre motståndet väl är krossat samlas styrkorna på nytt med ställföreträdaren Hyusaa Quickbreeze vid helgedomens trappa."}},faq={{q="Vad är målet med anfallet i Making Our Move?",a="Making Our Move är ett samordnat taktiskt anfall mot de fientliga styrkor som håller Shrine of Akir. En avledningsmanöver framifrån drar till sig fiendens uppmärksamhet medan huvudstyrkan går runt deras position för att bryta sig in i helgedomen och besegra översteprästinnan.",al={"making our move","uppdraget making our move","uppdraget shrine of akir"}},{q="Vem är Hyusaa Quickbreeze?",a="Hyusaa Quickbreeze är anfallsstyrkans ställföreträdare. När du har decimerat leden bland Al'Akeths försvarare vid helgedomen får du order om att möta Quickbreeze vid helgedomens trappa.",al={"vem är hyusaa","hyusaa quickbreeze","var finns hyusaa"}},{q="Vem är översteprästinnan som anfallet riktas mot?",a="Översteprästinnan är den ledande gestalten i Shrine of Akir. Hela den omfattande flankmanövern ska snabbt tränga igenom fiendens linjer så att anfallsstyrkan kan nå henne och besegra henne.",al={"vem är översteprästinnan vid akir","översteprästinnan alaketh","målet översteprästinnan"}},{q="Vad är Shrine of Akir?",a="Shrine of Akir är en befäst religiös plats som hålls av Al'Aketh. Den försvaras av beväpnade väktare, spiritcallers och blademasters som skyddar den centrala helgedomen där deras ledning håller till.",al={"vad är shrine of akir","lore om shrine of akir","var finns shrine of akir"}},{q="Vilka Al'Aketh-styrkor håller helgedomen?",a="Al'Aketh är de fientliga försvarare som håller Shrine of Akir. Deras styrkor består av ståndaktiga Guardians i främsta ledet, trollkunniga Spiritcallers och rörliga Blademasters som vaktar vägen till deras översteprästinna.",al={"vilka är alaketh","al'akeths försvarare","alaketh-fiender"}},{q="Varför används en avledningsmanöver framifrån i anfallet?",a="Några få erfarna kämpar skickas rakt genom helgedomens huvudingång för att locka fram försvararna och skapa kaos. Avledningen gör att huvudstyrkan kan gå runt anläggningen och slå sig in mot den inre helgedomen.",al={"varför avledningsmanöver","anfallsplan för helgedomen","anfallsstrategi för making our move"}}},fp="15,179,20.338.0,27.359.0,56.171.0,26.156.0,49.132.0,27.174.0,47.195.0,49.203.0"}
P.entries["quest:92960"] = {n="Siphoned Ephemeral Essence",s="Elaena Moonwhisper vill stoppa en grupp demoner som dröjer sig kvar i ett läger i öster. Dessa helvetiska bestar har härjat bland hennes folk och stulit deras livskraft, och prover på den utsugna essensen kan avslöja hur deras magi kan motverkas.",h="Elaena Moonwhisper vill stoppa en grupp demoner som dröjer sig kvar i ett läger i öster.",kw={"demonläger","elaena moonwhisper","flyktiga essenser","helvetiska bestar","utsugen flyktig essens"},sec={{t="Stulen kraft",b="I öster hyser demoniska bestar kraft som stulits direkt från fallna fränder. Elaena Moonwhisper behöver att du tar dig in i deras läger, gör slut på monstren och säkrar prover av resterna innan den dränerade kraften kan vändas mot hennes allierade. Genom att undersöka den stulna essensen hoppas hon ta reda på hur vidundren suger åt sig sådan livskraft."}},faq={{q="Vem ber om essenserna?",a="Elaena Moonwhisper ber om dem för att studera hur demonerna dränerar kraft från hennes folk.",al={"vem vill ha de flyktiga essenserna","vem lämnar ut utsugen flyktig essens"}},{q="Var finns demonerna?",a="Ett demonläger ligger i öster, där bestarna dröjer sig kvar efter att ha anfallit Elaena Moonwhispers folk.",al={"var finns de helvetiska bestarna","var ligger demonlägret"}},{q="Varför behöver Elaena essensproverna?",a="Elaena Moonwhisper hoppas att en undersökning av den stulna kraften ska avslöja hur bestarna suger åt sig styrka från hennes allierade.",al={"varför samla flyktig essens","vad ska elaena göra med flyktig essens"}},{q="Vad har dessa demoner gjort?",a="De är demoniska bestar som har härjat bland Elaena Moonwhispers folk och stulit deras styrka för att vända den mot deras allierade.",al={"vad är det för bestar","vad gör demonerna"}}},fp="26,245,12.342.0,31.82.0,29.99.0,41.111.0,28.116.0"}
P.entries["quest:93"] = {n="Dusky Crab Cakes",s="Chef Grual på Scarlet Raven Tavern i Darkshire har en hemlighet bakom sina berömda Dusky Crab Cakes: de innehåller inte krabba alls. För att hjälpa den utsvultne och nervöse Jitters skickas äventyrare ut för att samla spindelben från de dödliga spindeldjur som strövar omkring i norra Duskwood, så att byns älskade tilltugg kan tillagas.",h="Chef Grual på Scarlet Raven Tavern i Darkshire har en hemlighet bakom sina berömda Dusky Crab Cakes: de...",kw={"chef grual","darkshire","duskwood","dusky crab cakes","jitters","scarlet raven tavern","spindelben","venom web spider"},ang={["faction:Alliance"]="Rätten visar hur osäker Alliansens södra gränstrakt är, där städer som Darkshire tvingas livnära sig på jättelika skadedjur på grund av eftersatt infrastruktur och avbrutna försörjningslinjer.",["profession:Cooking"]="Chef Grual visar prov på den uthållighet som krävs av kockar i gränstrakterna och bevisar att även skräckinjagande rovdjur i vildmarken, som giftiga jättespindlar, kan förvandlas till en bys stolta lokala delikatess."},sec={{t="En tvivelaktig delikatess",b="Duskwood har länge plågats av isolering, mörk magi och avbrutna försörjningsvägar, vilket tvingat Darkshires invånare att anpassa sin matlagning. Chef Grual, kocken på Scarlet Raven Tavern, löste sin köttbrist genom att hitta på Dusky Crab Cake. Trots att namnet antyder skaldjur från avlägsna kuster medger Grual utan omsvep att rättens tydligt syrliga smak helt och hållet kommer från de kladdiga benen från traktens jättespindlar."},{t="Jakt på giftspindlar",b="För att uppfylla beställningen skickar Grual jägare norrut mot bergssluttningarna och flodstränderna där Venom Web Spiders spinner sina nät. I en dyster skog full av odöda och vilda bestar är det farligt att samla färskt spindelkött, men det är fortfarande en av de få lättillgängliga proteinkällorna i den härjade skogen. Grual steker de kryddade spindelbenen i en het panna tills de blir knapriga."},{t="Tröst åt en förbannad själ",b="Matärendet har sin grund i omtanken om Jitters, en upprörd luffare som söker skydd i den övergivna byn Raven Hill i västra Duskwood. Jitters är uppfylld av skuld och skälver av skräck efter att oavsiktligt ha släppt fasor lösa över trakten, och han kan knappt tänka på något annat än sin hungriga mage. En varm omgång av Gruals smakrika spindelkakor blir en sällsynt, om än bisarr, tröst i hans eländiga exil."}},faq={{q="Är Dusky Crab Cakes verkligen gjorda av krabba?",a="Nej. Chef Grual erkänner öppet för äventyrare att Dusky Crab Cakes helt och hållet görs av kladdiga spindelben. Darkshire har ingen tillgång till havet eller färsk krabba, så Grual använder traktens jättespindlar för att efterlikna konsistensen och få till ett skarpt, syrligt tilltugg.",al={"är det riktig krabba","krabbkakornas hemlighet","vad innehåller krabbkakor"}},{q="Var får Chef Grual tag på spindelbenen?",a="Grual förlitar sig på äventyrare som samlar kladdiga ben från Venom Web Spiders. Dessa aggressiva spindeldjur håller främst till i norra Duskwood, mellan skogens bergssluttningar och floden.",al={"var hittar man spindelben","spindelplatser i duskwood","var finns venom web spiders"}},{q="Vem bakas de här krabbkakorna åt?",a="Grual serverar dem till gäster i Darkshire, men just den här omgången har beställts åt Jitters. Jitters är en vettskrämd eremit som svälter i spökstaden Raven Hill i västra Duskwood och desperat behöver något som stillar hans kurrande mage.",al={"vem vill ha krabbkakorna","vem äter krabbkakorna","varför laga krabbkakor"}},{q="Kommer Chef Grual att lära mig laga Dusky Crab Cakes?",a="Chef Grual håller sitt exakta recept på Dusky Crab Cakes strikt hemligt och vägrar avslöja sin egen kryddblandning. Han belönar däremot hjälpsamma äventyrare med ett annat recept ur sin kulinariska repertoar.",al={"kan jag lära mig receptet på krabbkakor","recept på krabbkakor matlagning"}},{q="Varför förlitar sig Darkshire på spindlar som föda?",a="Duskwoods vägar hemsöks av odöda, Nightbane-worgen och fientliga varelser, vilket stör handelskaravaner och jordbruk svårt. Eftersom färsk boskap och importerade varor är sällsynta använder Darkshires invånare sin uppfinningsrikedom och fångar den vilda fauna de kan komma åt.",al={"varför äta spindlar i darkshire","matbrist i duskwood"}},{q="Vet Jitters att kakorna är gjorda av spindlar?",a="Jitters är särskilt sugen på Gruals berömda krabbkakor och bryr sig föga om ingredienserna. Förlamad av skräck och svält ute i skogen längtar han efter vilken välbekant måltid som helst från Darkshire, oavsett dess rysliga ursprung.",al={"vet jitters om spindlarna","jitters reaktion på spindelkött"}}},fx={e54432be={q="Vad används Gooey Spider Leg till?",a="Trots det trevliga namnet på tavernans meny är Gooey Spider Legs själva köttet i Chef Gruals berömda Dusky Crab Cakes. Grual kryddar de sprattlande benen med sin hemliga kryddblandning och steker dem i en panna. Han förlitar sig på deras naturliga safter för att ge de smakrika kakorna deras särpräglade, syrliga smak.",al={"vad gooey spider leg används till","varför gooey spider legs","spindelben i krabbkakor"}}},fp="16,156,23.300.0,22.309.0,25.320.1,43.216.0,42.166.0,40.196.0,54.184.0,44.236.0,48.213.0"}
P.entries["quest:930"] = {n="The Glowing Fruit",s="Glowing Fruit är ett uppdrag i Teldrassil som börjar när du upptäcker en märklig fruktbärande växt som växer vilt i skogen. Unga äventyrare misstänker att något onaturligt ligger bakom och tar det självlysande exemplaret till örtkännaren Denalan vid Lake Al'Ameth för undersökning.",h="Glowing Fruit är ett uppdrag i Teldrassil som börjar när du upptäcker en märklig fruktbärande växt som växer...",kw={"boglings","denalan","glowing fruit","örtmedicin","lake al'ameth","märklig fruktväxt","teldrassil","timberlings"},ang={["class:Druid"]="För druider som värnar om naturens balans är främmande, instabil flora som växer onaturligt bland Teldrassils heliga grenar en omedelbar varningssignal.",["profession:Herbalism"]="Örtkunniga kommer att uppskatta Denalans botaniska insikter om hur främmande frön kan färdas mellan kontinenter och mutera när de utsätts för förtrollad jord.",["race:NightElf"]="Kaldoreiungdomar lär sig av Denalan att även den unga jorden i deras nya hem, Teldrassil, är mottaglig för oförutsägbara främmande farsoter."},sec={{t="En onaturlig skörd",b="När upptäcktsresande färdas bland Teldrassils dimhöljda grenar stöter de ibland på märkliga, lysande växter med stora, runda frukter. Med tanke på världsträdets känsliga balans och de märkliga beteenden som öns djurliv nyligen uppvisat måste ovanliga växter undersökas noggrant. Övertygade om att den märkliga växten inte bör ignoreras plockar äventyrarna den strålande skörden för att ta den till någon som känner till vildmarkens växter."},{t="Denalans undersökning",b="Vid Lake Al'Ameth tar den kunnige trädgårdsmästaren och örtkännaren Denalan emot den lysande frukten med både fascination och oro. Han noterar att exemplaret verkar exotiskt och spekulerar i att fröna kan ha kommit från avlägsna länder på andra sidan havet, kanske till och med Eastern Kingdoms. Än mer oroande för Denalan är hur det främmande fröet reagerade med Teldrassils jord. När han planterar fröna i den jord han har förberett stiger fientliga boglings upp ur marken."}},faq={{q="Var hittar man den märkliga fruktväxten?",a="Den märkliga fruktväxten växer vilt i Teldrassils ödemarker, undangömd bland snåren långt från de större bosättningarna. När du undersöker växten får du Glowing Fruit och uppdraget börjar.",al={"var hittar jag växten","den märkliga fruktväxtens plats","hur börjar man glowing fruit"}},{q="Vem är Denalan?",a="Denalan är en örtkunnig Night Elf och botaniker som håller till längs Lake Al'Ameths stränder. Han ägnar dagarna åt att sköta jorden, studera traktens växter och hålla uppsikt över de märkliga miljöförändringar som påverkar Teldrassil.",al={"var finns denalan","denalan npc","vem tar emot glowing fruit"}},{q="Varför lyser frukten?",a="Orsaken till att frukten lyser är inte fastställd. Denalan betraktar den som ett ovanligt exemplar och planerar att undersöka den.",al={"varför lyser frukten","vad är fel på frukten"}},{q="Vad händer när du lämnar frukten till Denalan?",a="Ta den lysande frukten till Denalan vid Lake Al'Ameth för undersökning. Hans fynd och resultatet av överlämningen avslöjas när du återvänder.",al={"vad dyker upp efter uppdraget","bogling-bakhåll"}},{q="Var tror Denalan att växten kommer ifrån?",a="Denalan misstänker att växtens frön kan ha sitt ursprung långt borta på andra sidan Great Sea och ha förts till Kalimdor från Azeroths avlägsna östra kontinent.",al={"var kom fröna ifrån","fruktens ursprung"}},{q="Har uppdraget koppling till andra ekologiska problem på Teldrassil?",a="Ja. Det ingår i Denalans bredare forskning om varför Teldrassils grenar och traktens skogsvarelser, som timberlings, blir alltmer upprörda och onaturliga.",al={"teldrassils fördärv","problem vid lake al'ameth"}}},fx={a8a1e1a2={q="Varför ta den glödande frukten till Denalan?",a="Strange Fruited Plant är en tanklös växt, men dess kusliga sken och bisarra utseende sticker genast ut bland Teldrassils naturliga växter. Du inser att en sådan onaturlig avvikelse måste undersökas och tar därför initiativet att lämna ett exemplar till Denalan vid Lake Al'Ameth. Du vet att botanikern aktivt studerar öns märkliga ekologiska störningar.",al={"varför frukten till denalan","strange fruited plants motiv","varför plocka glödande frukt"}}},fp="17,185,20.306.0,23.373.1,41.158.0,15.190.0,24.85.0,48.147.1,46.137.0,67.161.0"}
P.entries["quest:93016"] = {n="A Brief History Lesson",s="Du skickas till Shen'dralas för att höra om kristallerna du lagade. Deras sken har väckt oro, men du får snart en förklaring.",h="Du skickas till Shen'dralas för att höra om kristallerna du lagade.",kw={"en kort historielektion","kristallernas sken","kristaller","dramatisk himmel","mordent evenshade","shen'dralar","shen'dralas","tempel"},sec={{t="Frågor i Shen'dralas",b="Kristallerna du lagade har väckt frågor, så du skickas till Mordent Evenshade i Shen'dralas för att få svar. Himlen har fått ett dramatiskt utseende, vilket ökar oron kring de tidigare förfrågningarna."},{t="Ett planerat besök",b="Mordent säger att han teg för att han var så upprymd över att se kristallerna lysa igen. Han hoppas kunna besöka Shen'dralas tempel, men saknar mod att tala med Shen'dralar där."}},faq={{q="Vem ska förklara kristallerna?",a="Mordent Evenshade i Shen'dralas får i uppdrag att förklara kristallerna du lagade.",al={"vem förklarar kristallerna","information om mordent","förklaring om kristallerna"}},{q="Varför verkade de tidigare förfrågningarna misstänkta?",a="Förfrågningarna saknade sammanhang, och himlen hade fått ett dramatiskt utseende.",al={"varför misstänkt","vad var märkligt","varför saknades sammanhang"}},{q="Varför utelämnade Mordent förklaringen?",a="Mordent säger att han ivrigt ville se kristallernas sken lysa igen och glömde att förklara situationen från början.",al={"varför ingen förklaring","mordents anledning","varför väntade han"}},{q="Planerar Mordent att besöka templet?",a="Mordent ser fram emot att besöka Shen'dralas tempel igen, men säger att det kan dröja innan han vågar tala med Shen'dralar där.",al={"tempelbesök","ska mordent dit","shen'dralas tempel"}}},fp="22,132,24.211.0,15.191.1,40.79.0,45.84.0,42.117.0,38.140.0"}
P.entries["quest:93036"] = {n="Infiltrating the Cult",s="Infiltrating the Cult är ett uppdrag i Shen'dar Village där en okänd äventyrare får i uppgift att närma sig den lokala missionären Sania Silverstream. Bakom sin fromma fasad värvar Sania anhängare till Al'Aketh, en kult tillägnad vindherren Al'Akir. Uppdraget går ut på att avslöja kultens verkliga planer för bosättningen innan den sköra freden brister.",h="Infiltrating the Cult är ett uppdrag i Shen'dar Village där en okänd äventyrare får i uppgift att närma sig...",kw={"al'aketh","al'akir","alaketh","infiltrating the cult","sania silverstream","shen'dar village","vindherre","vindfurste"},ang={["class:Priest"]="Sania Silverstream utger sig för att vara en lägre prästinna, men hennes tro tillhör en elementarherre snarare än det Heliga Ljuset eller Elune. Sanna präster kommer att känna igen hennes behagliga religiösa fasad som en täckmantel för elementardyrkan.",["class:Rogue"]="Att infiltrera en fientlig kult genom en ovetande värvare passar en skurks talanger inom spionage, bedrägeri och spaning bakom fiendens linjer."},sec={{t="En skör fred",b="I Shen'dar Village håller en orolig vapenvila på att falla samman. Under en tid har de lokala myndigheterna tolererat Sania Silverstreams närvaro. Hon är en självutnämnd missionär som bor bland dem. Hon företräder Al'Akeths orden, en organisation som klär sig i en godartad religiös rörelses skrud samtidigt som den skickar ut vänliga värvare för att locka ovetande anhängare. Byäldste tillät henne att värva enbart för att undvika att provocera kulten till öppen konflikt, men förespeglingen om att kunna leva sida vid sida håller på att blekna."},{t="Bakom missionärens slöja",b="Bakom det diplomatiska spelet och det stillsamma missionsarbetet finns hängivenhet till en uråldrig och farlig makt: Al'Akir vindherren, luftens elementarers härskare. När man närmar sig presenterar sig Sania öppet som en lägre prästinna i Al'Akeths orden. Hon bjuder in blivande invigda att lära sig om deras härskare och lovar dem en plats vid hans bord. Eftersom de bofasta känner henne alltför väl för att kunna undersöka henne säkert, får nykomlingar i byn i uppgift att vinna hennes förtroende och avslöja vad kulten egentligen planerar för Shen'dar."}},faq={{q="Vem är Sania Silverstream?",a="Sania Silverstream är en lägre prästinna i Shen'dar Village som säger sig vara missionär för en religiös orden kallad Al'Aketh. I själva verket värvar hon lokalbefolkningen på ett vänligt och harmlöst sätt till dyrkan av vindherren Al'Akir.",al={"vem är sania","sania silverstreams historia","prästinnan sania"}},{q="Vad är Al'Akeths orden?",a="Al'Aketh är en kult som utger sig för att vara en vanlig religiös rörelse. Bakom sina offentliga missionsaktiviteter vördar de Al'Akir vindherren, luftens elementarherre, och försöker utöka sitt inflytande genom att i det tysta värva anhängare från närliggande bosättningar.",al={"vilka är alaketh","vad är alaketh","alakeths orden"}},{q="Varför har Shen'dar Village tolererat Sania Silverstream?",a="Byäldste har tolererat Sania Silverstreams missionärsnärvaro för att bevara en skör illusion av fred och undvika öppen fientlighet med kulten. Men den oroliga vapenvilan är snabbt på väg att brista, och därför har man beslutat att undersöka henne i hemlighet.",al={"varför låta sania stanna","varför inte döda sania","varför är sania i byn"}},{q="Vem är vindherren Al'Akir?",a="Al'Akir vindherren är elementarherren över himlen, stormarna och luften. Al'Akeths orden vördar honom som sin gudomliga härskare och lovar en plats vid vindherrens bord åt alla som ångrar sig och ansluter sig till deras sak.",al={"vem är vindherren","al'akirs historia","vem är al'akir"}},{q="Varför får du infiltrera kulten i stället för någon från byn?",a="Eftersom du är en okänd nykomling i Shen'dar Village kommer Sania och Al'Aketh inte att misstänka att du arbetar för byns ledare. Du kan närma dig henne under förevändningen att du är en intresserad rekryt utan att väcka misstankar.",al={"varför jag","varför skicka en äventyrare","varför infiltrera kulten"}},{q="Vad planerar Al'Aketh för Shen'dar Village?",a="De lokala ledarna misstänker att Al'Akeths värvningsförsök döljer större och aggressiva ambitioner för Shen'dar Village. Huvudsyftet med att infiltrera kulten är att avslöja dessa hemliga planer innan byns sköra fred kollapsar helt.",al={"kultens planer för byn","vad vill alaketh","alakeths avsikter"}}},fp="21,204,18.424.0,29.388.1,26.197.0,34.244.0,54.210.0,28.192.0,60.218.0,52.181.0"}
P.entries["quest:93065"] = {n="Prepare for Battle",s="Prepare for Battle markerar Peacekeepers mobilisering när de samlar sina styrkor för att marschera ut från staden. Äventyrare kallas till sina sista förberedelser och ska möta Valennia Stormfist i Gustberry Lowlands innan truppen ger sig av.",h="Prepare for Battle markerar Peacekeepers mobilisering när de samlar sina styrkor för att marschera ut från...",kw={"östra vägen","gustberry lowlands","mobilisering","peacekeepers","prepare for battle","valennia stormfist"},ang={["class:Warrior"]="För frontkämpar är mobiliseringen ett avgörande förspel till striden, där utrustningskontroller och leden som formas tillsammans med allierade avgör hur det kommande slaget utvecklar sig."},sec={{t="En kallelse till samling",b="När spänningarna i regionen ökar har det lokala försvarsförbandet Peacekeepers kallat till vapen. Soldater och frivilliga beordras att säkra sin utrustning, göra vapnen redo och samlas för en organiserad marsch genom det omgivande området."},{t="Samlingen i Gustberry Lowlands",b="Uppsamlingsplatsen för expeditionen ligger längs den östra vägen som går norrut från staden in i Gustberry Lowlands. Där genomför samordnaren Valennia Stormfist en sista inspektion och upprop för att säkerställa att alla kämpar är redo innan truppen marscherar in i faran."}},faq={{q="Vem är Valennia Stormfist?",a="Valennia Stormfist samordnar Peacekeepers uppbåd i Gustberry Lowlands. Hon övervakar de sista förberedelserna längs den östra vägen norrut från staden innan styrkorna ger sig av.",al={"vem är valennia stormfist","valennia stormfist","stormfist"}},{q="Vilka är Peacekeepers?",a="Peacekeepers är ett organiserat lokalt militärt förband eller försvarsförband som nu mobiliserar sina styrkor för att möta ett hot som närmar sig utanför staden.",al={"vilka är peacekeepers","peacekeepers","peacekeepers styrka"}},{q="Var ligger Gustberry Lowlands?",a="Gustberry Lowlands är regionens uppsamlingsområde där de lokala försvarsstyrkorna samlas. Det ligger längs vägen norrut från staden.",al={"var ligger gustberry lowlands","gustberry lowlands plats","gustberry lowlands"}},{q="Vad förbereder sig Peacekeepers för?",a="Peacekeepers rustar sig för att marschera ut med full styrka och kallar alla dugliga allierade att kontrollera sin utrustning och samlas vid stadens utkant innan expeditionen ger sig av.",al={"vad förbereder de sig för","varför förbereda sig för strid","vad är det för strid"}},{q="Var ligger mötesplatsen för marschen?",a="Samlingsplatsen ligger längs den östra vägen norrut från staden. Den har valts så att truppen kan formera sig innan marschen ut på fältet.",al={"var ligger samlingsplatsen","var ska man möta valennia","mötesplats"}},{q="Vad händer när alla har samlats?",a="När de har anmält sig gör Valennia Stormfist en sista avstämning med de samlade leden och konstaterar att styrkorna är så redo de kan bli för att marschera ut i faran.",al={"hur avslutas uppbådet","vad säger valennia","vi är så redo vi kan bli"}}},fp="18,208,16.240.0,35.213.0,26.187.0,25.115.0,33.128.0,40.160.0,44.142.0,40.102.0"}
P.entries["quest:93066"] = {n="Bristleback Retreat",s="En befälhavare från Magram skickar dig till Bristleback Retreat för att konfrontera quilboar som bär på en artefakt från ett närbeläget tempel. Deras fäste har hindrat arbetet i Magram-lägret.",h="En befälhavare från Magram skickar dig till Bristleback Retreat för att konfrontera quilboar som bär på en...",kw={"artefakt","bristleback retreat","bristlebacks","desolace","hagiak","magram","quilboar","tempel","valley of bones"},sec={{t="Magram Foothold",b="På andra sidan Valley of Bones i Desolace har Magram slagit upp ett litet läger inför marschen in i en närbelägen skog. Ett Bristleback-infall blockerar deras väg. Quilboar anlände ungefär samtidigt som Magram och tog en artefakt från ett närbeläget tempel. Du skickas till Bristleback Retreat för att döda quilboar och sedan rapportera till Hagiak vid Magram Front."},{t="Ett nytt syfte",b="Vid Magram Front säger Hagiak att din närvaro har försenat lägrets arbete och att de inte behöver dig där. Sedan ändrar han sig och hittar en annan uppgift åt dig som soldat."}},faq={{q="Varför vill Magram att quilboar ska dödas?",a="Bristlebacks har tagit en artefakt från ett närbeläget tempel, och deras intrång hindrar arbetet i Magram-lägret.",al={"varför döda bristlebacks","quilboar vid reträtten","bristleback-problem"}},{q="Var ligger Bristleback Retreat?",a="Bristleback Retreat ligger på andra sidan Valley of Bones i Desolace.",al={"bristleback-plats","var finns grisarna","reträttens plats"}},{q="Vem ska jag rapportera till?",a="Rapportera till Hagiak vid Magram Front, på andra sidan Valley of Bones i Desolace.",al={"rapportera till hagiak","vem finns vid magram front","hagiaks plats"}},{q="Vad förbereder sig Magram på att göra?",a="Magram har etablerat ett litet fotfäste inför en marsch in i en närbelägen skog.",al={"magrams planer","varför etablera ett fotfäste","marsch in i skogen"}}},fp="19,169,19.345.0,19.173.1,40.111.0,29.58.0,23.73.0,35.89.0"}
P.entries["quest:93072"] = {n="Long-Term Solutions",s="Vid Magram Front skickar Hagiak dig mot Gelkis-klanens Outcast-spejare, plundrare och nekromantiker. Magram vill göra Desolace till hem för centaurer av eget blod.",h="Vid Magram Front skickar Hagiak dig mot Gelkis-klanens Outcast-spejare, plundrare och nekromantiker.",kw={"desolace","gelkis","hagiak","långsiktiga lösningar","magram","plundrare","nekromantiker","outcasts","spejare"},sec={{t="Magrams krav",b="Hagiak vid Magram Front skickar dig mot Gelkis Village i sydväst. Han förväntar sig att du bevisar din lojalitet mot Magram genom att angripa Gelkis Outcasts. Klanen vill ha landet åt centaurer av Magram-blod, och Hagiaks uppmaning lämnar föga utrymme för tvivel."},{t="Anspråk på Desolace",b="Hagiaks spejare rapporterar att du lyckats, och han säger att Magram kan fortsätta sin träning i fred. Han uppmanar till att döda alla eftersläntrare så att de fruktar att lämna sin by. Magram tänker fortfarande göra anspråk på Gelkis hem och Desolace åt sig själva."}},faq={{q="Vem ger det här uppdraget?",a="Hagiak vid Magram Front skickar dig mot Gelkis Outcasts.",al={"vem är hagiak","hagiaks uppdrag"}},{q="Var finns Gelkis?",a="Deras by ligger sydväst om Magram Front.",al={"var ligger gelkis village","den andra centaurbyn"}},{q="Vilka är Outcasts?",a="De är Gelkis-spejare, plundrare och nekromantiker.",al={"vilka är outcasts","gelkis outcasts"}},{q="Varför skickar Hagiak mig efter dem?",a="Hagiak förväntar sig att du bevisar din lojalitet mot Magram genom att angripa Gelkis Outcasts.",al={"varför döda outcasts","lojalitet mot magram"}},{q="Vad vill Magram?",a="Magram gör anspråk på Gelkis hem och Desolace åt centaurer födda av Magram-blod.",al={"magrams mål","vem äger desolace"}}},fp="19,175,15.271.0,19.250.1,20.67.0,21.56.0,21.51.0,35.91.0,24.79.0"}
P.entries["quest:93089"] = {n="What Comes Next",s="På Zephras Isle söker High Order din välsignelse inför avresan med sina allierade från Kirin Tor. Deras expedition är beroende av att finna en arkan lösning på öns instabilitet.",h="På Zephras Isle söker High Order din välsignelse inför avresan med sina allierade från Kirin Tor.",kw={"ansirem","dalaran","elaadrin evengale","high order","kirin tor","skycutter","what comes next","zephras isle"},sec={{t="Avresan",b="High Elder Shadowsong har välsignat expeditionen, och förberedelserna är klara. Ansirem har arbetat för att upprätta resor med skycutter mellan Dalaran och Zephras Isle. Nu förbereder sig förtruppen för avfärd. Tala med Elaadrin Evengale när du är redo att lämna ön."}},faq={{q="Vem ska jag tala med innan jag lämnar Zephras Isle?",a="Tala med Elaadrin Evengale när du är redo att lämna Zephras Isle.",al={"vem ska jag tala med","lämna zephras isle","elaadrins avresa"}},{q="Vart är High Order på väg?",a="High Order förbereder en expedition, med transport med skycutter mellan Dalaran och Zephras Isle.",al={"vart är de på väg","high orders resmål","nästa anhalt"}},{q="Vem hjälper High Order?",a="Kirin Tor hjälper High Order. Ansirem har arbetat med transport med skycutter mellan Dalaran och Zephras Isle.",al={"vilka är de allierade","hjälp från kirin tor","high orders vänner"}},{q="Vad söker expeditionen?",a="Expeditionen hoppas finna en arkan lösning som kan ge Zephras Isle stabilitet.",al={"vad letar de efter","arkan lösning","varför lämna ön"}},{q="Vad hände med kulten?",a="Elaadrin säger att kulten har besegrats och att förberedelserna inför expeditionen är klara.",al={"kultens status","är kulten besegrad","hur är det med kulten"}}},fp="15,179,13.274.0,48.70.0,30.101.0,30.117.0,31.83.0,26.91.0"}
P.entries["quest:93090"] = {n="What Comes Next",s="What Comes Next markerar slutet på händelserna på Zephras Isle, när resenärer förbereder sig på att ge sig av genom skyn. Det lokala kult hotet är undanröjt och High Elder Shadowsongs välsignelse är säkrad. Nu öppnas färder med skycutter mellan ön och Mulgore slätter.",h="What Comes Next markerar slutet på händelserna på Zephras Isle, när resenärer förbereder sig på att ge sig av...",kw={"ayessa dawnsinger","earthen ring","high elder shadowsong","mulgore","muln","skycutter","what comes next","zephras isle"},ang={["class:Shaman"]="Expeditionen ordnar direkta färder till Mulgore för att knyta kontakt med Earthen Ring, den högt aktade shamanorganisationen som verkar för att lugna Azeroths elementandar.",["race:Tauren"]="Målet på andra sidan skyn är Mulgore, taurenernas förfäders hemland där Earthen Ring bedriver sin verksamhet."},sec={{t="Avfärd från Zephras Isle",b="När den lokala kulten besegrats och tryggheten återvänt till Zephras Isle har High Elder Shadowsong välsignat den fortsatta färden. Expeditionen på ön blickar nu bortom dess stränder och riktar fokus mot Kalimdors öppna himmel. Ayessa Dawnsinger samordnar den sista avfärden för dem som är redo att lämna ön bakom sig."},{t="Skycutters till Mulgore",b="Det krävdes noggranna förberedelser för att ordna färder från ön. Muln arbetade målmedvetet för att säkra stabila skycutterfärder mellan Zephras Isle och Mulgore. Efter lyckade provfärder har en förtrupp redan tagit sig över och väntar på andra sidan, redo att ta kontakt med shamanerna i Earthen Ring."}},faq={{q="Vad är uppdraget What Comes Next?",a="What Comes Next är ett övergångsuppdrag som markerar avfärden från Zephras Isle. Efter att ha fått High Elder Shadowsongs välsignelse och sett till att kulten besegrats förbereder sig resenärerna på att färdas med skycutter till Kalimdors fastland.",al={"vad är what comes next","uppdraget what comes next","vad är det här för uppdrag"}},{q="Vart reser expeditionen?",a="Skycutterfärden går mellan Zephras Isle och Mulgore, ett gräsbevuxet höglandsområde mitt i Kalimdor där Earthen Ring har sitt hem och där expeditionens förtrupp redan väntar.",al={"vart ska vi","skycutter destination","vart flyger skycutter"}},{q="Vem är Ayessa Dawnsinger?",a="Ayessa Dawnsinger samordnar avfärden från Zephras Isle. Hon bekräftar att förberedelserna är klara, att provflygningarna har lyckats och att expeditionen har High Elder Shadowsongs välsignelse att ge sig av.",al={"vem är ayessa dawnsinger","ayessa dawnsinger","ayessa"}},{q="Vem är Muln?",a="Muln är en allierad som arbetade målmedvetet för att ordna stabila skycutterfärder mellan Zephras Isle och Mulgore. Han genomförde provfärder för att säkerställa en trygg resa genom skyn.",al={"vem är muln","muln skycutter","muln zephras"}},{q="Vad är Earthen Ring?",a="Earthen Ring är en sammanslutning av shamaner som strävar efter att upprätthålla harmoni mellan elementandar. Under expeditionen är de kontaktpersoner och värdar som välkomnar resenärerna till Mulgore.",al={"vad är earthen ring","earthen ring mulgore","vilka är earthen ring"}},{q="Varför lämnar expeditionen Zephras Isle?",a="När den lokala kulten besegrats och High Elder Shadowsongs välsignelse säkrats är syftet med att stanna isolerade på Zephras Isle uppnått. Expeditionen kan nu fortsätta till fastlandet.",al={"varför lämna zephras isle","är zephras färdigt","varför åka till mulgore"}}},fp="15,214,27.332.0,21.231.0,34.191.0,33.185.0,25.184.0,12.149.0,25.166.0,43.176.0"}
P.entries["quest:931"] = {n="The Shimmering Frond",s="Bland rötterna och trädkronorna i Teldrassil har en märklig växt upptäckts, skimrande av ett utomvärldsligt ljus. Resenärer inser hur sällsynt den är och tar ett exemplar till botanikern Denalan vid Lake Al'Ameth för att ta reda på varifrån den kommer.",h="Bland rötterna och trädkronorna i Teldrassil har en märklig växt upptäckts, skimrande av ett utomvärldsligt...",kw={"botanik","denalan","lake al'ameth","shimmering frond","spirande bladskott","märklig växt med bladskott","swamp of sorrows","teldrassil"},ang={["class:Druid"]="Druider som värnar om det stora trädets balans håller uppsikt över främmande växtliv som förs in i Teldrassils känsliga, unga trädkronor.",["profession:Herbalism"]="Örtmästare och växtentusiaster uppskattar det botaniska mysteriet i att hitta en våtmarksväxt som frodas tusentals kilometer från sitt ursprungliga ekosystem.",["race:NightElf"]="För Night Elf-folket som vårdar sitt nya hem ger Denalans experiment viktiga insikter i hur motståndskraftig Teldrassils jord verkligen är."},sec={{t="Ett märkligt sken",b="När uppmärksamma resenärer vandrar genom Teldrassils grönskande grenar kan de stöta på en märklig växt med bladskott. Till skillnad från skogens vanliga växtlighet fångar dess bladskott ljuset och skimrar med ett pulserande, slingrande sken. Den onaturliga närvaron fångar blicken hos alla som värnar om öns känsliga, unga ekosystem."},{t="Denalans upptäckt",b="När sticklingen förs till botanikern Denalan vid Lake Al'Ameth avslöjas en oväntad sanning. Denalan identifierar växten som ett exotiskt exemplar som inte hör hemma i norra Kalimdor. Han stötte senast på en sådan för flera årtionden sedan, under en resa till det avlägsna Swamp of Sorrows i Eastern Kingdoms. Han fascineras av att ett frö kunnat färdas över havet och växa sig så stort på Världsträdet, och börjar genast odla och undersöka exemplaret."}},faq={{q="Var kommer den märkliga växten ursprungligen ifrån?",a="Enligt botanikern Denalan hör växten hemma i Swamp of Sorrows, en dimmig våtmark långt åt sydost i Eastern Kingdoms. Han hade inte sett ett levande exemplar sedan han besökte träskmarkerna flera årtionden tidigare.",al={"bladskottets ursprung","varifrån kommer bladskottet","träskväxt"}},{q="Vem är Denalan?",a="Denalan är en vetgirig Night Elf-botaniker och örtmästare som håller till nära Lake Al'Ameths strand på Teldrassil. Han ägnar sin tid åt att studera och vårda Teldrassils växande växtliv, och experimenterar ofta med främmande frön och planteringskärl.",al={"denalans historia","vem är denalan"}},{q="Varför växer den här växten på Teldrassil?",a="Det förblir ett ekologiskt mysterium. Denalan förundras över hur ett frö kunnat färdas hela vägen från Eastern Kingdoms över Stora havet och ändå slå rot och frodas till ett så stort exemplar i Teldrassils bördiga jord.",al={"hur kom den till teldrassil","varför är bladskottet här"}},{q="Vad händer efter att man ger bladskottet till Denalan?",a="Denalan placerar genast exemplaret i sin planteringslåda vid Lake Al'Ameth för att utföra tester. Hans odling får snart flera bladskott att spira, vilket leder till ytterligare studier av den exotiska floran.",al={"nästa uppdrag","denalans test","spirande bladskott"}},{q="Orsakar den här växten fördärv i Teldrassil?",a="Nej. Mycket av Teldrassils djurliv påverkas av ett subtilt fördärv från onda krafter, men den här växten verkar bara vara en ovanlig, malplacerad exotisk sort, inte en källa till fördärv.",al={"är bladskottet fördärvat","fördärvad växt"}}},fx={add2b0dd={q="Varför ta en kvist från Strange Fronded Plant till Denalan?",a="Växten har inget medvetet syfte; den är bara ett ovanligt, pulserande exemplar som växer vilt bland Teldrassils grenar. Du känner igen dess märkliga, skimrande aura som något främmande och kanske onaturligt för det stora trädet, så du skördar ett skott åt Denalan, botanikern vid Lake Al'Ameth som studerar sällsynta växter.",al={"strange fronded plants motiv","varför ta skottet till denalan","varför ta skottet"}}},fp="20,168,14.188.0,19.318.1,50.139.0,15.180.0,40.174.0,47.151.1,47.107.0"}
P.entries["quest:93129"] = {n="Threat of Starvation",s="Hagiak ber dig föra stulna förnödenheter från Outcast Hideaway till Magram Front. Han tänker använda dem för att försvaga exilerna och främja Magram-klanens planer.",h="Hagiak ber dig föra stulna förnödenheter från Outcast Hideaway till Magram Front.",kw={"exiler","hagiak","magram","magram front","outcast hideaway","svält","stulna förnödenheter"},sec={{t="Magrams mål",b="Hagiak skickar dig till Outcast Hideaway för att hämta förnödenheter och ber dig samtidigt att behålla ditt anseende hos Magram. Han ser exilerna som fiender och räknar med att deras nederlag ska föra gömstället under Magrams kontroll. Han hoppas också kunna samla en armé mot de andra klanerna."},{t="Vid fronten",b="Vid Magram Front granskar Hagiak lådorna du kommer tillbaka med. En del innehåller mat, och han tror att det kommer att förkorta exilernas tid där. Han ser Magrams seger som allt närmare."}},faq={{q="Vem ber om förnödenheter?",a="Hagiak ber dig ta med förnödenheter till honom vid Magram Front.",al={"vem vill ha förnödenheter","hagiaks förnödenheter"}},{q="Var kommer förnödenheterna ifrån?",a="Hagiak skickar dig till Outcast Hideaway för att hämta förnödenheter.",al={"varifrån kommer förnödenheterna","förnödenheter från outcast hideaway"}},{q="Vilka förnödenheter vill Hagiak ha?",a="Hagiak ber dig ta med sex stulna förnödenheter tillbaka till Magram Front.",al={"vad ska tas med","stulna förnödenheter"}},{q="Varför vill Hagiak ha förnödenheterna?",a="Hagiak tror att förnödenheterna kommer att förkorta exilernas tid vid gömstället.",al={"varför förnödenheter","svälta ut exilerna"}},{q="Vad vill Hagiak för Magram?",a="Hagiak vill att Magram ska säkra gömstället och samla en armé mot de andra klanerna.",al={"magrams planer","andra klaner"}}},fp="20,166,16.262.0,12.184.1,27.61.0,32.55.0,31.70.0,34.77.0,37.89.0"}
P.entries["quest:93159"] = {n="The Strange Hermit",s="The Strange Hermit är ett introduktionsuppdrag i Shadowgale Forest om en blyg, huvbärande enstöring som bor långt från civilisationen. Efter lång tids isolering söker eremiten samtal och delar med sig av glimtar från sitt enkla, handgjorda liv och sitt band till de sjungande skogsandarna i trakten.",h="The Strange Hermit är ett introduktionsuppdrag i Shadowgale Forest om en blyg, huvbärande enstöring som bor...",kw={"skogsandar","handgjord","eremit","huvbärande gestalt","ensamvarg","shadowgale forest","märklig eremit"},ang={["class:Druid"]="Druider som står i samklang med naturen kan uppskatta eremitens kontakt med traktens skogsandar, även om hans oförmåga att verkligen samtala med dem skiljer sig från en druids djupare förbindelse.",["profession:Engineering"]="Hantverkare och uppfinnare kan känna igen sig i hur eremiten finner ro i att bygga saker för hand och inreda sitt ensliga hem."},sec={{t="En enstöring i skogen",b="Djupt inne bland Shadowgale Forests avskilda trädkronor bor en gåtfull, huvbärande enstöring som bara är känd som The Strange Hermit. Långt från bebodda samhällen och vanliga handelsvägar tillbringar han dagarna i stilla ensamhet bland träden. När du närmar dig märks det på hans stapplande tal och nervösa uppträdande hur länge han har levt utan vanligt umgänge. Till och med en enkel hälsning blir en obekant utmaning."},{t="Andar och enkla ting",b="Trots sitt ensamma liv hävdar eremiten att han har allt sällskap och alla förnödenheter han behöver. Han berättar att han bodde någon annanstans innan han slog sig ner här och valde ett liv omgiven av handgjorda prydnader och skogens andar. De vilda andarna sjunger ofta för honom, men han medger att melodiska körer inte helt kan ersätta samtal med någon som verkligen kan svara."}},faq={{q="Vem är den märkliga eremiten?",a="The Strange Hermit är en excentrisk, huvbärande person som lever isolerad i Shadowgale Forest. Han är ovan vid regelbundet umgänge och tillbringar sin tid med att sköta handgjorda tillhörigheter och umgås med traktens skogsandar i stället för med andra människor.",al={"märklig eremit","eremitens identitet","vem är eremiten"}},{q="Var bor eremiten?",a="Eremiten har sitt hem avskilt, djupt bland träden i Shadowgale Forest, långt från de vanliga vägarna där få resenärer någonsin vandrar.",al={"var är eremiten","shadowgale forests plats","eremitens område"}},{q="Varför lever eremiten ensam?",a="Han medger att han bodde på en helt annan plats innan han drog sig tillbaka till skogen. Han är mycket fåordig om sitt förflutna, men valde ett stilla liv omgiven endast av sådant han själv byggt och skogens vilda andar.",al={"varför är eremiten ensam","eremitens isolering","eremitens bakgrund"}},{q="Kan eremiten tala med skogsandar?",a="Han ser traktens skogsandar som sina följeslagare, även om de inte för vanliga samtal. I stället sjunger de för honom, vilket han tycker om, även om sången inte ger samma djup i samtalet som med en annan dödlig.",al={"eremiten talar med andar","shadowgale forests skogsandar","eremitens vänner"}},{q="Vad har eremiten byggt i skogen?",a="Eremiten nämner att han har flera handgjorda föremål och konstruktioner som håller honom sysselsatt. Han finner ro och tillfredsställelse i enkla, handgjorda ägodelar.",al={"eremitens hantverk","vad byggde eremiten"}},{q="Vad händer under uppdraget ”The Strange Hermit”?",a="Uppdraget går ut på att närma sig den nervöse eremiten i Shadowgale Forest, inleda ett vänligt samtal och höra vad han är villig att berätta om sitt tillbakadragna liv.",al={"uppdraget the strange hermit","tala med eremiten"}}},fp="18,192,22.261.0,25.245.0,26.194.0,27.117.0,36.180.0,41.148.0,40.140.0,51.115.0"}
P.entries["quest:93160"] = {n="The Forest's Bounty",s="The Forest's Bounty är ett lokalt uppdrag i Shadowgale Forest där en försiktig örtletare ber om hjälp att samla fallna ekollon. Glupska rovfåglar stryker omkring i skogens djupare delar, så det är alltför farligt att plocka dem utan en äventyrares beskydd. Ekollonen rostas sedan till en smakrik måltid från skogen.",h="The Forest's Bounty är ett lokalt uppdrag i Shadowgale Forest där en försiktig örtletare ber om hjälp att...",kw={"ekollon","matlagning","plocka vilda växter","rovfågel","shadowgale acorns","shadowgale forest","the forest's bounty"},ang={["profession:Cooking"]="Att samla Shadowgale Acorns visar hur lokala vilda nötter kan rostas till enkel skogsmat, vilket gör dem särskilt intressanta för matintresserade örtletare."},sec={{t="En farlig plocktur",b="En försiktig örtletare som söker mat i Shadowgale Forest hamnar i knipa. Ekollon ligger utspridda över skogsmarken, men rovfågelslika varelser stryker omkring bland träden. Efter att ha samlat allt som fallit nära tryggheten är örtletaren beroende av förbipasserande resenärer som vågar sig in i de vildare dungarna, så att ingen av dem behöver gå hungrig."},{t="Skörden rostas",b="Shadowgale Acorns ger rejält med näring åt den som vet hur de ska tillagas. Råa är de bittra eller hårda, men när de rostas över en sprakande eld blir skogens vilda skörd en mustig, rostad godsak. Att trotsa rovfåglarna bland träden förvandlar ett enkelt skogssökande till en varm måltid ute i vildmarken."}},faq={{q="Vem ber dig att samla ekollonen?",a="En nervös örtletare som vilar nära Shadowgale Forest ber om hjälp. Hen har samlat alla ekollon i närheten som är säkra att plocka och behöver nu en tålig äventyrare som vågar sig längre in i skogen, där farliga djur strövar omkring.",al={"vem ger uppdraget the forest's bounty","vem vill ha ekollon","uppdragsgivare the forest's bounty"}},{q="Var finns ekollonen?",a="Shadowgale Acorns ligger utspridda på marken under trädkronorna i Shadowgale Forest. Den som letar måste söka på skogsmarken och samtidigt hålla utkik efter fientliga rovdjur bland träden.",al={"var finns shadowgale acorns","ekollonens plats","ekollon i shadowgale forest"}},{q="Varför är det farligt att samla ekollon här?",a="Rovfåglar stryker omkring på skogsmarken. Dessa aggressiva varelser gör det mycket farligt för vanligt folk utan stridsträning att ge sig långt från lägret och försvara sig.",al={"varför är shadowgale forest farlig","vad är rovfåglar","varför är det farligt att samla ekollon"}},{q="Vad används ekollonen till?",a="Ekollonen är en mättande källa till vildmarksmat. När de har samlats in ska de rostas över en eld till ett varmt, nötigt mellanmål att dela med dem som vågar trotsa skogens bestar.",al={"vad används shadowgale acorns till","rostade ekollon","varför samla ekollon"}},{q="Vad är det för rovfågelliknande varelser som nämns i skogen?",a="Uppdragsgivaren beskriver dem som farliga ”rovfågelsgrejer” som jagar i Shadowgale Forest. Dessa fågel- eller reptillika rovdjur är tillräckligt stora och vildsinta för att se en oförsiktig resenär som sin nästa måltid.",al={"vad är en rovfågelsgrej","rovfåglar i shadowgale forest","rovfåglar i skogen"}},{q="Hur tillagas ekollonen?",a="Ekollonen är hårda eller bittra när de plockas från marken, men örtletaren påpekar särskilt att Shadowgale Acorns blir en utsökt godsak när de rostas ordentligt över värme.",al={"går det att äta shadowgale acorns råa","hur tillagar man shadowgale acorns","äta skogsekollon"}}},fp="19,164,23.292.0,20.236.0,34.162.0,27.132.0,40.133.0,29.128.0,59.181.0,39.99.0"}
P.entries["quest:93165"] = {n="Mercy Falls on Deaf Ears",s="Mercy Falls on Deaf Ears är en belöning som utlovas av en sörjande enklav som söker våldsam hämnd på Al'Aketh-kulten. Efter en fruktansvärd tragedi som kultisterna orsakat lovar enklaven mynt och tillgång till Nightclaws dolda kunskap i utbyte mot troféer från deras stupade fiender. Den som antar uppdraget kastas rakt in i konflikten som sprider sig genom Shadowgale Forest och de omkringliggande områdena.",h="Mercy Falls on Deaf Ears är en belöning som utlovas av en sörjande enklav som söker våldsam hämnd på...",kw={"al'aketh","blodsfejd","kultister","öron","gustberry lowlands","mercy falls on deaf ears","nightclaw","shadowgale forest","shrine of akir"},sec={{t="Blod för blod",b="Fejden mellan Nightclaw-enklaven och Al'Aketh-kultisterna är bitter och skoningslös. Efter en ospecificerad men förödande tragedi som drabbade enklaven har de överlevande gett upp allt hopp om fredlig försoning. För att hämnas sina fallna fränder vänder de sig till kringvandrande äventyrare och legosoldater och kräver våldsam vedergällning. I utbyte mot att fälla kultisterna och ta deras öron som dystra bevis på dådet erbjuder enklaven kalla mynt och utsikten till större förtroende."},{t="Hotet från Al'Aketh",b="Al'Aketh verkar i flera vildmarksområden och sprider sitt inflytande genom Gustberry Lowlands, Shadowgale Forests mörka skogar och det forntida Shrine of Akir. Deras mörka sedvänjor och fanatiska natur har väckt lokalbefolkningens hat. Genom att angripa deras läger i dessa områden försvagar du kultens närvaro och vinner Nightclaws gunst. Denna hemlighetsfulla grupp håller sina egna esoteriska mysterier nära tills en främling bevisar sin lojalitet."}},faq={{q="Vad är Mercy Falls on Deaf Ears?",a="Mercy Falls on Deaf Ears är ett uppdrag där en äventyrare anlitas för att hämnas på Al'Aketh-kultisterna efter en katastrofal attack mot en lokal enklav. Uppdragsgivaren kräver vedergällning: äventyrarna ska döda kultister och återvända med deras avhuggna öron som obestridliga bevis på dödsfallen, i utbyte mot mynt och förtroende.",al={"uppdraget mercy falls on deaf ears","vad är det här för uppdrag","översikt över uppdraget"}},{q="Vilka är Al'Aketh?",a="Al'Aketh är en sekt av förbannade kultister som är kända för att föra olycka och tragedi till närliggande bosättningar. De har en fientlig närvaro i Gustberry Lowlands, Shadowgale Forest och Shrine of Akir och väcker öppna blodsfejder med dem som bor i de omgivande områdena.",al={"vilka är alaketh","alaketh-kultisternas bakgrund","vilka är al'aketh"}},{q="Var hittar man Al'Aketh-kultister?",a="Al'Aketh-kultister finns i tre olika områden: bland Shadowgale Forests täta trädkronor, på den heliga marken kring Shrine of Akir och runtom i Gustberry Lowlands. Om du dödar kultister i något av dessa områden får du de bevis som den sörjande enklaven kräver.",al={"var finns alaketh-kultister","alakeths platser","var hittar man kultister"}},{q="Varför samlar uppdragsgivaren på kultisternas öron?",a="Avhuggna öron är påtagliga och obestridliga bevis på dödsfall i en brutal konflikt i vildmarken, där blod måste betalas med blod. Eftersom enklaven hyser ett djupt hat mot Al'Aketh efter en svår tragedi kräver de fysiska troféer för att försäkra sig om att varje utbetald belöning motsvarar en död kultist.",al={"varför öron","varför vill de ha kultisternas öron","öron som bevis"}},{q="Vilka är Nightclaw?",a="Nightclaw är en hemlighetsfull enklav som har lidit stora förluster till följd av Al'Aketh-kultens härjningar. De är misstänksamma mot främlingar, men besitter välbevarade hemligheter och kunskap. Om utomstående bevisar sin lojalitet genom att krossa deras kultistfiender får de så småningom tillgång till gruppens innersta mysterier.",al={"nightclaw-fraktionen","vilka är nightclaw","nightclaws hemligheter och bakgrund"}},{q="Vilken tragedi orsakade Al'Aketh?",a="Uppdragsgivaren berättar om en stor tragedi som Al'Aketh direkt vållade Nightclaw-enklaven och som utlöste en oförsonlig blodfejd. Belöningen nämner inga specifika dödsoffer eller detaljer, men händelsen var så fasansfull att de överlevande kräver total hämnd utan nåd.",al={"vad gjorde alaketh","vad hände med enklaven","alaketh-tragedin"}},{q="Vilka hemligheter bär Nightclaw på?",a="Nightclaws hemligheter hålls inom enklaven och avslöjas inte genast för utomstående. Uppdragsgivaren lovar att äventyrare som fortsätter hjälpa till i kampen mot Al'Aketh och visar sig vara sanna vänner så småningom får tillgång till denna dolda kunskap.",al={"nightclaws hemligheter","vilka hemligheter har nightclaw","vad avslöjar nightclaw"}}},fp="24,329,15.361.0,19.392.0,33.168.0,21.257.0,37.169.0,46.180.0,22.231.0,36.206.0,33.234.0"}
P.entries["quest:93172"] = {n="Free the Hollows",s="Free the Hollows är ett uppdrag i Shadowgale Forest, där spöklika andar som kallas vindhåligheter dröjer kvar bland forntida ruiner. Fångade av en uråldrig tragedi hemsöker deras sorgsna sång skogarna runtomkring, tills någon befriar dem.",h="Free the Hollows är ett uppdrag i Shadowgale Forest, där spöklika andar som kallas vindhåligheter dröjer kvar...",kw={"free the hollows","spöken","håligheter","ruiner","shadowgale","shadowgale forest","vindhåligheter"},ang={["class:Druid"]="Oroliga andar som dröjer kvar i Shadowgale Forest är en onaturlig störning i vildmarken som kräver balans och befrielse.",["class:Priest"]="Vindhåligheterna är sorgsna skepnader som fångats av tragedi. Att förgöra dem är därför en barmhärtighetshandling som befriar själar bundna i evig vånda.",["race:NightElf"]="Öns lokala alver har länge anat att Shadowgale Forest är hemsökt och oroats av de tragiska andar som dröjer kvar, bundna till deras forntida ruiner."},sec={{t="Hemsökelser i Shadowgale",b="Alver som bor över hela ön har länge betraktat Shadowgale Forest som en hemsökt lund, och deras vidskepelse har grund i verkligheten. Djupt inne i skogen, i nordost, ligger gamla stenruiner där skepnader kända som vindhåligheter driver omkring bland snåren utan slut. Andarna utstrålar ingen fientlighet, utan en djup sorg, fångade av tyngden från den katastrof som drabbade ruinerna för länge sedan."},{t="Den sorgsna sången",b="Under stilla nätter berättar resenärer nära ruinerna att de hör en märklig, eterisk sång som driver med vinden. Den liknar ingen känd sång från dödliga och bär på en djup melankoli som oroar alla som hör den. Med tron att det är en plåga att låta skuggorna vara fångade i sin eviga klagosång söker medkännande resenärer upp vindhåligheterna för att förstöra deras spektrala bojor och skänka dem frid."}},faq={{q="Vad är vindhåligheter?",a="Vindhåligheter är sorgsna, spöklika andar som hemsöker gamla alvruiner i nordöstra Shadowgale Forest. Fångade av någon uråldrig tragedi frambringar de en kuslig, sorgsen sång som ekar bland träden om natten.",al={"vad är vindhåligheter","håligheternas bakgrund","vad är håligheterna"}},{q="Varför måste vindhåligheterna befrias?",a="Uppdragsgivaren tror att andarna är fångade i evig sorg efter en fruktansvärd katastrof. Att förstöra vindhåligheterna ses som en handling av befrielse och barmhärtighet, som frigör deras dröjande skepnader från banden till ruinerna.",al={"varför befria håligheter","varför döda håligheter","syftet med free the hollows"}},{q="Var hittar man andarna?",a="Shadowgale Forest är en skogsklädd ö som bebos av alver. Där finns forntida ruiner i nordost, där de spöklika håligheterna samlas.",al={"var ligger shadowgale forest","ruinerna i shadowgale","ruinernas plats"}},{q="Vad är den märkliga sången som hörs i skogen?",a="Vindhåligheternas sång beskrivs som en oerhört sorgsen melodi som inte liknar någon vanlig sång. Man tror att den föddes ur deras tragiska död och ändlösa fångenskap i öns ruiner.",al={"håligheternas sång","spöksång","varför sjunger spöken"}},{q="Vem ber dig befria håligheterna?",a="Uppgiften erbjuds av en observatör på ön som känner medlidande med de fångade andarna och märker att de lokala alverna är rädda för den hemsökta skogen.",al={"vem ger free the hollows","uppdragsgivare för free the hollows"}},{q="Vad hände vid ruinerna som skapade håligheterna?",a="Även om de exakta detaljerna har fallit i glömska vet lokalbefolkningen att en fruktansvärd händelse inträffade vid ruinerna i nordost och band andarna till platsen i ett evigt, sorgset kretslopp.",al={"vad hände vid ruinerna i shadowgale","varför är ruinerna hemsökta"}}},fp="16,173,23.290.0,17.315.0,26.184.0,41.184.0,28.125.0,47.176.0,33.121.0,49.152.0"}
P.entries["quest:93176"] = {n="My Little Friends",s="En skötare erbjuder dig ett paket för att börja studera tre små varelser. Entomology Starter Kit innehåller anteckningar och material för arbetet.",h="En skötare erbjuder dig ett paket för att börja studera tre små varelser.",kw={"arbor tarantula","entomologi","flesh picker","hay weevil specimen","menageri","my little friends","startsats"},sec={{t="En skötares erbjudande",b="En skötare som har ägnat många timmar åt att studera ett litet menageri erbjuder sig att dela sin hobby med dig. Paketet innehåller anteckningar och material för att komma igång. Med Entomology Starter Kit kan du leta efter en Arbor Tarantula, ett Hay Weevil Specimen och en Flesh Picker."}},faq={{q="Vad vill skötaren att jag ska göra?",a="Använd Entomology Starter Kit för att hitta och fånga en Arbor Tarantula, ett Hay Weevil Specimen och en Flesh Picker.",al={"my little friends uppdrag","vad ska jag samla"}},{q="Vad finns i paketet?",a="Paketet innehåller anteckningar och material för att komma igång med skötarens hobby.",al={"startsatsens innehåll","vad finns i paketet"}},{q="Vad studerar skötaren?",a="Skötaren studerar anatomin, kosten och de sociala ritualerna hos varelserna i ett litet menageri.",al={"litet menageri","vad studerar han"}},{q="Vad händer om jag tappar bort startsatsen?",a="Skötaren säger att du kommer att behöva köpa ett nytt paket för en liten avgift.",al={"borttappad startsats","ersätta startsatsen"}}},fp="17,141,18.256.0,35.111.0,23.86.0,28.96.0,31.74.0"}
P.entries["quest:93188"] = {n="Return to Orgrul",s="Magram Front behöver dig inte längre vid frontlinjen, och Orgrul väntar på din rapport. Nästa drag beror på de stridande som ännu ska ansluta sig.",h="Magram Front behöver dig inte längre vid frontlinjen, och Orgrul väntar på din rapport.",kw={"gelkis","magram","magram front","magram village","orgrul","outcast encampment","utomstående","valley of bones"},sec={{t="Tillbaka till Orgrul",b="Medan du var borta drabbas Magram Village av en krigshandling. Orgrul väntar nära Valley of Bones norra ingång, där du rapporterar tillbaka. Magram Front har blivit starkare och siktar på en ny bosättning. Fler stridande väntas ansluta sig."},{t="En öppning",b="Orgrul kallar det en utomståendes verk under Gelkis banér. Han säger att Magram en gång kanske hade krävt att du avrättades, men ser en möjlighet i det som hänt – för dig, klanen och kriget."}},faq={{q="Varför ska jag återvända till Orgrul?",a="Magram Front säger att den klarar sig utan dig och ber dig rapportera till Orgrul nära Valley of Bones norra ingång.",al={"återvänd till orgrul","rapport till orgrul","varför tillbaka till orgrul"}},{q="Var väntar Orgrul?",a="Orgrul är nära Valley of Bones norra ingång.",al={"orgruls plats","var är orgrul","orgrul valley of bones"}},{q="Vad planerar Magram Front?",a="Magram har siktet inställt på outcast encampment som sin nästa bosättning, när ytterligare en skara stridande ansluter sig.",al={"mag rams nästa bosättning","magram fronts planer","vart är magram på väg"}},{q="Vad hände i Magram Village?",a="Medan du var borta utförde en utomstående, som stred under Gelkis banér, en krigshandling i Magram Village.",al={"incident i magram village","vad hände i byn","gelkis krigshandling"}},{q="Varför kallar Orgrul det en möjlighet?",a="Orgrul ser det som hänt som en öppning för dig, Magram och kriget.",al={"orgruls möjlighet","vilken möjlighet","varför möjlighet"}}},fp="16,153,20.247.0,11.201.1,40.119.0,19.47.0,26.128.0,28.110.1,40.69.0"}
P.entries["quest:93196"] = {n="Khan Jehn",s="Orgrul ber dig hjälpa till att återuppliva Khan Jehn, den stupade ledaren för Magram Clan. Din ställning hos klanen och en ritual vid Magram Villages centrala sjö står på spel.",h="Orgrul ber dig hjälpa till att återuppliva Khan Jehn, den stupade ledaren för Magram Clan.",kw={"centrala sjön","gelkis clan","khan jehn","magram clan","magram village","nekromanti","orgrul","återupplivning"},sec={{t="En klans ledare",b="Khan Jehn, ledare för Magram Clan, dödades av främlingar som agerade för Gelkis Clan. Orgrul säger att anfallet kom medan Magram var upptagna, en strategi han väntar sig av Gelkis. Han ger dig ett välbekant vapen, nu laddat med större kraft, och ber dig behålla Magrams förtroende medan du utför en nekromantisk ritual i ett tält vid byns centrala sjö."},{t="Bland Magram",b="I Magram Village utför du ritualen och behåller din ställning hos klanen. Orgrul ser din lojalitet och potential, trots att du är en främling. Magram tar emot dig som en av sina egna."}},faq={{q="Vem var Khan Jehn?",a="Khan Jehn var ledare för Magram Clan innan främlingar som agerade för Gelkis Clan dödade honom.",al={"khan jehn","magramledare","vem är jehn"}},{q="Vem ber mig hjälpa Khan Jehn?",a="Orgrul ber dig hjälpa till att återuppliva Khan Jehn.",al={"vem ger khan jehn","orgruls uppdrag","magram ber"}},{q="Varför dödades Khan Jehn?",a="Främlingar som agerade för Gelkis Clan dödade Khan Jehn medan Magram var upptagna.",al={"varför dödades jehn","gelkis anfall","vem dödade khan jehn"}},{q="Var finns ritualplatsen?",a="Ritualplatsen finns i ett tält vid Magram Villages centrala sjö.",al={"ritualplats","var återuppliva jehn","magram sjötält"}},{q="Vad ger Orgrul mig?",a="Orgrul ger dig ett välbekant vapen som har laddats med större kraft än förut.",al={"vapen från orgrul","välbekant vapen","förstärkt vapen"}}},fp="9,162,15.368.0,16.210.1,18.97.0,30.42.0,24.92.0,25.67.0,25.73.0"}
P.entries["quest:93197"] = {n="Mending Communications",s="Sebelia behöver att postpaket bärs från lägret på toppen av Mount Hyjal till Innkeeper Vizzie i Everlook. Hårda strider och reträtten från Nordrassil Lodge har lämnat bergsutposten underbemannad och hotar kontakten med bosättningarna nedanför.",h="Sebelia behöver att postpaket bärs från lägret på toppen av Mount Hyjal till Innkeeper Vizzie i Everlook.",kw={"everlook","innkeeper vizzie","post","mending communications","mount hyjal","nordrassil lodge","paket","sebelia","winterspring"},sec={{t="Brev från toppen",b="Strider över hela Mount Hyjal och en tvingad reträtt från Nordrassil Lodge har lämnat försvararna underbemannade i lägret på toppen. Sebelia behöver någon som färdas nedför bergsstigen och bär en bunt postpaket till Everlook, så att nyheter från höjderna når låglandet."},{t="Meddelande till Everlook",b="På värdshuset i Everlook tar Innkeeper Vizzie emot bergsposten och sorterar den för stadens post. När du bär dessa försändelser hålls det hårt ansatta lägret ovanför i kontakt med Winterspring medan försvararna håller höjderna."}},faq={{q="Vem är Sebelia?",a="Sebelia håller till i lägret på toppen av Mount Hyjal och sköter posten och förråden åt dem som är stationerade högt uppe på berget.",al={"sebelias plats","vem är sebelia","vem ger uppdraget mending communications"}},{q="Vem tar emot paketen i Everlook?",a="Innkeeper Vizzie sköter värdshuset nere i goblinstaden Everlook, där hon sorterar och delar ut brev från högländerna.",al={"var ska posten lämnas","innkeeper vizzies plats","vem tar emot posten från hyjal"}},{q="Varför har kommunikationen på Mount Hyjal störts?",a="Strider uppe på höjderna och reträtten från Nordrassil Lodge lämnade lägret underbemannat och satte stopp för vanliga resor och regelbunden post mellan topparna och Winterspring.",al={"varför leverera post till everlook","varför behöver posten flyttas från hyjal"}},{q="Vad hände vid Nordrassil Lodge?",a="Hårda strider på berget tvingade försvararna att dra sig tillbaka från Nordrassil Lodge, vilket gjorde att förråd och manskap blev knappa.",al={"vad hände med nordrassil lodge","reträtten från nordrassil lodge"}}},fp="22,251,23.277.0,16.213.1,15.119.0,34.129.0,48.165.0,34.123.0"}
P.entries["quest:932"] = {n="Twisted Hatred",s="Twisted Hatred är ett hemligt uppdrag från Tallonkai Swiftroot i Teldrassil. Han ber betrodda hjältar ta sig in i Fel Rocks grotta och döda Lord Melenas, en satyr som samlar de lokala grell till en organiserad, korrumperande styrka farligt nära nattalvernas bosättningar.",h="Twisted Hatred är ett hemligt uppdrag från Tallonkai Swiftroot i Teldrassil.",kw={"fel rock","grell","lord melenas","satyr","tallonkai swiftroot","teldrassil","twisted hatred"},ang={["class:Druid"]="Melenas och hans korrumperade grell vid Fel Rock förgiftar den sköra balansen i Teldrassils nyvuxna vildmark.",["race:NightElf"]="Varje satyr är en forntida påminnelse om hur dina förfäder föll offer för demoniska ambitioner. Att döda Lord Melenas är både en plikt mot världsträdet och en botgöring för dina förfäder."},sec={{t="En bitter skam",b="För nattalverna är satyrer ett levande minne av ett forntida svek. De föddes ur Highborne som överlämnade sig åt Burning Legion under War of the Ancients och är getbenta demoner, en smärtsam och bestående skamfläck i kaldoreis historia. Att en satyr skulle etablera ett avskyvärt fäste just här i Teldrassil, det unga världsträdet som skulle vara en fristad, ses av lokala försvarare som Tallonkai Swiftroot som en stor skam."},{t="Hotet vid Fel Rock",b="Norr om stigarna i närheten ligger Fel Rock, ett korrumperat grottsystem fullt av vilda grell. Lord Melenas har samlat dessa naturligt kaotiska varelser till en fientlig, organiserad styrka under sin mörka vilja. Tallonkai fruktar vad satyren tänker släppa lös bland världsträdets grenar och kräver att Melenas dödas snabbt, tyst och beslutsamt. Ta med hans avhuggna huvud tillbaka."}},faq={{q="Vem är Lord Melenas?",a="Lord Melenas är en satyr som tagit grottan Fel Rock i norra Teldrassil i besittning. Han leder en skara aggressiva grellkrigare och smider planer på att sprida korrumpering över hela världsträdet.",al={"lord melenas","vem är melenas","bossen i fel rock"}},{q="Var hittar jag Lord Melenas?",a="Han håller till djupt inne i Fel Rock, ett taggigt grottsystem norr om Dolanaar i Teldrassil, omgiven av grell och andra korrumperade varelser.",al={"melenas plats","var är melenas","hur hittar man fel rock"}},{q="Varför vill Tallonkai Swiftroot hålla det här hemligt?",a="Satyrer representerar ett fasansfullt, forntida kapitel i nattalvernas historia. De svek sitt folk under War of the Ancients. Att en satyr lurar så fräckt i hjärtat av det nyplanterade världsträdet ses som en fullständig skam som Tallonkai helst vill hantera utan att skapa allmän panik.",al={"varför hemligt","varför måste det här stanna mellan oss","tallonkai hemlighet"}},{q="Vilken relation har satyrer till grell?",a="Grell är små, busiga och naturligt korrumperade vilda varelser som finns över hela Teldrassil. Satyrer är listiga och till sin natur demoniska, så de skrämmer eller tvingar gärna dessa mindre varelser att tjäna sina avskyvärda mål.",al={"grell och satyrer","varför följer grell melenas","satyrers koppling till grell"}},{q="Varför finns det satyrer på Teldrassil över huvud taget?",a="Teldrassil växte upp för bara några år sedan. Trots druidernas förhoppningar om en ren fristad kröp korrumpering och mörka varelser snabbt in på ön. Satyrer smög sig in och etablerade fästen på skuggiga platser som Fel Rock.",al={"satyrer på teldrassil","hur kom satyrerna hit","korrumpering av teldrassil"}},{q="Vem är Tallonkai Swiftroot?",a="Tallonkai Swiftroot är en nattalvsväktare stationerad nära Dolanaar. Han håller utkik efter nya hot mot Teldrassil och ger äventyrare i uppdrag att oskadliggöra närliggande fickor av korrumpering.",al={"tallonkai","vem ger uppdraget twisted hatred"}}},fx={["84ee0888"]={q="Varför behöver Tallonkai Swiftroot Melenas' Head?",a="Tallonkai Swiftroot ber om Lord Melenas avhuggna huvud som obestridligt bevis på att satyren verkligen har dödats. När Lord Melenas är död och huvudet är i hans hand kan Tallonkai vara säker på att det vidriga hotet alldeles intill Shadowglen har undanröjts i hemlighet. Då kan han lämna den förödmjukande saken bakom sig utan att väcka de äldstes oro.",al={"melenas heads syfte","varför ta tillbaka melenas head","vad används melenas head till"}}},fp="14,179,17.327.0,22.331.0,20.167.0,30.123.0,51.210.0,50.167.0,54.221.0,27.165.0"}
P.entries["quest:93224"] = {n="Carved Centaur Totems",s="Captain Pentigast vid Nijel's Point söker snidade kentaurtotemer för att efterlikna deras mönster. Han hoppas att kopiorna kan hjälpa honom att skaffa sig ett övertag hos kentaurklanerna.",h="Captain Pentigast vid Nijel's Point söker snidade kentaurtotemer för att efterlikna deras mönster.",kw={"captain pentigast","snidade kentaurtotemer","snidat trä","kentaur","kentaurklaner","desolace","nijel's point","totemer"},sec={{t="En byteshandel i trä",b="Captain Pentigast vid Nijel's Point ser kentaurklanernas snidade träföremål som ett sätt att skaffa sig ett övertag. Båda klanerna tvekar inför att ta emot hjälp från utomstående, särskilt icke-kentaurer. Han ber dig ta med prover på deras mönster så att han kan ordna liknande sniderier."}},faq={{q="Varför vill Captain Pentigast ha totemen?",a="Han hoppas kunna ordna liknande sniderier och skaffa sig ett övertag hos kentaurklanerna.",al={"varför totem","pentigasts plan"}},{q="Varför tvekar kentaurklanerna inför att ta emot hjälp?",a="Båda klanerna tvekar inför att ta emot hjälp utifrån, särskilt från icke-kentaurer.",al={"varför tar kentaurer inte emot hjälp","kentaurer misstror utomstående"}},{q="Vad är kentaurernas totem gjorda av?",a="De lokala kentaurerna idkar byteshandel med snidat trä.",al={"totemens material","snidat trä"}},{q="Var väntar Captain Pentigast?",a="Captain Pentigast är vid Nijel's Point.",al={"var är pentigast","kapten nijel's point"}}},fp="21,158,17.267.0,43.81.0,50.88.0,36.42.0,34.38.0"}
P.entries["quest:93225"] = {n="Carved Centaur Totems",s="Gurda Wildmane tror att snidade totemer kan hjälpa henne vinna Gelkis- eller Magramklanens gunst. Hon behöver äkta totemer från kentaurklaner runt om i Desolace.",h="Gurda Wildmane tror att snidade totemer kan hjälpa henne vinna Gelkis- eller Magramklanens gunst.",kw={"snidade kentaurtotemer","kentaurvaluta","desolace","gelkis","ghost walker post","gurda wildmane","magram"},sec={{t="En kentaurvaluta",b="Gurda Wildmane vid Ghost Walker Post har sett kentaurklaner träffas för att handla utanför sina bosättningar. Hon har sett dem använda snidade totemer som valuta. Nu tror hon att en stor bunt kan beveka Gelkis eller Magram, men totemerna hon har snidat kanske inte verkar äkta. Därför ber hon dig hämta äkta exemplar åt henne."}},faq={{q="Vad vill Gurda ha?",a="Gurda Wildmane ber dig hämta äkta snidade kentaurtotemer åt henne.",al={"gurdas begäran","vad behöver wildmane"}},{q="Varför behöver hon snidade totemer?",a="Gurda tror att en stor bunt kan hjälpa henne vinna Gelkis- eller Magramklanens gunst.",al={"vad ska totemerna användas till","varför totemer"}},{q="Var använder kentaurerna totemerna?",a="Gurda har sett kentaurer från olika klaner träffas utanför sina bosättningar och handla med snidade totemer som valuta.",al={"kentaurhandel","var totemer"}},{q="Var hittar jag Gurda Wildmane?",a="Gurda Wildmane finns vid Ghost Walker Post.",al={"gurdas plats","wildmane vid ghost walker"}},{q="Vilka kentaurklaner är inblandade?",a="Gurda hoppas att en bunt totemer ska vinna antingen Gelkis eller Magrams gunst.",al={"gelkis magram","vilka klaner"}}},fp="21,157,18.320.0,21.69.0,32.79.0,32.118.0,32.39.0,33.84.0"}
P.entries["quest:93227"] = {n="Buying Friendship: Gelkis",s="För fred med Gelkis-centaurerna krävs värdefulla gåvor som visar din välvilja. Du tar en säck med totem till Gelkis Village i sydvästra Desolace för att sluta en allians med deras kvartermästare.",h="För fred med Gelkis-centaurerna krävs värdefulla gåvor som visar din välvilja.",kw={"köpa vänskap gelkis","fred med centaurerna","desolace","gelkis-centaurer","gelkis village","magram","totemsäck"},sec={{t="Gåvor i sydväst",b="Gelkis-klanen håller mark långt sydväst i Desolace, trots att de är färre än sina rivaler i Magram-klanen. Spejare får veta lite från deras läger, men centaurerna förblir en dominerande kraft i de torra ödemarkerna. Att ta en säck med totem till kvartermästaren i Gelkis Village är ett direkt sätt att vinna deras välvilja. Klanen kräver minst neutral status innan de tar emot fredliga inviter."}},faq={{q="Vem tar emot totemen i Gelkis Village?",a="Du tar säcken med totem till kvartermästaren i Gelkis Village. Även bland primitiva centaurer sköter en klanförvaltare sådana gåvor.",al={"vem får totemen","mottagare av gelkisgåvan","vem tar emot säcken"}},{q="Hur står sig Gelkis mot Magram-klanen?",a="Spejare rapporterar att betydligt färre Gelkis än Magram strövar omkring i ödemarkerna. Trots sitt mindre antal förblir klanen en av de dominerande centaurstyrkorna i Desolace.",al={"gelkis jämfört med magram","är gelkis svaga","gelkis befolkning"}},{q="Varför lämna en säck med totem till Gelkis?",a="När du lämnar säcken med totem vinner du Gelkis-klanens välvilja. Värdefulla totem hjälper till att säkra fred med deras hövdingar.",al={"syftet med totemsäcken","varför ge totem","fred med gelkis"}},{q="Var ligger Gelkis Village?",a="Gelkis Village ligger långt sydväst i Desolaces ödemarker.",al={"var finns gelkis","gelkis village läge","hitta gelkis"}},{q="Vem kan lämna totemen till Gelkis?",a="Klanen förhandlar inte med svurna fiender. Du behöver minst neutral status hos Gelkis-centaurerna innan du närmar dig deras by med gåvan.",al={"kan vem som helst lämna in den","gelkis statuskrav","rykteskrav"}}},fp="25,224,26.400.0,42.143.0,45.166.0,43.133.0,32.71.0,39.153.0"}
P.entries["quest:933"] = {n="Crown of the Earth",s="Crown of the Earth är ett Alliance-uppdrag som Corithras Moonrage ger i Dolanaar. Han ber dig hämta vatten från månbrunnen nära Pools of Arlithrien, ett område som hotas allt mer av vansinniga Gnarlpine-furbolger. När du slutför uppdraget får du veta hur Arch Druid Fandral Staghelm samlade nattalverna för att resa Teldrassil efter Malfurion Stormrages försvinnande.",h="Crown of the Earth är ett Alliance-uppdrag som Corithras Moonrage ger i Dolanaar.",kw={"corithras moonrage","dolanaar","fandral staghelm","gnarlpine","malfurion stormrage","pools of arlithrien","tourmaline phial"},ang={["class:Druid"]="Cenarion Circles splittring under Fandral Staghelms ledarskap blir tydligare när Corithras berättar om det desperata försöket att återfå den forntida odödligheten.",["race:NightElf"]="Den här delen av din resa förklarar den omstridda politiska drivkraft som ledde till att Teldrassil skapades efter Malfurions plötsliga försvinnande."},sec={{t="En farlig månbrunn",b="Corithras Moonrage ber dig ta en turmalinflaska till en månbrunn sydost om ingången till Darnassus, vid stränderna kring Pools of Arlithrien. Resan är långt ifrån lugn. De en gång fridfulla Gnarlpine-furbolgerna har plötsligt gripits av våldsam vrede. De överfaller resande och trakasserar Sentinels patruller i hela området. Tidiga rapporter avfärdade det som enstaka skärmytslingar, men hotet har vuxit och hemsöker nattalvernas nya hem."},{t="Fandral Staghelms ambition",b="När du lämnar över den fyllda flaskan berättar Corithras viktig historia om Teldrassils skapelse. Efter det tredje kriget försvann Shan'do Malfurion Stormrage och lämnade Cenarion-druiderna utan ledare och splittrade. I hans frånvaro tog Arch Druid Fandral Staghelm över ledarskapet. Staghelm övertygade de äldstes krets i Darkshore om att nattalverna inte hade råd att sörja sysslolösa. De behövde återfå sin förlorade odödlighet och läka sin civilisation genom att plantera ett enormt nytt världsträd."}},faq={{q="Var finns månbrunnen i det här uppdraget?",a="Månbrunnen ligger sydost om huvudingången till Darnassus, vid Pools of Arlithriens södra stränder.",al={"månbrunnen vid arlithrien","månbrunnens plats","var fyller man flaskan"}},{q="Varför anfaller Gnarlpine-furbolgerna?",a="Gnarlpine-folket var traditionellt ett fridfullt björnmänniskosläkte, men ett mörkt, tanklöst raseri har nyligen drabbat dem över hela Teldrassil. Sentinels avfärdade först de tidiga angreppen som enstaka händelser, men fördärvet har spridit sig snabbt och gjort dem till ett ständigt hot mot närliggande bosättningar och patruller.",al={"furbolger vansinniga","gnarlpine aggressiva","varför anfaller furbolgerna"}},{q="Vad hände med Malfurion Stormrage?",a="Shan'do Malfurion Stormrage försvann utan förklaring efter det tredje kriget. Än i dag vet varken Cenarion-druiderna eller nattalvernas ledare vad som blev av honom.",al={"var är malfurion","vad hände med stormrage","malfurion försvunnen"}},{q="Vem beslutade att plantera Teldrassil?",a="När Malfurion var försvunnen tog Arch Druid Fandral Staghelm på sig att vägleda druiderna. Han övertalade de äldstes krets i Darkshore att stödja resandet av ett nytt världsträd. Han hävdade att det var nödvändigt för kaldorei att återuppbygga sitt samhälle och återfå odödligheten de förlorat när Nordrassil förstördes.",al={"vem skapade teldrassil","staghelm världsträd","varför växte teldrassil"}}},fx={f2628340={q="Varför vill Corithras Moonrage att det här ska göras?",a="Corithras Moonrage undersöker Teldrassils heliga månbrunnar för att bedöma och vårda Världsträdets hälsa. Medan han vägleder dig genom ritualerna berättar han också om Teldrassils oroliga historia och hur trädet planterades. Han hoppas att du ska förstå både ditt folks heliga plikter och de oroande tecken som sprider sig i ert nya hem.",al={"varför vill corithras ha vatten från månbrunnarna","corithras motiv","varför crown of the earth"}},["21308da4"]={q="Vad används Filled Tourmaline Phial till?",a="Kärlet innehåller rent vatten från månbrunnen nära Pools of Arlithrien. Corithras behöver prover från Teldrassils olika månbrunnar för att övervaka vattnet som ger Världsträdet näring och utföra ritualerna som bevarar landets andliga balans medan fördärvet växer.",al={"filled tourmaline phials syfte","varför fylla tourmaline phial","tourmaline phial från månbrunnen"}}},fp="18,201,19.359.0,27.473.0,37.111.0,41.247.0,37.151.0,32.269.0"}
P.entries["quest:93317"] = {n="Crab Season",s="Crab Season är ett brådskande insamlingsuppdrag på Zephras, där du ska samla sällsynta Windsong crawlers under deras korta årliga säsong. Eftersom kultisternas senaste aktivitet gjort stränderna vid Windsong Lake farliga kallas äventyrare in för att trotsa både fientliga inkräktare och aggressiva kräftdjur.",h="Crab Season är ett brådskande insamlingsuppdrag på Zephras, där du ska samla sällsynta Windsong crawlers...",kw={"crab season","krabbor","kultistaktivitet","kött från windsong crawlers","windsong crawlers","windsong lake","zephras"},ang={["profession:Cooking"]="Det är viktigt för de lokala förråden på Zephras att samla säsongens kött från Windsong crawlers, men färska fångster från sjön måste hanteras varsamt eftersom djuren är aggressiva."},sec={{t="En flyktig skörd",b="Vid stränderna kring Windsong Lake på Zephras öppnar ett kort skördefönster under bara några veckor varje år. De inhemska Windsong crawlers dyker upp i stora antal längs sötvattnets stränder och bifloder, och erbjuder en sällsynt köttskörd åt den som är djärv nog att samla dem innan årets möjlighet går förlorad."},{t="Faror vid vattnet",b="Den senaste tidens ökade kultistaktivitet kring Zephras har stört vardagslivet och utsatt lokala samlare för fara. När fientliga kultister patrullerar vildmarken har det blivit alldeles för riskabelt för ensamma samlare att ta sig till Windsong Lake. Den korta säsongen riskerar att gå till spillo om inte dugliga äventyrare vågar sig ut till stränderna och de argsinta krabborna."}},faq={{q="Vad är Windsong crawlers?",a="Windsong crawlers är en aggressiv krabbart som bara finns i Windsong Lake på ön eller landmassan Zephras. De kan bara skördas under ett kort säsongsfönster på några veckor varje år.",al={"vad är windsong crawlers","windsongkrabbor","sjökrabbor zephras"}},{q="Varför måste krabborna skördas just nu?",a="Windsong crawlers kan bara samlas in under ett kort säsongsfönster på några veckor varje år. Om de inte skördas innan fönstret stängs går möjligheten att samla deras kött förlorad resten av året.",al={"varför samla crawlers nu","crawlersäsongens tidsfönster","varför krabbor bara en kort tid"}},{q="Varför kan den lokala skördaren inte samla krabborna själv?",a="Den senaste kultistaktiviteten i området har gjort det för farligt att ta sig till Windsong Lake för vanlig insamling. Lokala samlare kan därför inte nå stränderna innan det korta skördefönstret stängs.",al={"varför kan lokalbor inte samla krabbor","kultister zephras","kultistaktivitet windsong"}},{q="Var finns Windsong crawlers?",a="Windsong crawlers håller till längs stränderna kring Windsong Lake på Zephras och längs närliggande sammanbindande flodbankar.",al={"var finns windsong crawlers","var finns krabbor på zephras","windsong lakes stränder"}},{q="Är Windsong crawlers farliga att jaga?",a="Trots sitt anspråkslösa utseende som enkla sötvattenskräftdjur är Windsong crawlers märkbart stridslystna och mycket elakare än de ser ut. De kniper gärna efter alla som försöker samla deras kött.",al={"är windsong crawlers farliga","krabbornas temperament","elaka krabbor"}},{q="Vad används köttet från Windsong crawlers till?",a="Köttet från de insamlade krabborna är eftertraktad säsongsmat från sjön, tillgänglig under de få veckor då krabborna finns att samla. Det är så uppskattat att lokalbor anlitar äventyrare när kultister blockerar vägarna.",al={"vad används köttet från windsong crawlers till","varför samla krabbkött","vad används crawlerkött till"}}},fp="11,149,18.180.0,19.235.0,27.135.0,48.144.0,58.125.0,34.105.0,40.74.0,39.163.0"}
P.entries["quest:93318"] = {n="WANTED: Vulgara the Insatiable",s="WANTED: Vulgara the Insatiable är en belöning från Peacekeepers för att fälla ett monstruöst bevingat odjur som terroriserar Shen'dar Highlands. Constable Aonda har utfärdat kontraktet, som kräver att äventyrare dödar den glupska vuldrenen och överlämnar hennes huvud till Danarii Bellowveil.",h="WANTED: Vulgara the Insatiable är en belöning från Peacekeepers för att fälla ett monstruöst bevingat odjur...",kw={"belöning","constable aonda","danarii bellowveil","peacekeepers","shen'dar highlands","shen'dar village","vuldren","vulgara","vulgara the insatiable"},sec={{t="Highland Scourge",b="En officiell efterlysning från Constable Aonda i Peacekeepers pekar ut Vulgara the Insatiable som en omedelbar fara för höglandet. Den väldiga bevingade vuldrenen har terroriserat resenärer och lokala bosättningar från sitt näste sydväst om Shen'dar Village. Därför uppmanar lokala myndigheter prisjägare att sätta stopp för hennes skräckvälde."},{t="Pressade beskyddare",b="Peacekeepers är redan belägrade från flera håll och kämpar för att hantera hot från regionala banditer och en skum kult som verkar i området. Om Vulgara elimineras minskar den hårda pressen på lokalbefolkningen. Då förblir himlen över Shen'dar trygg medan försvararna fokuserar på att skydda samhället."}},faq={{q="Vem är Vulgara the Insatiable?",a="Vulgara the Insatiable är en väldig, bevingad vuldren som terroriserar Shen'dar Highlands. Lokala myndigheter kallar henne höglandets gissel. Hennes glupska aptit och våldsamma närvaro utgör en allvarlig fara för resenärer och närliggande bosättningar.",al={"vem är vulgara","vulgara bakgrund","vad är vulgara för slags monster"}},{q="Vem utfäste belöningen för Vulgara?",a="Constable Aonda i de lokala Peacekeepers utfärdade den officiella belöningen för Vulgara för att skydda invånarna. Jägarna ska överlämna bevis på odjurets död till Danarii Bellowveil.",al={"vem utfärdade belöningen för vulgara","vem vill döda vulgara","constable aonda"}},{q="Var hittar man Vulgara the Insatiable?",a="Vulgara strövar enligt uppgift på en höjd sydväst om Shen'dar Village i Shen'dar Highlands.",al={"vulgaras plats","var dyker vulgara upp","hitta vulgara"}},{q="Vem är Danarii Bellowveil?",a="Danarii Bellowveil är rådgivaren som hanterar utbetalningen av belöningen. Danarii är hårt pressad av kringliggande banditer och kultister, men granskar Vulgara's avhuggna huvud och betalar ut den utlovade belöningen.",al={"vem är danarii bellowveil","lämna in till danarii"}},{q="Vad är en vuldren för slags varelse?",a="En vuldren är ett farligt, rovgirigt bevingat odjur som finns i höglandet. Vulgara är ett ovanligt stort och våldsamt exemplar vars omättliga jakt hotar lokala bosättningar.",al={"vad är en vuldren","vuldren odjur"}},{q="Vilka andra hot plågar Shen'dar Highlands?",a="Förutom rovdjur som Vulgara är Peacekeepers i Shen'dar Highlands hårt ansträngda av aktiva hot från en fast förankrad kult och höglandsbanditer som ger sig på lokalbefolkningen.",al={"vilka hot finns i shendar highlands","kult och banditer i shendar"}}},fp="30,204,20.264.0,20.212.0,30.207.0,33.155.0,42.81.0,26.180.0,35.164.0,49.174.0"}
P.entries["quest:93319"] = {n="Pilfered Windstones",s="Pilfered Windstones är ett lokalt uppdrag på Zephras där du återtar livsviktiga stulna resurser från Highlands Bandits. Dessa vindstenar förvaras i reserv för nödsituationer och är avgörande för vardagen, men de lokala ordningsvakterna är upptagna med kultisthot och kan inte själva rensa ut tjuvarna.",h="Pilfered Windstones är ett lokalt uppdrag på Zephras där du återtar livsviktiga stulna resurser från...",kw={"aonda","banditgrotta","falaath village","highlands bandits","pilfered windstones","shen'dar highlands","vindstenar","zephras"},ang={["class:Rogue"]="Highlands Bandits använder simpel list för att stjäla lagrade vindstenar, men skickliga skurkar känner igen hur tjuvar utnyttjar en bosättning som är upptagen med kultisthot.",["race:Skyborne"]="Livet på Zephras är starkt beroende av vindstenar för den dagliga överlevnaden, så det är avgörande att försvara och återta förråden för att hålla de lokala bosättningarna vid liv."},sec={{t="Zephras stulna förråd",b="På ön Zephras är vindstenar mer än märkliga artefakter – de är livsviktiga resurser för vardagen. Bosättningarna har nödförråd för att klara kriser. Men förråden började sina stadigt, och det var först när tillfångatagna banditer från norra Shen'dar Highlands upptäcktes med stenarna som mysteriet fick sin förklaring. Dessa ficktjuvar hade tydligen smugit sig in i de lokala förråden i flera månader och utnyttjat den bristande bevakningen för att stjäla så mycket de kunde bära."},{t="Överansträngt försvar och hot vid horisonten",b="Även om det verkar självklart att rensa ut den norra grottan står bosättningens ledare inför svåra val. Aonda, som ansvarar för byns försvar, avböjde att godkänna en moträd eftersom samhället har för få ordningsvakter för att avvara några. I söder blir kultisterna vid Falaath Village snabbt fler och utgör en allvarlig fara som tvingar vakterna att hålla sina poster. Eftersom ordningsvakterna är upptagna med kultisthotet faller det på självständiga äventyrare som vågar möta banditerna att återta de stulna vindstenarna."}},faq={{q="Vad används vindstenar till på Zephras?",a="På Zephras förlitar sig invånarna på vindstenar för sin vardag och överlevnad. Eftersom de är så viktiga för det dagliga livet försöker bosättningarna ha ett förråd undanstoppat för nödsituationer.",al={"vad används vindstenar till","varför behövs vindstenar","vindstenarnas syfte"}},{q="Vem stal vindstenarna?",a="Vindstenarna stals av Highlands Bandits, som håller till i en grotta i Shen'dar Highlands. När tillfångatagna banditer påträffades med stenarna insåg lokalbefolkningen att tjuvarna troligen hade brutit sig in i byns förråd i flera månader.",al={"vem stal vindstenarna","vem tog vindstenarna","vindstenstjuvar"}},{q="Var håller Highlands Bandits till?",a="Highlands Bandits har sitt läger i en grotta norr om bosättningen, i Shen'dar Highlands. Där samlar de stöldgods från byns förråd.",al={"var finns banditgrottan","highlands bandits plats","shendar-banditer"}},{q="Varför har byn inte rensat ut banditgrottan?",a="Aonda, som ansvarar för bosättningens försvar, valde att inte organisera en räd mot den norra grottan eftersom byn har så få ordningsvakter. Om de skickades bort skulle bosättningen bli sårbar för det växande antalet kultister vid Falaath Village i söder.",al={"varför anfaller de inte banditgrottan","varför anfaller aonda inte","byförsvar mot banditer"}},{q="Vilket hot finns vid Falaath Village?",a="Falaath Village ligger i söder och där ökar antalet kultister oroväckande snabbt. Deras växande närvaro utgör ett omedelbart hot som binder upp de lokala ordningsvakterna med att försvara hemmet i stället för att jaga banditer.",al={"vilket hot finns vid falaath village","kultister falaath","falaath-kultister"}},{q="Löser återtagandet av vindstenarna bosättningens brist?",a="De återtagna vindstenarna ger nödförråden tillfällig påfyllning, men lokalbefolkningen påpekar att störningarna i de större försörjningsrutterna fortfarande är ett akut problem. Om försörjningslinjerna inte säkras snart kommer bristen fortsätta att hota bosättningen.",al={"är vindstenarna säkra nu","zephras försörjningsrutter","är bristen på vindstenar löst"}}},fp="19,184,28.354.0,38.379.0,40.117.0,25.210.0,40.137.0,51.254.0,38.159.0,63.194.0"}
P.entries["quest:93320"] = {n="Tower Defense",s="Tower Defense skildrar en desperat kamp mot övermäktiga styrkor vid en befäst position. Medan försvararna vid fronten upprätthåller ett tillfälligt dödläge hotar den växande utmattningen att få försvaret att falla utan snabb hjälp.",h="Tower Defense skildrar en desperat kamp mot övermäktiga styrkor vid en befäst position.",kw={"försvarare","utmattning","befästning","utpost","belägring","dödläge","tower defense"},ang={["class:Warrior"]="Försvar mot numerärt överlägsna styrkor prövar uthålligheten lika mycket som skickligheten och kräver disciplinerade kämpar vid fronten för att förhindra en total kollaps."},sec={{t="Ett pressat försvar",b="Tower Defense kretsar kring en desperat kamp vid en befäst position under hårt angrepp. Garnisonen lyckas stå emot den första anstormningen, men fienden är fler och fortsätter att pressa sitt övertag. När de överlevande kämparna börjar bli utmattade blir den tillfälliga gränsen mellan överlevnad och nederlag allt skörare."},{t="Utmattningens hot",b="Trots att garnisonen håller en försvarslinje arbetar tiden emot den. Långvariga skärmytslingar mot övermäktiga styrkor tär stadigt på deras krafter och förvandlar striden till ett utmattningskrig. För att överleva belägringen behöver försvararna genast vidta en avgörande åtgärd och bryta dödläget innan linjerna brister."}},faq={{q="Vad handlar Tower Defense om?",a="Tower Defense är en brådskande försvarsinsats där försvararna kämpar för att hålla en position mot övermäktiga styrkor. Den närmaste försvarslinjen håller, men utmattning hotar att bryta försvaret om de inte hittar en avgörande motåtgärd.",al={"vad är tower defense","uppdraget tower defense","vad är det här för uppdrag"}},{q="Vilka strider försvararna mot?",a="Angriparna är fler än försvararna och pressar så hårt att de gradvis nöter ner garnisonen och tvingar fram ett spänt dödläge. Deras tillhörighet är inte känd; endast deras farliga numerära överläge är dokumenterat.",al={"vem anfaller i tower defense","vilka strider vi mot","fienden i tower defense"}},{q="Hur går det för försvararna just nu?",a="Försvararna börjar bli utmattade efter långvarig strid under obevekliga angrepp. Utan förstärkningar riskerar garnisonen att förlora mark mot de övermäktiga styrkorna, om de inte agerar snabbt och bryter dödläget.",al={"varför är försvararna trötta","dödläge vid tornet","stridens läge"}},{q="Avgör det striden att hålla linjen?",a="Att stå emot angreppet ger bara en tillfällig respit, inte en slutgiltig seger. Styrkorna på plats inser att utmattningen kommer att övermanna dem om ingen omedelbar plan bryter låsningen.",al={"vann vi tower defense","hur slutar tower defense","vad händer efter att vi hållit stånd"}},{q="Var utspelar sig försvaret?",a="Försvaret äger rum vid en befäst utpost under belägring, där styrkorna är hårt ansatta av de många fiendernas ständiga press.",al={"var finns tower defense","området tower defense","vilket torn är det här"}},{q="Vad krävs för att vända striden?",a="Försvararna måste snabbt utarbeta en strategi för att bryta belägringen och vända striden innan den utmattade frontlinjen ger vika för fiendens numerära överläge.",al={"vad måste göras härnäst","hur vinner man belägringen","bryta dödläget"}}},fp="13,156,21.221.0,23.219.0,28.152.0,31.143.0,44.155.0,41.131.0,35.135.0,32.94.0"}
P.entries["quest:93394"] = {n="Meeting the Magister",s="En kontakt bland Shen'dralar ber dig hitta Magister Kirandis i Shen'dralas tempel. Mötet gäller templets återställda pelare och din plats bland dess misstänksamma invånare.",h="En kontakt bland Shen'dralar ber dig hitta Magister Kirandis i Shen'dralas tempel.",kw={"kirandis","magister kirandis","mötet med magistern","pelare","shen'dralar","shen'dralas","tempel"},sec={{t="I templet",b="Den ståtliga byggnaden drar till sig din uppmärksamhet, och en kontakt bland Shen'dralar visar dig vägen till Magister Kirandis. Magistern är en gammal vän till den som skickade dig och kanske välkomnar dig. Shen'dralar kan vara misstänksamma, så du ombeds närma dig dem med respekt."},{t="Pelarna",b="När du har hittat Kirandis ser magistern att pelarnas kraft åter lyser. När de återvänder knyts Shen'dralar helt till Shen'dralas. Kirandis uppmanar dig att träffa templets invånare, vars misstänksamhet kanske lättar med tiden."}},faq={{q="Vem ska jag hitta?",a="Du ombeds leta reda på Magister Kirandis i Shen'dralas tempel.",al={"hitta kirandis","möte med magistern","kirandis tempel"}},{q="Var finns Magister Kirandis?",a="Magister Kirandis finns i Shen'dralas tempel.",al={"kirandis plats","var finns magistern","templet kirandis"}},{q="Vad har Kirandis för relation till den som skickade mig?",a="Kirandis är en gammal vän till kontakten bland Shen'dralar som skickade dig.",al={"kirandis vän","magisterns gamla vän"}},{q="Kommer Shen'dralar att välkomna mig?",a="Shen'dralar kan vara misstänksamma mot din närvaro, men du ombeds visa respekt.",al={"shen'dralar misstänksamma","kommer de att tycka om mig","shen dralar välkomna"}},{q="Vad har hänt med pelarna?",a="Deras kraft lyser åter, och Kirandis säger att detta knyter Shen'dralar helt till Shen'dralas.",al={"pelarnas kraft","tempelpelare","återställda pelare"}},{q="Vad ska jag göra efter mötet med Kirandis?",a="Kirandis uppmuntrar dig att träffa några av templets invånare, som kanske är misstänksamma till en början.",al={"träffa invånarna","vad göra efter kirandis","shen'dralas folk"}}},fp="20,180,13.266.0,10.221.0,26.75.0,27.54.0,42.66.0,32.86.0,32.92.0,40.88.0"}
P.entries["quest:934"] = {n="Crown of the Earth",s="Crown of the Earth är ett avgörande steg i Dolanaars uppdragskedja, där man undersöker plågorna som drabbar Teldrassil. Corithras Moonrage skickar äventyrare att hämta vatten från den heliga månbrunnen i The Oracle Glade. Resan avslöjar den oroande sanningen bakom världsträdets skapelse.",h="Crown of the Earth är ett avgörande steg i Dolanaars uppdragskedja, där man undersöker plågorna som drabbar...",kw={"alexstrasza","amethyst phial","corithras moonrage","fandral staghelm","odödlighet","månbrunn","nozdormu","the oracle glade","oracle tree","teldrassil"},ang={["class:Druid"]="För Cenarion Circle visar ett besök vid The Oracle Tree den ideologiska klyftan mellan Fandral Staghelms hänsynslösa ambitioner och den naturliga balans som Malfurion Stormrage traditionellt har bevarat.",["faction:Alliance"]="När man förstår Teldrassils bräckliga tillstånd blir det lättare att förstå den ihållande farsoten och galenskapen bland varelserna som plågar Alliansens nyaste huvudstadsområde.",["race:NightElf"]="Resan berör nattalvernas förhoppningar om Teldrassil efter Nordrassils offer under det tredje kriget."},sec={{t="The Oracle Glade",b="Corithras Moonrage visar resenärer vägen långt nordväst på Teldrassil, inbäddad under The Oracle Glades majestätiska trädkrona. Direkt under The Oracle Trees väldiga grenar ligger den första och mäktigaste månbrunnen som rests på ön. När sökare hämtar en Amethyst Phial med dess skimrande vatten får de möta den främsta helgedomen, där druiderna och själva trädet vakar över sitt nya hemlands hälsa."},{t="Den uteblivna välsignelsen",b="När Corithras får tillbaka flaskan till Dolanaar avslöjar han den mörka bristen i ärkedruiden Fandral Staghelms storslagna plan. Efter Nordrassils offer vid Mount Hyjal försökte Staghelm återställa nattalvernas odödlighet genom att plantera Teldrassil och be Drakflykterna om välsignelser. Men Nozdormu the Timeless One vägrade och tillrättavisade Staghelm för hans rena arrogans. Drottning Alexstrasza följde hans exempel och undanhöll Livsaspektens livsviktiga välsignelse. Därmed blev Teldrassils tillväxt instabil och bristfällig, och trädet blev sårbart för djup korruption."}},faq={{q="Var ligger månbrunnen i The Oracle Glade?",a="Månbrunnen ligger i nordvästra Teldrassil, strax norr om huvudvägen mot Darnassus. Den finns under The Oracle Trees väldiga grenar.",al={"var ligger oracle glade","oracle glade månbrunnens plats","oracle glades brunn"}},{q="Vem är Corithras Moonrage?",a="Corithras Moonrage är en nattalvsväktare som är stationerad i Dolanaar. Han leder unga försvarare genom Teldrassils grenar för att ta prover från månbrunnarna och berättar om trädets bristfälliga begynnelse.",al={"corithras","vem är corithras moonrage"}},{q="Återställde Teldrassil nattalvernas odödlighet?",a="Nej. Teldrassil ger nattalverna ett nytt hem, men deras odödliga liv har inte återställts efter Nordrassils offer under det tredje kriget.",al={"är nattalver odödliga","teldrassils odödlighet","lever alver för evigt igen"}},{q="Varför samlar man vatten från The Oracle Glade?",a="Månbrunnen under The Oracle Tree är öns första och mäktigaste brunn. När Corithras hämtar dess vatten kan han bedöma Teldrassils andliga och naturliga hälsa i grunden.",al={"varför hämta vatten från oracle glade","amethyst phials syfte"}}},fx={["28d6c4e0"]={q="Varför vill Corithras Moonrage att det här ska göras?",a="Corithras Moonrage vägleder dig genom Teldrassils heliga månbrunnar och berättar den sanna historien om det nya Världsträdet. Genom att skicka dig under grenarna vid The Oracle Tree för att hämta vatten från Teldrassils första och mäktigaste brunn ser han till att du själv får ta del av dess djupa visdom innan han avslöjar varför grenarna fortfarande är oroliga och saknar odödlighet.",al={"varför vill corithras ha vattnet","corithras motiv","varför skicka till oracle glade"}}},fp="18,174,16.321.0,19.520.1,43.152.0,26.190.0,45.139.0,62.156.0"}
P.entries["quest:93404"] = {n="Rot and Regret",s="Woodwyrd ber dig släcka lågan som tynger en uråldrig ande i Forlorn Gardens. Anden hänvisar dig till heligt vatten i Maraudon.",h="Woodwyrd ber dig släcka lågan som tynger en uråldrig ande i Forlorn Gardens.",kw={"uråldrig ande","earth song water","forlorn gardens","maraudon","mashan’she","rot och ånger","helig ravin","woodwyrd"},sec={{t="En andes börda",b="Den uråldriga anden säger att dess sista misstag binder den till den här platsen, där den fortfarande känner en låga i döden. Den ber dig söka efter rent vatten från en helig ravin på andra sidan Mashan’she. Platsen som nämns är Maraudon, och Woodwyrd väntar på Vial of Earth Song Water i Forlorn Gardens."}},faq={{q="Vem ber om vattnet?",a="Woodwyrd i Forlorn Gardens ber dig hämta tillbaka Vial of Earth Song Water åt den uråldriga anden.",al={"vem är woodwyrd","uråldrig ande","uppdragsgivare för rot och ånger"}},{q="Varför vill den uråldriga anden släcka lågan?",a="Anden säger att den tyngs av sitt sista misstag och fortfarande känner lågan i döden.",al={"varför släcka lågan","andens ånger","vad var dess misstag"}},{q="Var hittar jag det heliga vattnet?",a="Anden hänvisar dig till Maraudon, på andra sidan Mashan’she, för rent vatten från en helig ravin.",al={"var finns earth song water","vatten i maraudon","helig ravin"}},{q="Vilket vatten behöver Woodwyrd?",a="Woodwyrd ber dig hämta tillbaka Vial of Earth Song Water.",al={"vattenflaska","vilket föremål behöver woodwyrd","earth song-flaska"}}},fp="14,147,17.283.0,28.105.0,51.86.0,34.96.0,30.59.0"}
P.entries["quest:93406"] = {n="Unfrozen Deliveries",s="Innkeeper Vizzie behöver returposten till Mount Hyjal, men en tjuv länsade posten och flydde norr om Everlook. Breven ligger utspridda i de kalla kullarna, där yetis tros ha dödat tjuven.",h="Innkeeper Vizzie behöver returposten till Mount Hyjal, men en tjuv länsade posten och flydde norr om Everlook.",kw={"everlook","innkeeper vizzie","försvunnen post","mount hyjal","ofrysta leveranser","yetis i winterspring"},sec={{t="Utspridda i snön",b="Innkeeper Vizzie har fått problem med returposten till Mount Hyjal. För några dagar sedan genomsökte en tjuv utgående post i jakt på mynt och flydde sedan upp i kullarna norr om Everlook. Breven ligger utspridda över de snötäckta sluttningarna där yetis stryker omkring. Inga försändelser når berget förrän de försvunna breven har samlats in från vildmarken."}},faq={{q="Vem stal den utgående posten?",a="En tjuv länsade den utgående posten för bara några dagar sedan, troligen i jakt på mynt, och flydde sedan till de norra kullarna.",al={"vem stal posten","vem länsade posten","vem tog breven"}},{q="Vart tog den försvunna posten vägen?",a="Tjuven flydde till kullarna norr om Everlook, där yetis stryker omkring på de snötäckta sluttningarna.",al={"var är posten","vart tog tjuven vägen","var hittar man försvunnen post"}},{q="Vem vill ha tillbaka den försvunna posten?",a="Innkeeper Vizzie i Everlook behöver få tillbaka de försvunna breven innan någon returpost kan skickas till Mount Hyjal.",al={"vem behöver posten","vem vill ha tillbaka posten","vem tar emot posten i everlook"}},{q="Vart ska posten skickas?",a="De återfunna breven är returpost som ska skickas till Mount Hyjal när de har samlats in.",al={"varför ska posten till hyjal","vart ska returposten","leverans till mount hyjal"}},{q="Vad hände med tjuven i kullarna?",a="Tjuven kom aldrig tillbaka från kullarna, och Innkeeper Vizzie misstänker att yetis slet rånaren i stycken.",al={"vad hände med tjuven","dödade yetis tjuven","var är tjuven nu"}}},fp="19,215,21.361.0,28.117.0,33.83.0,36.115.0,30.87.0,40.99.0"}
P.entries["quest:93407"] = {n="A Thorn in the Paw",s="På Mount Hyjals topp behöver Tiala Whitemane säkra lägret utan sten eller timmer. Hon ber dig samla törnbusksfrön i skogen så att naturen själv kan växa till en skyddande mur.",h="På Mount Hyjals topp behöver Tiala Whitemane säkra lägret utan sten eller timmer.",kw={"naturens rikedom","hyjals försvar","mount hyjal","törnbuskar","törnen i tassen","törnbusksfrön","tiala whitemane"},ang={["class:Druid"]="Som druid är det naturligt för dig att forma vilda törnsnår till levande försvarsvallar och kalla på själva skogen att vakta helig mark.",["profession:Herbalism"]="Som örtalchemist vet du hur man skördar frön från vilda törnsnår så att de kan slå rot och frodas som skyddande häckar."},sec={{t="Levande försvar",b="Tiala Whitemane behöver befästa sin utpost på Mount Hyjals topp, men hon har varken sten eller timmer till ordentliga barrikader. I stället hoppas hon att den uråldriga skogen ska ge henne levande försvarsvallar. Hon ber dig söka igenom skogarna efter vilda törnbuskar och samla deras frön. Med höjdernas naturmagi hoppas hon kunna odla täta snår som avskräcker alla som närmar sig."}},faq={{q="Vem ber om törnbusksfröna?",a="Tiala Whitemane ber om fröna på Mount Hyjals topp.",al={"vem ger törnen i tassen","vem vill ha törnbusksfröna","tiala whitemane hyjal"}},{q="Varför vill Tiala Whitemane ha törnbusksfrön?",a="Lägret saknar material till stenmurar eller timmerbarrikader. I stället kan täta törnbuskar ge ett naturligt skydd.",al={"varför samla törnbusksfrön","vad ska fröna användas till","varför törnbuskar"}},{q="Var kommer törnbusksfröna ifrån?",a="Du kan samla törnbusksfrön från de vilda buskar som växer utspridda i Mount Hyjals höglandsskogar.",al={"var finns törnbuskarna","törnbusksfrön plats","var hittar man frön i hyjal"}},{q="Hur ska försvararna skydda sig?",a="Tiala Whitemane tänker använda naturens kraft för att odla levande barrikader runt deras position på berget.",al={"hyjals försvar","varför bygga försvar i hyjal"}}},fp="18,195,15.398.0,29.64.0,42.141.0,35.98.0,42.119.0"}
P.entries["quest:93429"] = {n="Blood of My Blood",s="En släkting till Lost Ones ber dig att befria dem från lidandet i Fallow Sanctuary. Deras våld hotar dem som är kvar.",h="En släkting till Lost Ones ber dig att befria dem från lidandet i Fallow Sanctuary.",kw={"blod av mitt blod","fallow sanctuary","hat","släktingar","lost ones","lidande","våld"},sec={{t="En dyster begäran",b="I Fallow Sanctuary ber en av Lost Ones dig att skydda dem som fortfarande lever där. Lost Ones har blivit våldsamma och hatfulla, och deras släkting ser inget hopp om bot eller frälsning för dem. Du ombeds att göra slut på deras lidande genom att befria dem från misären."}},faq={{q="Vem ber om hjälp?",a="En av Lost Ones ber dig att skydda dem som är kvar i Fallow Sanctuary.",al={"vem ger uppdraget","vem ber om hjälp"}},{q="Varför fruktas Lost Ones?",a="Lost Ones i Fallow Sanctuary har blivit varelser präglade av våld och hat.",al={"varför är de farliga","lost ones våld"}},{q="Kan Lost Ones räddas?",a="Deras släkting tror att det inte finns någon bot eller frälsning för Lost Ones.",al={"kan de sona sina synder","finns det hopp för lost ones"}},{q="Varför ombeds du döda dem?",a="Deras släkting tror att Lost Ones lider och ber dig att göra slut på lidandet för att skydda dem som är kvar.",al={"varför döda lost ones","befria dem från misären"}}},fp="17,118,14.272.0,18.68.0,29.76.0,27.77.0,31.110.0"}
P.entries["quest:93430"] = {n="Taking the Bait Back",s="En tjuv har stulit Pelluks dyrbara fiskedrag direkt från linan. Han förlitar sig på redskapen för att föda lägret och vill att du letar upp varelsen vid de östra vattnen.",h="En tjuv har stulit Pelluks dyrbara fiskedrag direkt från linan.",kw={"fiskedrag","fiskare från lost ones","lost ones","lyckodrag","pelluk","ta tillbaka betet"},sec={{t="En avskuren lina",b="Pelluk fiskade i träsket när en varelse steg upp ur dyn, slet av linan och flydde med hans dyrbara drag. Han misstänker att en fiskare från Lost Ones tog det för att fiska längs stränderna österut. Utan redskapen kan han inte fånga mer fisk, och lägret riskerar att få slut på mat."}},faq={{q="Vem stal Pelluks lyckodrag?",a="En fiskare från Lost Ones steg upp ur dyn, slet av Pelluks fiskelina och flydde med draget för att använda det längs stränderna österut.",al={"vem stal draget","vem tog pelluks bete","pelluks tjuv"}},{q="Var finns tjuven?",a="Lost Ones fiskar längs stränderna rakt öster om Pelluks läger.",al={"var finns draget","var finns lost ones","plats för fiskare från lost ones"}},{q="Varför behöver Pelluk få tillbaka sitt lyckodrag?",a="Pelluk förlitar sig på draget för att fånga fisk, och han fruktar att lägret svälter utan sin vanliga fångst.",al={"varför behöver pelluk draget","pelluk svälter","lyckodragets betydelse"}}},fp="20,180,10.285.0,30.129.0,29.72.0,45.103.0"}
P.entries["quest:93443"] = {n="Lost Shipping Crate",s="Friz Frazzlesparks Lost Shipping Crate har en varning om att inte öppna den utan tillsyn. Etiketten säger att du ska lämna tillbaka den till Powderfuse Port i Riverglades.",h="Friz Frazzlesparks Lost Shipping Crate har en varning om att inte öppna den utan tillsyn.",kw={"lådans etikett","lådans karta","friz frazzlespark","lost shipping crate","powderfuse port","riverglades"},sec={{t="Lådans etikett",b="En handskriven etikett på Lost Shipping Crate nämner Friz Frazzlespark och Powderfuse Port. Den varnar för att manipulera eller öppna lådan utan tillsyn och ber dig sedan lämna tillbaka den till Friz vid hamnen i Riverglades."}},faq={{q="Vem äger Lost Shipping Crate?",a="Etiketten anger att Friz Frazzlespark äger lådan.",al={"lådans ägare","vem den tillhör"}},{q="Vart ska jag ta lådan?",a="Etiketten säger att du ska lämna tillbaka Lost Shipping Crate till Friz Frazzlespark vid Powderfuse Port i Riverglades.",al={"var lådan ska lämnas tillbaka","lådans leverans"}},{q="Vad står det på etiketten?",a="Den handskrivna etiketten varnar för att manipulera eller öppna lådan utan tillsyn och säger att du ska lämna tillbaka den till Friz Frazzlespark.",al={"lådans varning","vad som står på etiketten"}},{q="Vad visas på lådans karta?",a="Etikettens karta markerar en sydöstlig kust norr om ett slarvigt ritat tempel omgivet av vatten och bevingade varelser.",al={"lådans karta","vad som finns på kartan"}}},fp="19,171,19.230.0,33.57.0,30.115.0,24.136.0,35.121.0"}
P.entries["quest:93461"] = {n="Welcome to Shen'dar Village",s="Welcome to Shen'dar Village presenterar resenärer för en avlägsen fristad präglad av forntida Highborne-släkter och pyrande rivalitet mellan fraktioner. Även om High Order och Windshapers upprätthåller en yttre vapenvila i bosättningen, dröjer bittra spänningar kvar strax utanför bygränsen.",h="Welcome to Shen'dar Village presenterar resenärer för en avlägsen fristad präglad av forntida...",kw={"coriella calmbreeze","high order","highborne","huvudloge","rathiril sunlance","shendar village","windshapers"},ang={["class:Mage"]="Magiker med band till Highborne-traditioner känner igen sitt ursprung i High Order, vars äldste som Rathiril Sunlance åtnjuter respekt i Shen'dar.",["race:NightElf"]="Shen'dar Village är genomsyrat av det forntida Highbornes arv och släkter och påminner oroväckande om stoltheten och det magiska arvet som splittrade alvsamhället."},sec={{t="En skör härd",b="Shen'dar Village är en skör fristad där olika alvfraktioner lever sida vid sida under en spänd vapenvila. Nykomlingar med spår av Highborne-blod skickas genast för att visa sin vördnad för High Orders äldste, Rathiril Sunlance, i bosättningens huvudloge och ordna logi hos den lokala värdshusvärden, Coriella Calmbreeze."},{t="Vildmarkens rivalitet",b="Under den vardagliga rutinen med logi och ströjobb pyr friktionen mellan två framträdande grupper: High Order och Windshapers. Även om de strikt upprätthåller hövligheten på bytorget, där de är i trygghet, råder fientlighet fritt i den omgivande vildmarken, där gamla rivaliteter avgörs utom nyfikna ögons räckhåll."}},faq={{q="Vad är syftet med uppdraget Welcome to Shen'dar Village?",a="Welcome to Shen'dar Village är ett introduktionsuppdrag som gör nyanlända äventyrare bekanta med bosättningens nyckelpersoner och sköra fred. Du får i uppdrag att träffa Rathiril Sunlance, den bofasta äldsten i High Order, och Coriella Calmbreeze på byns värdshus innan du tar dig an lokala uppgifter.",al={"vad är det här för uppdrag","information om welcome to shendar village","introduktion till shendar village"}},{q="Vem är Rathiril Sunlance?",a="Rathiril Sunlance är en äldste i High Order som bor i Shen'dar Village. Han finns i byns huvudloge, strax runt hörnet från den första uppdragsgivaren, och är en viktig kontakt för dig med Highborne-ätt eller ärenden som rör High Order.",al={"vem är rathiril sunlance","äldste i high order","var finns rathiril"}},{q="Vem är Coriella Calmbreeze?",a="Coriella Calmbreeze driver det lokala värdshuset i Shen'dar Village. Hon tar hand om resenärer med mat, logi och förnödenheter inför färder ut i den omgivande vildmarken.",al={"vem är coriella calmbreeze","värdshusvärd i shendar","var får man logi i shendar"}},{q="Vad ligger bakom spänningen mellan High Order och Windshapers?",a="Spänningen mellan High Order och Windshapers är stor på grund av deras olika traditioner och ambitioner. De två fraktionerna lyckas leva sida vid sida med hövlighet inom Shen'dar Villages gränser, men återhållsamheten upphör vid byns utkant, där konflikterna ofta övergår i våld ute i vildmarken.",al={"high order mot windshapers","varför finns det spänningar","konflikt i byn"}},{q="Vad är det för utseende hos High Order som uppdragsgivaren nämner?",a="De som härstammar från Highborne är kända för ett särskilt glitter i ögonen, ett magiskt arv som genast avslöjar för uppmärksamma lokalbor att de har High Orders utseende.",al={"high orders utseende","highborne-ögon","highborne-glitter"}},{q="Är Shen'dar Village skyddat från konflikter?",a="Inne i Shen'dar Village upprätthålls hövligheten strikt mellan rivaliserande fraktioner som High Order och Windshapers. Utanför bosättningen råder däremot ingen sådan fred, och öppen fientlighet blossar ofta upp utom vakande ögons räckhåll.",al={"är shendar säkert","våld utanför shendar","faror i vildmarken"}}},fp="27,199,16.267.0,22.230.0,61.211.0,25.249.0,27.156.0,63.230.0,56.157.0,39.171.0"}
P.entries["quest:93464"] = {n="The Visiting Mage",s="En draenei vid The Harborage ber dig söka upp Azore, en mänsklig magiker i Desolace. Hans kunskap om draenethyst kan hjälpa dem som inte helt förstår dess kraft.",h="En draenei vid The Harborage ber dig söka upp Azore, en mänsklig magiker i Desolace.",kw={"azore","desolace","draenei","draenethyst","the harborage","mänsklig magiker"},sec={{t="En magiker att minnas",b="Vid The Harborage minns en draenei hur hen drev bort Azore när han kom från Desolace. Den mänsklige magikern fruktade draenethysts kraft och varnade för att den inte fick hamna i fel händer. Nu verkar hans kunskap värd att söka upp, även om draenein medger att de här inte helt förstår kristallen. Du ombeds hitta Azore i Desolace."}},faq={{q="Vem är Azore?",a="Azore är en mänsklig magiker från Desolace som en gång kom till The Harborage. Han fruktade draenethysts kraft.",al={"vem är azore","besökande magiker","draenethystmagiker"}},{q="Vad är draenethyst?",a="Draenethyst är helig för draeneierna vid The Harborage och hjälper dem att behålla förståndet, även om de inte helt förstår den.",al={"draenethyst","draeneikristall","vad är draenethyst"}},{q="Varför letar jag efter Azore?",a="Draeneierna vid The Harborage tror att Azores kunskap om draenethyst kan vara värdefull.",al={"hitta azore","varför söka magikern","magiker i desolace"}},{q="Vart tog Azore vägen?",a="Azore är i Desolace.",al={"azores plats","var är magikern","hitta den besökande magikern"}},{q="Varför drev draeneierna bort Azore?",a="De drev bort Azore för att skydda det som var deras.",al={"varför skicka bort azore","azore bortkörd","magiker vid the harborage"}}},fp="17,159,17.336.0,13.98.0,20.119.0,27.88.0,19.21.0,37.49.0"}
P.entries["quest:93465"] = {n="Notes on Draenethyst",s="Azore Aldamort skickar dig efter Gimashis anteckningar om draenethyst. Häxmästarna i Burning Blade studerar ämnet, som kom från andra sidan Dark Portal.",h="Azore Aldamort skickar dig efter Gimashis anteckningar om draenethyst.",kw={"azore aldamort","burning blade","the dark portal","draenethyst","gimashi","anteckningar","häxmästare"},sec={{t="Gimashis anteckningar",b="Azore Aldamort säger att Gimashis anteckningar kan förklara vad Burning Blade har lärt sig om draenethyst. Gimashi är en häxmästare vars torn står i en ravin åt sydost. Du ombeds ta hennes anteckningar tillbaka till Azore innan Burning Blade kan använda sin kunskap om ämnet för mörkare syften."}},faq={{q="Vad är draenethyst?",a="Draenethyst är ett ämne från andra sidan Dark Portal.",al={"draenethyst betydelse","vad är draenethyst","draenethyststen"}},{q="Vem är Gimashi?",a="Gimashi är en häxmästare i Burning Blade som studerar draenethyst.",al={"vem är gimashi","häxmästaren gimashi","gimashis anteckningar"}},{q="Varför vill Azore ha Gimashis anteckningar?",a="Azore vill ha Gimashis anteckningar för att ta reda på vad Burning Blade vet om draenethyst.",al={"varför anteckningar","azore draenethyst","vad behöver azore"}},{q="Var finns Gimashi?",a="Gimashi finns högst upp i sitt torn i en ravin åt sydost.",al={"gimashis plats","var finns tornet","ravin åt sydost"}},{q="Varifrån kom draenethyst?",a="Draenethyst kom från andra sidan Dark Portal.",al={"draenethyst ursprung","ämne från dark portal","varifrån kommer draenethyst"}}},fp="20,157,15.300.0,20.55.0,15.56.0,36.84.0,17.65.0,32.45.0"}
P.entries["quest:935"] = {n="Crown of the Earth",s="”Crown of the Earth” markerar höjdpunkten i månbrunnsriterna över hela Teldrassil. När det insamlade vattnet överlämnas till Arch Druid Fandral Staghelm i Darnassus blir oron över världsträdets bristfälliga, oblessade existens tydlig.",h="”Crown of the Earth” markerar höjdpunkten i månbrunnsriterna över hela Teldrassil.",kw={"alexstrasza","cenarion enclave","corithras moonrage","crown of the earth","darnassus","fandral staghelm","månbrunn","nozdormu","teldrassil"},ang={["class:Druid"]="När du bär månbrunnsvatten till Cenarion Circles ärkedruid ställs du direkt inför Fandral Staghelm. Mötet visar den djupa politiska och andliga splittring som har gripit druidernas ledarskap medan Malfurion är borta.",["faction:Alliance"]="För den större Alliansen är Darnassus en mäktig huvudstad full av uråldriga mysterier, men den fördärvade vildmarken runt staden visar att även nattalverna möter inre faror på sin egen heliga mark.",["race:NightElf"]="Riten blottlägger den stilla oron under ditt nya hem: Teldrassil planterades i högmod utan drak aspekternas välsignelser, och den växande sjukdomen påminner om hur skör ditt folks nya början är."},sec={{t="Ett bristfälligt ursprung",b="Teldrassil restes efter det tredje kriget för att ge nattalverna ett nytt hem och återställa deras förlorade odödlighet. Men de stora aspekterna Alexstrasza och Nozdormu undanhöll sina välsignelser och vägrade godkänna trädets tillkomst. Utan deras gudomliga beskydd har Teldrassil drabbats av en smygande sjukdom, som får bisarra varelser att välla fram ur grenverket och tidigare fridfulla furbolgstammar att sjunka ner i vansinne."},{t="Leverans till ärkedruiden",b="Corithras Moonrage ber unga äventyrare samla vatten från månbrunnar över hela ön för att övervaka och lindra grenverkets åkommor. Corithras samlar proverna i ett enda kärl och skickar budbäraren djupt in i Darnassus, till Cenarion Enclave. Där sitter Arch Druid Fandral Staghelm, Teldrassils skapare, som ser den smygande korruptionen som en besvärlig börda han ensam måste lösa, inte som ett tecken på högmod."}},faq={{q="Varför vill Fandral Staghelm ha vattnet från månbrunnarna?",a="Fandral Staghelm lät samla prover från månbrunnar över hela Teldrassil för att studera och bekämpa korruptionen som sipprar genom världsträdet. Som ledaren som drev på trädets plantering bär han ansvaret för att hitta en lösning på de märkliga bestarna och de vansinniga furbolgerna som oroar trädkronan.",al={"varför fandral vill ha vatten","varför fandral behöver kärlet","vad vattnet ska användas till"}},{q="Varför plågas Teldrassil av korruption och vansinniga bestar?",a="Till skillnad från det uråldriga världsträdet Nordrassil planterades Teldrassil utan välsignelser från Alexstrasza Livgivaren eller Nozdormu den Tidlöse. Eftersom det nya trädet nekades dessa urdrakars beskydd är dess tillväxt i grunden bristfällig, vilket låter märkliga maligniteter slå rot i jorden och förvrida djurlivet och furbolgerna i närheten.",al={"varför teldrassil är sjukt","korruption i teldrassil","varför furbolgerna är galna"}},{q="Var finns Arch Druid Fandral Staghelm?",a="Arch Druid Fandral Staghelm bor i Darnassus, i Cenarion Enclave. Du hittar honom högst upp i den centrala druidpaviljongen, med utsikt över enklavens heliga lundar.",al={"var finns fandral","fandral staghelms plats","hur hittar man fandral"}},{q="Vem är Corithras Moonrage?",a="Corithras Moonrage är en nattalv stationerad i Dolanaar som låter unga äventyrare fylla flaskor vid Teldrassils månbrunnar. Han häller flaskornas innehåll i ett enda kärl och skickar budbärare för att leverera det till ärkedruiden Staghelm i Darnassus.",al={"vem ger crown of the earth","corithras roll","corithras moonrage"}},{q="Vad händer när du har slutfört uppdraget?",a="När du levererar det fyllda kärlet till Fandral Staghelm avslutas den huvudsakliga uppdragskedjan för Crown of the Earth i Teldrassil. Staghelm tar emot vattnet ganska kort och riktar sedan uppmärksamheten tillbaka mot de större hoten mot nattalvernas hemland.",al={"fortsättning på crown of the earth","vad händer efter crown of the earth 6","nästa uppdrag efter crown of the earth"}},{q="Varför är Fandral Staghelm så avvisande när han tar emot kärlet?",a="Fandral Staghelm är ökänd för att vara stolt, otålig och tyngd av den överväldigande uppgiften att leda Cenarion Circle medan Malfurion Stormrage är borta. Han ser administrativa bakslag och långsamma budbärare med förakt och känner att Teldrassils överlevnad helt vilar på hans egna axlar.",al={"varför fandral är otrevlig","fandrals personlighet","är fandral alltid butter"}}},fx={d62362b9={q="Varför vill Corithras Moonrage att kärlet förs till Fandral?",a="Corithras oroar sig djupt för sjukdomen som sprider sig i Teldrassil. Eftersom Världsträdet växte utan Aspekternas, Alexstrasza och Nozdormus, livsviktiga välsignelser har märkliga bestar stigit upp ur jorden och tidigare fredliga furbolger blivit våldsamt vansinniga. Corithras tror att Arch Druid Fandral Staghelm aktivt söker ett botemedel mot det spridande fördärvet. Därför samlar han skyndsamt vattenproverna du hämtat bland grenarna och skickar dig direkt till Darnassus med dem.",al={"corithras motiv","varför skicka vatten från månbrunnen","varför vill corithras att det här ska göras"}},["01febe86"]={q="Varför skickar Corithras Moonrage dig i stället för att själv gå?",a="Corithras är kvar i Dolanaar för att sköta lokala angelägenheter och hålla uppsikt över de oroande avvikelserna som stör Teldrassils nedre grenar. Du har själv färdats till de olika månbrunnarna och hämtat vattenflaskorna, vilket visar din uthållighet och hängivenhet. Genom att anförtro dig det samlade kärlet kan Corithras hålla uppsikt över Dolanaar och samtidigt se till att Fandral Staghelm får proverna i Darnassus utan ytterligare dröjsmål.",al={"varför skicka spelaren till fandral","varför jag, corithras","varför levererar inte corithras kärlet själv"}}},fp="18,209,16.368.0,26.368.1,51.257.0,58.324.0,45.161.0,26.239.0,41.201.1,64.240.0"}
P.entries["quest:93552"] = {n="Harvesting Windstones",s="Harvesting Windstones är ett uppdrag som erbjuds av Dalia the Collector i Thendal Grove på Zephras Isle. När de uråldriga elementarkrafterna som håller ön vid liv sakta försvagas, har råa vindstenar blivit en viktig magisk bränslekälla. Äventyrare skickas runt i lunden för att samla kristallkluster av vindsten innan deras kraft går förlorad.",h="Harvesting Windstones är ett uppdrag som erbjuds av Dalia the Collector i Thendal Grove på Zephras Isle.",kw={"förankringspelare","dalia","dalia the collector","thendal grove","vindelementarer","vindstenskluster","vindstenar","zephras isle"},ang={["class:Mage"]="För dem som utövar arkana konster är den koncentrerade elementarkraften i vindstenar en tydlig påminnelse om hur sköra magiska ekosystem blir när deras elementarkällor försvinner.",["profession:Mining"]="Att samla råa vindstenar är en introduktion till att samla värdefulla mineraler och kristaller i Zephras Isles otämjda vildmark."},sec={{t="En ö som försvagas",b="Zephras Isle är starkt beroende av kvarvarande vindmagi för att hålla sig vid liv, men öns naturliga försvar försvagas. För flera århundraden sedan försvann vindelementarerna som levde på ön tillsammans med de lokala alverna helt. Sedan de försvann har den omgivande magin som håller landet och de stora förankringspelarna uppe sakta men säkert avtagit. För invånarna i Thendal Grove kräver överlevnad att varje möjlig reserv av rå energi säkras."},{t="Vindstenarnas värde",b="Vindstenar är lysande blå kristallformationer som finns naturligt utspridda i Thendal Grove. I deras sköra skal finns tät, koncentrerad vindmagi från svunna tider. De är ingen outsinlig lösning, men de utgör en pålitlig och ovärderlig källa till magisk näring och nytta för öns alver. Därför är insamlingen av råa kluster en livsviktig daglig uppgift."}},faq={{q="Vad är vindstenar?",a="Vindstenar är blå kristallfyndigheter runt Thendal Grove som innehåller koncentrerad, rå vindenergi. Alverna på Zephras Isle samlar dem som en viktig magisk bränslekälla.",al={"rå vindsten","vindstenskluster","blå kristaller"}},{q="Vem är Dalia the Collector?",a="Dalia är en alv som samlar in resurser och håller till i Thendal Grove på Zephras Isle. Hon organiserar insamlingen av viktiga råvaror, särskilt vindstenar, för att hjälpa till att fylla på öns krympande magiska reserver.",al={"dalia","dalia zephras","samlaren dalia"}},{q="Varför försvagas magin på Zephras Isle?",a="För flera århundraden sedan försvann vindelementarerna som levde tillsammans med de lokala alverna. Utan deras fortsatta närvaro har förtrollningen som de stora förankringspelarna ingjutit i ön sakta runnit bort.",al={"zephras förlorar magi","magin försvagas zephras","förankringspelare"}},{q="Vart tog vindelementarerna vägen?",a="Deras öde är fortfarande ett mysterium. Det enda man vet är att de försvann för flera århundraden sedan och lämnade ön att sakta förbruka sina återstående elementarreserver.",al={"saknade elementarer","var finns vindelementarerna","elementarerna försvann"}},{q="Vad är förankringspelarna?",a="De stora förankringspelarna är uråldriga strukturer på Zephras Isle, genomsyrade av kraftfull magi som håller landet vid liv. Nu när elementarerna är borta försvagas deras livgivande krafter gradvis.",al={"stora förankringspelarna","förankringspelarnas historia"}},{q="Var hittar du råa vindstenar?",a="Råa vindstenar finns utspridda över landskapet i Thendal Grove på Zephras Isle och ser ut som lysande blå kristallformationer.",al={"vindstenarnas plats","kristaller i thendal grove"}}},fx={["0a83a06c"]={q="Varför vill Dalia the Collector ha Windstone Clusters?",a="Dalia söker Windstone Clusters eftersom Zephras Isle är beroende av deras magiska kraft för att bestå. Sedan vindelementarerna försvann för århundraden sedan har den livgivande magi som en gång gav ön näring sakta avtagit. För de lokala alverna, vars liv och kultur fortfarande är tätt knutna till arkansk energi, är de här kristalliserade vindarna en livsviktig och pålitlig energikälla som ersätter det de försvagade förankringspylons inte längre kan ge.",al={"varför vill dalia ha windstones","dalia the collectors motiv","varför samla windstones"}},["33ac4299"]={q="Vad används Windstone Clusters till?",a="Windstone Clusters innehåller vindarnas råa, koncentrerade energi. Eftersom de uråldriga magiska förankringspylons på Zephras Isle långsamt förlorar sin kraft använder öns invånare de kristalliserade klustren som en pålitlig alternativ energikälla. Den håller samhället vid liv och bevarar dess viktiga band till magisk energi.",al={"vad windstone cluster används till","vad är windstone cluster till för","varför windstone clusters"}}},fp="21,166,15.327.0,23.276.0,20.168.0,27.214.0,40.178.0,33.152.0,27.191.0,33.122.0"}
P.entries["quest:93584"] = {n="Cult Closure",s="En druid ber dig skingra Wild Kings anhängare nära Well of Eternity. Deras iver hindrar arbetet med att vårda Nordrassil och skydda Well.",h="En druid ber dig skingra Wild Kings anhängare nära Well of Eternity.",kw={"blackthorne adepts","kultens slut","druider","nordrassil","well of eternity","wild king","wild-branded cultists"},ang={["class:Druid"]="Som druid möter du anhängare som en gång svor samma eder som de som vårdar Nordrassil."},sec={{t="En delad ed",b="En druid nära Well of Eternity skickar dig för att bekämpa Blackthorne Adepts och Wild-branded Cultists. De svor en gång samma eder som druiderna som vårdar Nordrassil, men deras iver hindrar nu arbetet och hotar Well. Landets försvarare fruktar att de också kan slå till när ett större anfall börjar."},{t="En svår plikt",b="Striderna gör druiden bekymrad. Druider har tvingats strida mot sina egna, och förhoppningen är att konflikten snart kan lösas."}},faq={{q="Vilka är Wild Kings anhängare?",a="De följer Wild King och hindrar arbetet med att vårda Nordrassil och skydda Well of Eternity.",al={"wild kings kultister","vilka är wild kings anhängare"}},{q="Varför strider druider mot varandra?",a="Wild Kings anhängare svor en gång samma eder som druiderna som vårdar Nordrassil, men deras iver hindrar nu arbetet och hotar Well.",al={"druider som strider mot druider","varför strida mot de egna"}},{q="Vad händer nära Well of Eternity?",a="Wild Kings anhängare hindrar arbetet med att vårda Nordrassil och skydda Well.",al={"kult vid well of eternity","vad händer vid well of eternity"}},{q="Vilka är Blackthorne Adepts?",a="De är några av Wild Kings anhängare nära Well of Eternity.",al={"blackthorne adepts","blackthorne-kultister"}},{q="Vilka är Wild-branded Cultists?",a="De är några av Wild Kings anhängare nära Well of Eternity.",al={"wild-branded","wild-kultister"}}},fp="12,148,14.300.0,11.143.1,34.107.0,39.154.0,44.89.0,31.67.0,34.67.0"}
P.entries["quest:93585"] = {n="This Light of Mine",s="Father Tuttle söker trygg passage över en farlig väg för att ta kontakt med draenei vid Harborage. Den mänsklige prästen hoppas vinna Alliance ett fäste genom Church of the Holy Lights läror.",h="Father Tuttle söker trygg passage över en farlig väg för att ta kontakt med draenei vid Harborage.",kw={"alliance-fäste","church of the holy light","draenei","father tuttle","the harborage","holy light"},ang={["class:Priest"]="Father Tuttle delar din hängivenhet åt Holy Light, men hans nedlåtande antaganden om draenei hotar själva bron han hoppas bygga.",["faction:Alliance"]="Alliance har ingen närvaro i dessa länder, och Father Tuttle hoppas att Church of the Holy Light ska ge Stormwind ett välkommet fäste vid Harborage."},sec={{t="Ett tronsändebud",b="Father Tuttle står nära en bro och hoppas föra Church of the Holy Lights tro till draenei vid Harborage. Alliance har inget inflytande i dessa träsk, och han tror att han kan öppna dörren för sitt folk genom att föra deras tro till lokalbefolkningen. Men vilda fränder stryker omkring på vägen framför honom, och han behöver din eskort för att nå bosättningen levande."},{t="Ett bittert välkomnande",b="Mottagandet vid Harborage är betydligt kyligare än prästen hade väntat sig. De överlevande draenei ser Father Tuttle som en arrogant dåre som behandlar deras tragiska historia som ren okunnighet. De skildes från Ljuset genom våld, och även om de avvisar prästen med avsky låter de dig stanna så länge du visar respekt."}},faq={{q="Vem är Father Tuttle?",a="Father Tuttle är en mänsklig präst som skickats av Church of the Holy Light för att ta fredlig kontakt med draenei vid Harborage.",al={"vem är father tuttle","vem ber om hjälp","father tuttle"}},{q="Varför söker Father Tuttle upp Harborage?",a="Father Tuttle hoppas introducera draenei för Church of the Holy Light och vinna välvilja för Alliance, som för närvarande saknar fäste i området.",al={"varför till harborage","kyrkans uppdrag","father tuttles syfte"}},{q="Varför behöver prästen en eskort?",a="Vägen bortom bron är full av fientliga, vilda draeneifränder som hotar alla som försöker nå fristaden.",al={"varför behöver tuttle skydd","fara på vägen","vad hotar tuttle"}},{q="Vad är Harborage?",a="Harborage är en bosättning för överlevande draenei som har genomlidit en våldsam brytning med sitt förflutna och Ljuset.",al={"vad är harborage","harborage-bakgrund"}}},fp="18,213,17.351.0,16.333.1,21.138.0,43.161.0,35.118.0,22.117.0"}
P.entries["quest:936"] = {n="Assisting Arch Druid Runetotem",s="Cenarion Circle i Thunder Bluff söker erfarna äventyrare till ett forskningsprojekt som leds av Hamuul Runetotem. Du ombeds tala med honom på Elder Rise.",h="Cenarion Circle i Thunder Bluff söker erfarna äventyrare till ett forskningsprojekt som leds av Hamuul...",kw={"hjälpa arch druid runetotem","cenarion circle","elder rise","hamuul runetotem","forskning","thunder bluff"},sec={{t="En uppmaning att tala",b="Cenarion Circle söker din hjälp med ett forskningsprojekt i Thunder Bluff. Hamuul Runetotem leder arbetet, men detaljerna är inte kända för den som hänvisar dig dit. Tala med Arch Druid Hamuul Runetotem på Elder Rise."}},faq={{q="Vem leder forskningen?",a="Arch Druid Hamuul Runetotem leder Cenarion Circles forskningsprojekt.",al={"vem leder det","hamuuls forskning","arch druid runetotem"}},{q="Var kan jag tala med Hamuul?",a="Hamuul Runetotem finns på Elder Rise i Thunder Bluff.",al={"var finns hamuul","elder rise plats","tala med runetotem"}},{q="Vad handlar forskningen om?",a="Cenarion Circle behöver hjälp med ett viktigt forskningsprojekt, men detaljerna är inte kända för den som hänvisar dig till Hamuul.",al={"forskningsdetaljer","vilken forskning","cenarion-projekt"}},{q="Vem ber om hjälp?",a="Cenarion Circle i Thunder Bluff söker erfarna äventyrare som kan hjälpa till med forskningsprojektet.",al={"vem behöver hjälp","cenarion circles förfrågan","varför är jag här"}}},fp="30,162,15.219.0,28.78.0,30.55.0,27.126.0,23.97.0"}
P.entries["quest:93601"] = {n="Passing the Blame",s="En kvinna säger att quilboar stal hennes gåva och skyller på dem för trädgårdens förfall. Hon skickar dig norrut till Valley of Bones för att söka upp en quilboar av betydelse vid Bristleback Retreat.",h="En kvinna säger att quilboar stal hennes gåva och skyller på dem för trädgårdens förfall.",kw={"bristleback retreat","trädgård","skjuta över skulden","quilboar","valley of bones","kvinnans gåva"},sec={{t="En trädgård i fara",b="En kvinnas trädgård är dömd att dö, och hon håller quilboar ansvariga. Hon säger att de tog hennes gåva och skickar dig norrut in i Valley of Bones. Vid Bristleback Retreat ska du söka upp en quilboar av betydelse."}},faq={{q="Vem säger att quilboar stal hennes gåva?",a="En kvinna säger att quilboar tog hennes gåva och skyller på dem för trädgårdens förfall.",al={"vem skyller på quilboar","kvinnans gåva","quilboar stal den"}},{q="Vart ska jag gå?",a="Kvinnan skickar dig norrut in i Valley of Bones, till Bristleback Retreat.",al={"var ligger dalen","vart ska jag gå","bristleback retreat"}},{q="Vad ska jag leta efter vid Bristleback Retreat?",a="Du ska söka upp en quilboar av betydelse vid Bristleback Retreat.",al={"vem ska hittas","quilboar av betydelse","vad är målet"}},{q="Varför skyller kvinnan på quilboar?",a="Hon säger att quilboar stal hennes gåva och är orsaken till att hennes trädgård är dömd att dö.",al={"varför quilboar","varför skylla på dem","trädgården dör"}}},fp="17,184,17.220.0,37.81.0,14.75.0,45.70.0,38.77.0"}
P.entries["quest:93604"] = {n="Agamaggan's Blood",s="Kog'thug the Brave vill ha ett särskilt blodprov från Razorfen Downs. Blodet han söker skiljer sig från det som finns i Razorfen Kraul.",h="Kog'thug the Brave vill ha ett särskilt blodprov från Razorfen Downs.",kw={"agamaggan","agamaggan blod","bristleback retreat","desolace","kog'thug","razorfen downs","razorfen kraul","virulent blood"},sec={{t="Ett annat prov",b="I Bristleback Retreat i Desolace ber Kog'thug the Brave dig hämta Virulent Blood of Agamaggan från Razorfen Downs. Blodet i Razorfen Kraul duger inte; han behöver provet från Downs."}},faq={{q="Vad vill Kog'thug ha?",a="Kog'thug the Brave ber dig hämta Virulent Blood of Agamaggan från Razorfen Downs.",al={"kogthug vill ha","vilket blod behöver han"}},{q="Var hittar jag blodet?",a="Det efterfrågade Virulent Blood of Agamaggan finns i Razorfen Downs.",al={"var finns blodet","agamaggan blod plats"}},{q="Fungerar blodet från Razorfen Kraul?",a="Nej. Kog'thug säger att Blood of Agamaggan i Razorfen Kraul inte räcker.",al={"razorfen kraul blod","fel agamaggan blod"}},{q="Vem ber om blodet?",a="Kog'thug the Brave i Bristleback Retreat i Desolace ber om blodet.",al={"vem vill ha det","kogthugs uppdrag"}}},fp="17,141,18.202.0,24.86.0,26.63.0,40.77.0,28.73.0"}
P.entries["quest:93644"] = {n="Tattered Journal",s="En skadad dagbok som hittas nära Shen'dralas leder dig till dess författare, Evenshade. De ord som saknas kan fortfarande vara viktiga för honom.",h="En skadad dagbok som hittas nära Shen'dralas leder dig till dess författare, Evenshade.",kw={"skadad dagbok","evenshade","förlorad dagbok","mordent","återställa dagboken","shen'dralas","sliten dagbok"},sec={{t="Ett namn finns kvar",b="Nära Shen'dralas finns en dagbok med slitna sidor som knappt går att läsa. Bland de suddiga bokstäverna står ett efternamn tydligt: Evenshade. Författaren kan finnas i närheten, och dagbokens återstående ord är den enda ledtråden."},{t="Dagbokens öde",b="Mordent känner igen dagboken som sin, trots att århundraden gått sedan han förlorade den. Texten är borta, men han minns vad den innehöll och håller den kunskapen för sig själv. Han låter dig försöka återställa dagboken, om sidorna finns kvar."}},faq={{q="Var hittades dagboken?",a="Dagboken hittades nära Shen'dralas.",al={"var dagboken finns","slitna dagbokens plats"}},{q="Vem skrev dagboken?",a="Namnet som finns kvar i dagboken pekar ut Evenshade som författaren.",al={"dagbokens författare","evenshades dagbok"}},{q="Varför leta efter Evenshade?",a="Efternamnet Evenshade står i dagboken, och författaren kan finnas någonstans i Shen'dralas.",al={"hitta evenshade","dagbokens efternamn"}},{q="Kan du läsa dagboken?",a="Det mesta av dagbokens innehåll har gått förlorat, och de återstående bokstäverna är svåra att urskilja.",al={"oläslig dagbok","dagbokens innehåll"}},{q="Vad säger Mordent om dagboken?",a="Mordent känner igen den som sin förlorade dagbok, men säger att texten är borta.",al={"mordents dagbok","vem äger dagboken"}},{q="Kommer Mordent att berätta vad som stod där?",a="Mordent minns vad dagboken innehöll, men vill inte tala om det högt.",al={"dagbokens innehåll","mordents hemlighet"}}},fp="16,124,14.231.0,18.250.1,28.39.0,22.71.0,23.88.0,25.96.0,40.72.0,36.85.0"}
P.entries["quest:93663"] = {n="Lost in Transit",s="Dar ber dig hitta en försvunnen goblinbudbärare och hans leverans till Harborage. Förlusten hotar hans rykte som handelsman.",h="Dar ber dig hitta en försvunnen goblinbudbärare och hans leverans till Harborage.",kw={"crocolisk","dar","draenei","goblinbudbärare","the harborage","försvunnen under färd","leverans","handel"},sec={{t="En försvunnen leverans",b="Dar byter extra förnödenheter med draenei vid Harborage mot en del av deras fångst. Nu har hans goblinbudbärare inte återvänt med en leverans. Dar befarar att en crocolisk kan ha dödat honom, men varorna är viktiga för hans affärer. Du ombeds söka nära vattnet längs vägen och ta leveransen till Harborage."}},faq={{q="Vem är Dar?",a="Dar byter extra förnödenheter med draenei vid Harborage mot en del av deras fångst.",al={"dar","vem skickade leveransen","goblinhandlare"}},{q="Vem är den försvunna budbäraren?",a="Dar skickade en goblinbudbärare med sin senaste leverans, men budbäraren återvände aldrig.",al={"försvunnen goblin","var är budbäraren","goblinbudbärare"}},{q="Vart skulle leveransen?",a="Leveransen var avsedd för draenei vid Harborage.",al={"leveransens destination","vart ska den levereras","leverans till harborage"}},{q="Varför måste Dar få leveransen återfunnen?",a="Dar säger att hans rykte som handelsman står på spel om leveransen inte hittas och levereras.",al={"varför hitta leveransen","dars rykte","varför spelar det roll"}},{q="Var ska jag leta efter budbäraren?",a="Dar ber dig leta nära vattnet längs vägen.",al={"var ska man söka","budbärarens plats","försvunnen under färd var"}}},fp="15,130,18.328.0,11.84.0,27.83.0,29.56.0,37.88.0,36.53.0"}
P.entries["quest:93680"] = {n="Key to the City",s="Magus Wordeen Voidglare i Tarren Mill vill veta mer om Kirin Tor, vars stad Archimonde förstörde och som nu har återuppbyggt Dalaran alldeles intill Dark Lady. Du ska genomsöka Kirin Tors läger efter något som kan föra in Horde i staden utan att någon märker det.",h="Magus Wordeen Voidglare i Tarren Mill vill veta mer om Kirin Tor, vars stad Archimonde förstörde och som nu...",kw={"archimonde","burning legion","dalaran","smutsig nyckel","kirin tor","nyckel till kloakerna","tarren mill","wordeen voidglare"},sec={{t="Den återuppbyggda staden",b="Alliansen hade en gång en armé av magiker, Kirin Tor, men den demoniska Burning Legion visade sig vara starkare. I ett enda slag jämnade ärkedemonen Archimonde deras stad med marken, och de överlevande blev rotlösa vagabonder. Nu har de återuppbyggt Dalaran alldeles intill Dark Lady. Magus Wordeen Voidglare i Tarren Mill vill veta mer och skickar dig till deras läger för att leta efter något, till exempel en uråldrig bok eller en hemlig relik, som kan föra in Horde i staden utan att någon märker det. Det du kommer tillbaka med är en smutsig Dalaran-nyckel till kloakerna."},{t="Wordeens svar",b="När Wordeen får se en nyckel till kloakerna säger han att det lyckligtvis är någon annan som ska använda den. Det finns arbete att göra innan den är säker att använda."}},faq={{q="Vem ger uppdraget Key to the City?",a="Magus Wordeen Voidglare i Tarren Mill.",al={"vem ger key to the city","uppdragsgivare för key to the city","var startar jag key to the city"}},{q="Varför är Horde intresserade av Dalaran?",a="Kirin Tor, vars stad Archimonde förstörde, har återuppbyggt Dalaran alldeles intill Dark Lady. Wordeen vill veta mer och behöver ett sätt att ta sig in utan att någon märker det.",al={"varför dalaran","varför hålla koll på dalaran","vad gör magikerna"}},{q="Vilket föremål ska du hitta?",a="En Dalaran-nyckel till kloakerna, en smutsig nyckel som finns i Kirin Tors läger.",al={"vad ska jag hämta åt wordeen","vad är nyckeln","föremålet key to the city"}}},fp="15,277,16.543.0,16.136.1,42.40.0,39.159.0,31.69.0"}
P.entries["quest:937"] = {n="The Enchanted Glade",s="I The Oracle Glade på nordvästra Teldrassil kämpar Sentinel Arynia Cloudsbreak för att skydda The Oracle Tree från aggressiva Bloodfeather-harpior. Efter att en utsänd budbärare på väg till Darnassus dödats kallas försvarare in för att slå tillbaka mot harpiornas bon och återta deras bälten som bevis.",h="I The Oracle Glade på nordvästra Teldrassil kämpar Sentinel Arynia Cloudsbreak för att skydda The Oracle Tree...",kw={"arynia cloudsbreak","bloodfeather","darnassus","harpier","the oracle glade","the oracle tree","sentinel","teldrassil","the enchanted glade"},ang={["class:Druid"]="Druider hyser stor vördnad för de kännande uråldringarna; att rensa bort harpiorna som hotar The Oracle Tree hjälper till att bevara gläntans naturliga balans.",["faction:Alliance"]="Att hjälpa Sentinels att säkra Teldrassils heliga lundar stärker banden till nattalvernas ledare i närbelägna Darnassus.",["race:NightElf"]="Att försvara världsträdets uråldriga andar och skydda Sentinels från harpiors vanhelgande är en högtidlig plikt för varje kaldorei."},sec={{t="En glänta under belägring",b="The Oracle Glade är en av Teldrassils heliga tillflyktsorter, centrerad kring ett kolossalt, uråldrigt exemplar som kallas The Oracle Tree. Sentinel Arynia Cloudsbreak skickades dit med en eskort av krigare för att vaka över denna vördnadsvärda gren. Tyvärr har vilda Bloodfeather-harpior trängt in i hålrummen, byggt bon över hela den omgivande trädkronan och hotar alla som närmar sig."},{t="Avbruten förbindelse med Darnassus",b="Spänningarna nådde sin kulmen när The Oracle Tree försökte skicka en budbärare till huvudstaden Darnassus med en brådskande rapport. Budbäraren hann aldrig förbi grenarna; harpierna överföll och dödade kuriren innan rapporten kunde lämna gläntan. Som svar har Arynia gett lokala äventyrare i uppdrag att decimera flocken och hämta Bloodfeather-bälten för att hejda den framryckande flocken."},{t="En kallelse från trädet",b="När det omedelbara hotet från de närliggande bona har minskat reagerar själva det uråldriga trädet. The Oracle Tree fäller en bit av sin förtrollade bark och söker ett sändebud som kan överlämna dess budskap till kaldoreiernas högsta ledare."}},faq={{q="Varför anfaller harpierna The Oracle Glade?",a="Bloodfeather-klanen har täta bon över norra Teldrassil. I The Oracle Glade har de omringat The Oracle Tree, vaktar sina boplatser ursinnigt och anfaller alla som försöker färdas till eller från den heliga platsen.",al={"harpier i the oracle glade","varför bloodfeather anfaller","harpier vid the oracle tree"}},{q="Vem är Sentinel Arynia Cloudsbreak?",a="Arynia Cloudsbreak är en Sentinel-officer som är stationerad tillsammans med en liten förtrupp i The Oracle Glade. Hennes främsta uppdrag är att försvara The Oracle Tree mot de omgivande harpiorna och återupprätta kontakten med Darnassus.",al={"arynia cloudsbreak","vem ger uppdraget the enchanted glade","cloudsbreaks historia"}},{q="Vad hände med budbäraren som skickades till Darnassus?",a="Budbäraren som skickades med en rapport från The Oracle Tree till Darnassus överfölls och dödades längs gläntans stigar av Bloodfeather-harpior innan hen nådde säkerhet.",al={"budbärare från the oracle tree","död budbärare darnassus"}},{q="Vad är The Oracle Tree?",a="The Oracle Tree är en väldig, kännande uråldring med rötter i The Oracle Glade. Den vakar över världsträdets grenar och förmedlar sin visdom och sina varningar till nattalvernas ledare.",al={"the oracle tree teldrassil","vem är the oracle tree"}},{q="Vilka bevis kräver Sentinel Cloudsbreak?",a="Sentinel Cloudsbreak kräver sex Bloodfeather-bälten från de dödade harpiorna som konkret bevis på att deras boplatser runt gläntan har decimerats.",al={"uppdraget bloodfeather belt","hur många bälten","bevis för uppdraget"}},{q="Vad händer efter att harpierna decimerats?",a="När det omedelbara området har säkrats fäller The Oracle Tree en bit av sin egen bark och öppnar en direkt kommunikationsväg så att en äventyrare kan föra dess sedan länge försenade budskap mot Darnassus.",al={"nästa uppdrag efter the enchanted glade","vad gör the oracle tree härnäst"}}},fx={["2b035f45"]={q="Varför vill Sentinel Arynia Cloudsbreak att det här ska göras?",a="Sentinel Arynia Cloudsbreak skickades ut med en liten styrka av Sentinels för att försvara det heliga Oracle Tree. Harpyor har byggt bon över hela gläntan och trängt in försvararna. De har till och med slaktat en kurir som skickades till Darnassus med viktiga rapporter. Arynia kan inte lämna sin försvarspost obevakad, så hon behöver en äventyrare som angriper bona direkt och driver tillbaka flocken innan gläntan övermannas.",al={"varför döda harpyorna","arynia cloudsbreaks motiv","varför skydda oracle tree"}},["164cdda3"]={q="Vilka är Bloodfeather-harpyorna som hotar gläntan?",a="Bloodfeather-harpyorna är våldsamma fågelliknande rovdjur som har slagit sig ned i de nordvästra delarna av Teldrassil. De är aggressiva och revirhävdande, och har byggt bon runt The Oracle Glade. De har skurit av kontakten med Darnassus och försöker driva bort eller slakta nattalvsväktarna som skyddar det uråldriga trädet.",al={"vilka är harpyorna","bloodfeather-harpyor i teldrassil","varför är harpyorna här"}},["3f052dc4"]={q="Varför kan inte Sentinel Cloudsbreak ta hand om harpyorna själv?",a="Sentinel Arynia Cloudsbreak leder bara en liten grupp Sentinels som är stationerade vid The Oracle Tree. Eftersom deras budbärare redan är död och harpyor omringar platsen måste hennes återstående trupper stanna kvar och skydda det heliga trädet från bakhåll. För att gå till angrepp mot harpyornas bon behövs dugliga, obundna resenärer som vågar ta sig in i fientliga nästen.",al={"varför behöver arynia min hjälp","varför kan sentinels inte döda harpyorna","varför jag till den förtrollade gläntan"}}},fp="19,252,19.296.0,26.290.0,23.172.1,43.181.0,35.187.0,46.175.0,24.178.0,45.149.0,39.146.1"}
P.entries["quest:93735"] = {n="The Broken Construct",s="The Broken Construct handlar om att hjälpa en hantverkare i Valanaar som kämpar med att reparera en sällsynt, skadad automat. Dessa maskiner skänktes ursprungligen av vindens bortgångna andar och bevarades av The Windshapers, vilket gör varje fungerande konstruktion som finns kvar till en ovärderlig relik från öns förflutna.",h="The Broken Construct handlar om att hjälpa en hantverkare i Valanaar som kämpar med att reparera en sällsynt...",kw={"hantverkare","the broken construct","konstruktion","riaani nightwind","valanaar","vindandar","windshapers"},ang={["class:Mage"]="Konstruktionerna och instrumenten som The Windshapers sköter drivs av känsliga magiska apparater, vilket gör dem särskilt intressanta för utövare av arkana konster.",["class:Shaman"]="Vindens andar skänkte ursprungligen konstruktionerna, vilket visar på det starka historiska bandet mellan lokalbefolkningen och elementarkrafterna innan andarna lämnade ön.",["profession:Engineering"]="Hantverkare som arbetar med uråldriga förtrollade konstruktioner ställs inför mekaniska och magiska utmaningar när de försöker hålla relikerna igång utan deras ursprungliga andliga beskyddare."},sec={{t="Vindandarnas gåvor",b="För länge sedan skänkte vindens andar magiska instrument, apparater och levande konstruktioner till öns folk. The Windshapers fick i uppgift att sköta dem och bevara dessa elementära gåvor genom generationerna. Men när andarna lämnade ön upphörde deras urgamla stöd, och de flesta underbara skapelser förföll tills bara en handfull fortfarande fungerade."},{t="En kris i Valanaar",b="I staden Valanaar skadades nyligen en av de sista fungerande konstruktionerna, vilket hotar att ytterligare minska öns redan krympande arv. Hantverkaren Riaani Nightwind skickades till stadens västra utkant för att undersöka maskinen och försöka reparera den, men dessa uråldriga apparater är så ömtåliga att de behöver all hjälp de kan få."}},faq={{q="Vilka är The Windshapers?",a="The Windshapers är lokala vårdare som historiskt har anförtrotts att sköta de magiska instrument, apparater och konstruktioner som vindens andar skänkte. Sedan andarna lämnade ön har deras uppgift blivit att varsamt bevara de få reliker som fortfarande fungerar.",al={"vilka är the windshapers","the windshapers i historien","vad gör the windshapers"}},{q="Varifrån kom de magiska konstruktionerna?",a="Vindens andar skänkte konstruktionerna till öns invånare, tillsammans med olika andra magiska instrument och apparater. Efter att vindandarna lämnat ön har mycket få av dessa skapelser fortsatt att fungera.",al={"vem byggde konstruktionerna","konstruktionernas ursprung","varifrån kom konstruktionerna"}},{q="Vem är Riaani Nightwind?",a="Riaani Nightwind är en hantverkare som skickats till västra Valanaar för att undersöka och reparera en av stadens få återstående fungerande konstruktioner efter att den skadats.",al={"vem är riaani nightwind","riaani nightwinds plats","hantverkare i valanaar"}},{q="Varför är de flesta av öns konstruktioner trasiga?",a="Konstruktionerna är beroende av gåvor och förtrollningar från vindens andar. När andarna lämnade ön avtog kraften och omsorgen som krävdes för att hålla dem igång, och i dag fungerar bara några få.",al={"varför är konstruktionerna trasiga","varför slutade konstruktionerna fungera","vindandarna lämnar ön"}},{q="Hur hänger Valanaar samman med konstruktionerna?",a="Valanaar är en bosättning där några av de sista fungerande konstruktionerna som vindens andar skänkte finns. En av dessa kvarvarande maskiner skadades nyligen i stadens västra del, vilket gör reparationer brådskande.",al={"vad är valanaar","staden valanaar","var finns konstruktionen"}},{q="Vad behöver göras i The Broken Construct?",a="Du ombeds ta dig till västra Valanaar för att hitta hantverkaren Riaani Nightwind och hjälpa till med att reparera den skadade konstruktionen.",al={"målet med uppdraget the broken construct","vad gör jag i the broken construct","vart ska jag gå i the broken construct"}}},fp="20,230,25.291.0,20.290.0,24.236.0,43.173.0,24.151.0,47.167.0,48.204.0,47.127.0"}
P.entries["quest:93736"] = {n="Unwelcome Spirits",s="Unwelcome Spirits är ett uppdrag åt Windshapers där du undersöker de oroande vindväsen som kallas ”hollows” och plötsligt dykt upp i Shadowgale Forest. Dessa märkliga väsen visade sig först efter att vindens sanna andar försvunnit, så Windshapers samlar in deras essenser för att förstå vad som drev bort de ursprungliga andarna.",h="Unwelcome Spirits är ett uppdrag åt Windshapers där du undersöker de oroande vindväsen som kallas ”hollows”...",kw={"hollows","shadowgale forest","vindväsen","unwelcome spirits","wind hollow essence","vindhollows","vindandar","windshapers"},ang={["class:Shaman"]="För den som står i förbindelse med elementarkrafter signalerar de naturliga vindandarnas avfärd och de tomma hollows ankomst en djup störning i traktens luftbalans."},sec={{t="De försvunna andarna",b="The Windshapers är upptagna av ett enda avgörande mysterium: vindandarnas plötsliga avfärd. När förbindelsen med dem har brutits lägger orden all sin kraft på att ta reda på varför de naturliga vindandarna övergav dem och vilka ritualer eller handlingar som kan locka dem tillbaka. I deras frånvaro har ett tomrum uppstått i traktens elementära atmosfär."},{t="Skuggor i Shadowgale",b="Efter vindandarnas avfärd dök en oroande ny närvaro upp i norr, i Shadowgale Forest. Iakttagare började se märkliga vindväsen som ofta kallas hollows. Före andarnas uttåg kände Windshapers inte till dessa varelser, som verkar nära knutna till de sanna luftandarnas plötsliga frånvaro. Att skingra dem och samla in deras kvarlämnade essenser ger bästa chansen att förstå deras natur."}},faq={{q="Vilka är Windshapers?",a="The Windshapers är en orden som vill förstå varför vindandarna övergav dem och upptäcka vad som kan göras för att få andarna tillbaka. Deras undersökningar kretsar kring märkliga fenomen som uppstod direkt efter att andarna försvann.",al={"vilka är windshapers","windshapers-fraktionen","vad vill windshapers"}},{q="Vad är hollows?",a="Hollows är en ovanlig sorts vindväsen som visade sig i Shadowgale Forest först efter att de ursprungliga vindandarna hade lämnat platsen. Man vet ännu lite om deras ursprung eller sanna natur, så forskare samlar in deras essenser för vidare studier.",al={"vad är hollows","vindhollows-lore","hollow-vindväsen"}},{q="Var ligger Shadowgale Forest?",a="Shadowgale Forest ligger i norr. Det är där de märkliga vindväsendena hollows har dykt upp i stort antal och slagit sig ner efter att traktens elementandar dragit sig undan.",al={"var ligger shadowgale forest","shadowgales läge"}},{q="Varför gav sig vindandarna av?",a="Den exakta orsaken till att vindandarna försvann är fortfarande okänd. Windshapers forskning syftar främst till att ta reda på varför de gav sig av och hitta ett sätt att återupprätta förbindelsen med dem.",al={"varför lämnade vindandarna","vart tog andarna vägen"}},{q="Varför samlar man in Wind Hollow Essences?",a="Wind Hollow Essences samlas in från skingrade hollows så att Windshapers kan undersöka deras lämningar. Genom att studera den fysiska essens som blir kvar hoppas de förstå vad som gav upphov till varelserna efter att andarna hade lämnat platsen.",al={"varför samla in hollow-essenser","syftet med wind hollow essence"}},{q="Betraktas hollows som fientliga?",a="Även om man ännu inte vet mycket säkert om dem ses hollows som ovälkomna inkräktare som dök upp när de naturliga andarna saknades. De blir allt fler i Shadowgale Forest, så de måste skingras för att skydda trakten och säkra exemplar.",al={"är hollows farliga","hot från hollow-vindväsen"}}},fp="17,189,20.204.0,21.273.0,24.207.0,21.195.0,27.122.0,31.122.0,44.168.0,35.202.0"}
P.entries["quest:93737"] = {n="The Broken Construct",s="The Broken Construct handlar om att hjälpa Riaani Nightwind, som står med överkroppen djupt inne i en maskin som inte fungerar. Ayessa har skickat dit dig som assistent, och du måste lyssna på Riaanis planer för att ta reda på hur du kan hjälpa till att återställa apparaten.",h="The Broken Construct handlar om att hjälpa Riaani Nightwind, som står med överkroppen djupt inne i en maskin...",kw={"ayessa","trasig konstruktion","konstruktion","ingenjörskonst","riaani nightwind","the broken construct"},ang={["profession:Engineering"]="Mekare och ingenjörer känner igen frustrationen i att hantera en trasig konstruktion vars mekaniska inre kräver omständlig felsökning."},sec={{t="Hjälpa hantverkaren",b="The Broken Construct börjar när Ayessa skickar en äventyrare för att hjälpa Riaani Nightwind. Riaani arbetar hårt med att försöka hitta felet i en skadad konstruktion, helt uppslukad av apparatens inre delar. Han blir förvånad över att få hjälp utifrån och tvivlar på att en otränad resenär kan hantera känsligt mekaniskt arbete, men går med på att beskriva några nödvändiga uppgifter när han väl kravlar sig ut ur maskinen."},{t="Felsökning av maskiner",b="Konstruktioner kräver exakt montering och noggrann kalibrering, så varje haveri är ett allvarligt bakslag för en ingenjör. Riaani Nightwind står djupt inne bland mekaniska delar och behöver ett extra par händer för att samla material eller utföra fälttester. Att lyssna noga på Riaanis genomgång är första steget mot att få den stillastående maskinen att fungera igen."}},faq={{q="Vem är Riaani Nightwind?",a="Riaani Nightwind är en uppfinnare som arbetar flitigt med en avstängd mekanisk konstruktion. Även om han till en början är skeptisk till nykomlingar som skickas till honom behöver han hjälp med att få maskinen att fungera igen.",al={"vem är riaani nightwind","riaani","mekaniker för konstruktioner"}},{q="Vem är Ayessa?",a="Ayessa är en medarbetare som hänvisar äventyrare till Riaani Nightwind för att hjälpa honom med hans pågående mekaniska problem. Det är hennes rekommendation som får Riaani att överväga att sätta en nykomling i arbete.",al={"vem skickade mig till riaani","ayessa","vem är ayessa"}},{q="Vad är den trasiga konstruktionen?",a="Konstruktionen är en mekanisk skapelse som för närvarande lider av mekaniska fel. Riaani Nightwind hittas djupt inne i den, där han försöker avgöra vilka delar och uppgifter som krävs för att reparera den.",al={"vad är konstruktionen","vilken maskin lagar riaani","trasig maskin"}},{q="Vad behöver Riaani hjälp med?",a="När du anländer från Ayessa måste du först ge Riaani en stund att kliva bort från konstruktionens inre och förklara situationen, så att du får instruktioner om hur du bäst kan hjälpa till.",al={"vad vill riaani att jag ska göra","uppdraget med den trasiga konstruktionen","hur hjälper jag riaani"}},{q="Varför är Riaani skeptisk till din hjälp?",a="Riaani är helt uppslukad av tekniskt arbete och blir något otålig när han blir avbruten. Han betraktar de flesta äventyrare som otränade nybörjare tills de visar att de kan följa mekaniska instruktioner.",al={"varför kallar riaani mig nybörjare","är riaani otrevlig","riaanis dialog"}}},fp="20,141,21.300.0,25.356.0,24.163.0,14.164.0,29.165.0,32.128.0,37.171.0"}
P.entries["quest:93738"] = {n="The Broken Construct",s="En Windshaper ber dig berätta för Ayessa Dawnsinger vad du fått veta om den trasiga konstruktionen. High Orders arbete med vindandemagi har väckt oro.",h="En Windshaper ber dig berätta för Ayessa Dawnsinger vad du fått veta om den trasiga konstruktionen.",kw={"ayessa dawnsinger","belathaan","trasig konstruktion","high order","valanaar","valennia stormfist","vindandar","windshaper"},sec={{t="Återvänd till Ayessa",b="För vidare det du fått veta till Ayessa Dawnsinger i Valanaar. High Order har prövat Windshapers tålamod med sina experiment med vindandemagi. Gruppen har också befattat sig med kunskap inom Windshapers ansvarsområde. Ayessa kan avgöra vad som bör hända härnäst."},{t="Ett oroande namn",b="Ayessa tror att High Order låg bakom att konstruktionen gick sönder. Hon känner Belathaan som Valennia Stormfists kusin och säger att hans mor var en Windshaper. Hans inblandning gör henne besviken. Hon behöver tid att tänka efter."}},faq={{q="Vem ska jag rapportera till?",a="Rapportera det du fått veta till Ayessa Dawnsinger i Valanaar.",al={"rapportera till ayessa","var rapportera","ayessa daw sinsinger"}},{q="Varför oroar sig Windshapers för High Order?",a="High Order har experimenterat med vindandemagi och lagt sig i kunskap inom Windshapers ansvarsområde, trots att det är förbjudet.",al={"high order problem","varför är windshapers arga","high order vindmagi"}},{q="Vad hände med konstruktionen?",a="Ayessa tror att High Order låg bakom att konstruktionen gick sönder.",al={"trasig konstruktion","konstruktionen gick sönder","varför är konstruktionen trasig"}},{q="Vem är Belathaan?",a="Belathaan är Valennia Stormfists kusin, och hans mor var en Windshaper.",al={"belathaan","belathaans familj","belathaans kusin"}}},fp="20,158,16.251.0,16.239.1,23.57.0,55.140.0,31.79.0,17.76.0"}
P.entries["quest:93739"] = {n="Exploring the Horde",s="Exploring the Horde är ett introduktionsuppdrag som skickar äventyrare på en vidsträckt rundtur bland Hordens ledare. Resan börjar med att rapportera till Nazgrel i Grommash Hold och går vidare till Vol'jin, Cairne Bloodhoof och Lady Sylvanas Windrunner. Uppdraget visar de diplomatiska och militära band som förenar orcher, troll, tauren och Forsaken.",h="Exploring the Horde är ett introduktionsuppdrag som skickar äventyrare på en vidsträckt rundtur bland Hordens...",kw={"cairne bloodhoof","darkspear","exploring the horde","forsaken","grommash hold","nazgrel","orgrimmar","sylvanas windrunner","tauren","thunder bluff","undercity","vol'jin"},ang={["faction:Horde"]="Resan presenterar äventyrarna för de olika ledarna som vägleder den nybildade Horden genom Kalimdor och Eastern Kingdoms.",["race:Orc"]="Nazgrel är direkt rådgivare åt krigshövding Thrall i Orgrimmar och fungerar som en viktig militär kontakt för unga orchkrigare som vill göra sig ett namn.",["race:Tauren"]="Mötet med High Chieftain Cairne Bloodhoof i Thunder Bluff knyter resenärerna till taurenfolkets andliga hjärta och styrka.",["race:Troll"]="Samtalet med Shadow Hunter Vol'jin stärker banden mellan Darkspear-stammen och deras orchallierade i Valley of Spirits.",["race:Undead"]="Resan till Undercity för att möta Dark Lady Sylvanas Windrunner visar hur viktig, om än spänd, Forsakens allians med Horden i Kalimdor är."},sec={{t="Order från Grommash Hold",b="Exploring the Horde börjar i Grommash Hold, fästningen i hjärtat av Orgrimmar, där Nazgrel och krigshövdingens råd leder militära operationer. Äventyrare hänvisas till Nazgrel för att få order om att bege sig ut i koalitionens vidsträckta områden. Uppdraget kräver en lång resa bort från Durotars röda kanjoner för att lära känna vidden av de folk som förenas under den röda fanan."},{t="En allians för överlevnad",b="Uppdraget skickar resenärer att tala med de främsta företrädarna för de allierade folken: Shadow Hunter Vol'jin bland Darkspear trolls, High Chieftain Cairne Bloodhoof bland tauren och Lady Sylvanas Windrunner, Forsakens drottning. Genom att möta dessa gestalter ansikte mot ansikte får äventyraren en inblick i banden som knyter Kalimdor till Lordaerons pesthärjade länder på andra sidan Stora havet."}},faq={{q="Vad är uppdraget Exploring the Horde?",a="Exploring the Horde är en introduktionsresa där äventyraren ska rapportera till Nazgrel i Grommash Hold. Därifrån leder instruktionerna resenären genom Hordens områden för att söka upp och tala direkt med viktiga ledare för olika folk: Vol'jin, Cairne Bloodhoof och Lady Sylvanas Windrunner.",al={"vad är exploring the horde","uppdraget exploring the horde","vad gör man i uppdraget"}},{q="Vem är Nazgrel och var finns han?",a="Nazgrel är en framstående orchkrigare och betrodd underbefälhavare som är stationerad i Grommash Hold i Orgrimmar. Han är rådgivare vid Hordens maktcentrum, samordnar uppdrag och hänvisar blivande hjältar till viktiga befälhavare och regionala allierade.",al={"vem är nazgrel","var finns nazgrel","nazgrels roll"}},{q="Vilka ledare ska du träffa?",a="Uppdraget leder dig till Hordens främsta ledare: Shadow Hunter Vol'jin bland Darkspear trolls, High Chieftain Cairne Bloodhoof bland tauren i Mulgore och Lady Sylvanas Windrunner, bansheedrottningen som styr Forsaken i Undercity.",al={"vilka ledare ska jag tala med","ledare att besöka","vem ska man tala med"}},{q="Varför ska äventyrare besöka alla ledarna?",a="Den moderna Horden är en koalition av olika folk som förenas av en gemensam kamp för överlevnad och broderskapspakter. Besöken hos Vol'jin, Cairne och Sylvanas visar alliansens räckvidd och bekantar äventyrarna med de olika maktcentrumen i Durotar, Mulgore och Lordaeron.",al={"varför besöka alla ledare","syftet med att besöka hordens ledare","diplomatiska skäl"}},{q="Var finns ledarna?",a="Vol'jin finns bland Darkspear trolls i Orgrimmars Valley of Spirits. Cairne Bloodhoof håller hov högt uppe på Thunder Bluffs platåberg i Mulgore. Lady Sylvanas Windrunner bor djupt inne i Undercitys Royal Quarter, under Ruins of Lordaeron.",al={"var finns ledarna","ledarnas platser","hitta vol'jin cairne sylvanas"}},{q="Vad är Grommash Hold?",a="Grommash Hold är den centrala fästningen i Valley of Strength i Orgrimmar. Den är uppkallad efter den legendariske Grom Hellscream och fungerar som Command Center, där krigshövding Thrall och hans främsta rådgivare, däribland Nazgrel, styr Hordens angelägenheter.",al={"vad är grommash hold","var ligger grommash hold","orgrimmars fästning"}}},fp="19,164,25.281.0,23.338.0,38.134.0,39.179.0,35.195.0,52.182.0,39.242.0,22.187.0"}
P.entries["quest:93740"] = {n="Blood for Blood",s="Flera Windshaper-noviser har hittats döda i Highlands, och misstankarna riktas genast mot Al'Akeths fanatiker. Ayessa skickar äventyrare norrut till Gustberry Lowlands för att slå ner kultisterna och återvända med deras vindstensbönekärl.",h="Flera Windshaper-noviser har hittats döda i Highlands, och misstankarna riktas genast mot Al'Akeths fanatiker.",kw={"al'aketh","ayessa","blood for blood","kultister","gustberry lowlands","highlands","windshapers","vindstensbönekärl"},sec={{t="En dyster upptäckt",b="Morgonen började med dystra nyheter för Windshapers: flera av deras noviser hade hittats mördade i Highlands. Även om det fortfarande saknas säkra bevis riktas misstankarna genast mot Al'Akeths kultister, vars ihärdiga fanatism gör dem till huvudmisstänkta. Windshapers vägrar låta blodspillan förbli obesvarad, drivna av en regel som kräver öga för öga."},{t="Krav på hämnd",b="Ayessa kräver direkt hämnd på alla Al'Aketh som påträffas norrut i Gustberry Lowlands. För att försäkra sig om att vedergällningen genomförs ber hon om vindstensbönekärlen som tas från de fallna kultisterna, som bevis på deras död. Angreppet är tänkt som ett första svar på vad Windshapers ser som långvarig fanatism."}},faq={{q="Vilka är Al'Aketh?",a="Al'Aketh är kultister som Windshapers ser som blodtörstiga fanatiker. De misstänks för att ha dödat Windshaper-noviserna som hittades i Highlands.",al={"vilka är al'aketh","al'akeths kultister","vilka slåss vi mot"}},{q="Varför söker Windshapers hämnd?",a="Flera Windshaper-noviser hittades döda i Highlands, och Windshapers misstänker starkt att Al'Akeths kultister låg bakom attacken. Enligt sin troslära kräver Windshapers hämnd.",al={"varför döda al'aketh","windshaper-noviser döda","varför hämnd"}},{q="Vem är Ayessa?",a="Ayessa är en företrädare för Windshapers som leder hämnden mot Al'Aketh och samlar in bönekärlen från de fallna kultisterna.",al={"vem är ayessa","uppdragsgivare","ayessa windshaper"}},{q="Vad är vindstensbönekärlen?",a="Vindstensbönekärlen är personliga föremål som Al'Akeths kultister bär med sig. Ayessa kräver dem som konkreta bevis på att kultisterna som låg bakom blodspillan har dödats.",al={"vad är vindstensbönekärl","bönekärl","bevis på dådet"}},{q="Var finns Al'Aketh?",a="Al'Akeths kultister håller till norrut, i Gustberry Lowlands, där de utövar sina ritualer.",al={"var finns al'aketh","var finns kultisterna","gustberry lowlands plats"}}},fp="15,228,16.279.0,22.280.0,21.138.0,44.145.0,14.144.0,37.142.0,32.94.0"}
P.entries["quest:93746"] = {n="A Firm Response",s="\"A Firm Response\" är ett Horde-uppdrag på Zephras Isle som Ayessa Dawnsinger ger. Spänningarna kokar över när det gåtfulla High Order inkräktar på Windshapers territorium och verksamhet. Ayessa beordrar ett förebyggande angrepp mot Belathaan Brightwish på vägen till Shrine of Akir för att med våld markera tydliga gränser.",h="\"A Firm Response\" är ett Horde-uppdrag på Zephras Isle som Ayessa Dawnsinger ger.",kw={"a firm response","ayessa dawnsinger","belathaan brightwish","high order","levande stormar","shrine of akir","windshapers","zephras isle"},ang={["class:Shaman"]="Sammandrabbningen med Living Storms på vägen visar hur det oroliga och otämjda elementarluftskenet genomsyrar Zephras Isle.",["faction:Horde"]="Hordes närvaro på Zephras Isle bygger på att säkra positioner och hindra rivaliserande fraktioner som High Order från att inkräkta på allierades intressen."},sec={{t="Dra gränsen",b="Windshapers på Zephras Isle tolererar inte oinbjuden granskning, särskilt inte från en så hemlighetsfull och beräknande organisation som High Order. Tidigare varningar har ignorerats, och Ayessa Dawnsinger tvingas därför trappa upp konflikten. För att skydda deras intressen väljer hon att genskjuta Belathaan Brightwish på den ensliga vägsträckan norrut mot Shrine of Akir, så att sammanstötningen sker utom räckhåll för nyfikna blickar i staden."},{t="Stormar på vägen",b="Belathaans färd norrut mot den uråldriga Shrine of Akir väcker omedelbart misstankar, även om hans exakta motiv är oklara. När han konfronteras på den avskilda vägen blir mötet snabbt fientligt, och Living Storms dras in i striden. Genom att besegra dessa våldsamma elementarer och kuva Belathaan skickar du ett tydligt budskap till High Order: inblandning i Windshapers angelägenheter kommer att besvaras med våld."}},faq={{q="Vem är Ayessa Dawnsinger?",a="Ayessa Dawnsinger är en uppdragsgivare som står på Horde och Windshapers sida på Zephras Isle. Hon värnar om deras domäner och är skoningslös mot inkräktare som lägger sig i deras angelägenheter.",al={"ayessa dawnsinger","vem ger ett tydligt svar","ayessa"}},{q="Vem är Belathaan Brightwish?",a="Belathaan Brightwish är en operatör med kopplingar till High Order. Han ses på väg ensam mot Shrine of Akir och blir måltavla för Ayessa Dawnsingers försök att skrämma hans organisation.",al={"belathaan brightwish","belthaan","vem är belathaan"}},{q="Vad är High Order?",a="High Order är en fraktion verksam på Zephras Isle vars aktiviteter går emot de lokala Windshapers intressen. Trots uttryckliga varningar fortsätter de att snoka i angelägenheter som inte angår dem.",al={"high order","high orders historia","vad är high order"}},{q="Var ligger Shrine of Akir?",a="Shrine of Akir ligger norr om staden på Zephras Isle. Belathaan genskjuts längs den avskilda vägen som leder till denna plats.",al={"shrine of akir","var ligger shrine of akir","shrine akir zephras"}},{q="Varför vill Ayessa att Belathaan ska besegras och inte dödas?",a="Ayessa vill uttryckligen skicka ett budskap snarare än starta ett fullskaligt krig. Genom att banka Belathaan blodig och låta honom återvända till sina överordnade hoppas hon ingjuta rädsla och respekt för Windshapers gränser.",al={"döda belathaan","varför skona belathaan","varför bara blåmärken"}},{q="Vad är Living Storms som möter dig under uppdraget?",a="Living Storms är elementarväsen som visar sig under konfrontationen med Belathaan på vägen. De speglar de flyktiga elementarkrafter som präglar Zephras Isle.",al={"levande stormar","vad är levande stormar"}}},fx={["3180a0eb"]={q="Varför vill Ayessa Dawnsinger att Belathaan konfronteras?",a="The High Order har upprepade gånger blandat sig i The Windshapers angelägenheter och struntat i tidigare varningar om att respektera deras territorium och seder. Ayessa anser att diplomatiska ord inte längre räcker. Genom att genskjuta Belathaan på vägen och ge honom en ordentlig omgång hoppas hon skicka ett glasklart budskap till hans överordnade: The Windshapers kommer att försvara sina gränser med våld om det behövs.",al={"varför konfrontera belathaan","ayessas motiv","varför skicka ett meddelande till high order"}}},fp="15,209,16.292.0,18.327.1,25.168.0,28.169.0,23.169.0,36.118.0,57.176.0,56.160.0"}
P.entries["quest:93786"] = {n="A Message in Blood",s="Krom’rosh skickar dig mot människornas gård vid Meadowsbrook. Han vill att gårdsfolket dödas som svar på avhopparnas anspråk på marken.",h="Krom’rosh skickar dig mot människornas gård vid Meadowsbrook.",kw={"ett budskap i blod","farholde","gård","mänskliga avhoppare","krom'rosh","meadowsbrook farm","gårdsarbetarna vid meadowsbrook farm","skärmytslingar"},ang={["faction:Horde"]="Som medlem av Horde utför du Krom’roshs order mot mänskliga avhoppare som har gjort anspråk på gården."},sec={{t="Gårdsfolket",b="Krom’rosh visar dig vägen till Meadowsbrook Farm, sydväst om floden. Mänskliga avhoppare gjorde anspråk på gården för några år sedan och sträckte sig sedan mot Farholde, fästet på den östra stranden. Krom’rosh säger att de tidigare skärmytslingarna saknade tillräckligt många krigare för att segra. Nu vill han att du stör gårdsarbetet och inte lämnar några fångar."}},faq={{q="Vem ber mig bege mig till Meadowsbrook?",a="Krom’rosh ber dig anfalla Meadowsbrook Farm och störa jordbruket där.",al={"vem skickade mig","krom'roshs uppdrag","vem ber mig"}},{q="Varför vill Krom’rosh att gården ska anfallas?",a="Mänskliga avhoppare gjorde anspråk på gården och utökade sitt område mot Farholde. Krom’rosh vill påminna dem om att hans folk finns där.",al={"varför anfalla gården","varför meadowsbrook","varför slåss mot människor"}},{q="Var ligger Meadowsbrook Farm?",a="Meadowsbrook Farm ligger sydväst om floden.",al={"var ligger gården","meadowsbrook läge","gården sydväst"}},{q="Vilka är gårdsarbetarna?",a="Gårdsarbetarna vid Meadowsbrook Farm är de människor som Krom’rosh skickar dig för att döda.",al={"vilka är gårdsarbetarna","folket vid meadowsbrook","människor på gården"}},{q="Vad hände i de tidigare skärmytslingarna?",a="Krom’rosh säger att hans sida skulle ha haft övertaget i de tidigare skärmytslingarna om de haft fler krigare.",al={"tidigare strider","varför skärmytslingarna misslyckades","kromroshs skärmytslingar"}}},fp="18,136,13.314.0,34.73.0,44.119.0,27.50.0,22.72.0,40.98.0"}
P.entries["quest:93787"] = {n="Food for the Taking",s="Krom'rosh skickar dig till en Alliance-gård i Meadowsbrook för att hämta dess foder. När du tar förråden hindrar du människorna och vinner tid att planera nästa drag.",h="Krom'rosh skickar dig till en Alliance-gård i Meadowsbrook för att hämta dess foder.",kw={"alliance-gård","feed satchels","food for the taking","människor","krom'rosh","meadowsbrook","förråd"},ang={["faction:Horde"]="Som medlem av Horde ombeds du beröva människorna i Alliance den bekvämlighet och näring som gårdens förråd ger."},sec={{t="Gårdens förråd",b="På Alliance-gården i Meadowsbrook finns foder som Krom'rosh vill att du tar. Du skickas sydvästerut för att lägga beslag på det du hittar, så att människorna blir utan förråd och du vinner tid för en annan plan."}},faq={{q="Vem vill att fodret ska tas?",a="Krom'rosh vill att du tar foder från Alliance-gården i Meadowsbrook.",al={"vem skickade mig","kromroshs begäran","vem vill ha förråd"}},{q="Var ligger gården?",a="Alliance-gården ligger i Meadowsbrook, åt sydväst.",al={"var ligger alliance-gården","meadowsbrook-gården","gårdens läge"}},{q="Varför ta förråden?",a="När du tar förråden blir människorna utan sina förnödenheter, och du vinner tid att planera nästa drag.",al={"varför stjäla foder","varför neka dem mat","vad är poängen"}},{q="Vilka förråd ska tas?",a="Förråden är Feed Satchels från Alliance-gården.",al={"vilket foder","feed satchels","vad ska stjälas"}}},fp="19,148,17.188.0,25.72.0,18.55.0,22.93.0,30.54.0"}
P.entries["quest:93788"] = {n="Borrowed Blades",s="Kreza Darkthorn ber dig hämta skogshuggarnas yxor från Turner's Logging Camp. Bladen ska ge material till vapen i Rog'mar.",h="Kreza Darkthorn ber dig hämta skogshuggarnas yxor från Turner's Logging Camp.",kw={"lånade blad","smedja","gur'dok","kreza darkthorn","skogshuggare","rog'mar","turner's logging camp","vapen","skogshuggarens yxa"},sec={{t="Vid Logging Camp",b="Kreza Darkthorn håller igång smedjan i Rog'mar medan Gur'dok bryter ner bladen. Människornas närvaro i söder och Twilight i väster gör det svårt att samla resurser. Du ombeds hämta skogshuggarnas yxor från Turner's Logging Camp, så att materialen kan formas till vapen."}},faq={{q="Vem vill ha yxorna?",a="Kreza Darkthorn i Rog'mar ber dig hämta yxorna från Turner's Logging Camp.",al={"vem skickade mig","krezas yxor","vem behöver blad"}},{q="Varför vill Kreza ha skogshuggarnas yxor?",a="Gur'dok bryter ner bladen, och Kreza använder materialen till att tillverka vapen.",al={"varför yxor","vad används yxor till","material till vapen"}},{q="Var ligger Turner's Logging Camp?",a="Turner's Logging Camp ligger söderut längs floden, vid sågverket.",al={"logging camp plats","var finns skogshuggarna","turner's camp"}},{q="Vad gör det svårt att samla resurser?",a="Människornas närvaro i söder och Twilight i väster gör kampen om resurser svår.",al={"varför resurser är svåra att få tag på","människornas närvaro","twilight i närheten"}}},fp="15,143,19.304.0,19.84.0,42.87.0,31.60.0,41.96.0"}
P.entries["quest:93791"] = {n="Speak with Belann",s="Speak with Belann skickar blivande magiker till Valanaar för att träffa mästerhantverkaren Belann Windwood. När en novis blir skickligare i magi är det en viktig övergångsrit enligt High Orders gamla traditioner att skapa ett eget magiskt fokus.",h="Speak with Belann skickar blivande magiker till Valanaar för att träffa mästerhantverkaren Belann Windwood.",kw={"belann","belann windwood","high order","magiskt fokus","stavar","valanaar","spön"},ang={["class:Mage"]="Att skapa ett eget magiskt fokus är en viktig övergångsrit för blivande magiker som hedrar High Orders uråldriga traditioner."},sec={{t="En ritual för växande kraft",b="När en blivande magiker blir skickligare i magi åberopar High Order uråldriga seder för att pröva och utveckla sina förmågor. Att skapa ett personligt magiskt fokus, som en stav eller ett spö, är en av ordens mest långlivade traditioner för elever som vill binda sin växande kraft till ett redskap de själva har skapat."},{t="Hantverkaren i Valanaar",b="För att utföra detta heliga hantverk skickas noviser till Valanaar för att söka upp Belann Windwood. Belann är känd för att i över ett århundrade ha smitt enastående stavar och spön åt High Order. Han är en betrodd mentor som gärna välkomnar hängivna elever och vägleder dem genom deras magiska redskaps komplicerade hantverk och historia."}},faq={{q="Vem är Belann Windwood?",a="Belann Windwood är en mästerhantverkare som bor i Valanaar. I över ett århundrade har han ägnat sitt hantverk åt att skapa stavar och spön åt medlemmar av High Order.",al={"vem är belann","belann windwood","belann"}},{q="Vad är High Order?",a="High Order är en uråldrig sammanslutning av magiker. Dess långvariga traditioner omfattar att vägleda unga magiker i att skapa och bemästra sina egna magiska fokus.",al={"vad är high order","high orders historia"}},{q="Vad är ett magiskt fokus?",a="Ett magiskt fokus, som ett spö eller en stav, kanaliserar magisk energi. Att skapa ett eget fokus räknas som en av de äldsta övergångsriterna för magiker under utbildning inom High Order.",al={"vad är ett magiskt fokus","syftet med magiskt fokus"}},{q="Var hittar man Valanaar?",a="Valanaar är bosättningen där Belann Windwood har sin verkstad och hjälper elever från High Order att skapa magiska fokus.",al={"var ligger valanaar","valanaars läge"}},{q="Varför skickas du för att tala med Belann?",a="Du är en blivande magiutövare vars krafter växer, och skickas till Belann för att lära av hans sekel av erfarenhet och börja forma ditt eget magiska redskap.",al={"varför besöka belann","varför skapa ett fokus"}},{q="Vad händer när du har träffat Belann?",a="När du presenterar dig för Belann i Valanaar välkomnar hantverkaren dig och gör sig redo att berätta om nästa steg i skapandet av ditt magiska fokus.",al={"vad händer sedan","efter samtalet med belann"}}},fp="17,153,23.326.0,25.270.0,23.145.0,23.158.0,22.162.0,28.112.0,38.157.0,35.138.0"}
P.entries["quest:93797"] = {n="Boughs in the Wind",s="Boughs in the Wind är en traditionell övergångsrit där en lärling samlar en vindgenomsyrad gren nära Falaath Village för att skapa ett magiskt fokus. Belann Windwood i Valanaar vägleder lärlingarna i traditionen, som hedrar en uråldrig sed i en tid då den magiska talangen i Zephras stadigt avtar.",h="Boughs in the Wind är en traditionell övergångsrit där en lärling samlar en vindgenomsyrad gren nära Falaath...",kw={"belann windwood","boughs in the wind","falaath village","magiskt fokus","valanaar","vindaltare","wind-infused bough","zephras"},ang={["class:Mage"]="Att skapa ett magiskt fokus av vindgenomsyrade grenar är en tidig övergångsrit för magiker som lär sig kanalisera elementarresonans.",["race:Skyborne"]="Eftersom allt färre unga visar fallenhet för magi för varje år som går, hjälper du till att bevara ditt folks förfäderskultur i Zephras när du deltar i skapandet av ett traditionellt magiskt fokus."},sec={{t="En övergångsrit",b="I Zephras länder genomgår unga magiker med gryende magisk talang en traditionell övergångsrit: de skapar sitt eget magiska fokus. Mentorer som Belann Windwood i Valanaar vägleder lärlingarna genom denna uråldriga sed och ber dem samla en nedfallen gren från regionens äldsta träd. Dessa vördnadsvärda grenar bär på kvarvarande elementarkrafter från vinden, vilket gör dem till utmärkta ledare för besvärjelser."},{t="Viskningar vid vindaltaret",b="De mest kraftfulla grenarna samlas nära vindaltaret strax söder om Falaath Village, där elementarströmmarna naturligt samlas. Enligt traditionen väljer grenen ofta magikern, och det sägs ibland att den stilla sjunger för dem som är känsliga nog att tämja dess kraft. För äldre som Belann innebär varje elev som fullbordar ritualen att deras kultur förs vidare, särskilt eftersom allt färre i Zephras föds med en magisk gåva för varje år som går."}},faq={{q="Vad är uppdraget Boughs in the Wind?",a="Boughs in the Wind är ett uppdrag som utgör en övergångsrit, där en blivande magiker samlar en vindgenomsyrad nedfallen gren för att skapa sitt eget magiska fokus. Det är en uråldrig sed som bevarar Zephras magiska arv.",al={"vad är boughs in the wind","uppdraget boughs in the wind","uppdrag om magiskt fokus"}},{q="Vem är Belann Windwood?",a="Belann Windwood är en mentor i Valanaar som vägleder unga magiker när de traditionellt skapar sina magiska fokus. Han ser med oro på att allt färre visar en magisk gåva för varje år som går.",al={"vem är belann windwood","belann uppdragsgivare","belann valanaar"}},{q="Var hittar du Wind-Infused Bough?",a="Vindgenomsyrade grenar faller från de äldsta träden nära vindaltaret, strax söder om Falaath Village. Belann hänvisar lärlingarna dit eftersom det uråldriga träet bär på kvarvarande elementarströmmar.",al={"var hittar man vindgren","var finns wind-infused bough","grenens plats"}},{q="Varför skapar unga magiker ett magiskt fokus?",a="Enligt den lokala traditionen skapar lärlingar sitt eget magiska fokus när de visat prov på magisk skicklighet. Fokuset leder elementarkrafter och fungerar både som en kanal för besvärjelser och som en invigning i kulturella riter.",al={"varför skapa magiskt fokus","magiskt fokus syfte","magiskt fokus bakgrund"}},{q="Varför frågar Belann om grenen sjöng för dig?",a="Belann Windwood påpekar att traditionen säger att grenen ofta väljer magikern, snarare än tvärtom. Han säger att en lämplig gren kan tyckas sjunga för någon som är känslig nog att hantera elementarvindar.",al={"grenen väljer magikern","sjungande gren","väljer grenen dig"}},{q="Vad händer med magin i Zephras?",a="Zephras är landet där den här traditionen utövas. Enligt Belann Windwood föds allt färre i Zephras med en naturlig magisk talang för varje år som går, vilket gör det viktigt att de uråldriga riterna förs vidare.",al={"var ligger zephras","magin avtar i zephras","zephras magibakgrund"}}},fp="18,207,17.262.0,27.396.0,37.130.0,23.174.0,41.181.0,47.153.0,46.155.0,38.147.0"}
P.entries["quest:938"] = {n="Mist",s="Mist är ett eskortuppdrag bland Teldrassils skuggiga grenar. Efter att ha hittat en skadad grå sabelkatt som lämnats ensam djupt inne i skogen måste resenärer leda henne tryggt tillbaka till Sentinel Arynia Cloudsbreak vid en närbelägen månskensbrunn.",h="Mist är ett eskortuppdrag bland Teldrassils skuggiga grenar.",kw={"arynia cloudsbreak","mist","månskensbrunn","the oracle tree","sabelkatt","vaktpost","teldrassil"},ang={["class:Hunter"]="Varje djurmästare känner igen den starka hängivenheten och intelligenta blicken i Mists ögon, så att föra henne tryggt tillbaka till sin partner är en fråga om yrkesstolthet.",["faction:Alliance"]="Att hjälpa vaktposterna i Teldrassil stärker den viktiga välviljan mellan den unga Alliansen och världsträdets kaldorei-försvarare.",["race:NightElf"]="Bandet mellan en vaktpost och en sabelkatt är en hörnsten i Night Elf-folkets krigföring och skogskunskap. Genom att rädda Mist värnar du om detta uråldriga, heliga följeslagarskap."},sec={{t="En skadad följeslagare",b="Djupt inne i Teldrassils vilda snår ligger Mist, en särpräglad grå sabelkatt med svåra, skärande sår över rygg och buk. I stället för att uppföra sig som ett vilt djur visar Mist ett anmärkningsvärt lugn och en klar intelligens i sina blå ögon, och söker genast vägledning och skydd hos vänligt sinnade resenärer."},{t="Bakhållens pris",b="Mist är Sentinel Arynia Cloudsbreaks älskade följeslagare. När Arynia patrullerade de väldiga grenarna nära The Oracle Tree överrumplades de av illvilliga häxor som gick till bakhåll och skilde dem åt. Övertygad om att hennes trogna husdjur hade mött en blodig död drog sig Arynia i sorg tillbaka till lugnet vid en närbelägen månskensbrunn, där hon desperat hoppades att Mist ändå hade överlevt."}},faq={{q="Vem är Mist?",a="Mist är en trogen grå sabelkatt och följeslagare till Sentinel Arynia Cloudsbreak. Hon hittas skadad i Teldrassils skogar efter att ha skilts från sin matte under ett våldsamt bakhåll.",al={"mist katt","vad är mist","vem är sabelkatten"}},{q="Vem skadade Mist?",a="Mist och hennes matte överfölls av lokala häxor som lurade i Teldrassils skogar. Angriparna lyckades skilja dem åt och tillfogade katten djupa sår över ryggen och magen.",al={"vem skadade mist","varför blöder mist","häxor överfaller mist"}},{q="Vart ska Mist eskorteras?",a="Mist måste föras tryggt till Sentinel Arynia Cloudsbreak, som väntar vid månskensbrunnen nära The Oracle Tree.",al={"vart ska jag ta mist","lämna in mist","mists destination"}},{q="Vem är Sentinel Arynia Cloudsbreak?",a="Arynia Cloudsbreak är en Night Elf-vaktpost och Mists följeslagare. Hon väntar vid månskensbrunnen nära The Oracle Tree.",al={"arynia cloudsbreak","cloudsbreak","mists ägare"}},{q="Varför knyter Night Elf-vaktposter band till sabelkatter?",a="Night Elf-vaktposter har stridit sida vid sida med Kalimdors stora katter i årtusenden och förlitar sig på dem som stridslystna partners i skärmytslingar, spejare bland de skuggiga grenarna och betrodda följeslagare för livet.",al={"night elf-katter som följeslagare","vaktposternas sabelkatter","varför sabelkatter"}},{q="Var ligger The Oracle Tree i förhållande till räddningsplatsen?",a="The Oracle Tree ligger i nordvästra Teldrassil. Vid en närbelägen månskensbrunn med heligt vatten utför Sentinel Arynia Cloudsbreak sina plikter.",al={"the oracle trees plats","månskensbrunnen mist"}}},fx={["1795c253"]={q="Varför behöver Mist din hjälp?",a="Mist är svårt skadad, med djupa sår över ryggen och magen, och har skilts från sin följeslagare Sentinel Arynia Cloudsbreak. Försvagad och ensam i skogen kan hon inte ta sig genom Teldrassils faror på egen hand och nå tryggheten vid månbrunnen utan ditt beskydd.",al={"varför hjälpa mist","mists motiv","varför behöver mist eskort"}},["94db0917"]={q="Varför förlitar sig Mist på dig i stället för att rädda sig själv?",a="Mist är alltför svårt skadad för att kämpa sig genom den fientliga skogen eller göra den långa färden tillbaka utan hjälp. Hon är ett djur som skilts från sin Sentinel och har inga allierade eller vakter i närheten att vända sig till. När du hittar henne känner hon igen dig som vänligt sinnad och litar på att du kan leda och skydda henne.",al={"varför jag för mist","varför kan mist inte fly ensam","varför följer mist med dig"}}},fp="4,154,19.257.0,19.238.1,12.145.0,17.135.0,30.101.0,35.120.0,50.191.0,52.150.0"}
P.entries["quest:93835"] = {n="Confront Lorthuna",s="En skadad magiker behöver din hjälp med att följa Ayessa Dawnsinger och Elaadrin Evengale genom en portal till Rohashi Spires. Där står de inför High Priestess Lorthuna och behöver din hjälp.",h="En skadad magiker behöver din hjälp med att följa Ayessa Dawnsinger och Elaadrin Evengale genom en portal...",kw={"ayessa dawnsinger","elaadrin evengale","high order","lorthuna","portal","rohashi spires","valennia","zephras"},sec={{t="Genom portalen",b="Lorthuna flydde genom en portal till spirorna ovanför. Ayessa Dawnsinger och Elaadrin Evengale följde efter för en liten stund sedan, men deras följeslagare är för svårt skadad för att följa med. Följ de två magikerna genom portalen när de ställs mot översteprästinnan."},{t="Efter sammandrabbningen",b="De återstående magikerna skickades för att hjälpa Valennia och hennes styrkor att fly. Valennia vilar i High Elder Shadowsongs bostad. Ansirem har återvänt till Azeroth efter att ha diskuterat nästa steg för High Order. Zephras överlevde dagen, men är fortfarande farligt sårbar, och planer måste göras för det som väntar."}},faq={{q="Vem ber mig att följa efter Lorthuna?",a="En skadad magiker ber dig att följa Ayessa Dawnsinger och Elaadrin Evengale genom portalen och hjälpa dem att möta High Priestess Lorthuna.",al={"vem skickade mig","skadad magiker","vem behöver hjälp"}},{q="Vart tog Lorthuna vägen?",a="Lorthuna flydde genom en portal till Rohashi Spires ovanför.",al={"var är lorthuna","lorthunas portal","vart flydde hon"}},{q="Vem följde efter Lorthuna?",a="Ayessa Dawnsinger och Elaadrin Evengale gick genom portalen efter Lorthuna.",al={"ayessa och elaadrin","vem följde efter henne","vem är där uppe"}},{q="Varför kan den skadade magikern inte följa med dem?",a="Magikern fick ta emot för många träffar och måste stanna kvar.",al={"varför går jag ensam","magikern för svårt skadad","varför stanna kvar"}},{q="Var är Valennia?",a="Valennia vilar i High Elder Shadowsongs bostad efter att de återstående magikerna hjälpte henne och hennes styrkor att fly.",al={"var finns valennia","vart tog hon vägen","valennia i säkerhet"}},{q="Vad står på spel nu?",a="Zephras är farligt sårbar, och High Order måste planera för det som väntar.",al={"zephras sårbar","vad hände med zephras","nästa steg för high order"}}},fp="17,176,18.239.0,15.311.1,38.137.0,22.62.0,24.79.0,40.49.0,18.116.0,20.84.0"}
